window.IV=window.IV||{};IV.univ=IV.univ||{};IV.univ["u071"]={"univ":"서울대학교","reviews":[{"univ":"서울대학교","dept":"경영대학","jeonhyeong":"학생부종합(기회균형)","method":"면접실 대기-면접 고사장 앞 대기-면접-퇴장","notes":"면접대기실 가자마자 들고온 자료를 전부 볼 수 없기 때문에 일찍간다고 좋을게 없음꼬리질문 상당히 많이 하는데 그때는 그냥 자기생각을 자신있게 대답만 하면됨교수님들이 친절하셔서 긴장 안 해도 됨","qa":[{"q":"알바생자르기를 읽고 우리나라 노동구조 어떻게 생각하는지","a":"우선우리나라 노동구조는 수직적인 노동구조로 정규직과 비정규직간 불균형이 심합니다 반면이책에서 나오는 독일같은경우는 수평적조직구조로 비정규직 또한 노동안정성이 어느정도 보장됩니다"},{"q":"비정규직을 정규직으로 바꾸면 기업에게 불이익이 있지 않을까요","a":"인건비 차원에서는 그런 부분도 있으나 기업은 사회적책임까지 고려하여야하기에 우리나라는 이러한 부분이 개선되야 할 것 같다 생각"},{"q":"미국의 노동구조에 대해서는 어떻게 생각하나","a":"그 부분은 조사하지 못했습니다"},{"q":"리쇼어링현상에 대해 탐구하고 알게된점","a":"코로나 팬데믹 러시아 우크라이나전쟁같은 변화로 인해서 최근 기업들이 외국에 있던 자국 생산기지를 본국으로 회기하는 리쇼어링 현상이 활발이 일어나고 있습니다"},{"q":"리쇼어링현상의 문제점은 없는가","a":"인건비나 재료비차원에서 부담이 될 수 있습니다"},{"q":"그럼 학생이 말한거 처럼 기업들이 전부 리쇼어링할시 기업에게 피해가있지 않나","a":"전부 리쇼어링 한다기 보다는 기업은 적당히 손익을 계산하여 상황에 맞게 대처해야 할것 같습니다"}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"서울대학교","dept":"경영대학","jeonhyeong":"학생부종합(일반전형)","method":"제시문 기반 면접서울대학교 일반전형 기출문제는 입학처 홈페이지에 제시되어있음. 제시문이 매해 다르므로 기출 문제를 통하여 출제의 방향성을 잡고 준비해야 할 것으로 판단됨.","notes":"제시문을 보고 답을 못하면 힌트를 주심.대기시간이 짧으면 30분에서 길면 3시간이 넘는데, 가서 개인 자료 볼 수 없어서 다소 지루함.30분 준비시간을 주는데 이동 시간도 포함돼서 28분만 주심.교과 지식이 아닌 제시문을 기반으로 한 전문적이고 심층적인 질문에 대한 대답을 요구함.","qa":[],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"서울대학교","dept":"경제학부","jeonhyeong":"학생부종합(기회균형)","method":"생기부기반면접","notes":"면접관과의 거리가 매우 가깝고 10분이 생각보다 정말 짧게 느껴진다. 분위기는 꽤나 편안한 편이다.","qa":[{"q":"새마을 운동 및 경제 개발 5개년 계획에 대해 설명하고 왜 경제발전에 도움을 줬다고 생각했는지 설명해보세요.","a":"답변 내용이 기억이 나지 않습니다."},{"q":"독서토론 동아리 돈으로 살 수 없는 것은 무엇이라 생각하며 왜 그렇게 생각하나요","a":"돈으로 살 수 없는 것의 기준은 사회에 부정적 영향을 끼치는 것으로 평가. 마약과 성매매를 생각한다. 일각에선 마약은 개인의 인권을 돈 주고 구매하는 것이며, 성매매는 타인의 인격을 구매하는 것으로 두 개가 구분된다. 하지만 장기적으로 볼 때 마약 복용자가 타인에게 권유하고 마약 섭취 후 운전, 살인등의 피해를 입힌다는 점에서 본질적으로 다르지 않다고 생각한다."},{"q":"마약과 성매매는 이미 법적으로 금지된 것 아닌가?","a":"법적으로는 금지되어 있지만 뒷세계에서는 여전히 소비되고 있기에 법적으로 금지되어 있다고 해서 돈으로 사서는 안되는 것을 주장할 수 없는 것은 아니라고 생각한다.(다소 의역, 기억이 잘 안남)"},{"q":"성욕, 식욕을 2대 욕구라 하는데 신체 불구인 장애인들의 경우 성관계가 불가능한 상황인데. 성매매 등의 수단마저 금지한다면 그들의 인격적 욕구를 배척? 하는 것 아닌가?","a":"물론 개별적인 사례에서는 위와 같이 긍정적으로 받아들여질 수도 있다. 하지만 불법으로 지정되어 있다는 것은 보편적으로 사회에 부정적 영향을 끼치는 경우가 더 많기 때문이라고 생각한다. 개별 사례에는 긍정적일 수 있지만 그럼에도 부정적으로 생각되는 경우가 더 많을 것이라 생각한다."},{"q":"가상화폐가 실물 화폐를 대체할 수 없는 이유는 뭐라고 생각하는가?","a":"화폐는 기본적으로 명목화폐이다. 가상화폐는 그 가격의 변동성이 하루에도 수십배가 변동할 정도로 크기 때문에 실물 화폐의 역할을 대체하기에는 무리라고 생각한다."},{"q":"전세의 문제 및 왜 등장?","a":"전세사기 문제는 법의 시차 때문에 발생한다. 전세사기를 예방하기 위한 여러 예방책의 예방 시점에 기간이 있기에 피해를 입으며 특히 여러 뉴스에서 보고 알게된 사실은 처벌 강도가 매우 약하다는 것이다. 수십명에게 사기를 친 사람이 징역 10여년, 벌금 조금 받는 것을 보았다. 우리나라에만 있는 전세제도가 사라지는 것이 가장 긍정적이라고 생각한다."},{"q":"그렇다면 전세가 사라지는데는 오랜 시간이 걸릴텐데 그 때까지 대처방법은 없는가?","a":"정부에서 당장 처벌을 늘리거나 하는 것은 법적인 것으로 오래 걸린다. 따라서 정부에서 처벌의 관점보다는 주거지 관련 정보를 제대로 명시하도록 하는 체계를 만드는 것이 방법이 될 수 있다 생각한다. 개인의 입장에서도 꼼꼼히 확인하는 것이 필요하다."},{"q":"마지막으로 하고 싶은 말","a":"경제학과에 입학하여 여러가지 경제학적 지식을 쌓고 싶다. 또한 경제학적 지식을 쌓고 난 뒤 최근 이분법적인 분위기가 강화된 사회에 타인의 선택 혹은 행위를 분석하고 이해하는 방법을 사회에 공유함으로써 더 건전한 사회를 만드는데 기여하고 싶다."}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"서울대학교","dept":"경제학부","jeonhyeong":"학생부종합(일반전형)","method":"큰 대기실에서 대기하다 ‘복도’로 이동함. 복도에 간이 책상들 있고, 그곳에 앉아있다 조교님이 시작하라 하면 30분 준비 시작. 이후 복도 바로 옆 방들 중 하나에 들어감. 교수님들 앞에서 15분 발표 시작.수학문제. 실제 위치와 숫자가 다른 3개의 공이 있음.첫째 공은 위치1, 숫자3. 둘째 공은 위치 2, 숫자2. 셋째공은 위치 3, 숫자1임.정해진 상수 h를 위치에 곱하고... 뭐 숫자를 더하고... 복잡한 등비수열 계산.","notes":"서울대학교는 작년에 들은 것과는 달랐음. 연필 대신 볼펜 주고, 그냥 복도에 막 앉히고... 아마 면접환경이 달라도 긴장하지 않는 게 중요함.유일하게 대학 차원에서 먹을 거 나눠줌. 연고대는 앞에서 학생들이 나눠주는데...조가 나눠져있긴 한데 그냥 조마다 한명 씩 보내려고 그런거고, 한 공간에 모아놓음.화장실 진짜 안보내줌. 최대한 빨리 갔다 올 것.","qa":[{"q":"두 번 수행 후 공들의 숫자의 평균은?","a":"한번 수행 후 2, 두 번 수행 후 1/2h^2-3/2h+3"},{"q":"2024번 수행 후 공 1에 적인 숫자는?","a":"못품."},{"q":"세공의 일반항??","a":"기억 안남.사회과학 문제. 제시문 가는 자기실현적 예언에 대해 다루고, 사회적 차별받는 사람들이 자기실현적 예언으로 일탈하고, 다시 차별로 이어짐 제시. 제시문 나는 자기실현적 예언으로 죽음에 이르는 부두죽음, 제시문 다는 물가상승률 예측이 물가를 실제로 예측대로 움직이게 하는 경향이 있다고 설명."},{"q":"나와 다 비교","a":"나는 생물학적, 물리적 차원에서 죽음에 이르른 반면, 다 에서는 사회과학적 차원에서 결과가 일어남. 나는 개인적 차원에서 영향을 받은, 소규모 사건인 반면 다는 사회적 차원에서 영향을 받은, 대규모 사건임."},{"q":"제시문 가에서 사회적 차별받는 사람에 대해 구제방법. 여러 주체들 중 3가지 골라 답변.","a":"정책 입안자, 교육자, 차별 받는 당사자.나머지는 그냥 생각나는 대로 답변, 정책입안자의 경우 자기실현적 예언 또한 사회과학적 현상이므로 해결할 수 있다는 자기실현적 예언에 기반하여 악순환의 고리를 끊어내는 것이 중요하다고 답변."}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"서울대학교","dept":"경제학부","jeonhyeong":"학생부종합(기회균형전형)","method":"구술면접","notes":"","qa":[{"q":"esg 경영에 대해 관심이 많은 것 같은데, esg에 대해 설명해보세요","a":"esg란, 환경의 e, 사회의 s, 지배구조의 g를 의미하는데, 사회적 가치를 경영에 투입하는 것을 의미합니다. 소비자 주권시대이고, 사람들이 더 이상 필요한 것을 소비하지 않습니다. 사회적으로 가치있고, 의미있는 것을 소비하므로, esg경영은 시대적 흐름이라고 생각합니다."},{"q":"그러면, g에 해당하는 지배구조는 어떻게 변화시킬 수 있나요?","a":"지배구조는, e나 s에 해당하는 사회적 가치를 더욱 잘 수용할 수 있도록 민주적인 의사결정을 강구하거나, 기존의 관료제에서 벗어난 탈관료제 형식, 또는 소비자의 의견을 원활히 받아들일 수 있는 소통의 창구를 형성하는 방식 등이 있을 수 있습니다."},{"q":"논술 시간에 그린벨트에 대해 토론했다고 나와있는데, 본인의 의견을 말해보세요","a":"저는 그린벨트 해제를 지역불균형 완화의 관점에서 긍정했습니다. 수도권 과밀화 현상이 지나치게 발생하고 있고, 균형발전이 어려운 현실에서 대부분의 그린벨트가 농촌과 어촌, 즉 1차 산업 위주의 지방에 편중되어있고, 저는 이러한 그린벨트를 해제하는 것이 지역균형발전을 달성할 수 있는 수단이 될 수 있다고 봤습니다."},{"q":"그러면, 지방에 수요가 중앙보다 좀 적다거나, 그런 현상으로 인해 오히려 지방의 개발이 어려울 수 있을 것 같은데 여기에 대해서는 어떻게 생각해요?","a":"저는 그런 문제는 지역의 문화적, 역사적, 산업적인 특색을 살린 산업 클러스터의 조성으로 해결할 수 있다고 생각합니다."},{"q":"그린벨트 조성이 농촌, 어촌 1차 산업 구조의 지역에 편중되어있다고 하는건 구체적인 자료나 수치를 직접 찾아보고 객관적으로 탐구한거에요?","a":"네 맞습니다"},{"q":"사회 문화 시간에 ‘긴급재난지원급이 한국 경제의 정상화에 기여하였는가?’에 대한 주제로 양적 조사 방식의 탐구를 시행했다는데 여기에 대해 구체적으로 말해보세요.","a":"우선 선행연구를 검토했습니다. 재난지원금 시행 전후의 소비자 심리지수, 가계 수입 전망 등 구체적인 수치를 확인한 결과 소비 심리의 진작과 수요의 확대라는 측면에서 재난지원금이 의미있었다고 판단헀습니다. 그 이후, 우리 학교 학생들을 대상으로 질문지법을 시행해, 재난지원금을 어떠한 용도로 사용했는가를 조사한 결과, 대부분의 학생이 외식 등 자영업에 그 금액을 사용했다고 하여 소비심리의 진작이라는 측면에서 의미있었다고 판단했습니다."},{"q":"자영업자에게 직접 지원금을 지급하는 것과 소비자에게 지급하는 것이 어떤 차이가 있고, 어느 것이 더 효율적인가요?","a":"저는 공급과잉의 측면에서 소비자 지급이 더욱 효율적이라고 생각합니다. 자영업자, 판매업자들은 미리 판매를 위해 준비해둔 상품 및 재료가 있고, 이것들을 충당하지 못한다면 공급량이 남아돌아 공급과잉이 발생합니다. 이러한 측면에서, 소비자에게 지원금을 지급하여 수요를 확대하는 것이 시장경제의 기본원리에 더욱 부합한 것 같습니다."},{"q":"KIKO 사태, knock-in 계약과 knock out 계약, 아직 기억나요?","a":"knock in 계약은 자산의 가격이 특정 수치에 도달하며 유효해지는 옵션이고, knock-out 계약은 자산의 가격이 특정 수치에 도달하면 무효해지는 옵션계약입니다. kiko는, 환율가격이 특정 수치 내에서 변동하면 수출기업에 이익, 그 최대와 최소 범위를 벗어나면 기업이 이익을 보는 구조로 형성되어, 리먼브라더스 사태 이후 환율이 급격하게 치솟자 수출기업이 피해를 본 사건으로 알고 있습니다."},{"q":"기본소득에 대해 탐구했다고 나와있는데, 구체적인 본인의 생각을 말해보세요.","a":"많은 미래학자들이 ai나 인공지능, 기계화의 확대로 인해 탈실업의 미래를 예견하고 있습니다. 저는, 노동 없는 미래 경제에서 기본소득이 기본적인 수요를 확대하거나, 수요량을 충족할 수 있다는 측면에서 경제의 활성화를 위해 지급될 수 있다고 생각합니다."}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"서울대학교","dept":"국어국문학과","jeonhyeong":"학생부종합(일반전형)","method":"제시문 면접. 어문과는 인문학 지문 하나, 사회과학 지문 하나 해서 총 두 지문을 풂. 제한 시간은 30분, 면접 시간은 15분임. 무슨 지문을 몇 분 안에 풀어야 한다는 규정은 없으나 15분 15분으로 나눠 푸는 연습을 하면 좋음. 제시문 면접을 보는 대표적인 타 학교가 연고대인데, 서울대는 이 학교들과 요구하는 답변 방식이 꽤 다름. 따라서 연고대 제시문 면접이 없다 하면 기출은 서울대만 보는 걸 추천. (시간 남으면 봐도 됨)연고대는 원하는 ‘답’이 존재하고 그걸 찾아서 제시하는 능력을 중시하는 듯. 반면 서울대는 답을 정해 놓지 않고, 여러 갈래 길을 주고 응시자의 견해를 궁금해 함. 빠른 시간 안에 본인만의 논리를 세워야 하고, 배경지식을 끌어올 수 있어야 함. 8시까지 입실이었고, 숙소에서 6시 반에 택시 잡아서 나갔는데 도착하니까 이미 거의 다 와 있었음. 입구에서 차로 들어가면 많이 막히는데 또 걸어가려면 한참이라 일찍 출발해야 함. 면접대기실에서 가방 제출하고 나면 자기 순서까지 아무것도 못 함. 책도 못 읽음. 본인은 끝 번호라 2시간 넘게 엎드려서 잤음.인문학 제시문 복기(가): 번역은 번역 텍스트를 모국어처럼 느낄 수 있게 착시 현상을 일으켜야 한다(나): 번역은 외국 여행을 하는 것처럼 이질성을 살려야 한다(다): 번역은 단지 의미 전달에 그치지 않고 번역하는 언어에 존재하는 이질적 요소를 모국어로 확장시킬 수 있어야 한다","notes":"","qa":[{"q":"(가), (나), (다) 번역에 대한 입장 비교, 본인의 독서 활동에 비추어 어떤 입장이 타당한지 설명","a":"(가)랑 (다)를 묶어서 모국어와 번역하는 언어의 연결을 중시하는 관점, (나)는 모국어와 번역하는 언어의 차이를 중시하는 관점으로 나눔. (가)랑 (다) 구체적으로 설명하고 공통점 다시 한 번 설명. (나) 구체적으로 설명. (가)랑 (다) 묶어서 얘기해 놓고 차이점은 크게 언급을 안 해서 꼬리 질문으로 물어보셨음. (가와 다는 완전히 같은 입장인 건가요?) 아니라고 하고 차이점 설명 드림. (가)와 (다)가 타당하다. 외국 문학을 읽을 때 그 나라의 문화나 정서가 우리와 많이 다르면 공감과 몰입이 어렵기 때문에 모국어와의 연결이 필요하다고 주장. 국문과라 독서 내용은 양귀자 박완서 김유정 이런 쪽만 준비해 가서 외국 서적 사례를 들라길래 당황함. 구체적인 책 이름을 대고, (가)와 (다) 중에 하나를 골라서 다른 두 입장과 차이점 짚어 주면 더 좋았을 것 같음."},{"q":"(박스 내용: 번역 활동과 역사 해석 활동은 유사하다) 구체적 사례를 들어 (가), (나), (다)가 어떻게 역사를 바라볼지 설명","a":"역사 해석과 결부시켜서 각각 설명. (가)는 마치 오늘날 일어나는 일인 것처럼 해석, (나)는 과거를 과거로 해석, (다)는 과거 사실만을 전달하는 게 아니라 오늘날로 확장해 해석, 이런 식으로 답변함. 준비할 땐 가나다 전부 각각 사례를 들어야 하나 고민하다가 너무 오래 걸릴 것 같아서 관둠. 아니나 다를까 꼬리 질문으로 사례 들어줄 수 있냐고 물어보셨음. 잠시만 고민해봐도 되냐 여쭤보고 518 민주화운동 예시 들어서 가나다에 적용시킴. 사회과학 제시문 복기(가): 자기 충족적 예언 설명(나): ‘부두 죽음’ 설명(다): ‘물가 안정 목표제’ 설명"},{"q":"(가) 바탕으로 (나)와 (다) 비교","a":"공통점으로는 자기 충족적 예언이 적용된 사례고 사람들의 믿음이 실제 행위로 이어졌다. 차이점으로는 (나)는 동기가 두려움과 공포라면 (다)는 중앙은행에 대한 신뢰다. (나)는 부정적 사례, (다)는 긍정적 사례."},{"q":"(나)의 ㄱ(자기 충족적 예언이 공동체의 믿음으로 이어져 차별과 배제를 낳는 문제)을 해결하기 위해 할 수 있는 노력 설명(예시 집단 중 세 집단 골라서 설명)","a":"교육자: 차별과 배제를 함부로 하지 않도록 교육, 차별과 배제를 받는다 하더라도 자신이 실제로 반사회적 인간이 아닐 수 있다고 교육(자기 충족적 예언에 대한 교육)정책 입안자: 차별과 배제를 사후적으로 조치, 사전적으로 예방할 수 있는 정책 마련연구자: 교육자와 정책 입안자에게 연구자료 제시, 신뢰성 확보시간 남으면 생기부나 지원동기 질문하는 경우도 있다고 들었는데, 올해 문제는 전체적으로 시간이 오래 걸려서 질문 거의 안 하신 듯.기 타국문과는 개인 필기구 못 쓰게 하셨고 검은색 볼펜 빌려주심. (과마다 다름)유의사항준비실에 시계 없음. 수능 시계 차고 가서 그거 보면서 함. 15분 지나면 옆에서 먼저 풀던 분이 면접실로 이동하셔서 대충 알 수는 있음."}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"서울대학교","dept":"기계공학부","jeonhyeong":"학생부종합(기회균형전형)","method":"2명의 교수님과 대면 면접. 생기부 기반 질문","notes":"독사 이빨을 모방한 여드름패치가 서울대에서 논문을 냈었다고 하시며 약간의 압박 질문이 들어옴. 대학에서 논문을 낸 것이 있으면 어느정도 읽어보는 것이 필요한 것 같다는 생각이 들었음.","qa":[{"q":"가우스 가속기가 무엇인가요?","a":"자석으로 쇠구슬을 가속시키는 하나의 장치, 전기력과 운동량 보존법칙 등으로 롤러코스터를 재현함."},{"q":"자연을 모방한 신소재에는 무엇이 있는가?","a":"독사의 이빨을 모방한 패치,-> 어떤 원리인가? 이빨이 휘어있기에 가장 적은 힘을 주고 가장 깊이 박히게 할 수 있는 구조이다"},{"q":"반장으로써 필요한 자질?","a":"공동체를 위해 희생과 헌신을 할 수 있는 능력. 고3때 반장을 하면서 학업이 중요했음에도 반을 위해 봉사하며 이러한 자질에 대해서 생각해봄."},{"q":"왜 수학적 모델링에 대한 탐구를 해보았는지?","a":"저의 목표인 유체에 대한 깊은 연구로 유체를 제어하고, 향후 연료전지 등과 연관한 탐구를 위해 유체에 대한 제어를 하는것이 필수. 이를 위해 수학적 모델링에 대해 공부해보면서 유체에 대한 제어의 기본적 이해를 돕기 위해 해보았음."},{"q":"연료전지와 유체의 제어가 무슨 연관?","a":"다양한 신재생에너지들의 효율을 높일 수 있고, 한가지 예시로 수소연료전지를 들자면 전지 내 수소분자, 산소분자나 전자의 흐름에 영향을 주며 전지의 효율성을 높일 수 있다고 생각함."},{"q":"학습을 하며 제일 어려웠던 기억은?","a":"나비에 스트로크 방정식을 탐구해보았던 기억. 유체의 흐름을 삼차원에서 파악해야하며 유체의 중력, 압력, 점성력을 x y z축에서 계산하며 이해의 어려움이 있었음. 하지만 기초 유체역학 책의 일부분을 발췌하여 이해하며 우력 등의 힘을 통해 과정을 단순화시키며 내용을 이해해봄."}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"서울대학교","dept":"농경제사회학부","jeonhyeong":"학생부종합(지역균형전형)","method":"면접관2인, 생기부기반면접, 10분내외","notes":"생기부 다 알고있기, 지원동기와 학업계획, 자기소개, 마지막말은 다 외워서 가기,면접 대기하면서 아무것도 못봄, 핫팩도 내야하고 물도 거기서 주는 거 먹어야함, 생각보다 되게 편한 분위기 속에 면접 진행함","qa":[{"q":"지속가능발전 프로젝트에 대해 탐구했던데, 이에 대해 설명해주세요","a":"유엔에서 발표한 sdgs17을 보고 지속가능발전프로젝트에 대해 탐구했습니다.--"},{"q":"빈곤에 대해 관심이 생긴 이유","a":"제 꿈은 빈곤을 해결하는 경제연구원입니다. 왜 세계의 절반은 굶주리는가, 빈곤의 연대기, 생각의 지도라는 책을 읽으면서 빈곤의 근본적인 원인은 식량문제라는 사실을 알게 되었고, 식량문제를 해결하고싶다."},{"q":"농경제사회학부에 지원하게 된 동기와 학업계획","a":"빈곤을 해결하는 경제연구원이 되고싶습니다. 빈곤의 근본적인 원인은 식량문제이고, 식량문제는 농업과도 직결되는 문제이기 때문에, 농업자원경제학을 전공하여 자원을 효율적으로 연구하는 법을 공부하고 싶습니다. 농업자원경제학을 대학원까지 가서 공부하여 국제식량농업기구에 진출하여 빈곤을 해결하는 경제연구원으로 성장하고 싶습니다."},{"q":"학생부회장, 회장 역할을 하면서 가장 기억에 남는 일","a":"운동장 사용과 관련된 학년간 갈등을 해결했습니다. 각 학년의 입장을 들어보고 가장 적합한 해결안을 도출한 뒤에 꾸준한 모니터링을 통해 해결안을 수정해나가는 과정을 거치면서 모든 학생이 만족할만한 결론을 내렸습니다."},{"q":"마지막으로 하고 싶은 말","a":"저는 단순히 학업성적이 뛰어난 학생이기보다는 꾸준했던 학생이었다고 자부할 수 있습니다. 왜 세계의 절반은 굶주리는가, 빈곤의 종말, 빈곤의 연대기, 생각의 지도와 같은 책들을 읽으면서 빈곤과 경제에 대한 관심을 꾸준히 키워나갔고 빈곤을 해결하는 경제연구원이라는 꿈을 키워나갔습니다."}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"서울대학교","dept":"산림과학부","jeonhyeong":"학생부종합(지역균형전형)","method":"학생부 기반 면접, 3배수, 면접관 2명, 10분 내외","notes":"접 당일에는 생각보다 차가 많아 붐빔.)두 분이 계셨는데 들어가니 교수님은 얼굴을 아는 분이었음. 홈페이지에서 교수님들 얼굴을 한 번 숙지하고 가는게 꽤 도움이 될 수 있음.뒤에서 두 번째 순서였는데 기다리는 동안 아무것도 할 수 없음. ( 약 1시간 정도 기다림.)생각보다 면접관님들이 밝은 표정을 해주셨기 때문에 긴장이 덜 됨.약 1분 정도 남았을 때 밖에서 노크를 해서 알려줌.","qa":[{"q":"저희 과에 지원하신 이유가 무엇인가요?","a":"제가 이 과에 지원한 이유에 ~"},{"q":"만약 저희 과에 오신다면 20년 정도 후에 어떤 일을 하실 것 같으세요?","a":"저는 산림과학부에 오게 된다면~"},{"q":"자율활동에 보니 독서 시간을 설정하고 꾸준히 독서를 하셨다고 되어 있는데 가장 인상 깊게 읽은 책 있다면 소개해줄래요?","a":"제가 가장 인상 깊게 읽은 책은 하이젠베르크의 저서 ‘부분과 전체’입니다. 생기부를 보시면 논술 시간의 활동에 활용하기도 하였는데요. 이 책에서 가장 기억에 남는 내용은 과학자의 책임에 관한 내용입니다. 이 책에서 하이젠베르크는~"},{"q":"화1 세특에 탐구한 내용이 저희 과와 관련이 깊네요. 모달과 같은 레이온 섬유에 대해 탐구하셨다 되어 있는데 어떤 내용인지 설명해주세요.","a":"우선 제가 이 활동을 한 동기에 대해 말씀드리겠습니다. 저는 축합중합, 첨가중합 등에 대해서 공부하며 합성 섬유 나일론에 대해서 자세히 알게 되었고 이런 합성 섬유가 만들어지는 과정에서 여러 화학 약품으로 인한 환경 오염이 일어나게 된다는 것을 알게 되었습니다. 좀 더 친환경적인 소재가 없는 지 알아보던 중 레이온 섬유라는 것에 대해 알게 되어 이에 대해 탐구했습니다. 레이온 섬유라 하면 나일론 같은 합성섬유와는 달리 중합 과정을 거치지는 않고 셀룰로스를 재생시켜 섬유로 다시 활용하는 소재로 알고 있습니다. 생기부에 기재되어 있는대로 레이온 합성섬유 실험도 진행했습니다. (교수님이 흥미를 보이시며 직접한 것인거냐 어려움은 없었냐고 물으심) 네 레이온 섬유 합성 실험이 ~과정인데 크게 복잡한 과정은 없어 어려움은 없었습니다."},{"q":"음 학생이 생각하는 친환경 소재란 무엇인가요?","a":"제가 생각하는 친환경 소재는 만들어지는 과정에서 환경오염이 없는 소재입니다. 하지만 저또한 소재가 만들어지는 과정에서 어쩔 수 없이 여러 화학 약품이 사용되는 것을 알고 있습니다. 그렇기 때문에 제가 생각하는 친환경 소재라고 하면 만들어지는 과정에서 발생하는 여러 환경 오염을 최소화하고 그 후에도 여러 가지 측면에서 환경 오염이 발생할 수 있는 문제들에 대해서 ~"},{"q":"약 30초 정도 남은 것 같은데 어필 시간 드리겠습니다.","a":"저는 제가 감히 서울대에 쓸 수 있을지는 몰랐습니다. 다만 운이 꽤 좋아 서울대에 지원할 수 있는 기회가 주어졌다고 생각합니다. ~~~서울대 면접을 준비하는 학생이라면 서울대 내부에 있는 호암교수회관에 묵는 것이 시간상 유리할 수 있음. (면"}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"서울대학교","dept":"수의학과","jeonhyeong":"학생부종합(일반전형)","method":"mmi 면접 방식이라서 10분씩 5개 방 질문 받고 답하는 형식나머지 방은 기억 잘 안나서 1,4번방만 적을게요.","notes":"2,3,5번방은 그래프 해석, 공혈견 선택 문제, x-ray 방사선 노출 문제에 관한 것이었고 특별히 여기서 변별하겠다는 의도는 못 느꼈습니다. (쉬웠고 계속 웃어주셨고 편안하게 해주셔서) 이 두방이 제일 힘들었고 꼬리 질문도 많았습니다. 교수님 두분이 들어오셨는데 눈 똑바로 번갈아 가며 마주쳤고 웃으면서, 여유있게 목소리 크게 대답하고 왔습니다.","qa":[{"q":"현재 수의학은 가축들과 관련된 농경사회와 정보사회로 나아갈 때 어느 정도의 범위와 역할인지 설명해줄 수 있을까요?","a":"네, 현재 수의학이 ~한 상황에서 맡고 있는 범위와 역할에 대해 말씀드리겠습니다. 현대 사회에서는 사람들의 활동 범위가 넒어짐에 따라 매일 새로운 병원체들을 만나고 있습니다. 이러한 상황 속에서 저는 수의사들이 빠르게 효율적인 백신을 개발해야 한다고 생각합니다. 만약 그러한 백신을 만들어 내지 못한다면 사람들은 그러한 생명체들을 맞서싸워야 할 적으로 생각할 것입니다. 하지만 그들은 적이 아니고 저희와 함께 살아가야할 생명체들입니다. 더군다나 현재에는 가축 질병과 인수공통감염병이 혼합된 형태로 발전되어 가고 있습니다. 예를 들자면, SFTS, 큐열, AI(였는지 럼피스킨이었는지..) 등과 같은 질병들이 있습니다. 이렇게 나날이 발전되어 가는 병원체들에 대한 적절한 백신을 만들어 내고 해결책을 제시해주는 것이 수의사의 역할이라고 생각합니다."},{"q":"수의학이 언제부터 왜 시작되었는지 어떻게 생각하나요?","a":"수의학이란 동물들과 인간의 복지를 위해 힘쓰는 학문입니다. 수의학은 동물들에 대한 연구를 기반으로 하기때문에, 옛날부터 사람들과 함께해왔던 동물들을 연구할 학문이 필요해서 생겼다고 생각합니다."},{"q":"그럼 인공지능과 수의사와의 관계는 어떻게 될 것 같나요?","a":"인공지능과 수의사는 서로 협력해가며 발전해 나 갈 것 같습니다. 우선 수의사는 임상과 수의사 두 가지로 나뉘는데, 비임상적인 부분에서 먼저 설명 드리겠습니다. 비임상 수의사는 식품 검역, 수의장교, 실험 동물 관리 등 다양한 일을 하지만 그중에서 연구사,, 아니 연구원으로서의 수의사에서 말씀드리겠습니다. 인공지능을 활용한다면 면역 펩티도믹스와 같은 기술을 이용해 신약을 개발할 때 화학물질의 반응을 예측할 수 있을 것입니다. 이를 통해 더 빠르게 약을 개발할 수 있습니다. 또, 가축들의 질병을 모니터링하며 공중보건에도 기여할 것입니다. 그다음 임상적 측면에서 말씀드리겠습니다. 임상수의사는 반려동물 뿐 아니라 다양한 동물들의 질병을 진단하고 또 보다 더 정확한 진단을 하기 위해 인공지능을 사용할 것입니다."},{"q":"수의사에 대해 많이 알고 있는 것 같은데 학교생활 중 수의사가 되기 위해 한 활동을 이야기해보래요?","a":"네, 저는 수의사에게는 의사소통 능력, 지역에 대한 관심등 다양한 덕목이 필요하지만 그 중에서도 끊임없는 도전정신과 동물에 대한 공감 능력이 가장 중요하다고 생각합니다. 우선 저는 연구 정신을 기르기 위해 여러 번 실험을 시행 착오를 겪으며 해냈던 적이 있습니다. 예를들어, 2학년 때 플라스틱과 빨대를 이용하여..."},{"q":"아까 수의사에게 동물에 대한 관심이 중요하다고 하였잖아요. 그거 한 번 이야기해볼까요?","a":"네 저는 동물에 대한 공감을 기르기 위하여, 다양한 서적을 읽고 봉사활동을 진행하였습니다. 제가 인상깊게 읽었던 책은 ‘동물과의 대화’입니다. 이 책의 주인공인 템플 그랜딘은 자폐성 장애를 가지고 있습니다. 그녀는 동물들의 시선에서 동물들을 위한 여러 가지 시설을 제작하였습니다. 이 책을 계기로 저는 동물들의 입장에서 먼저 생각해보는 계기가 되었다고 할 수 있습니다."},{"q":"네,, 더 듣고 싶은데 시간이 없어서 생기부 질문 하나만 할게용. (용하셨던 거 같은데...), 꿀벌을 한때 좋아하셨나봐요. 꿀벌에 대한 질병이나 탐구해보았던 것을 이야기해보세요?","a":"꿀벌을 좋아합니다. 꿀벌은 다양한 질병에 걸림에도 불구하고 그에 대한 많은 백신이 개발되어 있지 않습니다. 저는 그래서 농가측에서 사용할 수 있는 진단키트와 바로아 응애를 막을 수 있는 rnai백신을 탐구해보았습니다."},{"q":"돌연변이가 생명체에게 어떤 영향을 미칠 수 있는지 설명해주세요.","a":"(아니 읽지도 않았는데...음..)유전자 돌연변이가 일어난다면 ASF 즉 아프리카돼지열병과 같은 변종 바이러스에 취약한 개체가 생길 수도 있습니다. 돌연변이에 적응한 또다른 바이러스가 발생하기 때문입니다."},{"q":"유전자 변이가 단백질 형성에 어떤 영향을 끼치는지 설명할 수 있을까요?","a":"우선 유전자가 단백질을 형성하기 위해서는 DNA의 전사 번역 과정을 거칩니다. 만약 유전자가 변형된 DNA에서 번형된 RNA가 생성되고 그로 인해 단백질이 이상하게 생선된다면.. 음.. 그러한 과정을 거친 것입니다."},{"q":"유전자 변형 기술을 이용한 성공사례가 있을까요?","a":"네 제가 꿀벌의 바로아 응애를 차단하기 위해 꿀벌의 장내세균의 유전자를 변형하여 생장에 필요한 단백질 생산을 막은 rnai간섭 백신에 대해 조사해본 경험이 있습니다. 꿀벌 장내 세균의 유전자 돌연변이를 이용하여 진드기의 성장을 막은 예시가 있습니다."},{"q":"그럼 유전자 돌연변이가 생긴 것을 어떻게 확인할 수 있을까요?","a":"그건 전기영동이나 염기서열 분석등을 통해 확인할 수 있습니다. 제가 3학년 때 PTC 미맹 제한효소 실험을 하였습니다. PTC 미맹이 걸린 사람은 C->G로 바뀌는 돌연변이가 일어납니다. 정상 사람의 염기서열을 분석할 수 있는 제한효소를 넣어준다면 그 부위가 잘립니다. 당연히 그럼 비정상적 사람은 잘리지 않습니다 이렇게 결론적으로 유전자의 크기나 개수 등이 달라져 색소(이때 색소가 생각 안 나서 진짜 당황....) 전기영동으로 확인할 수 있습니다."},{"q":"그럼 유전자 편집 기술을 설명해줄 수 있나요?","a":"유전자 편집 기술은 cas-9단백질이 상요됩니다. 이 단백질은 rna효소와 함께 작용합니다. 어떤 ; 유전자를 인식하는 rna효소가 그 유전자를 인식한다면, cas-9단백질의 그 끝을 자르는 역할을 합니다."},{"q":"아까 장내세균을 이용한 유전자 변형을 말하셨잖아요. 그럼 체내에 있는 물질을 가공할 수는 없을까요..?","a":"음..(고민하고.. 생각났다는 듯이) 있습니다! 병원체에 감염된 세포의 테로머레이스를 분해하는 것입니다. 텔로미어는 세포가 분열할 때 정확성을 높이기 위하여 일정 부분 소비됩니다. 이를 재생시켜주는 효소가 텔로머레이스입니다. 병원체에 감염된 세포의 계속된 감염을 막기 위해 그 세포의 텔로머레이스를 분해시켜주는 효소를..... (종침)"}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"서울대학교","dept":"식물생산과학부","jeonhyeong":"학생부종합(지역균형전형)","method":"10분, 면접관 두분이서 2대1면접. 생기부 기반","notes":"분위기 편안함. 처음에 분위기 푸는 질문 많이 하셨음.잘 들어주시지만 꼬리질문이 날카로움.","qa":[{"q":"물리학1을 늦게 수강했는데 식물생산과학부와 뚜렷한 연관은 없어보인다. 수강 이유는?","a":"물리학1은 기초적인 과학이라고 생각하여 과학 지식을 쌓기 위해 들었습니다. 학교의 선택과목 수강 관련 안내가 원활하지 않아 물리학1을 수강하지 못하였고 이후 기초 내용으로써 화학 등의 과목과 밀접히 연관되어 있다는 점에서 물리학1이 필요하다 판단했습니다. 학교에 직접 요청하여 물리학1 수업이 개설되었고, 늦게나마 들을 수 있었습니다."},{"q":"생기부를 보면 의약학 계열에 관심이 많은데 식물생산과학부와 어떻게 연관지을 수 있을지?","a":"저는 약용식물에 관련한 연구를 하고 싶습니다. 항암제, 아스피린을 포함한 많은 약들이 식물을 연구하여 발견되었습니다. 최근에도 식물들의 몰랐던 약용 효과들이 계속해서 발견되는 상황입니다. 약용식물 연구를 통해 식물의 새로운 활용성, 약용효과의 강화 등을 통해 사람들에게 도움이 되고 싶으며 식물 연구 발전에 기여하고 싶습니다. 따라서 식물, 특히 약용생물학을 배울 수 있는 식물생산과학부에 지원하였습니다."},{"q":"생명과학 탐구 동아리에서 가장 기억에 남는 활동은? 활동하며 있었던 어려움은?","a":"동식물 세포 관찰실험이 가장 기억에 남습니다. 현미경을 처음 직접 다루게 되어 재밌게 활동했던 것 같습니다. 그렇지만 동아리원들이 적극적으로 참여하지 않는 어려움이 있었습니다. 아무래도 동아리 활동이 직접적인 학업 성적에 들어가지 않아 자습을 원하는 친구들도 많았습니다. 저는 저부터 즐겁게 열심히 참여하였고 나중에는 동아리원 대부분이 자연스레 적극적으로 실험 활동에 참여하게 되었습니다."},{"q":"학생에게 ‘팔방미인’이라는 표현이 쓰였는데 왜 그런 표현이 사용되었다고 생각하는지?","a":"제 담임 선생님은 체육 선생님이셨습니다. 제가 체육 시간에 농구, 축구, 배드민턴 등의 다양한 운동에 열정적으로 참여하고 반장과 부반장을 맡아 반을 이끌며 친구들과도 잘 소통하는 등 학교 생활 전반에 걸쳐 매 순간 최선을 다했다고 생각합니다. 선생님께서 저의 그러한 부분을 좋게 봐주셔서 ‘팔방미인’ 같은 표현을 써 주셨다고 생각합니다."}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"서울대학교","dept":"심리학과","jeonhyeong":"학생부종합(지역균형전형)","method":"생기부 기반 면접 / 10분 간 진행","notes":"면접 들어가기 전에,, 서울대학교 사회과학대에서 잡곡바를 나눠주길래 먹고 면접을 봤는데 끝나고 보니 이에 뭐가 껴있더라고용 ㅠㅠ 꼭 면접 보기 전에 거울 보고 다 확인하고 들어가세용 엉엉슨. 끝나고 너무 슬펐음.. 그리고 야자라는 말도 야간자율학습으로 바꿔서 이야기했어야 했는데 까먹고 놓침. 긴장은 엄청하고 말도 잘 못함 ,, 준비한 거 반의 반도 안 나온 듯 넘 슬펏다~~","qa":[{"q":"30초 동안 지원동기 설명해보세요.","a":"초등학교 저학년 때부터 눈에는 빨간 색으로 보이는 사과가 실제로 파란색이라면 어떨까? 하는 식으로 인지에 대해 궁금해했었고 그러한 궁금증들이 이어져 심리학에 대한 관심이 되었습니다. 심리학과에 진학하여 이런 어린 시절의 궁금증들을 탐구하고 싶습니다."},{"q":"가장 인상 깊었던 활동?","a":"BCI 기술의 윤리적 문제에 대해서 탐구하고 자료가 더 이상 나오지 않아 아닐 세스의 ‘내가 된다는 것’을 읽었습니다. 예측기제로서의 뇌라는 저자의 관점이 뇌의 작용기제에 대한 저의 생각을 아예 바꾸었고, 인지가 어떻게 작동하는 지에 대한 저의 이해가 깊어지는 계기였습니다."},{"q":"DQN 강화학습과 스키너의 조작적 조건화를 비교한 내용 설명해주세요.","a":"2학년때 심리학 공동 교육 과정을 이수하며 스키너의 조작적 조건화를 배웠는데, 비둘기에게 돌기를 가르치는 내용이었습니다. 반응에 대해 보상을 하며 강화한다는 아이디어가 이전에 본 DQN 강화학습 과정과 유사하다는 생각이 들었습니다. 과정을 일대일로 비교하며 살펴보니 실제로도 매개변수를 조정하고 그에 대해 보상을 주는 과정이 유사했습니다. 이 탐구를 수행하며 인공지능의 기초 개념인 퍼셉트론도 심리학자가 고안했다는 사실을 알게 되었습니다. 심리학의 응용 분야가 제 생각보다 훨씬 더 넓을 수 있다는 깨달음을 얻은 활동이었습니다."},{"q":"살펴보니 수학, 과학, 인공지능 등 이과 학문에 관심이 많네요. 맞나요?","a":"네 맞습니다. 가장 기억에 남는 이과적인 활동은 우울증 자가 진단 프로그램을 코딩해본 경험인 것 같습니다. 정보 시간에 배운 개념들을 종합하여 스스로 프로그래밍을 해보고자 시도했고, 공인된 기준을 사용하기 위해 정신의학과에서 실제로 사용하는 dsm5판을 가지고 우울증 진단 기준을 세웠습니다. 조현병, 조울증 등 유사한 질환과도 구분하기 위해 관련 문항들도 고심해서 비전공자도 알기 쉬운 용어로 풀어 기제했던 기억이 납니다."},{"q":"이것저것 트라이를 많이 해보신 것 같은데, 실패한 경험은 없나요?","a":"전교회장으로서 학생들의 건의사항을 선생님들께 전달하고자 월례 간담회를 개최하고 심야 야자를 추진하였습니다. 월례 간담회에서 좋은 반응을 얻어 바로 심야 야자를 추진하고자 학생들에게 성급하게 긍정적인 답변을 받았다고 전달한 결과 학생들이 감독하시는 선생님이 계시지 않은 상태로 남아있는 상황이 발생하였습니다. 커뮤니케이션 과정에서의 오류가 있었다고 판단하고 교장 선생님을 비롯한 선생님들과 소통으로 오해를 바로잡고자 노력하고 학생들에게도 사과했던 실패한 경험이 있습니다. 조직 내에서 커뮤니케이션 과정에서 크로스 체크가 얼마나 중요한지 깨닫고 그 이후로는 두 번 이상 확인하고자 했던 것 같습니다."},{"q":"시간이 다 되었네요. 마지막으로 하고 싶은 말 있나요?","a":"이렇게 앞에 계신 두 분의 교수님과 이야기를 나누게 되어 영광입니다. 서울대학교에 진학하여 교수님들께 지도를 받으며 심리학 연구를 수행하는 것이 가장 좋은 길이겠지만, 혹여나 서울대학교에 진학하지 못하더라도 저에게 주어진 환경에서 최선을 다해 공부하고 있을테니 나중에 심리학자 대 심리학자로 다시 만나는 날이 오기를 기대하고 있겠습니다. 이야기 들어주셔서 감사합니다."}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"서울대학교","dept":"식품ㆍ동물생명공학부","jeonhyeong":"학생부종합(지역균형전형)","method":"ㆍ서류(생기부)기반 대면면접, 면접관 2 : 지원자 1ㆍ대기실 내에서 가번호 부여 후 가번호 순서대로 면접 진행ㆍ정확히 10분간 면접 진행","notes":"로와 관련 없는 분야일지라도 모든 생기부 활동을 꼼꼼히 분석하고 정리하는 것이 필요하다고 생각된다.대기실 입실 시간(08:20)이 지나면 본인이 보고 있던 자료를 포함한 모든 소지품을 큰 비닐봉투 안에 넣고 제출해야 한다. 면접 시작 시간이 9시이기 때문에 짧게는 40분, 길게는 2-3시간 동안 대기실에서 멍 때리고 있어야 한다.과목별 세특 질문보다는 진로활동, 자율활동에 기재된 내용에 대한 질문을 많이 하시는 듯 하다.면접시간 10분은 칼같이 지켜지고 대략 1분 정도 남았을 때 밖에서 알려주신다. 시간 압박이 있더라도 답변은 차분하고 침착하게 하자.","qa":[{"q":"우리 과에 지원하게 된 동기와 식품공학이라는 학문이 무엇이라고 생각하는지 말해줄래요?","a":"주변에 식품 섭취에 있어 어려움을 겪고 계시는 분들이 많아 이런 어려움을 극복하는 데에 도움이 되고 싶어 식품공학자라는 꿈을 꾸게 되었다고 답변함. 식품공학은 식품 개발, 제조뿐만 아니라 유통, 저장, 보관 등 식품 공정 전반을 관할하고 연구하는 학문이라고 답변함."},{"q":"생기부 보니까 유당불내증에 대해 조사한 것 같은데, 이에 대해 설명해줄래요?","a":"생기부 내용 기반으로 답변함. 락타아제라는 효소가 결핍되었을 경우 유당불내증이 발생할 수 있다고 답변함."},{"q":"아까 답변하면서 락타아제에 대해 설명했는데, 락타아제의 다른 이름이 뭔지 혹시 알고 있나요?","a":"고민하다가 결국 모르겠다고 답변함."},{"q":"지속가능성과 같은 요즘 트렌드를 반영했을 때, 식품 산업이 나아가야 하는 방향은 무엇일까요?","a":""},{"q":"그리고 사실 식품첨가물이라고 하면 소비자들은 부정적인 인상을 갖고 있는 경우가 많은데, 이를 해결하기 위해서는 어떻게 해야 할까요? 여기에 대한 본인 생각을 말해주세요.","a":"지속가능성이라는 트렌드를 보았을 때, 식품 업계는 ‘대체 식품’을 중심으로 발전해나가야 한다고 설명함. 식품첨가물에 대한 소비자들의 부정적인 인상을 타개하기 위해서는 기업 측면에서 식품첨가물에 대한 인식 개선 캠페인이나 광고 등을 진행하여야 한다고 답변함."},{"q":"생기부 보니까 1학년 때 네일아티스트라는 직업을 체험했네요? 어떤 경험이었고 무엇을 배웠는지 얘기해주세요.","a":"전혀 예상하지 못했던 질문이라 생각나는 대로 답변함. 네일 아티스트 체험을 통해 그때 처음으로 네일을 해보았는데 생각보다 무게감이 있었음을 느꼈고, 그 체험과 강연을 들으며 네일 및 뷰티 산업 전반에 대한 흐름을 이해할 수 있었다고 답변함."},{"q":"메틸셀룰로스를 이용한 튀김의 흡유량을 예측했다고 했는데 자세히 설명해줄래요?","a":"생기부 내용을 기반으로 답변함. 다만 실제 예측한 것이 아니라 쌀가루 기반의 튀김 흡유량을 예측해주는 ai프로그램이 있는데, 이것과 메틸셀룰로스를 이용한 튀김을 연계해보면 어떨까라는 구상을 해본 것이라고 답변함."},{"q":"생기부 보니까 모둠장을 많이 맡아본 것 같은데, 우리가 모둠활동하다 보면 참여 안하고 비협조적이고... 그런 팀원이 있잖아요? 이거에 대해 어떻게 생각하는 지 설명해주세요.","a":"그런 팀원들은 자신의 흥미에 맞지 않는, 혹은 자신이 잘 해낼 수 없으리라 생각하는 역할을 부여받았기 때문에 비협조적인 태도를 보이는 것이라고 답변함. 따라서 리더 역할을 맡았을 때, 각 팀원의 장점, 흥미, 적성, 특성 등등을 잘 분석하여 작은 역할이라도 그 각각의 팀원들이 가장 잘 수행해낼 수 있는 역할을 부여하는 방식으로 문제를 해결했다고 답변함."},{"q":"시간이 얼마 안 남았는데, 마지막으로 가장 인상깊었던 책이 있으면 소개해주세요.","a":"최낙언 교수님께서 쓰신 ‘맛의 원리’라는 책이 인상깊었다고 소개함. 정비각과 후비각의 관계에 대해 알게되어 흥미로웠다는 식으로 답변했으나 시간이 얼마 남지 않았다는 압박감에 다소 산만하게 답변함.전반적으로 압박 면접의 분위기는 아니었다. 다만 지원자가 당황할 만한 질문을 몇 개 하시는 듯 하다. 전공, 진"}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"서울대학교","dept":"약학계열","jeonhyeong":"학생부종합(지역균형전형)","method":"생기부 기반 면접이며, 면접 시간은 10분입니다.지원 동기도 없이 바로 시작했다, 교수님 두 분 중 한 분은 무표정이시고, 한 분은 계속 미소를 짓고 계셨다.","notes":"끝나기 1분 전에 노크해 주고 노크해도 이어서 그냥 말하면 된다. 교수님과의 거리는 가깝지도 멀지도 않은 편이었으며 의자뿐만 아니라 책상도 준다.1차 합격 후 받는 수험번호가 순서는 아니고 당일 대기실에서 면접 번호를 따로 받았다. 유의 사항 안내 후 대기실에서 자료를 보는 것이 불가능하다. 오직 물 마시는 것과 화장실 가는 것만 허용된다. 뒷 번호의 경우 2~3시간 이상 대기해야 할 수도 있다.","qa":[{"q":"2학년 과학과제 연구에 대장균에 대한 녹차 추출물의 MIC 실험을 했던데 내용에 대해 말해 보세요.","a":"천연물에서 항생물질 추출 책 읽고~관심 생겨서 마침 일본어 시간에 녹차가 항균효과 있다고 해서 선택함 특히 자료조사로 다른 사람들의 실험을 찾아볼때 아직 하지 않는 재료라 내가 도전정신을 가지고 함/실험 간단히 설명, 추출을 에탄올과 증류수로 낭눠 했고 증류수는 효과 x, 에탄올은 대조군 카나마이신보다 최소 저해농도가 25<100 높아서 효능이 떨어지긴 하지만 관련 사전 조사(120ug/ml)와 비교해서 충분히 항생제로 쓸 가능성이 있다고 결론지음/예상 못한 시행착오들 얘기함 첫번째로 재료 배송오류, 이때문에 실험 일정이 밀려 2회 진행후 평균을 내야하는데 그러지 못해 아쉬움, 대학와서 보완하고 싶다, 두번째로 억제대가 원형이 아님, 이를 대비해 에탄올만 접종한 대조군 만들고 여기서 억제대 형성 안됐기 때문에 내가 에탄올은 충분히 증발시켰고 아마 항온기 내 위치에 따른 온도나 대장균 도말 시 문제로 보인다고 결론 내렸다고 답함, 이렇게 예상 못한 어려움이 많았지만 이를 해결하고 이유를 추론하는 과정이 많은 도움이 되었고 재밌었기 때문에 이런 시행착오들이 오히려 실험을 더 흥미롭게 만들어준 점이라고 생각한다고 답함."},{"q":"화학 II에 반감기 조사하고 발표하면서~~활동에서 열심히 한 점 위주로 얘기해 보세요.","a":"2학년 때 미적분에 대한 책을 찾아 읽었는데 그 책에 혈중 농도 공식이란 게 있었음. 당시는 왜 이런 식을 쓰는지 몰랐는데 0차, 1차 반응에 대해 조사하며 1차 반응의 속도식을 적분하면 해당 식이 나옴을 직접 유도해 봄. 이처럼 수학과 화학의 접목을 통해 몰랐던 점을 알게 됨. 게다가 교과서에 소개된 반응의 반감기가 일정한 이유가 궁금하여 이를 식으로 유도 후 그래프 그리는 프로그램을 이용해 모든 반응이 그런게 아니라 1차만 그러한 성질을 가짐을 이해함. 이처럼 열정적으로 궁금한 점을 직접 찾고 실행에 옮기고 이를 친구들에게 발표했다고 말함."},{"q":"2학년 수업량 유연화 과정에서 항생제를 탐구하고 MIC 실험을 했는데 이때 쓰인 그람 양성균과 음성균의 차이가 뭔가요?","a":"그람 염색시 그람양성균은 두꺼운 세포벽 때문에 탈색이 잘 되지 않아 여전히 자색을 띰,음성균은 세포벽이 비교적 얇아 탈색이 잘 되어 적색을 띰, 이처럼 세포벽의 구조로 구분이 됨."},{"q":"그럼 양성균과 음성균에 따라 항생제에 어떤 반응을 보이는지 말해 보세요.","a":"그람 양성균은 세포벽이 두껍기 때문에 세포벽을 분해하는(펩티도글리칸이라는 용어를 썼는지 가물가물함) 항생제 계열인 페니실린계에 취약함을 보임, 반면 그람 음성균은 얇은 세포벽 위에 외막이 있어 세포를 보호하므로 페니실린계 같은 항생제는 효과가 적고 양성균보다 내성이 발현되기 쉬움, 따라서 다른 방식의 항생제를 선택해서 사용해야 함."},{"q":"3학년 진로활동에 적힌 인공지능이 신약 개발에 어떻게 쓰이나요?","a":"올해 노벨 화학상이 인공지능 개발자일 정도로 이제 생명, 화학 분야에 인공지능이 접목되고 있음, 단백질 접힘 구조 예측 모델 알파폴드를 설명함, 현재 아미노산끼리 상호작용에서 dna같은 다른 분자와의 상호작용까지 다루도록 발전 가능, 그리고 생체 내에서 수용체와 결합시에 미세한 구조 변화까지 설계가 되면 질병의 메커니즘을 연구 가능, 이를 표적하여 치료법을 개발하거나 약의 반응, 부작용을 예측하여 모델링하는 기반이 됨."},{"q":"인공지능 신약개발의 단점은?","a":"아무래도 인공지능이 오류가 0이라 할 수 없고 이것이 사람들에게 악영향을 미칠수도 있음, 또 아직 생체 내 반응이나 상호작용에서 미흡한 점도 많아서 인체 적용에 한계있음, 하지만 인공지능이 시간과 비용을 절약하는 일종의 도구이고 나는 사람이 결정자이기 때문에 인공지능의 장점은 얻고 단점은 버리는 식으로 개발자들이 스스로 선택하고 과정을 통솔해야한다고 생각함, 그리고 최근 몇 년 크게 성장한 것처럼 앞으로 기술의 부족은 점차 보완될 것이라 단점이 아직 많더라도 인공지능의 역할이 매우 중요한 것은 맞음."},{"q":"3학년 진로활동에 적힌 친환경 약물 개발에 어떤 것이 있는지 말해 보세요.","a":"합성 시 주로 사용되는 유기용매를 대체할 수 있는 초임계액과 이온생 액체를 설명함, 회수가 쉬워 재활용이 잘되면서 효율이 좋은게 장점임, 합성뿐만 아니라 약의 포장시 이중포장 생략, 생분해성 재질 사용 등 사소한 부분도 개선해야 한다고 주장함."},{"q":"생명과학 I에 대식세포 M1과 M2를 구분하는 형광물질의 구분 방법과 형광물질의 중요성을 말해 보세요.","a":"M1, M2의 역할 설명 후 주에너지원이 탄수화물, 지방산으로 나뉘므로 이를 이용하여 탄수화물 기반 화합물을 형광물질로 사용해 구분한다고 말함, 형광 물질은 복잡한 방법 없이 현미경으로 쉽게 관찰해서 세포의 활성화와 위치를 알 수 있어 앞서 한 대답처럼 질병 메커니즘을 밝히고 치료법을 연구하는 것을 도와준다고 말함.이 대답을 하던 중간에 노크 소리가 들렸다."},{"q":"서울대 약대에 지원한 동기가 무엇인가요?","a":"1학년 때 서울대 약대를 소개하는 글을 봤음, 다른 약대와 다르게 약학 연구원을 양성하는게 주 목표라는 것이 멋있다고 생각했음, 나는 약학이란 학문에 큰 관심을 갖고 있어서 약사 자격증을 그저 얻는 것이 아니라 약학 연구원이 되는 것이 꿈임, 대학원까지 진학하여 공부를 하고 싶은 열정도 현재 있음, 따라서 서울대 관련 사이트나 정보 등을 찾아보는 등 이 학교에 꾸준히 관심을 가져옴, 특히 ‘천연물을 기반으로 한 항생물질 발견’ 연구에 관심을 가지고 있어 이에 대한 학교의 연구 성과를 찾아보기도 함(이 말을 할 때 미소 교수님이 더 크게 웃음? 웃음을 참는 듯한 표정? 을 지으셨다..) 따라서 미래의 약학 연구원으로 성장하기 위해 이 학교에서 꼭 공부하고 싶다고 대답함.꼬리 질문이 딱히 없어서 이상하다고 생각했는데 다 쓰고 보니 내가 답변이 긴 편이라 그럴수도 있겠다. 과마다 사람마다 다르겠지만 압박 면접이 아닌 편안한 분위기의 면접이었다."}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"서울대학교","dept":"영어교육과","jeonhyeong":"학생부종합(지역균형전형)","method":"2:1로 진행, 면접관 두 명과 학생 한 명이 면접을 진행함.","notes":"8시 15분까지 입실하고 첫 학생 면접이 한 9시 넘어서 시작되었던 것 같음. 기다리는 데 너무 힘들었음. 대기실에 히터가 많이 나오고 폰도 제출하고 아무 말도 못하고 있으니 잠이 몰려왔음.물을 꼭 챙겨 가서 마실 것. 면접 보는 교실도 히터가 많이 나와서 목이 너무 건조했음. 말 하는데 목이 아플 정도로 건조함!! 물을 꼭 가져갈 것!!","qa":[{"q":"교사 이슈 관련해서, 교사에 관한 인식이 예전과 많이 바뀌었나?","a":"서이초 교사 자살 사건이나, 교권침해 사례 등이 꾸준히 늘어나는 것을 보니 예전 만큼 교사에 대한 인식이 많이 안 좋아진 것 같습니다."},{"q":"역사랑 일반사회를 잘했다고 생기부에 나와있는데, 왜 과목을 바꾸게 되었나요?","a":"중학교 때까지 역사랑 일반사회가 마냥 좋아서 멘토링 활동도 하다 보니 막연히 고등학교 1학년 때까지 역사랑 일반사회 교사를 꿈꿔왔던 것 같습니다. 하지만 고등학교 2학년 때 영어 시간에 멘토-멘티 수행평가에서 멘토로서, 반 친구들과 멘티에게 영어 지문을 어떻게 하면 재밌고 쉽게 알려줄지에 대해 고민하는 과정에서 영어에 대한 즐거움, 지식을 전달하는 데에 대한 즐거움을 느꼈습니다."},{"q":"그럼 결론적으로 교사나 영어교사를 꿈꾸게 된 이유는?","a":"앞서 말했던 수행평가에서 영어에 대한 확신과 2학년 때부터 반장을 해오면서 학급 운영 및 친구들을 챙겨주고, 대가 없이 오는 뿌듯함 등이 저를 교사라는 길로 이끌었던 것 같습니다."},{"q":"영어 동아리를 운영하셨네요? 혹시 영어 동아리 운영하시면서 힘드셨던 점은 없나요?","a":"수능 공부, 내신 공부에 지쳐있는 친구들이 영어 동아리에서까지 영어를 해야 하냐며 그냥 자습을 주면 안되냐는 등 의욕이 없고 많이 힘들어하였습니다. 저는 친구들의 이 지친 마음을 풀어주면서도 영어까지 할 수 있는 활동을 찾다가 영어 필사 활동과 영어 토론 활동을 기획하게 되었습니다."},{"q":"동아리원들이 활동을 잘 수행해냈나요?","a":"네. 영어 필사도 꾸준히 하고 영어 토론 활동에서도 약식 토론이었긴 하지만 적극적으로 참여해주었습니다."},{"q":"‘영어를 잘하면 우리는 행복해질까’ 라는 이 책을 읽고 느낀점으로 우리나라 영어교육이 우리 사회에 끼친 부정적인 영향이 있다고 생기부에 쓰여있습니다. 어떤 부정적인 영향이 있나요?","a":"지나친 영어 사교육, 쓰기와 읽기 중심, 독해 기술에만 집중하고 실생활에서 쓰이는 듣기와 말하기는 교육하지 않는다는 내용으로 말을 했던 것 같음."},{"q":"그러면 듣기와 말하기 교육을 활성화하기 위해서 학생이 생각한 방안이 있나요?","a":"원어민 강사와 말하기 수업이나 줌이나 구글 클래스룸? 같은 플랫폼을 활용하여 외국에 있는 선생님과 수업을 진행하면 좋을 것 같습니다.(1분 남았다고 밖에서 노크를 함.)"},{"q":"앞서 말했던 책 이름이 ‘영어를 잘하면 우리는 행복해질까’였습니다. 정말로 영어를 잘하면 우리는 행복해질까요?","a":"행복해질 것 같습니다! 영어를 잘해서 의사소통 능력이 향상되면 다양한 외국인 친구들을 만나 많은 경험을 쌓을 수 있을 수 있고 또 타지에 나가더라도 적응이 빨라 살아가는 데 많은 도움이 되니 행복해질 것 같습니다."},{"q":"영어는 우리나라 모국어가 아닌데도 행복해질까요?","a":"모국어가 아니어도 영어를 활용해 실험을 하고 논문을 작성하고 좋은 성과를 이루어내 우리나라를 널리 알릴 수 있고 뽐낼 수 있으니 행복해질 거라고 생각합니다!"}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"서울대학교","dept":"에너지자원공학과","jeonhyeong":"학생부종합(지역균형전형)","method":"2대 1 면접, 10분 동안, 학생부 기반 면접","notes":"인 가능. 8시에 번호표 받고 한 시간 정도는 아무것도 없이 기다려야만 함, (가져온 프린트 전부 넣고 수험표만 올려놓으라고 함) 첫 번쨰 조 8시 50분 출발. 한 조에 각 과당 두 명씩 이동. (두 번째 조는 9시 10분 출발. 한 명당 10분씩) 면접관들과 자리 엄청 가까움. (약 40~60CM?) 대화하는 듯 한 분위기. 편하게 하면 될 것 같다. 평소에 본인 활동에 대해서 여러 측면에서 깊이 생각해 보는 것이 도움이 될 듯. 끝나기 1분 전에 밖에서 노크해 준다고는 하는데 안 들린다.","qa":[{"q":"(2학년 지구과학 수행평가) 지구온난화 관련한 질문. (정확히 기억 안 난다. 어려운 질문 아니라 간단히 생각 확인하는 질문)","a":"적당히 잘 대답했다. 뭐라고 했었는지 기억이 안 난다."},{"q":"(2학년 지구과학 수행평가) 지구온난화로 인한 해수면 상승의 심각성을 어떻게 드러냈는가?","a":"IPCC 기후변화연구보고서 같은 자료들을 참고하여 수치적으로 드러냈던 것 같다."},{"q":"(2학년 지구과학 수행평가) 그러한 수치적 상승이(해수면의) 지구온난화 때문이 아니라 지속적으로 주기적으로 일어나왔던 지구의 변화? 작용 아닌가?","a":"이 수치가 주기적인 것 이상으로 이례적으로 크기 때문에 지구온난화 때문이라고 생각한다. 대답이 애매했는지 표정이 이상하셨다."},{"q":"(3학년 동아리 시간) 사용후 핵연료 심층처분장 관련한 활동 어떻게 했는지 설명해달라는 내용의 질문","a":"아는 대로 대답하였음. 동기-과정-결과-의미 순으로 설명하되 의미에 스스로가 에너지 기술 관련 정책 전문가를 꿈꾸는데 이러이러한 활동이 이러이러한 점에서 이런 꿈을 이루는 데 어떠한 기본 소양을 길러준 것 같다는 식으로 답했음."},{"q":"(3학년 동아리 시간) 심층처분장 부지 선정하려면 무엇무엇을 고려해야 하는가?","a":"아는대로 말씀 드렸는데, ‘이 활동을 하기 전에도 이러이러한 점은 고려해야 할 것 같았는데 활동을 하면서 흥미로웠던 점은 이러이러한 점(지질학적 요건 등)도 고려해야 한다는 것이었다.’ 이런 형식으로 답변했었음."},{"q":"에너지 정책에 관심 있냐는 질문","a":"그렇다고 하고, 구체적으로 한국에너지기술연구원 연구전략본부에서 연구원으로 일하고 싶다고 함."},{"q":"그럼 무슨 과목 들어야 할 것 같은가?+정책전문가로서 어떤 가치관을 중요시 여기는지?","a":"개인적으로는 국제에너지시장분석이나 에너지환경기술경영 등 과목 수강하고 싶다."},{"q":"(3학년 물리 시간을 예로 드시면서) 어려웠던 활동 소개해 달라.","a":"3학년 동아리 시간의 파이로프로세싱 관련 활동이라고 소개하다가 끝남.끝나고 보니 잘했다는 느낌은 아니었다. 대기할 때 앞번호 아이 면접하는 것이 약간 들렸는데 분위기가 좀 달랐다.대기실에서 다른 과 지원자들과 함께 대기. 입실 시간(7시~8시) 동안은 자유롭게 휴대폰 확인, 가져온 프린트 확"}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"서울대학교","dept":"영어영문학과","jeonhyeong":"학생부종합(일반전형)","method":"제시문 면접(인문학+사회과학)인문학제시문 (가)(나)(다) - 문제는 홈페이지에서 확인할 수 있습니다.","notes":"합니다. 본인의 답이 꼭 정답이 아니더라도 납득할만한 근거가 있고, 그걸로 교수님을 설득한다면 되는 것입니다! 그렇기 때문에 배경지식을 뽐내며 번지르르한 답변을 만드는 것보다, 제시문에 충실하여 논리적이고 명료한 답변을 만드는 것이 더 중요하니, 기출 분석할 때 다각도로 접근해보며 가장 논리적인 구조를 만드는 연습을 해보세요.모의면접 꼭~~~~~~~해보세요. 저는 면접 전날에 서울에 올라가서 모의면접을 2번 봤었는데, 그 경험이 상당히 도움이 되었습니다. (실제 면접보다 모의면접이 더 떨리기도...) 학교에서든, 학원에서든, 어디서든 상관없지만 단! 실전과 유사하게 긴장된 환경을 만들고, 그 속에서 면접 연습을 꼭 해봐야합니다. 면접날 답변 구상실이 너무 추워서 긴장이 더 되었었는데, 모의면접 했던 거 생각하면서 금방 안정을 되찾았습니다. 연습을 많이 하면 할수록 긴장 상태에서 안정 상태로 가는 속도가 더 빨라질겁니다. 자신에 대한 믿음과 자신감또한 올라갈거구요! 기출 분석, 답변 구성 연습하셨다면 모의면접도 반드시 여러 번 긴장된 상태에서 해보시길 바랍니다.면접, 생각보다 별거 아닙니다!!! 들어가 인사할 때도 웃으면서, 나올 때도 웃으면서! 반드시 방긋 웃으면서 자신감있게, 밝게 이야기하시구, 최대한 편안하게 하려고 노력하세요!!!! *^^* 위에 적은 tip들 참고하셔서 연습하시면 더 도움이 될 겁니다. 끝까지 포기하지 마시고, 최선을 다한다면 원하는 결과 얻을 수 있을 겁니다. 파이팅!!!!!","qa":[{"q":"1. 번역에 대한 세가지 관점 비교, 셋 중 타당한 관점을 본인의 독서경험을 들어 설명","a":"공통점: 번역가의 번역에 따라 독자의 수용양상 달라짐.차이점: 번역에서 주력해야할 부분(가) 원작의 느낌이 나도록 자연스럽게 수정, 독자가 이해하기 쉽도록(나) 번역문이 어색하더라도 원작의 형태 그대로(다) 원어, 번역어 모두 확장할 필요(다)가 타당하다고 생각함. ‘깐부’를 다른 영어단어가 아닌 ‘gganbu’로 번역한 것을 영어를 확장한 예시로, ‘the great gatsby’를 ‘최고의’, ‘멋진’이 아닌 ‘위대한 개츠비’로 번역한 것을 번역의 과정에서 새로운 의미를 발견한 예시로 설명함.tip) 문제에서 요구하는 종류의 예시가 아니더라도, 자기가 생각했을 때 적합한 예시라고 생각되면 미리 말씀드리고(깐부라는 단어는 책에서 근거한 것은 아니지만~) 당당하게 이야기할 것!tip) 비교 문제에서는 꼭 공통점과 차이점 모두 말할 것! 공통점 빼먹기 쉬우니까 의식적으로라 기억했다가 말하려고 노력하기.1번 문제 추가질문"},{"q":"깐부를 예로 들어 설명한 것이 왜 (다)와 연결되는지","a":"여기에 모두 적지는 못하겠지만... 깐부와 위대한 개츠비를 예시로 든 저만의 논리적 이유가 있었기 때문에 그것을 정리해서 답변을 했고, 교수님도 이해하셨다는 듯이 끄덕끄덕하고 넘어감."},{"q":"역사해석과 번역 과정을 빗대어 (가)(나)(다) 설명 + 사례","a":"주어진 글(역사해석과 번역과정을 빗대는 글) 요약(가) 역사 해석 시 주관적인 해석 가미하여 이해하기 쉽게 이야기를 만들것임.(나) 역사적 사실 그 자체를 강조할 것임.(다) 사실성과 허구성 적절히 조합사례: 유대인 학살에 가담한 독일 경찰대(가) 사회적 맥락, 순응주의 등을 이유로 들어 그들이 왜 유대인 학살에 가담했을지 설명(나) 유대인을 학살했다는 사실 자체에 집중(다) 사실 자체 + 왜 그랬을지 이유 제시tip) 위의 사례는 서울대 기출 중에 있었던 내용! 역대 서울대 기출을 풀면서 제시문 면접의 방법을 익히는 것은 물론이고, 핵심내용을 기억해두면 이렇게 사례를 요구하는 문제에서 다른 배경지식 끌어올 필요없이 용이하게 써먹을 수 있음.2번문제 추가질문"},{"q":"(이 부분을 잘 못 들으셨는지) (가)의 입장에서 역사해석 어떻게 했을지 다시 물어봄.","a":"다시 더 구체적으로, 이해하기 쉽게 설명함.사회과학제시문 (가)(나)(다) - 문제는 홈페이지에서 확인할 수 있습니다."},{"q":"자기실현적 예언의 관점에서 (나), (다) 비교","a":"자기실현적 예언 (가) 설명(나)(다) 공통점: 신뢰를 기반으로 함.차이점: (나)는 예측과 결과를 두고 보았을 때 비과학적, 비논리적 과정을 거침.(주술의 비과학성) 반면 (다)는 예측과 결과를 보았을 때 물가상승이라는 결과에 영향을 주는 행동들이 논리적으로 이어지므로 과학적임. (나)와 (다) 모두 예측과 결과 간의 상관성은 있지만, (나)는 논리적 인과성이 없고 (다)는 인과성이 있다. (이 부분은 저도 이야기하면서 이게 맞나 의심이 들었지만... 교수님들도 이해가 안된다는 표정을 지으셨지만... 안 그런 척 당당하게 이야기했습니다.)1번 문제 추가질문"},{"q":"상관성이 있다는게 무슨 뜻인가요?","a":"예측이 결과로 이어지는 것이 과학적이든 비과학적이든 연관이 있는 것으로 나타나기 때문에 ~(나)가 인과성이 없다고 했는데.. 인과성이 있는 거 아닌가?(나)도 물론 예측이 결과로 이어지는 과정을 보면 인과성이 있는 것 같지만 (다)에 비해서 과학적으로 설명되는 과정이 아니기 때문에 ~ 이 부분 열심히 설명했는데 한 분은 이해된다는 표정, 한 분은 이해 못하신 표정으로 다음으로 넘어감.(나)에서는 주로 믿음이라는 표현을 사용하는데 신뢰라는 말을 사용하시네요. 믿음과 신뢰는 차이가 있다고 생각하나요?이 때 조금 당황했지만... 차분하게 생각해보고, 믿음과 신뢰의 언어적 차이는 확신할 수 없지만, 제시문 (나)에서 신뢰라는 단어를 ~라는 맥락에서 사용하는 것으로 볼 때, 믿음과 유사한 의미에서 사용될 수 있다고 생각한다고 답변함."},{"q":"밑줄친 문제 해결 노력을 교육자, 언론인, 정책 입안자, 연구자 중 두 가지(세가지?) 이상의 관점에서 설명","a":"밑줄친 문제: 근거없이 예측을 확정짓고 낙인을 찍어 그것이 결과로 이어지는 현상교육자 – 교육 시 편견 없이 아이들 교육. 교육자의 특성상 성장기인 아이들과 접촉하므로아이들의 미래에 미치는 영향이 지대함을 강조함.언론인 – 기사 작성 시 사실검토과정을 거칠 것, 그 과정에서 자신의 주관을 개입하지 말 것을 강조함. 언론의 특성(정보 확산이 빠름)을 강조함.정책 입안자 – 가장 포괄적인 노력을 해야함. 문제를 예방하기 위한 사전적 노력과 문제 발생 후 사후적 노력으로 나누어 설명. > 교육자와 언론인 선발 시 교육과정을 거칠 것, 부당하게 차별당하는 사람이 그것이 부당하다고 인식할 수 있도록 할 것, 피해 발생 시 구제책 마련할 것 등 설명.tip) 해결책을 설명할 때 사전적 문제 예방책과, 사후적 구제 방법 등으로 나누어 설명하면 그냥 나열만 하는 것보다 훨씬 논리적인 구조가 될 수 있음.2번 문제 추가질문"},{"q":"잘 못 들어서 정책 입안자가 해야할 노력 부분 다시 말해주세요.(이 때 시간 얼마 안 남아서 조금 빠르게 말했더니 재질문하심.)","a":"다시 설명~선발 시 교육을 거쳐야한다고 했는데 선발과정에 교육을 넣어야한다는 의미인가요 아님 선발하고 교육을 해야한다는 의미안가요 아님 둘다인가요?(잠시 생각하다가) 선발과 교육의 순서가 중요한 것이 아니라, 교육자와 언론인이 교육의 과정을 거치는게 중요하다는 점에서 그렇게 답변한 것이라고 이야기함.제시문 추가질문 tip) 어떤 당황스러운 질문이 나와도, 말리지 말 것! 제시문의 내용, 자신이 답변할 때 어떤 의도로 그렇게 답변한 것인지를 중심으로 이야기하면 되니까! 차분하게 자신의 생각을 말하면 됩니다.시간 거의 다 되었을 때 마지막 추가질문고등학교 재학 시절 가장 인상깊게 읽은 책은?미리 준비한 답변 이야기함.서울대는 과별로 면접을 진행하기 때문에 대기 시간에 가져온 자료를 볼 수 있는지, 물을 나누어주는지, 시계가 있는지 등등의 세부사항이 상이합니다. 영어영문학과의 경우 대기실에 물과 간식이 있었고, 시계도 있었지만 모든 짐을 다 내야했습니다. 저는 18명 중 18번이 걸려서 아침 7시반까지 입실해서 오후 1시가 될 때까지 그저 멍~하니 대기해야했습니다. 내년에는 대기시간에 가져온 자료를 볼 수 있을지 모르니 챙겨가도록 하되, 올해처럼 금지당할 수도 있으니... 지루한 대기시간에 잠을 자거나 가져온 간식을 먹으며 버틸 수 있도록 해야합니다. 저는 자려고 노력했는데 대기시간이 너무 길어서 명상을 했습니다.ㅎ... 아 그리고 조금 추웠습니다!!! 핫팩 많이 챙겨가세요.서울대는 배경지식의 풍부함이 중요한 것이 아닙니다. 물론 어느정도 있으면 좋겠지만, 가장 중요한 것은 논리적으로 답변을 구성하는 연습입니다. 즉 답과 (제시문에서 찾은)근거를 연결지어 논리성을 만드는 연습이 가장 중요"}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"서울대학교","dept":"원자핵공학과","jeonhyeong":"학생부종합(지역균형전형)","method":"서류 기반, 면접관 2명, 2단계 30%, 10분","notes":"생각보다 준비한 대로 안 나왔음. 인성 관련된 내용을 주로 대비했는데 전공적합성을 주로 물어봄. 첫 질문을 매끄럽게 답하지 못해 면접관이 전공의 기초와 심화 사이의 어중간한 내용을 질문했음. 첫 질문을 매끄럽게 답하는 것이 중요하다 생각됨.","qa":[{"q":"지원동기가 어떻게 되나요?","a":"2학년 동아리 시간에 이중슬릿 실험으로 실험 설계에서 주변 환경과 변인 통제의 중요성을 배웠고, 3학년 자율 주제 탐구 활동에서 핵융합에서의 전기에너지 생산을 탐구하며 블랭킷의 역할과 중요성을 알게 됨. 서울대는 우리나라에 단 하나뿐인 구형 토카막 장치 VEST를 소유하고 있기에 직접적인 실험, 연구가 가능함. 서울대에 진학하여 핵융합 분야의 전문가로 성장하고자 함."},{"q":"블랭킷에 대해 탐구했다고 했는데 역할과 중요성을 말해 보세요.","a":"블랭킷의 역할에는 3가지가 있는데, 첫째는 핵융합 원료인 삼중수소 생산임. 블랭킷 내부에서 리튬과 중성자를 반응시켜 삼중수소를 생산함. 둘째, 차폐제의 역할을 함. 핵융합 과정에서 나오는 미량의 방사능을 차폐해줌. 셋째, 중성자의 운동에너지를 열에너지로 변환해 줌. 중성자의 운동에너지를 열에너지로 바꾸어 외부 열기관을 통해 전기에너지를 생산하는 것으로 알고 있음. 탐구하며 사소하다고 생각한 부품이 상당히 중요하다는 것을 알게 됨."},{"q":"2학년 독서 시간에 중국의 EAST와 한국의 KSTAR를 비교하는 신문을 작성했다 했는데 관련 내용을 말해 보세요.","a":"EAST와 KSTAR는 주력 연구 분야가 다름. 중국은 전자 플라즈마의 유지에 주력하고 있고 우리나라는 이온 플라즈마 유지를 주력으로 연구하고 있음. 이처럼 각국의 다양한 분야의 연구 결과를 공유하고 함께 연구하여 ITER 프로젝트를 완수하는 것이 중요하다 생각함."},{"q":"융합과학 시간에 무엇을 배웠나요","a":"1학기에 걸쳐 2가지 주제로 탐구활동을 진행함. 토카막에서의 전자기장의 역할과 JET의 해체와 의의에 대해 탐구함. 토카막에서 용기 내부를 손상시키지 않고 플라즈마를 진공용기 내부에 띄어서 운전하기 위해 초전도 자석으로 자기장을 형성함. JET 해체의 힘든 점은 핵융합 실험 과정 중 발생한 방사능을 세척하는데 오래 걸린다는 것이고 JET 해체의 의의는 이후의 ITER프로젝트에 JET부품을 재활용 가능하다는 것임."},{"q":"가장 좋아하는 과학 과목은?","a":"물리학1 과목이 논리적으로 이해 가능해서 좋았음. 토카막 내에서 플라즈마의 운동을 이해하는 것이 힘들었는데, 물리 시간에 자기장 내에서 하전 입자의 운동을 배우며 더욱 깊게 이해할 수 있었음."},{"q":"핵융합 원료가 무엇이며 생산 방법을 말해보세요.","a":"중수소와 삼중수소, 이외에도 붕소 등 다양한 원소를 쓰는 것으로 알고 있음. 중수소는 해수에서 추출 가능하고, 삼중수소는 주로 리튬과 중성자의 반응으로 얻을 수 있는데, 이 리튬을 광산이나 해수에서 추출할 수 있음. 또한 최근에 이산화탄소 플라즈마를 이용해 해수에서 리튬 추출률을 약 3배 정도 향상시켰다는 연구 결과도 있음."}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"서울대학교","dept":"인문계열","jeonhyeong":"학생부종합(기회균형특별전형-사회통합)","method":"생기부 기반 면접 10분","notes":"면서 봐주셨던 분이었습니다. 웃으면서 너무 어려운 질문 던지셔서 좀 힘들었어요.질문이 정말 예상치 못하게 나왔어요. 저는 칸트를 좋아해서 말한 게 맞지만 생기부에 칸트 내용이 하나도 없는데 계속해서 질문하시는 걸 보니 어쭙잖게 좋아하는 척을 하면 안 될 것 같다고 느꼈습니다. 생기부에 있는 활동을 다 설명할 수 있는 건 당연하고, 생기부 외에 지원동기에서 말할 내용도 잘 준비하셔야 될 것 같아요.입실시간 지나면 수험표, 신분증, 물 빼고 전부 다 가방에 넣어서 복도에 줄지어 놔뒀어요. 그리고 면접 보는 방은 대기실 바로 앞에 있어서 부르면 나와서 면접 보고 바로 짐 챙겨서 나갔어요.","qa":[{"q":"반갑습니다. 자율이나 동아리 활동 중에서 기억에 남는 게 있으면 말해줄래요?","a":"2학년 동아리 활동에서 이주민에 관한 책을 읽고 난민 출신 강사분을 초청해서 북토크 한 내용 설명."},{"q":"학생은 난민 수용에 찬성하는 입장인 거네요? 그러면 난민 수용에 반대하는 사람들은 어떻게 설득할 수 있을까요?","a":"인도주의적 측면을 강조할 수도 있지만 난민이 한국에 정착함으로써 경제적인 측면에 기여할 수 있음 설명."},{"q":"학생이 이렇게 사회 문제에 관심 많은 거 알겠습니다. 여기 왜 지원했나요?","a":"사회 문제에 관심을 가지면서 살아오다가 윤리 과목을 접하고 철학이 단순한 사색이 아니라 보편적 가치와 존엄성 실현에 큰 역할을 할 수 있음을 알게 되면서, 더 공부하고 알아가면서 사회에 기여하고 싶다는 내용."},{"q":"그럼 어떤 사상이나 철학자를 보고 그런 생각을 했나요?","a":"칸트의 인간성 정식 내용 설명."},{"q":"인간성 정식이 사회 문제 해결에 기여할 수 있다는 건가요? 인간성 정식에서 인격을 수단만으로 대하는 것과, 동시에 목적으로 대한다는 것의 의미를 사회 제도와 연관지어서 설명할 수 있나요?","a":"수단만으로 대하는 제도와 목적으로 대하는 제도를 각각 사례를 들어가면서 설명함."},{"q":"그러면 칸트 말고 다른 사상이나 철학자를 법이나 사회 제도를 만드는 것과 연결지어서 설명해 보세요.","a":"공리주의와 입법 연관지어서 설명."},{"q":"(8분 정도 지난 시점. 옆에서 듣고만 계시던 교수님께서 질문하심) 책임윤리 뜻이 뭐예요?","a":"(아는 게 요나스밖에 없어서 요나스를 설명하려고 함)"},{"q":"아니아니 요나스 말고, 학생이 생각하는 책임윤리가 뭐죠?","a":"(당황하고 횡설수설 답해서 기억이 안 남)"},{"q":"그렇군요. 요나스와 칸트를 비교해 볼 수 있겠나요?","a":"못하겠다고 했음."},{"q":"그럼 학생이 생각하는 책임윤리의 정의가 그런 거라면, 그것의 대(對)가 되는 사상이나 철학자가 있으면 말해 줄 수 있어요? 이건 고등학생 수준에서는 좀 어렵죠?","a":"이것도 답변 못 함."},{"q":"(1분 남았다는 노크 소리 들림) 이쯤 하고 마지막으로 학생이 하고 싶은 얘기 있으면 하고 면접 마치도록 할게요.","a":"준비했던 말 하고 나옴.면접관들이 굉장히 편안한 분위기로 진행하셨어요. 표정을 일부러 굳히지도 않으시고, 쭉 무표정이었던 분과 웃으"}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"서울대학교","dept":"인문계열","jeonhyeong":"학생부종합(지역균형전형)","method":"전체 지원자를 여러 개의 조로 나눠 진행 , 8시30분까지 입실, 입실 후엔 준비한 대본 못 봄면접은 10분씩 진행","notes":"‘내가 진로가 이것이니까 이것을 중심으로 질문을 계획하면 되겠지?’ 라는 안일한 생각으로 면접에 임하면 안됩니다. 내가 제일 준비 안한 것이 질문으로 깊게 파고들 수 있는 것이 면접입니다. 자신의 생기부에 있는 내용들을 모두 꼼꼼히 분석하고 준비하세요. 논리적 허점이 보이면 바로 지적하고 비판하는 것이 서울대학교 면접인 것 같습니다.","qa":[{"q":"프로이트와 아들러의 교육 심리에 대해 조사했었는데, 이들의 주장에 대해 말해보세요","a":"네, 프로이트는 무의식에 잠재되어 있는 욕구를 해소하기 위해 교육심리치료가 필요하다고 주장했습니다. 성장기 아이들은 자라면서 집중되는 욕구가 신체 부위를 이동하면서 달라지는데, 입이나 항문 등의 신체 부위에 집중되는 욕구를 적절히 해소해 주어 트라우마가 발생하지 않도록 도와주는 것이 중요합니다. 아들러는 무의식에 있는 잠재 의식을 끌어 올리는 프로이트의 주장과는 달리 타인에 대한 열등감으로 인해 발생하는 좋지 않은 감정을 잘 해소해 주는 것이 중요하다고 주장합니다. 타인과의 상호작용을 통해 적절하게 협력하고 경쟁하는 관계에서 열등감을 잘 해소하는 심리치료가 중요하다고 강조합니다."},{"q":"그렇다면 본인이 생각하는 교육심리치료란 무엇이 있다고 생각하시나요?","a":"(답변을 제대로 준비하지 못하여 또래와 함께 경쟁하고 소통하는 심리치료를 제시하였으나, 방안이 모호하여 추가 꼬리 질문을 계속해서 받았고, 실현 가능성이 있는지, 또래와 경쟁하는 것이 오히려 열등감을 유발시키는 것은 아닌지와 같은 논리적인 허점들을 지적당함)"},{"q":"사회 문화 시간에 공교육과 사교육이 격차를 줄이기 위해 공교육의 질을 높이는 것이 중요하다고 주장했는데, 공교육의 질을 높이기 위한 방안은 무엇이 있다고 생각하시나요?","a":"제가 제시하였던 공교육의 질을 높이기 위한 방안은 교육방송에 금전적인 지원을 통해 유능한 강사들이 모두가 들을 수 있는 교육방송에 많이 참여하여 교육의 질을 높일 수 있도록 노력하는 것이 중요하다고 생각합니다. 또한 디지털 교육 기술을 많이 보급하여 교과서를 편리하게 들고 다닐 수 있도록 하거나 여러 시청각적 이미지를 통해 수업의 이해를 돕는 것을 통한 교육이 공교육의 질을 높일 수 있는 방안이라고 생각합니다."},{"q":"과연 공교육에 지원을 많이 한다고 해서 유명하고 능력 있는 강사들이 사교육을 버리고 올 수 있을까요?","a":"(공교육의 질을 높이기 위한 방안 자체에 대한 답안을 준비하는 것이 마땅한 해결책이 생각나지 않아 허점을 지적당함, 이 질문에 대해 명쾌한 답을 내리지 못하고 우물쭈물한 기억이 남)"},{"q":"그렇다면 사교육 격차를 완화하기 위한 방안은 무엇이 있다고 생각하시나요?","a":"제가 공교육의 질을 높이기 위한 방안만 생각해서, 지금 현재 심화되어 있는 사교육 격차를 완화하기 위한 방안은 직접적으로 생각해 보진 못했습니다."},{"q":"밴드부장으로서 성취감 있었던 경험이 있었나요?","a":"밴드부장으로서 성취감 있었던 경험은 축제 무대에서 좋은 공연을 선보이기 위해 밴드부원들과 함께 악곡을 연습하여 음정과 박자를 개선하고 화합하고 조화로운 연주를 할 수 있게 노력하였고, 그 결과 축제 전 팀 2등이라는 성과를 보일 수 있어서 성취감이 있었던 것 같습니다."}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"서울대학교","dept":"재료공학부","jeonhyeong":"학생부종합(지역균형전형)","method":"생기부 기반 면접","notes":"","qa":[{"q":"초전도체에 관심이 많은거 같은데 어쩌다가 관심이 생기게 됐나요","a":"제 상식과 다른 현상이였기 때문입니다. 저는 이전에 입자는 온도가 낮을수록 운동을 적게하게 되어 전류가 흐르지 않을 것이라고 생각했는데 초전도체는 일정 온도 이하의 낮은 온도에서 전류가 더 잘 흐른다는 점 때문에 관심이 생기게 되었습니다."},{"q":"그러면 초전도체와 고체는 어떻게 전류가 흐르는 방식이 다른가요","a":"초전도체는 쿠퍼 전자쌍에 의해 전류가 흐르지만 고체는 자유전자의 운동에 의해서 전류가 흐른다고 알고 있습니다."},{"q":"SRAM과 DRAM의 차이를 설명할 수 있나요","a":"두 메모리는 정보를 읽고 저장할 수 있는 장치로 sram은 dram보다 더 속도가 빠르다고 알고 있습니다."},{"q":"베르누이 법칙과 운동량을 관련지어서 조사했다는데 어떤 내용을 조사한건가요","a":"베르누이 법칙이란 유체의 속도와 압력에 관한 내용입니다. 저는 운동량 또한 속도에 관련되어 있다는 점에 주목하여 유체의 질량, 속도, 압력에 대한 연관성을 조사했습니다."},{"q":"고등학교에서 공부를 하면서 어떤 과목이 더 관심이 있었나요","a":"저는 물리학인 것 같습니다. 물리학은 모든 과학의 기반이 되는 과목이라고 생각하기 때문입니다. 물리학을 공부하면 화학, 생명과학, 지구과학을 더 이해하기 쉬워지고 물리학이 모두 관련되어 있다고 느꼈습니다. 이러한 점 때문에 물리학에 더 관심이 있었던 것 같습니다."},{"q":"이 과에 지원한 동기가 뭔가요","a":"저는 소재를 연구할 수 있는 연구원이 되고 싶기 때문입니다. 이전에 화학을 공부하면서 원자의 구조와 배열에 따라 소재의 성질이 달라진다는 것을 알게 되었고, 이러한 점이 흥미로워 재료를 연구할 수 있는 재료공학과에 지원하게 되었습니다."}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"서울대학교","dept":"재료공학부","jeonhyeong":"학생부종합(지역균형전형)","method":"교수님 두 분과 일대일 면접, 면접 시간 10분","notes":"교수님과의 거리가 1~2미터 정도로 가깝습니다. 모의 면접 시 가까운 거리에서 연습하세요.전혀 긴장되는 분위기도, 압박하는 분위기도 아닙니다.대기 중에 어떤 자료도 볼 수 없습니다. 마음 편하게 대기하세요.","qa":[{"q":"재료공학부 지원 동기와 대학 오면 하고 싶은 거 이야기해 주세요.","a":"재료공학은 더 나은 재료의 개발을 통해 여러 환경문제와 사회문제에 솔루션을 제공하는 학문 분야로 알고 있습니다. 재료 개발을 통해 여러 환경문제와 그로 인해 나타나는 사회문제를 해결하여 노인, 장애인 등의 소수를 포함한 모든 사람이 건강하고 행복한 삶을 영위하는 데 기여하고 싶기 때문에 재료공학부에 지원하였습니다. 대학에 가면 제일 먼저 타 학과 학생들과 함께 연구하거나 프로젝트를 진행해 보고 싶습니다."},{"q":"그럼 친구들이랑 연구하고 싶은 관심 분야가 있나요?","a":"청정 에너지에 관심을 가지고 있습니다. 핵융합 발전이라든지, 태양광 발전 등에 재료공학이 기본이 되지만 재료공학만으로 가능한 게 아니기 때문에 타 학과와 협업을 말씀드렸습니다."},{"q":"타이탄호와 관련해서 여러 가지 계산을 하셨던데 간단히 설명해주세요","a":"해당 활동을 할 당시 물리학1에서 압력, 부피, 온도 관계에 대해서 배우고 있었습니다. 마침 타이탄호라는 잠수정이 내파를 당했다는 기사를 봤고 기사를 읽다 보니 수업 시간에 배운 내용으로 사고 당시 잠수정이 받은 압력이나 힘 등을 계산할 수 있겠다 생각했고 활동을 진행했습니다. 사고 당시 수심을 해저 3800미터로 예상하고 있고 수심이 10미터 낮아질 때마다 1기압씩 증가하므로 381기압 정도의 압력이 가해졌을 것이라고 정리했습니다. 이를 pa 단위로 바꾸면 4000만 정도가 됩니다. 타이탄호의 길이, 높이, 생김새를 바탕으로 겉넓이를 계산하니 15.75제곱미터가 나왔고 압력과 곱하니 사고 당시 6억 뉴턴 정도의 힘을 받았을 것이며 이는 항공모함 100대 그리고 반 친구 900만 명이 누르는 힘이라고 설명했습니다.(되게 재밌는 활동이었겠어요, 어떻게 숫자를 다 기억하고 계시네요?)"},{"q":"계산 과정을 지금 다시 분석했을 때 문제가 있다면?","a":"힘은 벡터값이기 때문에 상쇄가 되거나 할 것 같은데 그냥 공식에 대입해서 힘을 구하는 게 옳은지 묻고 싶습니다."},{"q":"그렇네요, 힘이 상쇄되었다면 잠수정이 왜 찌그러졌을까요?","a":"힘과 압력의 명확한 차이를 잘 모르고 있는 것 같습니다."},{"q":"미네랄과 정수과정에 관한 실험을 하셨네요, 설명해주세요.","a":"이 실험을 하기 전에 해수담수화 기술에 대해 조사한 적 있습니다. 해수담수화와 정수 모두 과정이 복잡하고 비용이 많이 든다는 문제가 있었고, 불필요한 물질만 흡착하는 소재를 개발할 수 있다면 과정을 단순화하고 비용을 절감할 수 있다고 생각했습니다. 간이 정수 키트 세 칸을 쌓아올리고 필터로 사용하는 재료를 모래, 활성탄, 마그네슘 조각으로 바꿔가며 소금물을 여과시켜 여과를 더 잘 시키는 소재를 찾고 싶었습니다. 10% 농도의 소금물을 부어 실험을 해보니 모두 9%정도로 나타났지만 동일한 재료로 다시 실험을 진행해도 값이 계속 달라졌기 때문에 유의미한 실험값은 아니라고 생각합니다.(아주 흥미롭네요.)"},{"q":"왜 실험 과정에 오차가 발생했을까요?","a":"가정용 염도계를 사용해 염도를 측정했습니다. 염도계는 소금물 속 Cl 음이온을 검출하는 전기전도 방식을 사용하기 때문에 마그네슘 조각과 반응해 MgCl2를 만들어 염도가 낮게 측정될 거라 기대했지만 충분히 반응할 만큼의 시간이 없었다고 생각합니다. 대학 진학 후에 원하는 결론을 얻기 위해 실험을 설계하는 법을 배우고 전문적인 장비를 가지고 실험을 다시 진행해 보고 싶습니다.(재밌는 실험이네요.)"},{"q":"화학 실험 동아리 와화학에서 이것저것 실험을 많이 했는데, 그래서 형광과 인광이 뭔지 설명해 줘봐요.","a":"제가 되게 재밌게 했던 활동이라 기억에 남습니다. 형광은 전자가 단일항의 들뜬상태에서 단일항의 바닥상태로 전이할 때 발생하는 빛이고, 인광은 전자가 삼중항의 들뜬상태에서 단일항의 바닥상태로 전이할 때 발생하는 빛입니다."},{"q":"그래서 두 개의 차이가 뭐죠?","a":"형광은 전자가 플립없이 떨어지기 때문에 인광에 비해 더 잦은 빈도로 일어나고 따라서 허용된 전이라고 한다고 알고 있습니다. 인광은 삼중항의 전자가 바로 떨어질 수 없어서 스핀 방향을 바꾸며 떨어져야 하기 때문에 드물게 일어나고 따라서 금지된 전이라고 합니다. (금지된 전이라는 용어까지 아시네요ㅎㅎ)"},{"q":"너무 물리만 물어봤네요 화학에서는.... 생분해 플라스틱, pla에 대해 조사했네요. 설명해 볼래요?","a":"pla는 락트산, 그러니까 젖산이 에스터 결합을 해서 여러 개가 연결돼 있는 사슬 형태의 물질입니다. 기존의 플라스틱은 c-c 결합을 하고 있어서 미생물에 의한 분해가 힘들지만 미생물이 에스터 결합은 잘 끊을 수 있어 생분해가 된다고 알고 있습니다."},{"q":"그러면 에스터랑 이써의 차이를 알아요?","a":"죄송하지만 다시 말씀해 주실 수 있을까요?"},{"q":"이써요 이써 (화학식도 불러주심)","a":"죄송합니다. 아직 일반화학, 유기 무기 화학은 깊이 공부해 보지 않아서 모르는 것 같습니다."}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"서울대학교","dept":"조선해양공학과","jeonhyeong":"학생부종합(지역균형전형)","method":"생기부 기반 면접 10분","notes":"면접시간이 생각보다 많이 짧음. 학과에 대한 정보보다는 생활기록부 기반으로 질문함.","qa":[{"q":"지원 동기가 뭐예요?","a":"저는 조선해양공학 기술과 인공지능 기술을 융합하여 선박을 가장 경제적이고 안정적으로 운행하는 알고리즘을 개발하고 싶습니다. 따라서 서울대학교 조선해양공학과에서 배우는 조선해양기계학습을 성실히 이수하여 조선해양공학에서 사용하는 인공지능 기술에 대해 배우고 싶고, 또한 서울대학교 조선해양공학과 딥러닝연구실에서 현재 경제적인 운송을 위한 날씨 경로 개발과 해안지역 안전 항해를 위한 강화학습 모델을 개발하는 프로젝트를 진행중이라고 알고 있는데, 저도 이러한 프로젝트를 통해 저의 목표에 한 발짝 더 다가가고 싶어서 지원하게 되었습니다."},{"q":"조선해양공학과 인공지능 기술을 결합하는 것은 다른 학교에서도 할 수 있는 것 아닌가요?","a":"네, 하지만 현재 서울대학교 딥러닝연구실에서 진행하고 있는 프로젝트가 저의 목표와 관련되어있기 때문에 서울대학교에 지원하게 되었습니다."},{"q":"수학에서 가장 좋아하는 분야가 어디예요? 그 이유는?","a":"미분을 가장 좋아합니다. 왜냐하면 변화량을 통해 미래를 예측한다는 것이 흥미로웠기 때문입니다."},{"q":"적분이 그래프의 면적을 의미하는 이유가 뭘까요? 부피도 되지 않을까요?","a":"저희가 다루는 적분은 2차원 좌표평면에서 존재하는 1차원 그래프를 적분하는 것이기 때문에 2차원 면적이 나온다고 생각합니다."},{"q":"그럼 왜 면적이 나올까요? 면적의 절반이 나올수도 있고 면적의 1/5가 나올수도 있는 것 아닌가요?","a":"(제대로 답변 못함)"},{"q":"1학년때 도서관 활동에 많이 참여했네요. 참여한 이유가 뭘까요?","a":"고등학교에 올라오면서 학업으로 인해 책을 읽을 시간이 줄어들 것 같아 도서관 행사에 참여해서 조금이라도 책을 읽을 기회를 늘리고자 했습니다."},{"q":"생활기록부에 약학에 관련된 내용이 많네요, 약학에서는 인공지능을 어떻게 활용할 수 있을까요?","a":"약학에서 구조 활성의 정량적 관계를 이용하는데, 이는 분자의 구조에 따른 특성을 예측하는 방법입니다. 이를 통해 각각의 분자들의 특징에 따른 효과를 인공지능으로 예측하고 의약품을 개발 할 수 있습니다."},{"q":"그런거는 인공지능이 아니더라도 할 수 있지 않나요?","a":"단백질은 고분자이기 때문에 여러 분자들의 구조를 이해하고, 각각의 구조에 따른 특성을 예측해야 할 뿐만 아니라 여러 분자들이 섞이면서 나오는 새로운 특징들을 이해해야 하는데 이를 하기 위해서는 인공지능이 필요하다고 생각합니다."},{"q":"그럼 무슨 인공지능 모델을 사용해야 할까요? 아는 인공지능 모델이 있을까요?","a":"(모른다고 함)"},{"q":"DNA 염기서열 분석법에 대해서 보고서를 작성한 적이 있네요, DNA 염기서열 분석법에 대해 간단히 설명할 수 있을까요?","a":"네 DNA 염기서열 분석법 중 제가 가장 인상깊게 조사했던 파이로시퀀싱에 대해 설명해보겠습니다. 파이로시퀀싱은 DNA의 염기를 투입했을 때, 염기가 DNA에 결합을 하지 않으면 효소에 의해 분해되고, 결합을 하게 된다면 발광 효소로 인해 빛이 나는 방식으로 염기를 분석하는 방법입니다. 이 과정에서 생명과학적 지식들과 화학적 지식들이 같이 사용된다는 점에서 가장 재미있었던 것 같습니다."},{"q":"DNA 염기서열 하면 유전자 가위가 생각나는데, 유전자 가위에 대해 어떻게 생각하나요?","a":""},{"q":"유전자 가위의 윤리적인 측면을 말씀하시는 걸까요?","a":""},{"q":"유전자 가위의 윤리적인 측면이나 기술적인 측면이나 아무거나 말해보세요.","a":"네 유전자 가위의 기능적인 측면에서는 현재 치료할 수 없던 유전병들을 유전자 가위 기술 한 번에 치료한다는 점에서...(면접끝남)"}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"서울대학교","dept":"첨단융합학부","jeonhyeong":"학생부종합(기회균형특별전형)","method":"총 10분, 3분 공통문제 질문 후 7분 서류 기반 면접 진행서류 기반 면접은 학생의 생기부에 나오는 내용을 바탕으로 하므로 학생마다 질문의 차이가 있기 때문에 본 면접 후기에는 공통 질문만 기록했습니다.","notes":"문을 받게 되니 답변이 간결하되 핵심을 담고 있어야 합니다. 과정을 너무 길게 이야기하기보단 결과를 우선 중심적으로 이야기하고 추가 질문이 들어온다면 그때 더 자세한 설명을 하는 것을 추천드립니다. 자신의 생기부에 대한 확실한 숙지를 하는 것은 기본 중의 기본입니다. 진로, 자율, 동아리 내용뿐만 아니라 교과목 활동에 대한 확실한 이해 역시 요구됩니다. 마지막으로 팁을 드리자면, 서울대는 지적역량뿐만 아니라 리더십과 인성도 중요시하는 학교입니다. 답변을 할 때 이런 요소들도 챙기며 연습하는 것이 도움될 것입니다.","qa":[{"q":"사회적 문제를 과학 분야 간 융합으로 해결한 사례를 말해보세요. 개인적인 사례도 좋고 역사적인 사례도 좋습니다.","a":"우주쓰레기에 대해 말씀드리려 합니다. 우주쓰레기를 기존에는 포획하는 방식으로 해결하곤 했는데, 그 방식이 충분하지 않다고 판단한 연구자들은 새로운 방식으로 자가포식 메커니즘을 이용한 로켓을 개발했습니다. 생명과학에서 다루어지는 자가포식 메커니즘을 우주공학 분야의 로켓과 융합해서 우주쓰레기라는 사회적 문제를 해결한 사례라고 생각합니다."},{"q":"자가포식 메커니즘을 이용한 로켓에 대해 더 자세하게 설명해주세요.","a":"자가포식 메커니즘을 이용한다는 것은 로켓이 제 임무와 역할을 다했을 때 자가포식을 통해 소멸하게 되는 것을 말하는데, 생명체 내의 세포가 제 역할이 다하면 자가포식을 통해 사멸하는 것과 유사하다고 알고 있습니다."},{"q":"첨단융합학부는 분야 간 융합이 중요한 학부입니다. 융합 분야의 연구자로서 가져야 할 자질을 하나 말해보세요.","a":"저는 융합 분야 연구자로서 가져야 할 자질이 ‘이해’라고 생각합니다. 연구를 함께 진행할 때 어떤 분야가 어떤 부분에 적용되었을 때 가장 효율적인지에 대한 확실한 ‘이해’가 있어야 하고, 다른 분야의 연구자들과 서로를 ‘이해’하는 능력이 있어야만 융합을 통한 최대의 시너지를 얻는 것이 가능하기 때문입니다."},{"q":"서울대학교 첨단융합학부에 진학한다는 것은 미래의 인재가 되기 위한 과정을 거친다는 것입니다. 자신이 인재의 자질을 가지고 있다는 것을 보여주는 근거를 제시해보세요.","a":"제가 미래의 인재가 될 수 있다는 것은 제가 가진 아이디어를 말씀드림으로써 보여드릴 수 있다고 생각합니다. 저는 서울대학교 첨단융합학부에 진학해서 뉴로모픽 반도체와 양자컴퓨터의 융합 기술을 개발하려는 목표를 가지고 있습니다. 제 목표를 실현한다면 전력 효율의 증가를 통해 인류의 삶의 질을 향상할 수 있을 것입니다. 이런 아이디어와 목표를 지니고 연구에 임할 것이라는 다짐이 인재로서의 제 자질을 보여준다고 생각합니다.서울대학교 기회균형 면접은 10분 정도로 비교적 짧게 진행됩니다. 그중 3분은 공통 질문, 7분은 서류 기반 질"}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"서울대학교","dept":"컴퓨터공학과","jeonhyeong":"학생부종합(지역균형전형)","method":"개별 / 대면 / 서류기반 면접 / 평가자 2:1 / 면접시간 10분 내외","notes":"면접관 두 분 모두 교수님 같으셨음. 거리가 약 1m 정도로 매우 가까움.전공 내에서 지망하는 세부 전공과 관련된 질문은 나오지 않았음.","qa":[{"q":"블록체인과 nft 원리가 뭐에요?","a":"네트워크의 거래 내역을 담은 장부를 네트워크 참여자들에게 나누어주어 보안성을 높인 기술입니다."},{"q":"왜 ‘체인’이라는 이름이 들어갈까요?","a":"아 거래를 담은 블록이 서로 연결돼서 체인의 형태를 띠어서 그렇습니다."},{"q":"왜 보안성이 높은가요?","a":"각 참여자가 그 체인을 공유하고 있기 때문입니다."},{"q":"음…그건 아닌데","a":"아 블록을 악의적으로 조작하면 앞 뒤 체인과의 링크가 끊어지게 돼서 다른 분기로 진입하기 때문에 그렇습니다."},{"q":"음... 해시 함수의 특징 때문에 그런 건데 나중에 공부해봐요.","a":"넵 알겠습니다"},{"q":"CoT와 관련된 탐구가 있는데, CoT가 뭔가요?","a":"CoT는 LLM에 단계적 사고를 하도록 하는 프롬프트입니다.그 탐구는, 인공지능 기초 과목에서 비버 챌린지라는 컴퓨팅 사고력 문항을 풀이할 때 올바른 답이 나오지 않았던 경험을 계기로 진행했습니다. 수능 수학 문제, 비버 챌린지 문제에 대해 기본 텍스트 프롬프트, CoT, 텍스트와 이미지를 활용한 멀티 모달리티 프롬프트를 사용했습니다. 결과적으로 수능 수학 문제는 CoT, 비버 챌린지 문제는 멀티 모달리티 프롬프트가 좋은 성능을 보였습니다. 수능 수학 문제는 인간의 연역적 사고를 필요로 하기 때문에 CoT가 좋은 성능을 보였고, 비버 챌린지 문제는 상황에 대한 이해가 중요하기 때문에 이 이해를 돕는 멀티 모달리티 프롬프트가 좋은 성능을 보인 것으로 추측해 보았습니다."},{"q":"다익스트라 알고리즘이 무엇인가요?","a":"다익스트라는 그래프 분석 알고리즘인데, 분석하고자 하는 그래프의 가중치가 양수일 때 사용할 수 있습니다."},{"q":"뭘 구하려고 쓰는 알고리즘인가요?","a":"어…최단 경로입니다"},{"q":"이걸 구현할 때 힙 자료구조가 필요한데, 알고 있어요?","a":"아 힙이 쓰인다는 건 알았는데, 힙 자료구조는 몰라서 안 썼습니다. 추후 자료구조에 대한 강의를 듣고 공부하고 싶습니다."},{"q":"아...그럼 힙은 안 쓰고 다른 걸로 구현한 거네요?","a":"넵. 저는 파이썬으로 구현해서, 리스트를 사용해서 구현해 보았습니다."},{"q":"이건 어려운 알고리즘인데, 어디서 배웠어요?","a":"인공지능 수학 같은 공동교육과정에서 배웠습니다."},{"q":"수학 잘해요?","a":"네. 좋아합니다."},{"q":"그럼 어떤 과목을 제일 잘해요?","a":"문학입니다."},{"q":"어떻게 공부했어요?","a":"시나 소설에서 어떤 상황에서 생겨나는 화자의 마음을 탐구하는 것을 중점적으로 공부했습니다."},{"q":"왜 좋아해요?","a":"제가 하고자 하는 일이 인간의 지식을 인간의 사고로 옮기는 일인데, 이를 위해서는 멀티 모달리티로 된 지식을 벡터 공간으로 인코딩해야 합니다. 이 과정을 모든 사람들이 인정할 수 있도록 하려면 인간의 의식을 오래 담아온 인문학과 같은 문학이 큰 역할을 할 것이라 생각했습니다."}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"서울대학교","dept":"건설환경공학부","jeonhyeong":"학생부추천/지역균형","method":"학생부 면접 / 대기실에서 대기 후 순서에 따라 조별로 이동, 10분 면접 진행","notes":"면접 후 나오면 학교 선배인 척 말을 거는 이단 종교 신도가 많음","qa":[{"q":"우리 학과에 지원하게 된 동기가 무엇인지에 대해 구체적으로 좀 알려주세요","a":"저의 꿈은 정부 산하 부처에서 국토균형발전, 도시재생 등에 대해 연구하는 업무를 하며 우리 사회의 안전과 발전에 기여하는 것입니다. 2022년 수도권 대홍수 사태, 광주 인천 아파트 붕괴 사건 등을 보며 재해안전과 건설안전을 위해 필요한 것은 무엇일지 생각하게 되었습니다. 이후 BIM과 디지털트윈의 결합 등에 대해 연구하며 건설환경공학이 최첨단기술과 융합할 때 비로소 혁신적 해결방안을 마련할 수 있음을 알게 되었습니다. 또한 국토균형발전과 도시재생 등에 관한 기사를 접하고 건설환경공학이 우리 사회의 구조적 문제를 해결할 수 있는 학문이라는 점을 깨닫게 되었습니다. 저는 앞으로 혁신적 사고와 최첨단 기술을 융합하여 사회 안전과 발전에 기여하고 싶었기에 이 학과를 지원하게 되었습니다."},{"q":"3학년때 TBM 관련해서 한 탐구활동이 있던데, 이거에 대해서 한번 이야기해봐요.","a":"TBM은 우선 커터헤드를 회전시키면서 디스크 커터가 지반을 굴착합니다. 이후 이수 또는 굴착된 버력으로 챔버를 채워 막장압을 유지합니다. 그리고 굴착과 동시에 이렉터를 이용해 터널 벽면에 세그먼트를 설치하는 방식으로 작동됩니다. 여기서 저는 TBM 공법의 트렌드에 대해 조사하며 지름을 길게 한다는 초단면화, 빠른 굴진을 하는 초굴진화, 우리나라의 한강터널과 같이 터널의 길이를 연장하는 초장대화, 더 깊이 하는 대심도화 등에 대해 알아보았습니다."},{"q":"그러면 이 TBM 공법이 어떤 지반에 이용되는 것이 좋을지에 대해 알고 있는 것이 있나요?","a":"TBM 공법이 발파진동이 적어 안전성이 높고, 도심지에 근접하게 건설할 수 있다는 내용을 본 적이 있습니다. 그렇지만 그게 어떤 지반에 적용되는 것이 유리할까에 대해서 구체적으로는 제가 잘 모르겠습니다."},{"q":"과학분야에 관심이 많아서 1학년때 동아리를 한 것 같은데, 이거에 대해서 한번 얘기해주세요.","a":"네. 1학년 때 한 라온동아리는 토론동아리였습니다. 토론동아리에서 각종 주제에 대해 토론을 하며, 통일에 대한 찬반을 주제로 토론을 할 때 건설환경 분야와 접목해서 근거를 말한 적이 있습니다. 북한의 경우에는 기본적인 상수도, 그러니까 소방시설보다도 이 기본적 상수도 자체가 제대로 구축되어 있지 않고, 건물 같은 경우에도 내진설계가 되어 있지 않고 안전 측면에서도 부실한 건물들이 많은 상태입니다. 그렇기에 전면적인 도시 재개발이 필수적일 것이고, 또 통일이 되면 대륙을 연결하는 철도가 구축되어 물류 운송에도 적합할 것입니다. 그래서 그런 과정에서 또 우리 토목공학의 최첨단 기술 등을 접목시키며 많은 발전을 이뤄낼 것입니다. 이런 부분에 대해 이야기했습니다."},{"q":"네. 보면 국토균형발전에 대해 탐구를 많이 한 것 같은데, 국토균형발전이 왜 필요한 걸까요?","a":"우리나라의 경우에는 전국에서 소멸 위험지역, 그리고 20세에서 39세의 여성에 대한 65세 이상 여성의 비율을 나타낸 수치가 0.5를 넘지 않는, 그런 지역이 절반이 넘습니다. 이렇게 지역 소멸이 일어나며 수도권 인구집중이 나타나고, 그러면 집값 상승, 경쟁 심화 등으로 인해 저출생, 일자리 부족과 같은 부가적인 사회문제까지 이어지게 되기 때문에 지역에 대한 균형을 유지하는 것이 헌법적 가치까지 고려했을 때에도 필수적이라고 생각합니다."},{"q":"그렇다면 지원자가 가지고 있는 단점이다 싶은 것. 장점은 많을 거 아니에요. 단점이다 싶은 것에는 어떤게 있나요?","a":"지금은 많이 극복이 된 단점이지만 우선 저는 선천적으로 체력이 약한 경향이 있었습니다. 1학년 때는 많이 느끼지 못했는데 2학년이 되며 잠도 많아지고, 이런 체력 문제가 드러나게 되면서 이걸 어떻게 해결할까에 대해 많이 생각해 보았습니다. 저희 학교같은 경우에는 체대입시를 준비하는 친구들도 많이 있었습니다. 그래서 그 중 한 친구에게 체력을 기르기에 좋은 게 뭐냐 물어봤더니, 그냥 뛰는 게 가장 좋다라고 하였습니다. 그래서 그 이후로 그 친구들과 함께 소화도 시킬 겸, 점심시간마다 운동장을 몇 바퀴씩 뛰고, 이렇게 하다보니 지금은 정말 많이 좋아졌습니다."},{"q":"그러면 지원자가 가장 중요하게 생각하는 가치, 그런게 있을까요?","a":"저는 능력과 인품을 겸비한 사람이 되자라는 것을 제 좌우명으로 삼고 있습니다. 예를 들면 세종대왕 같은 경우에도 훈민정음을 창제하실 때, 말하고자 하는 바가 있어도 뜻을 펼치지 못하는 백성들을 가엾이 여기는, 그런 측은지심으로 훈민정음을 창제하였다고 하셨습니다. 이렇게 제가 가진 능력과 인품이 결합해 시너지를 이룰 때 비로소 우리 사회에 이바지하는 그런 훌륭한 인물이 될 수 있다고 생각합니다.전공질문보다 공통질문의 비중이 다소 높았음, 교수님들이 학생들의 생기부를 꼼꼼히 숙지특이점하진 않은 듯 했음.합/불 분석최초합아쉬운 점"}],"naesin":"1.03","result":"최초합격","resultNote":"최초후보순위","suneung":"최저충족","type":"일괄합산( ) 단계형( ○ ) 【1단계】 서류100(3배수) 【2단계】 1단계70+면접30","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"서울대학교","dept":"기계공학부","jeonhyeong":"학생부종합전형/ 기회균형특별전형(사회통합)","method":"서류 기반 면접 면접 대기실에 입실을 완료한 후 수험생 확인 및 안내사항을 전달받음. 이후 / 면접실로 이동하여 서류 기반 면접을 진행함.","notes":"서울대 입학 웹진 ‘아로리’ 확인!!","qa":[{"q":"지구과학 실험, 기하, 인공지능 수학을 선택했는데 왜 선택했나요? (남)","a":"지구과학 실험을 선택한 것은 천체 물리학에 관해서는 어려서부터 관심을 가지고 있었고, 기하는 물리학, 수학과 함께 항공우주공학에 필수적으로 사용되는 학문이어서 선택했습니다."},{"q":"여기는 기계관데요? (남) (웃음, 분위기 환기?) 그렇다면 왜 기계공학과에 지원하게 되었나요? (여)","a":"저는 고등학교 3년 동안 배우는 지식은 대학 수준의 지식에 비하면 아주 기초적인 수준의 지식이라고 생각했습니다. 평생 공부하게 될 전공을 고등학교 3년의 얕은 경험을 기반으로 선택하는 것이 부담스럽게 느껴졌고, 보다 폭넓은 분야를 다루는 기계공학과에 지원하여 공부하는 것이 앞으로의 저의 진로 선택을 비롯해 저에게 도움이 될 것이라 판단하였습니다."},{"q":"(3학년 물리학 세특 중 레이놀즈 수에 관한 탐구 내용) 레이놀즈 수가 무엇인가요? (남)","a":"층류, 난류와 같은 유체의 유동을 구분하는 무차원 수라고 알고 있습니다."},{"q":"그렇다면 실제 난류의 예시는 어떤 것이 있을까요? (남)","a":"수도꼭지에서 물을 강하게 틀면 물이 불규칙적으로 층을 이루지 못한 채 흐르는 것이 있습니다."},{"q":"그러면 층류에는 어떤 것이 있죠? (남)","a":"아까와 같은 예시를 들어 설명하자면, 수도꼭지에서 물을 약하게 틀 때 물이 층을 이루어 흐르는 것이 있습니다."},{"q":"1학년 동아리 활동 시간에 가장 기억에 남았던 것은? (여)","a":"양자 컴퓨터 관련 책을 읽고 토론한 것이 가장 기억에 남았습니다."},{"q":"어떤 내용으로 토론했는지는 기억이 나나요? (여)","a":"음.. (기억이 잘 안 났음) 양자 컴퓨터의 발전이 인류에게 꼭 도움이 되는지에 관해 토론했습니다."},{"q":"혹시 본인은 어떤 생각인가요? (여)","a":"음... 양자 컴퓨터의 도입은 많은 분야에서 빠르게 시간을 절약할 수 있게 해주어 도움이 되었지만, 너무 빠른 것은 삶의.... 꼭 필요한 것들을 놓치게 할 수 있어..있다고 생각합니다."},{"q":"학교 생활하면서 어려웠던 것이 있나요? (여)","a":"네. 저는 중학교 때 인간관계에 관한 회의감으로 방황했던 적이 있습니다. 밖에서는 항상 타인의 시선을 의식에 스트레스 속에서 살았습니다. 그러던 중 아들러 심리학이 담긴 미움받을 용기라는 책을 알게 되었습니다. 이 책에서 제가 가장 기억에 남았던 것은 내가 통제할 수 있는 것과 없는 것을 구분하라는 ‘과제의 분리’였습니다. 타인의 의식은 통제할 수 없기에 그것에 얽매이지 말고 자유롭게 살아가라는 내용이었습니다. 저는 고등학교에 올라와서도 항상 이 책과 함께 생활하였고, 이전과 같은 강박증에서 벗어날 수 있었습니다."},{"q":"그렇다면 왜 유체는 층을 이루어 흐르죠? (남)","a":"흐르는 유체의 중심에서 바깥쪽으로 갈수록 속도가 점점 느려지는데 이러한 속도 차이 때문에 유체가 층을 이루어 흐른다고 생각합니다. Ÿ 입학사정관 남녀 두 분이 면접을 진행하셨음. 위의 질문 순서는 다 기억이 나지는 않아 대략적인 순서임. 두 분이 번갈아서 진행하며, 자신이 했던 활동에 대한 꼬리질문이 핵심.Ÿ 보통의 면접 준비 할 때의 예상 질문같은 것은 거의 직접적으로 물어보지 않았음. 아로리에도 나와있는 것이지만 서울대 면접관들은 준비된 답변을 싫어함. 구체적으로 예상하지 못한 질문에는 웅얼거리며 답변하지 못한 채 예상 질문에 대해서만 기계적으로 뱉어내는 것을 싫어함. 학과에 대한 지원동기, 이후의 진로계획, 선택과목의 선택 이유 등에 관해서특이점는 잘 정리해 놓고, 나머지는 예상 질문과 답변 암기가 아니라 생활 기록부에 나와있는 활동들을 돌아보며 구체적으로 꼼꼼히 여러번 복기하는 과정을 거치면 됨.Ÿ 10분 동안 아주 많은 것을 물어볼 수는 없고, 본인이 갔던 면접은 지원자들에게 마지막으로 하고 싶은 말, 1분 자기소개 같은 것은 전혀 물어보지 않음. 순식간에 시작해서 10분이 지나는 즉시 끊고 다음 지원자가 들어갔음. 결론은 생기부에 적혀있는 자신의 활동들에 대해 잘 ‘숙지’한 채 (답변을 달달 외우는 것은 비추천) ‘주요’ 예상 질문에 대한 답변을 준비하면 됨. 합/불 분석아쉬운 점말을 더듬은 것."}],"naesin":"1.41","result":"최초합격","resultNote":"최초후보순위","suneung":"최저기준없음","type":"일괄합산( ) 단계형( ○ ) 【1단계】 서류평가 100 (2배수) 【2단계】 1단계 성적 70 / 면접 30","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"서울대학교","dept":"기계공학부","jeonhyeong":"학생부종합/지역균형","method":"생기부기반 / 2명의 면접관과 10분간 면접","notes":"","qa":[{"q":"간단하게 지원동기와 자기소개 해주세요","a":"다양한 기계장치와 그중에서도 엔진에 관해 큰 흥미를 느껴 기계공학부에 지원하였습니다. 어릴 적부터 비행기에 대한 관심이 높아 중학교 고등학교를 거치며 비행기에 대한 탐구를 진행했고 비행기에 탑재된 여러 기계장치들과 엔진에 대해 알게 되었습니다. 이후 ‘무거운 비행기가 어떻게 하늘을 날까?’ 라는 호기심이 ‘저런 섬세한 기계장치들이 모여서 하늘을 난다는 장엄한 일을 하는구나’라는 충격이 되었고, 기계공학에 자연히 이끌리게 되었습니다. (긴장해서 자기소개를 까먹었습니다.)"},{"q":"자기소개도 해주세요","a":"저는 학업에 대한 끈기와 협업능력을 가진 지원자라고 생각합니다. 학교생활을 하며 이해가 안되는 부분에 대해 넘기지 않고 끈기있게 탐구하여 습득하는 경험을 많이 하였고, 리더의 역할을 자주 맡으며 다양한 성격의 동료와 성공적으로 협업하는 경험을 하였습니다. 이러한 경험을 통해 더욱 그러한 역량을 기르는 데에 노력했습니다.(생기부 기재내용을 바탕으로 지원동기와 자기소개 준비하였습니다.)"},{"q":"생활기록부를 보니 1학년때 종이비행기에 대한 강연을 듣고 활동을 진행하신거 같은데, 어떤 활동을 하셨나요?","a":"종이비행기 강연자분이 오셔서 종이비행기를 비롯하여 물체가 하늘을 나는 원리에 대해 알려주시고 그것을 바탕으로 종이비행기의 비행을 설계하는 방법에 대한 강연을 들었습니다. 이후 강연 내용을 바탕으로 종이비행기를 멀리 날아가는 목적으로 직접 제작하여 날려보는 활동을 진행했습니다."},{"q":"대륙간탄도미사일이나 종이비행기가 멀리 날아가게 할 수 있는 방법이 뭘까요?","a":"우선 대륙간탄도미사일과 종이비행기의 가장 큰 차이는 동력이라고 생각합니다. 대륙간탄도미사일에는 엔진이 탑재되어 비행중에도 지속적으로 출력을 얻을 수 있다고 알 수 있습니다. 하지만 종이비행기는 던지는 순간 손을 떠날때 주어지는 동력만으로 비행을 합니다. 때문에 비행에 관여하는 다양한 요인중 균형에 관한 부분이 멀리 날아가게 하는 부분에 있어 중요하다고 생각합니다. 직선 비행의 가정하에 좌우에서 작용하는 중력과 양력 항력 추력이 같아야 할 것이고 이를 통해 우선적으로 무게중심과 공력중심이 비행방향의 중심축에 위치해야 합니다. 이러한 과정으로 균형을 통해 동력이 헛되이 소비되지 않게 하는 것이 멀리 날아가게 하는 방법 중 하나라고 생각합니다."},{"q":"지원자의 생활기록부를 보면 항공쪽에 대한 관심이 높은것 같은데, 서울대학교에는 항공우주공학과가 따로 있단 말이죠? 왜 기계공학부에 지원하셨는지 말해줄 수 있을까요?","a":"앞서 말씀드린 대로 비행기에 대한 탐구를 진행하며 비행기에 탑재된 다양한 기계장치와 엔진에 대한 흥미가 높아져 그러한 기계에 대해 더 자세히 공부하고 싶어 기계공학부에 지원하게 되었습니다. 큰 중량의 물체가 하늘을 난다는 것에 대한 경외감과 호기심이 그것을 이루게 하는 기계장치에 대한 깊은 인상으로 이어졌고, 중학교 고등학교에서도 배우는 간단한 과학적 지식을 바탕으로도 복잡하고 효율적인 기계를 설계 제작하는 기계공학에 대해 매료되어 기계공학부를 지원하게 되었습니다."},{"q":"답변을 들어보니 엔진에 대한 관심이 높으신 것 같은데 엔진과 관련하여 10년 뒤에는 어떤 일을 할 것 같고 어떤 일을 하고 싶나요?","a":"새로운 매커니즘의 엔진을 개발하고 싶습니다. 물론 기존의 엔진에 대해서도 다양한 연구 개발을 수행할 것 같습니다. 하지만 기존 엔진의 메커니즘 초월하는 새로운 엔진을 만들어 보고 싶습니다. 예를 들면 현재 열심히 개발 중인 핵융합에너지를 이용한 엔진이나, 이론상으로 에너지의 극치라 여기는 반물질을 이용한 엔진을 설계하여 보고 싶습니다. 현재까지는 고등학생의 지식으로 아는 지식이 드물겠지만 서울대학교 기계공학부에 들어가 관련 지식을 배우고 그러한 바람을 실현하고 싶습니다."},{"q":"그럼 엔진에 대한 탐구에 서울대학교 기계공학부의 어떤 커리큘럼이나 수업이 도움이 될거라고 생각하세요?","a":"엔진은 그 엔진이 탑재된 동체에 대한 부분과 엔진 사용 시 동체의 운동을 고려해야 한다고 생각합니다. 때문에 서울대 안에 있는 풍동실험시설이 이러한 부분에 있어 도움이 될 것 같습니다. 동체가 운동하는 환경은 실제 환경이기 때문에 지구 내에서 운동하는 동체의 경우 관련한 유체역학에 대한 부분을 고려해야 된다고 생각하기에 풍동시설 같은 부분에 도움을 받을 수 있다고 생각합니다."},{"q":"100톤의 무게의 순금과 100톤 무게의 로켓발사체 중 어떤 것의 값이 높을까요?","a":"제가 순금의 가격을 잘 모릅니다. 하지만 질문해 주신 내용에 대해 생각해 봤을때 100톤 무게의 로켓발사체의 값을 높게 상정하고 싶습니다. 로켓발사체에 포함되는 물질, 원소 하나하나의 질량으로 값을 매겼을때 값은 꽤나 저렴한 것으로 알고 있습니다. 하지만 그런 원소를 가공하여 부품을 만들고 이 부품을 조립하여 기계장치를 만들고 그러한 기계장치가 모여 로켓발사체를 이루는 과정을 생각했을때, 크게 연결이라는 이러한 부분에 높은 가치를 두고 싶습니다. 연구자들이 이러한 연결을 생각해내고 제조과정에서 이러한 연결을 수행하고 하는 모든 과정에 엄청난 노력과 지성이 탑재되어 있다고 생각합니다. 이러한 부분에 있어 100톤 무게의 로켓발사체에 더 큰 값을 매기고 싶습니다. (마지막 질문이 기억이 나지 않습니다. 이 질문을 40초 남짓 남았을때 받아 답변 도중 면접이 종료되었습니다.)4명이 한 조가 되어 면접을 진행하는 층에 입실함. 지원자 한 명에 면접관 두 분이 10분동특이점안 면접을 진행함. 입장하자마자 느낄 수 있을 정도로 면접관 두 분이 압박면접관과 온화한 면접관으로 나뉨높은 내신과 무난했던 면접에도 불구하고 불합격한 이유는 생활기록부 내용이 주로 우주항합/불 분석공쪽이어서가 아닐까 생각함. 서울대 기계공학부의 커리큘럼에 대한 질문에 답변을 잘하지 못함아쉬운 점마지막 질문에 답변하는 도중 면접이 끝남"}],"naesin":"1.19","result":"불합격","resultNote":"최초후-보순위","suneung":"최저충족","type":"일괄합산( ) 단계형( ○ ) 【1단계】 서류 100%(3배수) 【2단계】 1단계서류70%+면접30%","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"서울대학교","dept":"사회교육과","jeonhyeong":"학생부종합/지역균형","method":"서류 확인 면접 / 학생 1명과 교수 2명이 10분간 서류 면접 진행","notes":"","qa":[{"q":"사회 문화 과목에서 ‘지역에 따른 교육 격차’를 주제로 탐구했다고 적혀있는데, 탐구 과정을 자세하게 설명해 줄래요?","a":"책을 읽고 코로나19가 불러온 교육 격차에 대해 알게 됨. 이를 좀 더 일반적인 상황으로 만들어보고자 탐구를 진행함. 거주 지역별 지대를 독립 변인으로 설정하고 교육의 질을 종속 변인으로 설정함. 이때, 교육의 질에 대해서 다양한 기준을 적용시켰음"},{"q":"정치와 법 과목에서 ‘국회에 계류 중인 교원 보호법과 개정안을 둘러싼 여러 교원 단체, 시민 단체, 이익 집단의 입장을 정치 주체 별로 소개’ 했다고 적혀있는데, 설명해 줄래요?","a":"당시 ~~ 기사를 보고 미래 교원이 된 자신도 저러한 상황에 처할 수 있음을 생각하게 되었고, 그렇다면 어떠한 법률을 통해 자신을 보호할 수 있는지 알아보고자 연구 진행함."},{"q":"그러면 정치 주체 별 입장을 알려줄 수 있을까요?","a":"기억이 안나용(실제 답변)"},{"q":"2학년 때부터 멘토링을 진행해 왔다고 적혀 있는데, 어떠한 가치를 중점적으로 두고 멘토링을 진행하였는지?","a":"멘토링을 진행하면서 친구들이 단순히 암기 형식의 학습만을 하지 않을 수 있도록 하려고 하였다. 그래서 수업 시간에 배운 학습 내용이 적용된 기사를 하나씩 찾아와서 분석한다거나, 서로의 오개념을 수정시켜 주는 방식으로 진행했다."},{"q":"사회 과제 연구에서 청소년 혐오 표현 관련 보고서를 작성했다고 하는데, 그 동기를 알고 싶음.","a":"주변에서 볼 수 있는 다양한 청소년들이 혐오표현을 거리낌 없이 사용하고, 그에 대한 문제의식을 갖지 못하는 모습을 볼 수 있었음. 그래서 혐오표현을 사용하는 이유와 종류, 사용 대상을 등을 알아보고자 보고서를 작성함"},{"q":"포괄적 차별금지법에 대한 내용이 적혀있는데, 이 법률에 대한 생각은 어떠한지?","a":"당시 조사를 하면서 차별금지법에 대한 찬반이 나뉘었던 걸로 기억함. 찬성측은 단순히 표현의 자유를 침해하는 것이 아닌 오히려 서로의 자유를 보장해 주는 법이 될 수 있다고 주장하였고, 반대 측은 그럼에도 불구하고 표현의 자유가 침해되는 것은 사실이라고 주장함. 저는 법률을 도입하여 혐오 표현을 규제하는 것은 본질적인 해결책이 될 수 없다고 생각하기 때문에 포괄적 차별금지법 도입에 대해서 회의적인 시각으로 바라보고 있음. 법보다는 차이에 대한 교육을 통하여 혐오 표현의 원인인 다름을 이해하지 못하는 것을 해결할 수 있다고 생각함. 한 분께서만 질문 하시고 다른 한분은 그냥 적고만 계셨다. 생기부에 있는 내용을 다 숙지특이점하는게 필요하다. 특히 생기부 내용에 있는 자신의 진로나 전공과 관련된 활동같은 경우는 무조건 내용, 동기는 다 생각해 놓고 면접을 가는 편이 좋다고 생각한다.합/불 분석긴장해서 날려먹은 내용들이 많아서, 면접 끝나고 불합격을 예상하긴 했다.긴장을 너무 많이 해서 준비한 내용도 잊어먹어 제대로 답하지 못했다. 긴장을 푸는 연습이 아쉬운 점필요했을 것 같다."}],"naesin":"1.43","result":"불합격","resultNote":"최초후보순위","suneung":"최저충족","type":"일괄합산( ) 단계형( ○ ) 【1단계】 서류100(3배수) 【2단계】 1단계70+면접30","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"서울대학교","dept":"사회학과","jeonhyeong":"학생부종합/ 기회균형특별전형-사회통합","method":"생기부 기반 면접 (2:1 대면 면접) / 대기실 → 복도에서 대기 → 면접(10분 내외) ∘밖에서 선배님들이 힘차게 응원해주심. 간식도 주심. 엄청 분위기 좋음. 면접장 안도 서울대라는 이름이 주는 중압감이 있지만 기본적으로 조교님들이 다 친절 하셨음. 옆에서 대기하던 친구가 젤리먹어도 되냐고 물어봤는데 흔쾌히 오케오케! 드세요! 해주심.","notes":"∘원래 대기실에서 자료 못 본다고 알고 있었는데 별 간섭 안하시는 것 같았음 (잘 모르겠음). 근데 복도에서 대기할 때는 아무것도 못보고 가만히 앉아서 기다려야 함. ∘학과마다 다를 수 있지만 두 학과 정도 묶어서 같이 대기했음. (지리+복지, 사회+심리 등등) / 면접 들어가기 1분전에 알려주심. 심호흡 천천히 하기.","qa":[{"q":"안녕하세요~ 앉으세요~","a":"넵! (앉음)"},{"q":"많이 떨리시죠?","a":"네 많이 떨립니다! ㅎㅎ"},{"q":"떨지말고 편하게 하세요~ 편하게~","a":"넵!"},{"q":"좋아요~ 학생이 보니까 영어를 되게 잘하시더라고요. 영자신문 만들기에서 ‘The true way to make Korea happy’라는 제목으로 물질적 풍요를 유독 강조하는 우리나라의 사회 풍조에 대해서 쓰고 자료도 수집하고 했던데, 왜 이걸 쓰게 됐는지, 그리고 쓰고 나서 느낀 점이 어땠는지 간략하게 설명해 주시겠어요?","a":"네 알겠습니다! 저는 저뿐만 아니라 주변 사람들, 사회가 편안하고 행복하길 바라는 사람이고, 그래서 행복에 관한 문제에 관심이 많았습니다. 신문기사를 읽다가 한 외국 언론에서 발표한 행복에서 가장 중요한 요소는 무엇인지에 대한 설문조사를 접하게 되었는데, 다른 나라 사람들은 주로 가족이나 친구관계라고 답한 반면, 우리나라 사람들은 물질적인 부, 즉 돈이라고 답했습니다. 우리나라 사람들은 왜 다른나라 사람들과는 달리 물질적인 부에 집착하게 된 것일지 궁금해서 작성하게 되었습니다. 기사를 쓰고 나서, 물질적 부만이 행복의 유일한 요소가 아닌데, 학력주의 등으로 인해 서로를 서열화하고 부만으로 행복을 나누는 풍조가 퍼진 것이 안타까웠습니다."},{"q":"알겠습니다. 학생이 행복에 관한 탐구를 되게 많이 하셨더라고요. 방대한 자료를 찾아보고 탐구를 수행했다고 하는데, 어떻게 행복에 관심을 가지게 되었는지, 어떻게 탐구를 진행했는지 설명해 주세요.","a":"저는 평소 편안해야 마음의 안정을 느끼는 사람이고, 저뿐만 아니라 제 주변 사람들, 이를테면 가족이나 친구, 제가 속한 공동체의 사람들이 행복해야 저도 행복을 느끼는 사람입니다. 제 자신은 행복한 사람을 보냈다고 생각했지만 고등학교 생활을 하면서 친구들과 사회의 사람들이 행복하지 않고 우울해하는 모습을 보고 왜 우리는 행복하지 못한 것일지, 그리고 행복하기 위해서는 어떻게 해야 하는지 궁금해졌기 때문입니다. 이런 궁금증을 바탕으로 저만의 행복지수 만들기(갑자기 말이 막혀서 이것만 말함) 등의 활동을 했습니다."},{"q":"그 행복지수 만들기 활동 말인데, 왜 지표를 이런 식으로 설정하게 되었나요? 그리고 실제로 이걸 해 봤을 때 다른 결과가 나오던가요?","a":"해당 지수는 제가 고등학교 생활 동안 탐구했던 더 나은 삶의 지수, 사회안전지수와 같은 삶의 질과 관련된 지표들을 종합하고, 그와 더불어 시대에 따라 변화하는 주관적이고 상대적인 행복을 반영하고자 했습니다. 그래서 미국의 한 대학교에서 실행했던 실험의 내용을 담은 <세상에서 가장 긴 행복 탐구 보고서>라는 책을 읽고 행복에 가장 영향을 끼치는 요소가 사회적 관계 형성이라는 점을 알고 사회적 관계 형성 지수를 추가했습니다."},{"q":"(더 말하려고 했는데 끊으심. 길어져서 그러신 것 같음.) 직접 시상을 해본 건가요, 아니면 고안만 한 건가요?","a":"시상을 아직 해보진 않았고, 고안만 해보았습니다."},{"q":"알겠습니다. 그러면 본인이 진행한 탐구와 다른 결론이 나올 가능성에 대해 생각해 본 게 있나요?","a":"저는 주로 행복을 사회적으로 더 거시적으로 측정하려고 했던 것 같은데, 경험이나(살짝 멈춤) 가정환경처럼 미시적인 부분을 고려한다면 다른 결과가 나올 수 있을 것 같습니다. 그러나 제가 그 부분은 고등학교 탐구에서는 반영하지 않아서, 그 부분에 대해서는 대학교에 입학하고 나서 추가적으로 탐구해 보고 싶습니다."},{"q":"2학년 동아리 활동에서 인문학적인 소양을 함양했다고 하는데, 이게 본인에게 어떤 변화를 주었나요?","a":"(답변하는 중에 1분 남았다고 밖에서 노크소리 들림) 현재 사회는 기술 발전 등으로 빠르게 변화하고 있고, 그 양상도 분화하고 있습니다. 동아리활동으로 쌓은 인문학적 소양이 이러한 현상들을 정치적, 경제적, 도덕적 관점 등 더 다양한 관점에서 바라볼 수 있게(문 열림) 해 준 것 같습니다."},{"q":"미안한데 시간이 다 되어서 여기서 끝내야 할 것 같아요~ 수고했어요~","a":"감사합니다!! (꾸벅 인사하고 나옴)∘면접 분위기가 편안한 편. 교수님들도 긴장하지 말라고 해주시고, 답변 들으시면서 응응, 어~ 하면서 들어주셔서 말하는 걸 어려워하는 나도 말하기 엄청 편했음.∘이 활동을 진짜 했는지, 탐구한 바를 바탕으로 추가탐구/실천해본 사례, 본인 생각이 어떻게 바뀌었는지, 해당 활동이 자신에게 어떤 영향을 주었는지 등을 중요시하시는 것 같음.∘생기부는 무조건 꼼꼼하게 뜯어봐야 하지만, 그렇다고 해서 예상질문&답변을 무작정 그대로 외우는 건 비추천. 어차피 그대로 안 나올 확률이 9할. ∘친구나 선생님과 자신이 했던 활동이나 관심있는 주제에 대해 이야기하듯 연습하는 것도 좋을 것 같음. 오히려 평소에 긴장을 많이 하는 편이면 이런 분위기가 오히려 말문도 특이점트이고 좋음.∘본인이 3년 동안 얼마나 활동을 열심히 했는지가 바로 나옴. 성실하게 활동했으면 설령 본인이 예상하지 못한 질문이더라도 정확한 개념을 묻는 게 아닌 이상 어렴풋이 기억날 확률 높음.∘본인 생기부가 주제, 색깔이 확실하다면 그것에 대해서 자세하게 물어보시는 것 같음(사람 / 면접관 스타일마다 다를 순 있지만 내 경우는 행복을 주제로 한 탐구를 많이 해서 그 내용을 많이 물어보셨는데 면접 시간 거의 대부분을 내가 공들여서 했던 활동에 대해서 얘기했음.)∘(경상도 사람 기준) 면접관님께서 말씀을 굉장히 천천히 하심. 쓰읍. 어~ 이런거 많이 하심. 질문시간+ 답변시간이 생각보다 길어서 질문이 몇 개 안 될 수도 있음.합/불 분석1단계 합격∘말하면서 내용을 정리하는 타입이라 반복하는 표현이 많았고, 말이 좀 길어진 것 같음.아쉬운 점∘편안해도 면접이다보니 떨려서 말 조금 더듬거림."}],"naesin":"1.36","result":"불합격","resultNote":"최초후보순위","suneung":"최저기준없음","type":"일괄합산( ) 단계형( ○ ) 【1단계】 2배수 서류 100% 【2단계】 1단계 70+면접 30","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"서울대학교","dept":"사회학과","jeonhyeong":"학생부종합 / 지역균형","method":"서류 확인 면접 7:40-8:20 입실, 8:20-8:50 대기실 전체 대기, 이후 면접 번호에 따라 5분전 / 복도 대기, 면접 10분 대기실에서 전자기기는 사용할 수 없지만 종이는 볼 수 있기 때문에, 자료를","notes":"미리 프린트해올 것.","qa":[{"q":"면접관1: 동아리 활동 기억하죠? 1학년 때 시사토론, 2학년 때 프리토킹, 3학년 때 경사법이라는 동아리를 했는데, 특히 3학년 활동에 관심이 갑니다. ‘68혁명과 마오주의’라는 주제에 대해 탐구를 했는데 전체적으로 설명해주시고, ‘40년대 자유주의 운동보다 68혁명이 더 큰 영향력을 가진 이유’에 대해서도 말씀해 주세요.","a":"장 뤽 고다르 감독의 ‘네 멋대로 해라’라는 영화를 보다가 고다르 감독이 68운동에 참여하는 장면이 나왔음. 그 뒤에 마르크스와 마오쩌둥의 얼굴이 그려진 포스터와 깃발이 나왔는데, 당시 냉전 체제 하에서 자유주의 진영 국가에서 일어난 운동에 공산주의 국가의 이념이 활용된다는 것이 흥미로워 주제로 선정하게 되었음. 마오주의가 68운동의 이념적 배경으로 작용한 이유는 소비에트식 공산주의와의 차이점에서 찾을 수 있음. 소비에트식 공산주의는 산업 중심이었지만, 마오주의는 농민 중심의 참여를 강조하는 혁명이라는 점에서 68세대의 환호를 받음. 이에 더해 극동아시아에서는 서구와는 다른 유토피아가 건설되고 있다는 오리엔탈리즘적 환상이 더해진 것이라 볼 수 있음. 발표 후 ‘40년대 자유주의 운동보다 68혁명이 더 큰 영향력을 가진 이유’를 묻는 질문을 받아서 추가 조사를 해봄. 그 이유는 범위에서 찾을 수 있음. 40년대 자유주의 운동은 제2차 세계대전 이후 자유와 권리의 회복을 강조한 반면 68운동은 더 넓은 범위에서 일어났음. 이는 이후 페미니즘과 록 음악의 발전으로 이어졌기 때문에 더 큰 영향력을 가짐. 또한 40년대 자유주의 운동은 국가적 단위에서 일어났다면, 사회학자 프란츠 파농이 정의했듯이 68세대는 ‘Live TV generation’임. 그렇기 때문에 세대적 연대를 바탕으로 초국가적 영향력을 가짐."},{"q":"면접관2: 문화에 되게 관심이 많아 보이네요. 무슬림... 아랍... unipolarity... 이런 내용을 다뤘는데, 사실 앞으로 단극성 체제로 갈 것인지, 다극성 혹은 양극성으로 갈 것인지 논란이 많이 되잖아요. 거기에 대한 본인의 의견과 그리고 바람직한 체제가 무엇인지에 대해서도 말씀해주세요.","a":"미국 중심의 단극적 체제가 유지될 것이라고 생각함. 군사, 경제, 문화적 측면에서 미국이 절대적 우위를 차지하고 있기 때문임. 특히 경제의 경우에는 미국이 달러 패권을 쥐고 있기 때문에 세계 경제의 주도권을 가지고 있음. 페트로 달러 체제가 현재 위기에 있지만 여전히 석유 거래의 대부분이 달러로 이루어지고, 외환 보유고의 59%가 달러인 것으로 알고 있음. 그렇기 때문에 미국 중심의 단극적 체제가 유지될 것이라고 생각함."},{"q":"면접관2: 그럼 중국의 영향력이 그렇게 크진 않다. 양극적 체제로 가진 않을 것이다. 이렇게 생각하는 건가요?","a":"이전에 ‘중국이 세계를 지배한다면’이라는 책을 읽었음. 그 책이 20년 전쯤 책인 것으로 알고 있는데, 그 책을 읽으면서 작가가 예상한 중국의 위상과 현재의 모습을 비교하면서 읽었음. 그 결과, 책에서 작가가 예상한 중국의 부상에 비해서 현재 중국의 영향력이 그리 크지 않다고 생각함."},{"q":"면접관1: 방금 세계의 단극성...에 대해서 얘기를 했는데 3학년 사회문제탐구 시간에 마강래의 지방도시살생부를 읽었어요. 기억나죠? 그 책에서도 단극체제와 비슷하게 ‘수도권 일극체제’를 얘기하는데, 마강래의 주장을 요약하고 그에 대해 비판해주세요.","a":"모든 지방을 균형있게 발전시키는 것은 비효율적이므로 선택과 집중을 통해 광역도시 중심으로 압축적으로 발전해야 한다는 것을 주장한 것으로 알고 있음. 하지만 지역균형발전은 헌법에서도 보장하는 가치이고 도의적으로 보았을 때도 맞음. 또한 노인들의 경우에는 살던 곳에 계속 살고 싶어하는 경향이 있기 때문에, 효율성을 문제로 압축 발전할 도시를 선별하는 것은 노인들의 의사와 상충된 방향으로 갈 수 있다는 점에서 비판할 수 있음."},{"q":"면접관1: 어떻게 상충된다는 것이죠?","a":"노인들이 원래 살던 도시가 압축 발전할 도시로 선별되지 않으면, 투자가 줄어 인프라가 낙후될 수도 있음. 효율적 투자를 위해 도시를 선별하는 것은 선택되지 않은 도시에 살고 싶어하는 사람의 선호를 무시할 수 있다는 점에서 비판할 수 있음."},{"q":"면접관1: 지역 불평등이 심해질 수 있다는 거죠?","a":"네.(1분 남았다는 노크 소리)"},{"q":"면접관2: 시간이 얼마 안남았는데, 사회학과 입학 후 무엇을 배우고 싶은지와 졸업 후 계획에 대해서 말씀해주세요.","a":"사회학과 진학 후 정책 설계 과정에 대해 배우고 싶음. 고등학교에서 사회 문제를 분석하고 그에 따른 해결책을 제시하는 보고서를 작성하는 활동을 많이 함. 그 과정에서 경제 성장과 환경 보호, 사회적 규제와 개인의 자유 등의 딜레마적 상황에 직면함. 그 상황에서 항상 상반된 입장을 절충해서 균형점을 제시해야 한다는 식으로 해결책을 제시했지만 이는 너무 당연하고 추상적이게 들려서, 실질적인 변화를 가져오기에는 역부족이라고 생각함. 따라서 사회학과에 진학한다면 구체적인 정책 설계 과정을 배우고 싶음. 현대 사회의 사회문제는 한 국가에 국한된 것이 아니라 초국가적 영향력을 가지고 있다고 생각함. 따라서 졸업 후에는 UNDP 같은 국제 정책 기구에 들어가고 싶음.(문 열림)"},{"q":"면접관2: 국제 기구에 들어가고 싶다는 거죠? 네 잘 들었습니다.꼬리 질문이랑 압박 질문이 심하다고 했는데, 꼬리 질문이 생각보다 별로 없었음. 주장의 특이점한계점을 지적하거나 반대 입장에서 질문하실 줄 알았는데, 호응 잘해주시고 잘 들어주심.꼬리질문 제외 크게 4질문 (마오주의, 단극성, 지방도시살생부, 앞으로 계획)을 물어보셨는데, 합/불 분석지방도시살생부를 제외한 3질문은 예상한 질문이라서 수월하게 답변할 수 있었음.면접 분위기가 좋아서 웃으면서 자신감 있게 답변했는데, 이가 합격에 도움이 됐다고 생각함. 아쉬운 점질문을 길게 하셔서 답변도 길게 하다 보니, 몇 질문밖에 못하고 시간이 끝남.","a":""}],"naesin":"1.09","result":"최초합격","resultNote":"최초후보순위","suneung":"최저충족","type":"일괄합산( ) 단계형( ○ ) 【1단계】 서류 100 (3배수) 【2단계】 1단계 70 + 면접 30","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"서울대학교","dept":"수리과학부","jeonhyeong":"학생부종합/지역균형전형","method":"서류 기반 면접 대기실에서 대기 후 면접 2분 전에 본인 차례임을 알려줌. 그 후 면접실 바로 밖에서 약 1~2분 대기 후 이전 차례 학생이 나오면 면접실에 / 들어가서 면접을 진행함. 10분 내외로 면접이 진행되며, 면접이 끝나면 퇴실함. 대기실 입실 시간 이후에는 본인이 준비한 자료 전혀 보지 못함.","notes":"2분 남았을 때 노크 한 번, 그리고 면접 시간이 다 되었을 때 노크 한 번으로 총 두 번 노크해 줌.","qa":[{"q":"길이 많이 미끄럽지는 않았냐고 질문함.","a":"많이 미끄러워서 조심해서 왔다고 답변했습니다."},{"q":"3학년 동아리활동에서 머신러닝 파트를 맡아 데이터 기술 개념 정리 활동을 진행했는데, 이에 관한 설명 부탁함.","a":"데이터 기술 개념 정리에서 인공지능, 머신러닝, 딥러닝 간에 어떠한 관계가 있는지에 답변했습니다. 그리고 머신러닝 파트를 맡았기에 머신러닝 알고리즘에 관해 탐구를 진행하였으며, 그중 나이브베이즈와 의사결정트리가 있음을 알게 되었다고 했습니다."},{"q":"나이브베이즈와 의사결정트리가 무엇이냐고 질문함.","a":"나이브베이즈와 의사결정트리가 무엇인지 답변했습니다."},{"q":"3학년 자율활동에서 오일러 공식에 관해 탐구 활동을 진행했는데, 오일러 항등식의 수학적 의미와 실용성에 관한 설명 부탁함.","a":"세특에서 말한 오일러 공식이 정확하게는 오일러 항등식임을 밝히고, 오일러 항등식을 구성하고 있는 5가지 숫자들의 수학적 의미에 관해 답변했습니다."},{"q":"5가지 숫자들로 구성된 오일러 항등식 자체의 수학적 의미가 무엇인지, 그리고 탐구활동을 진행하며 느낀 점을 질문함.","a":"관련성이 없어 보이는 숫자들 간의 연결성을 드러낸다는 점을 중심으로 오일러 항등식의 수학적 의미에 관해 답변했습니다. 더불어 탐구활동을 진행하며 숫자들간의 연결성이 있음을 알게 되고, 이에 흥미를 느꼈으며 추후 이와 같은 분야를 연구해보고 싶다고 답변했습니다."},{"q":"오일러 항등식의 실용성에 관해 질문함.","a":"물리, 컴퓨터와 같은 분야에서 활용될 수 있다고 답변했습니다."},{"q":"리더쉽을 발휘한 경험과 그에 대한 느낀점에 관해 질문함.","a":"동아리 부장으로서 리더쉽을 발휘한 경험에 관해 답변했습니다. 동아리 활동 계획, 과학체험전 참여 등 여러 활동을 진행하며 리더쉽을 발휘했다고 답변했습니다.(중간에 2분 남았다고 노크함) 과학체험전과 동아리 활동 계획 등을 하며 어려움을 느꼈으며, 처음에는 적극적으로 학교생활에 참여하고 싶어 부장을 맡았지만, 부족한 점을 되돌아보며 책임의 중요성을 느꼈다고 말했습니다.(뒤에 할 말이 더 남았지만 끝나서 못함.)특이점매우 편안한 분위기에서 면접이 진행됨. 압박 면접과 같은 분위기는 전혀 없었음.아쉬운 점본인이 약간 간과한 부분에서 질문이 나올 수도 있으니 주의할 것."}],"naesin":"1.25","result":"불합격","resultNote":"최초후보순위","suneung":"최저충족","type":"일괄합산( ) 단계형( ○ ) 【1단계】 서류100(3배수) 【2단계】 1단계70+면접30","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"서울대학교","dept":"식품ㆍ동물생명공학부","jeonhyeong":"학생부 종합/지역 균형","method":"학생부 기반 면접 입실→공지 후 소지품 모두 제출→대기(30분 정도)→면접→면접 후 대기(10분 정 / 도)→퇴실 전자기기뿐만 아니라 학생부나 예상 질문지 같은 종이까지도 모두 제출해야 함.","notes":"대기 시간 동안 할 수 있는 것이 아무것도 없으므로 짐은 최대한 간소하게 챙겨 가는 것이 편함","qa":[{"q":"학생부 기반으로 질문할게요. ‘Survival of the friendliest’를 읽고 활동을 했다고 되어 있는데, 책 내용 중에 가장 공감 가는 내용과, 그 이유가 뭔가요?","a":"우선 그 책을 읽게 된 계기부터 말씀 드리겠습니다. 1학년 진로 활동 시간에 ‘이기적 유전자’를 읽었는데, 거기에서는 적자생존과 경쟁의 관점으로 진화를 바라봤습니다. 하지만 이 책에서는 제목에서처럼 진화에서의 협력과 유대를 강조하고 있으므로, 상반된 관점을 비교해 보기 위해 읽었습니다. 책에서는 보노보와 호모사피엔스의 예를 사례로 들며 때로는 강함보다 상냥함이 생존에 더 도움이 될 때가 있다고 말하는데요, 학교에서도 머리가 좋지만 불친절한 친구보다는 공부를 조금 못하더라도 항상 웃는 얼굴로 다른 친구들을 대하는 친구가 학교생활을 더 잘합니다. 생존에 비유하기는 애매하지만, 확실히 개체의 강함보다는 타인에 대한 친절함이 생활에 더 도움이 될 수 있다는 점에서 공감이 갔습니다."},{"q":"3학년 때 길고양이 개체 수를 줄이기 위한 방법을 탐구했는데, 어떻게 했는지 자세히 말해 주세요.","a":"우리 학교에는 길고양이가 매우 많아서 학생들과 선생님들, 그리고 고양이가 모두 불편을 겪습니다. 수학Ⅰ과 영어 독해 작문에서는 길고양이 개체 수를 TNR을 통해 조절하는 방안에 대해 자세히 탐구했었는데, 학교에서 TNR을 시행하기에는 무리가 있기 때문에 서식지를 분리하는 것으로 방법을 강구해 봤습니다. (크로마토그래피, PCR 이용 방안 설명~~~)"},{"q":"해수 공급 여부에 따른 토마토 당도 상승 실험의 계기, 본인의 역할과 느낀 점을 말해 보세요.","a":"우리 지역의 마늘이 해풍을 맞고 자라서 타 지역보다 맛있다는 기사를 보고, 그렇다면 다른 식물을 재배할 때도 해풍을 맞게 하면 더 맛있어지지 않을까? 하는 가설을 세운 뒤, 친구들과 생명과학에서 배운 대조 실험을 진행했습니다. 그 결과, 실제로 희석한 해수를 공급한 실험군에서 토마토 당도가 더 높았습니다. 실험 중간에 당도 측정계가 없는 문제점이 있었는데, 화학적 지식을 기반으로 전류 측정계를 대신 사용하자는 아이디어를 제시하여 실험이 성공적으로 이루어질 수 있도록 기여했습니다. 저희가 내린 결론이 지역 사회 발전에 도움이 될 수 있을 것이라는 생각에 뿌듯했던 경험이었습니다."},{"q":"해풍과 해수는 차이가 좀 있지 않을까요?","a":"네, 하지만 지리적 여건상 해풍을 직접 맞게 하기는 어려웠기 때문에 우선 식물이 물을 흡수하는 방법에 대해 알아봤습니다. 뿌리로 흡수하는 방법이 있고, 잎을 통해 흡수하는 방법이 있는데, 해풍이 뿌리보다는 잎에 닿을 것이라고 판단했기 때문에 희석한 해수를 잎에 뿌리는 방법, 즉 엽면시비 방법으로 해수를 공급함으로써 최대한 한계점을 보완하려 했습니다."},{"q":"한국사 시간에 곰이 마늘과 쑥만을 먹고 100일간 버틸 수 있는지를 탐구해 봤네요? 왜 안 될 거라고 생각했죠?","a":"(나는 인간으로 가정하고 진행한 건데 교수님은 곰이라고 생각하고 계셨나 봄) 필수 아미노산과 탄수화물이 결핍되어 있을뿐더러, 쑥 속의 카로틴이라는 성분이 지방을 분해하기 때문에 동굴 속에서 에너지를 최대한 비축해야 하는 상황에서 불리하게 작용할 것이라 생각했기 때문입니다."},{"q":"실제로 곰은 겨울잠을 세 달간 자면서 아무것도 먹지 않기 때문에 가능합니다~ 한국사 선생님이 배경지식이 없어서 그렇게 하라고 시켰을 수도 있는데, 아니에요~","a":""},{"q":"‘반려동물 영양학’을 읽으면서 고양이 사료에 대해 탐구했는데, 음... 그러면 고양이 사료에서 가장 중요한 건 뭘까요?","a":"당뇨병 위험이 있기 때문에... 탄수화물 비율을 조절하는 것이 가장 중요하다고 생각합니다. 그리고, 비타민B도 중요한 것으로 알고 있습니다."},{"q":"고양이 사료에서 가장 중요한 건 타우린이에요. 체내에서 합성을 못하기 때문에. 고등학교 선생님은 이런 거 잘 모르시니까 그럴 수 있어요. 대학 가서 배우면서 통합적 지식을 넓히면 좋을 것 같아요~(1분 남았다고 노크함)","a":""},{"q":"시간 거의 다 돼서 나가봐도 좋아요~ (인사하고 나옴)학생부 외에 지원 동기나 향후 계획, 목표 등 상투적인 질문 없었음. 학생부에서도 수학, 과특이점학 말고 영어나 한국사같이 안 중요하다고 판단한 과목에서 질문하심합/불 분석초반에 긴장해서 목소리도 떨렸고 물어보지 않은 것까지 너무 장황하게 설명함. 지원 동기아쉬운 점랑 마지막 할 말 연습 많이 했는데 할 기회가 없었음. 시간 1분 남겨놓고 끝나서 마지막 할 말은 할 수 있었을 것 같은데 안 하고 그냥 나와서 조금 아쉬운 마음이 있음","a":""}],"naesin":"1.93","result":"최초합격","resultNote":"최초후보순위","suneung":"최저충족","type":"일괄합산( ) 단계형(○) 【1단계】 서류100(3배수) 【2단계】 1단계70+면접30","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"서울대학교","dept":"원자핵공학과","jeonhyeong":"학생부종합/기회균형특별전형","method":"서류 확인 면접 입실 > 수험표 및 신분증 확인 > 전자기기 수거 > 대기 > 면접 > 전자기기 / 회수 후 퇴실 전자기기 수거 후 아무것도 할 수 없음","notes":"(책 읽기x, 유인물x, 자는 것, 멍떄리기, 화장실 정도만 허용)","qa":[{"q":"예... 자기소개 하고 우리 원자핵 공학과에 지원하게 된 동기를 말해보세요","a":"넵 저는 열정의 온도만으로도 핵융합을 상용화 시킬수 있는 열정과 다양한 분야의 관심을 가진 면접번호 ○이라고 합니다. 제가 원자핵공학과에 지원하게 된 동기를 말씀드리겠습니다. 저는 원래 원자핵공학과 수학 두 분야에 많은 관심을 가지고 어느 분야로 진학할지 많은 고민을 하였습니다. 그런데 생각해보니 수학은 제가 노력해서 어떤 결과를 얻는다고 하여도 사람들에게 그 이익이 즉각적으로 돌아가지 않습니다. 하지만 원자핵 공학과는 제가 만약 플라즈마 물리학에 대해서 공부하여서 핵융합의 상용화에 도움이 되는 어떤 발견을 한다면 그 이익이 사람들에게 에너지의 형태로 즉각적으로 돌아갈 수 있습니다. 그런 원자핵공학과의 비전에 매력을 느껴 이 과에 지원하게 되었습니다."},{"q":"음... 학생은 그러면 핵융합에 대해서 관심을 가지고 있는거 같은데요. 핵융합의 난제 같은 것도 조사한거 같은데 말해볼래요?","a":"먼저 토카막 방식에서 핵융합의 난제는 플라즈마의 불안정성 때문에 발생됩니다. 플라즈마를 가열할 때 4000만 캘빈까지는 플라즈마에 전류를 걸어주어 그 전기저항을 이용하여 가열하는 방식을 사용하는데 이 방식은 전류를 걸어주기 때문에 전기장, 자기장이 생겨 플라즈마의 운용을 방해합니다. H-모드의 경우에 가장자리 불안정 현상이 발생하여 곳곳에서 플라즈마의 밀도와 온도가 다른곳이 생겨서 자기섬이 형성되어 플라즈마가 붕괴되는것과 같은 핵융합의 난제가 있습니다."},{"q":"학생이 유체역학에 대해서 공부를 한 것 같네요. 유체역학과 핵융합은 어떤 연관이 있을까요?","a":"먼저 핵융합에서 플라즈마는 디바이 차폐를 만족시키는 이온화된 기체를 뜻합니다. 핵융합은 이런 이온화된 기체인 플라즈마를 얼마나 잘 유지하고 조정하느냐에 달려있습니다. 따라서 유체의 움직임을 예측할 수 있는 유체역학이 필요합니다."},{"q":"3학년 때 공학 동아리를 했다고 나와있네요. 어떤 동아리이고 몇 명 정도 가입되있었나요?","a":"공학에 관련된 수학과 물리학에 관련하여 공부하거나 혹은 자신이 만들고 싶은 것을 만드는 그런 동아리입니다. 대략 23명 정도 가입되어 있습니다."},{"q":"(위의 꼬리질문) 그럼 학생은 여기서 어떤역할을 하였나요?","a":"제가 1학년 때부터 수학과 물리학에서 여러 심화탐구를 많이 진행하다보니 다른 학생들보다 교과과정에 없는 그런 지식을 얻는 법이나 기초적인 미적분, 물리학 지식이 많습니다. 이런 지식을 방식으로 심화탐구에 어려움을 겪는 학생들에게 편미분, 변분법 등을 가르쳐주거나 혹은 이런 지식은 어떤 장소(웹사이트)에서 얻으면 된다 이런걸 알려주는 역학을 하였습니다."},{"q":"허허 학생이 ‘진국’이라는 별명을 가지고 있네요. 왜 이런 별명을 가졌나요?","a":"선생님과 제 친구들이 제 수업 태도와 학문에 관한 태도를 보고 그런 별명을 지어주었습니다. 저는 항상 수업에서 가장 앞자리에서 누구보다 열심히 수업에 참여하였고 수업에서 배우는 지식만이 아닌 조금 더 스스로 공부하여 선생님에게 물어보며 심화탐구하였습니다. 또한 전에 말했다싶이 저는 여러 친구들에게 제 지식을 많이 나누어주었습니다. 이런 지식에 대한 제 태도를 보고 친구들이 “와 이 녀석 ‘진국’이네. 노벨상 타자.” 약간 이렇게 제 별명이 진국이 되었습니다.특이점테이블이 있고 입학사정관 , 교수님과의 거리가 가까움 합/불 분석아쉬운 점유체역학에 관련된 내용을 별로 탐구하지 않았는데 더 탐구하였으면 좋았을 것 같음"}],"naesin":"1.62","result":"불합격","resultNote":"최초후보순위","suneung":"최저기준없음","type":"일괄합산( ) 단계형( ○ ) 【1단계】 서류100(2배수) 【2단계】 1단계70+면접30","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"서울대학교","dept":"원자핵공학과","jeonhyeong":"학생부종합/지역균형","method":"확인 면접 / 대기하다가 타이머로 정확히 10분간 확인 면접 진행","notes":"대기시간동안 면접 준비 불가능","qa":[{"q":"생기부를 보니까 고급 물리학을 들은 것이 인상깊은데 고급물리학을 들은 이유가 있나요?","a":"저는 고등학교 생활 동안 물리에 관심이 많았습니다. 중학교 3학년 겨울 방학 때 여러 분야의 책을 읽었습니다. 그 중 물리 분야의 책에 흥미가 갔고, 그 뒤로 물리에 관해 탐구하며 더 심화된 물리학 수업을 듣고 싶다는 생각이 들어 고급물리학을 수강했습니다."},{"q":"1학년때 보어 원자모형의 문제점을 파악하고 물질의 이중성을 통해서 해소했다고 나와있는데, 보어 원자모형의 문제점이 뭔가요?","a":"보어 원자모형은 전자의 정상상태를 가정하고 전자가 특정 정상 상태의 궤도에서만 돈다고 가정하는 이론입니다. 보어 원자모형에서 전자가 입자라면 특정 궤도를 계속 돌지 못하고 에너지를 잃어 원자핵 쪽으로 떨어진다는 문제가 발생합니다. 하지만 전자가 파동성을 가진다면 파동이 정상파가 되어야 함으로 특정 궤도를 도는 것을 설명할 수 있습니다."},{"q":"물리 중에 관심 있는 분야가 따로 있나요?","a":"저는 양자역학에 관심이 많습니다. 1학년 때부터 물질의 이중성, 불확정성 원리 등에 관해 탐구한 경험이 있으며 스핀과 관련하여 탐구하는 등 여러 양자수에 관하여도 학습하였습니다"},{"q":"스핀이 뭔가요?","a":"스핀은 전자 등의 입자에 내재되어 있는 각운동량을 뜻합니다. 스핀에 관해 처음 알게 된 것은 스핀트로닉스라는 책을 통해서 였습니다. 하지만 그 책은 스핀을 이용한 기술에 주목하여 스핀을 전자의 자전이라고 간단히만 설명하였습니다. 저는 이전의 물질의 이중성에 관한 탐구를 바탕으로 전자가 입자성과 더불어 파동성을 가진다는 것을 알고 있었고, 전자가 파동이라면 스핀을 어떻게 설명할 수 있을 지 의문을 가지게 되었습니다. 따라서 스핀이라는 책을 통하여 스핀에 관해 심화탐구한 결과 입자에 내재되어 있는 각운동량임을 알게 되었습니다."},{"q":"그럼 물리에 관심이 있는 건 알겠는데 왜 원자핵공학과에 지원한 것인가요?","a":"저는 학문적 소양을 갖추는 동시에 이를 활용하여 인류에 도움이 되는 기술을 개발하고 싶다는 목표가 있습니다. 지만 고등학교 3년 동안 학문적 탐구를 한 경험은 많았지만 이를 일상생활에 적용하고 새로운 것을 개발하는 경험이 부족하다고 생각했습니다. 저는 대학이 부족한 부분을 배우고 성장하는 곳이라고 생각했기에 공과대학에 지원하였습니다. 그 중 제가 관심있는 양자역학을 활용할 수 있고 제가 관심있는 환경 문제를 해결하는 데에 원자로가 핵심 기술이라고 생각하였기에 원자핵공학과에 지원하게 되었습니다."},{"q":"환경 문제에 원자로가 왜 핵심 기술인가요?","a":"현재 화석 연료를 대체하기엔 다른 친환경 에너지는 충분한 에너지를 내지 못하고 있다고 생각합니다. 따라서 많은 에너지를 생산할 수 있는 원자로가 핵심 기술이라고 생각합니다."},{"q":"저희 학과에서 듣고 싶은 분야가 있나요?","a":"양자역학을 활용한 양자공학과 제가 관심있는 환경과 관련된 시스템 공학 관련하여 공부하고 싶습니다."},{"q":"진로 계획이 있나요?","a":"아직 구체적인 계획은 없지만 대학원 진학 후 연구소에 취업하여 사람들을 위한 기술을 개발하고 싶습니다."},{"q":"공부 외에 하고 있는 것이 있나요?","a":"저는 공학자는 인류와 밀접하고 특히 원자핵공학과는 기술의 부작용이 크기 때문에 올바른 과학 윤리관을 정립하는 것이 중요하다고 생각했습니다. 따라서 토론을 하거나 여러 사례를 고찰하며 올바를 과학 윤리관을 정립하기 위해 노력하였습니다."},{"q":"질문을 잘 이해 못한 것 같은데 취미생활이 있냐고 물어본겁니다.","a":"아 저는 배드민턴을 즐겨 치고 중학교때 처음 접한 저글링도 즐겨 하고 있습니다."},{"q":"아까 연구원이 되고싶다고 했는데 연구원의 자질에 맞다고 생각하는 본인의 장점을 한번 자랑해보세요.","a":"저는 창의력이 뛰어나다고 생각합니다. 1학년때부터 열매가 둥근 이유나 종이가 물에 젖으면 쭈글쭈글해지는 이유 등 저만의 궁금증에 대해 탐구하였는데 교과 선생님들께서 창의력이 뛰어나다고 칭찬해 주신 것이 기억에 납니다."},{"q":"연구원에게 중요한 능력이 뭐라고 생각해요?","a":"새로운 무언가를 발견하기 위해서는 창의력이 첫 번째로 중요하다고 생각합니다. 그 다음으로 공학은 조금의 오차도 큰 실패로 이어질 수 있다고 생각하기 때문에 성실함과 꼼꼼함도 (문 열고 들어옴)"},{"q":"시간 다 됐네요 수고하셨습니다. 특이점질문을 조곤조곤 하시는데 질문의 날카로움이 느껴짐.지원자에게도 긴장감과 압박감이 큰 면접이었겠지만 면접관의 질문에 차분히 본인의 소견을 조리있게 성실하게 답변하려고 노력한 점, 면접관의 추가 질문과 전공적합성을 파악하는 질문에 합/불 분석가감없이 본인의 활동 내용과 견해, 고교생활을 어필한 점이 긍정적인 평가로 이어진 것으로 보임.아쉬운 점","a":""}],"naesin":"1.47","result":"최초합격","resultNote":"최초후보순위","suneung":"최저충족","type":"일괄합산( ) 단계형( ○ ) 【1단계】 서류100(3배수) 【2단계】 1단계70+면접30","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"서울대학교","dept":"윤리교육과","jeonhyeong":"지역균형","method":"서류 확인 면접 / 간단한 인사 -> 질문","notes":"대기실, 면접실 모두에서 분위기가 딱딱하지는 않은 편이었음 오전 이른 면접이었으며, 아침을 먹고 왔냐고 따뜻하게 맞이해 주셨음. [질문 내용1]","qa":[{"q":"(윤리와사상 세특 관련) 미디어 리터러시 교육 제도에 대해 탐구했다고 했는데 학생이 실제로 교사가 되면 어떻게 학생들에게 미디어 리터러시 교육을 할 건가요?","a":"학생들이 어떤 사례 속에서 직접 어떤 정보를 받아들일지 결정하고 자신만의 수용 기준을 설정해 보는 활동을 계획한다는 식으로 답변했습니다."},{"q":"학생들에게 직접 생각하게 했는데 잘못된 방향으로 생각한다면 어떻게 할 건가요?","a":"미디어 리터러시 자체의 개념에 대해 다시 설명해 줌으로써 자신의 수용기준에 대해 다시 생각해 볼 기회를 준다는 식으로 답변했습니다.[질문 내용2]"},{"q":"(3학년 자율활동 중 독서내용) 루소의 다른 책 읽은 거 있나요?","a":"아직 읽어보지는 못했으나 제가 읽은 책의 바탕이 된 책이 루소의 ‘에밀’인데 그 책을 읽어보고 싶다는 식으로 답변했습니다."},{"q":"루소의 자연주의 교육관을 현대교육에 적용했을 때의 의의점이 뭐라고 생각하나요?","a":"창의성, 자율성 강화를 중심으로 답변했습니다."},{"q":"부작용도 있을 것이라 생각하는데, 부작용에는 어떤 것이 있나요?","a":"학교교육에서 배우는 것은 공부뿐만이 아니라 미래사회 구성원으로서 갖추어야 할 사회성, 협업능력 등의 다양한 태도와 가치관이 있습니다. 자연주의 교육관을 적용하면 이러한 역량을 기르기 어려움이 있기에 자연주의 교육관은 현대, 미래사회에 전적으로 적용하기는 어렵고 선택적 수용이 필요합니다."},{"q":"수능 윤리과목 응시하셨나요?","a":"네. 평소 윤리과목을 좋아하고, 사상가들의 생각을 심층적으로 분석하는 것을 좋아하여선택했다는 식으로 답변했습니다.[질문 내용3]"},{"q":"그럼 루소의 사상 중에 가장 기억에 남는 거 있었나요?","a":"네. 사회계약론 중에서 일반의지라는 개념이 가장 기억에 남습니다. +일반의지 개념 위주로 추가 설명하였습니다."},{"q":"일반의지에 대해 더 구체적으로 설명해 줄 수 있나요?","a":"서로 충돌하는 욕구같은 것은 배제하고, 모두가 갖는 오직 공익만을 지향하는 것이라는 느낌으로 답변했습니다.[질문 내용4]"},{"q":"미래의 교사에게 필요한 역량이 뭐라고 생각하나요?","a":"미래 사회의 특성상 공부만을 똑같이 가르치기보다는, 학생들 개개인이 스스로 관심과 소질이 있는 것을 배울 수 있는 어떤 태도와 사회성 등을 길러주는 역량이 필요하다는 식으로 답변했습니다."},{"q":"인공지능이나 디지털 교과서 도입같은 변화에 따라 달라지는 역량은 없나요?","a":"우선 인공지능은 (까지 말했는데 시간이 끝남) 꼬리 질문이 있었지만 공격적이라기보다는 생각을 물어보는 질문을 많이 하심. 특이점떨어뜨릴 생각으로 쉬운 질문만 물어본 것 같기도 함.합/불 분석2차 추합 예상 가능한 범위에서 질문이 나왔으나, 긴장하여 구체적 방안을 생각해 내지 못해 추상적아쉬운 점으로 대답한 점."}],"naesin":"1.19","result":"충원합격","resultNote":"최초후보순위","suneung":"최저충족","type":"일괄합산( ) 단계형( ○ ) 【1단계】 서류100% 【2단계】 면접(30) + 1단계 성적(70%)","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"서울대학교","dept":"윤리교육과","jeonhyeong":"학생부종합 / 지역균형","method":"생기부 기반 / 생기부 기반 10분 진행","notes":"","qa":[{"q":"이 학과에 지원하게 된 동기를 말씀해 보세요,","a":"고등학교 2학년, 윤리와 사상 수행평가를 준비하면서 우연히 보게 된 넷플릭스 드라마 ‘소년심판’은 윤리교육과를 선택한 결정적인 계기가 되었습니다. 드라마는 소년범을 혐오하는 주인공이 판사로서 실제 사건을 바탕으로 한 소년범죄를 다루는 내용인데, “인생에서 중요한 것은 마침표가 아니라 쉼표다.”라는 대사가 가장 인상 깊었습니다. 누구나 실수를 하지만 그렇다고 그 실수가 곧 실패는 아니라는 의미로, 이것이 유교 사상가 순자가 말한 화성기위와 닮아있다고 생각했습니다. 인간의 본성은 악하다는 성악설의 대표 학자인 순자는 예법과 후천적인 교육을 통해 악한 본성을 교화하여 충분히 선하게 바뀔 수 있다고 믿었습니다. 저는 이러한 순자의 사상을 본받아 교권을 침해하거나 문제행동을 보이는 학생들에게 바뀔 수 있다는 믿음을 가지고 다가가려는 윤리 교사가 되고자 윤리교육과에 지원하게 되었습니다."},{"q":"정말 그 이유로 윤리 교사를 꿈꾸게 된 게 맞아요? (다른 면접관분이 웃으심)","a":"(1차 당황했지만 웃으면서) 네, 정말 맞습니다."},{"q":"순자의 화성기위를 들면서 촉법소년의 악한 본성을 교화하면 선하게 바뀔 수 있다고 했는데 지원자 본인이 생각하는 우리나라 윤리 교육의 방향성은 어떠해야 한다고 생각해요?","a":"현재 우리나라에서는 윤리라는 분야를 주요 과목이 아닌 범교과로 분류하고, 학교에서 이루어지는 윤리 교육은 단순히 영상을 틀어주고 감상문이나 활동지를 작성하는 등 너무나 피상적으로 이루어지는 것이 문제라고 생각합니다. 그래서 저는 우리나라의 윤리 교육이 실생활과 연관되어 학생들이 몸소 느끼고 중요성을 깨달아 훗날 어른이 되었을 때 윤리적이고 올바른 인재로 성장할 수 있는 교육으로 나아가야 한다고 생각합니다."},{"q":"순자 말고 본인이 고등학교 생활을 하면서 좋아하거나 영향을 준 사상가가 있다면 그 사상가의 대표적인 개념 하나와 함께 구체적으로 설명해 보세요.","a":"네, 물론 있습니다. 제가 너무 좋아하는 실존주의 사상가 중 한 명인 사르트르입니다. 실존주의 사상을 한마디로 요약하면 자신이 삶의 주인이 되어 주체적으로 살아가라는 것입니다. 사르트르는 ‘실존은 본질에 앞선다.’라는 유명한 명언을 남겼습니다. 인간만이 세상에 우연히 내던져진 존재로서 자신이 삶의 주체가 되어 능동적이고 주체적인 삶을 살아간다는 의미입니다."},{"q":"만약 수업 시간에 반에서 마음대로 돌아다니면서 방해하는 학생이 있어요. 그런 상황이라도 실존주의에 입각해서 자유롭게 하게 둘 거에요?","a":"<죽은 시인의 사회>라는 영화가 있습니다. 거기에 키팅 선생님이라는 인물이 나오는데, 기존의 수업방식을 깨고 밖으로 나가 들판에 드러누워 수업을 하거나 책상 위에 올라가서 ‘카르페 디엠’을 외치며 세상을 바라보는 시각을 달리하라는 메시지를 던집니다. 키팅 선생님처럼 학생들에게 어느 정도의 자유를 제공하며 각자의 개성을 인정하는 것도 교사로서 필요한 덕목이라고 생각합니다. 하지만 수업을 방해할 정도로 돌아다니는 학생들이 있다면 지금이 수업 시간임을 확실히 알려주고 자리에 앉을 것을 권유하여 자유에도 제한점이 있다는 것을 인지시킬 것입니다."},{"q":"마지막으로 하고 싶은 말 있으면 해보세요.","a":"저는 윤리를 정말 좋아하고 누군가를 가르치는 것도 적성에 맞다고 느꼈는데, 제가 좋아하고 잘하는 것들을 윤리 교사라는 꿈으로 실현하기 위해서 본교의 윤리교육과에 꼭 진학하고 싶습니다. 또한 제가 다른 사람들보다 음악적 재능이 있다고 자신할 수 있는데, 본교에 입학하게 된다면 윤리교육과의 밴드 동아리인 ‘율리타카’에서 활동하며 드럼을 치면서 학교생활을 즐기고 싶습니다. 감사합니다!- 면접관은 남자 두 분이 계셨음. 30대 후반쯤 보이는 오른쪽 분은 푸근한 인상에 잘 웃어주셨는데, 나이가 있으신 왼쪽 분은 잘 안 웃으셨고 당황하게 만드는 질문을 많이 하심. 특이점분위기는 대체로 밝고 좋았음.- 가번호가 스티커로 주어져서 왼쪽 가슴에 부착할 수 있게 함. - 그냥 인사해도 되고 “가번호 ~입니다.”로 해도 상관없다고 함.합/불 분석최초합생기부 기반이라 여러 번 정독하고 예상 질문을 정리하면서 다양한 내용으로 대비했는데 아쉬운 점한 주제로만 너무 파고들면서 꼬리 질문을 많이 해서 아쉬웠음."}],"naesin":"1.17","result":"최초합격","resultNote":"최초후보순위","suneung":"최저충족","type":"일괄합산( ) 단계형( ○ ) 【1단계】 서류 100(3배수) 【2단계】 1단계 70 + 면접 30","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"서울대학교","dept":"인문계열","jeonhyeong":"지역균형전형","method":"학생부 기반 면접 대기실 대기 후 순번이 되면 해당 면접실로 이동하여 면접의원 2인이 면접 / 평가함","notes":"학교나 개인정보를 면접 중 말하지 않도록 주의해야함","qa":[{"q":"학생부에 고고학이랑 역사에 관심이 많다고 서술되어 있는데 본인 진로와 관련해서 기억에 남는 탐구활동이 있는지?","a":"최종 진로는 학예연구사다. 학예연구사의 가장 중요한 연구 중 하나는 전시를 기획하고 유물을 구성하는 것이라고 알고 있다. 따라서 3학년 동아리 활동 때 3D 프로그램으로 학교 역사관을 설계해 보는 활동을 통해 이러한 업무를 직접 체험해 보려고 했다."},{"q":"고고학에 관심이 많은 것 같은데 해당 분야에서 벗어나서, 수학 과목에서 인공지능과 빅데이터에 대한 탐구를 많이 한 것 같은데 왜 그랬는지?","a":"1, 2학년 때 탐구를 하다가 고고학에서 유적지 도굴 흔적 탐사에 빅데이터를 활용하는 등, 인공지능 분야에 접목한 시도가 다양하게 이루어지고 있다는 것을 알게 되었다. (답변에 고고학이 또 나오니까 질문한 교수님 웃으심;;) 이러한 인공지능 학습법의 원리가 무엇인지 궁금해서 해당 분야를 탐구해봤다. 따라서 2학년 때 빅데이터 학습에 이용되는 경사하강법을 조사했고 함수 그래프 미분을 통해 그래프의 최솟값을 찾음으로써 인공 지능이 바람직한 정답과 가장 근접한 답을 찾게 하는 방법을 이해했다. 인공지능과 빅데이터가 점점 더 많은 분야에 활용되고 있는 만큼 인문학을 전공하고자 하는 사람도 이러한 기술을 이해할 만한 기본 소양을 갖춰야 한다고 느꼈다."},{"q":"2학년 언매 때 ‘향토색’이라는 거랑 보들레르 철학을 연관시켜서 탐구를 했는데 이에 대해 설명 좀 해줄 수 있는지?(질문이 구체적이지 않아서 당황)","a":"보들레르 철학은 수능특강 지문에서 처음 접했다. 보들레르는 당시 정해진 양식에 따라 고전 속 인물을 그려내던 아카데미 예술은 개성과 생명력이 없다고 비판했고 동시대를 살아가는 인물, 그 인물들이 살아가는 순간 속에서 의미를 끌어내야 한다고 주장했다. 한국에도 근대 개화기에 서양 미술이 전파되면서 예술 양식이 변화될 때 변화를 주도한 사상이나 예술가가 있었는지 궁금해서 한국 개화기 예술을 정리한 책을 읽음."},{"q":"향토색이라는 용어를 사용했는데 향토색이 부정적으로 작용한 구체적 사례가 있는지?","a":"향토색 자체는 국가 고유의 정체성과 세계의 문화 다양성을 지켜주는 것임. 그러나 이러한 향토색이 극단적 보수주의나 수구주의로 변질되었던 사례가 있었다고 앞서 설명한 책에서 읽었다. 한국에도 화가들이 자신의 그림을 소개하고 그림을 전시하는 다양한 행사가 있었는데 책은 서양의 양식을 받아들인 화가들은 해당 행사들에 그림을 전시하는 것이 거부되거나 그림이 자체의 예술적 가치가 아닌 서양 양식의 사용 때문에 비판받았다고 설명했다."},{"q":"그러면 근대 프랑스나 한국에서 본인이 제일 좋아하는 작가가 있는지?","a":"마네가 있다. 그림의 형식뿐만 아니라 내용, 소재 등에서도 혁신을 추구했던 화가였다. 프랑스가 멕시코에 허수아비 정권을 세웠을 때 이를 비판하는 그림을 그려내는 등 사회에도 적극적으로 참여하고 의견을 낸 화가라 좋아한다."},{"q":"아까 학교 역사관 프로젝트 얘기 나왔는데 가장 좋아하는 박물관이 있는지? 그리고 학교 역사관을 만들 때 본인이 가장 중요시한 3가지 물건이 있다면 무엇인지?","a":"국립공주박물관. 유물을 다량으로 묶어서 전시하는 방식이 아니라 유물 하나하나에 집중할 수 있도록 전시관이 구성되어 있어서 좋았다. 무령왕릉을 실제로 재현해놓은 공간도 있고 전시관 자체가 무령왕릉을 발굴했을 때 유물 배치 순서 그대로 유물을 관람할 수 있도록 구성된 공간도 있는데 사람들이 역사를 생생하게 체험할 수 있도록 하는 것 같다. 학교 역사관에 관해서, 학교의 역사는 결국 학생들의 일상으로 구성되기 때문에 학생들의 생활 모습을 드러내는 사물들을 가장 중요하게 생각했다. (1분 남았다는 노크 소리 들림) 따라서 학생들의 생활 모습을 담은 사진, 그리고 학생들의 생활상을 담은 인터뷰를 편집한 자료, 학생들이 봉사활동을 할 때 쓴 사물 등 학생들의 모습 자체를 드러내는 것을 중시했다."},{"q":"수고했습니다.","a":"감사합니다.-아이스브레이킹이 있을 거라고 듣고 갔는데 아이스브레이킹 없었음. 인사하고 앉으니까 ‘학생부 기반으로 진행하는 면접이고 총 3가지 질문을 할 예정입니다. 첫 번째는 학업 역량에 관한 질문입니다’ 하시고 그대로 시작함. (그런데 질문은 3개보다 많았다.)-교수님은 두 분인데 예상 외로 두 분 다 눈 잘 맞춰주시고 질문도 거의 똑같은 빈도로 하심. 특이점두 분 다 젊으신 편이었는데 이건 면접실마다 다를 것 같음. 교수님이 들고 계신 서류는 책상에 세우는 가림막으로 가려져 있음. 얼굴이랑 어깨만 보임.-교수님하고 거리가 1. 5미터 정도로 생각보다 멀게 위치함.-끝나고 나서 생각해 보니 지원동기, 인상 깊었던 도서 등에 대한 질문이 없었음.학생부에 기록된 내용을 꼼꼼하게 다시 복기하고 간 점과 당황스러운 꼬리 질문에 적절히 합/불 분석임기응변으로 아는 것을 토대로 잘 대처하여 대답하였기에 최초합이 가능했다고 생각함.준비해 간 것(지원동기, 도서 등등)과 다른 질문이 나와서 잠깐 당황함. 모든 기대를 버리고 가는 것이 좋을 것 같음. 수학 관련 질문 때 고고학 외 분야에서 답변하길 바라신 것 같은데 아쉬운 점애초에 진짜 목적이 고고학 관련이었던 탐구라서 또 고고학 얘기가 나오니까 교수님 웃으심. 실망의 웃음인지 그냥 순수하게 웃기셨던 건지는 모름."}],"naesin":"1.52","result":"최초합격","resultNote":"최초후보순위","suneung":"최저충족","type":"일괄합산( ) 단계형( ○ ) 【1단계】 서류평가 100% 【2단계】 1단계 성적 70% + 면접 30%","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"서울대학교","dept":"자유전공학부","jeonhyeong":"학생부종합/지역균형","method":"생기부 면접 큰 대기실에서 앉아서 대기함. (개인 학습 자료 열람 불가) / 면접 10분. 4명씩 무작위로 불러서 면접 시행","notes":"","qa":[{"q":"자기소개 간단하게 해주세요.","a":"고등학교 시절 저는 환경 문제와 사회적 책임이라는 키워드 깊은 관심을 가지고, 기후 불평등을 해결할 방안으로 기업들이 탄소를 감축하면서 개발도상국과 함께 성장할 수 있는 방안에 대해 탐구하였습니다. 또한 지방 소멸과 저출산 문제를 해결하기 위한 기업과 사회의 역할을 친구들과 토의했고, 해결 방안으로 지방에 특수한 산업 분야를 중심으로 스타트업 군집을 형성하여 우량 일자리를 제공함으로써 수도권 인구를 분산하는 방안을 제시하는 등 우리 사회가 지속 가능한 사회가 되는 방법을 탐구해 왔습니다. 이 활동을 통해 환경을 보호하고 사회적 가치를 추구하는 기업 경영이 기업의 이해관계자를 포함한 사회 구성원 모두에게 긍정적 영향을 미칠 수 있음을 알게 되었습니다. 그래서 저는 기업들이 이윤 추구뿐 아니라 사회의 구성원으로서 사회 문제를 해결하는 것에 앞장서도록 하여 정의로운 사회를 만드는 기업 경영가가 되는 것이 꿈입니다.서울대학교 자유전공학부에 입학하여 열린 학문적 환경에서 동료들과 협업을 통해 융합적 지식을 갖추고, 소통하는 능력을 길러서 사회의 긍정적인 변화를 이끄는 데 기여하고 싶습니다.[질문 1번]"},{"q":"그린워싱 관련 활동을 했다고 적혀있는데 그린워싱 사례 말해볼까요?","a":"저는 그린워싱이 심각하게 일어나는 분야가 아기 용품이라고 알고 있습니다. 부모님들이 아기들이 사용하는 물건에는 특히 예민하기 때문에 그런 기업에서는 친환경, 유기농 등의 키워드를 검증 없이 사용하고 마케팅하는 그린워싱이 자주 발생하는 것 같습니다. [질문 2번]"},{"q":"2학년 한국지리와 3학년 동아리 활동에서 지방 소멸 문제를 해결하기 위해 기업 도시를 짓는 그런 활동을 했는데 어떻게 한다는 건가요?","a":"평소 지방 소멸 문제가 심각하다는 것을 뉴스로 자주 접하고 이것의 주요 원인이 지방 도시의 우량 일자리 부족이라고 생각했습니다. 그래서 각 지자체에서 세제 감면 혜택과 지역 대학과의 연계 등의 유인책을 통해서 지역에 스타트업 클러스터를 형성하고, 대기업과의 협업을 통해 하나의 특정 산업도시를 만들어 수도권으로의 인구 유출을 방지할 수 있는 방안을 고민한 활동이었습니다."},{"q":"(꼬리질문) 일자리를 만들어 놓는 그런 건 지자체에서 다 하고 있고 중소기업들도 많이 있는데 인구가 계속해서 유출되는 이유는 뭐라고 생각해요?","a":"저는 그것이 우량의 일자리 부족이라고 생각합니다. 일자리는 많으나 젊은 연령대가 원하는 높은 질의 일자리는 수도권에 몰려 있고, 우리나라에서 투자하는 자본 80% 이상도 수도권에 집중되어 있습니다. 사람들이 원하는 인프라와 우량의 일자리를 만들기 위해서 특정 산업 중심의 도시가 만들어져야 한다고 생각합니다."},{"q":"(꼬리질문) 한국지리 시간에 외국의 도시 기업 사례만 조사했는데, 우리나라 도시에도 이러한 사례가 있죠? 알고 있는 거 있으면 한번 말해보세요.","a":"어.. 외국의 사례를 한국에도 적용해 우리나라 문제를 해결해 보면 어떨까 했던 거라서.. 잘 모르겠습니다.[질문 3번]"},{"q":"ESG 경영에 대해서 많이 한 게 보이는데, ESG 중에서 가장 중요한 게 뭐라고 생각해요?","a":"ESG 모두 경영에 있어서 매우 중요하지만, 저는 지배구조가 가장 중요하다고 생각합니다. 지속 가능한 경영을 위해서는 기업 내부가 청렴해야 하고, 주주에게 이익도 많이 환원하고 전문 경영인을 통해서 기업이 부패하지 않게 유지하는 것이 가장 기본적이고 중요한 부분이라고 생각하기 때문입니다."},{"q":"1분 정도 남았는데 마지막으로 하고 싶은 말 있으면 해보세요.","a":"일단 제 이야기를 끝까지 경청해 주셔서 정말 감사드립니다. 저는 서울대학교 자유전공학부에 입학하여 교수님들, 그리고 학우들과 주제 탐구 세미나 시간에 참여하여 다양한 주제를 다양한 관점으로 토론하면서 학문 간의 경계에 구애받지 않는 융합적인 공부를 꼭 해보고 싶습니다. 또 환경 정책과 인권 문제에 대한 것을 대학교에서 학문적으로 같이 공부하면서 ESG 경영을 전문적으로 하는 경영인이 되고 싶습니다. 정말 열심히 탐구할 자신이 있습니다! 감사합니다.면접실이 협소했고 면접관과의 거리가 생각보다 가까워서 조금 더 편안한 분위기였음.특이점생각보다 무거운 분위기가 아니었고 웃으면서 하는 면접.합/불 분석아쉬운 점답변 말하고 다른 생기부 활동과 관련지어서 보충 답변 했으면 더 좋았을 것 같음."}],"naesin":"1.33","result":"충원합격","resultNote":"최초후 1 보순위","suneung":"최저충족","type":"일괄합산( ) 단계형( ○ ) 【1단계】 서류100(3배수) 【2단계】 1단계70+면접30","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"서울대학교","dept":"자유전공학부","jeonhyeong":"학생부종합/지역균형전형","method":"학교생활기록부 기반 면접 / 다수의 평가자에 의한 다단계 종합평가","notes":"","qa":[{"q":"지원 동기를 말해주세요.","a":"저는 고등학교 3학년 때 제 고장의 인구 감소 문제에 대한 정책 제안서를 작성하는 활동을 했습니다. 이 활동을 통해 제가 지역 사회의 문제를 외부에서 바라보는 것에서 끝나지 않고 그 문제를 해결하는데 보탬이 될 수 있다는 가능성을 발견하게 되었습니다. 이후로 지역 활성화를 도울 수 있는 로컬 콘텐츠 개발자라는 꿈을 가지고 다양한 탐구 활동을 펼쳤습니다. 하지만, 하나의 학문으로는 지역 문제의 근본적인 해결/지역 활성화가 어렵고 지역에 대한 관심, 콘텐츠 기획에 대한 이해뿐만 아니라 공공정책학, 행정학 등 다양한 학문의 융합이 필수적임을 알게 되었습니다. 이러한 깨달음을 바탕으로 학문의 지리적 경계를 뛰어넘는 학제적 사고를 키우고자 서울대학교 자유전공학부에 지원하게 되었습니다."},{"q":"자유전공학부에 와서 어떤 과에 가고 싶은지?","a":"제가 자유전공학부에 입학하게 된다면, 학생 설계 전공과정을 통해 도시학과 경제학, 공공정책학 등을 함께 배울 수 있는 도시 사회학 수업을 개설하여 도시 브랜딩에 대해 체계적으로 배우고 싶습니다. 저는 3학년 영어권 문화 수업에서 미국의 볼티모어가 야구장 개장을 통해 범죄도시에서 스포츠 도시로 이미지 쇄신에 성공한 사례를 조사한 적이 있었습니다. 이때, 저는 도시의 이미지가 관광객 유입, 일자리 창출 등 지역에 미치는 영향력이 크다는 것을 알게 되었습니다. 이를 계기로 제가 사는 지역을 리브랜딩 하고 싶다 생각해 직접 스포츠 명문 도시 OO시라는 테마로 우리 지역을 홍보해보면 어떨까? 하고 관련 영상을 제작해 보았습니다. 해당 영상에서는 경기 장면뿐만 아니라 팬들의 응원하는 모습을 담았으며 이 과정을 통해 저는 도시 이미지가 단순히 지역에 대한 외부인 / 타지인의 관심을 환기하는 것 뿐 아니라, 지역 내 거주민들의 자부심과 공동체 의식을 강화하는 방식으로서 존재 한다는 것을 깨달았습니다. 이때의 흥미를 바탕으로 대학에 입학해서는 도시 이미지가 주민들의 소속감을 어떻게 촉진하는지와 도시브랜드를 구축하는 과정에 대해 체계적으로 배우고 싶습니다."},{"q":"들어보니 지역 도시를 위해서는 여러 학문이 필요해서 자유전공학부에 지원했다는 것 같은데, 우리나라는 서울에 사람이 많이 살잖아요. 서울에 이사를 가고 이런것들은 개인의 선택인데, 문제가 있을까요?","a":"네, 물론 서울에 이사를 가는 개인의 선택에 대해 비판을 가할 수는 없습니다. 하지만, 이런 수도권 과밀화 및 지방 소멸은 국가적 차원에서 불균형으로 이어지고, 이러한 불균형은 민족 공동체의 와해를 유발합니다. 국민들은 자신을 국가의 일원으로서가 아니라 지역적인 집단으로서 인식하게 될 가능성이 커집니다. 이는 민족 공동체의 결속력을 약화시키고, 민족적 통합이나 국민적 연대의 감각을 둔화시킬 수 있습니다. 또한, 수도권에 인구와 자원이 집중되면 지방은 점점 더 소외되고, 지방 주민들은 자신들이 국가 발전에서 제외된 느낌을 받을 수 있습니다. 이는 \"우리나라\"라는 집단 정체성을 약화시키고, 각 지역이 자기 지역 우선주의나 지역주의를 강화하는 결과를 초래할 수 있습니다. 만약 이럴 경우, 국가적 차원에서의 큰 문제가 발생했을 때 연대를 통해 해결할 수 있는 가능성이 적어진다는 점에서 문제라고 생각합니다."},{"q":"근데 이제 미국은 땅도 크고 주 단위로 나라가 운영이 된다하지만 우리나라는 되게 작잖아요? 그런데도 지역이 필요하나요?","a":"우리나라는 영토가 작지만, 꼭 필요하다고 생각합니다. 앞서 말씀드렸듯이, 국가적 차원의 큰 문제가 발생했을 때 ‘국민’이라는 이름으로 연대하여 해결하는 것은 중요합니다. 예컨대, 우리나라가 과거 외환위기를 맞았을 때 대한민국 국민이라는 정체성을 토대로 금 모으기 운동을 진행했었고, 그러한 연대 덕분에 국가 위기를 빨리 해결할 수 있었습니다."},{"q":"민족 정체성 이야기하셨는데, 관련한 활동이 있더라고요? 코즈모폴리터니즘에 대한 보고서를 쓰셨다던데 내용이랑 느낀점을 이야기 해주세요","a":"네, 제가 평소에 생각해오던 세계시민주의는 다른 나라의 일을 우리나라의 일처럼 여기는 것이었습니다. 하지만 1학년 일본 고교 교류 프로그램을 통해 같은 동아시아 문화권, 지리적 인접 국가임에도 사고관과 가치관에 큰 차이를 보이는 것을 보고 과연 제가 생각하던 세계시민주의가 가능할까? 하는 고민에 탐구를 시작했었습니다. 저는 ‘코즈모폴리터니즘이란 무엇인가’라는 책을 참고해서 세계시민주의로 대표되는 코즈모폴리터니즘의 필요성에 대해 정리했습니다. 이후, 진정한 세계시민주의가 되기 위해서는 교내 세계시민 교육의 방향이 바뀌어야 한다고 생각했습니다."},{"q":"그렇다면 난민을 대함에 있어서 지역은 어떤 대처를 보여야할까요?","a":"우선, 난민을 수용하자/수용하지말자 이야기를 하기 앞서 난민을 수용할 수 있는 환경이 마련되어야 한다고 생각합니다. 여기서 말하는 환경은 단순히 행정적 인프라만을 말하는 것이 아니라, 우리의 인식도 포함됩니다. 얼마 전 국내에서도 난민 수용을 두고 의견이 분분했습니다. 저는 이것이 아직 국내가 난민 수용의 환경이 잘 마련되지 않아서 생긴...(시간이 되어 면접 종료)"},{"q":"마지막으로 하고싶은말 있으시면 하세요","a":"네, 저는 앞서 말씀드렸듯이 자유전공학부에 입학하면 꼭 지역 브랜딩에 대해 배우고 싶습니다. 저는 해당 홍보영상을 만드는 활동에서 이미지를 만들어가는 스토리텔링에 정말 큰 흥미를 느꼈습니다. 이때의 흥미를 바탕으로 꼭 도시 이미지를 구축해가는 브랜딩 과정과 이것이 지역 거주민의 소속감에 미치는 영향에 대해 배우고 싶습니다. 이상입니다. 감사합니다.총 4개의 면접실이 있으며, 앞 면접자의 내용이 잘 들림. 면접실에는 2명의 교수님이 계시특이점고 10분의 시간을 정해 놓고 면접을 봄. 3분, 1분의 시간이 남으면 노크로 알려주고 10분의 면접 시간을 넘기려 하지 않으려고 함.학교생활기록부의 전체적인 주제와 방향를 먼저 정한 후, 면접 준비와 예상 답변을 구상하합/불 분석였던 것이 많은 도움이 되었음.아쉬운 점생기부에 기재된 도서의 내용을 답변에 녹이지 못한 점이 아쉬웠음."}],"naesin":"1.02","result":"최초합격","resultNote":"최초후보순위","suneung":"최저충족","type":"일괄합산( ) 단계형( ○ ) 【1단계】 서류100(3배수) 【2단계】 1단계70+면접30","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"서울대학교","dept":"재료공학부","jeonhyeong":"학생부종합/지역균형전형","method":"서류(생기부) 기반 면접 / 1인당 10분, 교수님 2분과 진행","notes":"출석체크 후 면접번호를 부여받고 나면 서류를 보는 등의 행위 불가능 [질문 내용1]","qa":[{"q":"위 학부(재료공학부)에 지원하게 된 동기를 말씀해주세요.","a":"다양한 분야에 관심이 많은 학생으로 빛에 대한 탐구에서 시작해 촉매와 관련한 활동을 진행했습니다. 또한 수소연료전지와 항산화제 관련 연구 활동은 특히 기억에 남습니다. 이러한 다양한 관심사에 대해 '소재'라는 키워드를 잡았고, 특히 서울대학교 재료공학부 홈페이지에서 본 '재료공학은 모든 학문의 근간이 되는 학문이다.'라는 것에서 더욱 실마리를 잡을 수 있었습니다. 특히 앞서 말한 제 활동이 재료공학이 나아갈 촉매와 바이오 분야에 특히 도움될 수 있을 것이라 생각하여 지원하였습니다.[질문 내용2]"},{"q":"다양한 실험을 했다고 하셨는데 정말 그렇네요. 수소연료전지와 관련해서 연구를 했다고 나와있는데 실험을 한 이유가 무엇이고 어떤 실험인지 설명해주세요.","a":"이 실험을 한 계기는 수소연료전지에서 흔히 사용되는 백금촉매의 한계성 때문입니다. 다른 촉매가 더 활성을 나타낼 순 없는지 탐구하기 위해 진행하였고, 이 실험은 촉매의 활성을 평가하기 위한 실험으로 금속결합을 하고 있는 구리봉과 공유결합을 하고 있는 숯과 샤프심을 촉매로 정해 가설을 세워 각 촉매의 활성을 평가하고 그 이유를 찾았던 실험입니다."},{"q":"그럼 그 가설은 뭐였나요?","a":"구리봉의 크기를 두 가지로 설정했던 것과 관련하여 가설을 세웠습니다. 가설을 세울 당시는 단면적이 큰 구리봉이 표면적이 크므로 활성이 높을 것이라 예상합니다. 하지만 실제 실험에서는 반대의 결과를 확인했습니다. 이에 대한 분석으로 전류밀도라는 개념을 통해 해석했습니다. 전류밀도란 전류가 오히려 단면적에 반비례한다는 것으로 이를 통해 결과를 분석할 수 있었습니다."},{"q":"그럼 여태까지 계속 촉매와 관련하여 이야기하고 있는데 촉매에 특히 관심이 있는 이유가 있는지?","a":"공학에서 가장 중요하다고 생각하는 효율과 가장 밀접한 분야라고 생각하기 때문입니다. 공학이 효율을 통해 사람들에게 필요한 것을 만들어내듯이 촉매도 반응 속도에 영향을 미쳐 효율을 추구하는 것 같습니다.[질문 내용3]"},{"q":"또한 항산화 관련 연구에서 사과의 유해성 평가를 진행했다는데 이에 대해 설명해주세요.","a":"그 실험은 2학년 때 진행했던 DPPH assay의 실험의 연장선입니다. 작년의 실험에서 사과가 가장 활성이 높았다는 연구 결과를 얻었고 이를 기반으로 사과를 선정하여 실험했습니다. 사과 시료를 처리한 곳과 처리하지 않은 곳을 대조해보니 그람음성균, 그람양성균과 관련해 그람음성균이 사과 시료에 의해 없어진 것을 알 수 있었고 이에 대한 이유를 두 균의 대표적 차이인 펩티도글리칸 층을 근거로 해석했습니다."},{"q":"그럼 그 그람음성균과 그람양성균은 직접 배양한 건가요?","a":"네. 학교의 물리실과 화학실의 세균을 채취해 직접 배양해 사용했습니다.[질문 내용4]"},{"q":"통합과학 시간에 주기율표를 새로운 경향에 따라 새로 만들었다고 되어 있는데 어떤 활동이었는지 설명해주세요.","a":"다양하게 생각해 보았습니다. 원래의 주기율표는 금속, 비금속, 준금속에 대한 명확한 구역이 나누어져있지 않습니다. 이를 보완해 차례대로 금속, 비금속, 준금속을 배열해 보았습니다. 또한 '일상생활에서 가장 많이 사용되는 원소가 뭐라고 생각해?'라는 질문을 바탕으로 각자 주기율표를 작성해보고 의견을 공유하는 시간 가진 활동이었습니다.[질문 내용5]"},{"q":"(2분 남았다고 밖에서 노크하심) 리더십을 보여준 경험이 있다면 빠르게 말씀해주세요.","a":"1.2.3학년 모두 학급 부반장 맡았습니다. 특히 의견차이가 생겼을 때 중재안을 내놓는 등의 경험이 있습니다. 또한 동아리부장으로서 학교에서 전체적으로 진행하는, 전체 학생 대상으로 한 프로젝트를 맡은 적이 있는데 이와 관련해 소통의 과정에서 리더십을 보일 수 있었습니다.[질문 내용6]"},{"q":"10년 후 무엇이 되고 싶나요?","a":"멘토연구자가 되고 싶습니다. 제가 생각하는 멘토연구자란 신입 연구원과 활동적으로 소통하고 새로운 기술을 가감없이 받아들이는 연구원입니다.(여기까지 말하고 문열림.)밖에서 진행요원분께서 면접 시간이 2분 남았을 때 노크하시고 면접 시간 10분이 끝나면 문을 그냥 여셔서 답변 중이었어도 중단하고 나와야 함. 공과대학 교수님의 1인 사무실을 특이점면접실로 사용해서 바로 앞에서 얼굴 마주보며 면접. 무거운 분위기는 아니고 중간중간 고개도 끄덕이시며 학생이 하는 말을 잘 들어주시는 분위기. 합/불 분석아쉬운 점"}],"naesin":"1.17","result":"불합격","resultNote":"최초후보순위","suneung":"최저충족","type":"일괄합산( ) 단계형( O ) 【1단계】 서류100(3배수) 【2단계】 1단계70+면접30","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"서울대학교","dept":"첨단융합학부","jeonhyeong":"종합/기회균형","method":"생기부 기반 면접 / 면접관3명에 학생1명,","notes":"꼬리질문을 많이함. 문이 열리면 면접 종료","qa":[{"q":"첨단융합학부는 융합형 인재를 기르는 곳인데 융합형인재가 갖춰야 할 역량이 무엇이라고 생각하나요? 그리고 자신이 융합형 인재로 성장할 수 있다고 생각하나요?","a":"융합형 인재로서 가장 필요한 역량은 소통력이라고 생각합니다. 저는 고등학교 1학년, 반장을 한 경험이 있습니다. 반장을 하면서 아이들의 의견을 하나하나 듣고 최대한 모두가 만족할 수 있는 의견을 수립하려고 했습니다. 이때의 경험으로 키운 소통력을 이용하여 저는 융합형 인재로 성장할 수 있다고 생각합니다."},{"q":"그래요? 그러면 그러한 역량이 가장 필요한 문제는 뭐라고 생각해요?","a":"한 분야의 전공에만 치우쳐있지 않아, 서로 소통하며 협력하는 그러한 공동의 문제, 다양한 전공에 걸쳐져 있는 문제가 발생했을 때 가장 필요하다고 생각합니다."},{"q":"그러면 고등학교 때 실제로 그러한 사회적인, 공동의 난제를 해결하기 위해서 노력했던 경험이 있나요?","a":"네 있습니다. 학년특색활동을 진행했었습니다. 서로 다른 관심분야를 가진 학생들이 모여 지역사회의 문제를 해결하려는 활동이었습니다. 어촌 지역에 요즘 소통의 부재와 젊은 사람들의 일자리가 부족해지고 있는데, 이 문제를 해결하기 위해서 스마트 섬이라는 것을 만들어 해결하려 했습니다."},{"q":"맡은 역할은?","a":"저는 스마트섬이다보니 전력의 문제가 심하여 태양전지의 효율을 높이는 방안을 고안하였습니다. 기존의 태양전지 대신 퀀텀닷을 이용한 태양전지를 활용하여 전력효율을 올리려고 했습니다. (다음질문이 더 있었으나 3분이 끝나 문을 두드림. 생기부 질문으로 넘어감)"},{"q":"과학과제연구, 물리학실험, 인공지능 수학 등 되게 소인수 과목을 수강하셨던데 그 동기가 무엇인가요?","a":"반도체에 관심이 생기면서 물리학실험을 수강하며 물리적 역량을 기르려고 했습니다. 데이터 시트를 만들면서 최소제곱법이 사용된다는 것을 알게 되었고 그러한 최소제곱법을 탐구하기 위해 인공지능 수학을 수강하게 되었습니다."},{"q":"과학과제연구 내용을 보니까 꽤 어려운 걸 다루었는데 탐구하면서 어려웠던 점은? 그리고 어떻게 극복했는지","a":"(긴장해서 대답을 제대로 못했습니다.) 저는....양자역학을 다루다 보니까 처음에는 직관적으로 이해가 되지 않았지만, 양자역학의 역사를 탐구하면서 이해도를 깊게 만들었습니다. <어떻게 극복했는지.>어..여러 자료들도 찾아보고 막히는 게 있으면 선생님께 적극적으로 찾아가 해결했습니다(ㅜㅜㅜ...)"},{"q":"3학년 물리 동아리를 보니 탐구활동을 했는데, 이런 조사 같은 거 말고 실제로 실험활동을 수행한 적 없는지?","a":"네 있습니다. 2학년 때 해파리 흡수율 실험을 진행했었습니다. <진행하면서 어려웠던 점 있나요?> 어..실험을 진행하기 위해선 고가의 실험장비가 필요했었는데 그러지 못했던 점입니다. <어떻게 극복?> 해파리를 동결건조 시켰어야 했는데 동결건조장비가 없어 불가피하게 다른 방안으로 대신했습니다.특이점수학 관련 성적이 모두 1등급우수한 수학, 물리학 성적합/불 분석이를 뒷받침하는 교과세특에서 우수한 자기주도적 역량늦은 진로 선택임에도 불구하고 뛰어난 진로 관련 심화탐구아쉬운 점늦은 진로 선택으로 3학년때만 거의 대부분이 진로 관련 탐구로 진행"}],"naesin":"1.53","result":"최초합격","resultNote":"최초후보순위","suneung":"최저기준없음","type":"일괄합산( ) 단계형( ○ ) 【1단계】70% 【2단계】30%","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"서울대학교","dept":"통계학과","jeonhyeong":"학교장추천전형/지역균형","method":"생기부 기반 대기실에서 대기 → 이전 면접자 끝나기 2분 전 면접실 밖에서 대기 → 10분 가 / 량 면접","notes":"","qa":[{"q":"통계학과에 지원한 이유는?","a":"4차 산업혁명 시대에, 저희 삶은 빅데이터, 인공지능과 매우 밀접해 있습니다. 이런 기술들은 가치 있는 데이터를 찾아내, 활용 목적에 맞게 잘 이용하는 것이 중요합니다. 이러한 안목을 배울 수 있는 곳은 통계학과라고 생각하여, 서울대학교 통계학과에 지원하게 되었습니다."},{"q":"통계학과에 입학하여 어떤 방향으로 진로를 희망하는지?(해당 질문에 대한 답변은 구체적으로 기억나지 않아 세부적인 내용은 다를 수 있음.)","a":"전 인공지능, 데이터 마이닝 분야에 관심이 있습니다. (여기서, 내가 그런 분야 위주의 활동을 뉘앙스의 말을 했던 것으로 기억함) 하지만 통계학엔 통계적 방법론을 다루는 분야 역시 있는 것을 알고 있습니다. 그렇기에 저는 서울대학교 통계학과에 입학하여 두 분야를 모두 공부해 본 후 진로 재탐색을 하려 합니다."},{"q":"가치 있는 데이터라고 했었는데, 그럼 가치 있는 데이터는 어떻게 판단하나요?","a":"주관이 개입할 것 같습니다. 여러 논문, 자료 등과 비교해보며 신뢰할 만한 자료인지 판단해야 할 것입니다. 또 데이터가 한 쪽으로 편향되어 있지는 않은지 등을 검토해야 할 것 같습니다."},{"q":"만약 데이터가 원래 편향된게 맞다면?","a":"(당황)...잠시 생각할 시간을 주셔도 괜찮겠습니까?몇 초 시간이 흘러도 답이 나오지 않자"},{"q":"다른 질문으로 넘어가겠습니다. 수2 활동에서 경사하강법이 나왔는데, 자신의 언어로 설명해 보세요.","a":"인공지능에 대해서는, 오차, 즉 다른 말로 손실을 줄이는 것이 중요합니다. 혹시 제스쳐를 좀 취해도 괜찮을까요? (네 가능합니다) x축 y축 좌표평면에 손실함수가 이렇게 생겼다고 해 보겠습니다. 손실을 최소화하는 것이 중요하기에, 여기 이 최솟값을 찾아야 합니다. 미분값이 음수라면 감소함수니, 해당 점이 오른쪽으로 이동하면, 증가하면, 그러니까 x축 방향으로 이동하면 함수값이 감소하게 됩니다. 미분값이 양수라면 그 반대가 됩니다. 이를 통해 미분값이 0인 최솟값을 찾을 수 있게 됩니다."},{"q":"경사하강법이 적용이 안 되는 경우도 있는데, 그럼 어떤 경우에 경사하강법을 적용할 수 있을까요?","a":"(음...우물쭈물...) 미분 같은 계산이 용이한 경우... (교수님: 아까 예로 들었던 그런 경우?) 네, 그런 경우에 적용할 수 있을 것 같습니다."},{"q":"경사하강법이 전역 최솟값이 아니라 다른 곳에 빠질 수 있는데, 어떻게 해결할 수 있을까요?","a":"그때 조사를 해 봤을 때, 확률적 경사하강법이란 것이 있었습니다. 점이 한 번에 이동하는 이동 거리를 조절한다면, 전역 최솟값이 아닌...다른 구덩이에 빠지더라도 진동하며 빠져나와 최솟값에 도달할 수 있습니다."},{"q":"통계와 미래 활동에서 확률적 모델을 설명했다고 했는데, ‘확률적’이란게 어떤 것이었는지 설명해 줄 수 있나요?(저런 느낌이었던 것 같긴 한데 질문이 정확히 기억나진 않음. ‘확률적‘ 이란 용어에 주목해서 질문하심.)","a":"우선 해당 자료에서 연구자들은 O*NET에서 702개의 직업 리스트를 사용했습니다. 여기서 제가 인상깊었던 것은 데이터의 처리 과정에 주관이 개입했던 것입니다. 데이터 중 전산화, 즉 컴퓨터에 대체될 가능성이 확실한 직업에는 1이란 라벨을, 확실히 대체되지 않을 직업에는 0이란 라벨을 붙였습니다. 이렇게 총 70개의 직업에 라벨을 붙였는데, 여기서 제가 정말 인상깊었던 것은, 로지스틱 모형을 사용해서 이렇게 라벨을 부여한 것이 얼마나 적절한지 검토했던 것이었습니다. (그 다음에 뭐라고 더 말했던것 같은데 기억이 안 남. 주관을 최소화하는 그런 방식이 인상깊었다...이런 식으로 말했던 것 같음.)"},{"q":"간단히 말해서 로지스틱 모형에서 확률적인 개념이 사용되었다는 거군요?","a":"네 맞습니다."},{"q":"데이터에 주관이 개입되었다는게 무슨 말인가요?","a":"아까 말씀드린 702개의 직업에 라벨을 매기는 것이었습니다. 전체 직업에 라벨을 붙인 게 아니라 여러 연구원 그룹들이 세미나 등에 참여하며 확실히 전산화 될 직업엔 1, 확실히 대체되지 않을 직업엔 0이란 라벨을 총 70개 부여했습니다. (이 다음에 또 주관 최소화 얘기 꺼냈는지는 잘 모르겠음.)내 자리에도 책상 있었음. 그래도 책상 밑 가림막이 그렇게 길진 않아서 다리를 떨거나 하면 잘 보일 것 같았으니 바른 자세 연습 필요함. 교수님들 테이블과 책상이 붙어있진 않았고, 특이점책상 1개 정도의 간격 있었음. 교수님 2분. 기본적으로 무표정 유지하셨지만 나름 웃으며 대화하는 분위기였던 것으로 기억함.합/불 분석최초합아쉬운 점내게 유리한 방향으로 면접을 이끌고 가기보단 교수님의 질문에 끌려간 경향이 강했음."}],"naesin":"","result":"최초합격","resultNote":"최초후보순위","suneung":"최저충족","type":"일괄합산( ) 단계형( ○ ) 【1단계】 서류 100(3배수) 【2단계】 1단계 70 + 면접 30","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"서울대학교","dept":"화학교육과","jeonhyeong":"학생부종합/지역균형전형","method":"학교생활기록부 확인 면접 / 지역균형전형, 기회균형전형 함께 면접 실시","notes":"10분, 대기시간 동안 자료 볼 수 없음.","qa":[{"q":"EDTA 실험 과정에 대해 말해보세요","a":"측정하고자 하는 물을 50ml 가량 넣습니다. 그 후에 암모니아 완충 용액과, 에리오크롬 블랙티라는 지시약을 넣습니다. 그 후 EDTA 용액을 한 방울씩 넣어주며 에리오크롬 블랙티가 변색하는 지점을 파악하여 사용된 EDTA 용액의 부피를 이용하여 물의 경도를 계산합니다."},{"q":"꼬리: 암모니아 완충용액을 넣는 이유는?","a":"pH를 10으로 맞춰줘야 하기 때문입니다."},{"q":"pH를 왜 맞춰주어야 하는지?","a":"pH가 너무 낮다면, 수소 이온 농도가 높아, EDTA가 수소 이온과 결합하여 정확한 결과를 얻을 수 없고, pH가 너무 높다면, 탄산이온이 침전되기 때문입니다."},{"q":"수소이온이랑 결합하면 왜 정확한 결과를 얻을 수 없죠?","a":"물의 경도를 측정하는 것이 칼슘이온이나 마그네슘이온과 같은 금속이온들을 측정하기 위함인데, EDTA와 수소이온이 결합하게 된다면, EDTA가 모든 금속이온과 결합하기 위해서는 더 많은 부피의 EDTA가 들어가게 되어 수식 상에서 EDTA 부피 값이 커져 실제 값과는 다른 값이 나올것이라 생각합니다."},{"q":"1학년 때 수학 멘토링 한 것에 대해 말해보세요","a":"당시 저희 반에 수학이라는 과목에 관심이 없는 학생들이 많았습니다. 저는 비교적 수학을 좋아하는 학생이었기 때문에 친구들의 수학이라는 학문에 대한 관심을 높이고자 하는 목적으로 멘토링을 하게 되었습니다. 단순한 지식 전달이 아닌, 학습 목표나 당위성을 스스로 알게 함으로써 체계적인 지식전달을 하려 노력하였습니다."},{"q":"요즘 교권추락과 관련하여 교사하려는 경향이 적은데 왜 지원한건지?, 어떻게 교육할 것인지?","a":"우선 최근 악성민원으로 인해 큰 문제가 발생한 사실을 알고 있습니다. 이에 미리 방지하기 위하여 모든 학생들을 최대한 평등하게 대우할 것입니다. 또한 저의 교육과정이나 신념들을 학부모들과 정기적으로 공유하는 방식으로 진행할 것 같습니다."},{"q":"꼬리: 신념이 무엇인데요?","a":"저의 신념은 교과서에만 나오는 딱딱한 내용을 공부하기 보다, 실험이나 융합을 통하여 학생들이 유연한 사고를 할 수 있게 하는 것입니다. 직접 실험을 하거나 다른 과목과의 연계성을 생각한다면 스스로 유연하게 생각할 수 있게 될 것입니다."},{"q":"1학년 때부터 지금까지 진로가 계속 변해온 거 같은데, 변해온 과정을 말해보세요.","a":"처음에는 환경에 관심이 많았으나, 저 혼자만의 힘으로는 부족하다는 것을 깨닫게 되었고, 과학을 대중화하는 것을 목표로 하여 사람들에게 체계적 지식 전달을 하기 위하여 화학교육과에 지원하게 된 것입니다.특이점사범대이기에 전공과목과 교직에 대한 인적성 관련 질문이 있음.합/불 분석진로희망이 화학교사는 아니지만, 면접에서 화학교육이 필요한 당위성을 적절히 표현함.아쉬운 점없음."}],"naesin":"2.02","result":"최초합격","resultNote":"최초후보순위","suneung":"최저충족","type":"일괄합산( ) 단계형( ○ ) 【1단계】 서류 100%(3배수) 【2단계】 1단계 70% + 면접 30%","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"서울대학교","dept":"국어교육과","jeonhyeong":"학생부종합(기회균형특별전형)","method":"대기실 → 복도 대기(5분) → 면접장(생기부 기반 면접) / 면접시간 10분 내외 / 면접위원 2명","notes":"압박 면접 분위기에 주눅들지 않는 연습을 많이 했는데, 이와 완전히 반대로 너무 부드럽게 “음~”, “어~” 해주시면서 계속 들어주셔서 오히려 당황했습니다. 면접장도 학과장실 같은 데서 본 것 같은데 분위기가 좋으니 딱딱하게 이야기하지 않고 계속 풀어가면서 지나치게 길게 이야기해 아쉬움이 남습니다. 계속 들어주신다고 계속 이야기하지 말고, 적당히 끊어서 1분 내외로 답변하는 연습하세요! · 8시 30분 정도에 모든 짐(자료, 외투, 가방 등 : 신분증, 수험표 빼고 전부)을 제출하고 대기했습니다.(물은 요청하면 한 병 주심) 면접 순번을 미리 알 순 없고, 자기 순번 5분 전에 관리원분께서 부르시면 복도로 나가서 대기하는 시스템이었습니다. 17번째로 3시간 대기했는데 그 시간 동안 속으로 헷갈렸던 답변 연습을 하며 긴장을 풀어서 오히려 좋았습니다. 앞 순번은 일찍 끝나니 좋은 거고, 뒷 순번은 여유있게 마음의 준비를 할 수 있어 좋으니 순서에 연연하지 말고 답변 내용에만 집중해 준비하세요! · 활동의 기승전결을 묻는 것과 더불어 정말 이 주제에 관심을 가지고 있는 학생인지 묻는 것 같다고 느꼈습니다. 모든 활동 과정을 다시 복기하고 외우는 것은 당연하고, 생기부에서 두드러지는 활동 및 적어도 관련 계열의 활동은 정말 진실하게 관심을 가지고 배경지식을 쌓고 면접장에 들어가시길 권유드립니다!","qa":[{"q":"1학년 때 영어로 글쓰기한 게 되게 재밌었어요~ 재능과 운의 요소가 둘 다 중요하다는 글을 썼는데 조금 더 자세하게 설명해주세요.","a":"1학년 때 친구를 보고 적었던 글이었습니다. 그 친구는 공부를 하고 싶은데 계속 잠이 온다고 이야기해서 구체적인 방안과 동기부여를 자주 해주었는데 (이 부분도 지나치게 풀어서 이야기해 아쉬움이 남음) 그런 모습을 보면서 노력을 하는 데 타고나는 기질적인 특성과 동기부여를 받을 수 있는 환경 등의 요소도 중요하다고 깨달아 쓴 글이었고 내 자신을 겸손하게 돌아보게 되는 활동이었습니다."},{"q":"교육학 시간에 인쇄 기반 문화에서 디지털 기반 문화로의 전환 과정에서 뇌의 읽기 회로가 변한다는 내용으로 수업 시연을 했다고 하는데, 구체적으로 읽기 회로가 어떻게 변하는지 구체적으로 설명해주세요.","a":"기본적으로 인쇄문화는 상호 소통이 아니라 독자가 주체적으로 이해해야 하기 때문에 내용이 일목요연하고 체계적일 수밖에 없고, 디지털 기반 문화는 영상 매체인데 영상 매체는 추상적인 내용을 구체적으로 이야기하기 때문에.. (이 답변하는데 이해가 안 되는 듯한 표정이셔서 예를 들어 덧붙여 설명함 ) 깊이 읽기가 어렵습니다. 때문에 뇌가 깊이 읽기에 익숙하지 않게 되고 이런 뇌를 가지고 인쇄 매체로 글을 읽을 때 일목요연하고 체계적인 글을 흡수하는 능력이 떨어지기 때문에 문해력이 현재 문제가 되고 있습니다."},{"q":"요즘 문해력이 글을 읽는 개념에서 영상을 보는 능력으로 개념이 바뀌고 있다~ 이런 이야기도 있는데 이거에 대해선 어떻게 생각하세요?","a":"문해력의 궁극적인 목적은 세상을 이해하고 사고를 확장하기 위해 매체를 이용하는 것이라고 생각합니다. 때문에 읽고, 말하는 능력에서 더 나아가 보고, 듣는 것까지 포함해 리터러시의 개념으로 확장해 문해력을 바라보아야 하고, 문해력이 좋다, 나쁘다의 기준은 세상을 이해하고, 사고를 확장하는 데 적절한 매체를 얼마나 잘 활용하느냐가 기준이 되어야 한다고 생각합니다."},{"q":"학생 생기부를 읽어보니까.. 뭐에 관심이 있는지 잘 나타나 있는 것 같아요. 능력주의나 문해력 같은.. 3학년 때 시험능력주의와 관련한 활동을 했는데 현재 우리 사회에 나타나는 능력주의도 있잖아요? 사회의 능력주의가 나타나는 원인이 뭐라고 생각하는지, 그리고 이를 학교 측면(교육측면이라고 하신 것 같기도 한데 기억이 잘 안 남 )이 아니라 사회 측면에서 어떻게 보완해야 한다고 생각하는지 말씀해 주세요.","a":"잠시 생각할 시간을 주시겠습니까? -> 네~ -> 체감 상 10초 ~ 20초 정도 생각한 것 같음.현재 한국 사회에서 능력주의가 심한 원인은 학력주의 때문이라고 생각합니다. 이 학력주의가 나타난 데엔 수능이 중요한 요소가 되는데 수능은 단일한 가치로 사람을 판단하고 그 결과가 중요시되는 사회 속에서 청소년 시기 학생들이 성공과 실패의 경험을 한다고 인식합니다. 그런 생각들이 청소년기에서 성인기로 넘어 갈 때 너무 중요하게 각인 돼서 사회에 능력주의가 만연해진다고 생각합니다.그리고 능력주의 사회를 보완하기 위해선 문화적 차원의 정부 지원이 있어야 한다고 생각. 경제적으로 부유한 집안과 아닌 집안에서 문화적 지원은 부모가 해줄 수 있는 한계가 있기 때문에.. (이 뒤로 계속 설명했는데 결론을 어떻게 지었는지 기억이 안 남) -> 이 답변하면서 밖에서 노트 소리가 나서 시간이 거의 다 됐다는 걸 알게 됨.)"},{"q":"그럼 그 과정에서 발생할 수 있는 차별이나 혐오 문제는 생각해 봤나요? 빨리, 짧게!","a":"어.. (노크 소리 들리고 빨리, 짧게 말하라고 하셔서 당황함, 한 5초 ~ 10초 정도 당황해서 면접관분들 번갈아가면서 바라봤던 것 같음 )"},{"q":"됐어요! 이만 나가봐도 돼요~","a":"(시간이 다 돼서 나가라고 하신 것 같음 -> 인사하고 나옴 )"}],"src":"세종특별자치시교육청 「보인다! 5.0 면접지도 길라잡이」","year":"2024학년도"},{"univ":"서울대학교","dept":"물리 천문학부(물리학전공)","jeonhyeong":"학생부종합(일반전형)","method":"대기실 입실 → 신분확인 → 문제풀이 → 면접 → 퇴실 / 면접시간 15분 / 면접위원 2명","notes":"같은과끼리 대기했음, 시험장 앞에서 선배들이 응원함 · 들어가서 공부 불가라고 할때부터 아무 것도 볼 수 없음. · 핸드폰은 자신이 소지하나 가져온 가방에 꺼서 넣어놔야함. · 일단 답을 맞추는 것이 가장 중요함 · 밖에서 문제를 풀고 들어가는데 면접장 안에서 필기도구를 쓸 수 없고 오직 말로만 설명해야하며 그러므로 추가 질문이 나올 때 필기도구가 없는 것에 당황하지 말 것.","qa":[{"q":"푼 문제부터 답을 부르고 풀이과정을 설명해봐라","a":"1-1은 1번 문제는 포물선 운동을 빗면에서 다루는 문제입니다. 이럴 때 저는 빗면을 기울여 제가 볼 때 수평으로 만들고 중력가속도를 수평성분과 수직성분으로 분해하여 등가속도 운동방정식을 각 방향에 적용했습니다. (적용한 식을 설명하고) 탄성충돌을 고려하니 답이 ~이 나왔습니다.(답이 상수로 숫자였음)1-2은 공을 여기서 굴리면 떨어질 때 속도가 ~가 되는데 그대로 탄성충돌하여 충돌 전, 후 속력이 같고 이를 이용하면 탄성충돌이 원래 가던 방향대로 진행을 시켜보면 더 쉽게 구할 수 있다고 생각했습니다. 그냥 포물선 운동으로 계산하면 ~이 됩니다. (1-3(1),(2)는 잘 기억이 나지 않지만 쉬운 문제였음. (3)이 어려웠음) 포텐셜이 최소인 지점까지 내려가기 때문에 더 운동합니다.1-4은 답만 말함.Q1-1: 조건을 ~로 바꿔서 풀어보세요.(암산으로 풀 수 있는 수준이었음) 답함. (맞은 문제에 대한 추가질문이었던 것 같음.)"},{"q":"2-1번 말해보세요.","a":"전기력, 중력과 전자의 운동량 변화를 구하면 진자의 기울어진 각도를 구할 수 있습니다.이를 이용하여 계산한 과정 식 설명하고 답 말함.(1번은 제시문 관련 없어보였음)"},{"q":"2-2번 말해보세요.","a":"속도는 커지는데 가속도는 작아질 것입니다."},{"q":"2-3번 말해보세요.","a":"제시문을 사용하여 평형식을 세운 과정을 설명하고 계산 과정을 통해 구한 답을 설명함.(2-4번도 마찬가지)]"},{"q":"1-4번 답을 다시 보시겠어요? 답 틀렸죠?","a":"네"},{"q":"풀이를 어떻게 했어요?","a":"풀이과정 설명함."},{"q":"풀이 과정은 맞았는데 왜 틀렸지?","a":"(연필이 없어서 계산을 다시 할 수가 없었음, 많이 당황했음)풀이 과정을 다시 검토함."},{"q":"시간이 남았는데(3분정도 남았던 것 같음) 더 할말 없나요?","a":"문제지 뒤적거림."},{"q":"수고했어요.","a":"감사합니다."}],"src":"세종특별자치시교육청 「보인다! 5.0 면접지도 길라잡이」","year":"2024학년도"},{"univ":"서울대학교","dept":"산업공학과","jeonhyeong":"학생부종합(지역균형전형)","method":"신분확인 → 대기실 입실 후 대기 → 면접 → 퇴실 / 면접시간 10분 / 면접위원 2명","notes":"한 대기실에서 항공우주과 친구들과 같이 대기 · 대기시간동안 자료 모두 못 보고 전자기기 사용 못함. · 제 생기부는 인문학적 소양을 많이 어필해서인지 인문학적 질문을 많이 하셨습니다. 산공과라는 과 자체의 특성을 잘 이해하는 것이 특히나 중요하다고 생각합니다. · 교수님들이 분위기를 편하게 이끌어주시고 압박 질문은 거의 없는 편이었습니다.","qa":[{"q":"산업공학과에 지원하게 된 동기를 이야기해 주세요.","a":"지속가능한 발전이 중요해진 사회에서, 국가와 기업이 인간과 환경을 위하는 일이 중요해졌습니다. 저는 국가와 기업이 인간과 환경을 위하는 방법을 택하려면, 결국 그 방법이 그들에게 경제적으로 이익이 되어야 한다는 것을 깨달았습니다. 따라서 산업의 최적화를 통해 국가와 기업의 변화를 선도하는 산업공학자가 되고자 산업공학과에 지원하게 되었습니다."},{"q":"활동 중에서 ‘실리콘밸리 사람들은 어떻게 일할까’라는 책을 읽고 활동을 했다고 나오는데, 이 책을 설명해보세요.","a":"이 책은 실리콘 밸리의 업무 방식을 이야기하는 책입니다. 우리나라에서는 아직 성취지향적인 성향이 뚜렷하고, 많이 일한 사람이 일을 잘하는 사람이라고 생각합니다. 그러나 실리콘 밸리는 다릅니다. 그들은 짧게 일해도 효율적으로만 일하면 된다고 생각합니다. 그리고 이런 생각을 뒷받침하는 확실한 성과금 제도, 해커톤 문화가 조성되어 있습니다. 이 책을 통해 어떻게 노동생산성을 효율적으로 증대시킬지 고민할 수 있었습니다."},{"q":"본인이 추구하는 본질적 목표가 무엇인가요? (삶의 목표를 묻는 질문이었음)","a":"모든 인간이 그러하듯, 저의 목표는 행복입니다. 인간은 사회적 동물입니다. 인간은 다른 동물처럼 날카로운 이빨을 가지고 있지도 않고, 힘이 세지도 않아서 타인이 없으면 한없이 나약해집니다. 따라서 인간의 행복은 결국 그 인간이 속한 공동체의 행복에서 온다고 생각합니다. 공동체가 행복하려면, 사회적으로 소외 받는 사람이 없어야 합니다. 따라서 저는 사회적 약자를 위한 기술을 연구하는 산업 공학자가 되어야겠다고 생각했습니다."},{"q":"생기부를 보면 스마트시티에 관심이 많은 것 같은데, 스마트시티가 뭐라고 생각하나요?","a":"스마트시티라는 것이 굉장히 추상적인 개념인데요, 저는 기술을 통해 인간의 삶의 질을 향상시키는 도시를 스마트 시티라고 생각합니다. 제가 제시했던 스마트 시티의 비전은 효율적인 도시, 약자를 위한 도시, 친환경적인 도시였습니다."},{"q":"전반적으로 ‘효율’에 관심이 많은 것 같은데, 산업공학자의 기본적인 역량이 뭐라고 생각하나요?","a":"자신이 설계하고 있는 기술 자체에 대한 수리과학적 이해, 데이터 분석을 통해 최적화된 효율적인 해를 찾으려는 노력, 마지막으로 사용자가 그 제품을 어떻게 사용하고 소비할지 인간을 이해하는 태도가 중요하다고 생각합니다."},{"q":"인간에 관심이 많다고 했는데, 인간을 이해하기 위해 어떤 노력을 했나요?","a":"저는 철학이 인간을 이해하는 좋은 방법이라고 생각하여 고전과 윤리라는 과목을 선택하여 수강하였고, 다양한 철학 책을 읽었습니다."},{"q":"그러면 읽었던 철학 책 중에 기억에 남는 책 있나요?","a":"장자입니다. 이 책에서 제가 깨달은 것은 아까 설명한 실리콘밸리 이야기와도 같은 맥락인데요. 장자가 따르는 도가 사상에서는 상선약수, 물과 같이 흐르는 삶을 가장 좋은 것으로 여깁니다. 흘러가는 대로 살고 싶은 것은 인간의 본성일 수 있겠다는 생각을 하게 되었습니다. 따라서 이런 인간의 본성을 잘 이해하여, 노동자에게 적절한 보상과 성과금을 주어 노동 생산성을 증대할 수 있다는 것이 중요함을 깨달았습니다."},{"q":"리더로서 활동한 경험이 있나요?","a":"네, 저는 반장과 동아리장 활동을 했습니다. 스마트 시티 플래너라는 동아리에서 동아리장으로 활동하였는데, 이 동아리는 다양한 공학분야에 관심 있는 친구들을 모아 스마트시티에서 어떻게 인간의 삶의 질을 향상시킬지 고민하는 동아리였습니다. 저는 이 동아리 활동을 통해 각 공학 분야가 어떻게 협력하는지 배웠고, 리더로서 어떻게 구성원들의 능력을 적재적소에 배치하고 협력하도록 이끄는 방법을 배웠습니다. 또한, 노인을 위한 열쇼크 방지 시스템 고안, 친환경 단열재 실험 등을 진행하며 산업공학자로서 추구해야할 가치를 정립할 수 있었습니다."},{"q":"그런 활동을 하는 게 쉽지 않았을 것 같은데, 어려운 점은 없었나요?","a":"실험 설계적인 측면에서 답변 드려도 되겠습니까?"},{"q":"네. 자유롭게 말씀하세요.","a":"친환경 단열재의 효율을 측정할 때, 열 전도가 잘 되는 그릇에 단열재를 설치하여 실험을 진행하였습니다. 그릇 안에 뜨거운 물을 넣고 온도가 하강하는 정도를 측정하는 식으로 실험을 진행했는데, 단열재가 구조적으로 안정적이지 않았기 때문에 저희가 예상했던 것보다 온도가 빠르게 하강하여 비교가 어려웠습니다. 구성원들과 함께 고민하여, 열이 반대로 이동하는 경우를 생각하였고 얼음을 녹이는 방식으로 단열재의 성능을 측정하여 효율을 비교할 수 있었습니다."}],"src":"세종특별자치시교육청 「보인다! 5.0 면접지도 길라잡이」","year":"2024학년도"},{"univ":"서울대학교","dept":"생물교육과","jeonhyeong":"학생부종합(기회균형특별전형)","method":"질문과 답변을 반복하여 구성함. / 면접시간 10분 / 면접위원 2명","notes":"2:1로 진행하였으며 기본적인 질문들이 많았음. · 생기부에 적혀있는 활동 및 내용보다는 교직에 필요한 역량을 자세하게 듣고싶어 하는 분위기였음. · 충분하게 답변 시간을 부여받았으며 면접관들의 리액션이 좋은 편이었음. · 자신의 내용과 활동을 교직관과 연결하여 충실하게 준비하는 것이 필요하다고 생각함.","qa":[{"q":"사범대를 언제부터 희망했나요?","a":"중학교 3학년 때 가정사로 방황하던 시기가 존재하였습니다. 이때 저희 담임선생님께서 그러한 저를 보고 다양한 대화와 상담을 통해서 라포를 형성하셨고 이에 저는 방향성과 앞으로 나아갈 용기릉 얻었습니다. 저는 그러한 선생님을 존경하였고 평소 친구들과 지식을 공유하여 상호 발전하기를 좋아해 교사라는 직업을 희망하였고 이러한 경험이 사범대를 희망하게된 계기가 되었습니다."},{"q":"생물교육과를 졸업하면 어떤 진로가 있나요?","a":"일반적으로는 중등학교 교사가 되어 학교 현장에서 교육을 실천하는 경우가 많을 것이지만 생물 교과다 보니 생명과학 연구원이나 의약계열도 가능할 것입니다. 뿐만 아니라 교육을 현장이 아닌 제도적으로 실현하는 교육과정 평가원이나 교육청의 일도 존재합니다."},{"q":"교사에게 필요한 것은 무엇인가요?","a":"교사는 크게 기본적으로 인성적 부분과 학문적 부분에 대한 역량이 중요하다 생각합니다. 인성적으로는 학생들을 사회 구성원으로서 책임감을 가지고 사회에 동화될 수 있게 하는 것이고, 학문적으로는 단순히 지식을 전달하는 것이 아니라 그 지식을 학생이 자신의 흥미와 적성과 연결하여 지식 기반의 사회적 가치를 창출하는 것이 중요하다 생각한다. 이에 교사는 학생들의 세계에 방향성을 제시할 수 있는 다양한 경험을 하는 것이 가장 필요하다 생각하며 서울대학교에 입학하면 snu in the world와 교환학생, 교육봉사 활동에 참여하여 학생들에게 다양하게 도움을 줄 수 있는 교사가 될 것입니다."},{"q":"생물교사에게 필요한 것은 무엇인가요?","a":"지식기반의 사회적 가치 창출을 학생으로 하는 것이 중요하다 생각하기에 생물교사에게 있어서 학생들에게 다양한 시각울 제공하는 능력을 기르는 것이 가장 필요하다고 생각합니다. 현재의 교육과정이 대입목적에 맞게 유전학에 비중이 많이 가해지고 면역학이나 생태핟에 비중이 많지 않다는 것이 학생에게 미시적 시긱을 기를 기회만 제공하고 거시적인 다양한 시각을 제공할 슈 없는 부분이 아쉬웠습니다. 따라서 학생에게 올바란 시각을 제공할 수 있도록하는 교육과정을 재구성하는 능력도 생물교사에게 필요한 능력이라고 생각합니다."},{"q":"스테로이드의 항상성에 대해서 보고서를 썼는데 무엇을 학습하였나요?","a":"지식기반의 사회적 가치 창출을 학생으로 하는 것이 중요하다 생각하기에 생물교사에게 있어서 학생들에게 다양한 시각울 제공하는 능력을 기르는 것이 가장 필요하다고 생각합니다. 현재의 교육과정이 대입목적에 맞게 유전학에 비중이 많이 가해지고 면역학이나 생태핟에 비중이 많지 않다는 것이 학생에게 미시적 시긱을 기를 기회만 제공하고 거시적인 다양한 시각을 제공할 슈 없는 부분이 아쉬웠습니다. 따라서 학생에게 올바란 시각을 제공할 수 있도록하는 교육과정을 재구성하는 능력도 생물교사에게 필요한 능력이라고 생각합니다."},{"q":"평가지를 만들어 학우분들과 나눴는데 자세히 설명해주세요.","a":"학생들과 배운 내용을 공유하며 상호발전하기를 좋아하여 다양한 평가지를 만들었습니다. 1학년 때는 접할 수 있는 평가도구가 지필고사와 모의고사 밖에 없었기에 현 대입 양식의 평가지를 만들었습니다. 하지만 이러한 양식이 현 교육과정이 요구하는 다양한 요소들을 평가할 수 없다는 것을 알게 되었습니다. 2학년 때는 기존의 방식과 다른 오류 발전 유전 프로그램 평가양식을 만들었고 학생들에게 적용한 결과 긍정적인 반응을 이끌었습니다. 하지만 이 또한 기존 대입 시스템의 내부에서 진행된다고 생각이 되어 3학년 때는 기존에 질적으로 아쉽다고 느껴진 생태학 부분에 대해 독서 논술식 문항을 개발하여 적용해보고 평가 기준까지 새워보았으며 학생들과 오류를 발견하고 토의하며 평가에 대한 이해와 상호발전을 이루어 냈습니다"}],"src":"세종특별자치시교육청 「보인다! 5.0 면접지도 길라잡이」","year":"2024학년도"},{"univ":"서울대학교","dept":"수리과학부","jeonhyeong":"학생부종합(지역균형전형)","method":"대기실 대기 → 순서가 되면 방앞에서 대기→입실 / 면접시간 10분 / 면접위원 2명","notes":"친절한 교수님들이 진행하는 편안한 분위기 · 학문관련된 학과는 교수님들의 전공분야에 따라 질문이 편향될 수 있음(어디에서 물어보실 지 모르니 철저히 준비 예) 난 다른 분야에 관심이 있는데 해석학이나 선형대수학 부분을 집중적으로 물어보실 수 있음.) · 지원동기, 리더십, 책 등은 하나도 안 물어보시고 처음부터 끝까지 수학내용만 물어보심.","qa":[{"q":"1학년에 고급수학을 들었네요? 고급수학을 수강한 동기와 들으면서 가장 중점적으로 공부한 것은 무엇인가요?","a":"고급 수학 지식들을 접하면서 학교에서 공부한것만으로는 부족하다 생각되어 고급수학을 수강하게 되었습니다(약간 더듬음). 제가 고급수학을 들으면서 가장 중점적으로 배운것은 ‘고유벡터’였는데요, 고유벡터에서 특히 회전행렬의 고유벡터에 대해 연구하면서 복소고유벡터를 알게 되었고, 복소고유벡터가 과연 어떤 방식으로 표현될 수 있을지, 그리고 어떤 의미를 가지는 지에 대해 탐구하였습니다."},{"q":"고유벡터는 어떤 의미를 가지나요(?)","a":"고유벡터는 회전변환..아니, 선형변환만의 특징을 잘 설명하는 벡터인것 같습니다. 고유벡터란 선형변환에 의해서 방향이 바뀌지 않는 벡터인데, 다른 벡터들은 선형변환에 의해 크기나 방향이 바뀌는 반면 고유벡터는 방향이 유지되기 때문에 선형변환만의 특징을 잘 설명해주는 벡터라 생각합니다."},{"q":"고유벡터는 항상 구할 수 있나요?","a":"(당황, 약 10초간 생각함)…제 생각에는 항상 구할 수 있을 것 같습니다. 선형변환에 대해서는 구할 수 있을 것.."},{"q":"(끊으면서)고유벡터를 구하는 방법에 대해 설명해보세요.","a":"고유벡터는 선형변환에 람다를 곱한 항등행렬을 뺀 다음 이 행렬의 행렬식이 0이 되어야함을 이용하여 연립방정식..아니 이차방정식과 연립방정식을 계산하여 구합니다."},{"q":"테일러 급수에 대해 공부한거 같은데 테일러 급수에 대해 말해주세요.","a":"테일러 급수는 해석함수를 도함수들의 한점에서의 값으로 구성된 항의 무한합으로 표현하는 방법입니다. 테일러 급수에서 항은 n팩토리얼 분에 (x-a)의 n제곱에 f의 a에서의 n번째 도함수를 곱한 꼴로 표현됩니다. 이렇게 구한 테일러 급수는 초월함수나 다항함수로 표현하기 힘든 함수를 다항함수로 표현할 수 있다는 것에 의의가 있는 것 같습니다."},{"q":"푸리에 급수에 대해서도 공부한거 같은데 푸리에 급수가 뭔가요?","a":"푸리에 급수는 주기함수를 사인과 코사인에 가중치를 곱한 것으로 구성된 무한합으로 표현하는 방법입니다. 푸리에 급수에서 가중치는 삼각함수의 직교성을 이용하여 적분하면 계산할 수 있습니다."},{"q":"푸리에 급수와 테일러 급수의 차이점은 무엇인가요?","a":"먼저 푸리에 급수는 주기함수를 무한합으로 표현하는 방법이고, 코사인과 사인을 이용해서 항을 표현한다는 점이 다른 것 같습니다.(잘 생각이 안나 말한것 반복)"},{"q":"테일러 급수는 항상 원래함수와 같나요?","a":"항상 일치하지는 않습니다. 테일러 급수는 매끄러운 함수를 대상으로 하는데, 그중에서도 테일러 급수와 원래함수가 일치하는 함수를 해석함수라고 합니다."},{"q":"미적분 시간에 감마함수에 대해 연구했다고 나와 있는데 이에대해 설명해주세요.","a":"lnt의 n제곱의 부정적분에 대해 탐구하면서 lnt의 n제곱의 부정적분과 n-1제곱의 부정적분이 팩토리얼의 점화식과 비슷하다는 것을 느꼈습니다. 이를 통해서 팩토리얼의 점화식과 일치시키기 위해 적분구간을 0~1로 설정하여 상수항을 없앴고, -가 반복하여 나오는 것을 없애기 위해 -lnt를 적중하는 것으로 바꿔 팩토리얼의 점화식을 만들 수 있었습니다. 이를 통해서 감마함수를 유도할 수 있었습니다."},{"q":"1학년때 원뿔곡선에 대해 심층탐구하고 실생활에서 활용되는 사례를 조사했다는데 예시를 말해주세요.A10답변 : 원뿔곡선 중 포물선은 평행한 직선이 입사했을 때 초점으로 모인다는 성질이 있습니다. 그래서 이런 성질을 활용하여 의료계에서는 빛을 한 곳으로 모아 결석을 제거하는 기술이 있는 것을 알고 있습니다.","a":""},{"q":"그거 말곤 없나요?","a":"네..딱히 생각이 나지 않는 것 같습니다."},{"q":"볼츠만 분포와 정규분포와의 연관성에 대해 설명해주세요.","a":"볼츠만 분포를 탐구하면서 볼츠만 분포식이 지수함수의 -제곱 꼴로 표현된다는 점과 볼츠만 분포의 그래프가 정규분포와 유사하다고 생각되어 비슷하다고 생각했었습니다."},{"q":"아까 테일러 급수가 항상 원래함수와 같지 않다고 했는데, 그런 경우 어떤 방식으로 테일러 급수가 일치하는 구간을 구할 수 있는지 설명해보세요.","a":"테일러 급수와 원래함수가 일치하는 구간을 계산하기 위한 방법은 비판정법을 활용하는 방법입니다. 비판정법은 a의 n번째 항분에 a의 n+1번째 항이 n이 무한대로 갈 때 1보다 작은 값으로 수렴해야 함을 이용하여 급수의 수렴성을 따지는 방법입니다."},{"q":"만약 급수의 항들이 비로 잘 표현되지 않는 경우는 어떻게 계산할까요?","a":"어..급수의 항들이 지로 잘 표현되지 않는 경우..(여기서 시간이 끝났니다. 시간이 끝났다고 알려주셔서 대답할 수 없었어요.)어.."},{"q":"대답 안하셔도 됩니다.","a":""}],"src":"세종특별자치시교육청 「보인다! 5.0 면접지도 길라잡이」","year":"2024학년도"},{"univ":"서울대학교","dept":"에너지자원공학과","jeonhyeong":"학생부종합(지역균형전형)","method":"면접시간 10분 / 면접위원 2명","notes":"면접관 분들과의 거리가 생각보다 많이 가까웠음 · 면접 대기실에서 전자기기 걷은 후에는 가져온 모든 자료 볼 수 없음","qa":[{"q":"화학, 생명 등 다른 과가 많은데 하필 우리 학과를 어떻게 지원하게 되었는지 이유좀 말해줄수 있을까요?","a":"저는 에너지의 지속가능한 발전과 소비에 기여하고 싶은 학생입니다. 전 세계적으로 인구는 계속 증가하고 있고, 1인당 에너지 소비량도 증가하는 상황에서 에너지의 확보는 필수적입니다. 그러나 화석연료는 자원이 한정되어 있어 고갈 문제가 있고, 지구 온난화의 원인이 된다는 점에서 대체 에너지의 개발이 필수적인 상황입니다. 저는 고등학교에 들어서서 이러한 문제를 해결할 수 있는 방안에 대해서 배웠습니다. 태양광이나 풍력과 같은 신재생 에너지, 그리고 핵융합 발전에 대해서 알아가면서 이를 개발하고 발전시키는 연구원이 되겠다는 꿈을 가졌고, 그래서 이 학과에 지원하게 되었습니다."},{"q":"그러면 연구원이 되고 싶은 건가요? 우리 학과에 와서 배우고 싶은거나 해보고 싶은게 있나요?","a":"네. 제가 여러가지를 배우다 보니 고등학교 수준에서는 이해할 수 없는 것들이 많았는데요, 저는 그 중 탄소포집저장활용 기술에 대해서 배우고 싶습니다."},{"q":"에너지의 개발에 어쩌다 관심을 가졌는지, 동기가 있나요?","a":"시작은 유튜브나 뉴스에서 기후 변화의 심각성에 대해서 많이 얘기를 하는데, 이에 대한 두려움에서였던것 같습니다."},{"q":"평소 일상생활에서 행복한 일과, 학업적으로 행복했던 경험 각각 하나씩 말해주시겠어요?","a":"일상생활에서는 제가 캐릭터 인형을 좋아해서, 이런것들을 판매하는 곳에 가서 구경할 때 행복하다는 감정을 느끼는 것 같습니다. 네 ㅎㅎ 학업적으로 가장 성취감을 느꼈던 경험으로는 1학년 때의 동아리에서 진행한 연구에 있었습니다. 유난히 녹이 슬어있는 시약장 경첩의 성분을 확인하는 연구였는데 처음 설정한 가설에서 예상과 다른 결과가 나와 가설을 수정하고, 다시 탐구해서 결론을 도출하는 과정이었습니다. 이 과정을 통해 ‘이것이 과학이다’ 라는 생각을 하게 되었습니다."},{"q":"수학 문제 풀이를 즐긴다고 나와있었는데, 수학 문제 푸는걸 좋아하시나요?","a":"중고등 학교 때는 수학 문제를 푸는 것을 좋아했습니다. 그러다 점점 과학 분야에 사용되는 다양한 수학적 개념에 흥미를 느꼈습니다. 교내 여러 탐구활동을 통해 좀 더 높은 수준의 수학 개념과 문제를 접하였습니다. 재미도 있었지만 제가 많이 부족한걸 느끼는 것 같습니다. 앞으로 대학교에서 제 부족한 부분을 더욱 보강하고 싶습니다."},{"q":"심화수학은 과목이 따로 있는거에요?","a":"네. 교육과정에 있는 과목이었습니다."},{"q":"앞으로 에너지를 어떻게 사용하고, 개발해 나아가야하는지에 대해서 말해줄수 있나요?","a":"화석 연료를 이용한 에너지 생산 방법에서 최대한 빨리 탈출하는 것을 최우선으로 생각해야 할것입니다. 신재생에너지와 핵융합 같은 에너지 생산방법에 집중해야 한다고 생각합니다. 우선 기존의 신재생 에너지의 효율을 향상시키며 시간을 벌어둔 후 핵융합 발전을 완성시키는 방향으로 진행해야 할 것 같습니다."},{"q":"핵융합에 대해서 말했는데, 핵융합은 언제쯤 사용이 가능할지..","a":"사실 지금 당장은 아니고, 세계적으로 진행되는 연구의 목표가 2040~50년 까지이므로, 그때쯤 상용화가 될 것 같습니다."},{"q":"다시 돌아가서 고등학교 생활을 한다면 가장 해보고 싶은일, 그리고 고등학교에 들어와서 가장 잘한일 하나씩 말해주세요","a":"우선 제가 고등학교에 입학할 때로 돌아간다면 가장 해보고 싶은 일은 코딩, 컴퓨터 이쪽 분야를 배워보고 싶습니다. 그리고 고등학교에 와서 가장 잘했다고 생각되는 일은 화학 동아리에 가입한 것 입니다."},{"q":"화학 동아리에서 어떤 활동을..?","a":"아까 말씀드린 연구인데, 자세히 설명해도 될까요? (대답 듣고 세부 과정 이야기 함)"},{"q":"그럼 물리학을 배울때, 가장 재미있었던 부분과 힘들었던 부분 있나요?","a":"네. 저는 물리학 1을 배울때 역학 부분이 그림상으로 무언가 표현되어있고, 이를 통해 값을 구하는 부분에서 가장 재미있었습니다. 가장 어려웠던 부분은 파동 부분을 배울때 어렵다고 생각한 것 같습니다."},{"q":"이제 곧 시간이 다 될것같은데, 마지막으로 하고 싶은 말 있나요?","a":"대답하려는 찰나 시간 다 됐다고 문 열려서 인사 후 나옴."}],"src":"세종특별자치시교육청 「보인다! 5.0 면접지도 길라잡이」","year":"2024학년도"},{"univ":"서울대학교","dept":"역사교육과","jeonhyeong":"학생부종합(기회균형특별전형)","method":"면접 대기실 → 면접 실 옆 자리에서 대기 → 면접실 / 면접시간 10분 / 면접위원 2명","notes":"입실 마감 후에 수험표, 신분증, 물 제외 모든 물건을 가방에 넣으라고 하시고 그 가방을 다른 교실로 옮기기 때문에 대기하는 동안 아무것도 볼 수 없습니다.","qa":[{"q":"3학년 사회문제 탐구 시간에 ‘인문학 위기에 맞선 인문학 교육의 방향 모색’이라는 주제로 연구를 진행했는데 이 연구를 하게 된 계기와 배운 점 또는 느낀 점을 말해보세요.","a":"우선 활동을 한 계기부터 말씀드리겠습니다. 평소에 뉴스 기사를 보는 것을 좋아하는 저는 기사를 보던 도중 이과 편중 현상과 의대 쏠림 현상이라는 사회적 현상, 문제를 접하게 되었습니다. 저는 이와 같은 사회적 문제가 학생들의 인문학에 대한 관심도가 떨어져서라고 생각하여 인문학 교육 방향에 대해 연구하였습니다. 이 연구를 진행하면서 저는 학생들이 생각하는 인문학, 인문학 위기의 원인, 인문학 교육에 대해 알 수 있었습니다. 학생들은 인문학을 인간과 관련된 학문, 인간의 문화나 역사 등 삶의 모습을 담은 학문이라고 생각하였으며, 경제적인 가치가 뚜렷이 드러나지 않는다는 점에서 인문학에 관심이 가지 않는다고 말하였습니다. 예를 들어, 과학 기술 같은 분야는 그 발전이 사회에도 잘 드러나지만 인문학은 그렇지 않는다는 점에서 이 이유를 말하였습니다. 그리고 학생들은 인문학의 내용이 평소 많이 접해보고 대부분 알고 있는 내용이라 인문학 교육에 흥미를 느끼지 못한다고 하였습니다. 저는 이를 바탕으로 앞으로의 인문학 교육에 대해 생각해 보았습니다. 앞으로의 인문학 교육은 인문학 캠프와 같이 인문학을 재밌게 접할 수 있는 교육 기회가 마련되어야 하고, 학생 중심의 협동 수업이 이루어져야 한다고 생각하였습니다."},{"q":"학생 중심의 협동 수업이 프로젝트형 수업을 말하는 건가요?","a":"네"},{"q":"그러면 프로젝트형 수업이 인문학 위기를 해결할 수 있다고 생각해요?","a":"당장은 해결되긴 힘들지만 프로젝트형 수업이 계속 이루어진다면 인문학 위기를 해결하는 데에 도움을 줄 수 있다고 생각합니다. 그 이유는 저는 인문학 위기의 원인을 학생들의 인문학에 대한 낮은 관심도라고 생각했기 때문에 학생들이 중심이 되는 협동 수업, 프로젝트형 수업이 이루어진다면 학생들의 인문학에 대한 관심, 흥미를 끌 수 있어 인문학 위기 해결에 이바지할 수 있다고 생각합니다."}],"src":"세종특별자치시교육청 「보인다! 5.0 면접지도 길라잡이」","year":"2024학년도"},{"univ":"서울대학교","dept":"전기정보공학부","jeonhyeong":"학생부종합(지역균형전형)","method":"생기부 기반 면접 / 면접시간 10분 / 면접위원 2명","notes":"진로 희망등의 일반적인 질문들, 생기부 세세한 내용들을 위주로 준비함. 그런데 실제 면접에선 열심히 탐구했던 주제 몇가지만 질문하셔서 크게 긴장하지 않고 답변할 수 있었음. 특히 프로그램을 만든 부분에 관심을 가지고 많이 물어보셨는데, 실제로 과정 하나하나 다 프로그래밍했던 내용이라 세세한 내용까지 잘 답변할 수 있었음. · 면접 분위기는 편하게 답할 수 있는 분위기였고 면접을 한다는 느낌보단 지원자가 했던 활동에 대해서 편하게 이야기를 나눈다는 느낌이였음.","qa":[{"q":"곡률에 대해서 왜 조사했나요?","a":"교과서에 곡률 식만 소개됨. 자세한 수학적 증명과정 궁금해서 탐구했습니다.Q1-1: 외적개념을 활용했다 했는데 좀 더 자세히 설명해 주세요.곡률의 기본 정의에서부터 식까지 유도과정중 벡터미적분학 사용. 이 과정을 간편하게 가기위해 외적 사용했던것으로 기억합니다.Q1-2: 그럼 3차원 상황에서 증명한것인가요?딱히 한정짓진 않았지만 외적사용했으면 3차원에 적용가능할 것 같습니다.Q-3: 조사는 어떤식으로 했나요?주로 인터넷을 찾아보고 모르는 부분은 선생님께 질문드렸습니다."},{"q":"3학년 물리학2 시간에 이중진자 프로그래밍 활동을 왜 했나요?","a":"과학과제연구 시간에 물리엔진을 구현했습니다. 더 다양한 상황을 프로그래밍해보고 싶어서 이중진자에 대해서도 탐구했습니다.Q2-1: 어디까지 구현했나요?(계산식 or 시각화)시각화까지 했습니다.Q2-2: 어떻게 탐구했나요?이것도 비슷하게 혼자 인터넷으로 조사하다 모르는 부분은 선생님께 여쭤 보았습니다.Q2-3: 어려운 점은 없었나요?장력을 구현할때 처음엔 용수철 상수를 높게 잡으면 실처럼 작동할줄 알았습니다. 하지만 제 프로그램은 프레임 단위로 했기 때문에 (Q: 중간질문 - 프레임 단위면 시간? A: 네) 물체의 이동에 약간씩 오차가 있어 떨림현상이 나타났습니다.Q2-4: 재밌었겠네요?네, 재밌었습니다.Q2-5: 이런게 수업 프로그램에 있었나요?딱히 없었지만 그냥 관심이 생기면 발표할 수 있는 환경은 있었습니다.Q2-6: 주제는 선생님이 잡아주신 건가요? 아니면, 직접 찾은 건가요?처음 제가 관심이 생겨 찾아보다가 모르는 게 있으면 선생님께 질문을 드렸고, 선생님께서 어떤 부분을 더 봐라 하면서 이끌어 주셨습니다.Q2-7: 공부하느라 시간도 없을 텐데 이런 건 왜 했나요?그냥 코딩으로 구현하는 과정이 재밌어서 고등학교 생활 동안 꾸준히 했습니다."},{"q":"3학년 진로 레이트레이싱 구현 활동(이 활동 질문하시기 시작할 쯤 노크소리가 들렸음)도 시각화까지 한 건가요?","a":"네.Q3-1: 하기 어려웠을 텐데 전반적으로 어땠는지 설명해 주세요.시간이 얼마 없으니 일반적인 구현법이랑 다른 부분만 말씀드리겠습니다. 첫 번째는 공간구현을 폴리곤(3d그래픽의 기본단위 삼각형)으로 하기엔 데이터 생성이 힘들었습니다. 그래서 수학적 정의로 공간을 구현했습니다. 이로 인해 이후 빛의 충돌판정을 할 때 폴리곤이였으면 간단하게 계산할 수 있는 것을 빛을 조금씩 전진시켜 츙돌을 판단하게 만들었습니다. 그런데, 이는 최적화 측면에서 불리했습니다.두 번째는 가상면에 대한 것입니다. 원래는 구면이여야 할 가상면을 평면으로 가정하고 프로그래밍했기에 시야 외곽으로 갈 수록 확대되며 왜곡되는 문제가 있었습니다.(Q: 중간 질문 - 그래서 어떻게 해결했나요?) A: 삼각함수를 활용하여 곡면으로 가상면을 바꾸면 좋았겠지만, 당시에 시간이 부족하여 시점과 가상면 사이의 거리를 늘리는 임시방편으로 해결했습니다."}],"src":"세종특별자치시교육청 「보인다! 5.0 면접지도 길라잡이」","year":"2024학년도"},{"univ":"서울대학교","dept":"정치외교학부","jeonhyeong":"학생부종합(지역균형전형)","method":"생기부 기반 면접 / 면접시간 10분 / 면접위원 2명","notes":"암기는 별로 도움이 되지 않은 것 같습니다. · 평소에 어떤 생각을 하고 있는지를 확인하는 질문들이 위주인 것 같아요. · 그리고 꼬리질문이 계속 이어져서 생기부 자체에 대한 질문은 적었습니다.","qa":[{"q":"국제정치와 관련하여 보편적 가치에 관심이 많은 것 같은데 왜 관심이 많죠?","a":"저는 인간의 존엄성이 가장 중요한 가치라고 생각하기 때문입니다. 인간은 인간이라는 자체로 존중받아야 마땅하며 이것에 대해 계속 추구해 나아가야한다고 생각합니다. 그래서 저는 보편적 가치를 다루는 것이 중요하다고 생각했습니다."},{"q":"학생에게 보편적 가치란 무엇인가요?","a":"저에게 보편적 가치란 생명권, 자유권, 재산권입니다. 그리고 추가적으로 참정권 또한 자신과 관련한 문제에 대해 직접 해결해나가는 권리라고 생각해서 이 권리 또한 보편적 가치를 지니고 있다고 생각합니다.(Q1,2번과 관련해서 꼬리질문이 계속 이어졌습니다. “어떻게 저 권리들을 보편적 가치라고 할 수 있는가,시대와 상황에 따라 다른 것이 아닌가”,“저 가치들을 실현하지 않은 나라들에게는 저 가치들을 실현하는 나라들이 더 이상한 것이고 보편적인 것이 아닌게 아닌가?”,“그럼 저 가치를 실현하지 않은 나라들을 어떻게 설득할 것인가?”,“북한과 같은 나라들도 나름의 논리를 가지고 있는데 그들에게는 그것이 보편적 가치를 실현하는 것이 아닌가?,”우리나라에서 특히 더 잘 실현된다고 생각하는 보편적 가치는 무엇인가?“"},{"q":"학생은 진로가 어떻게 되죠?","a":"저는 명확하게 아직 어떤 진로, 직업을 정하지는 않았습니다. 하지만 제가 고민하고 생각하는 문제에 대해서 답을 찾아 나아가고 싶습니다. 그 고민으로는 평화를 실현하는 과정에서의 폭력이 어디까지 정당화될 수 있느냐와 관련한 문제입니다. 평화 상태에서는 당연히 폭력이 없어야하지만 평화를 실현하는 과정에서는 공격에 대한 방어,구조적 폭력에 대항하여 민주정을 설립하려는 혁명 등 예외적인 예시를 생각하니 고민이 들었습니다. 그래서 이 문제에 대해 계속 생각하고 저의 답을 찾아나가기 위해 노력하고 싶습니다.(꼬리 질문:“과거부터 많은 학자들이 평화를 추구하려고 노력해왔음에도 불구하고 매우 어려운 일이다. 그리고 인간의 역사에서 폭력과 전쟁을 빼놓을 수는 없다. 이에 대해 어떻게 생각하는가?”)"},{"q":"고등학교 생활 중 가장 자신에게 큰 영향을 끼친 도서는?","a":"저는 <두 도시 이야기>가 가장 기억에 남습니다. 이 책은 프랑스 혁명 당시의 영국 런던과 프랑스 파리에서 있던 일을 다루고 있는 장편 소설입니다. 이 책이 저에게 끼친 영향은 평화를 실현하는 과정에서의 폭력에 대해 생각해보게 하였기 때문입니다. 프랑스 혁명은 구조적 폭력을 깨고자 하는 목적에서 실현이 되었습니다. 하지만 이 폭력이 정당한 목적을 위해 이루어졌다고 하더라도 이 과정에서 관련이 없는 민간인의 희생 등 폭력의 비참함 또한 다루어졌습니다. 그래서 저는 평화를 위해 폭력이 어디까지 정당화될 수 있을지 고민이 이 책으로부터 시작되어 <두 도시 이야기>가장 영향을 많이 끼친 도서입니다.(꼬리질문:“그럼 학생은 폭력이 사용될 수 없다고 생각하나요?”"}],"src":"세종특별자치시교육청 「보인다! 5.0 면접지도 길라잡이」","year":"2024학년도"},{"univ":"서울대학교","dept":"철학과","jeonhyeong":"학생부종합(일반전형)","method":"신분 확인 → 대기실 입장 → 다시 신분 확인 → 대기 → 면접실 복도 앞에서 대기 후 준비 / 면접시간 구상 30분, 답변 15분","notes":"수험생에게 믿기지 않을 수준의 자율성을 제공함. 전자기기를 따로 수거하지 않고, 본인 가방에 넣어 보관하라고 하는 등 정말 시험이 아닌 면접의 느낌이 강했음. · 추가 질문에 교수님의 의도가 전부 숨겨져 있었는데 현장에서의 긴장감 등으로 의도를 파악하기 어려웠음.","qa":[{"q":"‘역사학의 허구성’이 (나)와 (다)에서 각각 어떻게 나타나는가?","a":"기본적으로 합리적 사고를 통해 역사적 사실을 재구성하는 데에 초점을 맞춘 역사학은, 사료에 기반한 합리적인 추론을 거칠 수 있는 내용만 ‘역사적 사실’로 간주합니다. 그러나, 사료가 부족하여 알 수 없는 내용이나 질적인 맥락 등의 경우 연구자가 과거로 돌아가서 알아볼 수 없으므로 사실적 검증을 거칠 수 없습니다. 따라서 역사학자의 생각이나 상상 등 사료에 기초하지 않은 내용을 추가하여 전체적인 맥락을 파악합니다. 저는 역사적 허구성이 이처럼 사료로만 알 수 없는 것들을 알게 해주는 도구라고 생각합니다. (나)에서 역사적 허구성은 ‘사람들이 권위에 순응하였다’라는 진술입니다. 실제로 그들에게 그러한 압력이 작용했는지, 혹은 그들이 그렇게 느꼈는지를 알 수 있는 별다른 근거가 제시되지 않았습니다. 따라서 이는 역사학자가 추측한 내용으로, 허구성에 해당합니다. (다)에서 역사적 허구성은 ‘유대인 혐오 감정’입니다. 이 역시 사람들이 실제로 말한 내용, 즉 사료에서는 드러나지 않는 내용으로, 허구성에 해당합니다. 이들은 공통적으로 감정적인 맥락 등 질적인 측면의 역사적 분석을 위해 역사학자의 주관에 일정부분 의존합니다."},{"q":"역사학처럼 사실성과 허구성이 나타나는 다른 학문의 예시를 들어보시오.","a":"인류학에서 민족지 연구를 할 때, 연구자의 주관이나 편견이 최대한 배제되어야 합니다. 여기에서 사실성은 기술된 인류학적 특성으로 볼 수 있습니다. 그러나 단순한 사실의 나열은 학술적 의미가 없기 때문에, 연구자의 해석이 가미될 수밖에 없으며 이는 역사학의 허구성에 대응될 수 있을 것입니다."},{"q":"그러면 역사학자는 자기 마음대로 이야기를 지어낼 수 있는가?","a":"그런 것은 아닙니다. 일정한 수준의 근거를 제시하고 자신의 이야기를 하여야 하지, 단순히 본인의 주관이라 하여 사실인 것처럼 말해서는 안 됩니다."},{"q":"근거라고 하였는데, 그 근거에는 무엇이 있을지?","a":"만약 자연과학이라면, 자연과학은 세계를 정밀하게 기술하는 것을 목표로 하기에 타당성 등을 검증할 객관적 수치/지표들이 있습니다. 그러나 역사학은 인문학으로서 이러한 것들이 존재하지 않기 때문에, 학계에서 합의를 통하여 도출된 일정한 이론이나 주장에 기반하여야 합니다."},{"q":"그렇다면 철학의 경우와, 자연과학의 경우는 어떨까요?","a":"잠시 생각할 시간을 주시겠습니까? (시간을 조금 많이 씀) 이어서 답변하겠습니다. 철학의 경우 사실성의 영역은 논리적 논증과 그 결과들, 허구성은 직관이라고 생각합니다. 아무리 철학적으로 명료하고 정치한 논증구조, 예를 들면 공리계 등을 설계하더라도, 그 전제를 파고들어가다 보거나 모순되는 지점을 찾다 보면 심리적인 직관이 요구되는 경우가 있습니다. 이때 우리는 우리의 심리적 직관의 작동 규준이나 존재 근거 등을 제대로 파악하지 못하기 때문에, 논리 구조에 포함될 수 없는 외부적 요소라는 점에서 역사학의 허구성에 대응합니다. 다음으로 자연과학에 관하여 말씀드리겠습니다. 자연과학의 경우, 앞서 말했듯 허구성이 끼어들 자리가 점차 줄어들고 있습니다. 과학적 방법론이 발전하고 연구가 이뤄지면서, 세계를 신뢰할 수 있는 정도를 측정할 표준들이 지속적으로 개발되고, 개선되고 있습니다. 따라서 사실성에 해당하는 검증된 과학적 연구들이 점차 늘어나고 있습니다. 반대로 허구성에 해당하는 것으로는, 현대에는 거의 찾아보기 어렵지만, 일부 최신분야가 잉태되고 초창기의 연구가 진행되는 과정에서는 ‘과학적 상상력’ 등으로 표현되는 과학자들의 주관이나 상상이 반영되고 있습니다. 이를 허구성에 해당하는 부분으로 볼 수 있고, 자연과학에서 허구성은 분야의 발전에 따라 점차 줄어들 것임을 다시 요약하며 답변 마칩니다.<사회과학>가) ‘아이가 타고 있어요’ 스티커를 붙이면 타 차량 운전자들에게 경각심을 주어 사고를 예방할 것이라 생각하고 스티커 여부에 따른 사고율을 조사했다. 스티커가 있는 차량은 사고율이 낮아졌지만, 이것이 부모에게 경각심을 준 결과는 아닐까?나) 생존자 편향 (인터넷에 검색하면 있는 그 전투기 사례 그대로)"},{"q":"(가)와 (나)에 나타난 문제점의 공통점과 차이점을 분석하시오.","a":"이 두 문제는 모두 문제를 해결하기 위해 데이터를 사용하였지만, 의도와 다른 결과를 가지게 되었습니다. 공통점으로 데이터의 활용에서 오류를 범하고 있다는 점이 있습니다. (가)의 경우 변인통제가 제대로 되지 않아, 다른 요인이 개입하기 쉽고 실제로 개입하였습니다. 반면 (나)의 경우 표본 추출 과정에서 오류가 있었습니다. 표본의 크기가 충분히 크지 않고 표본추출이 편파적으로 이뤄져 대표성을 충분히 확보하지 못했습니다."},{"q":"(가) 또는 (나) 사례와 유사한 사례를 들고, 이유를 설명하시오.","a":"심리학에서의 ‘학부생 문제’가 있습니다. 대학생이 주변에 많기 때문에, 심리학 연구에서 표본으로 대학생들이 집계되기 더욱 쉬운 경향이 있어 표본의 대표성이 떨어질 수 있습니다."},{"q":"2번 질문 다시 답변해주세요. 누구를 대상으로 한 심리학 실험이기에 왜 문제가 되는지를 설명해야 더 나을 것 같아요.","a":"일반적인 대중, 즉 전 세계 사람이나 전국민에게 일어나는 심리적 현상을 연구하는 실험이라고 해본다면, 대학생들이 표본으로 추출되는 비율이 크다면 문제가 발생합니다. 이들은 비교적 소득수준이나 연령, 교육수준이 일정하기 때문에 과대대표되는 문제가 생길 수 있습니다."},{"q":"그러면 2번 질문에서 (가)와 관련지은 사례는 없나요?","a":"한국사회에서는, ‘대학 졸업자들 중 부유층의 비율이 높다’라는 이유로 대학에 가면 돈을 벌기 쉬울 것이라는 말을 합니다. 그러나 이는 (가)처럼 상관관계와 인과관계를 혼동한 분석입니다."},{"q":"(나)도 인과-상관관계를 혼동한 것 같지 않나요?","a":"총알자국의 개수가 부품의 안정성에 주는 영향에 대한 따로 판단이 나와있지 않으므로 그런 것 같지는 않습니다."},{"q":"시간이 거의 끝났는데, 마지막으로 인문학 제시문 답변 중에, 철학적 사실성과 역사학적 사실성이 질적으로 다르다고 생각하지 않나요?","a":"다르다고 생각합니다. 철학적 사실성은 주로 연역적 논리에 기반한 반면, 역사적 사실성은 제시문에 ‘경험주의’라는 언급이 있듯 경험적 외부 자료에 기반했습니다."}],"src":"세종특별자치시교육청 「보인다! 5.0 면접지도 길라잡이」","year":"2024학년도"},{"univ":"서울대학교","dept":"철학과","jeonhyeong":"학생부종합(일반전형)","method":"30분 동안 제시문 숙지와 답변 구성(인문 제시문1, 사회 제시문1로 총 2개), 15분 동안 답변 / 면접시간 30분(준비시간), 15분(답변시간) / 면접위원 2명","notes":"서울대는 꼬리질문으로 유명함. 교수님이 한 질문에 답변해 나가는 상호작용 과정이 중요함.","qa":[{"q":"(가)지문의 역사학의 모순에 대한 내용을 말하고, (나), (다)에서 이와 관련지어 말하라?","a":"(가)지문에서 역사학의 모순이라고 말한 까닭은 주관적인 사례를 들어 보편적 진리를 찾으려고 하기 때문임. (나)에서는 ‘나치당 지지 세력의 말’이라는 주관적 내용을 들어, (다)에서는 ‘사람의 가치관’과 ‘사람의 행위’라는 주관적 내용을 들어서 나치당 지지 세력의 내적 동기의 보편적 진리를 찾으려고 하고 있음."},{"q":"위에서 말한 역사학의 모순과 유사한 특징을 지닌 예를 하나 제시하시오?","a":"철학과 유사함. 객관적 자료에 근거하여 탐구하는 과학과 달리, 철학은 인간의 사유라는 주관성이 반영될 수 있는 요소를 통해 객관적 진리를 찾고자 하기 때문임.Q2-1: 철학, 역사학과 같은 학문은 객관적인 과학과 같은 학문과 달리 객관적일 수 없다는 것임?...답변 제대로 못 해서 비슷한 질문만 2-3번 반복함..지문2: 사회지문(가)자동차 뒤에 ‘아이가 타고 있어요’라는 표지판이 붙어있을 때, 사고율이 줄어든다는 연구결과 제시. 이 결과에 기반하여 해당 표지판이 사고율을 낮춘다는 주장 제시. 그러나 진짜 해당 표지판이 사고율을 줄이는 것인지에 대한 의문 존재함을 첨언. 사고율 감소의 원인이 표지판에 있는 것이 아니라, 부모의 조심성에 있다는 새로운 가능성 전개. 표지판을 붙인 부모들이 애초 조심성이 많은 사람들이 다수이기 때문임. 결론은 표지판만으로는 사고율 감소의 결과를 확신할 수 있는지 모른다는 것임 (나)전투기를 보완해야 하는 상황 제시. 전투기의 일부분만을 보완할 수 있는데, 그 일부분을 어디로 해야 하는지에 대한 2가지 주장 전개. 1번째 주장은 전쟁에서 돌아온 전투기들을 보았을 때, 가장 총알을 많이 맞은 부분을 보완해야 하다는 주장임. 해당 부분이 총알을 맞기 쉬운 위치이기 때문. 2번째 주장은 전쟁에서 돌아온 전투기들을 보았을 때, 가장 총알을 안 맞은 부분을 보완해야 한다는 주장임. 표본이 전쟁에서 돌아온 전투기들 뿐이기 때문에, 전쟁에서 돌아오지 못한 전투기가 어느 부분을 총에 많이 맞아서 못 돌아왔는지 알 수 없음. 따라서, 전쟁에서 돌아온 전투기들이 총을 많이 맞은 부분은 애초 치명적이지 않기 때문에 돌아올 수 있었다는 가정을 한다면, 전쟁에서 돌아온 전투기가 총을 많이 맞지 않은 부분이 가장 치명적인 부분이라는 것임."},{"q":"(가), (나) 상황의 특징을 비교하시오.","a":"(가), (나)의 공통점은 둘 다 표본의 대표성 문제라는 점이다. (가)는 표지판을 붙인 부모를 표본으로 정함으로 인해 자연스럽게 조심성이 많은 사람이 표본이 되게 되었다. 이로 인해 조심성이 없는 사람은 표본으로 사용하지 못하게 되면서, 조심성이 많은 이와 적은 이가 공존할 수 있는 전체 모집단을 해당 표본이 대표하지 못하게 되었다.(나)는 전투에서 돌아온 전투기만을 표본으로 함으로 인해 전투에서 돌아오지 않은 비행기는 표본으로 사용하지 못하게 되면서, 전체 모집단을 표본이 대표하지 못하게 되었다.차이점은 (가)의 운전자의 조심성이라는 요소는 사고율과 직결된다고 말하기에는 다소 주관성이 반영될 수 있기에 조심성이 없다고 반드시 사고가 많이 나는 결과를 낳는다고 단언할 수 없다는 점..(나)는 이와 달리 총에 맞아서 전투기가 추락했다는 결과를 낳는다는 것은 단언할 수 있다는 점.."},{"q":"(가), (나) 상황과 유사한 예를 제시하시오.","a":"(가)는...(기억이 안 나요..)Q2-1: (가)에서 표본의 대표성 문제를 해결하려면 어떻게 해야 하는가?표지판을 붙인 부모뿐만 아니라, 그저 일반 운전자들을 표본으로 데려다가 표지판을 붙이게 한 후 일정 시간 동안 도로를 주행하게 한다. 이때 주변 자동차들의 동향, 표지판을 안 붙였을 때보다 공격적으로 주행하는 차들이 주변에 적은지, 많은지 등등을 확인하여 표본의 대표성 문제를 해결할 수 있다."}],"src":"세종특별자치시교육청 「보인다! 5.0 면접지도 길라잡이」","year":"2024학년도"},{"univ":"서울대학교","dept":"화학생물공학부","jeonhyeong":"학생부종합(지역균형전형)","method":"생기부 기반 면접 / 면접시간 10분 / 면접위원 2명","notes":"학교가 관악산에 있어서 아침에 매우 춥습니다. 옷 따뜻하게 입고 가세요. · 대기 시간에 가져간 자료를 볼 수 없습니다. 면접장 가서 생기부 공부할 생각하지 마세요.","qa":[{"q":"3학년 때 촉매 관련 실험을 진행하였는데 배경이 무엇인가요? 또 어떤 방식으로 실험을 진행하였나요?","a":"저는 화학 2를 공부하면서 교과서에 촉매의 표면적이 넓어질수록 촉매의 효율인 아진다는 것을 알게 되었고, 이를 실험으로 확인하기 위해 실험을 계획하였습니다. 결과 비교를 위해 두 가지 실험을 준비하였습니다. 첫 번째는 은거울 반응을 이용해 은박을 만들었고, 두 번째는 은 콜로이드를 합성하여 과산화 수소를 분해하는 실험을 진행하였습니다. 실험 결과, 정량적으로 측정할 정도는 아니지만, 은 콜로이드로 분해하였을 때 과산화수소가 더 빨리 분해되었습니다. Q1-1: 이 실험에서 아쉬운 점이 있었나요? 있었다면 어떻게 해결할 수 있릏까요?실험 결과를 정량적으로 분석하지 못한 점이 아쉬웠습니다. 은 콜로이드를 합성하는 양에 은의 몰수를 맞추면 은박이 너무 조금 만들어져서 이를 분석하기 힘들었던 것 같습니다. 이를 해결하기 위해서 많은 양의 콜로이드를 만들고, 이를 조금만 덜어서 실험을 진행하면, 큰 은박을 이용해실험을 진행할 수 있을 것이라 생각합니다."},{"q":"반장 활동 같은 리더 역할을 많이 했는데 자신의 리더쉽이 잘 드러난 사례를 이야기해 주세요","a":"저는 1학년 때 동아리 기장을 맡아 동아리 페스티벌에서 실험 체험을 준비한 적이 있었습니다. 1학년이다 보니 동아리 페스티벌에 대해 자세히 몰랐고 어떻게 준비해야 하는지도 잘 몰라서 동아리에서 정한 펜로켓 실험을 기간까지 다 준비하지 못할 것 같다는 생각이 들었습니다. 그래서 친구들의 의견을 물으니 대부분 그럴 것 같다는 생각을 하였습니다. 그래서 방안을 물으니 차선책으로 준비 시간이 적게 걸리는 다른 실험을 동시에 준비하자는 의견이 나왔습니다. 처음에는 반대하는 친구들도 몇 있었지만 동아리 페스티벌을 준비해야 하는 동아리의 상황을 설명하니 모두 납득하여 실행으로 옮겠습니다. 결국 첫 번째 싫험은 다 준비하지 못하였고, 두 번째 실험으로 정안 발열팩 만들기 실험으로 동아리 페스티벌을 진행하여 호응을 얻었습니다. 위기 상황에서 동아리의 상황을 잘 파악하고, 구성원의 의견을 수렴하여 해겳 방안을 모색하였다는 점에서 리더로서 잘 행동했다고 생각합니다."},{"q":"삶의 목표가 무엇인가요?","a":"저는 행복이 삶의 목표입니다. 저와 주변 사람들의 행복이 가장 중요하다고 생각합니다. 현대 사회에서 돈의 중요성이 강조되고 있지만, 이는 수단일 뿐 궁극적인 목표는 행복이 되어야 한다고 생각합니다. 이 생각은 저의 진로와도 연관되어 있다고 생각합니다. 저는 연구자가 되어 인류에 도움이 되는 연구를 진행하고 싶습니다. 이는 저와 주변 사람들뿐만 아니라 많은 사람들의 행복을 가져와 줄 것입니다."},{"q":"자신이 생각하는 사회 문제에는 무엇이 있나요?","a":"저는 의대 쏠림 문제가 심각하다고 생각합니다. 훌륭한 인재가 모두 의대로 (진학하는 것은 국가적인 문제라고 생각합니다.면접 시간 종료)"}],"src":"세종특별자치시교육청 「보인다! 5.0 면접지도 길라잡이」","year":"2024학년도"},{"univ":"서울대학교","dept":"경영대학","jeonhyeong":"학생부종합(지역균형전형로비에서 신분 확인 → 면접 대기실 입장 → 지정 좌석에 착석 → 수험생 유의사항 및 신분 확인 → 면접실이 4개 있었고, 학생들 문밖)","method":"대기 → 마지막 안내 받고 면접실 입장 → 부여받은 수험번호와 함께 인사 → 생기부 관련 질문 → 꼬리질문 → (문 밖에서 종료 2분 전 노크 2번 해주심) → 실장하면서 인상깊었던 경험 질문 → (문 밖 시간 종료 시 노크 한 번과 함께 문 열어줌)면접 대기실 들어간 순간부터 아무것도 볼 수 없음. 가져온 물도 마실","notes":"수 없고 물을 따로 제공함. 전자 기기 반납 시에 아날로그 시계도 반납해야 하니 챙겨가지 않는 것이 좋을 것 같음.","qa":[{"q":"RE100. 탐구했는데 RE100에 관심 가지게 된 계기가 있다면 구체적으로 얘기해주세요.","a":"ESG경영에 관심을 가지고 있었고 ESG와 함께 자연스럽게 기업 활동에 필요한 전력의 100%를 태양광과 풍력 등 재생 에너지를 이용해 생산된 전기로 사용하겠다는 RE100이라는 자발적 캠페인에 대해 알게 되었습니다. 몇 년 전만 해도 뉴스에서 RE100이 계속 언급되었지만, 최근 2~3년간은 RE100에 관한 뉴스가 잘 나오지 않아서 왜 잠잠해졌는지 궁금하여 RE100에 관심을 갖게 되었습니다."},{"q":"RE100의 한계점이 무엇인데요?","a":"한국에서 RE100 이행이 어려운 이유는 태양광, 풍력 에너지 등의 재생에너지가 야간 발전에 제한적이기 때문에 결국 화력 에너지 사용이 불가피한 상황이 발생하기 때문입니다. 또한 우리나라에서 재생에너지 발전소를 많이 설치하는 것이 어렵다고 생각합니다."},{"q":"우리나라에서는 왜 어려워요? 다른 나라는 재생에너지 발전소 설치하는 것이 쉬운가?","a":"유럽국가들이 재생에너지 발전소를 설치하는 것이 어렵지 않다는 것은 아니지만, 우리나라가 유럽국가보다 재생에너지 발전소 설치가 더 어려울 것이라고 생각합니다. RE100의 한계와 관련하여 등장한 것이 CF100인 것으로 알고 있습니다."},{"q":"CF100? 좀 어려운데 이건 뭐에요?","a":"CF는 carbon free의 약자입니다. RE100보다 조금 더 넓은 범위로 사용 전력의 전부를 무탄소 에너지로 공급한다는 의미입니다."},{"q":"그러면 RE100이랑 CF100 차이는 뭐에요?","a":"둘 다 탄소중립이라는 같은 목적을 가지고 있지만 RE100은 재생에너지로 수단을 한정한 반면 CF100은 풍력, 태양광, 수력, 지열 등 재생에너지뿐만 아니라 탄소를 배출하지 않는 원자력발전, 연료전지 등을 수단에 포함시키고 있습니다."},{"q":"둘 다 어려우면 그냥 RE100 하는 게 낫지 않나요? RE100이 CF100 안에 있다는 거잖아요.","a":"네. 하지만 RE100이 이행되기 쉽지 않은 우리나라에 CF100이 RE100보다 더 장점이 많다면 CF100을 고려해보는 것도 좋다고 생각합니다. 그리고 우리나라의 수소에너지 발전도 활발히 이루어지고 있다고 알고 있습니다. (이 뒤로 수소에너지와 CF100 얘기를 했었던 것 같음.)"},{"q":"수소에너지도 그거 처리하는 데 비용이 들고 오히려 친환경적이지 않은 것 아닌가요?","a":"(당황해서 얼버무렸던 것 같음.)"},{"q":"그런데 우리나라 삼성, SK와 같은 대기업들은 RE100에 참여하고 있는데 이건 어떻게 생각해요? 왜 가입할까요? 어려운데?","a":"저는 여기서 RE100이 반드시 자발적인 캠페인은 아닐 수도 있겠다고 생각했습니다. 만약 RE100에 가입하지 않는다면 세계 시장에서 무역장벽을 겪게 될 것입니다. 그렇기 때문에 우리나라의 대기업들도 RE100에 참여하고 있다고 생각합니다."},{"q":"정부의 무슨 지원이 필요하다고 생각해요?","a":"재생에너지에 대한 재정적인 지원이 필요하다고 생각합니다."},{"q":"재정적인 것 말고 지금 본인이 대통령이라면 어떤 지원을 하고 싶어요?","a":"(제대로 대답 못 함.)"},{"q":"그런데 기업 간 혜택을 받는 기업과 제대로 받지 못하는 기업 간에 생기는 문제는 어떻게 해야 할까요? 혜택을 잘 받지 못하는 기업들은 불만이 있을텐데?","a":"기업의 분야별로 검토해서 지원하는 것이 필요할 것 같습니다. (중소기업에 관한 지원 얘기도 했었음.)"},{"q":"(중국 정부와 중국 시장에 대한 말씀을 하셨음.) 중국은 현재 정부가 지원을 하지 않고 있는데, 중국처럼 우리도 RE100 소용이 없으면 지원을 그만두어야 할까요? 아니면 지원을 계속해야 할까요?","a":"중국의 상황을 계속 주시하되 우리나라는 RE100과 기업 지원은 계속해야 한다고 생각합니다."},{"q":"네. 그러면 학급 실장으로서 의미있는 경험과 느낀 점이 있을까요?","a":"반톡에 공지사항과 준비물에 관한 안내를 꾸준히 했었는데 반 친구들이 고맙다고 칭찬을 해준 것이 기억에 남습니다."},{"q":"친구들이 왜 갑자기 칭찬을 해줬어요? 구체적으로.","a":"(수능 준비로 자습실에 오래 가 있어도 꾸준히 할 일을 했더니 친구들이 그것에 대해 성실하다고 칭찬해주었다고 대답함.)(노크 한 번과 문이 열림. 인사하고 나옴)후배들을 위한 조언 의 나오지 않았습니다. 저는 면접이 끝나고 답변을 제대로 하지 못한 아쉬움보다 재미있다고 생각했습니다. 면접관들께서는 계속해서 다방면으로 생각하게끔 질문을 하십니다. 끝나고도 계속 생각하게 되었던 시간이었습니다. 면접 준비 기간 동안 꼬리 질문을 많이 해보시는 것이 좋을 것 같습니다. 면접관들(교수님들)께서는 내가 한 활동에서의 내 생각을 궁금해하시는 분들이라고 생각했습니다. 면접 중 저의 답변에 대해 경청하시면서 정말 궁금하신 부분을 물어보시는 것 같습니다. 그리고 어떤 주제에 대한 내 생각을 정했다면 웬만하면 밀고 나가시길 바랍니다. (교수님들을 설득한다고 생각하시고 임하시면 좋을 것 같습니다.) 면접 대기실 들어가면 생기부도 못 보고 정말 아무것도 못 합니다! 너무 빨리 가시면 오래 기다려야 될 수도 있으니 적당한 시간에 입실하시는 것이 좋을 것 같습니다!"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(1권)」","year":"2025학년도"},{"univ":"서울대학교","dept":"경제학부","jeonhyeong":"학생부종합(기회균형특별전형(사회통합))","method":"생활기록부 기반 면접(10분)사회문제탐구 질문-> 3학년 동아리 질문-> 화법과 질문-> 지원동기1. 경제학부 면접고사장이 서울대 입구에서 많이 멀어서 버스타고 가면 좋을 것 같습니다.2. 경제학부는 대기하면서 서류 보는 것이 가능했는데, 불가했다는 학과도 있어서 오기 전에 마무리하고 오면 좋을 것 같습니다.","notes":"3. 면접이 예상대로 안 흘러갈 확률이 높습니다. 이에 당황하지 않고 자신의 역량을 끌어낼 수 있는 훈련을 평소에 선생님들과 모의 면접 등으로 대비하면 좋을 것 같습니다.4. 면접이 1분 정도 남으면 밖에서 노크 두 번 합니다. 이러면 거의 마무리 한다고 생각하고, 답변하시면 됩니다.5. 면접이 끝나고 종교인이 접근할 수 있습니다. 조심하세요.","qa":[{"q":"예, 안녕하세요. 질문 시작할건데, 기억이 안 나거나 모르겠으면 얘기해주세요, 괜찮습니다. 어차피 1,2학년 활동은 기억 잘 안날테니까 3학년 위주로 할게요.","a":""},{"q":"사회문제탐구라는 과목에서 코리아 디스카운트에 대한 탐구를 했는데, 문제점으로 한국 기업의 지배구조를 지적했네요?","a":"네 맞습니다."},{"q":"우리나라 지배구조의 문제점을 어떻게 파악하셨나요?","a":"우선 ‘좋은 주식 나쁜 기업 이상한 대주주’라는 책을 읽으며 코리아 디스카운트 현상에 대한 탐구를 진행하였습니다. 그 과정에서 여러 논문과 자료를 찾아보며 코리아 디스카운트의 주요 원인이 한국 대기업의 대주주 중심 경영과 그로 인한 소액주주의 피해에 있다는 것을 알 수 있었습니다."},{"q":"코리아 디스카운트 현상을 어떻게 측정하셨나요?","a":"코리아 디스카운트 현상은 한국 대기업과 글로벌 경쟁사의 재무제표를 비교하며 실재함을 파악하였습니다. 특히 PBR비율(주가수익비율), 즉 주가가 1주당 순이익의 몇 배인지 나타내는 지표가 우리나라 기업의 경우 유사 실적 대비 현저히 낮음을 파악함을 통해 알 수 있었습니다."},{"q":"그러면 지배구조의 문제를 명시적인 지표로 분석해 볼 수 있는 방법은 없을까요?","a":"답변드리겠습니다. 우선 지배구조의 문제는 재무성과로 드러나는 것이 아니기 때문에 여러 가지 지표를 종합해서 신중히 분석해야 할 것 같습니다. (당황해서 얼버무려 답변함.)"},{"q":"네, 긴장한 것 같은데, 앞에 있는 물 마셔도 괜찮아요. 코리아 디스카운트 현상을 대기업을 위주로 탐구한 것 같은데, 중소기업은 코리아 디스카운트 현상이 발생하지 않는 것인가요?","a":"그것은 아니라고 생각합니다. 중소기업 역시 코리아디스카운트 현상이 중소기업에 비해 한국 대기업의 물적분할로 인한 소액주주 피해등, 대기업의 문제가 더 크다고 생각합니다."},{"q":"3학년 동아리 시간에 전기차 산업에 대한 탐구를 총괄했다고 적혀있는데, 구체적으로 어떤 과정으로 탐구를 진행했나요?","a":"우선 저희 조는 4명이 탐구를 진행하였습니다. 각각 한국 전기차 시장, 중국 전기차 시장, 미국 전기차 시장을 담당하여 탐구하였고, 저는 조장으로서 각각의 탐구를 도와주고, 정리하며 총괄하였습니다. 탐구를 진행하며 현재 전기차 시장이 과열 경쟁으로 인한 치킨게임 상태라는 것을 알 수 있었습니다. 특히 중국은 전기차 시장의 후발주자로서 시장 점유율을 확보하기 위해 국가 주도 보조금 정책으로 육성중임을 확인하였습니다. 이에 미국은 IRA법안을 통해 자국 내에서 생산된 전기차에 보조금을 지급하여 대응 중임을 파악하였습니다. 결론적으로 한국 기업은, 이러한 급격한 국제 질서 변화에 신중히 대응하고, 균형잡힌 대책을 세워야 한다고 주장하였습니다."},{"q":"최저임금의 차등적용에 대한 탐구를 진행하였는데, 최저임금의 차등적용에 대해 어떻게 생각하시나요?","a":"네, 먼저 저는 최저임금의 부작용에 대한 문제점에 주목하였습니다. 최저임금으로 인해 노동시장의 초과 공급 및 고용 감소로 실업이 발생하고, 이로 인해 사회적인 잉여가 감소한다는 문제점을 알 수 있었습니다. 그로 인해 지역별 생활 수준에 따라, 또 산업별 업무 강도에 따라 최저임금의 차등적용을 실시하여 이러한 부작용을 해결할 수 있다고 주장하였지만, 지역 격차 확대와 사회적 박탈감 심화등의 문제점도 있기 때문에 최저임금의 점진적 인상 등 균형잡힌 대책이 필요하다고 주장하였습니다."},{"q":"(밖에서 똑똑) 네, 시간이 거의 다 되어서 마지막으로 지원 동기 말해주세요.","a":"안녕하십니까, 저는 고등학교에서 많은 사회적 현상을 경제학의 관점에서 분석해보는 탐구 활동을 진행하였습니다. 문학 시간에 난장이가 쏘아올린 작은 공이라는 책을 읽으며 우리 사회의 소외 계층과 약자가 겪는 불평등을 생생히 느낄 수 있었습니다. 나아가 21세기 자본이라는 책을 읽으며 이러한 불평등의 문제는 현대 사회에 까지 유효한, 사회 구조적인 문제임을 깨달았습니다. 저는 경제학이 이러한 불평등의 문제를 체계적으로 분석하고, 실질적인 해결책을 제시할 수 있는 학문이라고 생각합니다. 그래서 저는 서울대학교 경제학부에 진학하여 경제학적 사고력을 학습한 후, 약자를 외면하지 않는 따듯한 가슴과 문제의 본질을 통찰할 수 있는 차가운 머리를 모두 갖춘 전문가로 거듭나고 싶습니다. 감사합니다! 후배들을 위한 조언"},{"q":"두괄식으로 말하는 연습하기 (질문에 대한 답변의 핵심부터 말하기)","a":""},{"q":"탐구 동기만 여쭤보셔도, 동기만 답변하지 말고 과정 및 결론등 탐구에 관련된 내용 모두 어필하면 좋을 것 같습니다.","a":""},{"q":"내가 준비한 내용에 대한 답변 준비도 해야하지만, 내가 준비하지 않았거나 굉장히 낯선 질문에 대한 답변 대비하기. 물론 생기부에 있는 모든 내용을 모두 철저히 준비하는 것이 최고지만, 면접에선 내가 생각조차 해보지 않았던 질문이 나올 수도 있습니다. 그때 저처럼 당황해서 답변 제대로 못하고 나머지 질문들도 망치지 마시고 그러한 상황에 대한 준비를 평소 모의면접을 통해서 대비를 하면 좋을 것 같습니다.","a":""},{"q":"수능 끝나고 면접 준비 생각보다 열심히 안 하게 됩니다. 수능 전에도 틈틈이 면접 준비를 시작하는 것이 좋을 것 같아요. 파이팅입니다!","a":""}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(1권)」","year":"2025학년도"},{"univ":"서울대학교","dept":"농경제사회학부","jeonhyeong":"학생부종합(지역균형전형)","method":"자기소개 → 전공 질문 → 자율, 진로활동 질문 → 확률과 통계 관련 질문 → 회장 관련 질문","notes":"","qa":[{"q":"지원동기 말해주세요.","a":"저는 농경제사회학부에 지원하게 된 B19번(면접번호)이라고 합니다. 제가 농경제사회학 부에 지원하게 된 계기는 경제에 대한 관심으로부터 설명할 수 있습니다. 제가 경제에 관심을 가지게 된 계기는 경제라는 것이 고정불변하지 않고 계속 변화해 계속해서 탐구가 필요한 학문이라는 것에 있습니다. 저는 또한 환경과 농업에 대한 중요성을 알게 되었습니다. 환경문제에 대한 일환으로 지자체에서 발표한 녹색성장계획에 대해 직접 찾아가 보며 관심을 키워갔습니다. 또한 농업의 관광효과와 고용효과에 주목하면서 이에 대한 중요성을 알게 되었습니다. 이러한 환경과 농업의 중요성을 바탕으로 농경제사회학부에 지원하게 되었습니다."},{"q":"농업의 관광 효과랑 고용효과가 있다고 말했는데, 구체적으로 말해주세요.","a":"첫 번째, 관광 효과에 대해 설명하겠습니다. 예를 들어, 우리가 제주도 하면 생각나는 것은 감귤일 것입니다. 제주도는 감귤 수확 체험을 통해 관광 효과를 얻고 있습니다. 고용효과는 관광 효과와 연결지어 생각해볼 수 있습니다. 관광산업을 운영하면서 고용이 발생할 수 있다는 것입니다. 또한, 저는 해외 사례를 찾아보았습니다. 캐나다의 SOLEfood는 도시의 취약계층을 대상으로 고용을 하였습니다. 이를 바탕으로 이 기업은 현재 대기업이 되었습니다."},{"q":"현재 농업에 종사하는 사람이 감소하고 있는데, 이에 대해서 말해주세요.","a":"현재 농업의 종사자 수가 감소하고 있는 이유는 소득의 차이 때문입니다. 도시에서 근로하는 것이 농업을 하는 것보다 더 높은 소득을 얻습니다. 이러한 도시와 농촌의 격차는 사람들로 하여금 도시로 근로하는 것에 대한 유인이 발생합니다. 이에 대한 해결방안은 농업에 부가가치를 창출해 내도록 유도하는 것입니다. 최근에 발생한 4차산업혁명을 통해 농업의 생산성을 향상시킨다면 그만큼 부가가치를 더 창출해 낼 수 있을 것이므로 사람들에게 농업에 종사할 유인을 제공할 수 있을 것입니다."},{"q":"농업과 기술의 연결이라는 주제로 보고서를 작성했다고 하는데, 이에 대해서 말해주세요.","a":"저는 아까 이야기한 것과 같이 4차 산업혁명과 농업의 연결에 대해 탐구하였습니다. AI, IoT 등이 농업에 결부된 현상을 바탕으로 농업의 생산성이 향상시킨다는 것을 알게 되었습니다. 이것의 대표적인 예시는 스마트팜이 있습니다. (스마트팜에 대해서 이야기함.)"},{"q":"스마트팜의 문제점이 비용이 많이 든다는 점인데, 이것에 대해서는 어떻게 생각하시나요?","a":"스마트팜에 사용되는 여러 장치들은 부담을 발생시킵니다. 이로인해 기존의 방식으로 농산물을 생산하는 것보다 스마트팜을 도입했을 때 더 많은 생산비용이 든다는 문제점이 있습니다. 이를 해결하기 위해서는 정부의 역할이 중요하다고 생각합니다. 농업의 진흥을 위해서 스마트팜을 도입하고자 한다면, 스마트팜은 분명 긍정적인 효과가 있기 때문에, 현재보다 더 적극적인 지원을 필요로 할 것입니다."},{"q":"확률과 통계 시간에 베이즈 정리에 대해서 학습하였다고 했는데, 이에 대해서 말해주세요.","a":"기존 확률과 통계에서 배우는 확률에 대한 개념은 어떠한 사건이 발생할 확률에 대해서 다룹니다. 하지만, 베이즈 정리는 이와 다른 관점을 취합니다. 확률을 어떠한 주장에 대한 신뢰도의 관점에서 바라봅니다. 이러한 시각을 베이지안주의라고 합니다. 이는 어떠한 주장이 발생했을 때의 신뢰도인 사전확률과 이러한 주장이 실제로 발생할지, 발생하지 않을지에 대한 근거를 모아 이를 바탕으로 한 신뢰도인 사후확률의 관계를 다룹니다."},{"q":"전교 회장을 6개월밖에 안했네요? 이유가 있나요?","a":"원래 한 학년 동안 진행하였던 것이 2학기와 그다음 해 1학기까지로 임기가 바뀌어 그렇게 됐습니다."},{"q":"아.. 그렇군요. 그러면 회장 활동을 하면서 가장 힘들었던 점이 무엇이었나요?","a":"저는 부회장과 회장직을 모두 한 경험이 있습니다. 제가 부회장을 하면서 가장 중요하게 생각한 덕목이 소통이었습니다. 학생들을 위한 사업을 진행하기 위해서는 그들의 의견이 가장 중요하다고 생각했기 때문입니다. 이를 바탕으로 부회장 임기가 끝났을 때 학생들에게 인상깊었던 학생회 활동에 대해서 설문조사를 돌렸습니다. 그런데 학생들의 대부분의 답변은 학생회가 구체적으로 어떠한 활동을 하였는지 잘 모르겠다는 것이었습니다. 이에 작년에 소통을 중시하여 학생회 활동을 이끌어간 것이 잘 이루어지지 않았다고 생각을 하였습니다. 이에 회장에 당선된 후, 어떠한 것이 문제였는지 고민해 보았습니다. 그 결과, 학생회가 진행한 회의 등을 학생들에게 공개하는 것이 이러한 문제를 해결하기에 가장 적합하다고 생각하였습니다. 이에 대한 구체적인 방법으로 회의록을 작성해 모든 학생들이 이것을 볼 수 있도록 배포할 것을 계획하였습니다.(더 이야기하려고 했지만 시간 끝남.)후배들을 위한 조언 -다음에 어떻게 될지 모르겠지만, 면접관과의 거리가 생각보다 멀어서 덜 부담스러웠던 것 같아요. 특히 책상도 있었고요. 딱히 압박식으로 하는 면접이 아니어서 면접 분위기에 적응하기 펀했어요.-자율, 진로활동에서 한 활동들을 위주로 물어봤어요. 거기에 자기의 전공 관련해서 쓴 친구들은 유의 깊게 봐야할 것 같아요.-학교에서 면접 준비를 할 때 선생님께서 질문하고 다뤄준 부분에서 면접 질문이 많이 나왔어요. 학교에서 준비해 주시는 대로 충실하게 따라가는 것이 기본이고, 그 다음에 다른 걸 하는 것이 중요한 것 같아요."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(1권)」","year":"2025학년도"},{"univ":"서울대학교","dept":"농경제사회학부","jeonhyeong":"학생부종합(기회균형특별전형(사회통합))","method":"긴장을 풀기 위한 질문 → 면접 진행 순서 안내 → 국제관계와 국제기구 질문 → 추가질문 → 생기부 진로활동 탐구 질문 → 마지막으로 하고싶은 말 & 입학하게 되면 하고 싶은 것","notes":"조금은 당황스러운 질문이 나올 수 있습니다. 10분이라는 시간을 거의 칼같이 지킵니다.","qa":[{"q":"안녕하세요. 벌써 점심시간이 되어가는데, 몇시에 도착해서 기다리셨어요?","a":"저는 시작 30분전에 도착해 기다렸습니다."},{"q":"오래 기다리셨군요.. 그럼 어서 면접 시작하도록 하죠. 면접은 질문 3개에서 4개 정도 로 생기부에서 궁금한 점들을 몇 가지 물어볼게요. 먼저, 3학년 때 국제관계와 국제기구라는 과목을 수강했는데 이 과목은 왜 선택하신거죠?","a":"이 과목은 제가 학교 수업시간 외에 자발적으로 신청한 공동교육과정 수업입니다. 저는 경제에 대해 탐구를 하면서 국제기구들이 세계경제와 마치 거미줄처럼 복잡한 관계로 얽혀있음을 알게 되었습니다. 따라서 이 과목을 통해서 여러 국제기구와 각각이 하는 역할들, 특히 경제 분야에서의 역할들에 대해서 알아보고 싶어 선택했습니다."},{"q":"그렇다면 여러 국제기구의 역할에 대해서 공부했을 것 같은데요. 그렇다면 농경제와 관련된 국제기구 중에 어디에 가장 들어가고 싶나요? 이유와 기여하고자하는 부분이 있다면 그 또한 답변해 주십쇼.","a":"저는 지금 바로 떠오르는 것은 대표적인 국제기구인 OECD입니다. OECD는 경제협력개발기구라는 이름에서부터 알 수 있듯이 전 세계적인 경제 문제에 대해서 관여하는 국제기구입니다. OECD는 크게는 국제경제에 관여하지만, 그 안을 들여다보면 매우 세분화 되어 다양한 부서들이 존재하는데요, 이러한 부서 중에는 농업에 대한 부서나, 환경오염에 대한 부서 등이 존재합니다. 따라서 저는 환경문제를 해결하며 농업에 기여할 수 있는 OECD에 들어가고 싶습니다. 앞서 말씀드린 부서들을 통해서 농업에 있어 무역문제나 플렌테이션과 같은 사회문제를 해결함과 동시에 환경오염과 같은 사회문제를 해결하는데 기여하는 것이 저의 목표이기 때문입니다."},{"q":"다음 질문 드리겠습니다. 3학년 생기부 활동 중에서 ‘지역문제해결단’이라는 활동을 하면서 환경과 경제의 공동 발전에 대해서 탐구하였다는데, 이 활동에 대해서 설명해줄 수 있나요?","a":"네. 그 활동은 3학년때 지역홍보 팜플렛 활동을 하면서 지역의 다양한 명소를 소개하는 봉사활동에서 시작되었는데요, 이 활동을 하면서 지역의 여러 환경 문제를 다룬 기사를 접하게 되었습니다. 해당 기사에서 언급한 문제들 중 저는 수질오염 문제에 대해서 깊이 다뤄보고자 하였습니다. 이 탐구를 계획하고 실제로 해당 문제가 발생한 하천에서 수질 검사를 직접 수행하였고 그 심각성에 대해서 객관적 수치로 측정하였습니다. 저는 이 문제를 해결하기 위한 방안을 고안하기 위해 SWOT 분석을 통해 적절한 해결책으로 녹색일자리 마련을 제시하였고 탐구 과정과 제안 내용 담은 제언서를 지역기관에 제출하였습니다."},{"q":"SWOT 분석을 사용하셨다고 했는데, 이 분석법이 무엇인지, 그리고 어떻게 사용했는지 구체적으로 알려주시겠어요?","a":"SWOT 분석은 Strength, Weakness, Opportunity, Threat에 대해서 분석하고 확인하는 방법입니다. 저는 저의 지역의 환경문제를 해결을 위한 방법을 수행할 때 혹은 환경문제 해결 이후에 발생할 장단점과 창출된 기회에 대해서 이 분석법을 적용해 확인하였습니다."},{"q":"시간관계상 질문은 여기서 마치도록하겠습니다. 마지막으로 하고싶은 말이나 입학하게 된다면 하고싶은 것 등 자유롭게 얘기해주세요.","a":"고등학교 3년 동안 경제성장과 환경문제해결, 농업과 관련된 자원문제들에 관심을 가지고 탐구했습니다. 만약 입학하게 된다면 이러한 관심사에 대해서 더 깊고 확장해서 연구하고 싶습니다. 3학년 때 수행한 중장기 세미나 활동처럼 입학 시 여러 세미나에 참여해 공동체 역량을 기르고, 수리통계적 분석 능력을 여러 수업을 통해 기르고 싶습니다. 이를 통해 저의 최종적인 목표인 환경과 지역문제, 자원문제를 해결하면서 경제성장에 대해서 답을 낼 수 있는 경제성장 모델을 만드는 경제학자라는 꿈을 이룰 수 있게 해줄 것이라 생각합니다. 감사합니다. 후배들을 위한 조언 10분이라는 면접 시간이 절대 길지 않습니다. 자신이 하고싶은 말이 있다면 그 내용에 대해서 숙지하고 말하는 연습까지 해보는 것은 필수적입니다. 만약 질문에 대한 답이 늦어지거나 오래걸려 시간이 많이 사용되면 뒤 질문에서 답을 하다가 중간에 끊을 수 있습니다. 10분 시간을 엄격히 지킵니다. 9분 동안은 계속해서 질문을 하시고 마지막 1분에 문에서 노크 소리가 들리면 면접관이 마지막으로 말하고 싶은 말을 물어봅니다. 질문을 받았다면 최대한 그 질문에 대해서 답변하려고 하세요. 저는 20~30초 동안 답변을 고민하며 시간을 사용했는데, 면접관이 다른 질문을 하는 것이 아니라 면접관 또한 그 질문에 대한 답을 계속 기다립니다. 고려대와 연세대는 면접 대기실에서 자신이 가져온 노트나 생기부 혹은 제시문 면접 연습지 같은 공부 자료를 면접 전까지 볼 수 있게 하지만, 서울대 면접 대기실에서는 처음부터 가방과 모든 짐을 수거해 가기 때문에 기다리는 동안 면접에 대한 공부는 어려울 것입니다. 미리 공부해 가십시오. 확실하지는 않으나 질문이 3학년 생기부 위주로 나오는 것 같습니다. 이는 면접관마다 다를 수도 있지만 선례에서도 거의 3학년 내용을 많이 물어본 것을 보면 중요도 면에서 가장 중요한건 3학년 활동이라고 생각합니다."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(1권)」","year":"2025학년도"},{"univ":"서울대학교","dept":"농경제사회학부","jeonhyeong":"학생부종합(지역균형전형)","method":"생기부 관련 질문( 독과점 시장, 필립스 곡선, 넛지, 최저임금) > 마지막으로 할 말","notes":"","qa":[{"q":"음 3학년 때 독과점 시장에 대해서 탐구했었는데 독과점 시장에 대해 탐구하게 된 동기는 무엇인가요?","a":"제가 당시 외국 IT기업이 독점을 하고 있다는 뉴스를 보게 되었는데 이에 관심을 가지고 독과점 시장에 대해서 조사했었습니다."},{"q":"그러면 독과점 시장에 대해 탐구하면서 새롭게 알게 된 점은 무엇이 있을까요?","a":"조사를 하면서 독과점 시장의 개념, 효과 같은 이론들은 알고 있었지만 이번 탐구로 독과점 시장의 그래프를 기하적으로 해석해 보며 어떤 원리로 시장이 돌아가는지에 대해 새롭게 알게 되었습니다."},{"q":"필립스 곡선에 대해 조사했었네요. 그리고 필립스 곡선의 평탄화란 것을 조사하였는데 한번 필립스 곡선의 정의, 한계, 평탄화 현상에 대해 말해보세요.","a":"네, 우선 필립스 곡선의 정의는 물가상승률과 실업률이 음의 상관관계를 갖는 곡선을 의미합니다. 그리고 필립스 곡선의 한계는 스태그플레이션에서 볼 수 있는데요, 스태그플레이션은 공급이 감소하면서 물가상승률과 실업률이 동시에 높아지기 때문에 필립스 곡선으로 설명할 수 없습니다. 마지막으로 필립스 곡선의 평탄화 현상이란 현대 사회로 들어오면서 물가상승률과 실업률 사이의 상관관계가 약화되는 현상입니다."},{"q":"스태그플레이션이 곡급이 감소하면서 나타나는 현상이라 했는데 공급이 감소하는 경우는 무엇이 있을까요?","a":"(이때 질문을 잘못 들어서 답했다가 정정함) 정정하겠습니다. 공급이 감소하는 경우에는 원자재 가격 상승, 임금 상승 등이 있습니다."},{"q":"네. 3학년 때 넛지라는 책을 읽었는데, 이 넛지를 읽게 된 동기와 인상 깊었던 내용이 있을까요?","a":"제가 넛지를 읽게 된 동기는 처음 팩트풀니스란 책을 읽고 사람의 행동을 무의식적으로 의도한다는 점에 호기심을 느껴 더 알아보고자 넛지를 읽게 되었습니다. 넛지에서 인상 깊었던 내용은 넛지는 양날의 검이라는 표현이 인상 깊었습니다. 긍정적, 모두에게 이익이 되는 쪽으로 넛지를 사용하면 좋지만, 기업이나 정부에서 자신의 이익을 위해서만 넛지를 활용할 경우 사회적 후생을 감소시킬 수 있기 때문에 인상 깊었습니다."},{"q":"그러면 넛지를 농업에 활용할 수 있는 방안은 무엇이 있을까요?","a":"(여기서 머리가 하얘짐) 잠시 생각할 시간을 주시겠습니까? .... 농업에서 넛지는 지금도 볼 수 있습니다. 대표적으로 우리나라에서 정부가 쌀을 비싼 값에 사들이는 사례를 들 수 있는데요, 자국의 쌀을 계속해서 생산할 수 있게 도움으로써 자연스럽게 자국의 농업생산력과 경쟁력을 증진시키도록 유도할 수 있습니다."},{"q":"동아리 시간에 최저임금 인상에 따른 영향에 대해 시뮬레이션했다고 써있는데 어떤 결과를 도출했나요?","a":"네 저희는 탐구하면서 임금 인상에 따른 공급 감소가 경제에 부정적인 영향을 미친다는 결론을 도출하였습니다."},{"q":"그러면 결국 최저임금 인상이 부정적인 영향을 미친다는 거네요?","a":"네 그렇습니다. 저희가 실업률, 기업의 생산력, 실질GDP 등 다양한 요소를 종합해서 파악한 결과 미약하게 부정적인 영향을 미칠 수 있다는 것을 파악했습니다."},{"q":"(노크 소리 들림) 알겠습니다. 그럼 시간도 없는데 마지막으로 할 말 해주세요. 짧게 해야돼요.","a":"네 저는 학교생활을 하면서 어떤 어려운 것이 있으면 끝까지 해보려는 경향이 있었습니다. 일례로 미적분 과목 시간에 몇몇 개념에서 어려움을 느끼고 더 알기 위해 ap미적분학 강좌를 듣기도 하였습니다. 이렇듯 제가 서울대학교 농경제사회학부에 입학하게 된다면 이러한 저의 탐구 역량을 바탕으로 학업에 정진하겠습니다. 감사합니다.후배들을 위한 조언 우선 생각보다 편안한 분위기이고 교수님들도 면접을 통해서 분별한다거나 그런 태도를 가지지 않는 것이 보였습니다. 긴장하지 말고 하면 다 대답할 수 있습니다."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(1권)」","year":"2025학년도"},{"univ":"서울대학교","dept":"사회학과","jeonhyeong":"학생부종합(지역균형전형)","method":"동아리 독서질문->꼬리질문->영미문학 독서질문->진로활동->동아리활동 느낀 점->자율","notes":"지원동기나 마지막으로 하고 싶은 말을 안 물어볼 수 있음","qa":[{"q":"위험사회를 읽고 위험이 평등하다고 생각하는지 불평등하다고 생각하는지","a":"불평등하다고 주장->사회적 맥락에 따른 차이를 필두로 근거 제시"},{"q":"사회적 맥락이 구체적으로 무엇을 의미한다고 생각하는지","a":"가정환경이나 성장배경 등 보이지 않는 계급을 결정짓는 요소에 관해 설명"},{"q":"앵무새 죽이기를 읽고 무엇이 인상 깊었는지","a":"기억에 남는 구절 언급 / 왜 인상 깊었는지 설명"},{"q":"진로활동에서 언급한 정책에 대해 현실적인 경제적 대안","a":"기존에 마련된 시설 이용 / 외적인 측면 외에 심리적 측면에서 정책 제안 / 심리상담이나 복지프로그램을 대학생 자원봉사로 -> 경제적 대안"},{"q":"동아리 왜 만들었고 느낀 점 무엇인지","a":"교내에 사회동아리가 없어서 직접 만듦 / 비경쟁토론을 통해 다양한 관점에서~"},{"q":"시뮬라크르의 예시가 무엇인지","a":"무선이어폰 광고로 예시 설명후배들을 위한 조언 자신의 생기부를 제대로 숙지하고 있어야 함. 자율/진로/동아리/과목별 교과 세특에서 했던 활동을 동기/활동/느낀 점으로 정리하고 말할 수 있어야 함. 의견을 묻는 질문이 많아서 활동별로 자신의 의견을 명확하게 마련하는게 좋음. 눈으로 읽으면서 연습하지 말고 말하면서 연습하는 걸 추천함."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(1권)」","year":"2025학년도"},{"univ":"서울대학교","dept":"소비자아동학부(소비자학전공)","jeonhyeong":"학생부종합(지역균형전형)","method":"자율활동 질문 -> 진로활동 질문 -> 동아리활동 질문","notes":"두 개의 알람시계가 울림 시간확인용","qa":[{"q":"3학년 때 씨커머스에 대한 활동을 했는데 이 정부 규제의 문제점은 뭐라고 생각해요?","a":"소비자들이 납득할만한 규제 기준과 인증 절차를 도입하지 않은 것"},{"q":"왜 KC 인증 마크가 공정하지 않다고 생각해요? 그리고 어떻게 보완할 수 있어요?","a":"정당하고 투명한 규제 기준을 소비자들에게 알리지 않았기 때문 / 새로운 인증 절차를 도입하거나 타국 기관에 의뢰하는 등"},{"q":"인증이란 게 엄청 전문적인 기관에서 하는 건데 그럼 어디서 담당해야 하죠?","a":"정부 / 다만 투명하고 공정한 절차와 기준을 도입한 새로운 기관 개설"},{"q":"2학년 때 진로 활동에서 소비자 심리에 어떤 요소가 영향을 미치죠?","a":"당시엔 국가 관계 즉, 일본과의 갈등으로 인한 노재팬 불매운동 탐구"},{"q":"그럼 소비자들의 취향이 배제된 No 재팬이 불매운동이 비합리적인 소비라 생각하나요?","a":"불매를 선택한 거 자체가 현재의 정치 상황을 인식한 가치관과 신념 담긴 취향이라고 생각하므로 합리적"},{"q":"그럼 지금처럼 일본을 막 소비하는 게 학생입장에선 문제가 있다고 보겠네요?","a":"소비자들의 인식 변화와 가치관 차이 등에 따른 자연스러운 선택이므로 문제가 있다고 보긴 어렵다"},{"q":"3학년 동아리 때 한 인센티브가 궁금해요 어떤 활동이죠?","a":"조사 -> 나이 별 유동적인 임금 적용 -> 효율성을 높이고자 젊은 세대는 성과급 개인 기성 세대는 시간급 단체 책정"},{"q":"그럼 형평성에 어긋나지 않나요? 임금이 형평성에 어긋나도 된다고 생각하나요?","a":"공평해야 효율성이 증진된다고 생각함 차별 해결을 위해 비금전적 보상을 늘림 칭찬 명 예 동료와의 우호적 관계 등후배들을 위한 조언 편하게 해주시니까 떨지 마세요. 생기부 분석이랑 답변 준비도 중요하지만 꼬리질문에 대비해 평소 자신의 가치관과 전공의 대한 방향성을 확실히 해두는 게 더 중요한 것 같습니다. 그래야 당당하고 일관적인 답변이 나오는 것 같아요."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(1권)」","year":"2025학년도"},{"univ":"서울대학교","dept":"소비자아동학부(아동가족학전공)","jeonhyeong":"학생부종합(지역균형전형)","method":"동아리 활동 질문 → 세특 질문 → 진로 변경 이유 → 대학교 와서 하고 싶은 것 → 진로 변경을 결심하게 된 책(이름만 말하라고 함)","notes":"면접실이 생각보다 매우 작음","qa":[{"q":"3학년 동아리 시간에 저출산 완화를 위한 현행 제도와 성과 평가 및 개선방안에 대해 탐구했네요. 결론으로 현대 사회의 가족형태를 이해하는 것이 중요하다고 말했는데 그 이유가 무엇인가요?","a":"저는 현재 저출산 관련 예산 규모도 증가하고 있고 다양한 정책이 실시되고 있음에도 저출산 문제가 심각해지고 있는 것에 대해 의구심이 들어 이 탐구를 시작하게 되었습니다. 다양한 정책과 예산 규모를 파악하는 과정을 거쳤고, 결론적으로 출산율이 가장 높았던 전라남도의 사례를 통해 현대 사회의 가족형태를 이해하는 것이 중요하다는 것을 알게 되었습니다. 전라남도에서는 조부모에게 육아 수당을 지급하는 정책을 실시하고 있었습니다. 전라남도에서는 단순히 양육의 주체를 어머니와 아버지로 한정짓지 않고, 조부모일 수 있음을 고려하였기 때문에, 즉 다양한 양육의 주체를 고려하였기 때문에 저출산 문제 해결에 있어서 효과를 얻었습니다. 따라서 저는 이 탐구를 통해 현대 사회의 변화하는 가족형태를 이해하는 것이 중요하다고 결론을 내리게 되었습니다."},{"q":"동아리 활동 중 정책의 예산규모 적절성과 경제적 효과성을 평가하는 역할을 맡았네요. 어떻게 진행했는지?","a":"저는 매 해마다 예산의 규모가 증가하고 있음을 수치를 통해 확인하였습니다. 하지만 매년 예산의 규모는 증가하고 있었지만, 출산율은 점점 낮아지고 있는 추세임을 확인하였습니다. 이를 통해 현재 저출산 관련 정책이 제대로 실시되고 있는 것인지, 현재 실시되고 있는 정책의 방향성이 올바른 것인지를 확인하여야 하고 사회의 변화에 맞는 정책이 수립되어야 한다고 결론을 내렸습니다."},{"q":"동아리 조장으로 어떤 역할을 했는지?","a":"저는 일단 조장으로서 각자의 역할을 분담하였습니다. 각자 조사한 후 함께 모여 소통하며 의견을 나누었습니다. 저는 메신저를 활용한 소통보다는 직접 만나서 대화하며 의견을 조정하는 것이 중요하다고 생각했기 때문에 조원들과 직접 모이는 시간을 많이 가졌습니다. 그 결과 다양한 생각을 교환할 수 있었고, 저출산 문제에 대해 다양한 해결책을 도출해낼 수 있었습니다."},{"q":"사회문화 시간에 조부모와의 관계가 노인 혐오 태도 형성에 미치는 영향을 탐구했는데 그 때 세운 가설과 탐구한 과정 설명해보세요.","a":"저는 조부모와의 언어적 상호작용이 많을수록 노인 혐오 표현을 적게 사용할 것이라고 가설을 세워 탐구했습니다. 한 달동안 조부모와의 언어적 상호작용 횟수와 노인혐오표현 사용횟수를 스스로 기록하여 제가 제시하는 질문지에 기입하는 질문지법을 활용한 탐구를 진행했습니다. 가설을 검증한 결과 언어적 상호작용이 증가할 수록 노인 혐오 표현 사용횟수가 적어진다는 결과가 도출되었고, 이를 통해 조부모와의 상호작용뿐만 아니라 소통을 강화하는 것이 혐오 표현 사용, 편견 형성을 줄이는데 효과적임을 확인하였습니다."},{"q":"그러면 질문지는 어떻게 구성했나요?","a":"저는 조부모와의 상호작용과 노인혐오표현 사용 정도를 수치화해서 표현했습니다. 구체적으로 한 달에 5번 미만, 5번 이상 10번 미만, 10번 이상 20번 미만 이런 식으로 표현했습니다."},{"q":"1학년 때는 초등교사, 2학년 때는 사회학, 3학년 때는 아동가족학으로 진로를 바꾸었는데 어떻게 이렇게 바꾸게 되었는지 설명해주세요.","a":"저는 누군가를 도와주는 일을 하고 싶었습니다. 1학년 때 제가 생각하기에 누군가를 돕는다는 것은 모르는 것을 알려준다는 의미로, 그래서 가르침이라고만 생각해서 초등교사를 희망했었습니다. 하지만 학년을 거듭하면서 여러 분야의 책도 읽고 활동도 하면서 타인을 돕는다는 것은 단순히 교육을 통해서만 이루어진다는 것이 아니라는 것을 알게 되었습니다. 그리고 무엇보다도 사회 전체를 이해하고 사회 문제에 관심을 갖게 되는 것이 도움을 주는 것에 있어서 중요하다는 것을 알게 되었습니다. 그래서 사회학에 관심을 갖게 되었습니다. 하지만 사회 문제를 해결하기 위해서는 근본적으로 인간에 대한 이해가 필요하다는 것을 알게 되었습니다. 사회라는 것은 결국 인간의 일이기 때문입니다. 따라서 인간이 처한 가정환경, 또는 가족관계, 그 사람이 살아온 생애를 전반적으로 이해하는 것이 필요함을 느껴 인간의 본질에 가장 맞닿아 있는 아동가족학에 관심을 갖게 되었고, 이 학과에 지원하게 되었습니다."},{"q":"마지막으로 이 학과에 지원하기로 결심한데 영향을 준 책은?","a":"(시간 없어서 책 제목만 말하라고 함) 루소의 에밀입니다.후배들을 위한 조언 면접 준비할 때 최소한 생기부에 적힌 본인이 한 활동은 꼭 숙지하는게 중요할 것 같아요. 구체적으로 어떤 과정으로 했는지는 설명할 수 있어야 합니다. 그리고 면접 시간이 10분 정도로 매우 짧으니, 질문의 핵심을 파악해서 답변이 너무 길어지지 않도록 주의해야 합니다."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(1권)」","year":"2025학년도"},{"univ":"서울대학교","dept":"소비자아동학부(아동가족학전공)","jeonhyeong":"학생부종합(지역균형전형)","method":"학과와 관련된 진로 생기부 질문 (2) → 학과와 관련된 수업량 유연화 생기부 질문 (2) → 학생회장 관련 질문 (2) → 지원동기","notes":"8시 30분까지 입실이라면, 8시까지는 도착해 있기!(어떤 상황이 발생할지 알 수 없으므로)","qa":[{"q":"중위소득은 증가하는데 상대적 빈곤선이 증가하는 것에 의문을 품고 탐구했는데, 그 과정을 들어볼 수 있을까요?","a":"정확히 기억 나지 않음."},{"q":"아 그래서 부양의무자 기준 폐지가 이유가 될 수 있다고 생각하셨나요?","a":"넵, 전 그 과정에서 양극화의 문제가 아닌, 중위소득이 증가하는 선진국으로 나아가는 과정에서 오히려 국가가 부양의무자 기준을 폐지한다는 것을 알 수 있었습니다. 현재 대한민국은 부양의무자 기준 폐지를 통해 극빈층을 위한 공공부조를 늘리고 있다는 사실을 알 수 있었습니다."},{"q":"모바일 투표 엠보팅과 같은 노령층을 위한 어떤 서비스가 필요할지에 대해서 설명을 해주세요.","a":"어떠한 서비스도 단순히 기기 전달과 기술을 보급하는 것만으로는 해결이 되지 않는다고 생각합니다. 기기전달과 기술이 보급되더라도 노령층은 그 사용법을 잘 익히지 못한다는 어려움을 겪기 때문입니다. 기술적 문제를 해결하는 것이 아닌 실제 사용할 수 있으며 적용할 수 있는 교육과 서비스가 시급하다고 생각합니다."},{"q":"노령층의 기술 교육이 된다면 노령층의 정치참여가 가능하다고 보는지?","a":"제가 여기에서 말씀드린 정치참여는 국회의원 선거와 같은 큰 범주의 정치참여가 아닙니다. 시와 동에서 진행하는 그러한 소 범주적 주민참여 요소를 의미합니다. 제가 생각하기에 이러한 주민참여에서 노년층의 의견 수렴이 잘 되지 않는 이유는 그들이 주민참여를 하는 방법을 모르기 때문이라고 생각합니다. 정보화 시대속 흔히 디지털 기기로 진행하고 있는 사이트등을 이용할 수 있는 방법들과 교육등을 통해서 노년층의 의견수렴이 가능하다고 보고 있습니다."},{"q":"지원자 학생은 뛰어난 리더십 역량을 계속해서 보이고 왔던것 같습니다. 그 중 학생회장으로서의 모습이 인상깊은데요, 지원자가 추구해왔던 리더십을 한마디로 표현해 볼 수 있을까요?","a":"통찰력 있고 공감할 줄 아는 리더십인것 같습니다. 저는 사회문제에 대해 관심이 많기에 학교 문제에도 관심이 많습니다. 학교 문제의 원인을 분석하고 어떻게 문제를 해결할지에 대한 고민을 많이 해왔습니다. 학생회 친구들의 능력과 역량을 잘 알고 있기 때문에 필요한 부분에 전략적으로 그들을 배치함으로써 문제를 효율적으로 해결할 수 있었습니다. 또한 제가 생각하기에 리더는 단순히 앞에서 구성원들을 끌고 나가는 것 뿐만 아니라 그들과 함께 같이 나아갈 수 있는 것이라고 생각합니다. 따라서 그들이 진정으로 원하는 것은 무엇인지, 필요한 것은 무엇인지 등을 소통하고 이해하며 공감할 줄 아는 그러한 리더십을 키워왔습니다."},{"q":"학생회장을 하면서 의미있었던 사건이 있을까요?","a":"제 다음 학생회장, 부회장 선거를 위한 후보 발표회, 토론회가 있었습니다. 순조롭게 학생회 측에서준비한 대로 진행되는 과정속에서 방송사고가 생겨 송출할 수 없는 상황이 생겼습니다. 송출할 수 없는 상황이란 선거권을 가진 모든 학생들이 토론회와 발표회를 볼 수 없기에 선거에 차질이 생기는 분명한 문제상황이었습니다. 도저히 방송 문제가 해결되지 않는 과정속에서 저는 긴급히 부장회의를 진행했습니다. 각 부서의 친구들이 긴급히 의견을 제시하던 과정속에서 각 부장의 방안을 듣던 전 한 부장의 강당으로 옮겨서 진행하자는 말에 타당성이 있고 가장 이 문제를 이겨낼 수 있는 방안이라 생각해 진행했습니다. 체육부 부장에게는 모든 학생들이 질서있고 안전하게 강당으로 이동할 수 있도록 하는 안전적 책임을 부여했고, 방송부 부장에게는 지금 즉시 강당으로 이동해 마이크,스피커와 같은 방송적 책임을 부여했으며 기획부 부장에게는 스케줄이 변경된 상황속에서 스케줄의 긴급한 재구성을 요구했습니다. 등등 많은 부장들에게도 그러한 책임과 역할을 부여했고 결국 모든 부장이 각 위치에서 자신들의 각각의 일들을 너무 잘해주어 좋은 마무리를 지을 수 있었던 것 같습니다.[면접관] 아~ 잘 들었습니다. 제가 깨달은 것도 말씀드려도 괜찮을까요?[면접관] 네, 하셔도 됩니다.저 혼자였다면 이 문제를 절대로 효율성 있게 해결할 수 없었으리라 생각됩니다. 더 나아가서 문제 자체도 해결하지 못했을 수도 있다는 생각이 들었습니다. 부장들의 의견을 모두 듣고 이해하는 과정속 지금의 상황에 맞는 가장 적합한 방안을 선택할 수 있다는 점에서 조직에서의 원활한 의사소통방식은 필수적이라는 점을 깨달을 수 있었습니다. 또, 리더란 조직 구성원 모두의 의견에 귀를 기울이는것이 필요하다는 교훈을 얻을 수 있었습니다."},{"q":"마지막으로 지원동기를 들어볼 수 있을까요? 또, 어떤 사람이 되고 싶나요?","a":"아동가족학과에 지원하게 된 계기는 제가 사회문제에 관심이 많기 때문입니다. 제가 좋아하는 철학자 아리스토텔레스는 이렇게 말했습니다. “최초의 공동체는 가족이며, 가족의 설명 없이는 어떠한 공동체도 이해할 수 없다” 저는 이런 아리스토텔레스의 말에 공감할 수 있었습니다. 내가 가족문제의 이해와 연구를 하지 않음에도 불구하고 더 큰 사회의 문제를 해결할 수 있을까에 대해서 생각했습니다. 따라서 아동가족학과에 지원해 가족에 대한 깊이 있는 이해를 바탕으로 사회문제 해결을 위한 기초적 토대를 마련하고자 합니다. 궁극적으로는 아동, 여성, 노인, 다문화가정, 더 나아가 모든 국민들의 삶의 질과 복지 향상을 위한 정책 제시를 하는 정책 연구원이 되고 싶습니다. 감사합니다.후배들을 위한 조언"},{"q":"준비한 것을 끝까지 보여주려고 노력하기. -생각나는 것이 있다면, 말씀드려도 되는지 여부를 꼭 확인하고 말할 수 있도록 하기. 후회가 안 남도록 하는 면접이 최고의 면접이라고 생각됨!","a":""},{"q":"진실성 있게 말씀드리기-내가 얼마나 이 학과에 관심 있고, 이 대학에 관심있 는지 눈빛과 말투를 통해 알 수 있다고 확신함. 물론 진짜 가고 싶은 학교, 학과라면 자연스레 나오겠지만 혹시나 그렇지 않더라도, 진실 되게 말씀드리고자 노력하기.","a":""},{"q":"들어가고, 끝맺음할 때 인사를 꼭 드리기.-면접관분들이 서류를 확인하시느라 인사를 못 보실 수도 있지만, 그럼에도 불구하고 인사드려야 하는 타이밍은 4번이 있음! *인사해야 할 타이밍-노크하고 조심히 들어가서 문을 닫고 난 후 인사드리기 -의자에 앉기 전 옆에서 인사드리기-의자에서 일어난 후 옆에서 인사드리기-나가기 전 인사드리기","a":""}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(1권)」","year":"2025학년도"},{"univ":"서울대학교","dept":"인문계열","jeonhyeong":"학생부종합(지역균형전형)","method":"-면접관 2명, 학생 1명-1조 당 16~17명씩 5개조로 구성-9시부터 시작, 면접 번호 순서대로 10분씩 진행-면접 번호는 랜덤으로 지정(미리 정해져 있었음)-대기실 입실과 동시에 개인 자료는 각자 가방에 넣어서 보관해야 함(읽고 싶으면 입실 전에 미리 읽어보고 가는 것 추천)","notes":"-대기실에서 먹을 것(마실 것, 간단한 간식) 정도는 꺼내놓을 수 있게 해줌(케바케 O)-히터 틀었는데도 개인적으로는 약간 추워서 핫팩 챙겨가는 것 추천","qa":[{"q":"안녕하세요~ 길이 많이 얼었는데 오늘 길에 미끄러지지는 않았나요?","a":"네! 다행히 미끄러지지 않고 잘 왔습니다 ㅎㅎ"},{"q":"네 이제 본격적으로 면접 진행할게요. 3년 동안 읽은 책들중에서 저희들에게 소개해주고 싶은 책이 있나요?","a":"저는 ‘존 롤스 정의론’이라는 책을 가장 소개시켜 드리고 싶은데요, (정의론 간략하게 이야기 + 왜 인상 깊었는지 간략하게 답변)"},{"q":"네 안 그래도 롤스의 정의론과 관련해서 생기부에 많은 내용이 있더라구요. 2학년 윤리와 사상 시간에 존 롤스의 자유주의적 평등주의를 말했는데 자유주의와 평등주의가 양립가능한 개념인지 잘 이해가 안 가서요 구체적으로 설명해주실래요?","a":"통상적으로 자유와 평등을 상호 대립적인 관계로 자유를 보장하면 평등이 평등을 보장하면 자유가 침해된다는 인식이 있을 수 있는데요, 롤스는 1원칙에서 모든 사람에게 기본적 자유를 평등하게 보장해야 한다고 말하며 평등과 자유의 개념을 조화시켰다고 생각했습니다."},{"q":"언어와 매체 시간에 사잇소리 현상을 비판한 내용이 적혀있는데 자세히 좀 설명해줄래요?","a":"처음에는 ‘갈등’이라는 단어에서 의문이 들어 자세히 알아보기 시작했는데요, 학교에서 ‘갈등’에서 나타나는 ‘ㄷ’의 경음화를 된소리되기로 배우고 이를 사잇소리 현상으로도 접근할 수 있지 않을까 라고 생각하면서 사잇소리 현상은 ㄴ첨가와 된소리 되기 현상 등이 겹쳐서 나타나기에 정확하게 구분되지 않는 점을 비판하였고, 된소리 되기 현상과 겹치는 부분이 있기에 비경제적이라고 비판하였습니다."},{"q":"프로그래밍 시간에 AI 리터러시 역량이 필요하다고 적혀있는데 AI 리터러시가 뭔지 설명해줄래요?","a":"최근 챗 GPT 등의 생성형 AI의 등장으로 많은 사람이 이를 활용하는 것으로 알고 있습니다. 하지만 이러한 생성형 AI는 학습 과정에서 정보를 무분별하게 학습하기에 정확하지 않거나 사회적으로 문제가 될 수 있는 정보를 학습하고 사용자에게 제시할 수 있습니다. 이에 이를 보완하기 위해 다른 매체를 활용해 정보의 진위를 교차검증하거나 관련 논문을 탐독하는 등의 노력이 필요하다고 생각했습니다."},{"q":"그러면 처음부터 다른 매체나 논문을 탐독하면서 그런 식으로 연구하면 안 되나?","a":"탐구 초기 과정에서 정보를 수집하는 과정은 상당한 노력이 드는 과정입니다. 하지만 생성형 AI는 정보의 수집에서 드는 노력을 상당 부분 감축시켜 줄 수 있습니다. 이러한 생성형 AI의 장점을 취하면서도 동시에 한계를 보완하기 위해 AI 리터러시의 함양이 필요하다고 생각했습니다."},{"q":"고등학교에서 동아리 활동을 하면서 본인이 동아리를 선정했던 기준을 말해주고 동아리 활동을 하면서 기억에 남는 활동을 말해보세요.","a":"(약간 당황) 음, 저는 1, 2학년 때 비즈니스라는 경영, 경제 동아리에 들어 동아리 활동을 하였는데요, 제가 중요하게 생각한 동아리 선정 기준은 선배들이 제시해주는 동아리 활동 계획이었습니다. (이후에 대충 이런저런 이야기 하면서 얼버무림)가장 기억에 남는 활동은 ESG 경영 관련해서 1학년 활동 -> 2학년 활동까지 자연스럽게 제시함."},{"q":"오 그 동아리 활동 좀 더 자세히 설명해볼래요?","a":"1학년때 ESG경영 개념에 대해 자세히 공부하고자 책을 탐독하고 논문을 탐독하였습니다. ESG경영이 기업의 이미지와 가격 공정성에 대해 긍정적 영향을 미친다는 연구 결과를 보고 이를 실제로 알아보고자 2학년 때 직접 자치 매점 활동을 진행하였습니다."},{"q":"그래서 실제로 어떤 결과가 나타났나요?","a":"매점을 이원화하여 한 매점에서는 ESG 경영활동을 하고 있다고 적극적으로 홍보를 하였고 한 매점에서는 이를 홍보하지 않았는데 추후 구매자를 대상으로 가격 공정성에 대한 인식을 설문조사 한 결과 홍보를 한 매점에서 가격 공정성에 대한 인식이 더 긍정적인 결과가 나타났습니다."},{"q":"그 매점에서 구매한 소비자들이 가격을 더 합리적이라고 인식했다는 것이죠?","a":"네 맞습니다!이쯤 노크 소리 들림"},{"q":"아 시간이 다 끝났네요. 수고했어요.","a":"아직 다 보여드리지 못한 것 같아 조금 아쉬운데 이 학교에 입학한다면 더 다양한 모습 보여드리고 싶습니다! 감사합니다.후배들을 위한 조언 -준비 과정저는 수능이 끝나고 1주일 뒤가 1차 발표였고 그 다음 주가 면접이었기에 수능이 끝나고 2주 정도의 면접 준비 시간이 있었습니다. 이걸 보고 있는 친구가 현재 어떤 상황인지는 모르겠으나 2주 정도의 기간은 생기부 기반 면접 준비를 하는데 절대 부족한 시간이 아니라고 생각합니다. 본인이 하고자 하는 의지와 약간의 밤샘이 있다면 생기부 숙지는 3일 정도 만에도 어느 정도 가능하다고 생각하기에 본인이 늦었다고 생각하고 포기하지 말고 그냥 본인에게 주어진 상황 내에서 최선을 다하는 것이 중요하다고 생각합니다.준비과정에서 저는 학교 선생님들의 모의면접의 도움을 크게 받았습니다. 다 숙지가 되어있다고 생각한 생기부에서의 허점을 발견할 수 있었고 말할 때 나타나는 안 좋은 습관도 파악할 수 있었습니다. 그리고 여러 회차 모의 면접을 진행하며 면접의 형식 자체에 좀 익숙해질 수 있었던 것이 아주 큰 도움이 된 것 같습니다. 본인이 아직 준비가 안 되었다고 생각이 들더라도 도망치지 말고 모의면접에 부딪혀 보는 것은 본인의 현재 상태를 파악하고 앞으로의 면접 준비를 하는데에 방향성을 제시해 줄 수 있을 것이라 생각하기에 모의면접은 가급적 빨리 자주 하셨으면 좋겠습니다. -면접 전대기실에 입실하고 지정된 본인의 번호에 따라 대기 시간도 정해지게 되는데 저의 경우에는 대기 시간에 개인 자료를 읽을 수 없었기에 아무것도 할 수 있는 것이 없었습니다. 이때 저는 커피를 홀짝홀짝 마시면서 계속 이미지 트레이닝을 했습니다. 면접실에 들어가는 순간부터 마지막 한마디까지 모든 과정을 매번 다르게 시뮬레이션을 돌려보며 이미지 트레이닝을 하려 했습니다. 저는 1시간정도를 대기했기에 크게 지루하거나 답답하지는 않았는데 뒷번호가 걸린 학생들 중에는 자는 학생들도 몇몇 있었습니다. 면접 전에는 계속 이미지 트레이닝을 하면서 너무 떨지 않도록 침착하게 평정심을 유지하는 것이 가장 중요합니다. 저는 평정심을 유지하려 계속 명상을 하였는데 본인만의 평정심 유지 방법을 찾아가는 것도 면접에 있어서 중요한 부분이라고 생각이 듭니당."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(1권)」","year":"2025학년도"},{"univ":"서울대학교","dept":"경제학부","jeonhyeong":"학생부종합(일반전형서울대 경제학부 일반전형은 제시문 기반 면접이며 사회과학 제시문과 인문 수학 제시문 각각 한 세트씩 제공됨.1. 대기실 입장 및 대기실대기실로 입장할 때 신분증과 수험표를 제시함. 입실 완료 시간 이후 가번호와 전자기기 수거 봉투를 지급하며 신분증과 수험표를 재확인 함. 전자기기 수거 후에는 준비한 종이자료만 열람이 가능함.2. 준비실가번호에 따라 순차적으로 면접도우미를 따라 준비실로 이동함(학과별로 정원 인원이 많은 경우 조를 나누기도 함). 대기실로 재입장이)","method":"불가하니 자신의 짐을 모두 챙겨야 함. 준비실이 일반적인 건물의 복도인 경우가 많으므로 이어플러그를 가져가는 것을 추천함. 30분 동안 제시문에 대한 답을 구상지에 써내려가며 준비한 후 구상지와 문제지 모두 면접 장소로 가져감.3. 면접실교수님 두 분이 계시며, 교수님의 지시대로 제시문 답변 순서가 결정될 때도 있고 자신이 원하는 순서대로 답변이 가능한 경우도 있음. 답변 내용에 오류, 궁금증 등이 있다면 추가질문이 이어지는 방식. 수학 제시문에 답할 때는 칠판 또는 화이트보드 사용이 가능함. 15분 동안 답변 및 추가질문 한 후 면접 종료됨. 면접도우미로부터 수거한 전자기기를 받고 소지품을 챙겨 귀가.","notes":"수험표, 신분증 꼭 챙기기칠판, 화이트보드 사용 시 면접 종료 후 지우기","qa":[{"q":"안녕하세요?","a":"안녕하십니까?"},{"q":"바로 면접 시작하겠습니다. 어떤 제시문부터 하실래요?","a":"사회과학 제시문 먼저 하겠습니다."},{"q":"네. 진행하시죠.","a":"네. 사회과학 제시문 1번에 대해 답하겠습니다. ~ 이상입니다."},{"q":"잘 들었습니다. 다음 답 해주시죠.","a":"네 2번 문제에 대해 답하겠습니다. ~ 이상입니다."},{"q":"말씀하신 것 중 낙인이론에 대해 언급이 있었는데, 제시문의 내용과 낙인이론이 완전히 같다고 할 수 있나요? 짧게만 답변해주세요.","a":"~한 점에서는 같다고 생각합니다."},{"q":"네. 그럼 이제 수학 해볼까요? 뒤에 있는 화이트 보드 사용하셔도 됩니다. 아, 그전에 혹시 몇 번까지 푸셨나요?","a":"1번만 풀었지만 2번을 여기서 해결할 수 있을 것 같습니다."},{"q":"네. 진행하시죠.","a":"1번의 정답은 ~ 입니다. ~"},{"q":"네, 그럼 2번 설명해주세요","a":"2번은 ~한 방식으로 진행 됩니다. (면접장에서 규칙을 발견함.) ~ 그래서 답은 ~ 입니다.(시간 거의 종료됨)"},{"q":"그럼 3번은 생각 못해보신거죠?","a":"네 그렇습니다."},{"q":"네 수고하셨습니다.","a":"감사합니다.후배들을 위한 조언 생각한 것보다 교수님들이 친절하심. 긴장하지 말기.학생부에 대한 내용은 시간이 남으면 물어본다고 함. 당연히 제시문 기반 면접이므로 제시문 준비에 전력을 쏟아야 하지만 만약의 경우를 대비해 학생부 내용과 지원 동기 정도는 간단하게 생각해보는 건 좋음.교수님께서 추가 질문을 하신다면 자신의 답변에 오류가 있을 가능성도 있으니 자신의 주장을 관철하려고만 하기보단 교수님의 의견도 수용하여 답변하면 좋겠음."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(1권)」","year":"2025학년도"},{"univ":"서울대학교","dept":"사회학과","jeonhyeong":"학생부종합(일반전형[오전]7시 20분 입실 시작, 8시까지 면접 건물 입실 → 강의실로 보이는 큰 대기실에서 학과별 지정석 대기(우리는 인류학과랑 같이썼음). 이 때까)","method":"지 화장실 자유롭게 가고 공부해도 됨. 핸드폰은 꺼서 봉투에 넣고 가방에 넣음. 랜덤으로 번호표 받아 가슴에 붙임. → 번호표 순서대로 두명 정도씩 짐 다 챙겨서 면접실 앞으로 이동 → 면접실 문앞 복도에 책상과 볼펜이 있고 거기서 30분동안 제시문 풀고 시간되면 면접실 문열고 들어감(안내해주시는 분이 계심) → 15분 면접 후 바로 퇴실","notes":"새벽부터 엄청 막히고 복잡하니까 일찍 출발해야함, 걷거나 대중교통 이용할 것(택시 말고 버스추천. 늦으면 전동킥보드라도...)","qa":[{"q":"<문제 1> (가),(나),(다)에 드러난 관점 3개를 비교하고 자신의 독서 경험을 예시로 들어 본인의 입장을 밝혀라.","a":"(관점 비교하는 중간에 말을 자르고 바로 내 입장이 뭐냐고 물어보심) 나는 제시문 (가)의 관점에 동의한다. 번역 활동에 있어서 읽는 사람의 내용 이해가 가장 우선이니 번역가의 언어에 맞게 자연스럽게 바꾸는게 중요하기 때문이다. 이전에 소설 ‘데미안’을 상대적으로 친절한 번역본과 그렇지 않은 번역본을 둘 다 읽은 적 있는데 전자가 훨씬 내용을 이해하기 쉬웠다. 또한 번역가의 주관적인 해석과 재창조는 비평과 같은 다른 활동으로도 가능하다는 점에서 제시문 (다) 말고 (가)를 선택했다."},{"q":"<문제 2> 그 세 가지 관점을 역사학에 접목해 설명하고 각각의 사례를 들어라","a":"(가)→역사를 지금 시점에 맞게 쉽게 해석해야 한다, 예) 조선시대 삼사를 오늘날 언론기관으로 바꿔서 해석 / (나)→ 역사를 그 당시 시대상으로만 그자체로 이해해야 한다 예) 조선시대 삼사를 그 자체로만 이해 / (다)→ 역사를 해석할 때 새로운 의미를 끌어내야 한다. 예) 조선 초기 고려시대 역사서를 재해석하여 조선왕조의 정당성 부여"},{"q":"(추가 질문) 그럼 우리가 북한에 대해서는 이들 중 어떤 관점으로 이해해야 할지 말해봐라.","a":"(나)의 관점으로 이해해야 한다. 왜냐하면.. → [그럼 아까 말한 네 입장과 충돌하지 않냐] → (생각할 시간을 가진 후) 먼저 (나)처럼 북한을 그 자체로 객관적으로 파악한 후 이를 바탕으로 종국엔 우리의 관점에서 이해해야한다고 생각한다 → [그건 (다)의 관점이 아니냐] → (말문이 막힘) → 일단 넘어가자고 하심..<사회과학 제시문> 자기예언적 확언의 개념 1개와 사례 2개"},{"q":"<문제 1> (가)에 제시된 개념이 (나)와 (다)에 어떻게 나타나고 있는지 비교하시오.","a":"(가)에 제시된 개념은 자기예언적 확언인데 ~~라는 개념이다. (나)에서는 자기예언적 확언으로 인한 문제점만을 말하고 있지만 (다)에서는 자기예언적 확언으로 발생한 문제뿐만 아니라 자기예언적 확언을 역할용해 이 문제상황을 해결한 사례가 나와있다."},{"q":"(추가 질문) 역할용했다는걸 더 자세하게 말해봐라.","a":"물가가 상승할거라는 자기예언적인 사람들의 믿음이 현실화되어 물가 상승이라는 문제가 발생했는데, 정부에서 물가 상승 목표치를 설정하면서 그에 따른 자기예언적인 믿음을 만들어냄으로써 물가 상승을 안정화했다."},{"q":"(추가 질문) 자기예언적 확언이 믿음만으로 이루어진다고 생각하느냐? 다른건 없나?","a":"그렇지 않다. 3가지 요건이 필요하다고 생각한다. 1. 어떤일이 발생할거라는 사람들의 믿음, 2. 그 예상되는 일에 대한 사람들의 감정 동요(공포심 등) 3. 그로 인한 실질적인 행동 및 실천 이다.(이어서) 그럼 방금 말한 그 3가지 요건에 맞춰서 문제 2번을 답해봐라."},{"q":"<문제 2> 자기예언적 확언의 문제를 해결하기 위한 해결 노력의 주체를 <보기>에서 3명을 골라 각각의 해결방법을 말하시오.","a":"(추가질문 답변내용이랑 갑자기 연결해서 말하라니 당황함. 정확히 기억은 안나는데 ‘연구자’→ 사람들이 정확한 믿음을 가질수있도록 돕기. ‘언론’→ 사람들의 잘못되거나 과도한 감정 동요를 조장하지 않기. ‘정책 책임자’→ (다)의 사례처럼 사태를 파악하고 문제 해결을 위한 정책을 마련하기. 이런식으로 답한 것 같다.)"},{"q":"(추가 질문) 시간이 1분밖에 안 남았다. 마지막으로 이렇게 문제상황과 다양한 해결주체들이 있을 때 어떤 가치가 가장 중요하다고 생각하는가?","a":"‘공감’이라고 생각한다. 공감의 태도를 기르기 위해 정책적으로는 숙의민주주의를 활성화해 공론장을 마련하고 개인적으로는 다양한 사람들을 접해보거나 문학을 통해 다양한 인간을 이해해보려는 노력이 필요하다.(생기부 질문 없었음)후배들을 위한 조언 굉장히 푸근한 인상의 교수님이 계셨음. 압박 분위기가 아니었고 들어가자마자 잠은 잘 잤냐고 하시면서 분위기를 풀어주려고 하심. (*이때 확 긴장이 풀어져서 답변 까먹거나 말투가 편해지지 않도록 정신 똑바로 차려야함.)교수님 두 분이 계셨는데, 한 분은 엄청 잘 웃으시고 친절한 느낌이고 한 분은 말도 잘 안시고 안 웃으시고 차가운 느낌임. 보통 원래 그런거니까 반응에 동요하지 말고 두 분 다 눈 똑바로 마주치도록 노력해야 함.면접실 앞 복도에서 문항 풀이를 하기때문에 다른 학과들도 다 모여있고 조금 좁고 어수선한 감이 있음. 근데 귀마개를 못쓰게 했음. (*서울대는 단과대마다 면접 보는 방식이 조금씩 다를 수 있으므로 학과에 따라 차이가 있을 수 있으니 참고)제시문 풀 때 개인 필기도구 못쓰고 거기 있는 볼펜 썼어야 했고, 나올 때 꼭 제시문이랑 구상지 반납하고 나와야 함.위에는 안 썼지만 인문학 지문, 사회과학 지문 시작할 때 각각 본인이 파악한 제시문과 문제의 출제 의도를 설명하고 답변을 시작하라고 하심.30분 동안 준비한 답변을 ‘발표’하고 질문받는 느낌이 아니라, 그걸 화두로 ‘대화’하는 느낌이 강함. 문제의 요지를 잘 파악했는지와 그래서 내 의견이 무엇인지를 그때그때 조리 있게 전달하는 게 중요. 면접 연습할 때 답변의 형식, 답변 시간, 제시문 내용의 단순 요약 등 외재적인 요소는 크게 중요하지 않은 것 같음(어차피 교수님이 추가 질문하면서 끌어주시기 때문에). 따라서 시간이 얼마 안 남았을 때는 학원에 가는 것도 좋지만 장기적으로 혼자서 생각을 많이 해보고 같은 주제로 친구들이나 선생님과 토론해보는게 많은 도움이 될 것 같다고 생각함.추가 질문을 받을 때 그에 대한 정답을 찾으려 하기보단 그 자리에서 순발력 있게 고민해보고 내 생각을 만들어보려고 해야 함. 평소 책이나 뉴스 많이 보고 자기 생각 말하는 연습이 되어있는 사람이 압도적으로 유리하다는 것을 느낌. 그리고 그런 사람을 뽑는 시험이라는 것을.. 당연히 단기간에 끌어올릴 수 있는 역량이 아니므로 서울대를 쓸 생각이 있다면 몇 달 전부터 꾸준히 준비하는 게 좋겠다."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(1권)」","year":"2025학년도"},{"univ":"서울대학교","dept":"언론정보학과","jeonhyeong":"학생부종합(일반전형면접 전 30분 동안 제시문을 보고 주어진 문제에 대한 답변을 마련함)","method":"→ 면접실에 들어가 준비한 답변을 함(중간중간 꼬리 질문을 하시는 경우도 있음) → 교수님께서 답변 내용에 기반해 꼬리 질문을 하심 → 꼬리 질문에 답변함 - 대기 시간 동안 갖고 온 책이나 자료를 볼 수 있게 하는 과도 있고 못 보게 하는 과도 있으나 언정과는 보게 해줬음.","notes":"- 문제 풀이가 복도에서 진행되기 때문에 면접 보는 소리가 들려 조금 소란스러움. - 귀마개는 사용 가능하고 개인 필기구는 사용 불가능함.(검은색 볼펜 제공)","qa":[{"q":"(가)의 관점에서 (나), (다)를 비교하시오.-공통점: 일종의 자기실현적 예언이다. (가), (나) 각각 왜 그런지 설명함.-차이점: 가. 의도의 합리성- (가)는 비합리적이고 개인에 대한 모욕인 반면 (나)는 공익을 위한 정부의 물가 안정 정책이다.나. 결과의 성격- (가)는 죽음이라는 비극적 결과를 일으키는 반면 (나)는 물가 폭등을 방지함으로써 공익을 도모하고 사회 전체를 안정시키는 결과를 초래함.","a":""},{"q":"정책 수립자, 언론인, 사회에서 소외된 사람들 등등(이 밖에도 다른 이해당사자가 있었음)은 ㄱ을 해결하기 위해 어떤 노력을 할 수 있을지 제시된 사람들 중 세 명을 골라 답하시오.-먼저 정책 수립자, 소외된 당사자, 언론인의 노력을 설명하겠다고 제시함.가. 정책 수립자-소외된 사람들 사회에 적응할 수 있도록 인적 자원을 발전시킬 수 있는 지원 정책, -배리어프리 서비스(예시로 방송, ott에서의 자막서비스를 들어 배리어프리에 대해 설명함) 장려 정책나. 소외된 계층-앞서 정책 수립자가 수립한 정책에 관심을 가지고 따름, 사회적 시선에 굴복하지 않는 태도 필요다. 언론인-사실 어떤 집단과 계층이 열등하다는 이미지를 형성하는 주체는 언론임. 그러므로 언론은 소수자도 동등한 인간이라는 인식을 제공해야 함. 언론에서 소수자를 재현할 때 편협한 시각으로 소수자 중 일부의 특징을 부각하는 것이 아니라 넓은 시각으로 그들을 있는 그대로 보여줄 필요가 있음.<인문>(가): 번역 시 원어와 번역어의 경계가 없는 정도로 자연스러워야 함.(나): 번역 시 원어의 개성을 살려야 한다는 관점. 완벽히 자연스러운 번역이 불가능함.(다): 번역이 단순히 언어를 바꾸는 것이 아니라 언어를 재해석하고 다른 사회에 적용하는 것임.","a":""},{"q":"(가),(나),(다) 입장 비교 후 어떤 입장이 옳은지 본인의 독서 경험을 바탕으로 주장하시오.-(가) 설명 후 (나)가 가와 대조되는 입장이라고 설명하며 (나)의 관점 설명. 그 후 (다)는 (가)와 (나)에 비해 한 발짝 진보한 관점이며 그 이유에 대해 설명한 후 (다)의 관점 설명-나의 주장: 제시문 (다)의 주장이 타당하다. [인간실격] 독서 경험을 언급 후 전쟁 후 해당 도서가 일본 사회의 분위기를 반영한 책이지만 ‘인간성 상실’이라는 주제는 한국 사회의 다양한 문제(묻지마 살인, 혐오 문제) 등의 원인이므로 한국 사회에도 적용할 수 있다는 내 생각을 말함. 이 경함을 바탕으로 원서가 번역되며 새로운 사회에 적용될 수 있다고 주장.","a":""},{"q":"(역사학도 번역과 동일한 과정을 거침을 설명하는 짧은 제시문) 제시문 (가),(나),(다)의 차이가 역사학에서 어떻게 나타날 수 있는지 사례와 함께 설명하시오.(가장 준비가 덜 되었던 문제여서 답이 완벽하지 못함, 사례도 한 가지밖에 생각 못 함)(가): 역사 해석 시 현대인의 관점에서 이해하기 쉽게 해석할 것이다. 역사 교과서에서 이런 관점이 주로 드러난다고 생각한다고 주장한 후 이유 설명함.(나): 당대의 분위기, 시대적 배경을 강조할 것이다.(다): 역사적 사건을 재해석해 현대 사회에 적용하는 데 집중할 것이다.*꼬리질문(전체적으로 저의 답변의 부족한 부분을 완성해주시려고 유도했음)","a":""},{"q":"그럼 (가),(나)의 입장은 어떤 비판점이 있는지?","a":"(가)의 경우 나 역시 완벽한 번역이 불가능하다고 생각한다. 언어는 각 사회의 사회문화적 특징을 반영해 형성되기 때문에 한 언어에는 있는 단어가 다른 언어에는 없을 수 있다. 그러므로 다른 언어의 맥락을 완벽히 재현할 수 없다는 점에서 (가)를 비판할 수 있다.((나) 대답하기 전 다른 교수님께서 다음 질문으로 넘어가셔서 대답 못 함.)"},{"q":"역사 교과서의 사례로 보았을 때 어떤 점에서 (가),(나),(다)의 특징이 드러나는지 구체적으로 설명해봐라.","a":"(가)의 경우 현재에 잘 쓰지 않는 용어를 각주를 달아 현대의 언어로 학생들이 알기 쉽게 설명하는 부분에서 가의 특징이 드러난다.(나)의 경우 역사적 사건 당시의 기록물 혹은 사진, 그림 등의 이미지를 통해 당시 사람들의 생각, 사회적 분위기를 알 수 있다는 점에서 나의 특징이 드러난다.시간이 다 되어서 (다)는 대답하지 못함.후배들을 위한 조언 -면접 준비: 확실히 모의 면접을 많이 해볼수록 실력이 늡니다. 그리고 답변을 준비할 때 완벽하고 화려한 답을 준비하는 것에 집착하지 마세요. 완벽하게 구상하려고 하면 시간이 오래 걸려서 주어진 요건을 다 지키기 어려울 수 있어요. 일단 핵심을 빠르게 구상한 뒤 시간이 남으면 살을 붙이는 식으로 가야 합니다. 절대로 종이에 완벽한 문장을 줄줄 쓰지 마시고 키워드 위주로 쓰세요!-면접: 인문 지문과 사회과학 지문의 답변 순서는 본인이 정할 수 있는데, 둘 중 자신 있는 지문을 먼저 답변하는 걸 추천합니다. 그리고 자신 없거나 부족한 지문은 꼬리 질문을 거치며 답을 최대한 완성해나간다고 생각하세요. 생각보다 따뜻한 분위기에서 진행되니 긴장하지 말고 본인이 준비한 내용을 차근차근 말하면 됩니다."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(1권)」","year":"2025학년도"},{"univ":"서울대학교","dept":"인류학과","jeonhyeong":"학생부종합(일반전형- 수험생이 입실을 완료하면 학과마다 배정된 조교가 휴대전화 및 모든 전자기기를 수거함. 응시 번호가 부착된 지퍼백을 나눠주면 ‘전원을 끄고’ 제출, 전자기기 수거까지 완료되면 조교가 수험표와 신분증을 확인 후, 면접 순서를 알려줌- 동시에 조/번호가 적혀있는 스티커를 부여함(면접실에 들어갈 의상의 왼쪽 가슴에 부착)- 수험생 간 간격은 15분으로, 자기 면접 순서에 15분을 곱하면 면접 시작 시각 예상 가능- 전자기기를 제외한 책이나 기출문제 등의 문서는 자유롭게 열람 가능- 조교와 함께 각 층에 마련된 면접실 앞 복도로 이동함- 면접실 바로 앞 복도에 문제 풀이를 위한 칸막이 책상이 마련되어 있음- 소지품을 한쪽에 보관하고 착석하면 15분 뒤에 문제지와 메모지를 부여하겠다는 안내가 있음)","method":"- 15분 동안 가만히 대기, 화장실 다녀올 수 있음- 15분이 지나면 감독관이 문제지와 메모지를 나누어 줌(인문학 제시문, 사회과학 제시문, 메모지가 각각 묶여 있음) - 따로 마련된 타이머는 없으며, 수험생이 아날로그 시계를 지참.- 감독관은 10분이 남았을 때 수험생에게 안내함- 30분 동안 문제를 풀이함. 30분이 지나면 펜을 내려놓고 잠시 대기- 제시문과 메모지만 들고 노크 후에 면접실로 입실함.- 원하는 제시문부터 답변해달라고 하거나, 답변할 제시문 순서를 지정하는 경우도 있음.- 시간 경과는 별도로 알려주지 않으며, 1분이 남았을 때 복도 감독관이 노크를 통해 안내함.- 2024학년도에는 생활기록부에 관련된 질문이 많았으나, 2025학년도에는 지원동기 등을 응답 후 남은 시간에 짧게 답변해달라는 경우가 많았음- 지원동기 등을 답변할 때 한 감독관이 바로 채점을 진행함- 1분이 남았을 때 면접을 마무리하고 퇴실시킴- 모든 전자기기를 제출하였는지 확인할 것","notes":"- 보호자에게는 수험생의 예상 퇴실 시간이 따로 전송되지 않음- 입실 마감 후에는 조교와 함께 화장실을 갈 수 있으므로, 입실 완료 전 화장실을 다녀올 것","qa":[{"q":"번역에 대한 제시문 (가), (나), (다)의 입장을 비교하고, 자신의 독서 경험을 바탕으로 어느 제시문의 입장이 타당한지 구체적으로 설명하시오.","a":"세 제시문의 공통점을 제시 후, 차이점을 제시하며 (가), (나), (다)의 입장을 각각 요약함. 독서란 다른 사람의 경험을 가장 간단하지만 생생하게 습득할 수 있는 것이라는 의견을 말하고, 김훈 작가의 <자전거 여행>이라는 도서의 ‘냉이 된장국’을 소재 삼아 (나)의 의견이 가장 타당하다고 설명함."},{"q":"다음 보기의 제시문을 바탕으로 할 때, 제시문 (가), (나), (다)의 입장이 어떻게 나타날지 구체적인 사례를 들어 설명하시오.","a":"보기의 내용이 역사적 사건 그 자체를 ‘원문’으로, 그에 대한 해석을 ‘번역’의 과정으로 이야기하고 있음을 요약함. 6.25전쟁에 대한 명칭이 국가별로 차이가 있음을 예시로 들어 (가), (나), (다)의 입장을 각각 적용하고, 우크라이나 전쟁의 사례를 소재로 삼아 제시문 (다)가 말하는 번역의 풍부한 가능성에 ‘역사적 성찰’을 추가로 제시함."},{"q":"제시문 (가)의 자기 실현적 예언을 바탕으로, ‘부두 죽음’과 ‘물가 안정률 목표제’의 공통점과 차이점을 설명하시오.","a":"제시문 (가)에서 말하고 있는 자기 실현적 예언이 무엇인지 요약하여 설명함. 제시문 (나)의 부두 죽음과 (다)의 물가 안정률 목표제를 간단하게 요약하여 설명하고, 공통점으로 예언의 주체가 필요하다는 점과 그에 대한 신뢰도가 예언의 결과를 좌우할 수 있다는 점을 꼽음. 차이점으로는 예언의 주체가 개인인가, 정부인가와 예언 자체가 어떤 성격을 지니고 있는지를 예로 들어 설명함."},{"q":"제시문 (가)의 ㉠과 같은 상황이 발생했을 때, 이를 해결하기 위해 어떤 노력을 할 수 있을지 언론인, 교육자, 연구자, 정책 입안자, 특정 집단의 구성원 중 3가지를 골라 구체적으로 설명하시오.","a":"제시문 (가)의 ㉠과 같은 상황이 어떤 상황인지를 제시문 (가)와, 사회문화 교과의 ‘낙인 이론’을 설명하며 요약 제시함. 언론인, 교육자, 연구자를 선정해 각각 어떤 노력을 할 수 있을지 표지를 활용하여 차례로 제시함. 특히, 연구자의 노력을 설명하는 과정에서 학과 교육과정에 포함되는 ‘문화 인류학’을 언급함.후배들을 위한 조언 면접 당일에는 많은 인파가 한 번에 모여 교통 상황이 양호하지 않고, 서울대학교는 정문에서부터 면접 장소까지의 거리도 있기에 반드시 면접 입실 가능 시간보다 1시간 먼저 출발하시는 것이 좋습니다.오랜 시간 대기하는 과정에서 목이 잠길 수 있으나, 긴장되는 상태에서 물을 섭취하는 것보다는 목캔디와 같은 간단한 사탕을 지참하여 대기하는 동안 컨디션 관리를 하시는 것이 좋겠습니다.면접이 시작되면 심호흡을 하고, 긴장감을 잠시 내려둔 채 진솔하게 여러분이 준비해 간 이야기를 면접관님들에게 들려주고 나올 수 있도록 많은 연습을 하시는 것을 추천드립니다."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(1권)」","year":"2025학년도"},{"univ":"서울대학교","dept":"철학과","jeonhyeong":"학생부종합(일반전형)","method":"대기실에서 대기->제시문 풀이(30분)->제시문 면접(15분, 추가질문 포함)1. 대기실에서 모든 자료, 전자기기, 필기구 등 제출해야 함","notes":"2. 교수님께 실명을 말하면 안 됨 (면접번호)3. 면접 끝나고 퇴실할 때 문제지와 구상지를 모두 제출해야 함","qa":[{"q":"(가)의 관점에서 유태인 학살을 더 구체적으로 설명해주세요.[문제1] (가)의 자기실현적 예언과 관련하여 (나), (다)를 비교하여 설명","a":"자기실현적 예언이란 (가) 정리(1) 공통점: 자기실현적 예언이 행동, 결과에 영향을 미친다. (2) 차이점: 각각 부정적, 긍정적 영향을 미친다. 또한 제도적 차원의 제어라는 기준에서 다르다. [문제2] (ㄱ)의 문제를 해결하기 위해 정책입안자, 피해자집단, 언론, 교육자 등 다섯 주체 중 세 주체를 고르고 그 역할을 각각 설명선정 주체 : 피해자집단(자기실현적 예언 극복, 주체성 회복), 언론(편협된 보도x), 교육자(다원성 교육, 편협x) / 예시는 퀴어 축제 등 성소수자 집단을 들었음."},{"q":"자기실현적 예언과 구체적으로 어떤 관계에 있는 거지?","a":"전제로 작용됨.후배들을 위한 조언"},{"q":"수능장과 분위기가 유사함. (ex. 화장실도 감독관과 동행함)","a":""},{"q":"면접관 두 분 모두 교수님이셨음. (입학사정관x)","a":""},{"q":"입실시작 시간 전까지 선배님들 응원 있음. (간식도 주심)","a":""},{"q":"대기, 준비, 면접 모두 인문대 강의실에서 진행했음. (목소리가 울릴 수 있음)","a":""},{"q":"생각보다 아주 빨리 끝남.","a":""},{"q":"(소설 포함) 책을 많이 읽어야 좋을 것 같음.","a":""}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(1권)」","year":"2025학년도"},{"univ":"서울대학교","dept":"자유전공학부","jeonhyeong":"학생부종합(지역균형전형)","method":"자기소개 이후, 학교생활기록부 기반 면접문과 중심 학교생활기록부여서인지 개념 질문은 하나도 없었음.꼬리 질문 거의 없고 활동 확인 질문이 많았음.① 8시 이전에 입장할 경우 다른 대기실에서 생기부 보며 대기하고 있음. (8시부터 8시 20분까지 강당에서 자기 자리에 앉아 대기)② 본인확인 후 전자기기 제출하고 생기부 자료 모두 볼 수 없음.","notes":"아무것도 없이 몇 시간까지 기다리게 됨. 가만히 앉아있거나 자고 있는 학생들도 있었음.③ 10분 칼같이 지킴. 말하던 중간에 문 열리면 말 멈추고 바로 나오기.④ 압박면접과 정반대의 분위기.","qa":[{"q":"기술과 사회적 약자 문제를 어떻게 연관 짓는지?","a":"기술 발달은 발달 과정에서 사회적 약자의 권리를 침해할 수 있기에 기술이 미칠 수 있는 영향을 탐구하고 기술을 개발하는 것이 필요하다고 생각합니다. 키오스크의 예시를 들어보겠습니다. 키오스크가 생기면서 전국 각지에 설치되는 과정에서 노인층, 어린아이, 장애인과 같은 사회적약자가 고려되지 않았습니다. 휠체어를 탄 사람들이나 시각장애인과 같은 사람들은 직원 응대가 줄어들고 키오스크가 생기면서 원하는 상품을 얻을 수 있는 권리를 침해받게 됩니다. 이러한 문제에서, 기술 발달이 사회적 약자에 미치는 영향을 고려하고 발달 방향을 설계해야 한다고 생각합니다."},{"q":"확률과 통계 시간에 댓글이 사회적 약자를 인식하는 과정에 미치는 영향에 관해 확률과 통계 포스터를 만들었다고 적혀있는데 내용이 뭔지?","a":"인터넷 댓글을 읽는 사람과 읽지 않는 사람들이 사회적 약자에 대해 가지는 인식에 대해 설문조사를 했습니다. 조사 결과 기사를 보고 객관적인 판단을 하는 것이 아니라, 댓글 속 주류 의견을 그대로 따른 경험을 한 사람들이 많다는 것을 알게 되었습니다. 이러한 문제 해결을 위해, 단순히 주류 의견을 받아들이는 것을 막기 위해 디지털 리터러시 능력을 증진하는 것이 필요하다고 생각합니다."},{"q":"그걸 어떻게 조사했는지 방법을 알려주세요. 질문지법이든, 면접법이든.","a":"짧은 시간 내에 다수의 설문을 얻고자 질문지법을 활용하였습니다. 온라인으로 설문지를 제작하고 학교 홈페이지에 게시함으로써 익명의 10대 학생들에게서 조사 결과를 얻어내었습니다."},{"q":"조지 오웰 <1984> 읽었던데 기술 발달로 인해서 빅브라더와 같은 사회문제가 발생할 수 있다면 그 문제가 뭔지 말하고 해결 방법도 말해주세요.","a":"CCTV와 같은 감시시스템의 발달로 개인의 사생활 문제가 불거질 수 있으며, 인터넷에서 글을 작성한 자를 추적할 수 있는 기술발달로 자유롭게 표현할 수 있는 자유가 침해되는 등의 문제가 생길 수 있습니다. 이러한 기술발달이 빅브라더와 같이 개인을 억압하는 사회로 이어질 수 있습니다.(이후 잠깐 시간 달라고 한 뒤 고민함)(해결방안에 대해 뭐라고 대답했는지 기억이 안 나는데, 범죄예방을 위해 생긴 기술이므로 범죄예방과 개인의 권리 보장 사이에 중용을 찾아야한다는 방향으로 말함. 구체적으로 제시하지 못하고 말을 좀 절음)"},{"q":"동아리에서 맡은 역할과 그 경험이 자유전공학부 와서 어떤 장점이 될지 말해보세요.","a":"3학년 때에는 동아리 내에 1학년과 2학년에 비해 3학년이 무척 적었습니다. 이 때문에 지난 2년간 동아리에서 해온 활동을 예로 들어 1학년과 2학년이 동아리에서 무엇을 얻어가야 하며 어떻게 참여해야하는지를 조언해주는 역할을 했습니다. 특히 영어토론 시간에는 토론진행을 도맡고 다른 학생들의 의견을 종합하여 정리하는 역할을 맡았습니다. 이러한 경험은 자유전공학부에 와서 조별과제와 같이 다른 학생들과 소통하는 작업을 할 때에, 소통을 돕고 원활한 과제수행을 돕는 과정에서 장점이 될 수 있습니다."},{"q":"사회문제탐구 시간에 환경문제와 사회적 약자의 연관성을 탐구했던데 어떤 내용이었는지?","a":"지구온난화로 인한 열사병과 같은 질병이 사회적 약자에게 더 많이 발생한다는 것을 탐구했습니다. 현재 마련된 정책은 복지대상을 선택할 때에 빈곤의 정도를 기준으로 선정하는 것이 아닌, 가족구조를 기준으로 선정하는 것에 문제가 있다고 생각합니다. 한부모가정이 아니더라도 지원이 필요한 가정이 있으며, 실질적인 도움을 주기 위해선 지원대상을 선정하는 과정이~ (이 때 10분 끝났다고 문 열리고 바로 나옴)후배들을 위한 조언 ① 수능 끝나면 1차 합격까지 기다리지 말고 미리 면접 연습해보기. 수능 이후 면접 준비기간이 무척 짧음.② 모의 면접 많이 참여하기③ 학교생활기록부 분석할 때 활동-참여동기, 맡은 역할, 깨달은 점, 관련 개념 숙지 등의 항목은 따로 문서에 정리해 놓기④ 서울대학교의 경우 전자기기 제출과 거의 동시에 종이 자료도 집어 넣어야하므로 굳이 인쇄 안 하고 노트북이나 패드 들고 가도 괜찮음.⑤ 건물 들어가기 전에 선배들이 응원해 줌. 간식은 받아놓고 나중에 집 갈 때 먹기. 선배들도 혹시 모르니 다 끝나고 먹으라고 말해줌."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(1권)」","year":"2025학년도"},{"univ":"서울대학교","dept":"교육학과","jeonhyeong":"학생부종합(일반전형)","method":"문제 풀기 (30분) → 문제 읽고 풀이 발표(1,2번 연달아서) → 꼬리 질문 → 교직인적성 문제 풀기(15분) → 교수님이 해주시는 질문에 따라 풀이 발표 → 꼬리질문(발표 중간중간에 하시기도 함.)","notes":"교직인적성은 교수님께서 문제를 보시고 질문을 하셨음. 1번 문제만 물어보는 것이 아니라 1번과 유사하지만 다른 1문제를 물어보실수도 있음.","qa":[{"q":"제시문에 나온 교사의 책임과 권위란 무엇인가?","a":"교사의 책임은 학생과 세계와의 관계를 이어주고 이를 이해시킬 책임이 있음. 권위는 이러한 책임에서 나옴. 교사는 성인들의 대표로서 가르쳐야 한다는 점에서 권위를 갖게 됨."},{"q":"요즘 우리나라 교사들의 책임과 권위는 어떤 것 같은가요?","a":"책임은 증가하고 유지되지만 권위는 내려가고 있음. 기사에서 학생이 교탁 아래에서 핸드폰을 보며 누워 있는 모습이 기억에 남음. 학생들이 교사를 학업을 주입하는 사람으로만 여기고 권위가 떨어진 것 같음."},{"q":"새것을 가르치는 교육이 되려면 어떻게 해야 할까?","a":"학문 간의 경계가 모호해져야 함. 학생들이 다차원적 문제를 다룰 수 있도록 돕는 것이 중요함. 체험학습과 직업 교육을 늘려야 함."},{"q":"고등학교 생활 중 교과목의 경계가 모호한 경험이 있는가?","a":"탐구활동 시간에 질문 저조 현상에 대해 사회문화와 생명과학을 연계해 탐구해 본 경험이 있음."},{"q":"질문 저조 현상의 원인은 뭐였는가?","a":"수업 중 낙인이 가장 큰 원인이라고 생각함. 내신 시험에 초점을 맞추다 보니 질문이 수업 흐름을 끊는다고 여겨지고, 학생들이 질문하는 것에 부정적 낙인이 형성될 수 있음."},{"q":"상황에 맞지 않는 질문을 하는 학생을 어떻게 지도할 것인가요?","a":"질문한 학생에게 칭찬하고, 그 질문은 창체 시간에 이야기하자고 제안함. 학생의 질문 내용을 기억해 두고 추가 탐구활동으로 연계할 것임."},{"q":"어떤 교사가 바람직하다고 생각하는가요?","a":"생각하는 교육을 할 수 있는 교사가 바람직하다고 생각함. 루트번 스타인의 책에서 교육 시스템에 생각의 과정과 도구가 필요하다고 했던 말이 기억에 남음. 교과서 만들기 활동을 통해 융합적 사고를 이해하게 됨."},{"q":"많은 선생님들께 배워오면서 생각이 있는 선생님이 많았는가요?","a":"생각이 많은 선생님들이 많았음. 담임선생님이 진로에 대해 고민해 주시고 조언을 많이 해주셨음.후배들을 위한 조언 팁이라고 한다면 좀 뻔하지만 책을 많이 읽으라고 권하고 싶습니다. 저는 사회과학에 약한 편이었는데 학교 도서관에서 경제 관련 개념 책들을 찾아보거나 정치 용어 관련 책을 좀 찾아보고 읽었더니 어느정도 도움이 되더라구요. 또 주변에 경제에 관심있는 친구들한테 물어도 보고 요즘 시사 이슈 다루는 채널도 찾아보면서 견문을 넓히려고 노력했습니다. 아니면 해당 교과 선생님께 찾아가서 자문을 구하는 것도 좋은 방법일 것 같습니다. 문제 푸는 과정에서 팁을 주자면 제시문을 보기 전 문제부터 읽는 방식을 추천합니다. 생각보다 문제에서 얻을 수 있는 힌트가 많고 또 없다고 해도 문제를 먼저 보면 어디를 중점을 두고 읽어야 할지는 확실하게 보이니깐 문제의 핵심을 파악하는데 도움이 됩니다.그리고 모든 답변은 구체적으로 할 것을 권장합니다. 생각보다 구체적으로 말하는 학생이 별로 없다고 합니다. 제시문 안에서 답을 찾는 문제는 그렇게 하기 어렵겠지만 자기 생각을 말하는 정답이 없는 문제에서는 최대한 구체적으로 말하는 걸 연습하세요. 내가 ㄱ이라고 생각하면 그 이유에 대한 구체적 설명과 예시를 드는 것이 가장 이상적인 답변 방식이라고 합니다. 생각을 할 때 최대한 구체적이게 하려고 노력하는 걸 추천합니다.그리고 연습할 때 본인 모습을 영상으로 찍거나 녹음을 해보세요. 내가 어떤 자세로 어디를 보면서 말하는 지 알 수 있는 가장 좋은 방법입니다. 태도는 뭐~하고 넘기기보단 태도라도 좋은 점수를 받아야겠다!라는 생각을 했으면 좋겠습니다. 녹음은 꼭 해보라고 말하고 싶어요.마지막으로 모의면접, 정말 많이 해보셨으면 좋겠습니다. 선생님과 하는 것이 제일 좋지만 상황이 된다면 친구와 하는 것도 추천합니다. 친구와 하게되면 내가 면접관 역할까지 할 수 있기 때문에 면접관 입장에서 학생의 이런 모습이 되게 불편하구나~, 한 문장이 너무 길어지면 집중이 잘 안되는 구나~같은 정말 좋은 깨우침을 가져갈 수 있기 때문에 진로 방향이 비슷한 친구들끼리 모여서 모의면접하는 걸 강력 추천합니다. 또 문과 제시문 면접은 정답이 없는 경우가 많습니다. 친구와 선생님과 함께 문제에 대해 토론해 보며 견문을 넓히는 시간을 필히 가졌으면 합니다.마지막으로 제시문 면접이라고 생기부를 무시하지 않으셨으면 좋겠습니다. 본인 생기부 내용에 대한 숙지가 잘 되어 있으면 요긴하게 써먹을 곳이 많습니다. 그래도 한 번 해 본 선배 입장에서 1차 합격의 문을 연 우리 후배님들이 정말 자랑스럽습니다. 내가 다른 친구보다 좀 못하는 것 같다해서 주눅들지 말고 자신 있게 하다오면 좋겠습니다. 면접을 준비하면서 정말 힘들었지만 그래도 합불의 결과를 떠나서 제가 투자한 시간들이 아깝지 않습니다. 서울대 면접은 그 자체에 의미가 있는 것 같으니 결과에 너무 연연하려 하지 말고 과정을 즐기고 후회 없이 보냈으면 좋겠습니다. 남아있는 길에 행운과 행복이 따르길 바랍니다."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(1권)」","year":"2025학년도"},{"univ":"서울대학교","dept":"역사교육과","jeonhyeong":"학생부종합(일반전형1) 면접 대기실 입장-자기 차례까지 대기합니다. 대기할 때는 그 어떠한 자료도 보지 못합니다.2) 제시문 읽기실을 입장합니다.(입장 전에 주의사항 읽고 들어가면 도와주시는 분이 타이머를 주십니다.)3) 30분 제시문 읽습니다. 인문 1개, 사회과학 1개(아마 연도마다 다를지는 모르겠지만 우리는 제시문에 밑줄이나 표시하지 말라고 하셨습)","method":"니다. 그런데 저는 실수로 밑줄을 그어 큰 문제가 생긴 줄 알았는데 그렇게 큰 문제는 아니었습니다.)4) 15분 제시문 본면접(끊는 분도 있다고는 들었지만 보통 내용은 끝까지 들어 주시는 것 같습니다.)5) 인적성 제시문 읽기실을 입장합니다.(마찬가지로 주의사항 읽고 입장하면 도와주시는 분 한 분이 타이머를 주십니다.)6) 15분 인적성 지문 읽습니다. 인적성 지문 하나7) 15분 인적성 본 면접8) 도와주시는 분의 안내를 받아 나가면 끝","notes":"도와주시는 분의 허락이 있어야 이동 및 활동이 가능합니다.전자기기 소지는 금지합니다.","qa":[{"q":"제시문 정리 및 자신의 의견(가) 동화식 번역(원어보다 모국어의 느낌으로 최대한 바꿈)(나) 전달식 번역(원어의 느낌을 그대로 살려서)(다) 창조식 번역(번역을 새로운 문학의 영역으로 봄)(다)를 지지함: 독서 경험-<어린왕자> (영어→한국어 (나)식으로 했을 때, 영어와 철학 완전히 이해할 수 없게 됨. 그 책의 속뜻을 느낄 수 없게 됨.) 또 문학은 새로운 창조로 새로운 가능성. 이것은 하나의 문학 영역.","a":""},{"q":"번역을 역사의 조사에 적용(가) 자신들의 정서 맞도록 조정(역사의 이질감 조정), 예를 들어서 '비유'(나) 사료, 유물 그대로 살려서 전달(다) 새로운 시각으로 새로운 해석과 자극을 줌예시: 각각의 방식으로 '나폴레옹'을 해석(가) 나폴레옹을 이해하기 어려운 한국사람이 있다면 이와 비슷한 광개토대왕에 비유: 지리 정복왕들(나) 나폴레옹 시절 실제로 있던 문화적 풍토들을 그대로 전달, 예시로 실제 그때 당시 나폴레옹을 토대로 작곡된 '영웅' 이라는 곡을 소개.(다) 나폴레옹을 평가하는 새로운 시선 제시, 예시로 나폴레옹의 근자감, 자신감은 그를 영웅이나 개척자로 만들었기 때문에 고평가 되어야 하나 아님 오히려 나르시스트적 발상을 가지게 되어 결국 몰락했기 때문에 저평가 되어야 하나<사회과학 지문: '자기실현적 예언'이라는 사회현상 분석>","a":""},{"q":"자기 실현적 예언에 대한 2개의 지문 분석(가) 자기 실현적 예언에 대한 내용: 여기서 그냥 지문을 정리하지 않고 일반화처럼 정리함.자기 실현적 예언: 일반 인과관계에서 도치된 양상. 보통 원인이 있어야 결과가 있지만, 이것은 결과가 있다고 '믿고' 그것에 맞는 원인을 만듦. 결과적으로 그 결과를 만들어 감. 원인의 원인이 결과 '믿음’(나),(다) 공통점: 자기 실현적 예언이 드러남.(나) 사회 배척: 특정 집단이 나쁜 짓을 할 것이라고 믿음 → 배척 시작 → 배척 당해 고통 호소. 소외 → 결국 나쁜 행동 시작(다) 경기 혼란 예측(사실 기억 소멸되어서 그냥 이 부분은 간단히 적겠습니다! 실제로는 좀 더 단계적으로 말했습니다.) → 소비자 회사 시장 주체들 혼란 → 실제로 혼란한 결과 등장(나),(다) 차이점: 해결책 마련(나) 지문에서는 해결책 X, 하지만 (다)에서는 해결 제도 마련. 심지어 이 제도 사람들의 자기 실현적 예언 태도 이용 (어떻게 이용했는지도 이야기 했었지만 기억이 나지 않아 확실한 부분만 언급합니다!) 이런 사회현상을 자연스럽게 제도에 녹여 사용","a":""},{"q":"나에서 나온 문제 해결을 위해 5주체 중 3주체를 들어 해결방안 이야기하기교육자, 언론인, 사회 연구원, 배척당한 사람들 등이 있는데, 이 중 교육자, 언론인, 사회 연구원을 골랐고, 왜 나머지 두 주체를 선택하지 않았는지 설명. (하나는 기억이 잘 나진 않지만, 배척당하고 있는 사람들에게 무언가 추가로 요구하는 것이 오히려 역효과가 나거나 정서적 고통을 줄 수 있기 때문이라고 이야기함.) 그리고 이 3주체가 가장 신경써야 하는 부분은 그 믿음을 깨고 진실을 전하는 것◦ 교육자: 학생들에게 어떤 것이 진실인지, 편견인지 알려주기. 또 어떠한 것을 대할 때 윤리적으로 대할 수 있는 태도 권장◦ 언론인: 언론 → 사람들의 증거, 많은 수의 증거는 사람들의 선입견을 만들기도 함. 언론은 해당 집단의 착한 면 등을 다각적으로 보여주고, 편견을 없애기 위해 노력◦ 사회 연구원: 학술 자료 → 사람들의 신뢰성이 높음. 또 사람들에게 현재 이러한 현상이 자기 실현적 예언이라는 현상이라는 것을 알리고 분석할 수 있음. 또 신뢰성 높게 알려 사람들에게 경각심을 줄 수 있음.이렇게 제시문 답변 끝남.","a":""},{"q":"<어린 왕자> 예시는 불어(원어)로 들어야 맞지 않나요?","a":"교수님의 말씀이 맞다고 생각합니다. 제가 한정된 지식으로 오류를 범했습니다. 죄송합니다."},{"q":"말할 때, 도치나 동화와 같은 어려운 단어를 쓰셨는데, 평소에 무슨 책 많이 읽으세요?","a":"저는 역사책도 좋아하지만, 사실 철학도 정말 좋아해서 철학책도 많이 읽습니다."},{"q":"(갑자기 생기부 교과세특에 대한 질문이 들어와서 당혹스러움) 춘추시대의 부국강병책을 <논어>를 통해서 얻기에는 조금 빈약하지 않나요? 추가적으로 읽은 책 없나요?","a":"아니요. 저는 그 책만 읽은 것이 맞습니다. 저는 논어와 같은 사람의 인생관을 알 수 있는 책에서 부국강병책과 같은 분야를 유추해 내는 과정, 연결해 나가는 과정 또한 역사학이라고 생각합니다.후배들을 위한 조언 많은 학생들이 압박 면접에 대한 공포심이 상당한 것으로 알고 있습니다. 제가 다녀왔던 서울대 면접에서는 말투나 태도는 압박 면접은 아니지만, 교수님들이 빈틈을 찾기 위해 계속 질문하십니다. 그러다 보니, 자연스럽게 압박감을 느낄 수 있고 답변을 잘못한 것에 대해 매우 신경쓸 수도 있습니다. 하지만, 앞에서 언급했듯이 계속 질문을 하시기 때문에 충분히 고쳐나갈 수 있습니다. 그래서 한번 당황해서 이상하게 대답하더라도 다음 질문 때 더 당당하게 대답하면 됩니다. 면접에서 언제나 자신의 의견을 피력할 기회가 있다는 것을 알게 되면, 좀 더 또박또박 면접을 이겨낼 수 있을 것입니다.또, 직접 면접을 보러 갔을 때, 가서 학문적 토론이나 의논을 한다고 생각하면 오히려 교수님들과 대화를 나누는 것이 영광이라고 생각하게 되어서 더 대화하고 싶고, 그 순간이 소중해진다고 생각합니다. 저도 가서 그러한 생각을 했고, 그래서 긴장을 많이 줄일 수 있게 되었습니다.노력한 만큼 말이 안 나오거나 평소보다 말의 전달력이 떨어질 수 있지만, 가장 핵심은 전달하고자 하는 메시지라고 생각합니다. 교수님들은 그 뜻이나 의견을 알고 싶어 하시는 것 같았습니다. 때문에, 저는 답변에서 중요한 것은 그 답변에 담고 있는 깊이와 의미라고 생각합니다. 물론, 말투나 태도, 제스처는 면접의 질을 올려줄 수는 있지만, 부수적인 것에 너무 집착하다 보면 그 의미를 전달하는 것을 놓칠 수 있습니다. 따라서, 언제나 면접에서 자신이 가장 전달하고 싶은 메시지와 의견이 무엇인지 인지하고 있어야 합니다.입시를 위해 지금까지 열심히 달려온 후배들에게 무언가 더 개선했으면 좋겠다고 말하는 것이 참 복잡한 감정이 들기도 합니다. 학생분들도 지금까지 오는 것도 많이 지쳤을 이 시점에서, 제가 감히 더 많은 짐을 주고 있는 것은 아닌지 계속 고민했습니다. 하지만, 정말 이것이 학생분들의 입시의 마지막이라면 욕심을 부려, 마지막까지 최선을 다하겠다는 마음가짐으로 임해주셨으면 좋겠습니다. 이 마음가짐 하나로도 정말 많은 것이 바뀐다고 생각합니다. 또, 자신을 부정하거나 학대하는 것이 아닌, 자신을 믿고 스스로 격려하는 형태로 최선을 다해주시길 바랍니다. 우리는 우리의 성장을 위해 달려온 것이지, 자신을 해치면서 결과만을 위해 온 것이 아닙니다. 저는 모든 학생분들이 입시뿐만 아니라 자신의 성장 또한 인지하는 현명한 학생이 되길 바랍니다.정말 이 조언이 학생분들에게 닿을지는 모르겠지만, 언제나 진심으로 응원합니다!"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(1권)」","year":"2025학년도"},{"univ":"서울대학교","dept":"사회교육과","jeonhyeong":"학생부종합(일반전형저는 사범대학 11동에서 면접을 진행했고 11동으로 들어가는 입구가 막혀 있어서 12동을 통해서 들어갔습니다. 안에 계신 관계자분들이 안내를 해주시는 대로 따라가서 11동에 일단 도착을 했습니다. 11동에 들어와서 사회교육과 대기실로 이동을 해서 8시가 되기 전까지 대기를 하였고 8시부터 휴대폰과 전자기기들을 회수하고 면접 번호를 부여받았습니다. 회수하고 나서는 어떠한 면접 준비도 할 수 없고 그냥 가만히 8시 30분까지 대기를 하였습니다. 8시 30분부터 15분 간격으로 1명씩 나가서 대기를 하고 제시문 준비)","method":"를 시작했습니다. 저는 6번이였지만 5번이 오지 않아서 5번째로 나갔습니다. 9동에서 시험을 본 친구가 있는데 그 친구는 제시문 면접 준비를 다른 방에 들어가서 준비했다고 하는데 저는 나가서 복도에 배치된 책상에서 제시문 면접을 준비했습니다. 작은 전자시계로 30분동안 제시문 면접 준비를 하고 바로 앞에 있는 면접실로 들어가서 면접을 진행했습니다. 15분간 면접을 진행하고 퇴실한 후, 옆에 있는 다른 책상으로 이동하여서 잠깐의 시간을 갖고 인적성 면접 준비를 15분 동안 진행하였습니다. 제시문 면접과 마찬가지로 준비 시간을 갖은 후, 앞에 있는 면접실로 들어가서 15분동안 면접을 진행하고 다 끝난 뒤에 휴대폰과 본인의 물건들을 다 챙긴 뒤 개별로 퇴실을 하였습니다.사범대학은 제시문 면접과 인적성 면접, 2가지의 면접을 진행하는데 이 2가지의 면접 모두 15분동안 진행을 합니다. 면접을 진행하는 중에 1분이 남았을 때 밖에 계신 관계자분께서 1분이 남았다는 의미로 노크를 해주시고 15분이 되자마자 문을 열어서 더 이상 면접을 진행할 수 없습니다. 따라서 노크 소리를 듣는다면 이제 면접의 끝맺음을 할 준비","notes":"를 하시고 마지막 정리를 하셔서 요약을 해주신다면 좋을 거 같습니다.그리고 면접 준비를 복도에서 진행한 만큼 분위기가 정숙하지는 않습니다. 면접을 준비하는 동안에 학생들이 화장실을 가기 위해서 움직이는 소리가 들리고 살짝 부산스러운 느낌이 있습니다. 따라서 학교에서 면접 준비를 하실 때, 조금 시끄러운 분위기에서도 준비하는 연습을 해보시면 좋을 거 같습니다.","qa":[{"q":"사회과학 지문<제시문 (가)> 자기실현적 예언에 관한 제시문, 자연현상과 달리 사회현상은 인간의 예측이나 두려움이 사건이 전개되는 과정에 영향을 끼치는 현상에 대한 제시문.<제시문 (나)> 부두 죽음에 관한 제시문, 주술의 효력은 주술을 당한 사람이 믿고, 그 사람의 주위에 있는 공동체, 친구, 가족들이 당사자가 주술이 걸린 존재라고 믿어서 결국 사망에 이른다는 제시문.<제시문 (다)> 물가 안정 목표제에 관한 제시문, 사회현상에서 인간의 막연한 두려움이 물가 상승에 영향을 끼쳐 심각한 물가 상승을 초래할 가능성이 있어 한국은행과 같은 기관이 물가 상승률에 대해 공지를 하면 실제로 설정한 물가와 비슷하게 물가가 상승한다는 제시문.","a":""},{"q":"제시문 (가)에 나오는 자기실현적 예언의 관점으로 제시문 (나)의 부두 죽음과 제시문 (다)의 물가 안정 목표제에 대해서 설명해 보시오.","a":"자기실현적 예언이 사회문화 교과 시간에 배우는 낙인 효과와 유사한 속성을 가진다고 설명을 먼저 했습니다. 그리고 제시문 (나)의 부두 죽음과 제시문 (다)의 물가 안정 목표제는 자기실현적 예언이 각각 부정적, 긍정적인 형태로 나타났다고 설명을 했습니다."},{"q":"제시문 (가)에 나타난 ㉠(자기실현적 예언의 효과로 인해서 차별받는 집단이 실제로 나쁜 행동을 하게 됨)을 교육자, 언론인, 정책입안자, 피해집단 중 3가지를 활용하여서 어떤 노력을 해야 할지 말해보시오.","a":"저는 교육자, 언론인, 정책입안자, 이 3가지를 선택해서 설명하였습니다. 인지의 중요성에 대해서 설명하면서 교육자가 정신적으로 미성숙한 학생들은 자기실현적 예언의 효과를 더욱더 강하게 영향 받을 수 있다고 말하였고 학생들에게 자기실현적 예언이라는 것이 있다고 인지시켜줘야 한다고 설명했습니다. 다음으로 언론인과 정책입안자에 대해서 설명을 하면서 제시문 (다)를 활용하여 공신력이 있는 기관에서는 자기실현적 예언의 효과를 더 극대화할 수 있으므로 조심해야 한다고 말했습니다."},{"q":"인문학 지문<제시문(가)> 번역할 때 원문을 자연스럽게 번역하는 것을 추구. <제시문(나)> 번역할 때 원문의 이질성을 추구. 완벽하게 된 번역이란 존재하지 않음. <제시문(다)> 번역할 때 원문을 모국어로 자연스럽게 번역하되, 번역하는 과정에서 새로운 가치들을 발견하여 원문과 모국어를 더 풍요롭게 만드는 것을 추구.","a":""},{"q":"제시문 (가), (나), (다)의 공통점과 차이점을 말해보고 그중에서 가장 적합한 번역 방법은 무엇인지 자신의 독서 경험을 토대로 설명해 보시오.","a":"제시문(가), (나), (다)의 공통점으로 모두 번역에 대한 특정한 입장을 가지고 있다는 점으로 꼽았습니다. 그리고 차이점으로는 (가) 같은 경우, 자연스러움을 강조하는 입장이라고 설명하였습니다. (나)는 완벽하게 된 번역이라는 것은 존재하지 않으며 번역에서의 이질성의 강조하는 것이라고 설명하였습니다. 마지막으로 (다)는 모국어와 원문의 언어는 번역이라는 활동을 통해서 언어를 더 풍요롭게 만드는 활동이라고 설명했습니다. 저는 이 3가지 중에서 제시문 (나)의 입장을 선택하였습니다. 그러면서 제가 일본 문학을 읽은 경험을 설명하면서 타국어로 써진 책을 읽는 것은 새로운 세계를 탐험하는 것에 비유하면서 이질성을 경험함으로써 그로 인한 호기심으로 추가적인 지식을 얻는 것이라고 생각한다고 설명하였습니다."},{"q":"<보기>(역사에 관련된 지문)와 제시문(가), (나), (다) 번역과의 유사점에 대해서 설명해 보시오.","a":"역사와 번역 모두 우리에게 익숙하지 않은 언어를 우리에게 익숙한 언어로 바꾸는 과정이라는 점에서 공통점이 있다고 하였습니다. 제시문 (가)의 번역은 역사에 나오는 사료를 우리가 쉽게 이해할 수 있도록 현재의 언어들을 사용하는 것과 유사하다고 설명하였고, 제시문 (나)의 번역은 고어들을 그대로 사용하여서 우리에게 이질성을 주는 것이라고 설명했습니다. 마지막으로 제시문 (다)의 경우에는 그 당시의 시대상 같은 것을 반영하여서 번역을 하는 것이라고 설명을 하다 시간이 다 되어서 충분한 설명을 하지 못하고 종료하였습니다.후배들을 위한 조언 서울대 면접은 준비 시간 30분, 면접 시간 15분으로 굉장히 오랫동안 진행을 합니다. 그리고 면접 질문에도 자신의 경험이나 생각을 묻는 질문들이 꽤 많이 존재합니다. 따라서 평소에 사회 문제나 철학적인 고민과 같은 주제로 깊은 생각들을 많이 해보는 것을 추천합니다. 그래야지만 15분이라는 면접 시간을 채울 수 있고, 만약 답변으로 시간을 못 채울 시 추가적으로 하시는 꼬리 질문에도 답변을 할 수 있습니다. 마지막으로 서울대 면접 문제는 교과서를 기반으로 출제되기 때문에 면접 보시기 전에 교과서를 한 번씩 정독하고 가시면 좋을 것 같습니다."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(1권)」","year":"2025학년도"},{"univ":"서울대학교","dept":"지리교육과","jeonhyeong":"학생부종합(일반전형)","method":"대기실 입장 → 가번호 부여 → 인문학, 사회과학 제시문 숙독(30분) → 면접 진행(15분) → 인적성 제시문 숙독(15분) → 면접 진행(15분)학과마다 지정된 대기실이 달라서 쾌적합니다. 또한 편안한 분위기라 긴","notes":"장이 많이 풀렸습니다. 아날로그 시계는 지참할 수 있었습니다. 기다리는 동안에는 아무것도 할 수 없습니다. 그냥 가만히 앉아 있어야 합니다.","qa":[{"q":"(추가 질문) 학생이 말한 ~한 점이 이해가 가지 않는데, 다시 한번 설명해 주세요.","a":"먼저 ~에서는 이러한 차이점이 발생하고 있습니다. (사례를 들며) 이러한 점에서 관점의 차이가 발생하고 있기 때문에 차이점이 발생한다고 생각하였습니다."},{"q":"(추가 질문) 학생은 지리라는 과목에 대해서는 세 가지의 입장 중에서 어떤 것이 가장 중요하다고 생각하나요?","a":"저는 보존성이 가장 중요하다고 생각합니다. 지리라는 과목 특성상 한 지역의 특성을 있는 그대로 본다는 것이, 그 지역을 그대로 이해하는 점을 통해서 선입견 없이 지역의 특성을 받아들일 수 있다고 생각하였기 때문입니다. <교직 인적성 면접>"},{"q":"(추가 질문) 학생은 교육에서 인성, 도덕적인 측면의 학습이 중요하다고 생각하는 것 같습니다. 이것을 왜 중요하게 생각하게 되었는지 사례를 들어서 설명해 줄 수 있나요?","a":"제가 학교생활을 하며 주변에서 학생들이 선생님께 예의 없이 행동하는 모습을 많이 관찰하여 그렇게 생각하였습니다. 하나의 사례로는 ~한 점이 있었습니다. 아무리 학급 친구라고 하여도 이러한 모습은 제 3자의 입장에서도 너무 불쾌하였습니다. 이러한 사례를 통해서 저는 성적보다 인성교육이 먼저가 되어야 한다고 생각하였습니다. 후배들을 위한 조언 충분히 많이 연습한다면 자신이 준비한 모든 것을 교수님들께 보여드릴 수 있다고 생각합니다. 수험생분들 모두 파이팅입니다!!"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(1권)」","year":"2025학년도"},{"univ":"서울대학교","dept":"생물교육과","jeonhyeong":"학생부종합(지역균형전형-입실시간 전까진 자유롭게 준비자료를 볼 수 있었음.-8:15 입실시간 이후로 신분증, 수험표만 꺼내고 나머지 일절 보지못)","method":"하게 함.-수험번호 맨 뒷자리 두 번호가 면접번호인 줄 알았는데, 갑자기 두번째로 호명되서 놀람.-면접은 9:00 부터 시작이었으며, 자신의 차례 5분 전 이동해서 면접방 앞에서 기다림.","notes":"면접방은 굉장히 큰 편이었고, 면접관과 자리가 너무 멀었음. 그래서 목소리가 잘 전달되도록 평소보다 크게 말하려고 함.","qa":[{"q":"(교수) 네. 바로 질문할게요. 생명과학2 교과시간 세포노화와 새포재생기전에 대해 탐구했는데, 어떻게 연구했는지 간략히 말해주세요.(여기서 두번 당황함. 먼저 잘 왔는지 분위기를 풀어가는 질문 말고 바로 생기부 질문을 하셨음. 또 활동의 내용을 물어보는게 아니라 ‘연구방법’을 물어보셔서 당황함. 그래서 약간 말을 더듬고 목소리 톤이 고르지 못했음.)","a":"네. 저는 생명과학2 교과시간에 다양한 학술자료를 종합하여 세포의 손상신호 전파, DNA 복구과정, 자가사멸과정을 탐구했습니다. (리소좀으로부터 확장된 활동임을 밝혀야 했는데, 이를 말하지 못해 아쉬움)"},{"q":"(교수) 어떤 학술자료를 종합했죠? 그 중에 가장 기억에 나는 학술자료나 내용이 있을까요?","a":"네. 저는 자가사멸과정을 탐구한 논문, 학술자료에서 p53단백질을 통해 CED-3 단백질과 CED-4 세포가 활성화되어 자가사멸과정이 진행될 때, Ced-3와 ced-4단백질이 톱니바퀴 모양으로 합성된다는 점이 인상깊었습니다. 어떻게 톱니바퀴처럼 모양이 형성되어서 세포를 사멸시킬 수 있을지, 어떻게 이런 작용기전이 존재할 수 있을지 감탄했었던 기억이 있습니다. (처음 생각해 본 주제여서 당황했지만, 교과시간에 탐구한 내용을 바탕으로 대답함.)"},{"q":"(교수) 그럼 학술자료를 종합해 봤을때, 자신이 제안해 볼만한 말은 무엇이 있을까요? (앞서 학술자료를 종합해서 어떤 점을 느꼈는지에 대해 답변하지 않아서, 이 말을 듣고싶어 하신 것 같았음)","a":"여러 학술자료를 종합해서 저는 세포의 생사과정을 다각도로 생각해볼 수 있었습니다. 그런데, 이 학술자료에 나와있는 작용기전들은 생명과학인데, 생명과학2 교과시간에 배우지 않고 접하기 어려운 기전이었습니다. 저는 생명과학 교과가 조금 더 이런 세부적인 내용들을 교육하고, 학생들에게 더 많은 기회를 주어야 한다고 생각했습니다.(이것도 예상치 못한 질문이었다. 첫 질문부터 꼬리질문이 모두 생각치 못한 질문이어서 너무 당황했다ㅜㅜ 그러나 침착하게 답변을 이어나가고자 노력했다. 교육과정 측면과 엮어 대답하려 했다.)"},{"q":"(입학사정관) 고급 생명과학을 수강하셨네요, 이때 전자의 이동과정을 탐구했다고 했는데 활동을 한 동기랑, 어떤 점을 배웠는지 설명해주세요","a":"네. 우선 저는 고급생명과학을 수강하며 전자전달계를 통한 화학삼투 과정에서 흥미를 느껴, 어떻게 수소이온이 펌핑될 수 있는지 궁금했습니다. 탐구한 내용으로는 퀴논회로에서 유비퀴논이 전자를 받아, 미토콘드리아 내막에서 수소이온을 끌어올린다는 점을 탐구했습니다. 이 점을 통해, 고급생명과학 수업시간에 배우지 못한 수소펌핑과정의 구체적인 내용을 습득할 수 있었습니다."},{"q":"(입학사정관) 고급생명과학에서 다른 실험을 했다고 나와있는데, 무엇이죠?","a":"저는 유세포분석기를 이용한 활동을 진행했습니다. 암세포를 대상으로 실험했는데, s기, m기 ,g1 g2기 등을 유세포분석기를 통해 표본을 추출하고 관찰하는 활동을 진행했습니다. (s기 m g g1이 아니라 분열기의 중 후 전 말기를 분석하는 것이었는데 잘못 말했다 ㅜㅜ)"},{"q":"(입학사정관) 거기서 특별히 배운 점이 있을까요?","a":"네, 사실 저의 표본은 실패했습니다. 저는 분열기에서 중기의 세포가 적게 나왔습니다. 이것은 올바른 표본과 다른 점이었는데요, 이를 통해 앞으로는 실험을 메뉴얼대로 정확히 진행해야겠다는 점을 깨달았습니다. (지금 생각해 보니 이때 구체적으로 분열기의 중기라고 특정 구간을 잡아줘서 앞선 질문에서 아쉬운 점을 대체할 수 있었다고 생각)"},{"q":"(입학사정관) 매뉴얼이란 무엇이죠?","a":"네, 저는 원심분리기를 통해 상층액을 분리하는 과정에서 상층액을 지나치게 많이 분리해냈습니다. 이 점이 오류였다고 생각하고, 실험 계획과 과정 속 수행을 정확히 지켜야 한다고 생각을 했습니다 (생각을 했습니다 말고 생각했습니다가 나았음…)"},{"q":"(입학사정관) 좋네요. 계속 반장과 부장을 해온거로 나와있는데, 이 과정에서 배운 점과 어려움을 극복하려 노력한 점 있을까요?","a":"저는 계속 반장과 부장을 도맡으며 리더십에 두가지 종류가 있다는 점을 배웠습니다. 저는 항상 리더로서 겪은 어려운 점이, 학생들을 카리스마 있게 통제하고 휘두르지 못한다는 점입니다. 그러나, 저는 이 단점보다는, 소통과 협력으로 구성원들을 화합시키는 유한 리더쉽을 발휘하려 노력했습니다."},{"q":"(입학사정관) 그거에 대한 구체적인 사례 설명해주세요. (사례를 말하지 않아서 궁금하셨나봄.)","a":"2학년때 학급의 중요한 일을 결정해야했던 사례가 있었습니다. 이때 많은 학생들의 의견이 통합되지 않아서 저는 의견을 강압적으로 모으려 시도했습니다. 그러나 결국 모두의 의견은 존중받아야 한다고 생각했고, 이후 소통과 대화를 통해 여러 친구들의 의견을 모으고, 절충안을 제시하는 것으로 했습니다. (말이 이상하지만 진짜 이렇게 대답함..)"},{"q":"(입학사정관) 알겠습니다. 생물학과나 다른 자연대학이 있었을 텐데, 굳이 생물교육과를 지원한 동기가 있을까요?","a":"생물교육과를 지원한 동기가 크게 세 가지가 있는데, 다 말씀드려도 괜찮을까요?"},{"q":"(입학사정관) 네. 그렇게 하세요.","a":"첫 번째로, 저는 중학교. 중학교 2학년 때 한 수학선생님의 수업에 영감을 받아 그때부터 교육자를 꿈꿔왔습니다. 이후 고등학교에 진학해 생명과학 과목을 수강한 후, 생명과학에 깊은 흥미를 느껴 생명과학을 더 연구하고 싶었습니다. 마지막으로 생명과학 수업을 들을 때, 문득 이런 생각이 들었었습니다. 생명과학의 본질이란 생명을 연구해 인류와 사회 복지 발전에 이바지하는 학문이다. 그런데, 교과과정에서는 정말로 일상에 적용하는 생명과학을 배우기 어려운 실정입니다. 따라서 교육과정을 바꾸긴 어렵겠지만, 학자 그리고 교육자가 되어서 교육과정을 제안하는 사람이 되고 싶어 지원했습니다."},{"q":"(교수) 음. 네 생명과학과에 진학하면서 특히 공부하고 싶은 분야가 있을까요?","a":"네. 저는 뇌과학을 공부하고 싶습니다. 생기부에 나와있을 지는 모르겠지만, 저는 뇌 관련 탐구를 많이 진행해서 관심이 있습니다."},{"q":"(교수) 구체적으로 어떤?","a":"신경세포가 신호를 전달할 때, 전기적 신호로 신호를 전달하는 것이 정말 인상깊었습니다. 단순히 세포일 뿐인데 그런 신호를 전달할 수 있다는 것을 저는 사람이 의사소통 하는것과 유사하다고 이해했습니다. 수많은 신경세포로 이루어진 뇌는 이런 뉴런들이 수많이 분포해있는것을 알 수 있습니다. 따라서 저는 뇌를 연구해 세포의 의사소통과정을 이해해보고 싶었습니다. 마치 사회에서 사람들이 서로 상호작용하는 것 처럼 말입니다.(교수, 입학사정관) 네. 이제 시간이 다 되어서 나가봐도 좋습니다.후배들을 위한 조언 수행평가 및 활동의 내용을 깊이 있게 질문했습니다.수박 겉핥기 식의 탐구와 세특은 위험합니다."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(1권)」","year":"2025학년도"},{"univ":"서울대학교","dept":"산림과학부","jeonhyeong":"학생부종합(기회균형특별전형(사회통합))","method":"자기소개+지원동기 → 입학 후 학업 계획 → 본교 수강 과목 관련 질문 → 화학2 질문 → 영어 질문","notes":"","qa":[{"q":"자기소개와 지원동기에 대해 말씀해주세요.","a":"저는 어릴 적부터 할머니와 함께 보낸 시간이 많음. 할머니의 건강을 위해 인근 산책로로 운동을 가곤 하였는데 저는 운동을 할 때 많은 곤충이 있음을 불평함. 할머니로부터 곤충이 있기에 우리가 살 수 있음과 같은 환경 이야기를 들음. 계절 변화에 따른 환경에 관심을 갖게 됨. 그 과정에서 관찰한 자연현상과 오염으로 인해 순환되지 않는 자원을 알게 됨. 이러한 환경 자원을 생태계 균형을 유지하는 선에서 이용하고 자연적으로 순환시키고, 환경 오염을 예방하는 것에 대해 공부하고 싶어 지원함."},{"q":"만약 입학하게 된다면 무슨 공부를 하고 싶나요? 혹시 산림과학부에서 배우는 과목 중 아는 게 있다면 말하세요.","a":"환경을 예방하는 공부와 환경 훼손 시 이를 원래의 모습으로 회복하는 것에 대해 배우고 싶음. 자연 회복의 중요성과 회복 불가 시의 피해에 대해 언급함. 이를 복구하고자 함. 학과 과목 중 수목 생태학이 있음을 말하고 무슨 학문인지와 수강하고 싶은 이유를 말함."},{"q":"화학2에서 완충용액에 대해 탐구하였다는데 완충용액이 무엇인지와 완충용액이 생물에게 중요한 역할을 한다는데 무슨 역할이고 왜 중요한지 자세히 설명해주세요.","a":"화학2 질문에서의 내가 탐구한 완충용액의 개념을 말함. 이를 산림과학부와 식물에 어떻게 적용할 수 있는지에 대한 내 생각과 가능성을 제시함. 생물에게 완충용액이 중요한 이유로 혈액과 몸이 아플 때 수액을 맞는 등 외부의 물질에 대한 항상성을 유지하는 등 다양한 역할을 함을 언급함. 만약 완충용액이 아니었다면 산성과 염기성으로 산성도가 변화하여 죽을 수 있다고 말함."},{"q":"영어 시간에 빛 공해에 대해 포스터를 작성했는데 정확히 무슨 활동이었는지 말하세요.","a":"영어 질문에서 빛 공해를 탐구하였는데 그 이유와 탐구 내용을 말함. 교과를 배우며 빛 공해에 대해 알게 되었고 그것이 무엇이고 왜 발생하게 되는지 설명함. 빛 공해가 생태계에 미치는 영향을 말함. 거북이가 해변에 알을 낳고 알이 부화할 때 가로등을 달로 착각하여 바다의 위치를 혼동하고, 인공 빛이 해양 생물들의 생태 리듬에 안 좋은 영향을 미칠 수 있다고 말함.후배들을 위한 조언긴장을 하지 않는 것이 중요한데 긴장을 하더라도 내가 할 수 있는 말과 아는 것에 대해최대한 전부 말하는 것이 중요한 것 같습니다."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(2권)」","year":"2025학년도"},{"univ":"서울대학교","dept":"산업공학과","jeonhyeong":"학생부종합(지역균형전형)","method":"지원동기 - 학생부 전반 질문 - 동아리 질문 - 가치관 - 공동체","notes":"","qa":[{"q":"학생부에 보면 수학과 관련된 활동이 많은데 산업공학과에 지원하게 된 동기가 뭔가요","a":"수학에 대해 관심이 많았고, 그 의미와 가치에 대해 탐구를 하다보니 응용에도 흥미가 갔었다. 그 응용분야와 더불어 산업공학과에서는 다양한 분야와 관점에서 문제를 접근하는 방식을 주로 활용하는데, 그런 점이 매력이 있어 지원하게 되었다."},{"q":"수학에 대하여 많은 탐구활동을 진행하였는데, 이런 활동을 하게 된 계기가 뭔가요","a":"수학에 처음 흥미를 느껴 시작했지만, 본격적으로 관심을 가지게 된 계기는 1학년 탐구 활동 시간이었던 것 같다. 특히 변환과 전환을 통해 논리적으로 해석하는 과정이 나에게 깊은 인상을 남겼다. 1학년 탐구 활동 시간에는 무한 집합의 증명과 개념을 탐구했는데, 직관적으로 이해하기 어려운 개념을 일대일 대응과 같은 논리를 통해 설명하는 과정이 무척 매력적이었다."},{"q":"2학년 동아리 활동시간에 보면 ai를 이용한 통계자료 분석이란 활동이 있는데 동기가 뭐고 어떤 자료를 선정했고 결론은 뭔가요","a":"동기는 통계자료의 해석과 관한 강의를 듣고 직접적으로 분석해보고 싶다는 생각에서 였으며, 문제에 대한 원인을 친구와의 소통으로 추려낸 후 통계청의 자료를 활용하였다. 결론은 저출산과 집값, 사교육비, 노동시가늬 양은 상관관계를 보인다는 것이었다."},{"q":"인생에서 가장 중요하게 여기는 가치는 무엇인가요","a":"1학년 2학기 쯤에 성적이 급락하게 된 적이 있는데, 이떄 선생님께 도움을 요청하고 많이 받아 해결한 적이 있었다. 그런 도움이 없었더라면, 지금과 같은 성장도 이뤄낼 수 없었을 것이고 그렇기에 예의가 가장 중요한 가치인 것 같다."},{"q":"리더쉽 활동한 사례 설명해주세요","a":"대표적으로 텐세그리티와 같은 주제로 팀 프로젝트 활동에서든지 학급 부스 운영에서의 활동가 있었다. 학급 부스 운영과정에서 전자기기의 고장으로 부스가 중단된 적이 있는데 이를 친구들과의 소통으로 분석해낸 후 장소 이전을 위한 곳을 선정하기 위해 역할 분담을 지시하였다. <답변 도중에 끝남.>후배들을 위한 조언 두괄식 답변, 대화라는 점 인지하기. 두가지로 요약할 수 있을 것 같다.면접 준비를 하다보면, 선생님들께서 두괄식 답변을 하라고 크게 강조하실 텐데 다음번에 말할 것의 개요를 잡는다고 생각하면 편하다. 두괄식 답변의 장점은 면접관 분들에게 다음 내용이 어떤 게 나올지 예상가능하게 한다는 점 뿐만 아니라 답변자에 입장에서 생각할 시간을 벌 수 있다는 것이 있다. 또한 제가 “…하게 된 동기는”, “… 하는 과정에 있어서” 와 같은 말 그와 관련된 답변의 기억들을 떠올리는데도 도움이 될 수 있다. 다만, 여기서 더 나아가 핵심적인 키워드를 먼저 제시하고 가면 좋겠으나 대부분은 이것이 무리일 가능성이 높기에 자기만의 말하는 방식에 덧붙이는 정도로 활용하면 좋을 것 같다.말을 조리있게 한다는게 단시간에 느는 것이 아니기에 학교과정 중에서도 설명하는 활동을 해보는 게 중요하다. 발표나 조원들에게 내용을 전달하거나 멘토링 활동 등을 통한 방식도 좋지만, 나 같은 경우에는 부모님과의 대화가 큰 역할은 한 것 같다. 세대 차이와 더불어 탐구하고자 하는 요소들이 부모님께는 낯설다 보니 이를 이해시키기 위해서는 내용이 관심이 가게 말하는 게 중요한데, 그 과정에서 자신의 내용을 정리해보고 여러 방식으로 설명 하면서 어떻게 해야 내가 전달하고자 하는 바를 얘기해야 이해하기 쉽구나를 터득한 것 같다. 이를 기반으로 하여 대화라는 것을 인식하는게 중요한 이유는 생기부에 관한 내용을 다시보고 면접준비를 하게되다 보면, 모의 면접에서 그냥 외우고 이를 답변하는 경향성을 보이기 쉬운데, 이런 답변은 면접에서 크게 도움이 되지 않기 때문이다. 물론 생기부 내용 확인 측면에서는 도움이 되겠으나, 서울대와 같은 상위권 대학에서는 생기부에 ‘표면적으로 드러나지 않은’ 학업역량, 태도, 공동체 역량의 확인에 그 목적을 두고 있기 때문이다. 그렇기에 청자와 화자 간의 목적과 상황을 고려하여, 즉 질문의 의도를 잘 파악하고 그에 맞춰 설명함과 동시에 자신의 장점을 뽐아내는 대화라는 점을 인식하는 것이 중요하다고 할 수 있다.추가적으로 생기부 분석은 중심활동을 기준으로 생기부 전체의 동기와 배운점을 이야기한다는 관점에서 접근하면 도움이 될 것이다. 생기부 하나하나 읽다보면, 너무 많기도 하고 모든활동이 진심일 수 없기에 가라거나 표면적으로 진행한 활동이 더러 있을 수 있는데 그런 점에서 매몰되다보면 전체를 잃는 경우가 생길 가능성이 있기 때문이다."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(2권)」","year":"2025학년도"},{"univ":"서울대학교","dept":"식품영양학과","jeonhyeong":"학생부종합(기회균형특별전형(사회통합)1. 대기실: 입실 및 착석 → 면접 순서에 따라 자리 이동 → 대기)","method":"2. 면접실: 인사 → 자기소개 → 과학교양 탐구 질문 → 프로그래밍 탐구 질문 → 생명과학2, 고급화학 탐구 질문 → 확통 탐구 질문 → 입학 후, 졸업 후 계획 → 인사","notes":"휴대폰은 따로 걷지 않고 전원 꺼서 각자 가방에 넣습니다. 다른 전자기기는 되도록 빼고 가시는 것을 추천드립니다.","qa":[{"q":"(남) 간단히 자기소개 해주세요.","a":"저는 자연 현상과 생명활동의 과학적 원리를 화학, 생명과학을 바탕으로 탐구하는 것을 좋아하는 학생입니다. 특히 3학년 때 활성산소의 대사과정과 비타민과 같은 영양소의 항산화작용에 대해 분자 수준에서 탐구하는 과정에서 실생활과 밀접한 현상을 과학적으로 이해하는 것에 큰 흥미를 느꼈습니다. 따라서 과학적 원리를 바탕으로 식품학, 영양학을 더 깊이 공부하며 전문성을 갖추고 여러 식생활 문제를 해결하며 사람들에게 건강한 식생활의 중요성을 알리고 싶어 식품영양학과에 지원하게 되었습니다."},{"q":"(남) 2학년 과학교양에서 바이오차에 대해 탐구했는데, 이것에 대해 자세히 설명해주세요.","a":"(바이오차 탐구 계기, 이점 등 설명)"},{"q":"(남) 프로그래밍 시간에 만든 카페인 중독 판단 프로그램에 대해 설명해주세요.","a":"(이 때 사용한 문법, 코드 등 설명)"},{"q":"코드를 직접 짠 건가요?","a":"네. 수업시간에 배운 여러 코드를 활용했습니다."},{"q":"(남) 중독을 판단하는 질문은 본인이 만든 건가요?","a":"아닙니다. 신뢰성 있는 공식 기관(식약처. 특정 기관 이름 말하면 불이익 있을까봐 이정도로만 말함.)의 평가 기준을 토대로 작성했습니다."},{"q":"(여) 아까 자기소개할 때 말한 비타민의 항산화작용에 대해 설명해보세요. (생명과학2, 고급화학)","a":"(활성산소가 위험한 이유 화학적으로 설명, 비타민C, 비타민E가 활성 산소를 중화시키기 위해 상호작용하는 과정 구체적으로 설명.)"},{"q":"(여자 교수님께서 질문 하나 더 하셨는데 기억이 안 남. 바로 앞에서 답변드린 내용중에서 다시 물어보셨음.)","a":""},{"q":"(남) 민감도, 특이도란 무엇인지 설명해보세요.","a":"(개념 설명)"},{"q":"(남) 베이즈정리란 무엇인지 설명해보세요.","a":"(베이즈정리의 쓰임, 수식 설명)"},{"q":"(남) 확통시간에 탐구한 내용을 결핵에 적용하면 어떻게 설명할 수 있나요?","a":"여러 결핵 검출 반응에서 양성으로 진단받은 사람이 실제로 양성일 확률, 음성으로 진단받은 사람이 실제로 음성일 확률을 계산할 수 있습니다."},{"q":"(남) 시간이 거의 끝나가서… 혹시 우리 학과 입학해서, 그리고 졸업후 뭘 하고 싶은지 말해보세요.","a":"저는 대학에 입학해 배운 전공지식을 바탕으로 영양교육 봉사 동아리를 만들어 활동하며, 효과적인 영양교육 방법에 대해 고민하고 실행함으로써 사람들에게 건강한 식생활의 중요성을 알리고 싶습니다. 그리고 졸업 후에는 대학원에 진학해 영양학 분야를 더 깊이 공부하고, 식품이 인체에 어떤 영향을 미치는지를 분자 수준에서 탐구하고 싶습니다."},{"q":"(남) 네. 고생 많으셨습니다. 나가셔도 됩니다.","a":"네. 감사합니다. 안녕히계세요.후배들을 위한 조언 전공 관련 심화 질문이 생각보다 안 나올 수도 있으니 심화 질문뿐만 아니라 전공과 큰 관련 없는 과목들에서 했던 탐구 활동도 소홀히하지 않는 게 좋을 것 같아요. 생기부에 탐구나 발표 내용에 대한 교사의 칭찬이 적혀있는 부분은 더 꼼꼼히 준비하는 것을 추천드립니다. 서울대 교수님들 앞에서 떨리는 것은 당연하겠지만, 최대한 본인 능력을 보여드리려면 정신을 똑바로 차려야합니다! 이 글을 읽는 분들 모두께 좋은 결과 있길 바라겠습니다."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(2권)」","year":"2025학년도"},{"univ":"서울대학교","dept":"에너지자원공학과","jeonhyeong":"학생부종합(지역균형전형)","method":"8시까지 1층 대기하고 자기 시간에 맞춰 조끼리 면접층으로 이동함. 문 바로 앞에서 대기 후 입장.건물 안은 생각보다 따듯함. 밖은 추우니까 건물 바로 앞까지 차타고","notes":"가는 게 좋음. 패드나 노트북 안 가져가는 게 편함. 학교에서 핫팩 줌. 면접 조가 뒷 번호로 잡힐 수 있어서 먹을 거 가져가도 좋음. 화장실 가기 어려움.","qa":[{"q":"3학년 때 했던 자율활동을 하게 된 계기 설명해주세요","a":"생명과학실험에서 했던 탐구활동을 이용해서 설명함."},{"q":"3학년 때 했던 진로활동의 과정을 설명해 주세요.","a":"설명함."},{"q":"양자역학과 양자역학에 대해서 관심이 있는 것 같은데 양자 컴퓨터의 원리가 무엇인가요?","a":"큐비트와 양자중첩을 연관지어서 설명함."},{"q":"그러면 양자컴퓨터와 슈퍼컴퓨터 중 어느 것이 더 빠르고, 그 이유도 알려주세요.","a":"양자컴퓨터가 더 빠르다고 하고, 앞에서 말한 원리 반복함."},{"q":"수학을 잘하시는 것 같은데 수학을 잘하면 에너지자원공학과에서 어떤 부분에 도움이 되는지 알려주세요.","a":"에너지자원공학과는 물리학을 많이 배우는 것으로 알고 있습니다. 물리학을 배우기 위한 기초는 수학이기 때문에 수학을 잘하는 것이 중요하다고 생각합니다."},{"q":"그러면 수학을 잘하면 물리도 잘할 것이고.. 이 두 과목 빼고 좋아하는 다른 과목있나요? 그리고 그 과목을 에너지자원공학과와 연관지어서 설명해주세요","a":"정보 교과를 가장 좋아합니다. 에너지자원공학과에서도 컴퓨터공학과 인공지능 분야를 많이 사용하는 것으로 알고 있습니다. ~....."},{"q":"정보 시간에 R&D 예산 삭감에 대해서 조사하신 것에 대해 설명해주세요.","a":"설명함."},{"q":"1학년 때 진로희망이 의사 쪽 이였는데 공학 쪽으로 바꾼 이유를 설명해주세요","a":"1학년 때는 주체적으로 선택하지 못함. 1학년 겨울방학 때 하이젠베르크의 [부분과 전체]에서 주인공이 진로를 설정하는 장면에서 영감을 받아 바꾸게 됨."},{"q":"우리 학과를 졸업한 뒤 어떤 것을 하실 예정인가요? 창업? 연구?","a":"대학원 졸업한 뒤, 연구할 예정.후배들을 위한 조언 진로를 바꿨기 때문에 학과에 대한 지식과 졸업 후 진로에 대해 많이 물어봄. 위에 쓴 질문보다 진로에 관한 질문 많이 물어봄. 생기부 질문은 나올 것 같은 활동 확실하게 준비하는 게 좋음."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(2권)」","year":"2025학년도"},{"univ":"서울대학교","dept":"에너지자원공학과","jeonhyeong":"학생부종합(기회균형특별전형(사회통합)(오전 기준)1. 안내된 시각(08:00)까지 입실)","method":"2. 수험번호 및 본인 확인 후 명찰 배부3. 전자기기 수거 후 사전 안내 진행4. 대기실에서 호명하면 면접실 앞에서 중간대기5. 면접 후 안내 따라서 퇴실-신분증, 수험표 반드시 지참.","notes":"-대기실에선 전자기기 수거 이후에 본인이 가져온 자료를 일체 볼 수 없고 자기 차례가 될 때까지 그냥 기다려야 함.","qa":[{"q":"다른 지원자와는 차별되게 신춘문예반에서 활동을 했던데 어떤 노력을 하셨나요?","a":"먼저 제가 활동을 한 동기를 말씀드리겠습니다. 저는 학업적 성취를 위해 공부하면서 발생하는 스트레스를 해소하는 것도 중요하다고 생각했습니다. 따라서 저의 감정을 시로서 승화시키고자 노력했고, 그 과정에서 저의 부족한 문과적 성향을 보충하려 여러 매체를 참고해서 공부하려 노력했던 것 같습니다."},{"q":"가장 인상 깊은 과목이 무엇이었나요?","a":"물리학과 미적분이 가장 인상 깊었습니다 물리와 수학을 공부하다 보면 어려운 개념에 부딪힐 때가 많습니다. 이때 낙담하지 않고 책을 통해 사고를 발전시키는 방향으로 문제를 해결해 왔기 때문에 기억에 남습니다."},{"q":"구체적으로 책을 참고하여 활동한 경험이 있나요?","a":"저는 미적분 시간에 탐구가 기억납니다. 당시 1/n 급수의 수렴 발산에 대해 탐구하면서 이 수렴값을 정확하게 계산한 오일러의 방법을 알게 되었습니다. 이것의 전개 과정을 이해하기 어려워서 대수학에 관련된 책을 읽었고 직접적으로 도움을 받진 않았지만, 책의 논리를 따라가면서 사고를 발전시켜 이해할 수 있게 되었습니다."},{"q":"은행 상품 추천 프로그램을 진짜 만든건가요?","a":"네. 인공지능에 가상으로 만든 고객 정보와 그때 추천되는 은행 상품 데이터를 학습시켜 고객의 정보를 주었을 때 은행 상품을 추천하는 프로그램을 만들었습니다."},{"q":"구글 클라우드에서 진행한 건가요?","a":"구글 코랩이라는 환경에서 파이선을 기반으로 프로그램을 만들었습니다."},{"q":"부모님이나 친구들에게 적용하지는 않았나요?","a":"그 프로그램을 실제 사람에게 적용하는 데에는 한계가 있었습니다. 가상의 데이터로 학습을 시켰기 때문에, 실제 사람의 데이터를 입력했을 때 결과가 신뢰할만하지 않다고 생각하여 실제 데이터를 입력하지는 않았습니다."},{"q":"수소연료전지를 직접 만든건가요?","a":"직접 만들기는 했으나 실제 작동이 가능한 것은 아닌 모형이었습니다."},{"q":"수소연료 전지에 대해서 설명해주세요.","a":"먼저 연료전지란 연료를 공급하여 화학적 에너지를 전기적 에너지로 전환하는 장치입니다. 수소연료전지는 수소 기체와 산소 기체의 산화 환원 반응을 이용해서 전류를 생산한다고 알고 있습니다."},{"q":"특히 연료 전지 등 신재생 에너지에 관심을 가지고 있는거 같은데 이유가 있나요?","a":"현재 화석연료를 이용해서 발전을 하며 기후변화나 자원고갈과 같은 문제가 대두되고 있다고 알고 있습니다. 이를 해결하기 위해서는 핵융합을 통한 발전이 필요하다고 생각합니다. 하지만 이는 시간이 걸린다고 알고 있고 이 공백이 생기게 됩니다. 이 에너지의 공백을 채우기 위해 신재생에너지의 효율적인 발전을 가능케 해야 된다고 생각했습니다."},{"q":"혹시 우리 에너지자원공학과의 커리큘럼에 대해 찾아보았나요?","a":"네. 학과의 커리큘럼에서 지구과학 지식이 필요한 과목이 많았다고 기억합니다. 제가 지구과학을 수강하지 않아서 단점이 될 수 있지만, 책을 통해 문제를 해결했던 것처럼 어려움을 겪더라도 잘 해결해 나갈 것 같습니다."},{"q":"커리큘럼 중에서 특히 관심이 가던 게 있던가요?","a":"저는 자원의 시추와 추출이 흥미로웠던 것 같습니다. 아직 전문적인 지식은 없어 잘 알지는 못하지만 그 채굴 과정이 궁금해서 관심이 갔습니다."},{"q":"우리 학과에서 무엇을 할지 생각한 것이 있나요?","a":"저는 저의 물리학에 대한 이해를 바탕으로 자원의 효율적 이용에 대한 연구를 하고 싶습니다. 아직 학과에 대해 잘 알지 못하지만, 학과 공부를 하고 관심이 가는 주제에 대해 연구를 할 것입니다. 기업체에 들어가거나 대학원을 진학하는 등 관심이 가는 주제의 연구를 이어가고 싶다고 생각했습니다."},{"q":"물리학 과목과 우리 에너지자원공학과와 어떻게 연관되나요?","a":"아주 직접적으로 연관이 되지는 않는다고 생각합니다. 하지만 물리학에 대해 탐구하며 흑체 복사 문제에 관심을 가지게 됐고, 이는 태양전지의 효율을 구하는 활동으로도 이어졌습니다. 또한 마찰력에 대해 탐구를 하기도 했는데 이것이 발전과정에서 손실되는, (...)(10분 끝) 문이 열리며 종료.후배들을 위한 조언 생각보다 관련 탐구활동을 묻지는 않아서 의외라고 생각했습니다. 생기부 위주일지 개방형 느낌일지는 모르기 때문에, 모든 상황을 열어두고 준비하셔야 합니다. 생기부, 학교 생활뿐만 아니라 자신의 학과와 장래에 대해 깊이 생각하고 정리하는 기회가 되었으면 좋겠습니다. 저는 신분증을 두고 갔습니다. 염두하지 못한 일이 일어나도 당황하지 마시고 유연하게 풀어나가시길 바랍니다."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(2권)」","year":"2025학년도"},{"univ":"서울대학교","dept":"응용생물화학부","jeonhyeong":"학생부종합(지역균형전형)","method":"대기실에서 대기->면접번호에 따라 10분간 면접을 진행함","notes":"면접번호는 당일 고사장에 가서 알려줌대기실에서 대기할 때 준비한 종이 등을 볼 수 없음","qa":[{"q":"생기부에 약 관련 내용이 많은데 굳이 이 학과에 지원하게 된 동기가 뭔가요?","a":"저는 생명체에 대한 관심을 가지고 탐구와 실험을 진행했습니다. 저의 목표는 인간의 삶의 질을 높이는 것이었고, '의식주' 중 '식' 측면의 질을 높이는 것에 관심이 있어 왔습니다. 약도 일종의 '식' 측면에서 건강을 증진시키며 인간의 삶을 더 향상시킬 수 있어 관심을 가졌습니다. 비록 학교 환경이 제한적이어서 약과 관련한 화학 실험 위주로 진행하였으나, 저는 식생활을 높이도록 노력하고 싶습니다."},{"q":"학과 뭐하는 곳인지 알고 있나요?","a":"생명체에 대한 지식을 바탕으로 생물학적 화학적 측면에서 생물을 분석하는 곳이라고 알고 있습니다. 특히 농업 분야에 활용하는 원리나 기술에 대해 연구합니다."},{"q":"이 학과와 관련해 관심있게 했던 탐구가 뭔가요?","a":"생2 교과 시간에 DNA 복제 모델들을 공부했고, 대장균 배양을 통한 DNA복제 관찰 실험이 결국 반보존적 복제가 생명체에 일어나는 복제 모델이라는 것을 알았습니다. 그러나 이 실험은 대장균을 대상으로 한 사실 증명 실험으로 과연 모든 생명체들이 반보존적 복제 모델을 따른다고 할 수 있나 궁금증이 들었고, 자료조사를 했습니다. 결론은 발견된 모든 생명체는 반보존적 복제 모델을 한다는 것이었습니다. 저는 비록 현실에서는 불가능하지만, 분산적 복제나 보존적 복제를 따르는 모델에 대해 탐구하고자 하는 목표가 있었습니다. 따라서 가상의 실험체를 구상해 모의실험을 했습니다. 저의 결론으로는 분산적 복제 모델은 지나치게 많은 돌연변이로 인해, 보존적 복제 모델은 한정된 유전정보로 인해 유전적 부동 현상이 일어나면서 자연선택으로 인해 멸종되었을 것이라는 가설을 세웠습니다. 이 활동을 통해 실험의 한 분야로 모의실험에 대한 경험을 할 수 있었습니다."},{"q":"DNA보존적 복제 모델 뭔지 설명해주세요.","a":"이중나선의 DNA 전체를 주형으로 하여 원형 그대로 보존되는 모델입니다."},{"q":"연구하고 싶은 분야는 만약 있다면 뭔가요?","a":"저는 '침묵의 봄'을 읽고 친환경 살충제와 제초제에 대한 관심을 키워왔습니다. 그러던 중 곰팡이-식물의 mRNA분자 전쟁에 대해 알게 되었습니다. 이 두 생명체는 서로의 유전자 발현을 조작해 싸우게 됩니다. 이를 통해 친환경적 살충제,제초제의 가능성이 될 수 있겠다고 생각했고 이에 대해 더 연구를 해보고 싶습니다.후배들을 위한 조언 이미 질문자체가 왜 해당 학과에 지원했는지에 대한 내용 중심입니다.1차에서 대충 점수가 결정난 것 처럼 느껴졌습니다.생기부 내용에 대한 숙지가 충분하다면 전혀 어렵게는 느껴지지 않다고 생각합니다."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(2권)」","year":"2025학년도"},{"univ":"서울대학교","dept":"첨단융합학부","jeonhyeong":"학생부종합(지역균형전형)","method":"입실 시간 전까지 면접 대기실에 입실하고 유의사항을 안내받습니다. 면접 대기실에서 기다리다가 순서가 되면 불러줍니다. 순서가 되면 10분간 면접 후 바로 귀가하면 됩니다. 면접 대기실에서는 준비한 자료도 걷어가서 못 봅니다. 그리고 뒷","notes":"순서면 오래 기다려야 하니까 당을 채워줄 수 있는 간단한 간식 정도는 챙기면 좋을 것 같아요","qa":[{"q":"첨단융합학부에서 필요한 역량은 무엇이라고 생각하시나요?","a":"다양한 교과를 융합하고 문제를 발굴해낼 수 있는 능력이 필요하다고 생각합니다. 저는 이러한 역량을 기르기 위해 융합과학탐구반이라는 동아리에 들어가 활동을 진행하였습니다. 동아리에서는 수학 개념인 정규분포와 물리학 개념인 이중슬릿 패턴을 연관시켜 활동을 진행하였습니다. 일단 갈톤 보드에서 구슬이 배열되는 모습을 보며 정규분포에 대해 생각해볼 수 있었고 이중슬릿 실험을 통해 가운데로 갈수록 빛의 세기가 세지는 패턴을 보며 여기에도 정규분포의 형태를 띤다는 것을 알게 되었습니다. 이때 구슬은 입자성만을 띠지만 이중슬릿에서는 빛이 입자성과 파동성을 모두 띠기 때문에 간섭무늬가 띄엄띄엄 나타난다는 것을 깨달았습니다. 이를 통해 수학과 과학을 융합하는 경험을 할 수 있었던 것 같습니다."},{"q":"희망 진로는 무엇인가요?","a":"저는 세상과 소통하는 데이터 과학자가 되고 싶습니다. 제가 이러한 꿈을 갖게 된 것은 3학년 정보과제연구 시간에 데이터 시각화 활동을 진행하면서 우리의 사회에는 다양한 데이터들이 떠돌고 있지만 사람들이 이를 제대로 알지 못한다는 사실을 알고 사람들이 이러한 데이터에 대해 깨닫고 사회의 문제를 제대로 인식할 수 있도록 하는 것이 데이터 과학자의 역할이라고 생각하고 이러한 데이터 과학자가 되고자 했습니다."},{"q":"굳이 첨단융합학부에 오신 이유가 무엇인가요?","a":"컴퓨터 공학 분야를 희망하고 있긴 했지만 확실하게 진로를 정하진 못해서 이 학과에서 다양한 과목들을 심도있게 학습하며 자유로운 꿈의 공작소에서 제 꿈을 찾아나가고자 이 학과에 지원하게 되었습니다. 또한 요즘같은 대전환 시대에는 사회의 문제를 해결하기 위해서는 한 분야의 지식만이 아닌 다양한 분야의 지식을 가지고 있어야 한다고 생각했고 이 학과에서 이와 관련한 역량을 쌓을 수 있다고 생각하고 이 학과에 지원하게 되었습니다."},{"q":"우산대여서비스 시스템 구축 활동에 대해 자세히 설명해주세요.","a":"이 활동은 학생들이 비가 올 때 우산을 이용하지 못하는 불편함을 겪는 것을 보고 이를 해결하기 위해 진행하게 되었습니다. 이 활동에서는 웹사이트를 활용했기 때문에 웹사이트의 뼈대를 담당하는 html, 디자인을 담당하는 css 등을 활용하였습니다. 또한 학생들이 우산의 존재 여부를 쉽게 확인할 수 있도록 원으로 시각화하였고 대여한 학생들의 정보는 로그로써 확인할 수 있도록 하였습니다. 이를 통해 데이터 과학자가 되었을 때 해야할 일에 대해 생각해볼 수 있는 기회가 되었습니다."},{"q":"자료구조 과목을 수강한 이유가 무엇인가요?","a":"자료구조라는 것이 큐, 리스트와 같이 데이터를 저장하는 방식이나 데이터의 유형을 배우는 과목이라고 생각했습니다. 그래서 이를 배운다면 데이터를 다루는 데이터 과학자가 되었을 때 데이터를 더욱 효율적으로 저장하고 활용할 방식을 찾을 수 있게 될 것이라고 생각해 이 과목을 수강하였습니다."},{"q":"본인의 장단점이 무엇이라고 생각하시나요?","a":"저의 장점은 하나에 꽂히면 포기하지 않고 도전한다는 점입니다. 2학년 물리 시뮬레이션 구현 활동을 통해 키울 수 있었습니다. 이 활동에서 처음 계획했던 방향으로 진행하지 못하는 실패를 겪었지만 3학년 동아리 때 이를 발전시켜 완성하는 경험을 함으로써 이 역량을 키울 수 있었습니다. 반면에 저의 단점은 낯을 많이 가린다는 점입니다. 이는 사람들을 처음 만나면 말을 잘 못하고 긴장한다는 것입니다. 하지만 이는 사람들과의 관계에 신중하다는 점으로도 볼 수 있습니다."},{"q":"다양한 프로그래밍 언어를 학습하셨는데, 어떤 언어를 가장 선호하시나요?","a":"저는 파이썬을 가장 선호합니다. 왜냐하면 파이썬에는 단순히 프로그램을 만들수도 있지만 다양한 라이브러리가 있어서 수학, 과학 등 다양한 분야에 활용이 가능하다고 생각했기 때문입니다. 후배들을 위한 조언 면접 준비에 있어서 가장 중요한 것은 자신이 했던 활동을 정리하는 것과 자신이 지원한 학과에 대해 아는 것이라고 생각합니다. 일단은 생기부 기반 면접이기 때문에 생기부를 잘 분석해야 자신이 중점적으로 준비했던 질문이 아니더라도 자연스럽게 대답할 수 있을 것입니다. 그리고 지원학과에 대해 알아야 어떤 방향으로 준비할 것이고 대답할 것인지를 알 수 있기때문에 중요합니다. 마지막으로 면접이라는 상황을 겪어볼 기회가 별로 없기때문에 대학에서 진행하는 모의 면접이 있다면 꼭 참여하고 선생님과 많이 연습 해보는 걸 추천해 드립니다."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(2권)」","year":"2025학년도"},{"univ":"서울대학교","dept":"첨단융합학부","jeonhyeong":"학생부종합(지역균형전형처음에는 대강의실에서 모두 모여있다가 10분정도 간격으로 5명씩 번호를 부르면 다른 층으로 올라가서 면접 진행합니다. 교수님실에서 진)","method":"행했어요. 들어가기 전에 앞에 의자에서 무소음 헤드셋 끼고 있다가 벗고 들어가라 해서 들어갔습니다.공통질문 → 개별질문(생기부 질문: 조금 왜 첨단융합학부냐에 집중해서 질문하셨어요) → 마지막으로 하고 싶은 말 순서로 진행했어요.대강의실에서 본인확인 진행한 이후 전자기기와 가져오신 자료 모두","notes":"볼 수 없어요. 다른 학교는 전자기기 외에 자료는 볼 수 있는 경우가 많은데, 서울대의 경우 불가능하니 이 점 주의하세요.","qa":[{"q":"분야를 융합해서 성공시킨 사례에 대해 아는 것을 말해보세요.","a":"제가 학교생활 중 융합해서 했던 활동에 대해 말씀드려도 될까요? (네) 저는 2학년 자율활동 시간에 학급 특색활동으로 인공지능 수학 때 배운 추세선의 개념과 지구과학 시간에 배운 기후변화와 관련된 내용을 연관시켜 융합한 활동을 하였습니다. 기온 변화와 이산화탄소 농도 변화를 추세선으로 나타내고 이들 간에 양의 상관관계가 있다는 점을 분석하여 탐구를 진행했습니다. 친구들과 발표를 통해 다양한 분야에 대해서 알 수 있었던 시간이어서 의미있었다고 생각합니다."},{"q":"과학 연구를 하다보면 이미 있는 것에 반기를 들어야 하는 때가 있어요. 학교생활을 하던 중 본인이 원래 없었던 것이나 조금 원래 있던 질서에 반기를 들어서 변화시킨 사례가 있을까요?","a":"저는 1학년 때 학교에서 동아리 활동을 진행하며, 과학 실험 활동과 신약과 관련된 의학에 관한 활동을 함께 할 수 있는 동아리가 없는 점이 아쉬워서 개설하고자 하였습니다. 저와 뜻이 맞는 친구와 함께 회장, 부회장을 맡아 동아리를 개설하고 2년간 회장으로 활동하기도 하였습니다."},{"q":"우리 첨단융합학부에서 지원자를 뽑아야 하는 점에 대해 어필해보세요.","a":"제 가장 큰 점은 끝까지 파고드는 탐구력이라고 생각합니다. 면역항암제와 관련된 책을 읽으며 ○○에 대해 탐구하기도 하였습니다. 이처럼 저는 궁금한 점은 끝까지 알아내려고 하기 때문에 이 점이 첨단융합학부에 와서 연구하는데 긍정적으로 작용할 수 있다고 생각합니다."},{"q":"CAR-T 치료제에 관심이 많았나요?, CAR-T 치료제가 뭔지 설명해줄래요?","a":"CAR-T 치료제는 키메릭 항원 수용체라고 하는 CAR을 환자의 T세포에 주입하여 면역반응을 일으키는 치료제입니다. 이는 강한 면역반응을 불러일으킬 수 있고, 아직 연구중이기 때문에 환자에게 부작용이 있을 수 있는 위험성이 있지만, 그래도 아직 치료제가 없는 환자들에게 희망이 되어줄 수 있을 것이라 생각합니다. 따라서 단계적인 임상실험을 거친다면 아직 치료법이 없는 환자들에게 희망을 줄 수 있는 치료제가 될 수 있을 것이라 생각합니다."},{"q":"지원자가 진행했던 신약 개발과 관련된 탐구 중에 소개하고 싶은 것 있을까요?","a":"저는 CAR-T 치료제에 관심이 많았습니다. 그 중 관심이 생겨 ○○에 대해서 탐구하기도 하였습니다."},{"q":"화학Ⅱ시간에 미하엘리스 멘텐식에 대해 탐구했네요. 어떤 식인가요?","a":"이는 기질 양에 따른 효소와 기질 복합체 양을 알 수 있는 식으로, 이를 통해 반응속도를 알 수 있습니다. 또한, 크게 2가지를 알 수 있습니다. 첫째로, 기질 친화도인 Km 값이 작다면 기질 양에 관계없이 초기속도가 최대속도와 같습니다. 둘째로, 기질 양이 많다면 Km 값에 관계 없이 초기속도가 최대속도와 같습니다."},{"q":"신약개발에 어떻게 활용될 수 있나요?","a":"기질 양에 따른 반응속도를 알 수 있기 때문에, 신약개발을 할 때 어떤 기질을 얼만큼 활용했을 때 얼마나 빠른 반응속도가 일어날지 알 수 있어서 그런 점을 활용할 수 있을 것이라 생각합니다."},{"q":"왜 많은 과 중에 우리 첨단융합학부에 오고 싶나요?","a":"첨단융합학부는 5개의 다양한 과로 이루어져 있습니다. 지금은 제가 혁신신약에 관심이 있고 그 과로 진학하고 싶지만, 대학교에 입학해서 다양한 학문을 배우며 다른 분야에 관심이 생길 수도 있을 것이라 생각합니다. 또한, 서울대 첨단융합학부는 3학기동안 다양한 공통과목을 배우며 배우고 싶은 학문을 찾기 때문에 그 점이 매력적으로 다가왔습니다. 더불어, 첨단융합학부에서 다양한 분야의 훌륭하신 교수님들과 다양한 분야의 인재들과 함께 소통하며 성장해나갈 수 있다는 점이 매력적이기 때문에 지원하였습니다."},{"q":"시간이 얼마 없네요. 마지막으로 하고 싶은 말 해주세요.","a":"서울대 첨단융합학부는 다양한 분야의 교수님과 친구들과 함께 공부할 수 있다는 점이 매력적이었습니다. 이곳에서 성장해 나가고 싶습니다. 감사합니다.후배들을 위한 조언 첨단융합학부의 경우 왜 꼭 우리 학과여야 하는지, 왜 우리가 뽑아야 하는지, 그리고 융합에 얼마나 관심 있는지에 가장 초점을 두고 질문하셨습니다. 면접 준비하실 때 지균의 경우 생기부 기반이기 때문에 생기부를 잘 숙지하시는 것도 물론 중요하지만, 꼭 왜 이 과여야만 하는지, 내가 융합적인 것에 얼마나 관심 있는지를 잘 준비하시면 공통질문 나왔을 때 당황하지 않고 답변하실 수 있을 것이라 생각합니다."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(2권)」","year":"2025학년도"},{"univ":"서울대학교","dept":"첨단융합학부","jeonhyeong":"학생부종합(기회균형특별전형(사회통합)대기실에서 대기)","method":"(면접 순서에 따라 대기 시간이 3시간 이상 걸릴수도 있음. 한숨 자도 됨.)→ 이동 후 헤드셋끼면서 대기 → 공통 질문 3분→ (노트소리) → 생기부 질문 7분 → (노트소리) -> 퇴장","notes":"시간을 칼같이 지키기 때문에 명료하게 자신의 답변을 전달하는 연습을 해야함.","qa":[{"q":"1학년 2학기 때 반장으로 활동하면서 ‘최고의 실장’이라는 평가를 받았다고 하는데, 구체적으로 한 활동에 대해 설명해주시고, 실장으로서 갖춰야할 역량에 대해 말씀해주세요.","a":"저는 주로 학생들과 선생님의 의견 전달에 힘썼습니다. 학생들은 주로 자유로운 상황을 원하지만, 선생님은 학생들이 학교 규칙을 지킬 수 있도록 해야 하기 때문에 갈등 상황이 발생합니다. 이 상황에서 저는 학생들의 선생님의 생각을 전달하며 서로의 입장을 이해할 수 있돌고 도왔습니다. 따라서, 실장으로서 필요한 역량은 의사소통 역량이라고 생각합니다. 의사소통이 원활하게 이루어지면 서로 이해하고 타협하는 것이 가능하기 때문입니다."},{"q":"체육 한마당에서 앞장서서 활동했다고 쓰여 있는데, 이에 대해 설명해주세요.","a":"여학생들이 체육 활동에 참여하길 꺼려하는 분위기였기 때문에 실장이 체육 한마당 준비 과정에서 힘들어하는 모습을 보았습니다. 저는 이 상황을 해결하고자, 도전 정신을 가지고 잘 못하는 활동에도 참여했습니다. 또, 실력을 키우기 위해 유튜브 영상을 찾아보거나 아침마다 체력 운동을 하는 등 노력하였고 체육 한마당 대회에서 능력을 발휘할 수 있었습니다."},{"q":"생기부에 약물 오남용, 유전자 등 다양한 내용이 있는데 대학에 와서는 주로 뭘 공부하고 싶나요?","a":"첨단융합학부는 첨단기술과 생명 과학을 융합해 인류의 문제를 해결하는 학과입니다. 이 학과에서는 첨단기술을 이용해 정보를 분석하고 유용한 정보를 추출해 적용하는 학과라는 점에서 매력을 느꼈습니다. 저는 혁신 신약을 전공하며 유전자 치료제를 개발하고 싶습니다."},{"q":"지수함수로 코로나 확진자 수를 예측했다고 쓰여 있는데 이에 대해 설명해주세요. (이 내용을 조금 더 풀어서 질문하셨고 비슷하게 한번 더 반복해서 질문하셨음. 잘 이해하고 답변하기를 바란 것 같음.)","a":"고등학교 2학년 때 수학1에서 했던 활동을 말씀하시는 것 같습니다. (‘네, 맞아요.’라고 해주심.) 이 내용은 코로나 확진자 수가 기하급수적으로 증가하는 것을 보고 지수함수를 이용해 확진자 수를 예측할 수 있을 것이라는 호기심을 가지고 탐구를 진행했었습니다. 하지만 예측 과정에서 시위나 집단 모임으로 인해 예측에 오차가 많이 발생한다는 것을 발견했고 이 문제를 해결하기 위해 예방 수칙을 준수해야할 필요성에 대해 알게되었습니다."},{"q":"1/n과 1/n^2 급수의 수렴판정법에 대해 탐구했다고 적혀있는데 이에 대해 설명해주세요.","a":"이것은 p급수 판정법을 이용했습니다. an보다 크거나 같은 급수 bn이 수렴하면 급수an이 항상 수렴한다는 것입니다. 1/n과 1/n^2 수열 모두 수렴하지만 급수의 수렴에는 차이가 날 수 있다는 것에 호기심을 가지고 탐구를 진행했습니다. 1/n에서 1, 1/2, 1/3, 1/4 는 1, 1/2, 1/4, 1/4 보다 크지만 뒤에 말한 급수는 발산하므로 1/n 급수는 발산합니다. (고개를 끄덕여주심.) 1/n^2 수열은 .. (노크 소리가 들려서 바로 퇴장함.)후배들을 위한 조언 [준비 과정]관심 분야가 주로 생명과학이고 생기부 내용도 생명과학, 화학 위주였어서 이 과목을 중점으로 공부했지만, 지원한 학과가 첨단융합학부였기 때문인지 공통과목인 ‘수학’에 대한 질문이 많았습니다. 자신이 지원하는 학과의 특성을 고려하여 준비하는 것이 바람직할 것 같습니다.면접 준비를 하면서 답변을 쓰는 것보다는 자신의 생각을 쭉 기록한다는 느낌으로 작성해보고, 이후 다듬어가는 것이 좋습니다. 처음부터 간단명료한 답변을 작성하려고 하면 암기식으로 빠질 위험이 있습니다.과학 분야 위주가 아닌 행발 위주에서 질문하신 것을 보면, 준비해온 답변보다는 평소 지원자의 생각과 자연스러운 답변을 원하셨던 것 같습니다. 암기식 답변보다는 자신이 한 활동을 키워드 위주로 설명한다는 생각을 가지고 준비하면 좋겠습니다.우선 활동 별로 동기, 활동 내용, 결과에 대해 간략하게 정리하며 생기부 내용을 전반적으로 정리한 후, 꼼꼼하게 핵심 키워드 개념을 정리해 나가는 것이 효과적일 것입니다. 처음부터 지엽적으로 준비하려고 하면 생기부 내용을 다 보지 못하고 갈 수도 있습니다.자신이 준비하는 것도 중요하지만, 학교 선생님들과 많이 모의 면접을 진행해보는 것이 좋습니다. 담당 선생님이 아니시더라도 특정 과목에 대한 모의 면접을 부탁드리고 연습하면 훨씬 도움이 많이 됩니다.저는 평소 연습할 때 짧고 명료한 질문 위주로 모의 면접이 진행되었지만, 면접 당일에 질문 내용이 길고 한 번에 2개씩 질문하시는 것을 보며 당황을 많이 했습니다. 질문의 의도를 파악하고 자신이 말할 것을 생각으로 정리해서 말하는 연습이 필요합니다.[면접 당일]기회균형은 아침 일찍 시작했지만 면접 순서에 따라 대기 시간이 3시간 넘게 걸리기도 했습니다. 억지로 잠을 참기보다는 한숨 푹 자고 개운한 마음으로 면접봅니다!긴장하지 말고 자신이 준비한 것을 최대한 보여주겠다는 마음으로 면접에 임한다면 마음 부담이 줄어들 수 있습니다.긴장해서 멍때리지 말고 면접관의 질문에 최대한 집중해야 합니다.아무리 긴장했어도 ‘두괄식’으로 답변해야 한다는 것을 잊으면 안 됩니다. 면접관님들은 몇십 명의 지원자들을 상대해야 하기 때문에 피곤할 것이므로 두괄식으로 간단명료하게 답변한다면 면접에 유리할 것입니다,주저리주저리 설명하기보다는 핵심 키워드를 토대로 간단명료하게 답변해야 주어진 시간 안에 최대한 많은 답변을 할 수 있습니다."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(2권)」","year":"2025학년도"},{"univ":"서울대학교","dept":"첨단융합학부","jeonhyeong":"학생부종합(기회균형특별전형(사회통합))","method":"대기 → 공통 질문 → 개인 질문","notes":"첨단융합학부는 사람이 많아 대기 시간 매우 길 수도 있다.대기하면서 준비해 온 자료를 볼 수 없다.","qa":[{"q":"서로 다른 분야가 협업, 융합하여 이 세상의 난제를 해결한 사례를 하나 말씀해 주세요.","a":"죄송하지만 지금 당장 무엇인가 생각나지 않습니다. (공통 질문이 나올 거라 전혀 예상하지 못했어서 당황함.)"},{"q":"당장 생각이 나지 않을 수도 있으니, 나중에라도 생각난다면 말씀해 주세요.","a":""},{"q":"그렇다면, 이렇게 서로 다른 분야가 협업, 융합할 때 가장 필요하다고 생각되는 역량이 무엇인가요?","a":"저는 의사소통 능력이 가장 중요하다고 생각합니다. 서로 다른 분야가 협업할 때 서로의 분야에 대해 잘 모른다면 이를 배우고 알려주기 위해 의사소통이 필요합니다. 또한 협업을 하는 과정에서 각자의 의견을 제시하고, 의사를 결정할 때 의사소통을 필수적입니다. 따라서 협업, 융합에 있어서 의사소통 능력의 부재는 매우 큰 비용이 될 수밖에 없으며, 가장 기본적이면서도 가장 중요한 능력이 바로 이 의사소통 능력이라고 생각합니다."},{"q":"첨단융합학부에는 다양한 전공이 있는데, 본인의 가장 희망하는 전공은 무엇인가요?","a":"저는 인공지능, 데이터에 관심을 가지고 있는 사람입니다. 그리고 이러한 관심을 바탕으로 인공지능 개발자라는 꿈을 가지고 있습니다. 저의 이러한 관심 분야, 희망 진로에 관련된 지식과 기술을 배우고 싶기 때문에 저는 융합데이터과학전공을 희망합니다."},{"q":"네. 그렇다면 본인의 관심 분야인 인공지능, 데이터와 다른 분야가 협업, 융합하여 난제를 해결한 사례를 생각이 나셨다면 말씀해 주실 수 있나요?","a":"네 저는 알파폴드를 예시로 들고 싶습니다. 알파폴드란.. (공통 질문 시간 종료)"},{"q":"시간이 끝나서 개인 질문으로 넘어가도록 하겠습니다.<개인 질문>","a":""},{"q":"방금 알파폴드를 말씀해 주셨는데, 3학년 자율 활동에서 알파폴드를 활용하는 탐구를 진행하였다고 나와 있어요. 이 탐구를 진행하게 된 계기와, 구체적으로 어떤 탐구 활동을 하였는지 설명해 주세요.","a":"네. 저는 약학을 희망하는 친구와 함께 알파폴드를 활용하는 탐구 활동을 하였습니다. 알파폴드란 단백질 구조를 예측하는 AI인데, 이를 신약 개발에 활용할 수 있다고 하여서 약학을 희망하는 친구와 함께 이를 탐구해보는 활동을 기획하였습니다. 크게 두 가지의 활동을 하였는데, 첫 번째는 이미 구조를 알고 있는 단백질의 아미노산 서열을 알파폴드에 넣어서 예측된 구조를 실제 구조와 비교해 봄으로써 알파폴드의 예측 성능을 확인해보는 활동이었습니다. 두 번째는 아미노산 서열이 비슷한 두 단백질의 구조를 알파폴드를 통해 예측하고 그 구조를 비교해 보는 활동이었습니다. 이 활동을 통해 아미노산의 서열이 대체로 비슷하면 전체적인 구조도 비슷하지만, 세부적인 서열의 차이가 단백질 구조에도 세부적인 차이로 나타날 수 있음을 알게 되었습니다."},{"q":"3학년 때 고급 물리학을 수강하였는데, 수강하게 된 계기가 무엇인지, 가장 기억에 남는 내용은 무엇인지 말씀해 주세요.","a":"네. 저는 2학년 때 물리학, 화학, 생명과학, 지구과학을 모두 수강해 보았습니다. 물론 다 각자의 매력이 있었지만, 저는 특히 물리라는 과목이 매우 신비롭고 흥미롭다고 느껴졌습니다. 따라서 3학년 때 이를 더 심화하여 배워보고자 고급 물리학을 수강하게 되었습니다. 가장 기억에 남는 내용은 아인슈타인의 일반 상대성 이론입니다. 일반 상대성 이론은 중력을 시공간의 휘어짐으로 설명하는 이론입니다. 이것이 기억에 남는 이유는 비유클리드 기하학과 연결지어 생각해볼 수 있었기 때문입니다. 저는 3학년 때 기하라는 과목도 수강하였는데, 그때 평면이 아닌 휘어지거나 왜곡된 공간을 다루는 비유클리드 기하학에 대해 탐구해 보았었습니다. 아인슈타인의 상대성 이론에서 시공간의 휘어짐과 빛이 휘어져 진행하는 것도 비유클리드 기하학과 연결지어 생각해 볼 수 있었기 때문에 기억에 남습니다."},{"q":"본인이 삶에서 궁극적으로 이루고 싶은 꿈, 목표가 있을까요?","a":"네, 물론 꿈이 인공지능 개발자이기 때문에 일차적으로는 인공지능을 개발해 보고 싶습니다. 그러나 저는 이 인공지능이라는 것이 목표가 아니라 수단이라고 생각합니다. 즉 인공지능을 개발하는 것이 목표가 아니라 인공지능 개발을 통해 이루고 싶은 상위 목표가 있어야 한다는 뜻입니다. 그리고 저의 상위 목표는 인공지능 기술을 통해 우리 사회가 겪고 있는 다양한 사회 문제들을 해결하여 더 나은 사회를 만드는 것입니다. 이와 관련된 탐구 활동을 진행한 경험이 있는데, 소개해 드려도 될까요?"},{"q":"네. 간단하게 해주세요.","a":"네. 저는 3학년 진로 활동에서 우리 사회가 겪고 있는 가장 심각한 사회 문제 중 하나인 ‘저출산과 고령화’를 주제로 직접 데이터를 분석해 본 활동을 해보았습니다. 저출산, 고령화와 관련된 데이터인 인구수, 출산율, 65세 이상 인구수 등의 데이터를 직접 수집하고 이를 분석하여, 저출산과 고령화의 원인이 무엇인지 알아보고, 앞으로 이 문제 상황이 어떻게 진행될지 예측해 보고, 이를 바탕으로 이 문제를 해결하기 위한 해결 방안까지 제시해 보는 활동이었습니다."},{"q":"이 인공지능 기술이 우리 삶에 도움이 될 수도 있지만, 우리의 삶을 위협하는 기술이 될 수도 있습니다. 이에 대해 어떻게 생각하시나요?","a":"네. 저는 모든 기술에는 부작용이 따르기 마련이라고 생각합니다. 그러나 특히 이 인공지능 기술을 그 부작용에 대해 많이 다루어지지 않은 채 개발만 집중적으로 이루어지고 있는 것처럼 보입니다. 저는 이러한 인공지능의 부작용을 최소화하고 우리 삶이 위협받지 않을 수 있도록 국제적으로 인공지능의 개발 속도를 제한하거나, 적용 범위를 제한하는 등의 국제적, 규범적인 조치가 필요하다고 생각합니다. 또한 개인적으로도..(개인 질문 시간 종료)(면접관) 네. 시간이 끝나서 답변 여기까지만 듣도록 하겠습니다.후배들을 위한 조언 -자신감 가장 중요-어떤 질문이 나와도 자기가 원하는 방향으로 답변을 이끌어 나갈 수 있을 만큼의 준비와 생각이 필요-농어촌 애들은 별거 아님. 대기실에서 얼굴만 봐도 파악 가능 (자신감 가지라는 소리)"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(2권)」","year":"2025학년도"},{"univ":"서울대학교","dept":"첨단융합학부","jeonhyeong":"학생부종합(기회균형특별전형(사회통합))","method":"공통질문 → 공동교육과정 질문 →활동 질문, 꼬리 질문 → 학교에서 하고 싶은 것아무것도 못 보고 대기하는 시간이 체감 한 시간 정도로 길다. 그리고 올라가서 방에 들어가서 본다. 방이 생각보다 좁았다. 건물이 동떨어져 있어서 조금 올라야 한다. 10분이라 다들 엄청 촉박하고 급하게 진행하는 느낌을 많이 받았다. 답변을 끊기도 하신다. 교수님들이 많","notes":"으신데 두명씩 나눠서 한명씩 7조로 동시에 진행하신다. 생기부 열심히 보며 용어 정의, 개념, 원리 공부 많이 하는데 시간이 없어서 활동 위주로 물어보셔서 그런 개념 질문은 하나도 안 받았다. 인상들은 웃거나 끄덕이시거나 말투도 괜찮은 편이었다. 재학생들이 주신 쪽지에 교수님이 진짜 좋은 분들이라고 써있었다. 홈페이지에서 봤던 교수님들이 있으셨다.","qa":[{"q":"앉으세요. 먼저 공통 질문을 할게요. 융합적으로 우리 세상의 과학적, 사회적 난제를 해결하는 경우 뭐가 있을까요?","a":"의료 문제를 기술적으로 해결하기도 하고, 사회 범죄 문제를 빅데이터, 지오프로스와 같이 해결하기도 합니다."},{"q":"그럼 본인도 융합해서 해결한 경험이 있나요?","a":"네. 저는 태양광 발전량 증대라는 환경 문제를 해결하기 위해 여러 분야를 융합한 적이 있습니다. 저희 학교의 태양광 발전 설비가 기대발전량에 못 미친다는 사실을 알고 직접 청소를 해본 결과 가장 빠르고 확실한 방법은 먼지 청소라는 사실을 알게 되었습니다. 하지만 저는 실제 도입을 위해 현실적인 비용의 측면에서도 다시 생각을 해보았습니다. 인건비가 비싸서 오히려 비용이 많이 들 수 있다고 생각했습니다. 자가발전 저비용 로봇이 해결책이 될 것이라고 새로운 아이디어를 낼 수 있었습니다. 이 로봇을 실제로 제작할 때 고려한 점은 첫째로 비용이 적어야 한다는 점이었습니다. 그래서 로봇에도 패널을 부착해 자가발전이 가능하게 하였고 저렴한 아두이노를 이용해 큰 비용을 들이지 않아도 가능하다는 점을 보여주고 싶었습니다. 두 번째로 경사면이란 특성에 맞게 만들자는 것이었습니다. 따라서 여러 바퀴 중 가장 마찰력이 좋은 바퀴를 실험으로 골랐습니다. 셋째는 야외라는 점이었습니다. 실제로 새똥도 태양광 패널의 문제가 되고 있기 때문에 새똥을 허스키렌즈로 이미지인식해서 워터펌프에서 물을 분사하도록 설계했습니다. 그런데 로봇을 만들었을 때 움직임 불안정 문제가 발생했습니다. 저는 서로 다른 세가지 분야의 방법으로 해결했습니다. 첫째로 프로그래밍 측면에선 pid 제어를 추가해서 움직임을 개선하고자 했습니다. 회로 설계 측면에선 자이로 센서는 민감한 아날로그를 생성하기 때문에 노이즈가 측정 신호에 영향을 미칠 수 있고 모터 드라이버와 워터펌프는 고전류와 고주파 노이즈를 생성하기 때문에, 다른 회로에 영향을 미칠 수 있다고 판단하여 lc 필터를 설계하여 안정화시켰습니다. 그리고 실험적 장비 측면에서 바퀴를 교체하여 문제를 해결할 수 있었습니다. 또한 저는 이러한 태양광 발전량을 높이기 위한 방안들을 생각만 한 것이 아니라 실제로 도입하기 위해 행정기관에 잘 전달하는 것이 중요하다고 생각해서 관련 통계 데이터를 지도 위에 시각화하는 등 효과적인 주장과 설득 방식에도 집중했습니다. 이런 해결 과정이 특히 더 다각적인 시야의 중요성을 느끼게 되는 계기가 되었습니다."},{"q":"특이하게 디지털 논리회로랑 전자회로 공동교육과정을 수강했는데 뭘 배우고 했나요?","a":"이진 감산기, 가산기 같은 것도 배웠고 학교에 비화재보가 발생햇는데 학생들이 대피하지 않는 것을 보고 안전불감증의 원인이 비화재보일 것이라 판단하여 비화재보를 줄일 화재경보기 회로를 만들었습니다. 기존처럼 단일, 이중센서인 게 아니라 다중센서로 그 중 두 개가 충족되면 경보를 울리도록 했습니다."},{"q":"비화재보가 뭔가요? (정말 모르시는 눈치)","a":"화재가 발생하지 않았는데 경보를 울리는 것입니다."},{"q":"에어마우스를 만들었는데 과정을 자세히 설명해주세요.","a":"손목 질환 완화를 위해 인체생물학과 기계공학과 디자인을 융합하여 에어마우스를 만들었습니다. 학교에서 손목터널증후군과 드퀘르뱅 증후군이 있는 친구들이 마우스를 사용할 때 불편함을 호소하는 것을 듣고 제가 도움이 되고 싶었습니다. 저는 이때 아예 마우스를 다르게 제작해보자는 아이디어가 떠올랐습니다. 여기서 세가지를 중요하게 고려했습니다.첫째로 손목 질환이라는 인체의 문제를 공학과 융합해 해결하는 것입니다.  두 번째로 마우스는 고가의 기기가 아니기 때문에 저렴한 재료로 만들어야 하고 친구들이 실제로 사용할 수 있어야 한다는 현실적인 고려입니다. 따라서 아두이노로 저렴하게 만들었습니다. 세 번째로 창의적인 혁신성을 고려했습니다.이를 위해 융합적 사고는 필수적이었습니다. 손목 질환의 특성을 먼저 공부한 뒤 손목의 각도 조절이 중요하단 사실을 습득한 후, 보통 손목이 아픈 분들은 마우스의 형태가 세로로 긴 것을 많이 사용하는데 전 아예 각도가 자유롭도록 자이로스코프를 이용해 에어마우스로 제작하자는 발상을 떠올렸습니다. 그리고 질환 특성상 손목에 부담이 없어야 하므로 선 없는 블루투스 마우스로 만들자는 아이디어도 떠올렸습니다. 그리고 손목 부목으로 고정하는 것이 질환 완화에 도움이 되므로 대부분의 에어마우스들과는 다르게 웨어러블 손목보호대형 마우스로 디자인하여 새로운 차별점도 주었습니다. 일련의 과정에서..(끊김)"},{"q":"행정기관에 태양광 제안을.. 거절(약간 웃으심)당했다고 써있어요. 왜 거절당했다고 생각하고 두 번째 시도 때 어떻게 고치려고 했나요?","a":"네, 예산 문제로 거절 당했습니다. 이 행정기관이 예산이 그리 많지 않은 행정기관이라는 사실을 알게 되어 상급 행정기관과 각 학교들에 제안하기로 했습니다."},{"q":"그럼 예산 말고 로봇의 문제는 없었나요?","a":"저도 그것이 알고 싶었는데 답변 글에 예산 문제만 써있었습니다."},{"q":"연구를 하다보면 앞으로도 이런 문제가 많을 거에요. 대학에 와서는 이런 태양광 청소 로봇을 어떻게 개선하고 싶나요?","a":"네, 전 차세대반도체전공을 선택해서 로봇 장비의 소형화를 하고 싶습니다."},{"q":"로봇 소형화는 반도체랑은 연관이 없는 것 같은데요?","a":"아, 네. 맞습니다. 하지만 이런 로봇의 과하게 큰 부분들을 소형화 하고 싶습니다. 부품들을 최적화하고 싶습니다."},{"q":"그럼 와서는 정확히 뭘 하고 싶은 거에요?","a":"전 태양광에도 관심이 많지만 더 관심있는 분야가 있습니다. 바로 stt mram과 sot mram을 이용한 획기적인 ai칩 개발입니다."},{"q":"그럼 그 개발에 대해 설명하고 끝낼까요?","a":"네 stt mram은.."},{"q":"아니요. 개념 설명보다는 왜 중요하게 생각하는지를 설명해보세요.","a":"아, 넵. 인공지능은 점점 모든 곳으로 확장되고 있습니다, 점점 복잡하고 많은 계산이 필요해져서 빠르고 효율적인 ai칩이 필요합니다. 따라서 전 획기적인 ai칩을 개발하고 싶습니다. 들어주셔서 감사합니다.후배들을 위한 조언 개념도 중요하겠지만 자신이 했던 활동과 목표를 잘 숙고해보고 정리하는 게 중요하다고 생각합니다. 본인이 했던 활동을 잘 기억하는 게 중요한 것 같습니다. 저도 활동을 조리 있게 정리했다면 버벅대지 않고 더 제대로 답변할 수 있었을 것 같습니다. 그리고 면접관의 질문을 잘 경청해서 의도를 파악해야 합니다."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(2권)」","year":"2025학년도"},{"univ":"서울대학교","dept":"첨단융합학부","jeonhyeong":"학생부종합(지역균형전형)","method":"첨단융합학부 공통질문(최근 과학기술 융합 사례/왜 하필 첨단융합학부인지/융합적 소양을 보여준 사례) -> 생기부 질문 -> 하고 싶은 말(3분 정도 남았을 때)- 신설 학과라 그런지 전체적으로 학과 특수성과 “융합”을 엄청","notes":"중요하게 생각하시고 그와 관련된 질문이 정말 많았습니다.- 학문적으로 고등학교 교과 내용에서 넘어간 내용도 그 원리를 설명하기보다는 활용 사례, 왜 필요한지 등이 더 중심이었습니다.","qa":[{"q":"최근 과학기술 융합 사례/융합으로 난제를 해결한 사례","a":"노벨 화학상을 언급하며. AI기술을 통해 2억 개의 단백질 구조를 예측하는 데 공헌 + AI모델을 통해 단백질을 구성하는 아미노산에 대한 분석으로 복잡한 단백질 구조를 예측하는 난제를 해결했다고 설명 = 생명과학과 컴퓨터 과학의 융합 (첫 질문인데 동기나 자기소개가 아니라 난제를 해결한 융합적 사례를 이야기 해보라고 해서 조금 당황+엄청 조리 있게 잘 이야기하지 못했음)"},{"q":"왜 꼭 첨단융합학부여야 하는지? 자신들을 설득해 봐라.","a":"크게 삶의 목표가 두 가지가 있는데, 외재적인 삶의 목표는 컴퓨터 과학 분야에 대한 심도 있는 지식을 쌓아 사회를 위해 기여하는 것이고 내재적인 삶의 목표는 어려움을 극복하는 과정 자체를 즐기고 스스로 삶의 문제에 직면해 삶을 설계해나가는 위버멘쉬에 도달하는 것임/이러한 삶의 목표를 뚜렷하게 지님과 동시에 주도적으로 삶을 계획해 나가는 것을 즐기는 저에게 초학제적인 융합을 지향하고 평가에 얽매어있지 않은 첨단융합학부가 가장 적합하다고 생각 -> [꼬리질문] 그건 다른 학과에서도 가능하지 않나? (추상적이라고 생각하신 듯) -> 융합적 소양의 중요성을 언급하며 더 구체적으로 설명"},{"q":"고등학교 생활에서 융합적 소양을 보여준 사례","a":"수학축제를 언급하며 켈리 공식을 통한 주식 투자 게임을 직접 개발해 부스를 운영한 경험 설명/수학적 거부감을 해소한 성취가 있었고 경제학과 수학의 융합 설명"},{"q":"앞서 언급한 삶의 목표를 처음 갖게 된 동기는 무엇이며, 어떻게 유지해왔는가?","a":"책 두 권-데미안, 니체의 잠언집: 데미안에서 온실 속의 화초였던 싱클레어(주인공)가 데미안을 만나 주체적으로 삶을 살아가는 모습을 봄 + 니체의 잠언집에서 니체가 주장하는 이상적인 인간상인 위버멘쉬에 대해 처음 알게 됨. => 결국 인생에서 중요한 것은 경제적 이익이나 명예가 아닌, 뚜렷한 목적의식을 지니고 자신의 삶을 주체적으로 살아가는 것임을 처음 깨닫게 됨(그 전에는 단순히 안정된 삶에 대한 동경이 있었음) -> [꼬리 질문] 싱클레어가 주체적으로 삶을 살아갔다고 판단이 가능한가? -> 데미안과 헤어지기 전과 후를 비교하며 설명, 데미안과 함께했던 신학교 진학 전에는 싱클레어가 데미안에만 의존하며 문제를 해결해 나가는 모습을 보였지만, 진학 후에는 데미안 없이도 스스로 문제를 해결해 나가는 상황과, ‘결국 나 스스로가 데미안이 된 것 같았다.’와 같은 구절을 통해 이후에는 충분히 싱클레어가 주체적으로 삶을 살아가고 있다고 판단이 가능하다고 생각함. 학교생활을 하며 학교 활동에서 얻은 성취감과, 학교생활에서 깨달은 나눔의 가치가 원동력이 되었다고 설명"},{"q":"물리학2에서 맥스웰 방정식을 수학적으로 분석했는데 맥스웰 방정식이 무엇이고, 어떤 의미를 지니고 있는가?","a":"맥스웰 방정식을 통해 전자기파(매질 없이도 전기장과 자기장이 주기적으로 상호 변환되는 과정을 통해 전달됨)은 빛과 동일하다는 사실과 전기장과 자기장은 상호 변환이 가능하다는 사실을 밝혀냈음에 대해 구체적으로 설명 + 1~4가지의 법칙이 파동 방정식으로 이어졌음을 설명함. 학문적인 의미를 말씀드려도 될까요? -> 편한대로 하세요 -> 기존 시공간의 절대성을 견지하던 과학사적 관점에서, 광속의 불변성을 통해 시공간의 상대성으로 통념이 변화하게 되었으며 특수 상대성 이론이 등장하는 배경이 되었음을 설명"},{"q":"질문이 생각이 안 나고 답변만 기억이 납니다. 아래 질문과 연결되는 질문이었던 것 같기도 합니다.","a":"위상수학적으로 고차원의 데이터를 통해 기존 통계학적. 수식적 방법에서 벗어나 ‘데이터 모양’의 분석이 가능해짐 -> [꼬리 질문] 정확히 어떻게? 더 구체적으로 설명해 보세요. -> 베티 수, 지속 구간 다이어그램의 개념을 통해 10가지 요인으로 결정되는 10차원의 데이터를 차원을 낮추는 과정 없이도 10차원 그대로 분석이 가능하고, 이를 통해서 고차원의 데이터 ‘모양’을 직관적으로 분석하는 것이 가능해짐을 구체적으로 설명"},{"q":"생기부를 보면 수학을 굉장히 좋아하고, 또 잘하는 것 같은데 수학만으로는 모든 문제 해결이 불가능 하지 않나요?","a":"답변이 생각 안 납니다... 위 질문과 연결되는 질문이었던 것 같기도 합니다."},{"q":"마지막으로 하고 싶은 말(3분 정도 남았을 때)","a":"앞서 말씀드렸던 것처럼 저는 공학자로서 사회에 기여하고 싶으며, 삶을 주체적으로 살아 나가고 싶다는 뚜렷한 삶에 목표와 목적의식이 있는 학생입니다. 이러한 저의 잠재력을 첨단융합학부에서 펼치고, 더 나은 학생으로 성장하고 싶습니다! (얼마 안 남은 것 같아서 준비해 간 마지막 말 짧게 두 줄 정도로 줄여서 이야기)"},{"q":"시간이 조금 남았는데... 질문하다가 끊길 것 같지만, 위버멘쉬처럼 앞서 말한 삶의 목표는 고독할 텐데 어떻게 이를 지켜나갈 수 있을까? (원동력을 어디서 얻을 수 있을까?)","a":"질문하시다가 시간 종료(문 열림) -> 나중에 다시 더 들어보죠~후배들을 위한 조언"},{"q":"현장 분위기","a":"들어간 방에서 말이 조금 울리는 느낌이 있다.교수님과의 거리는 모의 면접과 거의 동일. 교수님 두 분 앞에는 책상이 있던 반면 학생은 아예 책상 없이 의자 하나만 있어서 앉고 일어날 때 태도나 말하는 내내 손, 발 산만하지 않게 의식하기생각보다 고민하는 시간 없이 쭉 말을 하다보면 10분이 꽤 짧게 느껴지고 끝남(너무 무언가를 ‘엄청’ 깊이 있게, 멋있게 말하려고 모든 걸 준비하겠다는 압박감은 없어도 될 듯+오히려 동기, 배운 점처럼 자신의 생각이 확고해야 떨리지 않고 말할 수 있다.)교수님 두 분 모두 압박 면접을 하고 계신다는 생각은 안 들었고 편안하게 다 말할 수 있는 분위기"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(2권)」","year":"2025학년도"},{"univ":"서울대학교","dept":"통계학과","jeonhyeong":"학생부종합(지역균형전형서울대 도착 후 자연과학대학 앞에서 오전 7시 40분에 입장-> 수험표, 신분증 확인 후 면접 대기실로 이동* 전자기기는 제공되는 봉투에 넣어서 각자 가방에 보관(크기가 큰 노트북 같은 전자기기는 봉투 별도 지급 X))","method":"* 면접 대기실 내에서 가방 및 기타 소지품 따로 걷지는 않지만, 자료 등소지품 일체 볼 수 없음-> 순서가 되면 소지품 전부 챙겨서 면접실 앞의 복도 의자에 앉아서 대기(유의사항 한 번 더 읽어보라 함)-> 감독관 분이 앞의 사람이 딱 10분이 되는 순간 문을 열어서 들어가라고안내해 주심.-> 10분 간 면접 실시 후 시간이 딱 되지마자 퇴실 및 귀가- 자연과학대학 앞에서 각 학과별로 선배들이 편지와 간식이 담긴 선물을 나누어 주셨음.- 면접 대기실 내에서 가져온 자료 및 소지품을 일체 꺼낼 수 없어 어떠한 공부도 할 수 없음.","notes":"- 화장실의 경우 입실 시간 전까지는 자유롭게 이동 가능하지만, 그 후부터는 남녀 각각 1명씩만 이동 가능한 점 참고(앞 사람이 다녀와야 그 다음 사람 이동하는 방식)- 면접의 경우 과거와는 달리 복도 앞의 감독관 분이 10분 타이머를 재고 타이머 종료와 동시에 면접이 마무리되며 다음 학생이 바로 입실하는 구조로 진행됨.","qa":[{"q":"(입실하여 앉자마자) 가장 인상 깊었던 수학 개념?","a":"가장 인상 깊었던 수학 개념은 고등학교 1학년 때 탐구했던 보간법이었습니다. 보간법이란, 알고 있는 값들을 바탕으로 모르는 값을 추청하는 개념으로, 평소에 관심이 있던 함수의 추론에 관련된 내용이었기에 선정하게 되었습니다. 보간법의 대표적인 종류로는 선형 보간법, 다항식 보간법, 라그랑주 보간법 등이 있는 것으로 추가적으로 알고 있습니다."},{"q":"선형 보간법과 다항식 보간법의 차이는?","a":"선형 보간법의 경우 양 끝 값의 데이터에서 일차원적 즉, 선형적인 방법을 이용하여 그 사이 값을 추정하는 방법이고, 다항식 보간법의 경우 선형적인 방법 대신 더 고차원 적으로 곡선을 이용하여 추정함으로써 정확도를 높일 수 있는 방법이라고 알고 있습니다."},{"q":"다항식 보간법이 곡선으로 추론하는 데 왜 더 정확도가 높은가?","a":"(선형적 방법보다 복잡한 데이터를 설명하는 데 적합하다고 생각한다고 발언 후)이 부분은 더 자세히 탐구한 후 말씀드리도록 하겠습니다."},{"q":"가장 좋아했던 수학 과목?","a":"저는 고등학교 전 과목 중에서 수학 과목을 가장 좋아했습니다. 하지만 그 중에서도 수학2 라는 과목을 가장 좋아했습니다. 그 이유는 수학2에서 처음으로 ‘미분’이라는 개념을 배우게 되었는데, 미분이란 어떤 함수나 운동의 순간적인 변화를 표현하는 방식으로, 종속변수의 아주 작은 변화율을 독립변수의 아주 작은 변화율로 나눈 값으로 구할 수 있습니다. 이 미분의 경우 여러 수학 개념이나 실생활에서 다양하게 활용되고 있다는 점이 흥미로웠기 때문에 수학2 과목을 선정하게 되었습니다."},{"q":"이항정리에 대해서 알고 있나?","a":"이항정리란 (a+b)의 n제곱을 a를 선택하는 횟수에 따라 b가 선택되는 횟수를 표현하여 나열하는 방식이라는 것으로 알고 있습니다."},{"q":"이항정리는 그 내용에 대한 것이 아니라, 전개에 관련된 것 아닌가?","a":"(이전 답변을 수정하여) 이항정리란 (a+b)의 n제곱을 의 일반항으로 가져 나열하는 공식으로 알고 있습니다."},{"q":"3학년 진로의 통계적 추론 활동?","a":"이 활동을 진행하게 된 동기는 2학년 지적호기심탐구에서 모집단에서 표본을 추출하는 표본 추출 과정에 대하여 탐구한 후 3학년 진로활동에서 추출된 표본에서 다시 원래의 모집단을 추론하는 과정인 통계적 추론에 대해서 궁금증을 갖게 되어 진행하게 되었습니다. 저는 모집단이 1개일 때 추정과 가설 검정을 중심으로 통계적 추론에 대해서 탐구해 본 후 모집단이 2개 혹은 그 이상일 때의 경우에서는 각각 t-test와 ANOVA(분산분석)이라는 통계기법을 이용하여 추가 탐구까지 진행하여 보았습니다."},{"q":"T 검정이란 무엇인가?","a":"T 검정의 경우에는 모집단이 2개일 때 그 2개의 모집단의 차이를 검정하는 방법입니다. 이 경우에 기각역을 결정하는 p-value의 값에 따라서 두 개의 모집단이 통계적으로 유의미한 차이가 존재하는 지 의사결정을 진행할 수 있습니다. 더 나아가 모집단이 3개 혹은 그 이상인 경우에는 ANOVA(분산분석)이라는 별도의 통계 기법을 사용해야 한다는 점까지 추가 탐구를 진행하였습니다."},{"q":"빈도주의와 베이즈주의에 대해서 알고 있나?","a":"빈도주의란 가상의 반복을 통해서 데이터의 빈도와 비율을 강조하는 분야이고, 베이즈주의란 사전확률 개념을 도입하여 사후확률이 사전확률에 비해 어떻게 변화했는지 파악하여 데이터를 분석하는 분야입니다."},{"q":"이 개념은 어디에서 알게 되었나?","a":"3학년 진로활동에서 통계적 추론에 대한 탐구에서 통계 철학에 대하여 추가 탐구를 진행하던 중 통계를 바라보는 두 가지 관점인 빈도주의와 베이즈주의에 대하여 알게 되었습니다."},{"q":"나중에 뭐하고 싶나?","a":"저는 4차 산업혁명 시대의 빅데이터 전문가로 성장하여 연구실에서 개발한 새로운 통계 방법론을 이용하여 비유클리드 데이터를 효과적으로 분석해냄으로써 사람들이 고차원 정보의 홍수 속에서 올바른 길을 찾을 수 있도록 도와주는 것이 제 궁극적인 목표입니다."},{"q":"가장 인상깊었던 책은?","a":"가장 인상깊었던 책은 “이공계생을 위한 확률과 통계”라는 도서였습니다. 이 책은 고등학교에서 가장 기억에 남는 활동이었던 3학년 진로활동의 “통계적 추론”에 대한 탐구의 길잡이가 되어준 책이었기에 선정하였습니다. 저는 이 책을 기반으로 추정과 가설검정을 중심으로 추출된 표본의 특성을 이용하여 모집단을 추론해 보고, 더 나아가 두 개 이상의 모집단을 대상으로 T-test와 ANOVA 분산분석에 대한 추가 심화 탐구를 진행할 수 있었습니다. 이 과정에서 이 책이 제시한 여러 가지 다양한 예제 문제들을 직접 풀어본 것이 정말 많은 도움이 되었기 때문에 가장 기억에 남는 도서로 선정하게 되었습니다."},{"q":"R 프로그래밍?","a":"여러 집단 간 차이를 분석하는 분산분석 기법에서 R Studio 프로그램을 이용하여 프로그래밍을 진행해 보았습니다. (10분 시간 끝나서 면접 종료)[면접관] 수고하셨습니다.후배들을 위한 조언 서울대 지균 면접의 경우 일반 면접보다도 1주일 후 진행되었고 오전 조가 많은 만큼 날씨가 생각보다 춥기 때문에 이에 대한 대비가 필요함면접 대기실에서 자료 등 기타 소지품을 일체 볼 수 없게 통제하기 때문에 보통 멍때리거나 잠을 자게 됨. 이 시간에 머릿속으로 무엇을 할지 미리 생각해 가는 것을 추천. 나는 지원동기, 마지막 할 말, 인상 깊었던 도서 등 예상 답변 머릿속으로 연습함.면접을 10분 단위로 정확하게 끊기 때문에 이에 당황하지 않기생기부 면접의 경우 질문에 대한 답변을 하고 내가 자신 있는 방향 및 분야로 이끌어가는 능력도 중요하다고 생각함 + 특히 서울대의 경우에는 꼬리 질문에 대한 대처가 가능하도록 깊이 있는 내용 탐구가 선행되어야 함."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(2권)」","year":"2025학년도"},{"univ":"서울대학교","dept":"항공우주공학과","jeonhyeong":"학생부종합(기회균형특별전형(사회통합)1. 입실 전 이른 시각이었음에도 재학생분들이 응원 나와 계심. 과 선배들이 노래 부르고 간식주고 응원해주심.2. 오전 반은 7시~8시 입실. 면접 대기실은 학교 교실 하나 정도 크기였음.3. 8시가 되자 한 명씩 이름을 불러 앞으로 나가고, 전자기기 반납하면서 면)","method":"접순서 확인함. 예정된 면접 시작 시각보다 10분 먼저 대기실에서 출발하고, 면접실 앞에서 조금 대기하다가 들어가는 구조였음.4. 8시~ 11시 25분(대기실에서 출발하는 시각)까지 생기부 등 자료 볼 수 없는 채로 대기5. 면접실 앞에서 10분 정도 대기6. 면접실 입실. 10분동안 교수님과 생기부 질의응답 진행. 면접 10분 중 2분 남을 때 밖에서 문 한 번 두드리고, 10분 되자마자 문을 열어 면접 끝냄.7. 개별퇴실미리 입실한 경우, 입실 완료 시각 전까지는 원칙적으로 들고 온 자료를 봐도 됨을 알고 있기. 필자의 경우, 7시 10분쯤 입실하자마자 진행요원이 책상에는 수험표, 안내사항종이, 필기구, 전자기기 빼고 모두 넣으라고 하심. 아직 8시가 안되어 생기부를 더 보고싶은데 못 보게 하는 건가 가만히 있었음. 주변에도 생기부 보는 사람이 없었음. 7시 40분쯤 한 학생이 '입실 완료시각","notes":"이 8시인데, 8시 전까지는 가져온 자료 봐도 될까요' 용기있게 물어봐서 남자요원이 고민하다가 허락함. 위와 비슷한 일을 겪게 된다면 고민하지 말고 손들어 물어보기.입실 완료 시각부터 본인의 면접 차례가 올 때까지는 들고 온 어떠한 자료도 볼 수 없는 듯함. 멍때리기보다는 머릿속으로 그간 준비한 내용들 떠오르는 대로 정리하기.","qa":[{"q":"일단 자기소개해주세요.","a":"안녕하십니까. 저는 항공우주공학을 너무 좋아하고 사랑해 본 과에 지원하게 된 사람입니다. 항공우주공학은 충돌, 제어 등 극한의 상황을 제어함으로 인간의 활동 반경을 우주까지 넓힌다는 점이 멋지다고 생각합니다. 항공우주공학이 좋아 고등학교 당시 선형대수, 제어공학, 추진과 관련한 마하다이아몬드 등을 관심가는 대로 공부해왔습니다. 재미있지만 쉽지만은 않았던 탐구 경험들은 항공우주공학을 좋아하는 제 마음을 더 심화시켰고, 본 과에 입학해 더 배워나가고 싶습니다. 나아가 저는 항공우주공학의 새로운 분야를 개척하는 연구를 하고 싶은 사람입니다. 로켓, 로켓 다음단계의 우주교통수단, 모든 우주교통수단이 조화를 이루는 우주교통체계를 개발하는 연구를 하여, 그들을 항공우주공학의 새로운 분야로 만들어나가고 싶습니다. 제 꿈을 이뤄나가는 과정에서 항공우주공학을 배우는 일이 반드시 필요하기에 본 과에 지원하였습니다."},{"q":"(왼쪽 김OO 교수님) 우주엘리베이터 만들고 싶고 CNT 관련 탐구도 했던데 우주엘리베이터 만들 수 있을 것 같아요?","a":"우주엘리베이터가 이론적으로는 굉장히 혁신적인 미래 우주교통수단의 한 종류라고 생각하지만, 소재 선택의 문제를 해결하기 전까지는 실현되기 어려우리라 생각합니다. 현재 우주엘리베이터 케이블의 소재로 가장 주목받는 CNT 조차도 케이블의 인장응력을 버티기에는 좋은 소재이나, 그것을 길게 엮어내는 기술이 부족해 우주엘리베이터가 실현되지 못하고 있습니다."},{"q":"(김OO 교수님) CNT 길게 엮는게 어럽다는게 구체적으로 무슨 말이에요? 더 자세히 설명해주세요.","a":"CNT가 굉장히 작은 길이 단위로만 만들어지지 못하고 있다고 알고 있습니다. CNT를 리본의 형태로 엮어나가야 CNT를 활용해 만드는 물체를 긴 길이까지 만들 수 있는데 그 기술이 부족하여 우주엘리베이터 케이블 제작도 어려움을 겪고 있다고 생각합니다."},{"q":"(김OO 교수님) 리본? 내가 알고 있는 거랑 좀 다르긴 한데요.(손동작을 하시면서) CNT는 이렇게 접합하는 기술 부족으로 아직 길게 못 만들고 있죠.","a":"(어찌 반응해야 할지 진짜 잠시 고민하다가 경청하기로 함) 아, 그렇군요."},{"q":"(김OO 교수님) 그러면 또 궁금한 게 있는데 공학일반 과목에서 광자추진이랑 메타물질 섞는 아이디어 냈는데 그 이야기 좀 들려주고 나를 설득해보세요.","a":"아~ 우선 메타물질이라 함은 음의 굴절률을 가질 수 있는 물질을 말합니다. (교수님이 이 얘기 듣고 갸우뚱하셔서 아차 싶었음.) 다시 말씀드리겠습니다! 메타물질이란 메타 원자라고 하는 아주 작은 인공 구조물을 모아놓은 신 물질인데, 다양한 광학적인 성질을 가질 수 있으며 음의 굴절률을 가지게 만들 수도 있는 것이 특징입니다. 제가 공학일반에서 냈던 아이디어는 음의 굴절률을 가지는 메타물질을 활용해 로켓에 빛이 입사하는 횟수를 늘리면 광자추진을 시킬 수 있겠다는 아이디어였습니다. 구체적으로는 메타물질과 거울을 순차적으로 배열한다면 빛이 메타물질을 통해 로켓에 재차 입사하게 되고, 결과적으로는 빛을 이용해 로켓을 의도한 방향으로 이동시키는 광자추진이 가능하리라 생각했습니다. (답변 후 김OO 교수님은 의아해하셨고 여OO 교수님은 고개를 격하게 끄덕이심. 무슨 상황인지 굉장히 의아했음.)"},{"q":"(김OO 교수님) 광자가 굉장히 작은 에너지를 가짐에도 물체를 운동시킬 수 있다는 말인가요? 광자추진처럼 빛을 이용해서 물체를 운동시키는 그런 사례 뭐가 있어요?","a":"우선 우주에는 마찰 등 외력에 의한 간섭이 적기에, 광자 충돌로 운동량을 얻는 과정이 장기적으로 봤을 때 로켓에 큰 운동량을 주는 효과적인 추진 방법입니다. 지구에서의 광자를 이용한 물체 이동 기술에 대해서는 아는 바가 없습니다."},{"q":"(김OO 교수님) 유전자가위 알아요? 그때도 광자로 원자를 이동시키거든요.","a":"아 그렇군요 ~ (또 한 번 어찌 반응해야 할지 고민하다가 말씀을 경청함.)"},{"q":"(김OO 교수님) 2학년 담임선생님이 써주신 생기부 보니까 칭찬이 가득해요. 절차탁마의 인재, 본인을 항공우주공학과에서 왜 뽑아야 하는지 본인 입으로 한 번 나를 설득해보세요.","a":"저를 뽑으셔야 하는 이유는 제가 '공학의 목적'을 정확히 인지하고 있기 때문입니다. 공학은 단순히 기술품을 만드는 학문이 아니며, 그것을 이용하는, 그것의 영향을 받는 사람을 위한 학문이라고 생각합니다. 이러한 공학의 존재 이유와 목적을 잘 알고 있기 때문에, 고등학교 때에도 단순히 혁신적인 우주엘리베이터를 설계하는 일에 그치지 않고 그것을 이용하는 우주인이 겪을 대사성질환에 대해, 또 그들이 느낄 불안을 해소하기 위한 내부 디자인에 대해서도 탐구해왔습니다. 저는 앞으로의 공부나 연구를 할 때에도 '사람'이나 '사회'에 대한 고민을 멈추지 않으며 공학의 목적을 잘 알고 실천하는 연구자가 될 것이며, 때문에 저를 뽑으셔야 합니다."},{"q":"(오른쪽 여OO 교수님) 그럼 이제 내가 질문해 볼게요. moving parts가 없는 스크램제트 엔진에 대해서 탐구했던데 이게 어떻게 작동하는 엔진인지 설명해줄래요?","a":"램제트나 스크램제트 엔진은 기본적으로 큰 속도, 즉 높은 마하수의 상황에서 이용할 수 있는 엔진입니다. 물리적인 압축기를 이용하는 터보엔진과 달리, 램제트/스크램제트 엔진은 충격파나 압축팬을 이용해서 공기를 압축하며, 그를 통해 초음속 상황에서 더욱 가속할 수 있습니다."},{"q":"(여OO 교수님) 구체적으로 충격파 어떻게? 더 자세히 설명해줘요.","a":"(조금 당황했지만 아는대로는 일단 다 말하기로 함) 충격파를 지난 공기는 마하파를 지난 공기보다 훨씬 고온 고압의 상태가 된다고 알고 있습니다. 이러한 충격파를 압축에 이용하는 엔진류 입니다. (좀 버벅거리고 있었음. 이후 질문에서 버퍼링걸린 나를 구해주심. 램제트가 normal shock 스크램제트가 oblique shock 이용한다는 차이라도 말할 걸.. 당시에 당황해서 못 말함.)"},{"q":"(여OO 교수님) 아 이거 우리 학교 2학년 때 다 배우긴 해요. 그래도 써있길래 물어봤어요. 그러면 브레이튼 사이클이랑 카르노사이클 차이가 뭐에요? 열역학적 사이클에 대해서도 잘 알고 있나 궁금해서.","a":"네 카르노사이클과 브레이튼 사이클의 가장 큰 차이는 '비가역과정'의 유무입니다. 브레이튼 사이클의 비가역과정이 야기하는 엔트로피 증가때문에 브레이튼 사이클의 열효율이 카르노 사이클을 못 따라가는 것이라 알고 있습니다. 램제트/스크램제트 엔진에서의 열역학적 공정은 유사 브레이튼 사이클을 따르며, 충격파를 이용하는 엔진의 특성상 큰 엔트로피 증가가 동반되는데, 그에 따른 열효율의 감소가 학계에서도 문제로 받아들여지고 있다고 알고 있습니다."},{"q":"(여OO 교수님) 네 그래요. 시간 얼마나 남았지? 오, 한 10초 남았네. 할 말 있어요? 있어도 할 시간 없을 것 같은데. (아주 조금 지나 바로 문 열림) 수고 많으셨습니다.","a":"감사합니다!후배들을 위한 조언 학과 홈페이지를 자주 들어가서 그런지 교수님들 얼굴이 눈에 익었고, 어떤 분야 전공하셨는지 & 어떤 lab 운영하시는지 면접장 들어가자마자 떠오르더라고요. 낯선 분들을 뵙는 느낌을 받는 것 보다는 이게 훨 나은 것 같으니, 여러분들께서도 원하는 대학교의 학과에서 뭘 배우는지 (교육과정), 어떤 분들이 교수님인지, 무슨 전공 하시는지 평소에 많이 알아두시길 바랍니다!교수님들이 어떤 전공이신지를 알고 봐서 그런지, 교수님들께서 본인 전공과 관련한 내용의 질문을 되게 심도있게 하신다고 느꼈습니다. 물론 주위 친구들에게 물어보면 전공내용보다 공통질문 위주로 나왔다는 친구도 많습니다. 저처럼 한 학과만 바라보고 생기부에서 전공내용을 깊이 팠던 친구들은 전공 지식도 심도있게 물어볼 수 있음을 알아두시고, 많이 공부해두세요! 정말 파이팅입니다!"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(2권)」","year":"2025학년도"},{"univ":"서울대학교","dept":"화학부","jeonhyeong":"학생부종합(지역균형전형1. 화학부 지원한 동기2. 질문1에서 답변 한 내용 중, 최근 연구 사례에 대해3. COF999 이름의 이유4. 학생부회장을 한 이유, 무얼 했는지, 함으로써 무엇을 얻었는지)","method":"5. 고급화학 수업을 어떻게 진행했는지6. 그 수업 속에서 어떤 것을 자발적으로 해냈는지7. 3년 동안 같은 동아리에서 활동했는데, 어떤 것을 중점적으로 하려고 노력했는지8. 교내 활동에서 탐구하면서, 어떤 자료를 위주로 탐구했는지9. 8번 답에 대한 추가 질문, 기억에 남는 논문이 있는지8. 마지막으로 하고 싶은 말저는 이번 면접 때 교통 때문에 애를 먹었습니다. 저는 사당역 주변에서 숙소를 잡고 아침에 택시를 타고 서울대로 가려고 했는데 전날 폭설로 인해서 안 그래도 혼잡한 교통이 더 혼잡했습니다. 그래서 가능하다면 학교 가는 길을 2-3개(택시, 지하철, 버스) 정도 알아놓고 가시면 좋겠습니다.저 같은 경우에는 대기실에 8:20까지 입실이었는데, 저는 도착해서 8:20까지 자료를 봐도 되는 줄 알고 일찍 가서 볼 생각이었습니다. 하지만 일단 저는 교통 문제로 인해서 8:10에 입실하였는데, 입실한 순","notes":"간부터 그 어떤 자료도 보지 못하게 하였습니다. 그래서 일찍 도착하셨는데 준비를 하고 싶으시다면, 화학부 면접 장소가 어디인지 확인하신 후에 뒤쪽으로 가면 카페가 있는데 거기서 조금 준비하시다가 면접장으로 가시는 것도 추천합니다.또한 면접장 가서 마음을 추스르고 안정을 찾는 시간도 생각보다 충분합니다. 8:20까지 입실한 후에 9:00까지는 무한대기입니다. 저보다 일찍 온 친구들 중에는 그 시간이 지루해서 엎드려서 잠을 자기도 했습니다. 또한 8:20 이후에는 화장실을 관리자분과 동행해서 가야 하니 화장실이 급하다면 8:20에 다녀오시는 것을 추천드립니다.","qa":[{"q":"우리 화학부에 왜 지원하셨나요?","a":"환경과 화학 관련된 책을 읽고, 환경에 있어서 화학의 중요성을 알게 되었습니다. 그리고 화학에 대해서 공부하다 보니, 환경을 위한 많은 연구가 진행되고 있고, 이러한 연구에 참여하고 싶다는 의지가 생겼습니다. 서울대 화학부에 입학해서 환경을 위해 연구하는 화학자가 되고 싶습니다."},{"q":"그럼 방금 말씀하신 환경을 위한 화학과 관련해서 진행되는 최근 연구 중에 알고 계신 것이 있나요?","a":"최근 연구 사례 중, COF999라는 물질에 대해서 알게 되어서 이에 대해서 알아본 경험이 있습니다. 이 물질이 공기 중에 퍼져있는 이산화탄소를 아주 효율적으로 포집한다는 연구자료를 접한 경험이 있습니다."},{"q":"방금 말하신 COF999가 왜 COF999라고 불리는 지 알아요?","a":"(답변이 조금 아쉬웠습니다. 저는 이 999라는 숫자에 집중을 해서 답변을 드렸는데, 다시 생각해보니 COF의 ‘C’에 대해서 물어보신 것 같았습니다.)네, 이를 연구하신 야마 교수님께서 이 물질이 공기 중의 이산화탄소를 포집할 수 있는 최고의 물질이라고, 이보다 더 나은 물질이 나오지 않을 거라고 하셔서 이렇게 이름을 지으셨다고 알고 있습니다."},{"q":"학생부회장을 했다고 써져 있는데, 왜 했는지, 어떤 활동을 했고, 어떤 걸 얻었나요?","a":"저는 제가 남들 앞에서 말을 잘 못하고, 많이 긴장해서 떨고, 얼굴이 붉어지는 것을 극복하고 싶었습니다. 이를 극복하기 위한 방법으로는 남들 앞에서 많이 서보는 것, 그리고 그들 앞에서 말하는 것을 연습해야 한다고 생각했습니다. 그래서 저는 전교부회장 선거에 출마했습니다. 감사히 당선이 되었고 교내축제, 학술제를 기획하였고 다양한 캠페인 활동을 진행하기도 하였습니다. 저는 학생부회장으로서 활동하면서 남들 앞에서 저의 의견을 근거의 의거해서 뚜렷하게 말하는 방법을 배웠습니다. 또한 제가 목표로 했던 다른 사람들 앞에서 떨지 않고, 긴장하지 않고 말하는 것도 늘었습니다. 결과적으로 이러한 경험들을 통해 오늘 이 면접 자리에서도 크게 떨지 않고 말할 수 있게 되었습니다.)"},{"q":"고급화학 수업은 어떤 식으로 진행되었나요?","a":"고급화학 수업은 선생님께서 학생들의 관심분야를 알아보신 후에 이에 맞게 수업을 구성하셨습니다. 저는 화학자가 되기 위해서 알고 있어야 하는 기초적인 학문적 지식에 대해서 알고 싶다고 말씀드려서, 선생님께서 무기화학, 유기화학에 대한 기초적인 수업도 진행해주셨습니다."},{"q":"그러면 학생은 이 수업에서 스스로, 자발적으로 한 것이 있나요?","a":"저는 이 수업에서 ‘방향족 화합물’에 대해서 배웠습니다. 수업 중에 배웠던 방향족 화합물은 공명구조를 가지고 있어서 매우 안정적이라 반응성이 낮다는 것을 알고, 저는 이 방향족 화합물을 어떻게 하면 반응성을 높여서 반응을 이루어지게 할 수 있는지에 대해서 알고 싶었습니다. 그래서 유기화학에서 친전자성방향족치환반응에 대해서 탐구를 진행했습니다."},{"q":"3년동안 한 동아리에 있었는데, 어떤 것을 중점적으로 하려고 했나요?","a":"저는 생명과학 동아리에서, 생명과학에서 연구하는 생체 반응들 속에서 화학반응들에 대해서 살펴보았습니다. 특히 체내 효소의 작용에 대해서 실험한 것이 가장 기억에 남았습니다. 이후에는 뭐라고 답했는지 정확하게 기억이 나지 않으나 아마 화학 관련해서 한 생명과학 실험에 대해서 답변했습니다."},{"q":"탐구하면서 어떤 자료들을 자주 사용했나요?","a":"저는 주로 신문기사, 칼럼, 그리고 논문들을 참조했습니다."},{"q":"혹시 기억나는 논문이 있나요?","a":"논문의 제목은 기억이 안 나지만, 굴의 껍질에 있는 효소를 통해 이산화탄소를 효율적으로 포집하는 것을 연구한 논문에 대해서 찾아본 적이 있습니다."},{"q":"마지막으로 하고 싶은 말이 있나요?","a":"연구하기를 좋아하고, 그 연구를 서울대에서 하고 싶습니다. (이런 의도로 답변함.)후배들을 위한 조언 면접은 생각보다 빠르게 끝납니다. 그 시간 속에서 자신의 관심사, 자신이 이 학과에 들어가겠다는 의지를 보여줘야 하기 때문에, 간절함을 보여야 합니다. 그 간절함은 자연스럽게 발현이 되니, 진심을 가지고 면접에 임하셨으면 좋겠습니다. 저는 첫 번째 순서라서 크게 자세한 질문을 못하신 것으로 보였는데, 뒷번호로 배정을 받으신다면 아마 조금 더 자세하게 질문을 하실 것 같습니다. 하지만 면접은 순서 상관없이 학생부를 처음부터 끝까지 머릿속에 넣으셔야 합니다. 특히, 저 같은 경우에는 화학과였기에, 교수님들께서 화학1, 화학2, 고급화학, 화학실험, 제조화학 과목들에 대해서 여쭤보셨습니다. 그래서 학생부의 중요도를 따지자면 ‘학과 관련 과목 -> 진로,자율,동아리 -> 행특 -> 교과세특’이라고 생각합니다. 너무 긴장하지 마시고, 편하게 면접을 보고 오는 것이 끝나도 마음이 편하니 너무 걱정하지 마시기 바랍니다. 간절함을 가지고 최선을 다하시면 꼭 좋은 결과가 있을 겁니다."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(2권)」","year":"2025학년도"},{"univ":"서울대학교","dept":"화학생물공학부","jeonhyeong":"학생부종합전형(지역균형전형)","method":"미적분 질문 → 인생의 목표 질문 → 과학과 철학 질문 → 전공 관련 질문 → 실험 탐구 내용 질문","notes":"책상 하나를 사이에 두고 가까운 거리에서 면접을 진행함.","qa":[{"q":"미적분 교과에서 분광광도계에 쓰이는 미분에 탐구했는데, 어떻게 미분이 사용되나요?","a":"1차 미분을 통해 흡광도 그래프의 피크 지점의 위치와 특징에 대해 알아내고, 2차 미분을 통해 피크의 폭과 밴드의 너비를 탐구하여 물질의 정량분석과 정성분석에서 이용합니다."},{"q":"학생의 인생의 목표는 무엇인가요?","a":"친환경 공정 전문가가 되어 인류의 지속가능한 발전에 기여하고 싶습니다. 환경 문제를 위해 친환경 플라스틱과 같은 친환경 제품들을 만들어내고 있습니다. 그러나 이러한 제품들의 공정 과정 속에서도 오염물질이 배출되어 환경 오염이 발생하고 있습니다. 따라서 공정 과정에서 발생하는 오염물질을 제거하거나 에너지로서 사용하는 연구를 하고싶습니다."},{"q":"과학에 있어서 철학이 필요한가요? 필요하다면 그 이유는 무엇인가요?","a":"과학에 있어서 철학은 필요하다고 생각합니다. 과학연구는 인류에게 해로운 결과를 초래할 수 있기에 과학이 발전함에 따라 윤리적 차원도 중요해집니다. 따라서 과학 연구의 결과가 사회에 미치는 영향을 고려하여 윤리적 기준을 형성하고, 공공의 이익을 위해 과학의 방향성을 제시하는 데에 철학이 필요합니다."},{"q":"탄소 포집 기술에 관해 탐구했는데, 이에 관해 설명해주세요","a":"탄소 포집 기술에는 3가지 방식이 있습니다. 첫 번째 방식으로는 연소 전 포집이 있습니다. 화석연료가 연소하기 전에 화석연료에서 탄소를 포집합니다. 두 번째 방식으로는 연소 후 포집이 있습니다. 공장과 산업 시설에서 화석연료가 연소한 뒤 발생하는 이산화탄소를 포집하고 에너지로 사용합니다. 세 번째 방식으로는 순산소 포집이 있습니다. 화석 연료를 순수한 산소와 부분산화시켜 이산화 탄소를 만들어내고 이산화탄소에서 산소를 분리하여 탄소를 포집합니다."},{"q":"포집한 이산화 탄소를 저장하는 방법이 있을까요?","a":"수산화 칼슘과 수산화 마그네슘을 이용하여 탄산염의 형태로 저장하는 방식이 있습니다. 수산화 칼슘과 마그네슘을 이산화탄소와 반응시켜 탄산 칼슘과 마그네슘을 만들어 낸뒤에, 고체의 형태로 저장할 수 있습니다."},{"q":"포집한 이산화 탄소를 이용하는 방법이 있을까요?","a":"철과 페놀의 하이드록시기가 포함된 촉매를 이용하여 고리열림반응을 촉진한뒤 이산화탄소와 에폭시를 반응시켜 고리형 카보네이트를 만들 수 있습니다. 고리형 카보네이트를 이용하여 고분자 화학 제품이나 콘크리트 등의 건축자재를 만들 수 있습니다."},{"q":"폴리페놀과 항산화 물질에 관해 실험을 했는데, 페놀의 구조가 어떻게 되나요?","a":"페놀은 벤젠 고리와 하이드록시기로 구성됩니다. 벤젠고리는 6개의 탄소원자가 수소와 결합하여 6각형 형태로 결합되어 있는 구조로, 전자의 비편재성으로 인해 전자가 탄소원자에 치우치지 않고 균일하게 분포되어 있어서 구조적인 안정성을 갖습니다."},{"q":"항산화의 원리는 무엇인가요?","a":"하이드록시기가 전자를 제공하는 역할을 하여 활성산소인 자유라디칼에게 전자를 주어 전자쌍을 이루게 합니다. 쌍을 이룬 전자로 인해 활성산소가 안정화되어 항산화 작용이 일어나게 됩니다. 하이드록시기가 전자를 하나 잃지만, 벤젠 고리의 구조적인 안정성으로 인해 반응성이 적어 안정화됩니다."},{"q":"그래핀 실험이 무엇이고 어떤 것을 얻었나요?","a":"그래핀이 신소재로서 다양한 능력을 가지고 있다는 것을 접한뒤 그래핀의 능력에 대해 알아보기 위해 산화 그래핀을 섬유에 코팅한 그래핀 필터를 제작하여 두가지 실험을 진행했습니다. 미니 청소기 앞에 섬유 필터를 달아 먼지 흡착력을 알아보는 실험과 흙탕물을 여과하여 여과능력을 알아보는 실험을 했습니다. 그래핀의 코팅 횟수가 늘어남에 따라 먼지 흡착력과 여과능력이 증가하는 비례관계를 발견하게 되었고 그래핀의 활용성에 대해 알아볼 수 있었습니다.후배들을 위한 조언 입실하는 순간부터 자료를 보지 못하여 긴시간 대기하는 동안 지루할 수 있지만 공부했던 내용을 복기하며 차분하게 대기하는 것이 좋습니다. 책상 하나를 두고 바로 앞에서 면접을 하니 평소 연습 할 때에도 편안한 마음으로 이야기 하듯 연습하는 방식으로 진행하는게 좋을 것 같습니다. 또한 꼬리질문이 집요하게 따라오는 경우가 있기 때문에 자신의 생기부에 내용에 대해 평소 공부했던 것보다 좀 더 깊게 공부할 필요가 있습니다."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(2권)」","year":"2025학년도"},{"univ":"서울대학교","dept":"건축학과","jeonhyeong":"학생부종합(일반전형1. 대기실 입장 후 순번 확인(1~5조에서 1~10번의 순번이 존재))","method":"2. 문제 풀이실 이동 → 문제 풀이(45분)3. 면접장 이동 → 면접(15분)자신의 출신학교 등의 신분을 밝히지 않아야 하므로 교복을 입거나,","notes":"이름을 말하는 행위를 하지 않도록 주의해야 합니다. (발언 금지 사항을 참고 해야함)","qa":[{"q":"<제시문 1~3번> 숫자가 적혀있는 공 P Q R을 수직선에 올려놓고 규칙에 따라 좌표와 숫자를 바꾸는 문제","a":"제시된 규칙에 따라 좌표를 구하는 식, 숫자를 구하는 식을 일반화 하여 여러번 계산하고, 이를 통해 귀납적으로 규칙성을 찾는 방법을 사용함. 계속해서 유지되는 값과 규칙적으로 변하는 식을 통해 최종적인 항을 구하는 방법을 이용함."},{"q":"<제시문 4~7번> 자동차 A B C를 속도,연료에 대한 규칙에 따라 움직여 이동거리를 비교하는 문제","a":"문제에서 제시된 규칙을 따라 구간을 나눠서 계산을 하였으며, 최댓값에 주목해 이차함수에 대한 식으로 유도하여 꼭짓점을 이용함. 이를 통해 한 문자로 정리하여 계산함.후배들을 위한 조언"},{"q":"면접 준비:저는 10월~11월 면접 전 까지 약 1달 반 정도를 면접 준비를 하였습니다. 제가 면접 준비를 위해 이용한 방법으로는 1. 기출 문제, 2. 학교 선생님과 모의면접,피드백, 3. 교육청 모의면접 프로그램입니다. 10월 달의 경우 기출문제는 최근 1개년만 풀고 주로 교육청 모의면접 프로그램에 참여해 제시문 면접의 성격을 이해하는데 초점을 맞추었습니다. 모의 면접을 통해 문제의 형식, 면접 진행 과정, 말하는 방식 등을 익혔습니다. 그 후 11월에 수능 이후 1주일 동안 최근 4~5개년 치의 기출문제를 풀이 한 후 선생님과 피드백을 하는 방식으로 준비하였습니다. 문제의 경우 하루에 1개년씩 공과대학, 인문대학, 수학교육과 문제를 모두 풀고, 일부를 모의면접 하는 방식으로 진행했습니다. 제가 생각하기에 너무 일찍부터 준비할 필요는 없고, 기출문제만으로도 충분히 대비가 가능하다고 생각합니다. 또한 단순히 문제를 잘 푸는 것 보단 푼 문제에 대해 핵심적인 부분을 추출해 설명하는 능력을 키우는 것이 더 중요하다고 생각합니다.","a":""},{"q":"서울대 면접은 오전 이른시간부터 진행됩니다. 또한 사람이 많이 몰리고 학교가 넓으므로 생각보다 더 일찍 출발해야 늦지 않을 수 있습니다.","a":""},{"q":"학과마다 진행방식이 다를 수 있습니다. 제시문 면접에 사용되는 문제와 면접 시간등은 같지만, 세부적인 부분에서 다를 수 있습니다. 같이 면접에 다녀온 친구들과 비교했을 때 대기시간에 자습을 허용하지 않는 곳도 있으며 면접 시에 채점결과를 알려주는 곳도 있는 등 진행방식이 다양합니다.","a":""}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(2권)」","year":"2025학년도"},{"univ":"서울대학교","dept":"식물생산과학부","jeonhyeong":"학생부종합(일반전형① 면접관은 2분이셨고, 친절하셨습니다.② 질문지에 대한 답변 작성(45분) ⇨ 교수님 앞에서 답변(15분)(15분씩 나누어서 답변을 3명씩 작성하게 되어 있어요.))","method":"3명 중 한 명이 45분이 지나면 그 학생은 면접을 보러가고,새로운 한 명이 답변을 작성하러 들어오는 식으로요.③ 문제지와 답변지를 가지고 가서 구술로 면접을 보고, 나올 때 두 가지 모두 제출하고 나와야 합니다.④ 필요하다면 뒤에 칠판과 보드마카를 활용해 설명할 수 있는 형식의 면접이었어요!)45분의 시간은 생각보다 굉장히 짧게 느껴졌습니다. 한 문제당 딸린 문제들이 많기에 절대 여유를 가지지 말고, 연습지에 최대한 간략하고 정확하게 쓰길 바라요. 또한 답변 시간도 생각보다 짧습니다. 만약 자신이 다 풀지 못한","notes":"문제가 있다고 해도 최대한 침착하게 풀었던 문제 중심으로 설명하세요. 긴장할 필요 없습니다!!면접 시간이 오전이었기에 차가 많이 막혀 버스를 추천합니다.또한 주변에 편의점이나 쉴 곳이 없습니다. 아침은 미리 먹고, 핫팩 등 몸을 녹일 것을 챙겨오시기를 바랍니다.","qa":[{"q":"긴장하지 말고, 푼 문제들을 설명해주세요.","a":"문제가 크게 두 문제가 있었기에 제시문을 읽고 제가 분석한 대로 먼저 요약해서 말씀드리고, 이후 그 제시문에 딸린 문제들을 차례대로 말씀드렸습니다.1번 문제는 이런 문제였습니다. 먼저 1-1번 설명드리겠습니다. 저는 이 문제에 대해 이렇게 생각하였고, 이러한 이유 때문에 이렇다고 생각하였습니다.[정리] 마지막 문제까지 답변하자마자 15분이 끝나 바로 나왔습니다. 서울대학교는 공정성 때문에 15분 이후 추가적인 질문이나 답변은 허용되지 않습니다. (사실 제시문은 자신이 그 자리에서 풀고 답변드리는 거라 답변 내용을 써 놓는 것은 큰 의미가 없다고 생각합니다. 그러나 문제에서 묻고자 하는 개념에 집중하여, 개념과 관련되어 본인이 이것을 안다는 것을 어필하려면 관련 키워드를 답변에 넣어서, 또는 비유 등을 이용해 답변한다면 좋은 답변이 되리라 생각합니다. 또한, 풀었는데 못 말씀드리고 나오면 교수님들은 우리가 못 풀었다고 생각하실 것입니다. 모두에게 어려운 면접이므로 당당한 태도와 논리적인 설명, 시간 분배가 정말 중요한 면접이라고 생각합니다.)후배들을 위한 조언 기출들을 한 번씩 보고, 저는 모의 면접에서 주셨던 제시문 면접 워크북이 정말 큰 도움이 되었습니다. 도교육청에서 하는 모의 면접을 신청하여 틈틈이 대비한다면 좋은 결과를 얻을 수 있으리라 생각합니다. 또한, 생명과학Ⅱ가 주된 내용입니다. 저 또한 생명과학Ⅱ를 면접 일주일 전부터 공부했습니다. 너무 걱정하지 말고, 열심히 하면 좋은 결과가 있을 테니 생명과학Ⅰ, 생명과학Ⅱ를 공부하고 말로 설명하는 연습을 반복하길 바랍니다. 파이팅!"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(2권)」","year":"2025학년도"},{"univ":"서울대학교","dept":"식품·동물생명공학부","jeonhyeong":"학생부종합(일반전형식물생산과학부, 식품·동물생명공학부 오전 3조 학생들이 하나의 면접대기실에서 대기→ 입실 마감(오전 8:00) 이후 배부되는 봉투에 가방을 비롯한 모든 소지품 보관)","method":"→ 답변준비실로 이동(번호 순, 15분 간격)답변준비실 앞에서 잠시 대기했다가 입실 → 45분간 문제 풀이 → 면접실 앞에서 잠시 대기 → 입실하여 15분 간 면접 진행면접실 퇴실 이후 문제지와 답변지 반납 → 봉투에 보관했던 소지품 돌려받고 퇴장.-당일에도 공부할 수 있는 시간이 있으니 공부할 자료를 챙겨갈 것.-면접실에 입고 들어갈 옷을 제외한 겉옷도 봉투에 보관하니 옷 따뜻","notes":"하게 입을 것.-답변준비실에서 개인별 타이머를 제공함.-면접실에서 칠판 사용이 어려웠음.","qa":[{"q":"문제 양이 많으니 중간에 질문은 하지 않을 것이고, 답변만 빠르게 듣겠다. 화학과 생명과학 중 어떤 것을 먼저 답변하겠는가?","a":"화학 먼저 하겠다. (화학 풀이 이후 생명과학 풀이)"},{"q":"1-2 문항에서 ~~ 이 부분을 고려하지 않은 것 같은데, 이 상황에서 ~~을 고려한다면 어떻게 될 것 같은가?","a":"(기존 답변에서 질문 내용을 추가해서 답변)"},{"q":"여기서 불가사리가 최상위 포식자이다. 이렇게 풀이한 게 맞는가?","a":"제시된 자료를 ~~ 이렇게 착각하고 풀이한 것 같다.(생명과학 문항에 대한 질의응답이 있었는데 제대로 기억나지 않음)"},{"q":"시간이 2분 정도 남았다. 생명과학 마지막 문항을 시간 부족으로 풀지 못했다고 했는데, 이는 연체동물과 절지동물 ~~을 계통수와 관련해서 설명하는 문항이다. 지금 풀어보겠는가?","a":"알겠다. (잠깐 생각하는 시간을 가진 후) ~~ 이러한 이유로 연체동물과 절지동물에서는 공통점이 더 많이 나타날 것이다.(바깥에서 문을 두 번 두드림.)"},{"q":"선구동물과 후구동물이 뭔지 설명해보겠는가?","a":"(원구가 생각나지 않음) 먼저 들어가는 부분이 입이 되고 나중에 항문이 생기는 동물을 선구동물, 먼저 들어가는 부분이 항문이 되고 나중에 입이 생기는 동물을 후구동물이라고 합니다."},{"q":"먼저 들어가는 부분을 뭐라고 부르는지 아는가?","a":"지금 그 단어가 기억나지 않는다."},{"q":"수고했다. 퇴실해라.후배들을 위한 조언","a":"문제 풀이할 때 긴장하지 말 것. 제시문 같은 경우에는 문제가 유기적으로 연결되는 경우가많기 때문에, 첫 번째 문항이 머리에 제대로 안 들어오면 뒷 문항도 못 풀게 될 가능성이 매우 높다.답변지 작성할 때 최대한 깔끔하게 할 것. 문제지에 적는 것이 금지되기 때문에 모든 풀이를 답변지를 이용해서 해야 한다. 그렇기 때문에 풀이 과정과 답변 내용을 잘 구별할 수 있게 작성하는 것이 중요하다. (답변할 때 내가 쓴 글씨를 찾느라 헤맬 수 있음.)큰 목소리로 또박또박 말할 것. 기본 중의 기본이지만 면접 당일, 내 풀이에 자신이 없으면 목소리가 작아지게 될 것이다. 풀이가 틀리더라도 내가 왜 그렇게 생각했는지, 그 이유는 잘 전달하겠다는 마음을 갖고 자신감 있게 말해야 한다."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(2권)」","year":"2025학년도"},{"univ":"서울대학교","dept":"재료공학부","jeonhyeong":"학생부종합(일반전형)","method":"면접대기실 → 신분확인 & 면접번호 배부 → 대기 → 문항풀이실(45분) → 면접실(15분)","notes":"대기 중에는 참고자료 챙겨와도 볼 수 없으니 미리 다 보고 오세요.(참고로 대기시간동안 보통 자거나 멍 때립니다.)","qa":[{"q":"다른 문제는 못 푼건가요?","a":"네. 1-2번은 x_2024의 값은 구하지 못했지만, x_n과 x_n+1간의 관계식이 x_n+1 = (1-h)x_n +2 라는 것을 구했습니다."},{"q":"답 맞히는게 중요하니까, 2-1 다시 한 번 풀어볼래요?","a":"네! [ ] 이라고 생각합니다."},{"q":"계산 실수한 것 같은데, 다시 확인해볼래요?","a":"(아무리 계산해도 똑같이 나와서 계속 풂.)"},{"q":"답이 [ ]인데, 이걸로 2-2 풀어보세요.","a":"네. 2-2답은 [ ] 라고 생각합니다."},{"q":"2-3 풀어보세요.","a":"2-3에서는 1, 2번과 달리 연료가 제한된 상황이라는 점에 주목했습니다. 따라서 정비시간과 그 후에 연료 소모 속도를 고려해 [ ]라는 식을 도출할 수 있었습니다. 이 r에 대한 3차 방정식에서 미분을 통해 그래프를 도출해 답을 구하고자 했으나 이 과정에서 어려움을 겪어 답을 구하지 못했습니다. 혹시 방향성이 잘못된 걸까요?"},{"q":"(정답지 보시면서) 연립부등식을 활용하는 건데.","a":"(계속 풀다가) 1-2번 다시 풀어봐도 될까요?"},{"q":"그래요. 답을 맞히는 게 중요하니까.","a":"1-2을 풀기 위해 제시문에 주어진 x가 정의되는 방식을 통해 [ ]라는 식을 도출했습니다. 이후 x_n+1과 x_n의 관계식을 도출하기 위해 식을 정리해 x_n+1 = (1-h)x_n +2 것을 구할 수 있었습니다. 이후 x_1=[ ]라는 점과 x_2=[ ]라는 점을 참고해 x_2024를 구하고자 했습니다. 이를 위해 관계식에 집중했으나 구하지 못했습니다. 혹시 x_1과 x_2를 활용하는 것이 맞나요?"},{"q":"(정답지 보시면서) 뭐 답 구하려면 활용하긴 해야겠죠?","a":"네! 다시 풀어보겠습니다. (계속 풂.) 혹시 x_n+1과 x_n의 관계식이 x_n+1 = (1-h)x_n +2이 맞나요?"},{"q":"(고민하시다가) 그건 알려줄 수 없죠ㅎㅎ","a":"네..(계속풀기)"},{"q":"시간 끝났습니다.","a":"감사합니다.*[ ] = 기억 안 나는 수치후배들을 위한 조언 수학 제시문은 확실히 답을 맞히는 것이 중요한 것 같음. 서울대 기출뿐만 아니라 다양한 수학 제시문을, 1차가 나오기 전부터 꾸준히 계속 준비하길."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(2권)」","year":"2025학년도"},{"univ":"서울대학교","dept":"전기·정보공학부","jeonhyeong":"학생부종합(일반전형7시 30분까지 지정된 장소로 입실하고 기다리면 교실 내 감독관이 수험번호를 호명한다.)","method":"호명하면 감독관에게 가서 면접번호를 받는다.(나는 A287이었다.)자신의 면접번호에 해당하는 면접 준비 시작 시간과 면접 시간을 확인한다. 해당 시간에 감독관이 같은 시간에 보는 면접자들을 줄 세워 대기시킨다.이후에 감독관을 따라 면접 준비실에 들어가서 제시문을 45분간 푼다. 45분 뒤 다시 도열하여 면접실로 이동하여 한 명씩 각 방으로 들어가서 면접을 본다.","notes":"6시 30분부터 건물 입구를 개방한다. 화장실은 대기하는 교실에서밖에 못 간다. 면접 준비 시간은 빠르면 8시 30분, 늦으면 1시이다.","qa":[{"q":"공 P, Q, R이 각각 1, 2, 3의 위치에 놓여 있다. P, Q, R에는 각각 3, 2, 1의 숫자가 쓰여있다. xn, yn, zn은 각각 P, Q, R의 공에 쓰여진 숫자를 뜻하고 pn, qn, rn은 각각 P, Q, R의 위치를 뜻한다. h에 대해서 xn+1은 평균에서 xn을 빼고 h를 곱한 후 xn을 더한다. yn+1, zn+1도 구하는 방법은 xn+1과 동일하다. pn, qn, rn은 ~~~ (기억이 잘 안 납니다....) 1-1. 2번 시행한 후 공의 평균을 구하시오.1-2. x2024를 h에 대해 나타내시오.1-3. r2024≤q2024 ≤p2024를 만족시키는 h의 값을 구하시오.","a":""},{"q":"원점에 자동차 A, B, C가 있다. A는 t초 동안 t만큼 움직이며 s만큼 움직일 때 연료를 4s 소비한다. B와 C는 –1의 속도로 10초 동안 이동한 후 정지하여 각각 rB, rC초 동안 정비한다. 이후 각각 2+rB, 2+2rC의 속도로 움직인다. B와 C는 –10까지 s 이동할 때 연료를 4s만큼 소비하고 정비 후에는 s 이동할 때 연료를 s만큼 소비한다.2-1. (t0≥12) B의 위치의 최댓값을 t0에 대해서 구하시오.2-2. B의 위치가 A의 위치보다 클 때의 t 범위를 구하시오.2-3. 연료가 K(K≥60)만큼 있을 때 B의 위치 최댓값을 구하시오.2-4. B와 C에 각각 연료가 60만큼 있고 추가로 연료통에 51만큼의 연료가 있다. 연료 51을 어떻게 분배해야 B와 C의 위치의 합이 최대가 되는지와 최댓값을 구하시오.(기억이 나는 대로 적어보긴 했는데 문제는 글로 장황하게 나열되어 있어서 제가 적은 것보다 더 이해하기 어려웠습니다.)","a":"1-1. 3번 시행까지 직접 해 보았고 따라서 평균이 2인 것을 알았습니다. 또한 평균이 항상 2라는 것을 귀납적으로 알 수 있습니다.1-2. (h-3)(h2022-1)?(이렇게 말한 것 같은데... 기억이 잘...) [면접관] 잘못 구했는데 어떻게 구했는지 알 수 있을까?xn+1과 xn의 관계식을 제시하고 내가 쓴 식을 보다가 부호를 잘못 적은 것을 발견했다.그래서 ‘부호를 잘못 적은 것 같습니다.’ 라고 말했다.[면접관] 그래? 그럼 관계식을 이용해서 지금 구해볼래?지금 머리가 안돌아가서 잘 모르겠습니다.(근데 진짜 몰랐음)1-3. 답변 못 함.2-1.  (이건 맞췄는데 기억이 안납니다.) rB와 t0의 관계식을 이용하여 rB에 대한이차방정식에 대입했습니다.2-2. 4<y<16[면접관] 잘못 구한 것 같은데. 우선 사잇값이 아니야. 왜 그렇게 구했는지 설명해봐.2-1번 식을 이용해서 구했다고 설명하다가 –10을 안 한 것을 알아채서 말씀드리고 사잇값이 아닌 것도 말씀드렸다.[면접관] 그러면 지금 다시 구해보세요.이차부등식의 근을 구했더니  or 가 나왔다.[면접관] 여기서 두 범위 다 가능해요?(여기서 이차부등식 잘못 푼 줄 알고 2로 나눠버렸다.)[면접관] ??다시 2를 곱함. (이러면 안됐는데 정신이 없었다.) [면접관] 그래서 두 범위 다 가능합니까? 만 가능한 것 같습니다.[면접관] 왜요?B가 10초 동안에 –방향으로 움직이고 A는 +방향으로 움직이는데 일 때는 10초보다 작아서 불가능합니다.[면접관] 아닌데요? 다시 생각해보세요. (근데 내가 말한 것도 생각해보면 맞는데...)....[면접관] 2-1번 식을 이용해서 구했잖아요. 바로 문제 2-1을 보고 ‘아! 문제 조건이 (t0≥12)여서 그런 것 같습니다.2-3. 우선 못 풀었다고 말씀드리고 어떻게 해결하려고 노력했는지 말씀드리던 와중 시간이 끝나서 나왔다.2-4. 타임아웃후배들을 위한 조언 너무 초반에 걸리면 이른 아침이라 정신이 없습니다. 그리고 너무 늦게 걸려도 지칠 것 같기도 합니다. 근 데이건 여러분이 결정하는게 아니라 운이니까 그려려니 하세요. 그리고 면접관 분들이 생각보다 가까이 계십니다. 채점하는거 다 보여요. 멘탈 챙기려면 면접관이 채점하는 종이 쳐다보지 않는 것을 추천드립니다. 그리고 긴장하지 마세요. 저는 별로 긴장 안 했는데 이 정도면 긴장했을 때는 답도 없습니다. 그리고 아침 챙겨드세요. 배고파요."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(2권)」","year":"2025학년도"},{"univ":"서울대학교","dept":"통계학과","jeonhyeong":"학생부종합(일반전형)","method":"문제풀이 → 힌트(교수마다 다름) → 문제풀이 반복자신의 생각을 전할때 당황하지 말고 질서정연하게 말하는것이 중요하다.","notes":"그리고 교수마다 다르지만 친절한 교수님도 있고 아닌 교수님도 있다. 힌트를 주시는 교수님이라면 그 힌트들을 잘 조합하여 답에 도달하도록 침착하게 대응하도록 해야한다","qa":[{"q":"푼 문제 알려주세요","a":"1-1, 1-2, 2-1, 2-2 풀었습니다"},{"q":"답 말해보세요.","a":"(푼 문제 답변)"},{"q":"1-2번에서 푼 식 다시 한 번 계산해볼래요?","a":"아 네 알겠습니다 (계산식 다시 검토) 답이 ~~나왔습니다."},{"q":"(고개 끄덕임.), 2-2번에서 답의 범위를 r을 통해서 표현하였는데 2-2번 답은 2-1에서 구한 y로 나타내볼래요?","a":"아 네 알겠습니다. (y로 나타낸다는 생각을 못하고있었어서 살짝 당황함)"},{"q":"2-1번에서 구한 y의 의미가 뭐죠?","a":"~~입니다. (뭐라고 했는지 기억이 안남)"},{"q":"그렇죠. 그럼 다시 생각해보세요","a":"(이때 깨닫고 다시 계산하여 범위를 구함) 답은 ~~입니다"},{"q":"2루트 29요?","a":"아 죄송합니다. 2루트19입니다."},{"q":"(고개를 끄덕임) 1-3과 2-3중에 더 풀어보고 싶은거 있나요?(이때 평소에 연습한거와는 다르게 맞은 문제는 풀이과정에 대한 설명을 요구하지 않고 넘어가서 시간이 남음)","a":"2-3번 풀어보도록 하겠습니다 (2-3번을 조금 풀어놓았던 상태여서 2-3을 선택함, 그러나 답이 잘 구해지지않음 그래서 멍때리기 보다는 힌트를 얻어야겠다고 생각해서 내가 푼데까지 언급하며 힌트를 유도함)일단 저는 문제 애서 주어진 식을 곱하면 사차함수꼴이 나온다는 점에 착안하여 개형을 토대로 극값의 범위를 알아내야 한다고 생각했습니다. 그래서 사차함수 식을 구하였는데요. 계산과정에 어려움이 있어서 완벽한 답을 구해내지는 못했습니다."},{"q":"이 식은 사차함수의 대칭성을 이용할수 있거든요?","a":"(살짝당황) 아 네."},{"q":"그 점 고려해서 극댓값이 어디서 구해질지 한번 고민해보세요","a":"(고민중.. 그러나 잘 모르겠음)"},{"q":"두 도형의 크기를 고려해보면 어느 순간에 극댓값인지 알 수 있지 않을까요?","a":"아 네 맞습니다 ~~일때 사차함수가 극대가 될것입니다."},{"q":"(고개를 끄덕임) 그렇죠.(시간이 끝나서 인사를 하고 나왔음)후배들을 위한 조언 일단 들어가면 교수님과 입사관분이 한분계시는데 나이가 적으신분이 입사관님입니다. 입사관분이 대체적으로 더 착하고 힌트를 많이주시니 그점 알고 계시면 좋을것같고요.또한 칠판이 있을 것이라고 예상했는데 칠판이 없어서 처음에 상당히 당황했습니다. 만약 제시문 면접을 연습하신다면 칠판이 없는 상태로 연습해보시는 걸 추천드립니다. 또한 자신의 생각을 마음껏 말해야합니다. 그래야지 교수님과 입사관이 이 친구가 어디까지 풀었는지 파악하고 그에 맞는 힌트를 주십니다. 그러므로 가만히 있지 말고 계속 커뮤니케이션하면서 힌트를 이끌어내세요. 물론 학과by학과이기 때문이 제 말이 절대적이라고 할 순 없습니다. 그러나 도움은 분명히 될 것 입니다. 화이팅하세요","a":""}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(2권)」","year":"2025학년도"},{"univ":"서울대학교","dept":"의예과","jeonhyeong":"학생부종합(일반전형• MMI+서류면접 형식• 면접 장소 입장 → 면접 전 대기실(4층)에서 물품 정리, 수거 및 주)","method":"의사항 안내 → 대기 후 면접실(2층)으로 이동 → 2분 제시문 준비 후 입실, 8분 면접 → (단, 서류 면접은 2분 대기 후 입실/18분 면접)(※ 제시문 면접 4회, 서류 면접 1회) → 퇴실 후 면접 후 대기실에서 설문 및 대기(저희는 유퀴즈 틀어줬습니다) → 소지 물품 챙긴 후 퇴실, 끝","notes":"블라인드 규정 지키기 (기본 소양이지만, 은근히 지키기 힘든 것 같아요. 신경 쓰는 게 도움이 될 거예요.)","qa":[{"q":"이 제시문에 관해","a":"조각가가 한 회장의 조각 의뢰를 받고, 회장의 지적에 대해 작품의 완성도뿐만 아니라 회장의 기분 또한 고려하는 대처에 관한 제시문이라고 생각합니다."},{"q":"조각가의 대처에 대해 어떻게 생각하시나요?","a":"회장의 지적을 해결하면서(회장의 위치를 바꿈으로써 빛에 의한 문제 해결)도 직설적으로 말하지 않아 회장의 기분까지 살피는 현명한 대처라고 생각합니다."},{"q":"만약 본인도 조각가와 같은 상황이었다면 그렇기 대처하셨을 건가요?","a":"네, 문제도 해결하고, 회장의 기분까지 챙긴다고 생각하기에 저였어도 그렇게 대처했을 것입니다"},{"q":"다른 사람이 이렇게 사실과 다르게 말을 함으로써 문제를 해결하는 것에 대해 어떻게 생각하시나요?","a":"문제를 해결하는 데에 도움이 되고, 그 외에 피해를 주지 않는다는 점에 있어서 유연한 해결 방식이라고 생각합니다."},{"q":"본인도 이렇게 사실과 다르게 말을 함으로써 문제를 해결한 경험이 있나요?","a":"당장 구체적으로 떠오르는 경험은 없지만, 상대방이 알지 않으면 더 좋은 사실을 말하지 않음으로써 대화를 유연하게 넘어간 경험이 여럿 떠오릅니다.※지금 다시 생각해보면, 사실과 다르게 말해도 괜찮다는 견해의 선행조건이 ‘피해를 주지 않음’이라는 것을 더 강조할 필요가 있지 않았을까 생각합니다.<방 2> 서류 면접"},{"q":"(※생기부를 읽을 동안 시간을 벌고, 분위기를 풀기 위한 질문인 듯하다) 면접 끝나고 나면 무엇을 할 예정인가요?","a":"집에 가서 가족과 같이 쉴 것 같습니다."},{"q":"보면 한문 시간에 모 단체가 킬러 문제를 삭제하라고 한 것에 대해 ‘탁상공론’이라고 평했습니다. 이에 대해 더 설명해주실 수 있나요?","a":"네. 해당 단체는 교육과정 범위 축소를 요구해 킬러 문제가 출제되는 원인을 제공했음에도 그를 무시하고 무턱대고 킬러 문제를 출제하지 말라고 주장했기에 이를 ‘탁상공론’이라고 표현한 것입니다."},{"q":"하지만 그 단체의 주장에도 합리적인 면모가 있지 않았을까요? (※아마 공감능력을 보거나, 제가 활동하면서 나온 생각의 흐름을 보기 위한 질문이 아니었을까 생각합니다) )","a":"물론 그 단체의 주장에도 합리적인 면모가 있지 않을까 생각해 그런 부분을 찾으려고 했습니다. 그런데 도저히 그런 것을 찾을 수 없었기에 ‘탁상공론’과 같은 부정적 평가를 내리게 되었습니다.<방 3> ‘언어는 소통을 하기 위한 도구다’"},{"q":"제시문의 내용이 어떻게 되나요?","a":"이 제시문의 요지는 언어가 결국은 사람끼리 소통을 하기 위해 쓰이는 도구라는 것입니다."},{"q":"학생의 의견도 이와 같습니까?","a":"저 또한 언어의 본질은 사람 간의 소통이라 생각해 비슷한 의견을 가지고 있습니다."},{"q":"이모티콘과 같은 비언어적 소통 수단에 대해 어떻게 생각하시나요?","a":"적절하게 사용하면 이로울 수 있으며 적절하지 못하게 썼을 때 되려 소통을 방해할 수 있는, 언어와 다른 종류의 추가적인 소통 수단이라고 생각합니다. (나머지 구체적 질문은 기억나지 않지만, 저의 소통 관련 경험을 많이 물어봤습니다.)<방 4> 내면과 외면"},{"q":"이 지문의 핵심 단어들을 몇가지 뽑아주세요","a":"(‘내면’ ‘외면’ 등을 핵심 단어로 꼽았습니다)"},{"q":"어째서 핵심 단어로 꼽았나요?","a":"이 지문의 요지는 사람이 발전하기 위해서 외면으로부터 답을 찾아야 하는 질문과 내면으로부터 답을 찾아야 하는 질문을 구별할 줄 알아야 함이라고 파악해, 그에 맞게 핵심 단어를 꼽았습니다.(이하 생략, 추가 제시문에 대해서도 핵심 단어를 꼽고 이유를 설명하라는 질문을 받아 비슷한 대답을 했습니다.)<방 5> 커피 섭취량과 위험도 간 상관관계 실험 자료"},{"q":"자료에 관해 분석한 바 말씀해주세요.","a":"(전체적 경향인 커피 섭취량과 위험도 간 양의 상관관계를 짚음. 그리고 양의 상관관계가 나타나지 않는 특이점을 짚으면서 표본 수 부족 등이 원인일 수 있다는 의견 제시. 제시문 자료에 따르면 통계적으로 의미가 없는 부분도 있었는데, 이를 짚었고 어째서 그런 부분이 나타났을지 추측하는 의견 내놓음.)"},{"q":"이 자료를 통해서 우리가 알 수 있는 바는 무엇일까요?","a":"일단 이 자료를 통해 결론을 내리려고 한다면 커피를 많이 섭취할수록 대사질환에 걸릴 위험이 커진다고 결론을 내릴 수 있겠습니다. 하지만 엄밀히 따지자면, 커피 섭취량과 위험도가 단순 상관관계인지, 인과관계인지는 이 자료만으로 알 수 없기에, 앞서 말한 결론에 더 높은 신뢰성을 주기 위해서는 인과관계인지 따지는 후속실험을 진행해야 할 것이며, 그렇게 했을 때 더 완성도 높은 연구가 될 것입니다. 후배들을 위한 조언 아마 서울대 의대 면접을 준비하는 학생이면 방학 중에, 혹은 시험 후에 학교에서 자체적으로 진행하는 연습이나 교육청 주관 연습에 많이 참여했을 것 같아요. 그런 경험을 꾸준히 쌓는 게 확실히 도움이 되는 것 같아요. MMI 면접은 한번에 연습을 몰아치는 거보단 꾸준히 적은 양을 연습해 감을 유지하는 것이 더 도움이 되는 것 같거든요. 물론 면접 직전에 막판 스퍼트로 연습하는 것도 도움이 되고요.서류 면접을 준비할 때는 생기부를 한번씩 되짚으면서 기억을 상기시키고, 내용을 까먹은 활동이 있다면 당시 자료를 보면서 기억을 살리는 식으로 준비하는 게 도움이 되었어요. 모든 활동을 정리하면서 어떻게 소개할지까지 구상할 수도 있지만, 그렇게 하기 위해선 수능 전부터 조금씩 준비하는 게 도움이 될 거예요. 서울대는 수능 끝나고 일주일만에 면접을 봐서 준비 시간이 약간 빡빡할 거예요. MMI 시험장이 어떻게 되어있는지 몰라서 제시문 보고 준비하는 방이 따로 있고, 질문에 답하는 방이 따로 있는 줄 알았어요. 그런데 복도에 책걸상 깔아놓고 거기서 제시문 보게 한 다음, 방에 들어가서 답하는 거더라고요. 가서 보면 당황할 수도 있으니 참고하세요. 아마 그럴 사람은 없겠지만, 제 문답을 하나하나 뜯어보고 분석하는 것은 크게 도움이 되지 않을 것 같습니다. 기억에 의한 왜곡이 있을 수도 있고, 저 스스로도 아쉬운 답변들이 있으니까요. 대신 전체적인 태도를 참고해주는 게 더 도움이 될 것 같아요. MMI에서 평가하려는 항목과 제시문 내용을 전체적으로 봤을 때 원하는 인재상은 (간단히 말해서) 의사에게 필요한 탐구력과 연구 정신도 가지고 있으면서 사람 냄새도 나는 그런 사람인 것 같아요. 저는 MMI 준비하면서 예시 질문에 대한 답변으로 ‘의사에게 가장 필요한 덕목은 타인과 소통하는 능력, 공감하는 능력, 그리고 성실하게 꾸준하게 학업을 이어나가는 능력이다’를 준비했는데, MMI에서도 이런 능력을 어필하려고 하면 면접에서 전체적인 톤을 맞출 수 있을 거예요.그렇다고 자신과 완전히 다른 사람으로 꾸미고 철판 깔려고 하는 것도 크게 도움이 안 될 것 같아요. 면접하면서 느낀 게, 거짓으로 꾸며낸 인격이 있으면 그 자리에서 다 ‘뽀록’날 것 같다는 거였어요. 솔직해지되, 위에 말한 것들을 조금씩 더 어필하려고 노력하는 게 도움이 될 것 같아요.시험장 안에 들어가면 사람마다 다양한 심정일 거예요. 어떤 사람은 간절하고, 어떤 사람은 긴장되고, 어떤 사람은 의외로 담담하고 아무렇지 않을 거예요. 심정이 어찌됐건, 대시길에선 최대한 진정하려고 하고, 시험장에선 어떻게든 질문하는 거에 잘 답하려고 하면 도움이 될 거예요. 면접이 굉장히 빠르게 바로바로 진행되어서 답하는 것에 집중하다 보면 걱정, 잡생각이 들 틈도 없을 거예요. 저보다 한 학년 위인 선배도 면접 볼 때 정신 없었다고 하더라고요. 1시간이 1시간 같지가 않아요 한 30분밖에 안 지난 것 같은데 면접이 끝나있어요."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(2권)」","year":"2025학년도"},{"univ":"서울대학교","dept":"약학계열","jeonhyeong":"학생부종합(지역균형전형)","method":"지원동기 → 자율, 진로 질문(윤리, 전공 관련, 인성) → 마지막 할 말","notes":"입실 후 자료 열람 불가","qa":[{"q":"지원동기 말해주세요","a":"안녕하세요. 저는 활성산소의 조절을 통해 질병의 예방 및 치료 방안에 대해 연구하고 싶은 지원자입니다. 2학년 때 <살고 싶다는 농담>이라는 책을 읽고 암 환자가 느끼는 고통이 극심하다는 것을 깨달았습니다. 이후 암의 치료도 중요하지만, 예방 또한 가치 있는 일이라는 것을 깨달았습니다. 저는 이후 항산화 물질에 관심을 가지게 되었고, 비타민 C 산화환원적정 실험, 항산화물질의 세포 보호 효과 실험 등을 하며 관심을 구체화해나갔습니다. 저는 궁극적으로 활성산소의 조절을 통해 많은 사람들이 쉽게 접근할 수 있는 치료 및 예방 방안에 대해 연구하고 싶습니다. 따라서 이를 이루기 위해 서울대학교 약학대학에 있는 세포독성학 연구실에서 공부하고 싶어 지원하게 되었습니다."},{"q":"벌써 대학원까지 정한건가요?","a":"먼저 학부 때 독성학, 분자종양생물학과 같이 관심 과목을 이수한 뒤 진로를 구체화 시키고, 제가 관심있는 활성산소에 대해 연구하는 세포독성학 연구실에서 연구하고 싶습니다."},{"q":"1학년 진로 때 생명공학기술 남용과 처벌 기준에 대한 모의 국제기구 프로젝트에 참여했다고 했는데 생명공학 기술 남용을 본인은 무엇이라고 생각하나요?","a":"저는 생명공학 기술 남용이란 생명공학 기술을 부정한 목적으로 이용해서, 윤리적 문제 등 사회에 피해를 주는 것이라고 생각합니다. 예를 들면 디자이너 베이비의 경우, 더 우월한 지능과 외모를 가지게 하려는 부정한 목적이 있으며, 이것이 실현될 경우 사회에 윤리적인 문제를 일으키는 등 여러 문제를 야기할 수 있어 생명공학 기술 남용이라 생각합니다"},{"q":"그렇다면 이 생명공학 기술의 남용의 해결 방안이 무엇인가요?","a":"저는 먼저 생명공학기술 남용에 대해 다루는 전문적인 국제기구가 필요하다고 생각합니다. 생명 공학 기술은 과학 분야 뿐만 아니라 사회에도 큰 영향을 미치기 때문에 과학 분야의 전문가와 사회 윤리 분야의 전문가가 모두 모여 다각적인 관점에서 생명공학기술을 다루는 국제기구가 필요하다고 생각합니다. 두 번째로, 구체적으로 생명공학기술 남용이 무엇이고 처벌은 어떻게 해야하는지를 규정하는 법이나 협약이 필요합니다. 현재 생물다양성 협약이 존재하지만, 규정이 모호하고, 빠르게 발전하는 생명공학기술을 모두 다루기는 어렵습니다. 따라서 구체적인 사례를 중심으로 남용의 기준과 처벌을 정하고, 이를 지속적으로 갱신하는 것이 필요하다고 생각합니다."},{"q":"2학년 진로 시간에 바이오의약품에 관한 책을 읽었다고 되어있는데, 바이오의약품이 무엇인가요?","a":"바이오의약품이란 단백질, 펩타이드처럼 생물체에게서 유래된 성분으로 만든 의약품입니다."},{"q":"바이오의약품 중 CAR-T 치료제가 무엇인지 아나요?","a":"CAR-T 치료제는 세포 면역 치료제입니다. 환자에게서 T세포를 추출하고, 유전자 조작을 통해 키메라 항원 수용체를 발현시킨 뒤 다시 환자에게 주입하는 방식입니다."},{"q":"CAR-T 치료제의 장단점 아나요?","a":"먼저 장점으로는, 환자의 세포를 이용하기 때문에 면역 반응이 적다는 것입니다. 두 번째로는 표적 치료제이기 때문에 정상 세포의 사멸을 최소화시킬 수 있습니다. 단점으로 첫 번째는 과도하게 면역 반응을 활성화시킬 시 사이토카인 증후군이 유발될 수 있습니다. 두 번째로는, 적대적인 미세종양환경 때문에 아직 고형암에서는 효과를 보기 어렵습니다."},{"q":"2학년 진로 시간에 학술제에서 전교생 대상으로 비침습 기술에 대해 발표했다고 되어있는데, 발표 내용 설명해주세요.","a":"저는 먼저 비침습 기술의 필요성에 대해 알렸습니다. 생명과학 시간에 항상성 단원을 배우면서 당뇨병 환자의 경우 정기적으로 채혈을 한다는 것을 알게 되었는데, 침습적 방식이 많은 고통과 불편을 야기할 수 있다는 것을 알게 되었습니다. 이를 해결할 수 있는 방안으로 비침습 기술이 필요하다고 하였습니다. 그리고 비침습 기술의 대표적인 예시를 설명했습니다. 마지막으로, 비침습 기술 개발 중 윤리적인 문제를 일으킨 기업의 사례를 들며, 비침습 기술을 만들 때 신속함도 중요하지만 정확성을 고려해 윤리적인 방향으로 개발하여야 한다고 주장했습니다."},{"q":"비침습 기술에 어떤 것이 있나요?","a":"대표적으로 적외선 분광법과 같이 빛을 이용하는 방법과, 전기를 이용한 방식이 있는데, 전기장을 걸어 나트륨 이온과 염화 이온을 측정해 혈당량을 파악하는 방식입니다. 마지막으로 침, 땀과 같이 채액을 이용하는 방법이 있습니다."},{"q":"2학년 자율 시간에 멘토멘티 했는데, 멘토멘티 내용과 이걸 통해 본인이 느낀점이 무엇인가요?","a":"저는 생명과학과 화학 과목 공부에 어려움을 느끼는 친구를 보고 멘토멘티를 하게 되었습니다. 먼저 친구가 어려워하는 개념을 설명하고, 필요한 부분을 바탕으로 직접 학습지를 만들었습니다. 또한, 화학식량, 몰 등의 관계를 이용하거나 표를 이용하는 저만의 방식을 알려주기도 하였습니다. (1분 노크 울리고, 느낀 점 급하게 마무리, 당황해서 뒷말이 정확하게 기억이 나진 않아요..) 저는 이를 통해 현재 성적 경쟁이 치열하긴 하지만, 이렇게 친구를 도와주면서 친구가 성장함에 보람을 느끼고, 저 또한 과목에 대한 이해가 향상되어 함께 성장하는 것의 가치를 알게 되었습니다."},{"q":"시간 얼마 안 남았는데, 마지막으로 하고 싶은 말 있나요?","a":"긴장해서 준비한 만큼 못 보여드린 것 같아 아쉽습니다. 지난 여름 방학 때, 서울대학교 약학대학에 방문하여 방명록에 내년에 신입생으로 다시 왔으면 좋겠다고 했었는데, 이렇게 1차에 합격하여 훌륭하신 선생님들과 이야기 나누어볼 수 있어 영광이었습니다. (더 있었는데 문 열려서 급하게 마무리) 감사합니다. 후배들을 위한 조언 제가 후기 분석하면서도 느꼈지만, 서울대는 지원자의 가치관이나 생각을 묻는 질문을 꼭 하는 것 같습니다. 관련 활동을 했다면 이에 대한 본인의 답변과 근거, 혹시 모를 반론에 대한 반박까지 준비해가시면 좋을 것 같습니다. 그리고 본인의 주요 활동이 아니더라도 꼼꼼히 준비해 가시길 바랍니다. 열심히 준비하신 만큼 좋은 결과 있을 것입니다. 화이팅!"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(2권)」","year":"2025학년도"},{"univ":"서울대학교","dept":"약학계열","jeonhyeong":"학생부종합(기회균형특별전형(사회통합))","method":"공동교육과정 질문 → 3학년 진로활동 질문 → 학생회 활동 질문 → 공동교육과정 질문","notes":"- 자기소개, 지원동기 안 물어봄.- 대기실에 들어가자마자 모든 물품 수거","qa":[{"q":"(첫 질문) 생명과학실험에서 활성산소 관련 활동을 했었는데~~","a":"(답변 내용이 기억 안 남.)"},{"q":"미토콘드리아에서 세포호흡의 결과로 활성산소가 생기는데, 비효소적 항산화제가 활성산소를 어떤 원리로 치료하는지 아나요?","a":"활성산소를 비효소적 항산화제가 제거하는 구체적인 기작에 대해서는 탐구하기 어려워 못했지만 대학교에 입학하여 그 기전에 대해서 더 공부해보겠습니다."},{"q":"3학년 진로활동 때 ELISA 실험 방법에 대해 탐구했는데 배우고 알게 된 점이 뭔가요?","a":"실험 결과, ELISA 실험 방법이 민감도와 특이도 모두 높은 실험이지만 상대적으로 특이도가 낮음을 알게 되었습니다. 이러한 단점을 보완하기 위해서는 Western blot과 같은 실험을 보완적으로 사용해야 함을 알게 되었습니다."},{"q":"(이어서 꼬리 질문) Western blot이랑 ELISA 실험의 차이점은 뭔가요?","a":"Western blot과 ELISA 모두 항체 검사로서 사용되고 있지만, Western blot은 전기영동으로 하는 실험으로, 정확도가 높으나 검사하기에 시간이 오래 소요된다는 점에서 차이가 있고, ELISA는 신속하고 정확하게 할 수 있다는 점에서 차이가 있습니다."},{"q":"(이어서 꼬리 질문) Western blot의 구체적인 기작을 아시나요?","a":"Western blot의 구체적인 기작에 대해서는 잘 모르겠습니다. 제가 탐구했던 활동이 ELISA 실험방법에 대한 탐구였어서 저는 그 탐구활동을 집중적으로 탐구했습니다. 탐구활동했던 ELISA에 대해서는 잘 알고 있지만 Western blot의 기작은 모르겠습니다."},{"q":"학년장 활동을 3년 내내 했었는데 학년장을 하면서 배운 점은 뭔가요?","a":"학년장 활동을 하면서 학교와 학생 사이의 소통을 매개하는 것이 정말 중요하다는 것을 알게 되었습니다. (뒤에 부연 설명)"},{"q":"그럼 만약에 학급반장으로서 선생님이 수업에 들어오셨는데 학생들이 수업준비가 안 되어있는 상태라면 어떻게 할건가요?","a":"친구들에게는 기분 나쁘지 않게 “우리 이제 수업준비를 해볼까? 우리 멋진 고등학생이잖아~”라고 유쾌하게 말할 것입니다. 그리고 수업 종료 후에 친구들과 함께 소통을 하며 문제에 대해서 해결해나갈 것이고, 선생님께 찾아 봬서 두 번 다시 이런 일을 만들지 않을테니 죄송하다는 말씀을 드릴 것입니다."},{"q":"고급화학 시간에 비대칭 유기촉매를 배웠는데 탈리도마이드랑 비대칭 유기촉매가 어떤 상관관계가 있죠?","a":"(먼저 탈리도마이드 사건의 심각성을 언급함.) 따라서 탈리도마이드 사건을 통해 거울상 이성질체를 안전하게 선택적으로 합성해야 함을 배웠고, 비대칭 유기촉매를 통해 거울상 이성질체를 선택적으로 합성할 수 있습니다."},{"q":"(이어서 꼬리 질문) 탈리도마이드의 부작용으로 약물 판매가 중단되었다가 오히려 그 부작용으로 약물을 판매하고 있는데 무슨 치료제로 사용될 수 있을까요?","a":"혈관 생성을 억제하는 부작용으로 보아 암세포를 억제하여 암을 치료할 수 있는 약물로 사용될 수 있을 것이라 생각합니다."},{"q":"(이어서 꼬리 질문) 네, 항암제로서 사용될 수 있고요. 그렇다면 정상세포와 암세포 둘 다 영향이 갈 수 있을텐데 어떻게 해야 할까요?","a":"정상세포와 암세포의 차이점을 활용하여 암세포만을 특이적으로 치료하는 기술을 사용해야 한다고 생각합니다.추가 질문을 하시던 와중 문 열리며 끝.후배들을 위한 조언 너무 떨지 마시고 가서 자신이 할 수 있는 얘기를 후회없이 하고 오세요. 저의 생각을 물어보시는 질문을 많이 하셔서 준비했던 거랑 달라 당황했지만 소신껏 자신의 생각을 말하면 됩니다. 그리고 공동교육과정을 물어보신다는 소문을 들었는데 정말로 공동교육과정 질문을 많이 하시더라구요. 더 꼼꼼히 살펴가면 좋을 것 같습니다."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(2권)」","year":"2025학년도"},{"univ":"서울대학교","dept":"약학계열","jeonhyeong":"학생부종합(지역균형전형)","method":"고급화학 기억에 남는 내용 질문 → 생명과학 질문 →독서 질문 → 사회문제탐구 질문","notes":"면접 수험번호가 아닌 가번호대로 조를 짜서 면접을 진행하기 때문에 면접 수험번호가 면접 순서가 아님.","qa":[{"q":"고급화학에서 가장 기억에 남는 내용을 말해보세요.","a":"저는 고급화학에서 배위결합에 대해 학습했던 내용이 가장 기억에 남습니다. 배위결합은 공유결합과 달리 원자가 서로 전자쌍을 주는 것이 아니라 한쪽에서 일방적으로 전자쌍을 주며 결합이 형성됩니다. 이러한 배위결합이 포함된 항암제의 예시로는 시스플라틴이 있습니다. 시스플라틴은 암세포의 DNA에 결합하여 항암 작용을 합니다."},{"q":"시스플라틴의 중심 금속 이온이 무엇인지 알고 있나요?","a":"백금 이온이 중심 금속 이온으로 결합해 있습니다."},{"q":"배위결합 말고 항암제에 포함되어 있는 결합에는 무엇이 있나요?","a":"배위결합 말고도 공유결합, 이온결합 등이 포함되어 있습니다."},{"q":"배위결합과 공유결합이 항암제에 쓰였을 때 그 차이점은 무엇일까요?","a":"배위결합은 공유결합과 달리 공유 전자쌍을 한쪽에서 일방적으로 제공합니다. 아무래도 공유 전자쌍을 한쪽에서만 제공하기 때문에 결합의 세기가 배위결합이 공유결합보다 약하다고 생각합니다."},{"q":"2학년 진로 시간에 탐구한 면역관문 억제제에 대해 설명해보세요.","a":"면역관문 억제제란 면역 항암제의 한 종류로, 말 그대로 면역관문을 억제하는 역할을 합니다. 면역관문은 표적 단백질들이 항원과 결합되었을 때 면역 반응이 끝났음을 알리는 역할을 하는데 암세포들은 이를 악용하여 면역 세포들이 자신들에게 공격하지 못하도록 합니다. 이때 면역관문 억제제를 사용하여 면역 세포들이 암세포들을 더 잘 인식해 공격할 수 있도록 유도합니다."},{"q":"면역관문 억제제의 예시를 들어볼 수 있나요?","a":"면역관문 억제제의 정확한 이름은 기억나지 않지만 이 면역관문 억제제가 작용하는 단백질의 예시로 PD-1 단백질과 CTLA-4 단백질이 있습니다."},{"q":"2학년 자율 시간 독서 워크숍 ‘가짜 인간’이라는 책을 읽었는데 그때 자신의 역할과 어떻게 생각하는지 말해보세요.","a":"‘가짜 인간’이라는 책은 반려 AI에 관한 도서로 AI의 시선에서 바라본 인간들의 모습을 담았습니다. 독서 내용을 발표해야 하는 상황이 있었는데 모둠원 친구들이 발표하기를 꺼려하는 것 같아서 제가 솔선수범해서 발표를 진행했던 경험이 있습니다."},{"q":"어떻게 생각하는지...","a":"책에서처럼 인간의 필요에 따라 무분별하게 반려 AI를 사고 버리고 하다 보면 AI들도 인공지능을 가지고 있기 때문에 언젠가는 영화 터미네이터처럼 인간들을 공격할 수도 있다고 생각합니다. AI 입장에서는 인간들의 욕망에 따라 사용되고 버려지는 것이기 때문에 AI를 무분별하게 사용하는 것은 부적절하다고 생각합니다.[1분 남음 노크]"},{"q":"사회문제탐구 시간에 탐구한 항암제 바이오시밀러에 대해 말해보세요.","a":"항암제 바이오시밀러는 특허 만료 기간이 지난 오리지널 항암제를 복제해서 만든 것으로 비용이 더 싸다는 장점이 있습니다."},{"q":"왜 비용이 싼지 좀 더 구체적으로 말해줄 수 있나요?","a":"새로 나오는 항암제는 일정 기간이 지나면 특허 기간이 끝나서 특허 보존이 끝납니다.[문 열림]후배들을 위한 조언 꼬리 질문 및 압박 질문이나 자세한 내용을 물어보는 질문은 전공 관련한 내용뿐 아니라 독서나 인문 과목 쪽에서도 나오기 때문에 폭넓은 다양한 영역의 질문들을 깊게 준비할 필요가 있음. 나올 것 같다고 예상한 진로 관련 질문만큼 아닌 것도 많이 나오므로 진로 관련 예상질문들을 착실하게 준비하되 진로와 상관없어 보이는 예상질문 답변 준비도 중요함. 1~2초라도 생각하는 시간으로 정적이 흐르면 기다려주지 않고 바로 질문하시기 때문에 대답이 굉장히 짧아지게 됨. 따라서 생각하는 시간을 최대한 줄이고 덧붙일 말이 있다면 이어서 바로바로 말하도록 해야함. 두괄식 답변을 많이 연습했지만 막상 시험장에 들어가면 생각을 물어보는 질문에 대해서는 순간적으로 두괄식으로 말하기 힘들었음. 생각을 묻는 질문에서도 두괄식으로 말하는 연습이 필요함."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(2권)」","year":"2025학년도"},{"univ":"서울대학교","dept":"수의예과","jeonhyeong":"학생부종합(일반전형)","method":"MMI 절차 간단히 설명 → 방 5개 드나들며 면접(제시문 1분 정도 숙지-대답)","notes":"마지막 조 배정되면 대기시간이 3시간은 넘어서 청심환 효과 줄어들 수도 있음.","qa":[{"q":"수립채십사회 산업화시대 정보화시대로 진입하며 수의사의 역할이 어떻게 바뀌었는지?","a":"과거에 동물의 건강이 인간의 삶에 직결되었다는 설명, 가족으로서의 동물의 건강을 지킨다는 설명, 과학 기술로 동물의 멸종을 막아 생태계를 보호할 수 있다는 설명"},{"q":"지원자가 학교에서 진행한 활동 중 가장 기억에 남는 것(비스무리한 질문)","a":"수의사가 하는 일은 동물의 생명과 안전을 지키는 일이기에 학생 신분에서 할 수있는 일으로서 유리창 버드세이버 붙이는 활동 설명"},{"q":"생기부에 4R에 대해 적혀있는데 실험동물 3R에 대해 알고 있는가?","a":"동물실험의 윤리적 기준과 관련된 지침인 것으로 알고 있으며 각 단어가 무엇인지는 정확히 모름, 대신 4R에 대해 설명드려도 되냐고 여쭝-시간 끝<제시문> 같은 약물을 같은 종의 동물 가. 나에게 투여해서 약물과 그 대사산물의 농도 변화 를 보여주는 그래프, 약물은 간에서 대사산물로 변화되고 그 대사산물을 배설하는 건 -에서 이루어짐"},{"q":"1. 약물의 농도가 줄어드는 양상의 차이와 이유를 설명하시오.","a":"수치 언급하며 양상 차이 설명, 간의 기능 차이로 인할 것"},{"q":"2. 약물이 배설되는 양상의 차이와 이유를 설명하시오.","a":"수치 언급하며 양상 차이 설명, -의 기능 차이로 인할 것."},{"q":"3. 가, 나 동물은 어떤 차이를 가지고 있을까","a":"간과 -의 기능에 차이가 있는 것으로 보임, 한 동물은 다른 동물에 비해 그 기관의 건강이 좋지 않거나 질병 있을 것."},{"q":"(추가 질문) 약물 사용시 주의할 점?","a":"배설 시간을 볼 때 그 시간보다 짧은 간격으로 투여하면 내성이 생길 가능성이 있으니 시간에 유의해서 사용해야 할 것."},{"q":"수혈할 피를 공혈동물에게서 얻는 것에 대해 어떻게 생각하는가","a":"공혈동물의 처우가 안 좋은 것으로 알고 있음. 수의사로서 동물을 대할 때 윤리적인 부분에 대해 고민해야 함. 현재로선 헌혈이 부족해 현실적으로 공혈 동물 사용할 수 밖에 없으므로 공혈동물의 처우 개선해야 함. 그리고 윤리적인 부분에서 동물을 도구적 가치로 대하는 것에 대해서도 고민해야 할 것."},{"q":"헌혈 동물에게서 얻는 것에 대해 어떻게 생각하는가?","a":"공혈동물과 관련된 문제가 발생하지 않으므로 적절한 방법이라고 생각함. 다만 헌혈양이 현재 부족하므로 헌혈을 장려할 방안을 고안해야 한다는 설명."},{"q":"동물병원 원장으로서 환자를 치료할 때 어떤 방법을 선택할 것인가","a":"수의사로서 동물 윤리를 고리해야 하므로 공혈동물에게서 혈액을 얻는 것은 최소한으 로 할 것. 그리고 병원을 찾는 고객분들게 헌혈의 가치를 알리고 공혈동물의 현실에대해 알려 헌혈을 장려할 것."},{"q":"유전자 조작된 동물은 어떤 변화가 생기며, 유전자 조직의 단점을 설명하시오.","a":"인간이 원했던 형질에 변화가 생기고, 그 형질을 담당하는 유전지군에 변화가 생기므 로 예기치 않은 변화 또한 생겨날 것. 예기치 않은 변화가 단점이 될 수 있는데 형질개량한 닭 풍종에서 발생한 단점 설명."},{"q":"유전자 조직한 동물과 아닌 동물을 가려내기 위한 실험을 고안하시오.","a":"전기.영동 실험을 통해 가려낼 수 있음. 혹은 동물을 특정 상황에 처하게 해서 그에 따른 반응을 살펴봄으로써 형질 중 성격과 관련된 부분의 변화를 가려낼 수 있음."},{"q":"엑스레이를 찍을 때 진료진이 동물을 붙잡고 찍는 것의 장단점을 설명하시오.","a":"안정적이기에 여러 번 찍을 수 있고 비용절감해서 병원 접근성 낮출 수 있음. 다만 진료진이 방사선에 지속적으로 노출돼 건강문제 있을 수 있고 일부 특수동물의 경우 붙잡고 찍는 것 자체가 불가."},{"q":"엑스레이를 찍을 때 마취제를 투여하는 것의 장단점을 설명하시오.","a":"앞서 말한 장점이 다 유지된다는 설명. 진료진 건강도 문제 없음. 마취제가 늙은 동물에겐 부담이 될 수 있는 등 동물의 건강에 문제 생길 수 있음. 마취제 가격도 추가됨."},{"q":"동물병원 원장으로서 어떤 방법을 선택할 것인가?","a":"진료진이 붙잡는 방법. 환자의 안전이 우선이라고 설명. 진료진 건강에 대해서도 언급하려는데 시간 끝후배들을 위한 조언 시사 문제의 경우 생기부에서 활동한 게 나왔기 때문에 사전 지식이 많은 게 있었음. 관련 시사 탐구 꾸준히 하는 게 도움될 것 같습니다. 관련 문제에 대해 평소에 고민해보면 좋겠습니다. 면접 도중엔 당황하더라도 가라앉히는 게 중요하다고 느꼈습니다. 방에서 나와 다음 방 대기하는 시간에 차분히 가다듬기. 은근 시간이 빨리 지나가서 차분히 임하는 것이 중요합니다."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(2권)」","year":"2025학년도"},{"univ":"서울대학교","dept":"수의예과","jeonhyeong":"학생부종합(지역균형전형)","method":"날씨 이야기 -> 생활기록부 관련 질문 -> 끝","notes":"면접관님 두 분이 번갈아 가며 질문하심.","qa":[{"q":"2학년 2학기 때 들은 생명과학실험 수업이 어떻게 진행되었고, 수업을 위한 준비는 어떻게 했나요?","a":"생명과학실험 수업은 이 과목에 관심을 가지는 학생들이 신청해서 밤 시간을 이용해 진행된 수업입니다. 실험에 잘 임할 수 있도록 교과서를 미리 읽어 내용을 파악했습니다."},{"q":"이 수업에서 어려웠던 것이 무엇이었고 어떻게 대응하셨나요?","a":"(5초 정도 고민함) 양파의 원형질 분리를 관찰하는 실험에서 양파의 껍질을 잘 분리하는 것이 어려웠습니다. 그래서 집에서 미리 연습해 갔습니다."},{"q":"생명과학2 시간에 <이기적 유전자> 읽었다는데, 이 책을 읽게 된 동기와 책의 내용을 간략히 설명해 주세요.","a":"진화에 방향성이 없다는 말을 이해하고 싶어서 이 책을 읽게 되었습니다. 이 책은 심해 열수구에서 우연히 생기게 된 유전자가 증식하며 진화해 생명이 되어가는 과정을 알려준 책이었습니다."},{"q":"저자의 생각과 반대되는 의견이 있었나요?","a":"이 책의 저자는 유전자에 새겨진 생명이 타고난 이기성을 인간의 이성으로 극복할 수 있다고 했습니다. 그 점에는 동의하지만 저는 인간이 아닌 다른 동물들도 이기성을 극복할 수 있다고 생각했습니다."},{"q":"인간이 선천적인 이기성을 극복할 수 없고, 동물은 극복할 수 있다는 건가요?","a":"동물도 인간처럼 유전자의 이기성을 극복할 수 있다고 생각했습니다."},{"q":"미적분 시간에 테일러급수와 맥클로린 급수로 초월함수를 분석하는 탐구를 진행했는데, 이 탐구를 하게 된 동기가 무엇이고 어떻게 진행했나요?","a":"다항함수의 경우에는 미분, 적분이 매우 쉬운 반면에 초월함수는 어렵습니다. 그래서 근사를 통해 초월함수를 쉽게 분석하고 싶어서 이 탐구를 진행했습니다. 관련 지식을 배우고 y=e^x를 근사해 보았습니다."},{"q":"이 내용이 미적분 교과서에는 없는 내용이기 때문에 쉽지는 않았을 것 같은데, 어떻게 공부했나요?","a":"교과서에는 없는 내용이기 때문에 쉽지는 않았습니다. 그래서 교과 선생님께 질문을 해서 여러 번 미분하는 방식을 사용하면 근사가 쉽다는 것을 배웠고, 테일러급수와 맥클로린 급수가 등장한 배경 등은 동영상 플랫폼을 이용하여 학습했습니다."},{"q":"이건 좀 재미있는 질문인데, 1학년 진로와 직업 교과에서 ‘나는 쉴 때 잘 쉬는 여유가 있고 일상생활에서 즐거움을 잘 찾아내는 삶을 살고 싶습니다’라는 긍정 선언문을 만드셨네요. 수의사는 이렇게 사는 것이 가능하다고 생각하나요?","a":"수의사는 생명을 구하는 직업이기 때문에 직업에 성실히 임해야 한다고 생각합니다. 따라서 쉴 때 오히려 열심히 쉬고, 즐거움도 잘 발견하여 깨끗한 정신으로 직업생활을 해야 한다고 생각합니다."},{"q":"수학과제탐구시간에 탐구한 SIR 모델에 대해 간략하게 설명해 주세요.","a":"SIR 모델은 전염병의 진행 예측에 사용되는 모델입니다. 기존 모델은 인간 집단의 예측만 가능한데, 여기에 동물 변수를 추가해서 인수공통감염병의 예측에 사용했습니다."},{"q":"그럼 여기에 필요한 데이터는 어떻게 얻었나요?","a":"제가 이 탐구를 진행한 목적이 인수공통감염병에서는 상호작용으로 인해 더 많은 감염자가 발생한다는 가설을 검증하기 위함이었기 때문에, 데이터를 쓰지는 않고 변수를 조정하며 여러 가지 결과 값을 얻는 탐구 방식을 사용했습니다."},{"q":"시뮬레이션을 하셨단 거군요?","a":"네 그렇습니다!"},{"q":"코딩도 직접 한 거고요?","a":"(끄덕이며) 네 그랬습니다.후배들을 위한 조언 조교님께서 노크를 통해 면접 시간을 알려주시는데, 노크 소리를 듣고 긴장할 수도 있습니다. 소리를 듣고 너무 멍해지지 말고 하던 말 차분히 하는 것이 좋습니다."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(2권)」","year":"2025학년도"},{"univ":"서울대학교","dept":"간호대학","jeonhyeong":"학생부종합(지역균형전형)","method":"생기부 활동 관련 질문 → 답변 내에서 추가 질문 →학과 지원을 결심한 계기","notes":"면접 시작하면 대기실에서 생기부 자료를 비롯해서 아무것도 볼 수 없습니다. 불안한 부분은 미리 다 숙지해 놓는 것이 필요합니다.","qa":[{"q":"심화수학을 수강했던데 어떤 활동과 노력을 했나요?","a":"심화수학에서는 조별로 모여서 팀원들끼리 문제를 풀어내는 활동을 했습니다. 제가 그때 팀장을 맡았었기 때문에 문제를 미리 먼저 공부해놓고 친구들에게 설명하는 것까지 연습해서 수업에 참여하려고 노력했습니다."},{"q":"생명과학에서 NK세포에 대해서 알아본 적이 있던데 어떤 배경지식을 가지고 어떻게 공부했나요? 어렵지는 않았나요?","a":"생명과학에서 면역반응에 대해 배운 내용을 바탕으로 했습니다. 특히 비특이적 면역반응과 특이적 면역반응 중에서도 면역세포와 연관된 특이적 면역반응에 집중했습니다. 말씀하신 것처럼 NK세포가 수업 시간에 배운 개념은 아니었기 때문에 공부하기 위해서 우선 신뢰성 있는 자료를 찾으려고 노력했습니다. 제가 1,2학년 동안 도서부 활동을 했기 때문에 책을 접할 기회가 많이 있었고 NK세포에 대한 책도 활동을 하면서 틈틈이 찾아봤습니다. 그래서 ‘생물학 명강’이라는 책을 찾아서 읽었고 NK세포가 감염된 세포나 암세포에 MHC 분자가 없어도 감지해서 죽일 수 있다는 사실을 배울 수 있었습니다."},{"q":"책이 어렵지는 않았나요?","a":"도서부 활동하면서 제 독서 수준을 잘 알고 있었기 때문에 충분히 이해할 수 있는, 생명과학1의 수준에 맞는 책을 골라서 읽었습니다. 또 제가 이것 관련해서 발표 활동도 했었는데 발표하기 전에 선생님께 찾아가서 제가 이해한 내용이 맞는지 확인하는 과정을 거쳤기 때문에 잘 이해했다고 생각합니다."},{"q":"3학년 때 특수건강진단에 관심을 가져서 탐구활동을 했다고 했는데 왜 관심을 가졌나요?","a":"제가 ‘아픔이 길이 되려면’이라는 책을 인상 깊게 읽었기 때문입니다. 이 책은 제가 학교 다니면서 너무 과학 과목만 많이 수강하고 있는 것이 아닌가 하는 생각에 인문학적 소양을 길러보고자 직접 골라서 읽은 책입니다. 이 책은 사회적 약자들이 건강상의 상해를 입은 내용이 나오는데, 저는 그중에서도 특히 산재를 입은 피해자들에 대한 이야기가 가장 인상깊었습니다. 그래서 이 피해 사실을 입증하는 것에 증거 자료가 될 수도 있는 특수건강진단에 관심을 가지게 되었습니다. 위험 사업장에서의 근로자들에게서 위험 물질이 얼마나 검출되는지에 대한 호기심을 바탕으로 실험 설계도 했습니다."},{"q":"그럼 그 때 했던 실험 설계 활동에서 사용한 개념에 대해 말해보세요.","a":"이때 화학2 수업을 듣고 했던 활동이라서 화학2에서 배운 개념을 사용했습니다. 분광광도법과 어는점 내림 측정이란 방법을 사용했는데, 어는점 내림 측정은 순수한 용매와 용질을 섞은 용매의 어는점 차이를 측정해서 분자량을 알아내는 방법입니다. 이 방법을 통해서 폐수 속 물질이 아닐린이라는 것을 알아냈습니다. 분광광도법도 분자량 측정같이 정성 분석이나 정량 분석에 많이 쓰이는 방법이라서 했고, 제가 다른 실험에도 사용한 개념이라 잘 이해하고 있어서 사용했습니다."},{"q":"화학2에서 배운 개념 이외에 새롭게 알게 된 내용이 있나요?","a":"기체 크로마토그래피가 있습니다. 이것은 제가 2학년 때 박층 크로마토그래피, TLC에 대해 배웠던 내용을 연장해서 탐구해본 내용입니다. 용매를 사용하는 TLC랑 다르게 이동상을 기체로 해서 시료를 밀어내고 그 이동속도 차이에 따라서 정성 분석과 정량 분석을 할 수 있는 방법입니다."},{"q":"건강교육을 주제로 한 활동은 어떤 학술자료를 가지고, 어떻게 했나요?","a":"자료는 학술 사이트에서 건강교육을 검색어로 해서 나온 자료들을 전체적으로 다 보려고 했습니다. 제가 학생으로서 건강교육의 문제점이라고 생각하는 것이 학생들의 흥미 미반영, 같은 내용의 반복, 이론적 내용 위주라고 생각해서 그 부분을 보완하려고 했습니다. 설문조사도 같이 해서 친구들이 듣고 싶은 건강교육 주제에 대해서 알아보고 그걸 바탕으로 친구들과 함께 모의수업을 진행해 봤습니다."},{"q":"활동 내용은 무엇인가요?","a":"저는 주제 중에서도 약품 복용에 대한 모의수업을 만들어서 친구들과 발표했습니다. 약품 복용도 너무 어려운 내용이 아니라 약을 어떻게 하면 목 넘김이 좋게 먹을 수 있을지나 폐의약품 분리배출 방법, 그리고 항생제에 대한 오해 같은 내용을 다뤄서 만들었습니다."},{"q":"간호에 관심 가지게 된 계기 얘기해주세요.","a":"저는 학교에서 과학 과목을 수강하면서 그중에서도 생명과학에 관심을 가지게 되었습니다. 그래서 인체에 대한 호기심을 가지게 되었고 의료 직종에 대한 꿈을 꾸게 되었습니다. 하지만 학업뿐만 아니라 1,2학년 동안 봉사활동을 하면서 제가 도움을 주었을 때 친구들에게서 받는 웃음이나 감사 인사의 가치를 느꼈습니다. 그래서 더 가까이서 사람이 건강하게 살 수 있도록 할 수 있는 간호라는 길을 걷기로 했습니다. 특히나 저는 정신건강 쪽에 흥미를 가지고 있기 때문에 앞으로 정신과 간호사로서 활약하는 간호사가 되고 싶습니다.후배들을 위한 조언 면접 분위기는 대화하는 분위기에 가까웠던 것 같습니다. 교수님들이 질문도 천천히 해주시고 바로 질문하시는 게 아니라 '생명과학에서 00에 대해 배운 거 기억나시죠?' 라고 하시면서 서론부터 차근차근 말씀해주셨기 때문에 중간에 생각할 시간도 좀 있었습니다. 학과 관련해서 기본적인 인성 질문이나 생기부 질문에 대한 답변을 잘 준비해갔다면 면접장에서는 교수님들과 대화하고 오는 거라고 최면을 걸면서 긴장을 좀 덜고 면접 보는 것이 좋을 것 같습니다. 면접 시작하면 대기실에서 생기부 자료를 비롯해서 아무것도 볼 수 없습니다. 저 같은 경우에는 조에서 두 번째로 면접을 봐서 그럴 시간이 없었지만 혹시 뒤 순서라면 기다리는 동안에는 그냥 자기가 제일 불안하게 답변하는 부분을 연습하면서 시간을 보내면 될 것 같습니다."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(2권)」","year":"2025학년도"},{"univ":"서울대학교","dept":"경제학부","jeonhyeong":"학생부종합(지역균형)","method":"인사->국제경제 질문->확률과통계 질문->수업량유연화 질문->세계문제와미래사회 질문->진로 질문->지원동기","notes":"","qa":[{"q":"오래 기다렸죠? 생활기록부에 적힌 활동 몇 가지만 확인할게요.","a":"네"},{"q":"국제경제 과목에서 밀턴프리드먼이 세계대공황의 원인을 시장실패가 아닌 정부실패라고 주장한 바를 탐구했는데, 프리드먼은 어떤 근거로 이렇게 주장했나요?","a":"세계대공황의 정확한 시작 원인은 알 수 없습니다. 하지만, 프리드먼은 경제 위기에 대한 정부와 연준의 대처가 세계대공황을 불러일으켰다고 주장합니다. 경제가 위축되어 갈 때 정부와 연준이 확대 재정정책을 하며 경기를 부양했어야 하는데 오히려 긴축하여 문제가 심각해졌다고 합니다."},{"q":"연준이 재정정책을 하나?","a":"아, 정부가 확대재정정책을 하고, 연준이 금리를 낮췄어야하는데 오히려 정부는 긴축하고 연준이 금리를 올린 것이 원인이라고 주장합니다."},{"q":"경제 상황에 대한 무지와 잘못된 판단 때문이라는 것이군요.","a":"네"},{"q":"확률과 통계에서 위험자산과 수익률을 탐구했는데, 분산투자의 중요성이 무엇인가요?","a":"자산의 전체 수익률은 위험자산에 위험자산 수익의 확률을 곱한 값과 무위험자산에 무위험자산 수익의 확률을 곱한 값을 더하여 나옵니다. 분산투자를 하면 위험자산과 무위험 자산에 적절히 배분하여 투자하므로 안전한 결과를 예상할 수 있습니다."},{"q":"수익률이 높은 상품에만 투자하는 사람에게 어떤 조언을 할 수 있을지 말해볼까요?","a":"수익률이 높다는 것은 돈을 얻을 확률이 높지만, 그만큼 위험성도 같이 커집니다. 따라서, 원래 가지고 있던 돈을 잃을 가능성도 있습니다. 이에, 적절히 분산투자 하는 것이 바람직합니다."},{"q":"사람마다 위험자산에 투자하려는 성향이 다른데, 이 차이는 어디서 오는건가요?","a":"손실을 피하려는 성향인 위험회피성향과 위험성에 대해 얼마만큼의 대가를 지불할 수 있는지인 위험 프리미엄에서 차이가 옵니다."},{"q":"수업량유연화에서 프랑스가 법인세율과 소득세율을 인하하여 불평등을 완화한 것을 탐구했는데, 어떤 과정으로 불평등이 완화되었죠?","a":"우선, 법인세율을 인하한 결과 기업의 세금 부담이 적어지므로, 해외의 기업이 프랑스 내로 많이 진입했습니다. 그에 따라 세율은 줄었지만, 정부가 걷은 전체 세금은 늘었고, 이것으로 사회적 약자를 지원하면서 불평등이 완화되었습니다."},{"q":"늘어난 세금으로 복지정책을 시행했다는 것이군요.","a":"네. 또한, 기업이 많이 들어오면서 일자리도 창출되고, 소득세율도 함께 인하되면서 근로의욕이 고취되고, 노동도 활성화되었습니다."},{"q":"이러한 정책이 우리나라에도 시행될 수 있을까요?","a":"저는 완벽히 적용될 수는 없다고 생각합니다. 프랑스는 우리나라와 다른 노동시간, 노동환경 등을 가지고 있습니다. 노동시간은 우리나라보다 적지만, 임금은 높고, 노동위원회라는 조직도 있어 좋은 노동환경을 갖추고 있습니다. 또한, 프랑스는 지방분권이 매우 잘 되어 있습니다. 프랑스는 지방정부의 힘이 적고, 중앙정부가 대부분을 결정하는 우리나라와 달리, 각 지역의 특성과 환경을 고려하여 지역에 맞는 세율을 정할 수 있습니다. 지방분권이 잘 되어있지 않은 우리나라에서 일률적으로 세율을 정한다면, 프랑스와 같은 결과는 힘들 것으로 보입니다."},{"q":"세계문제와 미래사회에서 원격의료를 반대했는데, 근거가 뭐였나요?","a":"첫 번째로는 거대병원과 지방 병원의 격차가 커진다는 것입니다. 사람들은 원격의료가 시행된다면, 수도권의 거대병원으로 쏠릴 것이고, 동네 병원은 망해갈 것입니다. 두 번째로는 의료사고가 발생했을 때 책임소재가 불분명하다는 것입니다. 의료사고가 발생했을 때, 의료행위를 지시한 의사, 행위를 실제로 한 환자, 원격의료 기기를 제공한 기업 사이에 책임 소재를 가리기가 어렵다는 것입니다."},{"q":"진로에서 탄소배출권 거래제의 부작용을 탐구했는데, 이러한 부작용이 있음에도 아직까지는 가장 실효성 있는 방안으로 평가되고 시행되는데, 탄소배출권이 가지는 장점은 무엇인가요?","a":"탄소배출권 거래제는 기업들이 모두 합리적이고, 이기적이라는 전제에서 출발합니다. 이러한 합리성에 근거를 두고, 각 정부나 기업에게 탄소 배출권을 할당하고, 남거나 부족하면 사고팔 수 있게 하므로써 배출된느 탄소의 총량을 유지시키거나 줄일 수 있습니다."},{"q":"탄소배출권 거래제가 부작용이 있다고 했는데, 다른 대안이 있나요?","a":"저는 탄소배출권 거래제가 면죄부의 역할을 하고 있어, 인간의 도덕성을 고려한 다른 정책이 필요하다고 생각합니다. 그 예로는 기업들이나 국가 간의 돈독한 협약이나 조약을 체결하여야 한다고 생각합니다."},{"q":"탄소를 적게 배출하자는 약속을 통해 해결한다는 거죠?","a":"네"},{"q":"시간이 얼마 안 남았는데, 마지막으로 우리 서울대학교에 지원하게 된 동기 간단히 말해볼까요?","a":"저는 경제적 정의를 실현하는 것이 목표입니다. 고등학교에 진학한 이후, 경제에 관심이 생겼고, 동시에 부정의한 현상도 접하였습니다. 그래서 이러한 부정의를 경제학의 방식으로 해결하고 싶다는 꿈이 생겼습니다."},{"q":"그러면 직업은 어떻게?","a":"경제적 정의를 실현하기 위해서는 현재의 부정의한 부의 취득과 이전이 교정되어야 한다고 생각합니다. 그래서 이러한 교정을 먼저 한 후, 경제적 정의를 실현하는 직업을 갖고 싶습니다."},{"q":"네, 잘 들었습니다. 시간이 다 되었네요. 수고했어요.","a":"네 감사합니다. 안녕히 계세요. 후배들을 위한 조언 모든 활동을 깊이 있게 숙지할 것.자신의 주장(또는 탐구)와 반대되는 주장도 공부할 것.2024 대입 면접후기"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"서울대학교","dept":"경제학부","jeonhyeong":"학생부종합(지역균형)","method":"▶ 면접시간 : 10분▶ 면접위원 : 2명▶ 면접절차 : 대기실에서 대기하다가 면접실로 1명씩 입장","notes":"","qa":[{"q":"남들이 안 해봤을 만한 생각 얘기해 보세요.","a":"탄소배출 줄이기 캠페인이랑 바자회 엮어서 활동한 거"},{"q":"물건에 대한 가격은 어떻게 정했나?, 가상 화폐는 어떻게 만들었나?, 가상 화폐는 또 다른 데 쓰일 수 있는 건가?","a":""},{"q":"그거 말고 또 얘기해 보세요.","a":"조삼모사랑 원리합계 엮어서 발표한 거"},{"q":"이런 내용 책에도 많을 텐데 보지 못했나?","a":"저는 영상을 참고했습니다.[꼬리질문] 그럼 지원자가 완전히 혼자 한 생각은 아닌거네?그렇지만 그 내용과 등비수열의 활용인 원리합계를 연관지어 발표해야겠다는 생각은 스스로 했습니다.아.. 등비수열~ (이러고 넘어가심)"},{"q":"또 얘기해 보세요.","a":"고민중"},{"q":"(다른 교수님이) 다른 활동 물어볼게요. 죄수의 딜레마가 뭔지 설명해 보세요.","a":"개념 + 예시 설명"},{"q":"코즈 정리가 뭔지 설명해 보세요.","a":"개념 설명"},{"q":"죄수의 딜레마랑 코즈 정리의 차이점을 말해보세요.","a":"살짝 애매하게 답변함"},{"q":"달러 강세로 인한 국제 동향이라는 보고서를 썼는데 공부한 내용 말해보세요.","a":"달러 강세가 우리나라, 중동 산유국에 미친 영향 설명 + 실제로 사우디아라비아 경제성장에 달러 강세가 영향을 미쳤음을 설명"},{"q":"그 자료는 어디에서 찾은 거예요?","a":"인터넷 기사에서 사우디아라비아 통계청이 직접 이야기한 것을 보았습니다"},{"q":"공공재 부족 현상에 대해 설명해 보세요.","a":"공공재는 비배제성과 비경합성을 띠고 있는 재화입니다."},{"q":"(더 설명하려고 하는데 끊으심) 오 비재제성이랑 비경합성 설명해봐요.","a":"(밖에서 시간 끝났다고 노크했는데 괜찮으니까 설명하라고 하심) 한 문장씩 간단하게 대답"},{"q":"마지막으로 경제는 어디서 배웠어요?","a":"학교에서 경제 수업 들었고 공동 교육과정으로 실용경제, 국제경제, 경제수학 들었습니다."},{"q":"학교 말고 다른 데서 배운건가?","a":"다른 고등학교에서 들었습니다."},{"q":"아 학교에서 수업이 안 열려서?","a":"네!후배들을 위한 조언 편하게 대화하는 느낌이었음. 내가 답변한 내용 중에 궁금한 게 생기시면 질문을 했는데 압박 면접하는 느낌이 아니라 진짜 궁금해서 물어보시는 느낌이었음.2024 대입 면접후기"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"서울대학교","dept":"바이오시스템소재학부","jeonhyeong":"학생부종합(일반)","method":"제시문 풀이(45분) -> 면접(15분)(몇 번까지 풀었는지 질문 -> 답변 -> 질문 혹은 힌트 주심)Ÿ 필기구는 고사실에서 제공. 개인 필기구나 아날로그 시계까지도 반입 못함.Ÿ 면접실은 화이트보드 구비되어 있었고 면접관 두 분 계셨음.Ÿ 이번 수학 제시문은 크게 2문제. 문제당 꼬리문제 4개씩 총 8문항.","notes":"1번 문항은 공통+미적분에서 출제됐고, 난이도는 역대 기출에 비해굉장히 쉬웠음. 2번 문제는 확률+등비수열 합에서 나왔고 어려웠음.Ÿ 제시문 푼 후 대기시간은 25분 정도. 어떻게 설명할지 구상할 시간은있었지만, 학과마다 조마다 다를 수도 있음. 그동안은 본인이 푼 건뒤집어두고 대기.","qa":[{"q":"몇 번까지 풀었나요?","a":"2번의 2번까지 풀었고 3번은 풀이 방법 정도만 생각했습니다."},{"q":"네 설명해 보세요, 답만 간결히. (마지막에서 두 번째라 앞에서 많이 들으셨던 듯)(문제 풀이 중)","a":""},{"q":"근데 a의 부호에 따라 바뀔 것 같은데?","a":"아 네. 문제 풀고 대기하면서 생각해 보니 그럴 경우에는 ~ (답변)"},{"q":"r(x)랑 s(x) 순서가 그게 맞을까?","a":"아 반대가 맞는 것 같습니다.(그리고 계속 풀이. 나는 중간에 문제를 잘못 푼 부분이 있어서 다시 계산하는데 시간이 좀 걸림. 교수님들은 위처럼 힌트 많이 주심. 2번으로 넘어가자 하셔서 양해 구하고 1번 마지막 답만 말씀드림. 이후 2번 풀이)2번의 2는 ~한 상황이므로 정리하면 등비급수의 합으로 정리되고, 이 등식을 만족하는 p값이 답일 것 같습니다. 1/2이랑 등식을 만족하는 다른 수일 것 같은데 찾지 못했습니다. 2번의 3은 ~한 상황이므로 마찬가지로 등비급수의 합으로 표현되고 정리하면 …(위 문장 말하면서 시간 종료, 시간 지나도 어느 정도 말 끝마칠 때까진 기다려주심.)후배들을 위한 조언 Ÿ 방마다 다를 순 있지만 수학 제시문은 대체로 친절하신 편, 본인이 풀었다면 자신감 가지고 말씀드리면 됨. 우리 방 교수님들은 웃으면서 말하셔서 엄숙한 분위기는 아니었음. 어느 정도 면접 연습하고 나서는 문제를 잘 풀어내는 게 중요한 듯. (수학면접 기준)Ÿ 힌트를 되게 많이 주심. 나는 처음에 틀려서 당황하면서 풀었는데, 보시다가 중간에 잘못되면 다시 한번 볼래요? 그게 맞을까요?(위협적 어조 아님) 이런 식으로 정정도 해주심. 특히 나는 마지막에서 두 번째 순서라 이미 앞선 학생들이 푸는걸 보셔서, 뒷순서면 어느 정도 스킵해서 해도 될 것 같음. 답변이 산으로 가면 문제에서 요구하는거 짚으면서 이건 뭐죠? 이렇게 물으시기도 함.Ÿ 겁먹지 말고 준비한 대로 문제를 차분히 풀면 됨. 교수님들 질문도 최대한 풀 수 있도록 유도하는 방향이라 틀리거나 못 풀어도 차분하게 다시 해보면 됨. 나는 좀 떨었지만 1차 붙었다면 뽑을 생각 있는 거니까 너무 긴장하지 말고 파이팅!2024 대입 면접후기"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"서울대학교","dept":"사회학과","jeonhyeong":"학생부종합(일반)","method":"발열 체크 및 손 소독 → 면접 대기실 입실 → 준비실 이동 → 30분간 면접 준비(제시문 면접 문제 풀이) → 15분간 면접 진행 → 퇴실서울대학교 사회과학대학 제시문 면접은 30분의 대기시간 동안 복도 통로에서 준비합니다. 이때 동시에 많은 면접자들이 함께 준비하고 수시로","notes":"조교분들이 움직이셔서 소음이 상당히 발생하고 조명도 없어서 어둡습니다. 다만 귀마개를 사용할 수 있으므로 소음에 민감한 분들이라면 귀마개를 꼭 챙겨가세요.","qa":[{"q":"역사학의 허구성과 사실성의 혼재가 혼잡성이라고 할 때(제시문), 다른 학문 분야에 혼잡성이 나타난 사례를 설명하시오.","a":"사회학이 혼잡성을 가진 대표적인 학문이라고 생각합니다. 사실에 대한 탐구가 사회학의 사실성에 해당한다면, 사회학적 상상력을 통해 사실 이면의 내용을 추론할 수 있다는 점에서 허구성을 가지기도 하므로 사회학은 혼잡성을 가집니다."},{"q":"현상 이면에 진정한 원인이 있었던 사례(제시문 내용)를 바탕으로 추가적인 사례를 제시하시오.","a":"(생활기록부 내용) 2학년 사회문제 탐구 시간에 기후위기 교육 횟수와 기후 위기 심각성 사이의 상관관계를 연구했을 때, 기후 위기 교육 횟수가 증가해도 관심 피로 현상으로 인해 기후 위기 교육의 효과가 증대되지 않음을 파악했습니다. 이것이 추가적인 사례라고 생각합니다.후배들을 위한 조언 면접 답변이 교수님 방에서 진행됩니다. 중간에 교수님의 전화기가 울릴 수도 있습니다. 제가 그랬습니다. 어떠한 변수가 발생하더라도 침착하세요. 오히려 예상치 못한 변수에 침착하게 대응하는 모습이 좋게 평가될 수 있습니다. 저도 면접실을 나갈 때 교수님께서 씩씩하다고 칭찬해 주셨습니다.서울대학교 사회과학대학 면접을 위해 면접 장소에 갔을 때, 문 앞에서 각 학과 선배님들께서 응원을 아끼지 않으셨습니다. 이른 아침부터 큰 목소리로 응원해 주신 선배님들 덕분에 크게 긴장하지 않고 편안한 마음으로 면접에 임할 수 있었습니다. 제가 만약 서울대학교에 진학하게 된다면 이 글을 읽고 있을 후배님들을 만나 제가 받은 응원 그 이상을 드리겠습니다.2024 대입 면접후기"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"서울대학교","dept":"생명과학부","jeonhyeong":"학생부종합(지역균형)","method":"생2 질문 -> 생활과 윤리 질문 -> 3학년 동아리 활동 질문Ÿ 면접 전 대기실에서 면접 준비할 시간이 있었음. 일찍 가서 생기부나 마지막 정리하는 게 좋을 것 같음","notes":"Ÿ 면접실에는 1명씩 들어가고 교수님들이 친절하셔서 크게 긴장할 필요 없음Ÿ 중간에 말이 길어지면 알아서 말을 끊어주시니 답변이 길다고 걱정할 필요 없음","qa":[{"q":"크리스퍼 유전자 가위에 대해서 탐구했던데 그 원리에 대해 설명해보세요.","a":"크리스퍼 유전자 가위는 세균의 면역체계에서 비롯되었습니다. 그 원리를 말씀드리자면, 세균에 바이러스가 침입하면 일부 세균은 살아남아 바이러스의 DNA일부를 잘라 자신의 크리스퍼 영역에 삽입해두고 ~~~ (쭉 설명)"},{"q":"크리스퍼 유전자 가위의 문제점으로는 무엇이 있을까요?","a":"첫 번째로 계층 간 갈등이 발생할 수 있습니다. 이 기술의 사용에는 비싼 비용이 요구되어 사회적 격차를 더 키울 있습니다. ~~ 두 번째로 잘못된 유전자 편집이 일어날 수 있습니다. 99% 정확도를 가진 기술이라는 보고가 있지만 20개 정도의 프로그래밍된 염기서열이 편집하고자 하는 유전자와 비슷한 유전자에 잘못 결합하여 ~~"},{"q":"유전체에 잘못 결합하여 잘못 편집될 확률이 어떻게 되나요?","a":"정확히는 모르겠으나 유전체의 정보가 굉장히 많기 때문에 잘못 편질될 확률은 매우 적을 것 같다고 생각합니다. (생각도 못한 질문이어서 좀 당황했고 그냥 간단히 말하고 빨리 다음 질문을 받음)"},{"q":"자살에 대해서 활동을 했던데 자살이 개인의 권리이다라는 주장에 찬성하는 입장과 반대하는 입장에 대해서 말씀해 보세요.","a":"(잘은 기억이 안 남) 저는 자살은 개인의 권리라고 생각했습니다. 반대하는 입장에서는 칸트의 입장에서 자기보존의 본성에 위배되어 자살 반대, 찬성하는 입장에서는 공리주의 입장에서 쾌락 추구, 고통 회피의 인간 본성으로 자살 찬성. (이후 추가적으로) 3학년 때는 자살을 과학적 측면에서 알아보면서 자살은 개인의 권리가 아니라고 생각이 바뀌었습니다. (이에 대한 근거 제시)"},{"q":"자살이 개인의 권리라고 볼 수 있는 기준?에 대해서 말씀해보세요. 예를 들면 어린아이들에게는 자살이 개인의 권리가 아니라던지..","a":"(답변 내용이 기억 안 남.)"},{"q":"기억의 저장 메커니즘에 대해서 말씀해 보세요.","a":"기억의 저장 메커니즘의 핵심은 장기증강입니다. 충분한 반복적인 자극을 받으면 신경세포 전 뉴런에서 글루타메이트라는 신경전달물질이 분비됩니다. ~~ (준비한 대로 답변하다 중간에 끊으심)"},{"q":"(질문이 정확히는 기억 안 나지만 다음과 같은 맥락이었음) 기억은 삭제된다 생각하나요? 아니면 남아있어서 나중에 다시 생각해 낼 수 있다고 생각하나요?","a":"저는 기억은 영구 삭제될 수 있다고 생각합니다. 시냅스에서 뉴런 간 연결이 어느 정도 이어진다면 기억이 복구될 수 있지만 뉴런 간 연결이 완전히 ~(잘 기억 안 남). 또한 실제로 여러 과학자들이 기억은 머릿속에 남아있는 것이 아닌 영구적 삭제가 될 수도 있다는 사실을 본 적이 있어 기억이 영구 삭제될 수 있다고 생각합니다.수고하셨어요~감사합니다~후배들을 위한 조언"},{"q":"질문에 대한 답변을 잘 모르겠을 때는 간단히 답하고 빨리 다음 질문받아 열심히 답변하는 게 더 좋을 수도 있음.","a":""},{"q":"면접 준비할 때 전공 관련 내용만큼은 이전에 했던 활동보다 더 깊게 이해하고 가는 것이 중요함. 특히 원리/메커니즘은 빠삭하게 알아둬야 함","a":""},{"q":"예상하지 못한 질문은 즉석에서 바로 답하는 능력이 요구되므로 평상시 준비할 때 과하다 싶은 예상 질문 뽑아서 즉석에서 말하는 연습도 많이 해봐야 할 듯함.2024 대입 면접후기","a":""}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"서울대학교","dept":"서어서문학과","jeonhyeong":"학생부종합(일반)","method":"면접 대기실에서 대기 → 면접 준비실에서 면접 구상(30분) → 면접실로 이동 → 지원동기 및 전공 관련 질문 → [인문학] 답변 → [사회과학] 답변 →꼬리 질문 및 답변(면접 시간 15분)대기실 앞에서 나누어주는 면접 번호표를 수험표 등에 붙여 보관하지 않도","notes":"록 유의해 주세요. 면접 번호표를 종이에 붙였다가 떼면 잘 찢어집니다.2024학년도부터 면접 대기실에서 대기 시에 사전에 준비한 면접 자료를 볼수 없게 되었습니다. 면접 순서가 뒤쪽이라면 상당히 지루할 수 있습니다.","qa":[{"q":"서어서문학과의 다양한 전공과목 중 어떤 과목을 중점적으로 배워보고 싶나요?","a":"저는 스페인어를 사용하는 다양한 국가, 특히 남미 국가의 문화에 대해 구체적으로 배우고 싶습니다. 저는 언어를 배운다는 것은 단지 언어만을 배우는 것이 아닌 그 나라의 문화까지 함께배우는 것이라고 생각합니다. 저는 학교 수업시간에 UN 지속가능발전목표에 관해 구체적으로탐구하고 난민기구에 5년 이상 지속적으로 기부하는 등 국제적인 난민 문제에 관심이 많습니다. 특히 저는 발전을 위한 자원은 풍부하지만 질서정연하지 못한 정치체계 때문에 난민이 많은 남미 지역의 문제에 관심이 많습니다. 따라서 저는 서어서문학과의 다양한 전공과목 중 스페인어를 사용하는 다양한 국가의 문화, 특히 남미의 문화에 대해 배우고 싶습니다.서울대학교 일반전형 면접은 제시문 기반으로 이루어집니다. 인문계열의 경우 인문학과 사회과학 지문이주어집니다. 제시문의 구체적인 내용에 따라 답변 내용을 구성하면 됩니다. 저는 아래의 형식에 따라답변을 진행하였습니다."},{"q":"[인문학] 1번 문제에 답변해 주세요.","a":"[인문학] 1번 문제에 답변하겠습니다. 제시문 (가)는 사람을 신뢰하는 것과 사실을 신뢰하는 것의 차이를 설명하고 있습니다. 사람을 신뢰하는 것은 그 사람과의 유대 관계에 기인한다는 점에서, 사실을 신뢰한다는 것은 그 근거에 기인한다는 점에서 차이가 있습니다. 제시문 (다)에서는 여행 중에 길을 모르는 사람이 낯선 사람을 믿지 않음에도 그가 알려준 길을 따라 간다고설명하고 있습니다. ··· 제시문 (가)와 (나)를 바탕으로 할 때, 여행 중인 사람은 낯선 사람이말해준 것이 사실일 것이라는 전제 하에, 즉, 낯선 이의 말을 사실로서 신뢰하므로 그가 알려준 길을 따라감을 알 수 있습니다. 이상으로 1번 문제의 답변을 마칩니다."},{"q":"[인문학] 2번 문제에 답변해 주세요.","a":"[인문학] 2번 문제에 답변하겠습니다. 제시문 (나)를 바탕으로 (라)의 사회가 유지되는 이유는 서로에 대한 신뢰가 높은 국가에서 개개인은 상대방이 자신에 대해 갖는 신뢰감과 유대 관계를 고려하기 때문입니다. 국가 신인도가 낮은 A 국가와 국가 신인도가 높은 B 국가가 있다고 할 때, A 국가의 사람들이 신뢰를 저버린 중대한 범죄를 저지른다고 해도 해당 국가의 사람들은 형사적 처벌만을 받을 뿐 사회적 질타를 받지는 않습니다. 반면에 B 국가에서 신뢰를 저버리는 중대한 범죄를 저지를 때 사람들은 형사적 처벌을 받을 뿐만 아니라 사람들로부터 사회적 질타를 받을 것입니다. 이와 같은 점을 고려할 때, 서로에 대한 신뢰가 높은 국가에서 사람들은 자신에 대해 사회가 갖는 기대감과 서로에 대한 유대 관계를 고려하여 행동하기 때문에 (라)에 제시된 사회가 유지된다고 생각합니다. 이상으로 2번 문제의 답변을 마칩니다."},{"q":"[사회과학] 1번 문제에 답변해 주세요.","a":"[사회과학] 1번 문제에 답변하겠습니다. 제시문 (가)는 소득이 개인의 살의 전반적인 수준을 판단할 수 있는 지표가 된다고 설명하고 있습니다. 제시문 (나)는 소득이 개인이 갖춘 역량 중 하나일 뿐이고, 개인의 구체적인 삶의 수준을 파악할 수 있는 지표는 역량이라고 설명하고 있습니다. ··· 이상으로 1번 문제의 답변을 마칩니다."},{"q":"[사회과학] 2번 문제에 답변해 주세요.","a":"[사회과학] 2번 문제에 답변하겠습니다. 제시문 (가)와 (나)를 바탕으로 실업 수당이 갖는 의의와 한계에 대해 설명하겠습니다. 소득의 측면에서 실업 수당은 개인이 전반적으로 인간다운 삶을 살 수 있도록 해준다는 의의를 갖지만, 개인의 개별적이고 구체적인 삶의 수준을 파악하기 어렵다는 한계를 가집니다. 역량의 측면에서 실업 수당이 갖는 의의와 한계에 대해 설명하겠습니다. 실업 수당은 개인의 역량 중 하나인 소득을 보완함으로서 부분적으로 개인의 공동체적 삶, 정치적 자유 등을 보장할 수 있지만, 인간이 처한 사회·문화적 맥락을 구체적으로 파악하기 어렵다는 한계를 지닙니다. 이상으로 2번 문제의 답변을 마칩니다.[꼬리 질문 및 답변]후배들을 위한 조언 수능이 끝나고 얼마 지나지 않아 바로 있을 면접에 지치고 힘들겠지만, 조금만 더 버티고 힘내면 정말 좋은 결과가 있을 거예요. 일반적인 생기부 기반 면접에 비해 훨씬 까다롭고 많은 사고력을 요하는 과정이지만, 서울대학교 1단계에 합격할 정도의 자질을 갖춘 후배라면, 충분히 해낼 것이라 믿습니다.2024 대입 면접후기"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"서울대학교","dept":"수리과학부","jeonhyeong":"학생부종합(지역균형면접 대기실에 입실 마감 시간까지 입실하고 유의 사항을 안내받는다.)","method":"유의 사항을 안내받은 후 자신의 이름이 불리기 전까지 면접 대기실에서 대기한다. 이름이 불리면 해당 면접실에 가서 10분 동안 면접관의 질문에 답변 후 집에 귀가한다. 면접 대기실에서 대기할 때 책을 봐도 상관이 없다.","notes":"휴대폰이나 전자기기는 제출은 안 하고 끈 채로 가방에 둔다.면접관은 두 명이다.","qa":[{"q":"인공지능 수학시간 때 만든 프로그램 설명 해주시겠어요?","a":"저는 공감AI를 만들었습니다. 인공지능에게 엄지를 올린 손을 보여주면 인공지능이 기분 좋은 것으로 인식하여 그것에 공감해줍니다. 또 엄지를 내린 손을 보여주면 인공지능이 기분이 안 좋은 걸로 인식하고 위로의 말을 해줍니다. 이런 프로그램을 만들었습니다.[꼬리질문] 이때 사용한 도구나 프로그램은 뭔가요?엔트리 프로그램을 통해 만들었고 그 프로그램명은 잘 모르는데 제 엄지 손가락을 올린 모양과 내린 모양의 사진을 엄청 등록시켜서 컴퓨터가 이를 헷갈리지 않게 학습시키는 프로그램을 사용했습니다."},{"q":"일계선형미분방정식에 대해서 탐구를 했는데 이거 설명 좀 해주시겠어요?이라는 식이 있다고","a":"일계미분방정식의 형태를 예로 먼저 들겠습니다. 가정하겠습니다. 이는 y와 y의 일차도함수로 이루어진 미분방정식입니다. 이때 변수 분리를 하고 양변을 적분해 주면 ln 가 나오고 이를 y에 대해서 나타내면 구할 수 있습니다."},{"q":"확률과 통계 시간 때 교과서에서 배운거 말고 추가적으로 학습을 했다는데 그 내용이 뭔가요?","a":"제가 동아리 시간 때 탐구했던 정규분포의 확률밀도함수의 식 유도가 있습니다. 정규분포 확률밀도함수는 그 식만 배우지 그 식이 어떻게 나왔는지는 나오지 않습니다. 그래서제가 이 함수가 어떻게 이런 식이 나오는지 궁금해서 찾아보았습니다. 먼저 원형 다트판이있다고 가정하겠습니다. 그 안에 한 점을 맞출 확률은 f(x, y)라고 할 수 있습니다. 중심을원점으로 본 극좌표라고 생각을 하면 라고 할 수 있습니다. 이때 x와 y는 독립이고극좌표에서의 확률은 이라고 했을 때 이라고 할 수 있습니다.그다음 cossin이므로 양변을 에 대해서 미분을 할 수 있습니다. 미분을해주고 식을 정리하게 되면 꼴이 나오게 됩니다. 이때 확률밀도함수를 전체부분에서 적분하면 1이 나온다는 것과 이를 사용하기 위해 가우스적분을 이용하면 A값이라는 것을 알 수 있습니다. 여기서 k값을 알기 위해 분산을 뜻하는 식인∞인 것을 알 수 있고 이를 식에 대입하면을 이용하면 ∞정규분포의 확률밀도함수 식을 유도할 수 있습니다.[꼬리질문] 정규분포가 왜 중요한가요?(잠시 시간을 갖고) 죄송합니다. 분명 배웠던 것 같은데 지금 잘 기억이 나지 않는 것같습니다."},{"q":"확률과 통계 시간 때 가장 기억에 남는 정리가 무엇인가요?","a":"저는 이항정리가 가장 기억에 남습니다. 을 쉽게 푸는데 이용되는 이항정리는n값이 큰 수일 때도 해당 꼴의 함수를 보다 쉽게 풀 수 있어서 위대한 것 같습니다.중학교 때와 고1, 2 때는 그냥 막 전개를 했는데 이항정리를 쓰니 쉽게 풀 수 있었고실제로 많이 이용한 정리인 것 같아서 기억에 남습니다."},{"q":"원뿔곡선을 탐구했는데 원뿔곡선에 뭐가 있는지, 어떻게 자르면 원뿔곡선이 되는지 얘기해볼래요?","a":"원뿔곡선에는 원, 타원, 쌍곡선, 포물선이 있습니다. 원뿔곡선의 모양을 결정짓는 것은이심률입니다, 이심률은 원뿔의 모선과 축이 이루는 각을 , 축과 원뿔곡선이 만드는cos로 나타냅니다.평명과의 각도를 라고 할 때 cos-------- 시간 종료 --------후배들을 위한 조언 후배님들, 제가 서울대에서 전공적합 질문만 받았다 할지라도 그거만 준비해서 절대안되고 생기부 꼼꼼하게 읽으면서 준비해야 합니다. 그리고 담임선생님과 면접 자주 하시는걸 권해요. 면접은 할수록 말하는 거나 자세나 다 좋아질 수 있습니다. 그리고 해당 전공의 선생님과의 모의 면접도 추천드려요. 전공 선생님은 그 전공에 대해서 날카로운 질문들도 하실 수 있으니까요.면접 준비 오래 안 걸린다고 생각하실 수 있는데 생기부 활동 하나하나 보면서 다 외우고, 책 찾아보고, 활동한 것들 다 찾아보고, 다시 조사하고 이러는 거 쉽지 않습니다. 생각보다 오래 걸려요. 그러니까 나중에 대학 발표날 때 1차가 붙든 말든 면접 준비 계속하시는 걸 추천드립니다. 그리고 전에 안 했으면 지금이라도 자기가 보고서 쓴 거 버리지 말고 꼭 저장들 하세요. 나중에 면접 준비하려고 생기부 볼 때 활동 잘 기억 안나서 다시 찾아보는 경우가 대다수입니다. 저도 저장했었는데 잃어버려서 하나하나 찾느라 힘들었어요. 그럼 화이팅!2024 대입 면접후기"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"서울대학교","dept":"아동가족학과","jeonhyeong":"학생부종합(일반)","method":"제시문면접","notes":"제시문 문제 푸는 시간 30분, 답변 시간 15분","qa":[{"q":"혼재성이 나타난 다른 학문의 예시를 드시오.","a":"과학이라고 생각한다. 제시문에서의 혼재성은 사실성과 허구성 사이의 모호함이라고 생각한다. 얼핏 보기에 과학은 사실성만을 강조하는 학문 같지만, 과학은 허구성을 사실성으로 바꿔나가는 학문이라고 생각한다는 점에서 혼재성이 존재한다고 생각한다. 과학에서는 가설 등을 세우는데 이러한 과정이 허구성을 상정한 뒤 사실성으로 바꿔 가는 과정이라고 생각한다. 과학에서의 귀납적 추론에도 반례라는 것이 생기는데, 이것 또한 과학에서의 허구성을 보여주는 예시가 아닐까 생각된다.(뭐 대충 이런식이었던 것 같은데 기억이 잘 안난다..)[꼬리질문] 과학에서의 허구성과 역사에서의 혼재성이 가지는 차이는?허구성이 사실성으로 나아갈 수 있는 가능성의 측면에서 차이가 있다고 생각한다. 과학은 과학 기술이 점차 발전하면서 허구성이 사실성으로 나아갈 가능성이 무궁무진하지만, 역사에서의 허구성은 과거의 일과 유산, 사료이기 때문에 허구성이 사실성으로 나아갈 가능성 측면에서 가능성이 상대적으로 덜하다고 생각한다."},{"q":"(가)와 (나)의 공통점은?","a":"(가)와 (나) 모두 표면에 드러나지 않은 다양한 요소들 때문에 인과관계에 있어서 오류가 나타났다는 점에서 공통점이 있다. (가)에서는 교통사고 감소의 원인이 오직 차량스티커 때문이라며 결과에 대한 원인을 오직 한가지로 가정하고 있었지만. 실제로는 이것이 차주의 심리와도 연관이 되어 차랑스티커의 부착이 무조건적인 교통사고의 감소로 이루어지지 않는 모습을 보이기도 했다. (나)에서는 전쟁에서 돌아온 전투기만을 고려하였다가전투기의 취약 부분을 잘못 파악하는 모습을 보고, 인과관계에서의 고려 대상에 있어서제한적인 면모를 보였다고 생각했다. 따라서 두 사례 모두 이면의 요소를 제대로 파악하지 못해 인과관계에 오류가 생긴 것이다.[꼬리 질문] 차량 스티커로 인한 정확한 교통사고 인과관계를 밝히기 위해서는 어떤 조건을 도입해야 할까요?잠시 생각할 시간을 주시겠습니까?답변 시작하겠습니다. 저는 운전자가 동질적이라는 조건을 도입해야 한다고 생각합니다.앞선 제시문에서 교통사고 증감현상은 차량 스티커가 아닌 운전자의 운전 심리에 의해서도좌우되는 현상을 보았습니다. 따라서 운전 심리라는 변수를 제거하기 위해서 운전자를 동질적으로 설정하면 차량 스티커가 발생시키는 교통사고 증감현상을 자세하게 파악할 수 있을것입니다.(실제로는 이것보다 말을 잘 못한 듯..)(등등 질문이 많았다)후배들을 위한 조언 제시문 면접은 외워서 되는 것도 아니고 그냥 여러 번 풀어보고 면접 해보면서 조금씩 익히면될 것 같아요. 서울대 면접은 구상 시간도 길고, 자기 생각 물어보는 질문도 많으니 평소에도좀 창의적이고 논리적으로 생각하면서 연습을 해보면 될거예요. 기출은 몇 개 년치 꼭 풀어보고면접장에서는 그냥 쫄지 말고 자기가 구상한거 똑바로 이야기하면 후련하게 나올 수 있습니다.팟팅~!2024 대입 면접후기"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"서울대학교","dept":"원자핵공학과","jeonhyeong":"학생부종합(기회균형(오전 기준)1. 안내된 시각(08:00)까지 입실)","method":"2. 수험번호 및 본인 확인 후 명찰 배부3. 전자기기 수거 후 사전 안내 진행4. 대기실에서 호명하면 면접실 앞에서 중간대기5. 면접 후 안내 따라서 퇴실신분증, 수험표, 필기구 반드시 지참.","notes":"대기실에선 전자기기 수거 이후에 본인이 가져온 자료를 일체 볼 수 없고 자기 차례가 될 때까지 그냥 기다리셔야 합니다.","qa":[{"q":"지원동기 말씀해 주세요.","a":"어느날 저는 한국의 기후 위기 대응 수준이 미흡하다는 기사를 접하였습니다. 특히 온실가스 배출이 심각하였고 이에 대한 대응책의 필요성을 느끼게 되었습니다. 온실가스 배출이 없으며 에너지 효율이 높은 발전 방법을 고민한 결과, 원자핵 공학에 매력을 느끼게 되었습니다.이를 위해 저는 평소 좋아하던 수학과 물리학적 역량을 토대로 해당 분야의 기초적인 이해와 의사소통 능력을 기르기 위해 노력하였습니다. 핵력에너지, 방사성 원소의 반감기, 핵 재처리 방식 등 많은 탐구를 진행하며 기초 소양을 쌓을 수 있었습니다. 또, 학생회 (봉사부) 임원으로서의 활동과 실험에서의 문제 상황을 팀원들과의 협력을 통해 해결한 경험으로 타인의 마음을 배려할 줄 아는 의사소통 능력을 배울 수 있었습니다.이를 바탕으로 현재 최선의 친환경 발전 방법인 원자력 발전을 진보시키고 나아가 환경과 에너지 고갈 문제를 근본적으로 해결할 수 있는 핵융합 발전에 대한 연구에 이바지하고 싶어 서울대학교 원자핵공학과에 지원하게 되었습니다."},{"q":"지원동기를 보면 핵융합에 관심이 있어 보이는데 그 이유가 있을까요?","a":"원자력 발전은 저·중 준위의 방사성 폐기물 발생과 우라늄의 매장량이 한정되어 있다는 점 등 단점 역시 존재하는 것이 사실입니다. 하지만 핵융합 발전은 폐기물이 발생하지 않고 바닷물에서 핵융합의 연료인 수소의 동위원소를 쉽게 구할 수 있는 등 단점을 극복할 수 있습니다. 따라서 핵융합 발전이 앞으로 우리가 나아가야 할 방향이라고 생각합니다."},{"q":"이 과를 고를 때 주변에 반대나 안 좋은 인식은 없었나요?","a":"네, 최근 국제사회에서도 주목받았던 일본의 후쿠시마 처리수 방류 등으로 여론이 좋지 못했으며 주변의 만류가 있었던 것은 사실이었으나 저의 소신대로 해당 학과에 지원하게 되었습니다."},{"q":"말해준 것처럼 해당 분야에 인식이 안 좋은데, 이에 대해 어떻게 생각하시나요?","a":"3학년 사회문제 탐구 시간에 앞서 말씀드린 일본 처리수 이슈와 관련된 탐구를 진행한 경험이 있습니다. 국제 원자력 기구에서도 해당 처리수에 대해 문제가 없음을 발표할 정도로 우리 과학은 고도로 발달 되어 있습니다. 국민의 오해를 풀고 과학적으로 올바른 사실을 알리는 것이 중요하다고 생각합니다."},{"q":"본인 성격의 장·단점에 대해 소개해 주세요.","a":"우선 저의 장점으로는 ’계획적이다‘라고 할 수 있습니다. 중학교 1학년 때부터 지금까지 총 6년간 하루도 빠짐없이 플래너를 작성해 오면서 계획적으로 주어진 일을 처리해 왔습니다.반대로 저의 단점으로는 지나친 엄격함입니다. 규칙을 지키는 것에 매우 민감하며 특히 타인이 이를 어기는 것에 따가운 눈초리를 보내는 등 다소... 오지랖이 넓다고 생각합니다."},{"q":"지원동기에서 의사소통 역량을 기르기 위해 노력했다고 했는데 사례를 제시해 줄 수 있나요?","a":"저는 2학년 화학Ⅰ 시간에 제시된 몰농도를 갖는 용액을 제작하는 실험에서 의사소통 역량을 기르기 위해 노력하였습니다. 이론적으로 추측한 몰농도와 실제 구현한 용액의 몰농도에 오차가 발생하였습니다. 이에 모둠원들과 실험 과정에서 오류를 찾고자 서로 의견을 나누었고 비커에 남아있는 용질을 모두 옮겨 담지 못한 것이라 결론을 내릴 수 있었습니다. 이 과정에서 혼자서는 발견하지 못했을 오류를 협력하여 해결하였기에 의사소통 역량의 중요성을 인식하였고 그 소통 과정을 기반으로 이후의 토의 활동에도 적용하면서 해당 역량을 기르기 위해 노력하였습니다."},{"q":"공부 말고 다른 취미가 있다면 말씀해 주세요.","a":"저는 수학 논술 문제를 푸는 것에 취미를 두고 있습니다. 문제를 푸는 것이 반드시 공부라고는 생각하지 않기에 대학 수리논술 문제를 찾아 해결하곤 합니다."},{"q":"수학과 물리를 좋아하는 것으로 보이는데 그 이유가 무엇인가요?","a":"우선 수학 같은 경우 마주하게 되면 어떤 일보다 몰입하여 즐길 수 있기 때문입니다. 그동안에는 어느 잡념도 없이 순수하게 즐거움을 느낄 수 있고 가슴이 뛰게 됩니다. 물리의 경우 자연 현상을 해석하고 예측하는 학문입니다. 그리고 이 과정에서 수학적인 활용이 돋보이기에 즐겨하는 것 같습니다. 예를 들어 조화 운동에 대해 이해하고 시간에 따른 물리량의 변화를 식으로 얻어내기 위해 미분방정식을 활용하여 삼각함수의 형태로 표현됨을 알게 된 탐구를 진행한 경험이 있습니다."},{"q":"수학과 물리 중에서 특히 관심이 있는 분야는 무엇인지 말씀해 주세요.","a":"수학은 대수와 관련된 영역에 관심이 있어 다양한 함수를 다루는 것에 흥미를 느낍니다. 물리의 경우 양자역학과 같은 미시 세계의 영역에 관심을 느끼고 있습니다."},{"q":"하필 양자역학인 이유가 있을까요?","a":"3학년 때 진로를 변경하게 되면서 주로 핵물리에 관심을 가지고 탐구한 것이 동기가 될 수 있었습니다."},{"q":"대학교에 진학한 뒤, 하고 싶은 활동이 있나요?","a":"현재 서울대학교에는 학부생 연구 참여 프로그램으로 ‘자장가둠핵융합 장치내의 내벽 조건에 따른 중성입자 거동에 대한 연구’가 있는 것으로 알고 있습니다. 이와 같은 핵융합 관련 연구 프로그램에 참여해 보고 싶습니다. 진로 관련 이외의 활동으로는 봉사활동을 하고 싶습니다. 구체적으로 수학과 과학에 대한 적성을 살려 어려운 형편의 아이들에게 수학·과학을 가르치고 싶다고 생각했습니다."},{"q":"대학교 이후 진출 분야에 대해 생각해 본 적이 있나요?","a":"대학에서 핵융합을 전공으로 선택한 후 연구원이 되어 이를 상용화하는 데에 힘쓰고 싶습니다. 다만 이를 실천할 직업의 경우 대학원에 진학하여 관련 연구를 충분히 한 뒤 적성에 맞추어 선택할 생각입니다."},{"q":"마지막으로 간단하게 인생의 좌우명을 소개해 주세요.","a":"저는 탈무드에서 읽었던 ‘이웃을 네 자신과 같이 사랑하라’를 좌우명으로 삼고 있습니다. 앞서 말씀드린 저의 성격의 단점을 극복하는데 도움이 되었기 때문입니다. (…)(10분 끝) 문이 열리며 종료후배들을 위한 조언 서울대 면접은 어떻게 나올지 모르니 모든 상황을 열어두고 준비하셔야 합니다. 저도 생기부 위주로 준비했는데 개방형 느낌으로 나와서 많이 당황했습니다.면접관하고 한 원탁 책상에서 면접을 진행했습니다. 너무 가깝더라도 당황하지 마세요.2024 대입 면접후기"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"서울대학교","dept":"자유전공학부","jeonhyeong":"학생부종합(기회균형(사회통합))","method":"(자기소개 및 마지막 인사 X)사회문제 탐구 세특 질문 → 진로 관련 질문 → 윤리와 사상 세특 질문","notes":"","qa":[{"q":"(사회문제 탐구) ‘국부론’이라는 책을 읽으셨는데, 과거의 사례를 통해 어떻게 현재의 문제를 해결할 수 있을까요?","a":"과거와 현재에는 분명 비슷한 부분이 있을 것이고, 과거의 사례를 통해 교훈을 얻을 수 있다. (실제에서는 더 구체적으로 답변함.)"},{"q":"(이어서 꼬리 질문) 그렇다면 과거의 사례가 있음에도 현재 문제가 해결되지 않는 경우는 어떻게 생각하나요?","a":"과거와 현재는 비슷한 부분도 있지만 시대가 발전해 나가면서 사회 구조, 기술, 문제의 발생 양상 등이 다양하게 나타납니다. 따라서 새로운 현상에 대한 대비가 잘되지 않았기 때문에 문제 해결이 어려운 경우도 생겨난다고 생각합니다."},{"q":"(이어서 꼬리 질문) 그럼 과거의 사례가 필요 없는 건 아닌가요?","a":"과거의 사례는 꼭 필요하다고 생각합니다. ~ 과거의 사례를 통한 교훈과 현재의 새로운 가능성을 모두 고려하는 것이 필요하므로 둘 중 하나만을 통해 문제를 해결하려는 것은 지양해야 합니다. (이후에도 비슷한 꼬리 질문 1-2개 더 질문하심.)"},{"q":"진로가 PD이신데, 4차 산업 혁명 기술을 어떻게 활용하실 건가요?","a":"예시로 ‘VR드라마’, ‘자동 구도 조정 기술’ 등을 언급하며 설명함."},{"q":"플라톤의 사상을 학습하셨는데, 정의로운 인간의 조건은 무엇인가요?","a":"윤리와 사상 시간에 진행한 활동을 바탕으로 설명함. (긴장 상태였기 때문에 질문의 의도를 정확히 파악하지 못한 것 같아 아쉬움이 남음.)후배들을 위한 조언 Ÿ 예상치 못한 질문, 많은 꼬리 질문으로 당황할 수 있으니 생활기록부 활동에 대한 깊은 이해가 필요하다.Ÿ 긴장한 티를 내지 않고, 최대한 차분하고 천천히 말하는 게 좋다.Ÿ 생각보다 시간이 금방 갈 것이다.2024 대입 면접후기"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"서울대학교","dept":"재료공학부","jeonhyeong":"학생부종합(지역균형)","method":"수소연료전지 탐구 관련 질문, 염료 감응형 전지 관련 질문,생명분야와 재료공학의 연관성, 온열 암 치료 관련 질문, 좋아하는과목","notes":"거의 다 생기부 기반 질문이여서 충분히 대비할 수 있음","qa":[{"q":"수소 연료전지 관련 탐구에 관해 구체적으로 설명해 주세요.","a":"교과서에서 수소 연료전지와 물의 전기분해가 역과정이라는 사실을 강조하여 탐구하게되었습니다. 물의 전기분해는 (+)극에서 물이 산화되어 산소기체가 발생하고 (-)극에서는물이 환원되면서 수소기체가 발생합니다. 수소 연료전지는 수소 연료전지는 그 역과정입니다."},{"q":"염료감응형 전지의 원리에 대해 설명해 주세요.","a":"염료 감응형 전지는 염료가 빛을 받으면 들뜬 상태가 되고 산화 티타늄이 염료의 전자를뺏게 됩니다. 전자를 뺏긴 염료는 넣어준 아이오딘 이온에게서 전자를 가져오고 뺏긴아이오딘 이온은 탄소 전극에서 다시 전자를 뺏어와 전자가 이동하게 되는 원리입니다."},{"q":"생명분야와 재료공학의 연관성은?","a":"암 치료에 활용되는 분야로 나소소재를 활용해 약물을 직접 전달하거나 온열 암 치료를하는 등 새로운 재료가 많이 활용되는 것으로 알고 있습니다."},{"q":"온열 암 치료가 뭔가요?","a":"온열 암 치료는 나노소재를 활용해 암세포에 넣고 인체에 무해한 주파수에서 열을 방출해 암을 사멸시키는 방법입니다."},{"q":"좋아하는 과목은?","a":"저는 고급화학이 가장 재미있었습니다. 특히 잎체 이성질체의 카이랄 의약품 관련된 부분이 가장 재미있었습니다.후배들을 위한 조언 생기부를 기반으로 꼼꼼하게 예상 질문을 추려보고, 이를 바탕으로 연습을 꾸준히 해온 것이 도움이 많이 되었습니다. 실전에서도 긴장하지 않고 침착하게 지금까지 해온 활동들을 답변하면 좋은 결과가 있을 것 같습니다.2024 대입 면접후기"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"서울대학교","dept":"재료공학부","jeonhyeong":"학생부종합(기회균형(사회통합(농어촌))7시부터 8시까지 39동으로 입실해야 한다. 대기실에 들어가는 길은 안내되어 있어 천천히 들어가면 된다. 대기실에 들어가면 물과 유의 사항이 써있는 프린트, 핫팩이 놓여있다. 아무 자리에 앉아 대기한다. 8시가 되면 조교님께서 설명을 해주심. 이때 모든 전자기기, 소지품(프린트물)","method":"포함) 모두 걷는다.대기실에는 지역균형전형 15명씩 3조와 기회균형전형 10명 1조가 있다. 지균 1조부터 기균 1조까지 차례로 복도로 나가 면접 번호가 적힌 스티커를 가슴에 부착한다. 이후 대기실에서 대기함.각 조의 2명씩 대기실에서 나가 면접실 앞에서 대기함. 10분 면접인데, 2분 전에 노크를 해주고 10분이 되면 밖에서 대기하는 조교님이 문을 강제로 열어 면접이 끝난다. 이후 소지품을 챙겨 개별 퇴실하면 된다.Ÿ 서울대 앞에 공사를 해서 길이 헷갈림.Ÿ 서울대 정말 많이 크기 때문에 전날 가보는 걸 추천Ÿ 39동을 출입할 때부터 수험표와 민증을 요함. 손에 들고 대기하는 것이 편함","notes":"Ÿ 39동 앞에서 선배들이 과별로 응원을 해주시면서 긴장을 풀어주심.Ÿ 대기실에서 대기할 때 순번에 따라 꽤 오래 기다려야 함(약 1~2시간)Ÿ 대기실 입장 후엔 조교분들께서 친절하게 잘 알려주시니까 너무 걱정할 필요는 없음Ÿ 면접실 앞에서 대기할 때 옆 친구와 말하면 안 됨Ÿ 대기실에서 대기할 때 준비자료 모두 걷음","qa":[{"q":"안녕하세요. 자기소개 간단하게 해주세요. (간단하게 강조하심)","a":"안녕하십니까? 저는 지속되는 환경오염을 해결하고자 친환경 전지 개발을 꿈꾸는 지원자입니다.저는 이 꿈을 이루기 위해 융합적 사고 역량, 그리고 리더십의 역량이 가장 중요하다고 생각했습니다. 그래서 저는 우선, 전지와 관련된 많은 탐구뿐만 아니라, 고급 물리학, 고급 화학을 수강하며 배운 것을 전지와 융합하여 탐구하고자 하였습니다. 또한, 고교 3년을 지내며 학급 또는, 교내 활동에 주체적으로 참여하며, 조별 실험 활동에 조장으로 나서 실험 중 생긴 문제점들을 해결하며 리더십의 역량, 그리고 공동체를 아우르는 포용의 역량을 길렀습니다. 저는 이 역량을 바탕으로 전공 관련 학문뿐만 아니라, 기초 교양 학문을 중시하며 융합적 인재를 양성하고자 하는 서울대학교에서 저의 꿈을 펼치고자 서울대학교 재료공학부에 지원하였습니다."},{"q":"전지 관련 꿈을 이루고 싶은데 왜 재료공학에 지원하셨죠?","a":"전지를 연구하기 위해서 전기전자공학을 전공할 수 있습니다. 하지만, 저는 전지의 분리막, 음극재 등을 재료와 관련한 연구를 통해 전지 개선시키고 싶어서 재료공학부에 지원하였습니다."},{"q":"수학2에 수학이 신소재에 중요함을 알게 되었다는데, 설명해 보면?","a":"과거에 선, 직선 등을 배우다가 계속해서 움직이는 물체에 대한 분석을 할 수 있는 미적분이 흥미롭게 느껴졌습니다. 이 흥미를 바탕으로 배터리의 잔량을 측정할 수 있는 전류 적분에 대해 알게 되었고, 이에 대해 탐구했습니다."},{"q":"고급 수학을 수강하셨는데, 어떤 방식으로 수업을 했고, 가장 인상 깊던 내용이 있을까요?","a":"공동 교육과정으로, 줌을 통해 온라인 수업을 진행했고, 프린트물을 위주로 진행함.벡터와 행렬이 가장 기억에 남습니다. 기하를 처음 배울 때 벡터에 대해 낯설어 거부감이 들고 실제로 어려움을 겪었습니다. 이로 인해 성적이 낮게 나왔고, 이에 대해 보완하고자 고급 수학을 수강했습니다. 고급 수학을 수강하며 기하 시간에 배웠던 내적뿐만 아니라 외적, 행렬을 같이 배우며 벡터에 대한 어려움을 극복한 점에서 기억에 남습니다."},{"q":"고급 화학에서 가장 기억에 남는 내용","a":"배위결합 간단 설명, 에너지 갈라짐(결정장 이론) 간략히 설명"},{"q":"고급 화학에서 염료 분자 탐구했다는데 어떻게 했나요?","a":"아연 중심으로 질소가 배위결합한 염료 분자임을 설명함. 전자쌍이 겹치면서 에너지가 불안정해 안정해지기 위해 에너지 준위가 미세하게 연속적으로 갈라져 전자의 이동이 편리해짐을 설명함"},{"q":"그런 자료들을 뭐 어떻게 구한 거에요?","a":"어.. 논문을 찾아 논문에 나와 있는 염료 분자를 발췌하여 탐구했습니다."},{"q":"(웃으면서) 논문 이해하기 어렵지 않았어요?","a":"아! 물론, 그 논문 전체 내용을 완벽히 이해하는 데 한계가 있었습니다. 저는 논문에 나와 있는 염료 분자에 대한 내용만 발췌하여 염료 분자를 스스로 탐구하여서 탐구를 하는 데 있어서 어려움은 없었습니다."},{"q":"학생의 장!단!점!이 뭐라고 생각하세요? (장단점을 강조하면서 느리게 말함)","a":"아,, 저는 투쟁심, 그러니까.. 도전 정신이 장점이라고 생각합니다. 저는 자존심이 강해서 관심 있는 한 분야에 대해 공부를 하면 다른 주위의 것들을 못 챙겼습니다. 그래서 국어 성적이 수학, 과학 성적에 비해 낮은 것도 사실이고요. 하지만, 여러 실험을 하며 한 가지에 집중을 하면, 실험실의 온도, 창문을 통한 바람 등 사소한 주변의 것들을 고려하지 못해 실패한다는 것을 느꼈습니다. 국어 역시 제가 나중에 논문을 작성할 때 독자를 설득하고 논리 있는 글의 구조를 위해 필요하다는 것을 느꼈고, 어른의 문해력이라는 도서를 통해 성적을 향상시키고자 노력했습니다. 또한, 전지와 관련한 탐구 활동을 하며 제가 물리2 화학2에서 배운 내용으로 한계가 있다 생각하여 여러 공동 교욱과정을 수강하였습니다."},{"q":"20년 뒤에 학생은 뭘 하고 있을 거 같아요?","a":"전지의 분리막, 음극재에 관련한 연구 논문으로 네이처와 같은 해외 학술지에 실릴 것입니다."},{"q":"그러면 꿈을 다 이룬 거에요?","a":"아! 물론 아닙니다! 이러한 권위 있는 연구 논문을 통해 한국을 전지 강국으로 올리는 것이 저의 꿈입니다.밖의 조교: (문 열고) 끝났습니다.교수님1, 2: 수고하셨습니다.학생: 감사합니다. (간단히 고개 숙여 인사)2024 대입 면접후기"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"서울대학교","dept":"정치외교학부","jeonhyeong":"학생부종합(지역균형)","method":"인상 깊은 책 -> 정치와 법 -> 진로 -> 생기부에 없는 인상 깊은 책대기실은 조용하고 따뜻합니다. 저희 과는 대기실에서 자료 볼 수 있었는데, 대기하고 있으면 무작위로 조교님들께서 부르십니다. 조교님들이 작은 스마트폰으로 논문을 읽고 계셔서 약간 당황했는데 계속 옆에 계시고, 시간 되면 면접장까지 같이 가주십니다! 면접장은 교수님 사무실이었는데","notes":"2평 정도로 작고 책상도 있어서 분위기는 편안합니다. 교수님들 2분께서 4절지 크기의 생기부를 넘기면서 질문하시고 주변에 다른 서류들도 있었던 것 같아요! 교수님들이 의자에 기대계셔도 1m 정도로 정말 가까운 거리였습니다. 1분 전에 조교님이 똑똑 해주시는데 저는 너무 긴장해서 못 들었어요.","qa":[{"q":"생기부를 보니까 3년 내내 국제정치나 사회 뭐 이런 분야에 관심이 많은 학생인 것 같네요~ 정치 관련해서 인상 깊었던 책에 대해 말해보세요.","a":"(지원동기가 첫 질문이 아니라 당황) 2학년 때 읽은 아리스토텔레스의 정치학이 정치에서 통일성이 아닌 다양성이라는 가치를 강조하였다는 점에서 기억에 남습니다. 정치학은 아리스토텔레스가 아테네 민주정이 펠로폰네소스 전쟁에서 패배한 후 최적의 정치 체제, 즉 혼합정을 찾고자 쓴 책입니다. 아리스토텔레스는 중산층을 확대하여 다양한 계층, 즉 부자와 빈민의 갈등을 완화하고 그것을 정치로 해결하는 것을 중요하게 생각하였습니다. 책을 읽으며 이 부분이 현대사회에도 적용된다고 생각하였고, 특히 뒷장에서 아리스토텔레스가 교육의 중요성을 강조하였는데 우리 사회에도 다양한 정치 교육이 활성화되어야 할 필요성을 배웠습니다. (처음부터 당황해서 답변에 일관성이 좀 부족하다고 생각합니다. 말하면서도 뭐라는지 모르겠던..)"},{"q":"이거 되게 어려운 책인데 읽을 때 어렵지 않았나?","a":"네 맞습니다. 읽기에 길고 어려운 책이기도 하고 아리스토텔레스가 고대 그리스 사람이니만큼 노예제를 당연시해서 현대의 가치관과는 맞지 않는 부분이 있었습니다. (사실 고대 그리스라고 했는지 2000년 전(아님)이라고 했는지 잘 기억이 안 납니다.. 세계사를 수강해서 연도를 잘못 말했으면 약간 신빙성이 떨어졌을 것 같습니다) 또한 아리스토텔레스가 사익을 추구하는 과두정과 민주정이 혼합하면 최적의 정치 체제라 하였는데 나쁜 것과 나쁜 것을 혼합했을 때 어떻게 좋은 것이 나오는지 이해가 잘되지 않기도 하였습니다. 그럼에도 어려운 부분은 다른 해설서를 읽으며 (사실 만화책이었는데 약간의 msg를...) 보완하였더니 끝까지 읽을 수 있었습니다. (여기서 끝나면 안 되고 과두정+민주정->혼합정인 이유를 내가 책을 읽고 이해한 것으로 말씀드렸어야 했는데 그걸 놓쳤습니다... 사익 추구가 당연한 욕망이라고 보고 그것을 적절하게 통제하는 것이 국가이고, 이 개념을 3학년 윤리와 사상 시간에 코나투스에 대한 탐구를 하며 배워 이해하게 되었다 이렇게 답변했으면 더 좋았을 것 같습니다.)"},{"q":"맞아요. 어려운 책인데 읽는데 누가 추천해 준 거예요?","a":"제가 추천 도서 목록을 찾아서 읽은 기억이 있습니다. (동기나 도움을 주셨던 선생님을 언급했었나... 저거보단 길게 말했는데 정확히 기억 안 납니다. 이 질문은 약간 소소(?)하게 넘어가고 바로 옆 교수님께서 다음 질문하셨습니다.)"},{"q":"근데 학생이 말한 것처럼 노예제를 찬성할 만큼 예전인데 그게 우리 사회에 적용이 가능할까요?","a":"물론 그 시대상이 현재와 괴리가 있는 것은 맞습니다. 그러나 고전이 주는 함의가 있다고 생각합니다. 예를 들어 저는 이 책을 읽은 계기 중 하나가 북한의 정치 체제가 유일하고 독특하여 잘 이해되지 않아 알아보고 싶어서가 있었습니다. (문장 진짜 이상한데 말이 계속 이렇게 헛나왔어요ㅠㅠ) 정치학을 읽으며 페이시스트라토스의 참주정과 그 체제가 매우 유사하다고 느꼈고, 현재 북한 정권이 자신의 체제를 유지하기 위해 사용하는 억압정책이 고대의 것의 반복이라는 것을 알게 되었습니다. 따라서 시대가 변함에도 이어져 내려오는 가치와 반복되는 역사를 독자가 스스로 판단한다면 충분히 현대사회에 적용이 가능하다고 생각합니다."},{"q":"3학년 정치와 법 시간에 장애인 지하철 시위를 다루었는데 여기에 대해서 설명해 볼까요?","a":"현재 우리 사회에는 다양한 집단의 의견 표출이 제대로 되지 않고 있고, 이를 대표하는 사례가 장애인 지하철 시위입니다. 무엇보다 다양한 집단의 이해관계를 듣고 정치를 통해 갈등을 해결하는 과정이 중요합니다. 하지만 현재 사회적 약자 집단의 요구사항이 정치의 장에 반영되지 않기에 이렇게 극단적인 방식으로 그들의 어려움을 들어달라고 호소하는 것입니다. 민주주의는 치자와 피치자가 동일한 체제인데, 이러한 상황에서 시위를 하는 장애인들은 치자가 아닌 지배받는 자가 됩니다. 저는 이 문제의 해결 방안으로 다당제로의 변화를 주장하였습니다. 사회통합 기능을 수행해야 하는 정당이 양당제하에서 제 역할을 하지 못한다고 생각하기 때문입니다. (여기까지 말하고 꼬리 질문하셨습니다.)"},{"q":"그럼 학생은 어떤 다당제를 생각하나? 그렇게 한 집단이 자기주장만 하는 당을 만들어야 한다고 생각하나?","a":"그렇지 않습니다. 예를 들어 장애인의 입장만 대변하는 당이라면 그것은 정권을 목적으로 하는 정당이 아닌 이익집단일 것입니다. 다당제에서는 더욱 다양한 이념을 가진 당이 국회에 진출할 수 있습니다. 정당의 역할은 한 집단의 의견만을 주장하는 것이 아닌 자기 당의 이념과 목적에 따라 여러 사람의 의견을 듣고 그것을 정책으로 만드는 것이라고 생각합니다. (뒤에 기억이 안 납니다ㅠㅠ) 그러나 양당제에서는 사회적 약자들의 의견을 듣기보다는 대다수 사람들을 위한 정책만을 내세울 수밖에 없습니다. (뒤에 기억 안 납니다... 여기부터 본격적으로 큰일났다는 직감이 들었습니다 ㅎㅎ... )"},{"q":"근데 다당제라고 의견이 잘 표출되리라는 보장이 있을까요? (이 부분은 질문은 잘 기억이 안 나고 답변만 기억이 납니다 ㅜㅜ 질문과 답변이 잘 맞지 않을 수 있습니다)","a":"물론 다당제에서도 안 될 수도 있습니다. 그러나 다당제로의 변화, 즉 그것을 만드는 선거제도 개혁은 필요한 조건을 갖추어 놓는 것입니다. 다수결 원칙으로 정책을 만드는 것의 전제는 다양한 의견을 가진 사람들이 토론을 통해 하나의 좋은 결과로 나아가는 숙의민주주의라고 생각합니다. 그러나 이러한 조건조차 없다면 민주주의는 그 작동 기반을 잃어버리게 됩니다. 다당제로 변화하였어도 현재의 상황이 지속된다면 그것은 제도의 문제가 아닌 정치 과정의 문제일 것입니다. 시민들은 환류의 과정을 통해 다당제하에서도 의견이 잘 표출되지 않는다면 정권을 바꿀 수 있고, 다당제하에서는 더욱 많은 정당들이 원내정당이 되기 위해 공약을 실천하고 노력할 것입니다."},{"q":"다양한 사람들의 의견을 듣는 것은 양당제하에서도 가능하지 않나?","a":"네. 물론 양당제하에서도 가능하기도 합니다. 저는 양당제가 그러한 역할을 수행할 수 있을지 궁금하여 양당제의 장점을 다룬 ‘책임 정당’이라는 책을 읽었습니다. 하지만 그 상황이 우리나라에는 적용되지 않는다고 생각합니다. 양당제가 정권을 획득하기 위해 다양한 유권자를 위한 정책을 펴고 정책에 책임을 진다면 제대로 작동하겠지만, 국가마다 맞는 정치 체제는 상이합니다. 우리나라의 상황은 양당제의 장점이 있다기보다는 거대 양당이 서로를 비방하고 토론을 통해 국민을 위한 정책을 펴기보다는 양극화가 심하다고 생각합니다. 이는 아리스토텔레스가 정치학에서 언급하였던 다양성이라기보다는 중간층이 없는 극단화된 상황이므로 좋은 정체라고 볼 수 없습니다."},{"q":"근데 국민들이 다당제가 되더라도 양당만 뽑으면 어떡해요? 우리나라도 다양한 당이 나오는데 거대 양당만 뽑는 거잖아요.","a":"국민의 의사를 따라야 합니다. 하지만 현재 우리나라의 양당제는 국민의 의사를 제대로 대표한 결과가 아닙니다. 소선거구 단순다수대표제 하에서는 양당제가 만들어질 가능성이 높고 심리적, 물리적 요인으로 사표가 많이 발생합니다. 이러한 선거제도에서 국민의 지지대로 의석이 반영되는 비례성의 원칙과 다양한 계층의 국민을 대표하는 대표성의 원칙이 훼손되고 있습니다. 저는 그래서 이러한 문제점을 해결할 수 있는 방법 중 하나로 연동형 비례대표제로의 선거제도 개혁을 주장하는 바입니다."},{"q":"학생은 꿈이 무엇인가요?","a":"평화통일을 위한 외교 전문가입니다."},{"q":"왜 통일해야 한다고 생각하나요?","a":"현재 우리는 분단에 익숙해진 것일 뿐 평화로워 보이지만 언제라도 전쟁이 가능한 상황입니다. 저는 인간의 존엄성을 보장하기 위해 가장 중요한 가치가 평화라고 생각합니다. 갈퉁에 따르면 구조적, 문화적 폭력까지 없어져야 진정한 평화를 달성할 수 있는데 현재 분단 상황에서는 그렇지 못하다고 생각합니다. (여기서 답변 구조가 많이 꼬였는데 이미 뇌도 많이 꼬인 상황이라 계속 이상하게 대답했습니다...)"},{"q":"근데 통일되고 나서도 막 러시아 중국 일본 이렇게 강대국들이 있는데 어떡하나요?","a":"(멘탈 붕괴 + 여기 답변은 진짜 기억이 안 나는데 우리나라가 분단 상황에서 통일을 이룩하게 되면 동북아의 평화를 위한 주축이 될 수 있고 그것을 달성하기 위한 방안이 외교이기 때문에 어쩌고 저쩌고 외교의 중요성을 설명했던 것 같습니다...)"},{"q":"마지막으로 인상 깊은 책 내용 짧게 얘기해볼래요?","a":"생기부에 있는 책 중에서 말씀드리면 되겠습니까? (실제로 이렇게 똑부러지게 말 못하고 엄청 어버버했어요... 당황해서ㅠㅠㅠ 그래도 표정은 포커페이스였어요.. 그래서 더 이상해 보였을거예요ㅜㅜㅜ)"},{"q":"아니아니 생기부에 없는 책!","a":"오준 전 유엔 대사의 생각하는 ‘미카를 위하여’라는 책이 인상이 깊었습니다. 이 책을 읽은 것은 제가 북한 문제에 관심을 가지게 된 이유 중 하나입니다. 오준 대사께서는 유엔에서 북한은 우리와 한민족입니다!!! 라는 연설을 하셨고 그게 감명이 깊어 우리나라의 진정한 평화를 위해 공헌하는 사람이 되고 싶다는 생각을 하였습니다. (북한 사람은 우리와 남이 아니다라는 진정 감동적인 연설인데 제가 까먹어서... 당연한 말을... 거의 외치다시피... 말하고 왔습니다... 여기서 이제 서울대와 작별 인사를 할 시간이 되었다는 걸 깨닫고 교수님께 인사드리고 나왔습니다.)후배들을 위한 조언 보시다시피 객관적으로도 못봤고... 연습했던 것보다도 훨씬 못해서 말 한마디 할 때마다 서울에서 10km씩 멀어지는 느낌이 들었어요.. 분명 들어갈 땐 서울이었는데 나올 때는 돌하르방이 된 것 같은... 하지만 붙었네요!! 자신감을 가지고 교수님께서 아무리 반대 질문을 하셔도 자기 생각대로 밀고 가는 게 중요할 것 같습니다. 말하는 것에 두려움을 가지지 마세요! 이 글을 1, 2학년 때 읽으신다면 친구들이랑 토론도 많이 하시고 발표도 꾸준히 해보세요. 면접 전에 읽으신다면 학교 선생님들과 모의 면접을 많이 해보세요. 저는 교육청 모의 면접도 기회가 될 때마다 전부 다녔는데 말도 할수록 늘고, 여러 학교의 선생님들께 다양한 피드백을 받을 수 있었어요.저도 조언을 듣고 더 좋은 방향으로 나아갈 수 있었습니다. 특히 한 선생님께서 면접은 결국대화하는 건데 대화가 되지 않는다고 말씀해 주셨는데, 그때 면접의 목적이 바로 이해되어 두괄식으로, 질문의 의도에 대한 핵심만 답변하는 습관이 생겼습니다. 또 제가 생각하지 못했던 목소리높낮이나 자세도 교정해 주셔서 면접을 더욱 완벽하게 준비할 수 있었습니다. 저희 학교는 선생님들께서 2주 동안 정말 많이 봐주셨는데, 제가 혼자 생기부 정리하고 보고서 읽는 것보다 훨씬큰 도움이 되었습니다. 모의 면접 이외에도 생기부에 모르는 게 있으면 선생님들 찾아뵙고 질문드리면 더욱 탄탄하게 대비하실 수 있습니다. 모의 면접은 하루에 한 번도 부족한 것 같아요.저는 학교에서 오전 오후 두 번씩 하고, 저녁에 집에 와서는 다른 정치외교학부 준비하는 친구들(수험생 카페에서 오픈 채팅으로 만났어요 익명으로 통화 가능합니다!) 이랑 공통 질문 연습을 했어요.서울대 면접은 보통 수능 끝나고 2주간 준비할 텐데 친구들 다 놀 때 계속 공부해야 해서힘들기도 했어요. (저희 학교에서는 아침부터 야자 시간까지 따로 교실을 준비해 주셔서 집중이진짜 잘 됐습니다!! 슬프지만 입시가 끝난 친구들과는 잠시 떨어져 있는 것도 하나의 방법인것 같아요) 하지만 대학 입학해서 공부하기 위해 제 3년을 복습한다고 생각하니 힘도 나고 시간이빨리 갔습니다! (항상 오히려 좋아. 라는 마음을 가지는 게 좋을 것 같아요) 생기부 양이 꽤방대하고 보고서나 읽어야 할 ppt도 많을 거예요. 저도 보고서 몇백 편 달달 읽었습니다... 보고서를읽다 보면 독서 활동을 정리할 시간이 없는데, 여름방학 때 책은 기본적인 내용, 차례, 저자,읽은 이유, 인상깊었던 점 등등 정도만 해두시면 편할 것 같습니다. 저는 수능 전에는 생기부만조금 읽고 준비를 아예 안 했는데, 2주가 생각보다 짧고 독후감을 안 쓴 책들도 몇 권 있어서여름방학 때 공부를 안 해놓은 것에 후회를 했습니다. 물론 수능 공부가 가장 중요하지만 스마트폰보고 쉬는 시간 30분만 줄여도 충분하다고 생각해요.2주라는 시간에 다시 집중하자면 정...정말 짧습니다!!!!! 무엇보다 전공 관련 중요한 활동부터정리하세요. 저는 진로와 부합하는 전공 -> 진로와는 약간 거리가 있는 전공 -> 계열 관련 활동 -> 교과 세특 활동 (전과목) 순으로 공부했습니다. 특히 3학년 세특과 진로!!! 저는 선생님께pdf를 받아 생기부 한줄 한줄 읽으며 어느 정도 준비가 되었다 싶으면 그 부분에 노란색으로덧칠을 했습니다. 20장이 넘는 생기부를 읽다 보면 꼭 빠지는 부분이 있는데 그런 걸 보기 편해요성취감도 들고!! 생기부 단어에 하나하나 시비를 걸며 (단어 선택이 좀 이상하긴 한데.. 예를들면 ‘~~이 옳다고 생각하여’ 이런 문장이 있으면, 내가 생각하는 옳은 것은 무엇인지, 어떤가치를 중요시하는지, 사회현상에 어떻게 적용할 수 있을지, 그 근거는 무엇인지, 반대 근거는무엇이 있을지 등등) 꼭 기록은 안 하더라도 스스로 생각해 보았습니다. 전공 관련 활동에 대해서는모의 면접이 큰 도움이 됩니다. 제가 생각해 보지 못했던 관점으로 선생님들께서 질문을 해주셨고, 실제 면접장에서도 교수님들께서 비슷하게 질문하셨습니다.제가 생각하는 합격 이유는 (주관적인 생각입니다.) 3년 동안 제 가치관과 삶에 대해 끊임없이고민했다는 것, 그리고 도전을 두려워하지 않았다는 것 같습니다. 내가 무엇을 위해 공부를 하고,배운 지식으로 어떻게 사회에 공헌할 것인지 생각했습니다. 사실 저도 아직 명확한 장래 희망은없고, 사회과학 말고 다른 분야에 적성도 찾은 상황입니다. 따라서 고민과 성찰이 모든 미래계획을 세워준다고 단언할 수는 없지만, 적어도 제가 나아가는 데 있어 큰 후회는 없었습니다.3년간 저는 입시와 관련이 없더라도 해볼 가치가 있다고 생각하는 일에는 시간을 투자했고 최선을다했습니다. 과목 선택에서도 과학사, 미적분, 정보과학 등등 진로와 큰 관련은 없지만 흥미있는 과목을 선택했고 열심히 수강했습니다. 사실상 AI가 우리보다 똑똑하기에 이제는 다양한 경험을 쌓고 문제 해결에 필요한 지식을 검색하여 융합하는 능력이 중요하다고 생각했습니다. 서울대가 원하는 인재상도 이런 것이 아닐까 조심스럽게 글을 써보네요... 이 글을 읽는 모든 분 합격하시길 바라고 부모님과 선생님, 편하게 공부에만 집중하게 해주신 주변 환경에 항상 감사한 마음을 가집시다!! 2024 대입 면접후기"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"서울대학교","dept":"중어중문학과","jeonhyeong":"학생부종합(일반제시문 분석 시간 (30분) - 두 명이 한 방에서 들어가서 진행)","method":"제시문 기반 면접 시간 (15분) - 간단한 일상 대화 → 제시문1+2에 대한 답변 → 제시문 1 관련 후속 질문 → 제시문 2 관련 후속 질문 → 마지막 할 말 (교수님 2분과 학생 1명 2:1로 진행)인문대학은 특히 찾기 힘들고 입구에서 멀어 면접 시간보다 1시간 정","notes":"도 먼저 도착하도록 준비하시는 걸 추천드립니다. 또한, 생각보다 교수님들께서 학생들의 긴장을 풀어주시려고 노력을 많이 하시기 때문에 너무 긴장하실 필요는 전혀 없을 것 같습니다.","qa":[{"q":"네 학생. 오는 길 춥던데 어떻게 왔어요?","a":"제가 타 지역에 거주해 어제 근처에서 하룻밤을 자고 버스 타고 왔습니다."},{"q":"그러면 가는 길은 어떻게 가나요?","a":"끝나고는 부모님이 오시기로 하셔서 부모님 차 타고 내려갈 것 같습니다."},{"q":"그러면 끝나고 뭐 할 거에요? 밥은 먹었어요?","a":"아침은 간단하게 챙겨먹었고, 끝나고 부모님하고 맛있게 점심식사하려고 합니다."},{"q":"이제 시작을 해볼텐데 어떤 지문 먼저 대답할래요?","a":"저 1번 지문인 인문학 지문 먼저 대답하고 2번 지문 사회과학 지문 관련해서 답변 드리도록 하겠습니다.(저는 한 번에 제시문 1번과 2번에 대한 답변을 모두 다 하였고, 교수님들은 듣고만 계시고 제 답변이 다 끝나기 전까지는 추가-심층-후속 질문을 하시지 않으셨습니다.)(이후로 제시문1과 2에 관련한 제 답변에 대한 후속 질문은 없으셨고, 두 분이 각각 하나씩 제시문 1과 2번에 대한 추가적인 분석을 요구하셨고, 이에 대해 모두 답하였습니다.)"},{"q":"이제 시간이 다 돼서 마지막 할 말 있으면 짧게 하고 끝내볼까요?","a":"아 네. 오늘 서울대학교에 와서 제 앞 교수님 두 분과 제시문 두 개에 대한 제 의견을공유하고 이 의견을 일부 수용하기도 해주시고 적절한 질문도 해주시는 상호 소통의 과정을 가질 수 있다는 것 자체로 저에겐 굉장히 귀중한 시간이었습니다. 이렇게 저에게귀중한 시간을 만들기 위하여 노력해주신 교수님들께 감사의 인사로 마무리하고 싶습니다. 진심으로 감사합니다.후배들을 위한 조언 제시문 면접에 있어서 가장 중요한 두 요소는 제시문 의도 파악과 임기응변이라고 생각합니다. 이를 위해선 기출을 통한 모의면접과 같은 연습이 필요하다고 생각합니다. 또한, 추가 질문이 들어왔을 때 생각이 안 난다면 너무 오랜 시간 뜸을 들이기보다는 그냥 먼저 대답을 시작하면 말을 떼기 시작해야 생각이 나는 경우도 있기에 당황하며 시간을 끌기보다는 먼저 대답을 시작하는 것도 좋은 방법인 것 같습니다. 저는 그런 케이스 중 하나였고 따라서 저도 이러한 방식을 따랐습니다.2024 대입 면접후기"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"서울대학교","dept":"첨단융합학부","jeonhyeong":"학생부종합(기회균형)","method":"자기소개/지원동기 -> 공통 질문 -> 개별 질문 -> 마지막 할 말면접 대기실 들어가면 작은 생수병을 제공해 줍니다. 그리고 핸드폰이나","notes":"스마트 워치와 같은 전자기기는 모두 제출해야 합니다. 또한 면접 대기실에서는 준비한 자료와 생기부도 볼 수 없습니다.뒷번호는 오래 기다려야 하기 때문에 간식이나 물 챙기면 좋을거 같아요.","qa":[{"q":"자기소개 말해주세요.","a":"저는 데이터 과학자 및 인공지능 개발자로서 첨단 과학 기술이 모두의 피부에 와닿을 수 있도록 이끄는 스타트업을 꿈꾸는 지원자입니다.저는 학교생활에서 인공지능과 사물인터넷과 같은 첨단 과학 기술에 대해 이론적으로 탐구를 진행하였습니다. 또한 학교 친구들이 겪고 있는 문제를 해결하고자 청원 사이트 제작 프로젝트, IOT 프로젝트 등을 진행하였습니다. 그리고 제가 만든 프로그램을 이용하여 친구들이 직접 이용할 수 있도록 하였습니다. 이러한 경험을 통해 저의 진로를 구체화하고 실현을 위해 노력해 왔습니다.이후 서울대학교 첨단융합학부에서 첨단 과학 기술과 융합적인 사고를 배워 공동체에 이바지할 수 있는 하나의 연결점으로 성장하고 싶습니다."},{"q":"어떤 창업을 하고 싶으세요?","a":"저는 첨단 과학 기술을 이용하여 산업 현장을 최적화시키는 스타트업을 하고 싶습니다.(뒤에 부연 설명함)"},{"q":"조금 더 자세하게 말씀해 주세요.","a":"인공지능과 디지털 트윈 기술을 이용하여 최적화 및 시물레이션을 통한 산업 현장 최적화를 꿈꾸고 있습니다. (뒤에 부연 설명함)"},{"q":"진로가 바뀐 이유가 무엇인가요?","a":"저는 구체적인 진로 설정에 어려움을 겪었습니다. 1학년 때에는 막연하게 이과 계열을 희망하고 있었습니다. 그마저도 2학년으로 올라오면서 친구들은 구체적인 진로 계획을 구성한 반면에 저는 무엇 하나 구체적으로 정한 진로 계획이 없는 모습에 많이 좌절감을 느끼게 되었고 이는 결국 성적의 하락으로 이어졌습니다. 그래서 저는 이러한 위기를 극복하기 위하여 화학실험, 물리 실험, 컴퓨터 프로그래밍과 같은 다양한 분야의 활동을 경험하기 위해 노력하였습니다. 이러한 활동에서 저는 프로그래밍, 인공지능과 같은 첨단 과학 기술에 매력을 느끼게 되었습니다. 이러한 흥미를 바탕으로 저는 인공지능을 이용하여 새로운 가치를 추구하는 사람이 되고 싶다는 진로 계획을 세울 수 있게 되었습니다."},{"q":"디지털 트윈은 무엇인가요?","a":"디지털 트윈이란 실세계와 가상 세계가 연결되어 상호 작용하는 기술로 현실 세계에 존재하는 사물, 시스템, 환경 등을 가상 공간에 동일하게 모사하고, 실물 객체와 시스템의 특성 및 결과 변화를 가상 세계에서 시뮬레이션할 수 있도록 하고 결과를 분석하여 실물 세계에 적용하고 다시 그 상태변화를 가상 세계로 전달되도록 함으로 최적화 체계를 구성하는 기술입니다."},{"q":"융합적인 소양을 기르기 위해 어떤 노력을 하셨나요?","a":"저는 융합적인 소양을 기르기 위하여 휴마니타스라는 학급 활동을 진행하였습니다. 저는 휴마니타스를 진행하며 4차 산업혁명 속 인문학의 중요성에 대해 탐구하고 이를 이공계 진학을 희망하는 친구들에게 발표하였습니다. 그 과정에서 인문학의 의미와 인문학을 통해 사회문제를 해결할 수 있다는 것을 알 수 있었고 첨단 과학 기술과 인문학의 융합이 필요함을 알고 이를 위해 인문학 도서들을 읽으면서 인문학에 대해 공부할 수 있었습니다."},{"q":"리더십을 보여준 활동이 있나요?","a":"저는 미진한 학급 활동 참여를 해결하기 위하여 반 친구들이 학급 활동에 흥미를 느낄 수 있도록 만들려고 노력하였습니다. 마니또, 학급 체육대회, 학급신문 제작 등 친구들이 흥미를 가질 활동들을 우선적으로 진행하면서 학급 활동에 대해 흥미를 느낄 수 있도록 하였습니다. 그 뒤 학급 활동을 계획하는 시간을 가지면서 저는 친구들이 학급 활동을 보다 쉽게 제안할 수 있도록 제안서의 형태와 이전 선배들이 제안하였던 활동을 수집하여 친구들에게 제공하였습니다. 이를 통해 친구들의 학급 활동 참여를 이끌어 낼 수 있었습니다."},{"q":"마지막으로 할 말 있으면 해주세요.","a":"저는 학교생활에서 인공지능에 대해서 탐구 및 프로그래밍, 관련 캠프 참여, 공동교육과정 수강 등을 통해서 첨단과학기술에 대한 관심과 자기 효능감을 높여왔습니다. 또한 사회에 대한 이해와 사회의 문제 해결을 위해 인문학적 소양도 함께 성장시켜 왔습니다. 이를 통해 인공지능 개발자와 스타트업이라는 진로를 실현시키기 위해 노력해 왔습니다. 앞으로 서울대학교 첨단융합학부에서 이러한 제 학교생활에서 얻은 경험들과 제 장점들을 활용해 공동체의 발전에 기여하는 사람으로 성장하고 싶습니다. 감사합니다.후배들을 위한 조언 면접을 준비하면서 가장 중요한 건 자기 생기부 분석인 것 같습니다. 우선 자기가 했던 활동들에 대해서 다시 한번 정리해 보면서 동기, 활동 내용, 배운점으로 정리하면 활동에 대해 질문받았을 때 대답하기 좋습니다. 그리고 답변을 준비하면서 답변 그대로 외우는 거는 좋지 않은방법인 것 같습니다. 그대로 외우는 것 보단 핵심 키워드를 중심으로 외우는 것이 시간 면으로도 좋고 대답을 할 때도 국어책 읽는 느낌보단 자연스럽게 나와서 키워드 중심으로 외우는것을 추천드립니다. 그리고 그 과에 대해서 조사하는 것 또한 중요합니다. 그 학교와 학과에인재상에 대해서 미리 조사하고 그에 대한 질문과 답변을 준비하는 것이 중요합니다. 또한 그학과에서 무엇을 배우는지 함께 조사해서 답변에 추가하면 그 학과에 관심이 있다는 것을 표현할 수 있습니다.2024 대입 면접후기"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"서울대학교","dept":"통계학과","jeonhyeong":"학생부종합(지역균형8시 20분까지 입실, 신분확인 후에는 감독관 동행 하에 화장실 이용이 가능합니다. 면접 시간을 정말 정확하게 측정하며, 예상 시간도 지원자별로 적어주십니다. 자신의 예상 시간 5분 전에 고사실 앞에서 대기하며, 앞)","method":"사람이 끝나자마자 바로 들어가게 됩니다. 저는 고사실에 들어가자마자 목례 후 의자 옆에 가서 인사말과 함께 다시 인사드렸습니다. 이후 면접이 진행됩니다. 면접하다 보면 첫 노크 소리(쿵)가 들리는데, 2분 남았다는 뜻입니다. 이후 10분이 완전히 지나면 진행요원님이 바로 문을 열고 들어와 면접이 종료됩니다.학과마다 다르지만 올해 통계학과는 8시 20분 입실 후 모든 자료를 볼 수 없었습니다. 자료는 모두 가방에 넣은 채로 대기 시간 내내 가만히 대기했습니다. 수험번호는 xxxx01번이었지만 면접 순서를 나타내는 면접","notes":"번호는 다르게 주어졌습니다. 저는 맨 마지막에서 2번째 순서였습니다.제 고사실은 연세가 있으신 남자 교수님 두 분이 들어오셨습니다. 서류 면접이라 책상이 없을 줄 알았는데 제 고사실은 있었습니다. 무의식적으로 손을 올리고 면접을 본 학생도 있다 하던데, 무릎 위에 손을 올리고 정자세를 유지하는 것을 추천드립니다.","qa":[{"q":"면접번호 xx번 지원자 맞죠? 앉으세요. xx번 지원자는 왜 우리 학과에 지원했나요?","a":"제가 통계학과에 지원하게 된 계기는, 제 꿈인 보건통계학자라는 꿈을 이루기 위해 통계학에 대한 공부가 필요하다고 생각했기 때문입니다. 저는 고등학교 3년 동안, 1학년 통합사회에서 의료비 본인부담금 비율과 코로나19 확진 인구 비율과의 관계, 2학년 영어2에서 소득 불평등과 범죄 발생률 간의 관계, 3학년 일본문화에서 일본의 도장 문화가 코로나19 초기 확산에 끼친 영향에 대해 탐구하며 우리 사회의 하나의 문제점은 하나의 요인이 아닌, 다양한 요인들에 의해 영향을 받는다는 것을 알게 되었습니다. 이 요인들을 분석하기 위해, 다양한 데이터들을 수집하고 다루는 능력이 필요하다고 느꼈고, 통계학에 대한 공부가 필요하다고 생각했습니다. 이러한 과정을 통해 저는 서울대학교 통계학과에 지원하게 되었습니다."},{"q":"3학년 확률과 통계에서 “베이즈 정리와 통계학의 법적 증거 성립 가능성“에 대해 칼럼을 작성했던데, 어떤 내용이었나요?","a":"저는 3학년 확률과 통계 과목에서 “통계학, 빅데이터를 잡다”라는 책을 읽게 되었습니다. 이 책에서 베이즈 정리에 대해 읽었는데, 이 베이즈 정리가 실생활에 어떻게 활용될 수 있을지에 대해 고민해 보게 되었고, 한 사례로 영국의 샐리 클라크 사건에 대해 알게 되었습니다. 샐리 클라크 사건에 대한 간략한 개요를 말씀드리겠습니다. 샐리 클라크는 두 아이의 어머니였는데, 두 아이가 같은 날 갑자기 사망하게 됩니다. 검사는 두 아이가 같은 날에 죽을 확률은 0에 수렴한다며, 어머니인 샐리 클라크가 두 아이를 살해하였다고 주장하고 재판부는 이를 받아들여 종신형을 선고하였습니다. 몇 년 후, 영국의 왕립 통계학회가 베이즈 정리를 활용하여 샐리 클라크의 무죄를 증명하였는데, 샐리 클라크는 이미 감옥에서 얻은 우울증과 불안장애, 알코올 중독증으로 숨을 거둔 뒤였습니다. 저는 이렇게 하나의 통계학적 오류가 한 사람의 인생을 완전히 빼앗아 버릴 수 있다는 것을 알고, 통계학이 아직 법적 증거로 활용되기에는 부적합하다고 생각했습니다. (베이즈 정리를 유도하는 과정과 구체적인 수치를 담았어야 했는데 긴장해서 까먹었습니다. 꼬리 질문도 안 하셔서 추가적으로 내용을 덧붙이지도 못했습니다)"},{"q":"확률과 통계에서 연속성 수정에 대해서 탐구했던데, 설명해 주세요.","a":"저는 확률과 통계 과목에서 이항분포를 정규분포로 근사하는 방법에 대해 공부했는데, 이항분포와 정규분포의 확률변수가 가지는 값이 서로 틀리기 때문에 이 과정에서 오류가 발생하지는 않을까? 라는 생각이 들었습니다. 이에 대해 탐구해 보기 위해 이항분포의 히스토그램을 그리고, 정규분포의 확률밀도함수를 그려 비교해 본 결과 그래프상의 면적, 즉 확률의 차이가 있다는 것을 알게 되었습니다. 이항분포가 실제로 가지는 값을 파이썬 프로그래밍으로 계산해 본 결과, 실제 이항분포가 가지는 값과 정규분포로 근사했을 때의 값이 약 0.01 정도 차이나는 것을 알게 되었습니다. 이를 보정할 수 있는 방법에 대해 탐구해 보며, 연속성 수정에 대해서 알게 되었습니다. 연속성 수정은 이항분포의 확률변수의 특징을 이용합니다. 예를 들어 이항분포를 따르는 확률변수 X에 대해 X=60일 확률은 X가 59.5 이상이나 60.5 이하일 확률과 동일합니다. 이항분포의 확률변수는 셀 수 있는 정숫값을 가지기 때문에, 위 부등식에서 X는 60밖에 존재하지 않기 때문입니다. 이 사실에 착안해서, 저는 정규분포의 확률변수를 양쪽으로 0.5씩 늘리면 (설명이 조금 잘못됐다는 걸 느꼈습니다) 그래프의 면적 차이가 줄어든다는 것을 알게 되었고, 연속성 수정을 한 경우와 아닐 때, 각각 정규분포로 근사했을 때의 값을 실제 이항분포의 값과 비교해 보니 연속성 수정을 한 경우가 더 근접한다는 것을 알게 되었습니다."},{"q":"수학 교과목을 많이 들었는데... 그중 가장 좋아하는 과목이 뭔가요?","a":"제가 가장 좋아하는 수학 교과목은 미적분과 고급수학I 과목입니다. 수학2 교과목에서 학습한 미분과 적분을, 저에게 익숙한 다항함수가 아닌 초월함수에도 사용할 수 있다는 것을 알고 큰 흥미를 느끼게 되었습니다. 고급수학I 과목은 통계학에서 다양한 데이터들을 다룰 때 많은 데이터들을 행렬로 간편하게 나타낼 수 있다는 점에서 더 열심히 공부했던 것 같습니다."},{"q":"요즘 빅데이터다 뭐다 많이 하는데... 인공지능에 대한 자신의 생각은 어떠한가요?","a":"저는 인공지능이 아직 인간을 대체하기에는 부족하다고 생각합니다. 인간과 인공지능이 효율적인 분야가 서로 다르기 때문에, 어느 한쪽이 대체되기에는 아직 이르다고 생각합니다. 인공지능은 반복적인 일에 능숙합니다. 예를 들어 한 공장에서 똑같은 제품을 계속 생성하는 것과 같이, 반복적인 일에 효율적으로 활용할 수 있습니다. 인간은 창의적인 분야에서 더 효율적이라고 생각합니다. 창의적이거나 인지적인 활동, 예를 들어 음악을 작곡하거나 미술 작품을 만드는 등의 활동에서 인간이 효율적일 수 있다고 생각합니다. 따라서 저는 아직 인공지능이 인간을 대체하기에는 이르다고 생각합니다.(시사 문제는 생각을 못 해서 제대로 답변을 못 했습니다.)"},{"q":"가장 기억에 남는 책이 있나요?","a":"(수학과 관련된 책을 원하시는 거 같은데, 생각이 안 나 과목에 상관없이 읽은 책을 선택했습니다.) 저는 나쓰메 소세키라는 일본 작가가 쓴 “마음”이라는 책이 생각납니다. 그 책은 세대가 진행됨에 따라 소외되는 존재들을 다룬 책입니다. 저는 이 책을 읽으며, 아직 우리 사회에는 소외되고 있는 존재들이 많다고 느꼈습니다. 특히 복지 사각지대, 정부가 운영하는 보건 정책에서 소외되고 있는 사람들에 대해 생각해 보게 되었고, 보건통계학으로의 진로를 변경하게 된 계기 중 하나가 되었습니다.(공통 질문이 지원동기 빼고 모두 준비 안 한 게 나와서 당황했습니다.)"},{"q":"아까 보건통계학자가 꿈이라고 했는데, 그거 말고는 다른 진로를 생각해 본 적은 없나요?","a":"저는 보건통계학 말고도 인공지능에 대해 관심이 많습니다. 특히 딥러닝의 인공신경망에 관심을 가지고 있는데, 인공신경망이 사람의 신경세포와 유사한 구조를 가지고 있기 때문입니다. 저는 인공신경망에 대해 탐구해 보며 인공신경망이 생명과학이랑 어떻게 융합될 수 있는지, 사람의 신경세포와는 어떤 차이점을 가지고 있는지 공부해 보고 싶습니다. 그렇기 때문에, 저는 보건통계학자 말고도 인공지능 연구자라는 진로도 가지고 있습니다. (이 질문 중 2분 남았다는 노크가 들렸습니다.)"},{"q":"진로가 구체적으로 어떻게 되나요?","a":"보건통계학자가 아닐 때의 진로를 말씀하시는 건가요...? (앞에서 하신 질문 때문에 헷갈렸습니다. 교수님: 아뇨, 보건통계학자도 다양한 종류가 있잖아요. 그 중에 구체적으로 어떤 건지.) 아 넵. 저는 보건통계학을 전공하여 미래에 국제기구에서 일하고 싶습니다. 전 세계에는 다양한 국제기구들이 있는데, 그 중 유엔의 WHO나 FAO에서 일하고 싶습니다. 두 기관은 모두 감염병을 예방하며 이에 대한 대응 방안을 연구하는 기관입니다. 감염병은 앞으로도 우리 인류를 계속해서 찾아오기 때문에, 보건통계학자로서 유엔의 WHO와 FAO에서 일해보고 싶습니다. (FAO도 인수공통감염병 관련 연구를 하기 때문)"},{"q":"학교 입학해서 가장 하고 싶은 일이 무엇인가요?","a":"제가 학교 입학해서 가장 하고 싶은 일은...(10분이 끝나고 진행요원이 들어옴. 재능기부 활동이나 공공데이터를 활용한 대회에 나가보고 싶다고 답변할 예정이었음.) 후배들을 위한 조언 면접 대기 중 자료를 볼 수 있는지의 여부는 학과마다 다르니 전날 최대한 다 읽어보고 가는 것을 추천해 드립니다. 만약 자료를 못 보는 경우, 가만히 앉아서 계속해서 스스로 질문해 보고 답변을 해보면서 복기하는 걸 추천해 드립니다. 대기실 및 고사장은 많이 따뜻한 편이니 너무 두껍게 입지 않도록 하고, 긴장하면 평소에 생각하던 루틴도 잘 안되니 계속해서 모의 면접 등을 통해 몸에 습관으로 익히시는 걸 추천해 드립니다. 실제로 저도 처음에는 단어를 끊어 발음하며 속도를 조절했는데, 어느새 후반부로 가니 숨도 안 쉬고 말하고 있는 저를 발견할 수 있었습니다. 대기실 내에선 간식도 섭취하면 안 된다고 들었으며, 물만 마실 수 있습니다. 면접 진행요원분들도 굉장히 친절하셨습니다. 다양한 후기들을 보면서 정말 말로만 분위기가 편하다고 하신 줄 알았는데 제가 직접 겪어보니 정말 편하게 하셨습니다. 압박 면접을 하려는 분위기는 아니었고, 저 같은 경우에는 꼬리 질문도 없어서 많이 놀랐습니다. 또, 오전 면접자분들은 숙소 잡으실 때 서울대 내에 있는 호암 교수회관으로 잡으시는 걸 추천드립니다! 외부인도 예약할 수 있으며, 서울대 내에 있고, 셔틀버스도 있다고 하네요. 제가 예약할 때에는 이미 예약이 다 차있어서 신림동 쪽으로 잡았는데, 지하철로 약 2~30분 정도 걸렸던 것 같습니다.공통 질문은 많으면 많을수록 좋습니다. 저도 자기소개, 지원동기, 장단점, 가치관, 리더십 발휘 경험, 가장 인상깊은 활동, 마지막으로 하고 싶은 말 정도 준비하고 이 정도면 충분하다고 생각했는데 지원동기 빼고 하나도 안 나와서 당황했습니다. 서울대는 책 좋아하니 인상깊었던 책에 대한 질문도 준비하시고, 전공 관련 시사에 대해서도 조금 알아보고 가시는 게 좋아요!수능 끝나고 꼭 바로 생기부 공부하시는 걸 추천드립니다! 생각보다 숙지해야 할 양도 많고 복습해야 할 책도 많을 겁니다. 놀고 싶겠지만 2주만 꾹 참고 끝까지 최선을 다하시길 바라요.2024 대입 면접후기"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"서울대학교","dept":"독어교육과","jeonhyeong":"학생부종합(일반제시문 풀기 -> 면접실 입실 -> 제시문에 대한 답하기 -> 추가 질문)","method":"(제시문에 대해) -> 생기부 관련 탐구 질문 -> 교직인적성 제시문 풀기 -> 면접실 입실 -> 문제 1번에 대해 답하기 -> 1번 문제에 대한 추가 질문 -> 2번 문제 답하고 추가 질문 -> 3번 문제 답하고 추가 질문","notes":"면접 시간이 75분가량 되기 때문에 지치지 않고 이어갈 수 있는 힘이 필요해요.","qa":[{"q":"독일교육에 대해서 연구했다고 되어있는데 뭘 연구했는지 말해줄 수 있나?","a":"저는 독일 시민교육을 접한 후로 교육에 관심이 생겼기 때문에 독일 시민교육에 대해서 탐구해 보았습니다. 독일 시민교육은 보이텔스바흐 협약을 공동토대에 두고 진행되고 있다는 것을 알 수 있었습니다. 이것은 교사가 현재 사회의 논쟁에 대해서 주입식 교육이 아닌 학생들 스스로가 주체성을 가지고 논쟁거리에 대해 자유롭게 의견을 나눌 수 있는 교육환경을 조성해야 한다는 내용을 담고 있습니다. 현재 사회 문제 현안에 대해 학생들이 스스로 생각하고 생각을 공유한다는 점에서 한국 교육이 배울 점이 많다고(?) 생각했습니다."},{"q":"한국 교육이 어떻길래?","a":"저의 경험으로 말씀드리자면 현재 사회 문제에 대해 토론하거나 생각을 공유하는 수업이나, 교육 등이 미흡했습니다. 그러나 지금은 교육 개정, 수업 혁신으로 인해 학교에서 토론수업, 문제에 대해 의견을 나누는 수업 등이 많이 도입된 것으로 알고 있습니다. ▶교직인적성 제시문 면접"},{"q":"AI와 교사가 해야 할 일을 구분해 볼 수 있나?","a":"AI 도입으로 개별 학생들에게 더욱 맞춤형 학습지원이 가능해질 것입니다. 기존에는 1명의 교사가 다수의 아이들을 똑같은 내용을 가르쳤지만, AI 교사로 개별 학생들에게 맞는 수준의 교육을 통해 학습의 질을 높일 것입니다. 교사는 여기서 학생들과 감정과 정서를 보듬어 주고 올바른 길로 이끌어줄 수 있는 지도자 역할이 더욱 강조될 것입니다. 인간만이 할 수 있는 공감과 인정을 통해 학생들이 자존감을 높이고 자아를 형성할 수 있도록 할 것입니다."},{"q":"독일어 교사를 별로 안 뽑는데 교사가 되지 않을 시 고려해 본 진로가 있나?","a":"저는 독일교육에 관심이 많기 때문에 독일교육에 대해 연구하고 이를 바탕으로 한국 교육과 상호 발전할 수 있는 정책을 만들고 싶습니다. 독일교육은 정치교육이나 주체성을 기르는 교육을 중점으로 하고 있기 때문에 한국 교육에 주는 시사점이 충분히 많을 것이라고 생각합니다."},{"q":"교사를 하다보면 나쁜 일이 생길 수 있을 텐데 꼭 교사가 좋은 직업이라고 할 수 있는가?","a":"교권 침해를 예시로 들어 저라면 어떻게 대처할지 말해보도록 하겠습니다. 문제행동을 하는 학생이 충분히 마음을 터놓고 해결할 수 있도록 심리적이고 정서적인 부분을 지원할 것 같습니다. 교사와 감정의 상호 교류가 나타날 때 비로소 학생의 마음의 문이 열린다고 생각합니다. 따라서 상담과 지원을 통해 학생과 좋은 관계를 만들어 이상적인 방향으로 해결할 것 같습니다."},{"q":"마지막으로 하고 싶은 말은?","a":"교육을 더 나은 방향으로 바꾸고 싶기 때문에 저는 교육에 대한 연구를 토대로 더 나은 미래를 만들어가고 싶습니다 (잘 기억이 나지 않음)후배들을 위한 조언 제시문 면접이지만 생기부 관련 내용도 많이 물어보시기 때문에 이에 대한 철저한 대비가 필요합니다. 제시문 내용은 예측할 수 없어서 답변 틀에 대한 인지와 사전에 배경지식을 많이 알아두는 게 도움이 됩니다. 또한 교직인적성 면접은 자신의 교직관과 얼마나 지혜롭게 교사의 상황에 있어서 대처할 수 있는지 미리 생각해 두면 도움이 많이 될 것입니다. 2024 대입 면접후기"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"서울대학교","dept":"역사교육과","jeonhyeong":"학생부종합(일반[제시문면접] 제시문 구상(30분) -> 인문제시문 질문 1, 2 답변 -> 사회과학 제시문 질문 1, 2 답변 -> 사회과학 제시문 추가 질문 후 답변)","method":"-> 인문학 제시문 추가 질문 후 답변 (15분)[교직인적성 면접] 제시문 구상(15분) -> 제시문 간단 요약 ->질문 1답변 -> 관련 추가 질문 -> 질문2 답변 -> 관련 추가 질문 -> 질문 3답변 -> 관련 추가 질문 (15분)1. 8시 이후 본인인증 및 소지품 검사 끝나면 본인이 소지한 모든 물건을 압수(?)당합니다! 가번호가 뒷번호면 기본 2시간은 기다려야 하고","notes":"사정에 따라 3시간 이상 대기해야 합니다.2. 가번호가 접착형식으로 되어있어서 옷에서 굉장히 잘 떨어집니다. 3. 제시문 구상 시 연필과 타이머, A4모두 제공합니다.","qa":[{"q":"제시문 면접 (구상 30분 / 구술고사 15분)<인문학 제시문> - 역사의 허구성, 혼용성 관련 지문 / 홀로코스트에 대한 역사학자들의 상이한 해석<사회과학 제시문> - 초보운전 스티커 부착 여부에 따른 안전운전 여부에 대한 실험 / 세계 제2차 대전 전투기 보완 실험의 문제점","a":""},{"q":"(제가 들어갈 때 가번호랑 들고 온 연필이 우수수 떨어졌습니다. ㅎㅎ;;) 허허 연필처럼 떨지 말고~ 차분히 인문학 제시문 1번부터 문제 읽고 답변해주세요~","a":"(근데 제가 모르고 사회과학 제시문부터 읽었는데 교수님들께서 크게 개의치 않아 하셨어요! 답변만 잘하면 약간의 실수는 눈감아 주는 듯 해요~) 네, 인문학 제시문 1번부터 답변드리도록 하겠습니다. (가) 제시문에서 드러난 역사의 허구성에 대해 제가 생각한 정의를 말씀드리고 (나)와 (다)에서 드러난 역사의 허구성이 무엇인지 말씀드리도록 하겠습니다.Ÿ 제가 자세히 기억이 나지 않아서 정확한 구술답변을 적지 못하는 점 양해 부탁드립니다. 저는 역사의 허구성의 정의에 대해 먼저 두괄식으로 답변하였습니다. 제시문의 내용을 요약하여 답변한 뒤 허구성이 드러나는 이유를 ‘저자’와 ‘사료’라는 키워드를 활용하여 답변하였습니다. 역사학은 사료로 이루어지는 학문입니다. 따라서, 사료의 선별에 따라 현세대가 학습하는 역사의 구체적인 내용은 역사학자의 사료 선택에 따라 달라질 수밖에 없습니다. 하지만, 역사학자는 사람이기 때문에 주관성을 가집니다. 소설이 작가라는 필터링을 거쳐 당시 시대를 서술하듯이 역사학도 역사학자라는 필터링을 거치기 때문에 어느 정도의 주관성과 이와 관련된 허구성을 가지게 되는 것입니다. 이를 (나)와 (다)의 사례를 예로 들어 설명해 보도록 하겠습니다. (두 제시문은 홀로코스트 사건을 두고 각각의 역사학자가 서로 다르게 해석한 것을 비교하는 제시문이었습니다. 저는 먼저 (나)와 (다)의 공통점과 차이점에 대해 간략히 요약 서술한 뒤 이 제시문에서 보이듯이 저자의 해석에 따라 역사학의 해석 정도가 달라질 수 있다는 것을 강조하였습니다.)Ÿ 정확히 기억이 나지 않아 자세하진 않지만 이런 뉘앙스로 1번 질문을 답변하였습니다. 더 구체적이지 못한 점 정말 죄송합니다.Ÿ 또한, 해당 답변 이후 교수님께서 소설을 사료의 범위로 인정하느냐에 대한 간단한 질문을 하셨습니다만 이에 대한 저의 답변이 정확히 기억나진 않습니다... 다만, 인정하는 입장에서 간단히 답변했던 것으로 기억합니다.네 다음은 문제 2번 답변하도록 하겠습니다. (가)에서 드러나는 역사의 ‘혼용성’에 대해 답변한 뒤, 이러한 것이 다른 학문과 관련되어 어떻게 드러나는지 설명해 보겠습니다. 저는 평소 역사는 다양한 학문과 화합하고 소통하여 구성되는 것이라고 생각하였고, 이러한 역사의 특징이 바로 지문에서 말하는 “혼용성”이라고 생각합니다. 역사를 배경으로 다른 학문을 함께 탐구하면 더 폭넓은 이해를 할 수 있습니다. 사례를 들어 설명해 보도록 하겠습니다.(이후 다른 학문에서 역사의 혼용성이 드러나는 사례로 고대 에피쿠로스학파와 스토아학파, 서양의 실존주의 사상을 꼽았습니다. ‘철학은 시대의 요구에 응답하는 학문이다. ’라는 저의 의견을 말한 뒤, 해당 철학이 등장했던 역사적 배경과 철학이 당시 사람들에게 미쳤던 영향과 의의를 서술하였습니다.)"},{"q":"네, 이어서 사회과학 제시문 1번부터 답변해주세요","a":"네. 사회과학 제시문 1번 답변하도록 하겠습니다. 먼저 (가)와 (나) 실험에서 드러나는 공통점에 대해 답변한 뒤 차이점에 대해 서술하도록 하겠습니다.(사회과학 제시문에 대한 답변은 정말 기억이 잘 나지 않습니다. 그래서 부연 설명으로 대체하도록 하겠습니다. ㅜㅜ)저는 우선 공통점으로 ‘성급한 일반화’와 ‘확증편향’을 꼽아 이 두 키워드를 주축으로 실험 사례를 저의 방식으로 해석하여 서술하였습니다. 이후 차이점으로 ‘대조군’과 ‘실험군’의 유무와 실험군의 허용 범위를 꼽아 답변하였습니다.사회과학 제시문 2번 질문은 (가)와 (나)실험의 문제점과 비슷한 사례를 서술하라는 것이었습니다. 그래서 저는 19세기에 만연했던 ‘적극적 우생학’을 사례로 들어 설명하였습니다. 당시에 범죄자 가문을 조사하여 가문 전체의 유전인자를 열성으로 획일화 시켜버린 한 사건을 설명하여 답변했습니다."},{"q":"그러면 학생은 (가)와 (나) 실험과 같은 사례가 현대 사회에서 증가하고 있는 것 같아요 아니면 감소하고 있는 것 같아요? 학생의 생각을 그냥 자유롭게 말해 주세요.","a":"저는 정보의 확산에 비해 대중들의 정보 수용력과 비판력이 부족한 현 체제를 지적하며 대중들의 확증편향 심리에 따라 비대해진 정보량과 동시에 성급한 일반화의 현상이 더 심해지고 있다고 서술하였습니다.(이후 인문학 교수님의 꼬리 질문이 시작되었습니다...)"},{"q":"지금 시간이 좀 남아서~ 다시 인문학 제시문 관련해서 추가 질문 좀 할게요. 허허~ 학생이 아까 역사에는 허구성이 있다고 했는데, 그럼 학생은 역사가 그냥 다 허구라는 건가?","a":"저는 이 답변에 대해 역사가 온전히 다 허구적인 것이 아니라 ‘저자’라는 필터링으로 인해 주관이 개입되면서 어느 정도의 허구성이 가미될 수밖에 없다고 답변하였습니다."},{"q":"역사가 허구성이 있으면 자네는 역사과에 왜 들어오고 싶나? 어차피 허구인데 허허","a":"해당 질문에 대한 저의 답변이 즉흥적이었기 때문에 정확히 기억나진 않습니다. 다만, 저의 주장을 계속해서 밀어붙이며 ‘저자의 해석’이라는 키워드를 중심으로 입장을 유지하였습니다."},{"q":"그러면~ 우리 ‘허구성’을 ‘추론성’으로 바꿔보자~ 본인 생각을 말해봐요~ 역사의 본질은 ‘허구성과 사실성’ 그리고 ‘추론성과 사실성’ 이 둘 중에 뭐라고 생각해요?","a":"우선 이런 교수님들의 질문에 답변을 바꾸면 안좋다고 들었기 때문에 해당 질문에 대해서도 저의 입장을 유지하며 ‘추론성’에 대한 정의를 저의 입장에 맞게 재정립하여 교수님의 의견에 계속해서 반박하였습니다. 이렇게 인문학 꼬리 질문에 답변을 열심히 하다가 시간이 초과되어 나가야 했고, 그 길로 저는 교직인적성 질문에 답변을 하러 갔습니다."},{"q":"교직인적성 면접 (구상 15분 / 구술고사 15분)Ÿ 교직인적성 면접 제시문은 2003년 기사였고, 학생들의 직업 선호조사와 교사의 자질 관련 기사문이었습니다.Ÿ 해당 면접 교수님들은 각 질문에 대한 답변이 끝나자마자 추가적인 꼬리 질문을 이어나가는 방식으로 진행하셨습니다.","a":""},{"q":"네, 먼저 간단히 기사문 요약하고 질문 1번부터 답변해 주시겠어요?","a":"기사문은 핵심 위주로 3줄 요약하였고 질문 1번에 대해 답변하였습니다. 질문 1번은 해당 기사문 내용이 2023년에도 비슷하다고 생각하는지에 대한 이유를 말하는 것이었고 저는 직업 선호조사에서 교사가 1위를 한 것은 과거에만 해당하는 것이고 현재는 교권 추락과 자본만을 추구하는 황금만능주의로 인해 유효하지 않다고 하였습니다. 하지만 교사가 갖추어야 할 자질에 대해서는 불변하지 않는다는 답변을 하였습니다.이에 대한 꼬리 질문으로 교권 추락의 원인과 해결방안에 대해 물으셨고, 저는 교사들을 향한 존경심의 하락과 교사의 사회적 위상에 대한 추락을 위주로 답변하였습니다. 해결 방안으로는 이러한 사회적 분위기를 회복해야 한다고 답변하였습니다.그러자 이에 대한 꼬리 질문으로 교사의 존경심을 외부적으로 강제하거나 교사의 자질을 외부에서 규정하면 부작용이 생길 것 같다고 말씀하셨고 교수님께서는 이러한 부작용에 대한 본인의 생각을 말해보라고 하셨습니다.저는 외부적으로 규정한 교사의 자질과 교사의 경험으로 얻게 되는 자질은 다르다는 주장을 명시하며 교사라는 직업을 통해 습득하는 자질만이 진정한 교육자가 될 수 있는 방향이라고 서술하였습니다.이에 대한 꼬리 질문으로 교사가 되기 전에는 어디서 진정한 자질을 얻을 수 있냐고 여쭤보셨고 저는 교생실습과 교육 봉사활동을 통해 교사로서의 자질을 스스로 얻을 수 있다고 답변하였습니다."},{"q":"네, 다음 문제 2번 답변해 주세요.","a":"(문제 2번은 교사로서의 자질을 제시문 내용과 엮어서 서술하라는 것이었는데 해당 질문은 기사문의 내용을 간단히 요약하며 저의 생각을 즉흥적으로 덧붙여 대답하였습니다. 그래서 자세히 기억이 나지 않습니다. 죄송합니다.)"},{"q":"네, 마지막으로 문제 3번 답변해주세요.","a":"(문제 3은 질문 자체가 정확히 기억나진 않지만 역사교육과에 입학해야 하는 이유와 왜 역사교육이 필요한지 등을 답변했던 것 같습니다. 이후 역사가 교육계에서 갖는 위상에 대해 저의 생각을 묻는 꼬리 질문이 나왔고, 저는 교육과 역사의 공통점에 대해 서술하며 역사야말로 인간다움의 본질을 실현하는 학문이라는 저의 주장을 피력하였습니다.)후배들을 위한 조언"},{"q":"교수님들은 생각보다 정말 온화하십니다. 면접장 분위기 자체는 굉장히 좋습니다. 물론 본인의 답변에 따라 스스로 느끼는 압박감은 다를 수 있지만 과도하게 겁을 먹는 것은 멘탈 관리에 도움이 되지 않으니 약간의 긴장감과 넘치는 자신감으로 면접을 보시길 권장합니다!","a":""},{"q":"모의 면접 활동을 자주 하시길 바랍니다! 저는 실제로 면접 준비를 7일 정도밖에 못했습니다. 본인이 다른 경쟁자들에 비해 굉장히 늦게 시작했음을 인지하고 선생님의 피드백을 하루빨리 듣고 수용하고 고쳐나가야 합니다. 따라서, 학교나 외부에서 지원하는 모의 면접은 하루도 빼지 마시고 하세요. 수능 끝나고도 맨날 학교 남아서 몇 시간 넘게 면접 준비해야 하고 열심히 하려 해도 마음처럼 안되면 도중에 포기하고 싶으실 수 있습니다. (저도 부끄럽지만 선생님들 피드백 듣다가 서러워서 운 적이 정말 많았습니다...ㅎㅎ) 그래도 일주일만 꾹 참고 버티면 교수님들 앞에서 생각했던 것 보다 술술 답변하는 본인을 발견할 수 있을 것입니다. 할 수 있다는 생각과 함께 정진하세요! (첨언하자면 저는 서울대를 쓴 다른 친구들보다 내신이 더 낮았어서 ‘절대 안되겠지...’라는 생각으로 면접 준비 초반을 보냈습니다. 그런데 서울대 일반전형은 단순히 내신으로만 평가받는 자리가 아닙니다. 내신이 다른 친구들에 비해 부족하더라도 면접이나 생기부 내용으로 충분히 합격할 수 있으니 너무 부정적인 생각은 하지 마세요 ㅜㅜ)[제시문 조언]1-1) 제시문 면접은 일반 생기부 면접과 달리 본인의 배경지식이 많아야 합니다. 본인이 문과라면 인문학 제시문과 사회과학 제시문을 30분 동안 독해하고 답변을 구상해야 합니다. 그 질문의 깊이가 꽤 깊으니 본인 전공뿐만 아니라 그 외의 사회탐구 과목들의 개념을 어느 정도 학습하는 것이 필요합니다. 1-2) 저는 실제로 고2, 3 때 정치와 법, 윤리와 사상, 생활과 윤리, 동아시아사를 학습하여서 사회과학 제시문의 답변 수준이 인문학에 비해 매우 낮았습니다. 이를 극복하기 위해 면접 준비를 하며 통합사회 교과서를 3회독 하였고 사회문화 수능특강 중 필요한 부분만 우선적으로 선별하여 개별적으로 학습했습니다. 실제로 통합사회와 사회문화 교과서를 학습한 것이 사회과학 제시문에 대한 답변을 할 때 큰 도움이 되었습니다. 그러니, 만일 저처럼 올곧게 인문학의 길만 팠던 학생이라면... 통합사회와 사회문화를 공부하는 것을 추천드립니다.1-3) 또한, <벌거벗은 세계사>나 <벌거벗은 한국사>를 주기적으로 보는 것을 추천드립니다. 제시문 질문 중 비슷한 사례를 언급하라는 내용이 꽤 많습니다. SNS나 OTT 서비스를 이용하여 본인이 가장 끌리는 회차를 몇 편 보다 보면 사례에 대한 답변을 꽤 원활히 할 수 있을 것입니다. -> 해당 영상을 보는 것에만 그치지 말고 이러한 사례가 현재에도 반복되고 있는지, 역사적으로 어떤 의의를 가지는지, 교훈이 무엇인지를 생각하며 보시길 권장합니다. 제시문의 내용과 본인의 배경지식을 엮는 능력을 키워줄 수 있습니다.*저는 실제로 사회과학 제시문에서 해당 실험 내용의 문제점과 비슷한 사례를 언급하라는 질문을 받았고 ‘성급한 일반화’라는 키워드를 공통점으로 꼽아 <벌거벗은 세계사>에서 본 19세기 적극적 우생학에서 발생한 유전자의 일반화 사건들을 비슷한 사례로 답변하였습니다.1-4) 본인이 아는 학문적인 개념과 제시문 내용을 엮어 말하는 능력이 굉장히!! 중요합니다. 본인이 학교에서 배운 개념 (ex. 사회문화-기능론, 갈등론)들이 사회에서 어떻게 적용되는지, 현대적인 관점이나 사건들에서는 어떻게 드러나는지를 아주 많~이 생각해 보세요.[교직인적성 면접 조언]2-1) 본인이 생각하는 교육의 의의에 대해 숙고해보세요. (물론 교수님들에 따라 다르지만) 교직인적성 면접은 제시문 면접에 비해 꼬리 질문이 굉장히 많았습니다. 제시문의 질문 외에도 본인의 교육관에 대해 물을 여지가 충분히 있는 면접입니다. 그러니 평소에도 본인은 왜 교육자가 되고 싶은지, 교육이 사회에 어떤 영향을 줄 수 있는지, 교육의 정의 등등을 사색해 보시길 바랍니다. *평소 본인이 교육계에 대한 꿈이 확고했다면 교직인적성 면접은 제시문에 비해 원활할 것입니다 :-)2-2) 교원대 제시문으로 모의 면접 많이 해보세요! 개인적으로 교원대 제시문 질문이랑 서울대 교직인적성 면접 질문이 가장 유사한 것 같습니다. 그리고 제시문 내용이 교원대가 훨씬 구체적이어서 서울대가 오히려 더 괜찮다고 느꼈습니다. 2-3) 교직인적성은 제시문 면접 끝나고 진행됩니다. 그러니 제시문이 망했다고 슬픔에 잠식되지 말고 ‘여기선 진짜 할말 다하고 나온다.’라는 마인드로 임하시면 분명 좋은 결과가 있을 것입니다!2-4) 교권 침해 같은 최근 교육 이슈 관련 신문을 많이 읽어보는 것이 좋습니다. 신문 읽는 것에만 그치지 말고 본인이 이런 상황이면 어떻게 해결할 건지, 해당 교육 이슈가 생긴 원인은 무엇인지와 앞으로 나아가야 할 방향까지 고심해 보세요!2-5) 본인이 왜 00교육과에 지원했는지와 00과목이 교육계에서 필요한 이유, 학생들에게 미치는 긍정적 영향 등에 대해 생각해 두세요!2-6) 이건 하이텍고 모의 면접에서 들은 이야기인데, 서울대학교는 재학생들이 단순히 교사에서만 그치는 것이 아니라 더 나아가 교육정책이라든지, 장학사 등 광범위적으로 영향을 미치는 사람이 되는 것을 좋아한다고 합니다. 그러니 만일 00교육과에 입학하여 어떤 일을 하고 싶냐는 질문을 받는다면 00교사에서 더 나아간 자신만의 목표를 최대한 야심 차게 말씀하시는 것이 좋을 듯 합니다.*저도 실제 면접에서 교사에서 더 나아가 교육정책에도 목소리를 내는 영향력 있는 교육계 인사가 되고 싶다고 답변하였습니다.이상으로 글을 마치겠습니다. 이 글을 읽고 있을 여러분들의 입시가 무사히 마무리되시길 응원하겠습니다! :-)2024 대입 면접후기","a":""}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"서울대학교","dept":"윤리교육과","jeonhyeong":"학생부종합(지역균형)","method":"인사 -> 아침밥 질문 -> 활동 관련 질문 -> 전공 질문-> 활동 관련 질문 -> 학업 질문 -> 학과 질문 -> 활동 질문아침에 생각보다 차가 막히니까, 오전조면 전날 서울 올라가서 아침","notes":"일찍 출발하기입실 마감되면 다 제출해야 하니까, 그 전에 충분히 자료 숙지하기(그전까지는 대기실에서 아이패드 필기까지 볼 수 있음)","qa":[{"q":"밥 먹고 왔어요?","a":"넵. 간단하게 빵이랑 바나나 먹고 왔습니다."},{"q":"간단하게 먹고 오셨군요(웃으심). 혹시 여기 메타버스 관련 활동을 했다고 적혀있고, 이 메타버스 수업이 정서적 상호작용 측면에서 우세하다고 결론을 지었다고 했는데요, 줌 수업과 차별화되는 메타버스 수업만의 특징이 무엇인지?","a":"저는 메타버스 관련 특강을 들으면서, 그 차별점을 파악했습니다. 그 특강에서는 메타버스를 활용한 마케팅 사례를 보여주었는데요, 거기에서는 아바타간 몸짓, 거리를 통해 다양한 상호작용을 구현하고 있었습니다. 이러한 몸짓, 거리 조절은 줌 수업에서는 하지 못하는 것이기 때문에 이러한 점이 줌 수업에서 나타난 삭막한 정서적 상호작용에 영향을 주었다고 생각했습니다."},{"q":"관련 활동 하면서 초등학생 대상의 실험을 진행했다고 하는데 이 점에서 어려운 점은 없었나요?","a":"물론 말을 안 듣는 문제가 발생하였으나, 다 같이 규칙을 정해, 가장 규칙을 잘 지킨 친구에게 상품을 지급하는 식으로 문제를 해결할 수 있었습니다."},{"q":"(웃으심) 화법과 작문 시간에 니코마코스 윤리학을 읽고 자족성에 대해 학습한 이후 윤리적 질문에 대한 고찰을 했다고 적혀있는데 설명 좀 해주세요.","a":"저는 지문 분석을 하다가 이해가 안되는 문장이 있어서 그 책을 읽게 되었습니다. 그 문장은 바로, 자신에게 압도적으로 중요한 원칙은 그 행위의 이유를 물을 수 없다 라는 문장이었습니다. 선생님께 도움을 요청하니, 그 책이 자족성에 관련된 개념이라고 하시며 니코마코스 윤리학을 읽어보라고 하셨습니다. 그래서 그 책을 읽고 자족성에 대해 알아보았는데요, 자족성이란, 그 자체로 완벽하여, 이것을 추구해야 하는 이유에 대해 답할 수 없으며, 그 자체로 추구할 수밖에 없는 성질이라고 알게 되었습니다. 이를 앞 문장에 적용하여 개인에게 가장 압도적으로 중요한 원칙이란, 그 자체로 완벽하기에, 행위의 이유를 물을 수 없다는 결론을 도출할 수 있었습니다."},{"q":"시소형 의사결정 모델을 적용했다고 나와 있는데, 이게 무엇이고 현실에서는 어떻게 적용하고 있는지?","a":"시소형 의사결정 모델은 제가 만들어본 의사결정 모델이기에, 현실에서 어떻게 적용되었는지에 대해는 답변을 못할 것 같습니다(흥미로워하심). 시소형 의사결정 모델은 see-saw라는 뜻인데요, 말 그대로 보고 또 본다는 의사결정 모델입니다. 우선 처음 의결 과정을 거칩니다. 이후 차득표 안건..차득표 안건..혹시 다시 말씀드려도 되겠습니까?"},{"q":"네. 천천히 말씀해 주세요.","a":"우선 처음 의결 과정을 거칩니다. 이후 그 의결에서 선정되지 않은 차득표 안건을 제안한 학생들이 다시 한번 자신이 그 안건을 선택한 이유에 대해 이야기하는 시간을 거칩니다. 이후 간단한 토론을 거치고, 2차 의결을 한 결과를 최종 의결 결과로 정합니다. 저는 이것을 학생회 의사 결정 과정에 적용해 보았습니다."},{"q":"(교수님이 무언가 물어보려고 하셨지만, 옆에 계신 분께서 먼저 질문하셔서 멋쩍게 웃으심)학업에서 가장 힘들었던 게 있나요?","a":"저는 불안함이 저를 가장 힘들게 만들었던 요인이 아닌가 싶습니다. 경쟁 시스템 속에서 남들보다 뒤쳐져서는 안된다라는 불안감 때문에 제 공부 계획까지 망가뜨려가며 사교육에 참여하기도 하는 등 굉장히 방황했던 기억이 있었습니다. 하지만 저는 이후 사교육을 그만두고, 저와의 싸움을 하며, 공교육에 많이 의지하게 되었습니다. 저만의 계획을 세우고, 모르는 것이 있으면 선생님에게 적극적으로 질문하였습니다. 선생님은 항상 저에게 웃으며 답변해 주셨고, 이 과정에서 공교육에 대한 애착이 커지게 되었습니다. 그렇기에 저는 이 공교육을 제공하는 선생님 혹은 교육 연구원이 되겠다는 진로를 더욱 확고하게 가지게 되었습니다."},{"q":"그런데 웃으며 대답해 주는 것은 사교육 선생님도 할 수 있는 것 아닌가요?(웃으심)","a":"물론 지식 전달은 사교육 선생님이 대체할 수 있는 부분이지만, 학교라는 사회 속에서 학생들과 상호작용하며, 학생들에게 올바른 가치관을 심어주고, 올바른 방향으로 나아가도록 도와주는 역할은 공교육 선생님들만 할 수 있다고 봅니다. 사교육은 단순히 정보전달을 목적으로 하고 있지만, 공교육은 이를 넘어서는 목적을 담당할 수 있기에 차별성이 있다고 생각합니다. (끄덕끄덕)"},{"q":"다른 대학교는 학과를 어떻게 쓰셨나요?","a":"윤리교육과와 교육학과 위주로 썼습니다."},{"q":"(약간 표정 찡그리시며 조심스럽게) 혹시 교대는 안 썼죠..?","a":"교대는 쓰지 않았습니다. (좋아하심)[1분이 남았다는 노크 소리]"},{"q":"마지막으로 여기 활동 중에 귀여운 활동 이름이 있어서 혹시 꿀벌 선생님 제도가 무엇인가요? (셋 다 웃음)","a":"답변드리도록 하겠습니다. 꿀벌은 분업이 굉장히 잘 되어있는 곤충인데요, 이 점에서 착안해 선생님들의 분업 아이디어를 제시해 보았습니다. 아이들을 관찰하는 관찰 교사, 상담을 하는 상담교사, 아이들의 수업을 설계하는 수업 교사 등 분업을 통해 학생들 개개인에 집중하고, 이에 맞는 수업을 설계함으로써 동아리 활동에서 제시한 [답변 중간에 끝났다고 문 열고 들어오심] 맞춤형 교육과정을 실현하기 위한 제도였습니다. (끄덕끄덕)감사합니다!"},{"q":"네 수고했어요.후배들을 위한 조언 물론 학과마다 다르고, 들어오는 교수님마다 다르겠지만, 저는 너무 편한 분위기였습니다. 최대한 면접관님들 반응까지 기억나는 대로 적어봤는데, 위에서 느끼셨겠지만 하는 말마다 웃어주시고 끄덕끄덕 해주시고 그러셔서 친한 선생님들과 대화하는 느낌이었습니다. 그러니까 긴장할 필요 하나 없고 들어가기 전에 긴장한다고 생각하면 더 긴장되니까 억지로라도 ‘긴장 하나도 안 되는데?’ 이렇게 마인드 컨트롤 하시면 좋을 것 같아요!2024 대입 면접후기","a":""}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"서울대학교","dept":"의예과","jeonhyeong":"학생부종합(기회균형[면접 절차]12:30까지 신분증, 수험표 확인 -> 12:40에 면접 방식 프레젠테이션)","method":"-> 3조로 6명씩 나누어 1시간씩면접 (1:30-2:30 / 2:30-3:30 / 3:30-4:30)[면접 과정]5개의 방(제시문 방 4개 10분씩(2분 제시문 숙지, 8분 면접) + 서류기반 면접 20분(2분 대기, 18분 면접)","notes":"서울대 면접 방의 개수는 매년 달라진다고 하니 정형화된 것은 아님","qa":[{"q":"그래프 해석","a":""},{"q":"그래프 분석해 보세요.","a":"이 그래프는 자기 객관화에 대한 그래프인 것 같습니다. a, b, c는 실제 점수보다 예상 점수가 높은 것을 보아 자기 객관화가 잘 되어있지 않은 것 같습니다. 그리고 a, b, c,순으로 자기 객관화가 더 많이 안되어 있음을 그래프 간 격차로 파악할 수 있었습니다. 반면에 d는 실제 점수보다 예상 점수가 낮은 것으로 보아 겸손한 성격의 사람인 것 같습니다."},{"q":"d와 같은 사람의 장점은 무엇일까요?","a":"d와 같은 사람은 겸손하다는 점이 장점입니다. 겸손함은 사회생활에 있어 다른 사람에게 좋게 보일 수 있다고 생각합니다. 자신을 낮춤으로써 겸손함을 보여줌으로써 다른 사람에게 공손함을 표현할 수 있습니다.#(추가 제시문)"},{"q":"a, b, c, d 학생에게 리더로서 어떤 활동을 맡길 건가?","a":"a 학생의 문제점은 지식과 자신감 모두 부족하다는 점입니다. 그래서 저는 이 부분을채우도록 돕기 위해서 제가 함께 자료조사, ppt를 만들면서 옆에서 자신감을 북돋아 주고,자료조사를 함께하며 지식을 쌓도록 도와주겠습니다. b학생은 지식과 경험이 부족한 것이문제이기에 자료조사를 시켜서 스스로 지식을 쌓도록 도와주겠습니다. c학생은 모난 점이딱히 없기 때문에 모든 과정에 있어서 필요할 때 도와주도록 하겠습니다. 과제 수행 시항상 원하던 대로 되는 것이 아니라 예기치 못한 상황이 발생하기 때문에 이를 막는 데활용하겠습니다. 마지막으로 d학생에게는 발표를 시키겠습니다. d는 자신감이 넘치기때문에 학우들에게 조사한 내용을 잘 전달할 수 있을 것이고 많은 지식을 바탕으로 돌발질문에도 잘 대답할 수 있을 것이라 생각하기 때문입니다."},{"q":"a, b, c, d 같은 경험을 겪은 적이 있는가?","a":"고등학교에 막 입학할 때 b와 같았습니다. 고등학교 생활의 경험은 적었지만 자신감이넘쳤습니다. 그러나 고등학교 생활을 하며 생각보다 힘들다는 것을 깨닫고 a와 같은 상황이되었습니다. 하지만 저는 친구들과 학교생활을 하면서 점점 자신감을 되찾았고 c, d와같은 친구로 발전할 수 있었습니다."},{"q":"자신이 이런 그림을 8개 그리는 일을 담당할 때 어떻게 지시할 건가요?","a":"우선 이 8개를 저 혼자 그리기에는 무리라고 판단이 들었습니다. 그래서 8개로 조를 나눠서 각 조에게 이 그림을 그리게 하겠습니다. 8개 조의 각 조장을 정하고 이 조장을 불러 제가 담당자로서 지시할 부분을 알려주겠습니다."},{"q":"그림이 복잡한데 어떻게 똑같이 보고 그릴 건가요?","a":"이 그림은 잔치 특성상 많은 시민들이 질서 없이 정조의 행차를 구경하고 있고, 행사 과정에서 다양한 깃발, 다양한 복장의 사람들이 서있습니다. 이를 똑같이 그리기 위해서는 각 부서가 그림의 각 부분을 맡아서 글로 그림에서 세세한 부분인 배치도, 색깔 등을 어느 정도 묘사하고, 그림으로 광경을 보면서 머릿속으로 그리게 하겠습니다. 그리고 이것들을 바탕으로 최대한 비슷하게 그릴 수 있도록 제가 옆에서 도와주겠습니다. 이렇게 하면 최대한 똑같이 재현할 수 있다고 생각합니다.#(추가제시문) 그림을 못 찾았습니다. 벨기에의 그림으로, 성모마리아 추모 행사에서 사람들이 똑같은 옷을 입고 놀이공원에서 줄을 서는 것처럼 한 명씩 질서 있게 서있었습니다."},{"q":"그림의 차이점을 말하세요.","a":"첫 번째 그림은 잔치 특성상 다양한 민중들이 다양하게 질서 없이 서있습니다. 그리고 색깔이 다양합니다. 반면에 두 번째 그림은 추모식으로 모든 사람들이 질서 있게 검은색의 같은 옷을 입고 줄 서 있습니다."},{"q":"동양과 서양의 차이는요?","a":"동양과 서양의 예술에서의 차이는 여백의 미가 있습니다. 첫 번째 그림은 비교적 여백의 미가 있지만 두 번째 그림은 빽빽하게 채워진 것을 볼 수 있습니다."},{"q":"자신이 이렇게 경험하고 본 것을 그릴 수 있다면 어떤 그림을 그릴 건가요?","a":"저는 어릴 때 증조할머니께서 돌아가셨을 때 경험했던 장례식장의 그림을 그리고 싶습니다. 어린 나이였지만 증조할머니의 죽음을 슬퍼하시는 할머니와 아버지의 모습이 마음속에 깊이 남아있기 때문입니다. 장례식장에서 저희 일가족은 슬퍼했지만 다른 사람들은 술을 마시며 즐기고 있었습니다. 그 당시에는 이해가 안 됐지만 지금 와서 생각해 보니 슬픔을 덜어주기 위해서였다는 것을 알 수 있었습니다. 이렇게 장례식장에서의 경험은 저에게 죽음에 대해 생각해 보는 계기를 제공했기 때문에 그 당시 상황을 그림으로 묘사하고 싶습니다."},{"q":"장례식장 그림에서 주인공은 누구이고 당신은 어떤 위치에 있나요?","a":"주인공은 돌아가신 증조할머니입니다. 증조할머니를 둘러싼 사람들의 반응을 그리고 싶기 때문입니다. 저는 전지적 작가 시점으로서 작품 밖에 있으며, 작품을 본 것을 그림으로 표현하겠습니다."},{"q":"내가 그린 그림 안에 내가 없으면 서운하지 않을까요?","a":"장례식장에서 제가 보고 느낀 것을 표현하고 싶기 때문에 제가 그림 속에 없어도 서운하지 않을 것 같습니다. 제가 밖에서 관찰하면서 표현할 수 있는 것을 최대한 섬세하게 표현하고 싶습니다."},{"q":"경시대회 문제학교에서 수학경시 대회 1인을 뽑아 전국 수학 경시대회에 나가기로 했다. 그러나 선우와 정한이 두 명이 동점으로 공동 1등을 하였다. 그래서 선생님께서 일주일 뒤에 재시험을 치르기로 하였다. 한편 선우는 곧 시험이 있어서 오늘부터 시험 공부를 하려고 했다. 하지만 재시험 때문에 재시험을 치르고 시험공부를 미루기로 하였다.","a":""},{"q":"정한이가 재시험을 1주일 미루자고 했다. 당신이 선우라면 어떻게 할것인가?","a":"정한이가 재시험을 왜 미루자고 했는지 그 이유를 물어보겠습니다. 선우는 안 그래도 재시험 때문에 시험공부를 미뤘는데 재시험이 미뤄지면 시험공부를 더 못하기 때문에 미루고 싶지 않을 것입니다. 그렇기 때문에 제가 선우라면 정한이와 대화하면서 정한이의 사정을 들어보고 함께 대화를 통해 풀어나가겠습니다."},{"q":"선우가 일요일마다 아프신 아버지를 도와야 한다. 당신이 선우라면 어떻게 할 것인가?","a":"선우가 일요일마다 아버지를 돌봐야 하는 것은 자신과의 약속입니다. 선우라면 이 약속을 깨고 싶지 않을 것입니다. 그래서 저는 정한이와 선생님에게 제 사정을 잘 말하고 제 심정을 이해시키려고 노력하겠습니다."},{"q":"다른 친구로 인해 피해를 봤던 경험이 있는가?","a":"조별 활동을 하는데 한 친구가 독감에 걸려서 참여하지 못했던 경험이 있습니다. 저희는혈액난을 해결하기 위해 대한적십자단에 가서 견학하고, 포스터를 만들어 친구들의 헌혈자수를 늘리는 활동을 하고 있었습니다. 그런데 독감에 걸린 그 친구가 모둠활동에서 중요한역할을 맡고 있어 활동에 차질이 생겼습니다. 그러나 독감은 걸리고 싶어서 걸린 게 아니라어쩔 수 없이 걸린 것이기 때문에 모둠원들에게 이 친구를 이해하자고 말했습니다. 다행히모둠원 친구들이 동조를 해주어 그 친구의 불가피한 상황을 이해하고 제가 더 열심히해서 활동을 이끌어 나갔습니다."},{"q":"위왕 문제위왕 위나라 충신이 태자를 데리고 한나라로 잡혀갔다. 충신이 한나라에 가기 전에 위왕에게 몇 가지 질문을 했다.‘만약 한 사람이 와서 저기 호랑이가 있다고 하면 믿으실 겁니까?’라고 충신이 물어보자위왕은 ‘아니’라고 했다. 다시 ‘그럼 두 사람이 와서 저기 호랑이가 있다고 하면 믿으실 겁니까?’라고 충신이 물어보자 위왕은 ‘반신반의하지’라고 했다. 마지막으로 ‘세 사람이 와서저기 호랑이가 있다고 하면 믿으실 겁니까?’라고 하자 위왕은 ‘응’이라고 했다.이말을 듣고 충신은 태자와 함께 한나라에 갔다. 이후에 대자는 위나라로 돌아왔지만충신을 돌아오지 못했다.","a":""},{"q":"이 제시문이 무엇을 묻는 거라고 생각하는가?","a":"마지막 문장을 보고서 충신이 위왕과 한 대화를 토대로 왜 충신이 돌아오지 못했는지를묻는 제시문인 것 같습니다."},{"q":"왜 충신은 돌아오지 못했다고 생각하는가?","a":"위왕의 말만 믿고 숫자에 집착했기 때문이라 생각합니다. 어떤 일이 일어나 판단 해야하는 상황에서는 그 상황의 맥락을 이해하는 것이 중요합니다. 그런데 충신의 위왕에게들은 ‘3’이라는 숫자에 집착하여 상황의 맥락이나 사건의 경위를 파악하지 않아 불화를입어 돌아오지 못한 것 같습니다."},{"q":"답변 수가 많으면 자료의 신뢰가 높아진다고 생각하는가?","a":"네. 어느 정도는 그렇다고 생각합니다. 제가 헌혈자 수를 높이기 위해 헌혈을 하지 않는이유에 대해 설문조사를 한 적이 있습니다. 이때 설문조사를 많이 하면 할수록 다양한의견을 바탕으로 자료의 신뢰도가 높아졌다고 생각합니다."},{"q":"타인의 말을 듣고 판단력이 흐려진 경험이 있는가?","a":"네. 제가 반장 생활을 하면서 한 친구가 다른 친구들이 자기를 무시한다고 해서 그 친구의말만 듣고 다른 친구들을 불러 질책하듯 얘기했던 적이 있습니다. 그런데 알고 보니 한친구가 다른 친구들의 험담을 하고 다녀서 다른 친구들이 그 아이를 무시했던 것이었습니다. 그래서 저는 이 상황을 알게 되고 나서 다른 친구들에게 섣불리 판단한 것을사과했습니다. 그리고 서로 잘 지낼 수 있도록 도와주었습니다."},{"q":"판단력이 흐려지는 이유가 무엇이라고 생각하는가?","a":"판단을 할 때 적용해야 하는 자신만의 기준이 명확하지 않아서인 것 같습니다. 무언가를 판단할 때 저는 우선순위와 같이 자신만의 판단하는 기준이 있어야 한다고 생각합니다. 이렇게 저는 제가 학교생활에서 정해온 저의 우선순위를 바탕으로 나중에 의사가 되어서도 중요한 순간에 판단을 잘할 수 있는 의사가 되고 싶습니다."},{"q":"서류기반 면접","a":""},{"q":"어떤 의사가 되고 싶나요?","a":"저는 암을 정복하는 의사가 되고 싶습니다. 암이라는 것은 불가피하고 많은 사람들에게 두렵게 인식되고 있습니다. 저는 서울대학교 병원 암연구소와 암병원에서 많은 의과학 연구를 선도하고, 이를 바탕으로 환자들을 치료하여 희망을 줄 수 있는 의사가 되고 싶습니다. 그래서 저는 꼭 세계 최고 대학 병원인 서울대학교 의학과에 입학하고 싶습니다."},{"q":"기하 과목에서 DNA 복제와 매듭이론은 어떤 관계가 있나요?","a":"매듭이론은 위상수학의 한 분야로 다른 모양이라고 같은 개수의 줄로 같은 개수의 구멍을 만들면 같은 차원이라고 봅니다. 그래서 효과적으로 모양을 만드는 데 도움을 줍니다. 이런 점에서 DNA 복제에 사용됩니다. DNA는 원에 꼬여있는 상태이지만 복제 시에 풀리면서 두 개로 잘립니다. 이때 관련 효소가 DNA를 절제하고, 복제 후에 다시 붙이는데 이 과정에 있어 가장 효율적으로 자르고 붙이는데 매듭이론이 사용됩니다."},{"q":"3학년 동아리에서 효소 활성 실험을 설계한 동기, 실험에서 맡은 것을 말해보세요.","a":"네. 저는 2학년 때 감자와 돼지 간으로 효소 활성 정도를 측정한 점이 있습니다. 그런데 이때 아쉬운 점이 있어서 3학년 때 좀 더 업그레이드해서 실험을 하게 되었습니다. 2학년 때는 온도, PH만 조작 변인으로 했지만 3학년 때는 온도, PH, 기질의 농도, 경쟁적 억제를 조작 변인으로 해 다양한 환경에서의 효소 활성 정도를 측정했습니다. 그리고 이전에는 감자와 돼지 간을 정략적으로 측정하지 못해 실험이 부정확했던 것 같아 3학년에는 효소 용액을 사용해서 졍량화하였습니다. 이 실험에서 저는 조장을 맡아 온도, PH, 기질의 농도, 경쟁적 억제 이렇게 4가지를 담당할 각 조를 구성하고 각 조에서 나온 결과를 바탕으로 어떤 환경에서 효소가 잘 활성되는지를 취합했습니다."},{"q":"안락사가 나중에 어떻게 될거라 생각하나요?","a":"저는 안락사가 조금 더 체계를 갖추고 환자의 자율성을 존중하는 의료 시스템을 만들거라 생각합니다. 안락사를 시행하기 위해 사전에 환자와 가족의 동의서를 받는 것처럼 사전에 조사한 내용을 문서로 작성해 남겨놓는다면 이후에 환자가 안락사를 희망할 때 최대한 도와줌으로써 광의의 웰다잉을 실천할 수 있다고 생각합니다."},{"q":"hif-1a가 암 억제에 어떻게 쓰일수 있고, 어떤 병이 효과가 있나요?","a":"hif-1a는 저산소증 유도인자로 암세포가 해당과정에서 항진하게 합니다. 암세포는 해당과정에서 에너지를 빠르게 얻고 성장에 필요한 물질들을 합성하기에 해당과정에서 항진함으로써 빠르게 성장합니다. 그래서 hif-1a를 억제함으로써 암세포의 성장을 억제할 수 있습니다. 이를 이용해 치료할 수 있는 암의 종류는 명확히 모르겠지만, 해당과정을 통해 성장하는 암의 경우에 효과가 있다고 생각합니다."},{"q":"빅데이터 분석에서 알아본 10년간 암 유병자 수의 특징은 무엇이 있나요?","a":"여성의 경우에는 유방암에 걸린 수가 굉장히 많았습니다. 그래서 관심이 생겨 더 알아보니 우리나라에서 5명 중 1명은 유방암에 걸린다는 사실을 알게 되어 굉장히 놀랐습니다. 남성의 경우에는 제가 잘 몰랐던 전립선암에도 꽤 많이 걸린다는 것을 알 수 있었습니다. 이렇게 여성, 남성 모두 암 유병자 수가 꾸준히 늘어났고 다양한 암이 있음을 알게 되었습니다."},{"q":"빅데이터에서 분석한 유병 지수가 증가 또는 감소하는 암에는 무엇이 있고 그 원인은 무엇이라 생각하는가?","a":"암 유병자 수가 증가 또는 감소하는 원인에는 우리 사회 변화의 영향이 큽니다. 현재 고령화 시대, 저출산 시대로 노인층은 많아지고 어린이는 적어지고 있습니다. 그래서 노인분들이 많이 걸리는 암은 유병자 수가 점점 늘어나고 어린이가 많이 걸리는 암은 유병자 수가 점점 줄어듦을 알 수 있었습니다."},{"q":"3년 내내 좋은 학업 성취를 얻을 수 있었던 비결은?","a":"저는 제가 모르는 문제를 친구들에게 알려주면서 좋은 학업 성취를 얻을 수 있었던 것 같습니다. 친구에게 설명하면서 친구도 잘 이해하고, 저도 생각해 보지 않았던 부분을 생각해 보는 계기가 되어서 친구와 저 모두에게 도움이 됐다고 생각합니다."},{"q":"자신의 노력뿐 아니라 재능, 주변 환경의 영향은 없었나요?","a":"물론 제가 오랫동안 앉아 꾸준히 공부하는 것에 재능이 어느 정도 영향을 끼쳤을 것이라 생각합니다. 그러나 재능보다도 저의 노력, 그리고 주변 환경의 도움이 컸다고 생각합니다. 부모님의 저에 대한 믿음을 바탕으로 한 지지, 그리고 친구들과 선생님들의 정서적인 지지 덕분에 제가 힘들 때에도 다시 일어섰고 끝까지 할 수 있었습니다. 후배들을 위한 조언 서울대 의예과는 예상과 전혀 다를 수 있기 때문에 모른다고 해서 당황하지 않고 자기 생각을 차분하게 말하는 것이 중요함. 어려운 문제는 모두에게 어렵다고 생각하고 마인드 컨트롤하는 것이 중요함.2024 대입 면접후기"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"서울대학교","dept":"의예과","jeonhyeong":"학생부종합(기회균형(사회통합))","method":"제시문 면접 4회(각 10분) + 서류면접(20분)서류면접: 개방형 질문 -> 생기부 질문","notes":"mmi 방식으로, 다소 빠르고 급하게 진행됨.블라인드 면접 개인정보 발언 금지.","qa":[{"q":"대학교 진학 후 공부 외에 하고 싶은 것이 있나요?","a":"나이지리아 여행을 가보고 싶습니다. 국어 시간 국경 없는 의사회에 대한 책을 읽고 흥미가생겼습니다. 나이지리아 내전 당시 파견된 의사들의 기록을 읽고 가보고 싶다 생각했습니다."},{"q":"위험하지 않나요?","a":"그를 감수하고도 볼 가치가 있는 것이라 생각했습니다."},{"q":"의사가 되기 위해 노력한 활동이 있다면 무엇이 있을까요?","a":"2학년 시절 신경계 질환, 뇌전증을 가진 친구를 돕는 도우미 역할 수행이 가장 기억에남습니다. 당시 긴급 상황 시 응급처치, 시간 체크 등을 했습니다."},{"q":"동물 실험에 대한 찬반 논의가 있는데 본인의 견해는 무엇인가요?","a":"저는 반대하는 입장입니다. 동물 역시 인간 못지않은 권리가 있으며 생명의 경중은 따질수가 없다고 생각하고 있습니다."},{"q":"그럼 대안이 있는가?","a":"오가노이드에 대한 기사를 읽은 기억이 있습니다. 오가노이드를 활용하면 동물 실험의대체가 가능할 것이라는 이야기가 있어 이것이 대안이라 생각합니다."},{"q":"오가노이드가 무엇인가?","a":"오가노이드란 인간으로부터 추출한 줄기세포를 배양한 것으로 실제 장기와 유사한 역할을한다고 알고 있습니다."},{"q":"장단점이 무엇인가?","a":"장점은 인체로부터 직접 추출한 것이기 때문에 거부반응이 거의 없다는 것이고, 단점은추출 시 엉덩이 뼈, 골수로부터 추출하기 때문에 상당한 고통을 유발한다는 점, 배양 조건,원하는 세포로 분화시키기 위한 조건을 맞추는 것이 까다롭다는 것입니다."},{"q":"본인은 동물을 먹는 육식은 반대합니까?","a":"인간의 생활을 위해 어쩔 수 없이 육식은 필요하다고 생각하고 있습니다. 다만 육식 자체는문제가 아니지만 그 동물을 기를 때의 공장식 축산이 가장 문제라 생각합니다."},{"q":"영어 시간 지역 공설시장 문제 탐구를 했다고 하는데 문제가 무엇이었는가?","a":"지역 공설시장의 경우 대형마트에 비해 값싸게 농작물을 매매 가능하다는 점이 장점이었습니다.그러나 수요가 적어 공급이 감소하였고, 그에 따라 주 이용층인 노년층도 시장을 이용불가하게된다라는 결론 내렸습니다."},{"q":"1학년 당시 유전자 편집 기술을 반대하는 논설문을 썼다하고 3학년은 모기 박멸과 같은과학적 활용에 관심이 많다고 하는데 견해가 상충되는 것으로 보이는데. 생각이 바뀐 것인가?","a":"1학년 당시 인간에 대해 적용하는 것에 대해서는 반대를 했습니다. 그 이유는 사회적지위에 따른 차별, 인간의 유전자를 조작하는 것의 윤리적 문제였습니다. 반면 3학년시절 모기 박멸과 같은 유전자가위의 활용에 대해서는 놀라운 과학적 성과임을 인정한것입니다."},{"q":"그럼 모기 박멸은 찬성하는가?","a":"아닙니다. 모기 박멸 시에 생태 피라미드에서 모기와 얽혀있는 먹이 그물이 깨져 생태계평형에 문제가 생기므로 도입하기 위해선 많은 논의가 필요하며 신중히 접근할 문제라생각합니다."},{"q":"통합과학 시간 적혈구의 고장액, 등장액에서의 기능에 대한 탐구를 한 것으로 보인다.이는 본인이 직접 탐구를 한 것인가?","a":"적혈구의 고장액, 등장액에서의 변화는 수업을 통해 배운 것입니다. 하지만 그 이후 기능의복구에 대한 부분은 스스로 의문을 품고 진행한 탐구였습니다."},{"q":"기·가시간 노화로 인한 신체, 정신적 변화에 관심이 있다고 하는데 그 변화가 무엇인가?","a":"신체적 변화로는 세월이 지나 신체가 당연히 많이 쓰인 만큼 기능적 하락이 발생합니다.또한 기본적으로 노화는 산화반응으로 활성산소로 인해 신체적 변화가 발생합니다. 정신적으로도 인생을 살며 쌓인 경험들로 기존과는 다른 정신을 갖게 되어 사고의 틀이 바뀌게 됩니다."},{"q":"심리학 과목에서 공감의 구체적 방법에 대한 탐구가 있는데, 이에 대해 설명해 주세요.","a":"공감을 위해서는 상담자의 상황, 맥락을 파악하는 것이 중요하다고 생각했습니다. 그렇기에 최대한 대화를 통해 그 소재를 직접적으로 다루는 것이 아닌, 간접적인 대화로 그 상황을 유추하는 것이 중요하다고 생각합니다."},{"q":"안락사에 대한 논설문 비교가 있는데, 본인은 안락사에 찬성합니까?","a":"그 활동에서 안락사엔 적극적 안락사와 소극적 안락사가 있음을 알게 되었습니다. 적극적 안락사의 경우 직접 약물 주입이 악용되어 범죄가 되거나 환자의 의지가 아닌 죽음이 될 수 있어 반대하지만, 소극적 안락사. 즉 존엄사의 경우엔 어느 정도 필요성을 동감합니다."},{"q":"CAR-T를 탐구했는데, 원리를 설명해라.","a":"T세포는 세포의 면역관문 단백질과 결합하면 그 세포를 공격하지 않는데, 암세포는 면역관문 단백질 생성으로 T세포의 공격을 회피합니다. CAR-T는 T세포에 인위적으로 결합할 수 있는 수용기를 달아 암세포와 결합할 수 있도록 하여 T세포가 암세포를 공격할 수 있도록 하는 역할을 합니다."},{"q":"중국의 의료보험 제도를 탐구했는데, 중국 의료보험 제도의 특징과 장단점이 무엇인가?","a":"특징은 우리나라는 일괄적, 필수적 가입이나, 중국은 선택적 가입이라는 점이 가장 큰 특징이라고 생각합니다. 또한 장점은 경제적 여건에 따라 필요한 보험 가입이 가능하다는 점이라고 할 수 있습니다. 다만 단점은 중국의 경우 대부분의 의료시설이 민영화가 되어 있고, 지방이 넓어 관할별로 보험료가 상이합니다. 따라서 도시인은 민영화로 보험 혜택이 적고, 지방은 수입이 낮아 보험 혜택이 적다는 점이 단점이라 할 수 있습니다."},{"q":"인체와 박테리아의 관계, 붉은여왕가설에 대해 탐구했는데 이를 설명해 주실 수 있나요?","a":"붉은여왕가설은 초기 인간과 박테리아는 경쟁적 관계였으나 서로를 지배하기 위해 경쟁적으로 진화를 해왔다는 가설입니다. 이에 따른 결과로 현재는 인간과 박테리아가 상리공생 관계를 띠고 있다고 결론지었습니다."},{"q":"동아리 시간에 세균배양실험을 했는데, 왜 했고, 그 결과는 무엇인가요?","a":"제가 미생물에 호기심을 가지기 시작한 것은 앞선 박테리아와 인간의 관계를 보면서였습니다. 인체 내부가 아닌 외부에도 수많은 미생물이 있을 것이라 생각했고, 그래서 한천으로 배지를 만들어 손가락을 찍어 배양하고 현미경으로 배지를 관찰했습니다. 이후 현미경으로 본 모습과 미생물백과를 대조하여 진균의 일종이라 결론 내렸습니다."},{"q":"그렇게 생각한 이유가 있나요?","a":"외형적으로 솜털의 형태를 띠고 있었고, 생명과학 선생님께 문의를 드려 효모균의 일종이란 결론을 내렸습니다."},{"q":"미적분 시간 감염병 예측 역학 모델에 대해서 감염병 역학모델에서 매개변수 미분법이 어떻게 사용되는지 탐구했다는데, 어떻게 사용되는 겁니까?","a":"감염병 예측 역학 모델에서는 집단을 감염자 집단, 비감염자 집단, 회복 집단으로 나누는데 이 집단에서의 변화율과 시간을 나타내는 변수t 와의 상관관계를 통해 나타내어진다고 탐구한 기억이 있습니다."},{"q":"봉사의 정의가 무엇이라고 생각하세요?","a":"상대에게 아무 대가를 바라지 않고, 자발적인 의지로 도움을 주는 것이라 생각합니다."},{"q":"본인이 학교 생활에서 그에 부합하는 행동을 한 게 있을까요?","a":"저는 학교에 가장 먼저 나오는 사람 중 한 명이었습니다. 그렇기에 아침에 창문을 열어 환기를 하고, 교실 내 큰 쓰레기들을 주워 담은 일이 그에 부합하는 경험이었다고 생각하고 있습니다."},{"q":"의견이 충돌하는 상대와 어떻게 대화해야 한다고 생각하십니까?","a":"최대한 객관적인 정보를 토대로 대화를 하는 것이 중요하다 생각합니다. 감정적인 말은 주관성이 개입해 충돌이 있을 것이라 생각합니다."},{"q":"그런 충돌한 경험이 있나요?","a":"동아리 실험 주제를 정할 때 의견이 맞지 않은 적이 있습니다."},{"q":"어떻게 해결했습니까?","a":"최대한 객관적인 정보만 이용해 대화를 하여 타협하려고 노력했습니다.(퇴장)후배들을 위한 조언 생기부에 적힌 내용들 하나하나를 진짜로 했는지 확인하려고 하는 느낌이 강하다. 의외로 압박은 거의 없었다. 전공지식적으로 해박한 것보다는 생기부 활동을 꼼꼼히 확인하고, 각 활동의 유기성을 잘 찾아보는 것이 좋을 것이라 생각했다.2024 대입 면접후기"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"서울대학교","dept":"의예과","jeonhyeong":"학생부종합(지역균형)","method":"5개의 방 중 4개의 방에서 제시문 면접(10분씩)5개의 방 중 1개의 방에서 생기부 면접(20분)수험표, 신분증 챙기기","notes":"대기실에 가면 모든 소지품을 빼앗기기 때문에 볼 자료를 굳이 들고가지 않아도 됨.","qa":[{"q":"1학년 때 의사가 되고 싶어서 ‘의대를 꿈꾸는 대한민국의 천재들’이라는 책을 읽고 해부학과 뼈의 구조에 대해서 조사하였다고 했는데 구체적으로 어떤 내용을 조사했나요?","a":"특히 뼈의 구조에 대해서 조사하였습니다. 그 중에서 두개골이 가장 인상깊은 내용이었습니다.이활동을 통해서 두개골이 하나의 뼈가 아니라 여러 개의 뼈가 합쳐져 하나의 두개골을 이룬다는 것을 알 수 있었습니다."},{"q":"조사를 하면서 참고했던 자료가 있나요?","a":"인터넷 조사를 할 때에는 주로 지식백과를 참고하였고 학교 도서관에서 ‘뼈’라는 책을 빌려서 그책을 참고하여 조사했습니다."},{"q":"정보에서 바이오 생명 AI 전문가라는 것을 상상하였다고 했는데 구체적으로 어떤 내용이었나요?","a":"바이오 생명 AI 전문가는 전세계적으로 방대한 의학 논문을 AI에게 학습시켜 이후에 의사가 논문을 찾아보고 싶을 때 빠르게 의사에게 제시할 수 있도록 하는 AI를 관리하는 직업입니다. 의사는 바쁘기 때문에 수많은 논문을 찾아보고 그 내용을 흡수하기는 어렵습니다. 그래서 바이오생명 AI 전문가가 인공지능에게 그 논문을 학습시키고 의사는 효율적으로 공부할 수 있도록 하기 위해서 이 직업을 상상하게 되었습니다."},{"q":"정보에서 주간 자가진단 프로그램을 설계하였다고 하는데 어떤 변수를 사용하였고 어떤 결과를도출시키나요?","a":"저는 이 프로그램을 설계할 때 이름, 키, 몸무게, 공복 혈당, 혈압을 사용하였고 이를 활용하여비만도를 산출하고 그 비만도와 공복혈당, 혈압을 활용하여 당뇨병 의심 여부를 판단하고 결과로는 비만 여부와, 당뇨병 의심 여부, 병원 내원 필요성 등을 산출합니다."},{"q":"과학 교양 시간에 마른 멸치 해부 실험을 한 후 동물실험에 대해서 반대하였다고 했는데 동물 실험 대신 할 수 있는 방안에 대해서 설명해주세요.","a":"저는 동물실험의 실효성이 없다는 것을 근거로 동물실험에 대해 반대하였습니다. 그래서 그 방안으로는 3가지 정도 있습니다. 첫 번째는 컴퓨터 시뮬레이션입니다. 현재는 아직 온전한 컴퓨터 시뮬레이션은 없지만 추후 개발이 된다면 안정성을 검사할 수 있는 신뢰성있는 컴퓨터 시뮬레이션을 통해서 실험을 진행할 수 있을 것입니다. 두 번째로는 줄기세포입니다. 줄기세포는 다양한 조직으로 분화할 수 있는 세포입니다. 줄기세포를 통해서 원하는 조직을 만들고 이를 통해서 실험을 진행한다면 안정성과 효과 등을 실험해볼 수 있을 것입니다. 세 번째는 3D 프린팅입니다. 최근에는 3D 프린팅을 활용하여 인공관절을 제작하는 등 3D 프린팅 기술이 급속도로 발전하고 있습니다. 3D 프린팅 기술을 활용하여 인공장기 등을 만든다면 이를 통해 실험을 진행할 수 있을 것입니다."},{"q":"구체적으로 동물실험을 대신하여 활용되고 있는 컴퓨터 시뮬레이션 기술이 있나요?","a":"현재는 동물실험을 대체할 신뢰성 있는 컴퓨터 시뮬레이션 기술은 없지만 현재 많은 기업에서 개발하고 있기 때문에 개발이 되면 그 기술을 활용하여 동물실험을 대신할 수 있다고 생각합니다."},{"q":"만약 지원자가 말한 방안을 모두 사용할 수 없는 상황에서 동물 실험이 불가피하다면 지원자는 어떻게 하시겠습니까?","a":"그 상황에서는 동물실험이 불가피하기 때문에 약물 등을 개발하기 위해서 불가피하게 동물실험을 할 수 밖에 없을 것입니다. 이 점이 저의 주장에 대한 한계라고 생각합니다."},{"q":"마른 멸치로 실험을 했다고 했었는데 이는 동물실험이 아닌가요? 마른 멸치를 통해서 많은 학교에서 실험을 진행한다면 이는 곧 동물실험을 진행하는 격이 되는 것이 아닌가요?","a":"마른 멸치는 원래는 식용의 목적으로 나온 것입니다. 그렇기때문에 많은 학교에서 동물 실험을 진행한다고 해서 멸치가 실험의 목적으로 많이 희생되는 일은 없을 것이라고 생각합니다.후배들을 위한 조언 첫 번째 생기부 면접은 면접관마다 상황이 다르기 때문에 모든 상황에 대한 준비를 해야 합니다. 자기소개와 지원 동기에 대해서 꼼꼼히 준비하고 대학 이후의 계획까지 준비하면 더욱 좋습니다. 그리고 전공 관련 과목이더라도 물어볼 수 있기 때문에 생기부의 모든 것에 대해서 준비하여야 합니다. 구체적으로는 활동에 대한 동기, 내용, 자신의 생각, 성장한 점을 모두 정리하여 준비하는 것이 좋습니다. 면접장에서는 면접관분들이 긴장되지 않는 분위기를 유도해주시기 때문에 걱정하지 말고 면접에 임해주시면 더 좋은 결과가 있을 것이라고 생각합니다.2024 대입 면접후기"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"서울대학교","dept":"의예과","jeonhyeong":"학생부종합(일반복도에서 제시문 2분 숙지 → 1번 방 입장 → 질문 및 답변 →)","method":"복도에서 제시문 2분 숙지 → 2번 방 입장 → 질문 및 답변 →복도에서 제시문 2분 숙지 → 3번 방 입장 → 질문 및 답변 →복도에서 제시문 2분 숙지 → 4번 방 입장 → 질문 및 답변 →복도에서 대기 → 5번 방 입장 → 생기부 질문 및 답변 → 완료제시문 2분 숙지, 8분 면접 4번 반복, 생기부 20분 면접","notes":"생기부를 물어보는 방을 첫 번째에 들어가는 사람도 있고, 2번째에 들어가는사람도 있고, 마지막에 오는 사람도 있음,","qa":[{"q":"(제시문1) 인물 2명 중 왕은 어떤 인물을 따라야 하냐고 생각하냐,(추가 제시문 준 후) 이렇게 겪은 경험을 이야기하고 어떻게 행동했냐, B그룹일 때 이끌어 갈 리더십의 덕목은 무엇이냐","a":""},{"q":"(제시문2) 제시문 요약해봐라, 평등이란 무엇이냐, 공평과 공정의 차이를 말해봐라,(추가 제시문 후) 왜 이 제시문을 읽으라고 준 것 같냐, 제시문 2개의 차이점 말해봐라","a":""},{"q":"(제시문3) 예술이란 무엇이냐, 예술을 하기 위해서 동식물을 희생하는 것이 정당한가,두 작가 중 무엇이 잘못되어 있다고 생각하냐.(추가 제시문 준 후) 동물 보호법에 대해 설명해봐라, 이 제시문을 읽고 생각이 바뀌었냐","a":""},{"q":"(제시문4) 병을 예측할 수 있는 기계가 있다면 어떤 기준으로 사용해야 하냐, 너가 실제로 권위자라 생각하고 연설을 해봐라","a":""},{"q":"(생활기록부 질문) 지원동기, 비대면 의료와 비대면 수업을 얘기해봐라, 동아리 활동,수학 세특, 사제 동행, 독서 세특후배들을 위한 조언 교수님이 편안하게 해주시니 긴장 말고 자신감 있게 얘기하세요.2024 대입 면접후기","a":""}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"서울대학교","dept":"약학계열","jeonhyeong":"학생부종합(지역균형)","method":"감독관의 호명→대기실에서 나와 고사실 옆에서 대기→고사실 입장→서류 기반 질문(3~4개)→퇴실","notes":"자기소개와 지원동기 등을 물어보지 않았음. 면접번호를 대기실에서 알려줌.면접 후에 대기실에서 기다리지 않고 바로 퇴실","qa":[{"q":"TLC 약물 분석 실험에서 본인이 무엇을 얻고 학습에 어떤 도움이 되었는지 말해주세요.","a":"TLC 약물 분석 실험을 하게 된 동기, TLC 약물 분석 실험의 원리 및 과정 등에 대해서 말함. 분자의 크기에 관한 언급에서 분자의 크기를 어떻게 아냐는 질문에 물질의 화학식을 알고 있기 때문이라고 답함."},{"q":"탈리도마이드 약물을 사례로 동물실험에 반대했다고 했는데 어떤 논리적 과정으로 반대했는지 알려주세요.","a":"동물실험 반대의 근거를 먼저 제시하고 탈리도마이드 약물의 특성을 제시함."},{"q":"항생제 내성 실험을 진행했는데 자세한 과정을 알려주세요.","a":"항생제 내성 실험의 과정과 원리, 결과를 제시함."},{"q":"3학년 동아리 시간에 토론을 진행했는데 갈등이 첨예하게 대립되었던 적이 있나요? 있다면 회장으로써 어떻게 해결했는지 알려주세요.","a":"갈등이 첨예하게 대립되었던 적은 없고, 여러 사람의 의견이 맞지 않아 갈등을 겪었다고함. 이후 해결 방안으로 의견을 수렴하기 위해 모두의 의견을 받아들이려는 유한 태도보다는 다소 강압적인 태도가 도움이 될 수 있다는 점을 제시함.후배들을 위한 조언 자기소개와 지원동기 등을 준비하는 것도 물론 전체적인 면에서는 도움이 되지만 오히려 너무 이쪽에 집중하면 서류 내용에 힘쓰지 못하는 것 같아요. 학생의 진로나 학업 역량 확인 질문도 중요하지만 어디까지나 서류 확인 면접이기 때문에 생활기록부 내에서 본인이 한 활동에 대해 과정과 결과, 보완할 점, 느낀 점까지 모두 정리해보는 게 도움이 될 것 같아요.2024 대입 면접후기"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"서울대학교","dept":"수의예과","jeonhyeong":"학생부종합(일반)","method":"생명과학 제시문 -> 인성 관련 상황 제시문 -> 생명과학+수의학 제시문-> 사회+수의학 제시문-> 서류(생기부)Ÿ 아날로그 시계, 디지털 시계, 전자 기기 소지 금지/ 물, 다과 제공Ÿ 가방, 외투 제출 (면접 전 대기실에는 맨몸으로)","notes":"Ÿ 면접 전 대기실에서 자료 등 공부 불가능Ÿ 5인 1조의 로테이션 형식의 MMI (10분씩 5개의 면접, 면접 사이 시간간격이 굉장히 짧음)","qa":[{"q":"현재 수의학의 역할","a":"동물 치료, 공중 보건, 식품 위생, 검역, 인수공통감염병 등 서울대학교 수의과대학 홈페이지설명과 유사하게 답변."},{"q":"수의예과를 선택하게 된 계기","a":"인수공통감염병인 코로나 상황과 생기부에 있는 인수공통감염병 관련 탐구 등에 흥미를느끼고 인간과 동물을 비롯한 생명체의 삶의 질 향상에 기여하고 싶었기 때문."},{"q":"(행특 내용을 언급하면서) 선생님께서 이렇게 평가하신 이유가 뭐라고 생각하는지","a":"다른 학생들의 경우 실험은 키트를 사서 진행하는 경우가 많은데, 가설을 세우고 반복하여 실험하고 스스로 결과를 분석하는 등 실험 전반을 직접 설계하고 조작 변인을 다양하게 설정하는 등 도전적인 연구를 시도함."},{"q":"봉사 시간이 굉장히 많은데, 왜 이렇게 많은 봉사활동을 했는지?","a":"학교라는 공간에서는 공부뿐 아니라 봉사 등을 통해 더 많은 것을 배울 수 있었기 때문.멘토링과 분리수거 등과 같은 봉사활동을 통해 시야를 넓히고 다양한 경험을 해 볼 수 있었음.후배들을 위한 조언 기출을 분석하면서 동물 복제, 동물 실험, 육식과 채식, 동물권 등을 비롯한 여러 이슈들에 대해서자신만의 가치관을 확립하는 것이 중요한 것 같다. 다양한 상황 제시문을 접해 보고 내가 이상황이라면 어떤 선택을 할지, 그 이유는 무엇인지 말로 표현해 보는 연습에 집중하면 도움이될 것이다. 수의대를 비롯한 메디컬 계열 MMI는 면접 시간이 길기 때문에 긴 시간 동안 집중해서 문제를 풀고 답변하는 연습이 필요한 것 같다. 면접 연습을 할 때는 영상을 찍어 두고목소리의 크기가 적절한지, 빠르기가 빠르지는 않은지, 특정 단어를 반복하지는 않은지, 아이컨택은 적절한지 등을 체크하는 것도 좋다.2024 대입 면접후기"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"서울대학교","dept":"수의예과","jeonhyeong":"학생부종합(지역균형)","method":"간단한 시작 질문 -> 생활기록부 속 전공 관련 활동 질문(2가지/세부꼬리 질문) -> 리더십 경험 질문 -> 개인적 경험 질문 -> 마지막 할 말1. 탐구활동을 할 때 여러 자료를 찾아봤다면 출처를 명확히 해두세요.정확한 출처를 원하시는 것 같았습니다.","notes":"2. 너무 긴장하지 않으셔도 될 것 같습니다. 대부분의 면접 보러 온친구들이 많이 긴장한 표정이었는데, 편안한 마음으로 본다면 더좋은 인상을 줄 수 있을 것이라 생각합니다.","qa":[{"q":"좀 오래 기다리셨네요. 언제 왔나요?","a":"어제 미리 왔습니다. (‘그럼 좀 여유가 있었겠네요’라고 맞장구쳐주심.)"},{"q":"2학년 자율 활동에서 고양이 식단 제작 프로젝트를 진행했는데 과정을 설명해 주시고,참고한 자료가 있다면 어떤 것을 참고했는지 출처를 함께 말해주세요. (출처를 강조하는느낌이었음.)","a":"고양이를 키우면서 고양이가 식이 알레르기를 겪고 있다는 사실을 알게 된 후 사료와영양성분에 관심이 생겼습니다. 그래서 영양학 관련 도서나 정보들을 찾아보면서 영양학에관심을 가지게 되었고 논란이 되는 성분들과 성분 하나하나가 끼치는 영향에 대해 알게되면서 자연식에 관심을 두고 관련 프로젝트를 진행했습니다. 우선 고양이 필수 영양소와질병에 따른 영양 관리법 등을 알고자 원서 ‘Feline Nutrition’과 여러 논문을 참고하였고,이로부터 알게 된 지식들을 바탕으로 먼저 주식 레시피를 짰습니다. 영양소 과부족과레시피 조정을 쉽게 할 수 있는 엑셀 폼을 사용했고 이후에 이것을 급여해보기엔 한계가있다고 판단하여 간식 레시피로 수정 후 급여하고 급여일지를 작성했습니다."},{"q":"요새는 책들이 온라인에서도 많이 볼 수 있고 그냥 종이책도 있을 텐데 ‘FelineNutrition’은 어떤 걸로 읽었나요?","a":"종이책으로 구매해 읽었습니다."},{"q":"한국에서 접근성이 좋은 책인가요? 쉽게 구할 수 있는 건지?","a":"쉽게 구할 수 있는지는 잘 모르겠지만 고양이 영양학을 다루고 있는 책이기도 했고 좀 더 전문적인 지식을 구체적으로 얻을 수 있을 것 같아 찾아보던 중 알게 되어 구매해 읽었던 것 같습니다."},{"q":"고양이 관련된 게 많은데 개는 관심 없나요? (생활기록부 내용 대부분이 고양이 이야기인데 교수님 분야가 개여서 물어보신 것 같음.)","a":"아닙니다. 고양이를 키우고 있기도 하고 아무래도 그러다 보니 접근성(?) 때문에 고등학교 동안에는 고양이를 위주로 탐구했지만, 대학교, 대학원에 와서는 다양한 동물을 접해보고 싶습니다."},{"q":"고양이 복막염 바이러스에 대해 탐구했는데 왜 탐구한 건가요? 동기를 말해주세요.","a":"주변 지인의 고양이가 복막염으로 인해 사망한 일이 있어서 관심을 가지게 되어 알아보던 중 명확한 치료제가 없다는 것을 알게 되었습니다. 또한 고양이 전염성 복막염이 코로나바이러스로 인해 발생하는 것을 알게 되어 좀 더 알아보기 위해 탐구했습니다. (아마 후자의 답변을 원하신 것 같음. 처음 주변 지인 이야기 꺼냈을 때 표정이 좋진 않으셨음.)"},{"q":"그렇다면 사람, 개, 고양이의 코로나바이러스가 다 같나요? (아마 제대로 알고 한 건지 확인차 물어보신 것 같음.)","a":"아닙니다. 코로나바이러스도 종류가 여러 가지인 것으로 알고 있습니다. 고양이의 경우, 고양이 장 코로나바이러스에 걸리고 변이가 생겨 고양이 복막염 바이러스에 감염되는 것으로 알고 있습니다. (답변을 듣고 끄덕끄덕하시면서 만족하신 표정이었음.)"},{"q":"고등학교 동안에 리더십을 발휘한 특별한 경험이 있나요?","a":"특별한지는 모르겠지만 2학년 때 동물보호동아리에서 동아리 부장으로 활동한 경험이 있습니다. 차장과 함께 이끌어 나가는 동아리였는데, 처음에 의견 충돌과 역할 분담에서 갈등이 있었습니다. 이때 동아리 부원들의 의견도 수합하여 활동을 그에 맞게 구성하고 진행하여 동아리 운영을 성공적으로 이끌어 나갈 수 있었습니다. (솔직히 답변하면서 조금은 아쉬웠음. 행동 능력 및 특기사항에서 선생님께서 적어주신 부분을 보고 우려되는 점을 확인차 물어보셨다고 교수님께서 말씀하심.)"},{"q":"고양이를 키웠다고 했는데 고양이랑 있었던 특별한 경험이 있나요?","a":"(처음에 당황해서 살짝 멈춘 후 잠시만 기다려달라고 말씀드리고 답변 이어감.) 고양이를 위해 캣휠을 마련해줬던 적이 있습니다. 처음에는 잘 타지 않아 속상했었는데, 캣닢과 트릿 같은 것을 이용하여 익숙해질 수 있도록 한 결과 나중에는 결국 완전히 치타처럼 달리는 모습을 볼 수 있었습니다."},{"q":"시간이 거의 다 된 것 같은데 마지막으로 하고 싶은 말 있으면 해주세요.","a":"아직 국내에서는 수의영양학이 계속해서 발전해야 된다고 생각하기에 최종적으로 수의영양학자가 되어~~ (말하는 도중 문이 열렸고 교수님께서 이제 다 들은 것 같다며 나가도좋다고 하심.)후배들을 위한 조언 생각보다 분위기가 아주 좋았습니다. 어쩌면 인생에서 첫 면접일 수도 있는데, 너무 떨지 말고자신을 최대한 어필할 수 있는 시간으로 만드셨으면 좋겠습니다. 면접 중간에 ‘답변 잘했어요’라는 말과 함께 종종 웃어주셨습니다. 또한 정말 대화하는 것처럼 말하다 보니 중간에 교수님두 분 다 제 말에 웃기도 하셨습니다. 그리고 보통 면접보러 가는 시기가 수능 최저 충족도불확실한 경우가 많을 텐데 이미 끝난 결과이니 수능 최저 충족 여부를 신경 쓰기보다는 미리미리 면접 준비 열심히 하셨으면 좋겠습니다. 생활기록부를 쭉 읽어보고 기억이 나지 않는 부분은그때 작성했던 보고서를 참고하여 내용을 정확히 숙지하여 두시고 읽은 책도 꼼꼼히 정리해두시는 걸 추천합니다. 마지막으로 할 말을 얼버무리다가 만족스럽지 않게 하고 나왔는데 미리여러 번 시뮬레이션을 돌리고 모의 면접도 많이 참여하시면서 감각을 익히셨으면 좋겠습니다.PART가천대학교세명대학교중앙대학교2024 대입 면접후기"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"서울대학교","dept":"농경제사회학부","jeonhyeong":"학생부종합(지역균형오전 7:30 ~ 8:20까지 농생대 203동으로 입실수험표, 신분증 확인 후 면접 대기실로 이동)","method":"안내에 따라 한 명씩 면접실로 이동2명이 번갈아가며 질문함면접 시간은 10분, 끝나기 1분 전 밖에서 노크함면접관은 2명이고 면접관과의 거리는 그렇게 멀지 않음면접관 자리에는 칸막이가 설치되어 있고, 면접관 손을 가려놓음","notes":"수험표와 신분증 지참화장실은 면접 전 1명씩만 갈 수 있고, 조교가 대동함","qa":[{"q":"제가 생기부에서 흥미롭게 읽은 부분이 있는데, 필립스 곡선에 대한 탐구를 했네요? 이게 제가 지금 가르치는 건데, 미시경제Ⅱ에서. 필립스 곡선이 뭡니까?","a":"필립스 곡선은 인플레이션과 실업률 사이에 상반관계가 있다는 것을 나타내는 곡선을 말합니다."},{"q":"무슨 얘기인지 한 번 구체적으로 설명해보세요.","a":"네. 인플레이션율이 올라가면 실업률은 낮아지고, 반대로 실업률이 올라가면 인플레이션율이 낮아진다는 것을 의미합니다."},{"q":"...는 아는 것 같고. 상관관계, 그 인과관계, 상관관계하고 인과관계가 뭡니까? 둘이 뭐가 다른지 알아요?","a":"인과관계는 원인과 결과, 즉 두 사안이 원인과 결과로서 연관성이 강하다는 것을 의미하고, 상관관계는 두 사안 간의 연관성이 느슨한, 그런 걸 말하는 것으로 알고 있습니다."},{"q":"어, 인플레이션하고 실업률하고 둘이 상관관계입니까, 인과관계입니까?","a":"상관관계인 것으로 알고 있습니다."},{"q":"왜 상관관계인지 혹시 알아요?","a":"그 둘이 달라서 그런 것 같은데... 하나가 실물경제인가? (잘 대답 못함)"},{"q":"아무튼 둘이 상관관계라는 건 아는 거죠?","a":"네, 그렇습니다."},{"q":"혹시 학생은, 지금 경제 상황에 필립스 곡선이 잘 적용된다고 보세요?","a":"아뇨, 저는 지금 경제 상황에 필립스 곡선이 잘 적용된다고 생각하지 않습니다. 그 이유는, 제 생기부에 적혀 있는 바와 같이 화폐발행 증가로 인한 인플레이션, 코로나19 발생으로 인해 총수요가 감소했기 때문입니다. 그리고 필립스 곡선이 적용되지 않았던 때가 또 있었던 것으로 알고 있습니다. 1970년대 석유 파동이 일어났을 당시 인플레이션율과 실업률 모두 상승했던 적이 있는 것으로 알고 있습니다."},{"q":"그걸 스태그플레이션이라고 하죠. 어, 학생. 애그플레이션에 관해 어떤 탐구를 했죠?","a":"네, 저는 애그플레이션의 정의와 현재 상황, 그리고 해결방안에 대해 탐구했습니다."},{"q":"그걸 자세하게 설명해보세요.","a":"애그플레이션은 농산물의 가격이 오르면서 다른 물건의 가격도 덩달아 상승하는 것을 말합니다. 현재 러시아-우크라이나 전쟁으로 인하여 애그플레이션 위기에 놓여있다고 할 수 있습니다. 해결방안으로는 2022년 흑해 항로 협상과 같은 국제적 협력과 장기적으로 지구온난화 대처 방법을 수립하는 것이 있습니다."},{"q":"소득주도성장에 대해 탐구했었네요? 소득주도성장은 무엇이고, 학생은 소득주도성장을 어떻게 생각합니까?","a":"소득주도성장은 저소득층의 실질임금을 인상하여 그들의 구매력을 이용해 경제성장을 이룩한다는 정책을 말합니다. 저는 소득주도성장이 성공적이지 못했다고 생각합니다. 왜냐하면 최저임금 인상으로 인하여 자영업자들이 고용을 축소하게 돼 일자리가 감소했기 때문입니다."},{"q":"최근 들어 비판적인 보도가 나와서 그런 것은 아니고요?","a":"(웃으며) 아무래도 그런 영향을 좀 받은 것 같습니다."},{"q":"농경제사회학부에 지원하게 된 동기를 말해보세요.","a":"저는 1학년 때 문학탐구반에 가입하여 김유정 작가의 <봄봄>, <금따는 콩밭>, 그리고 <만무방>을 읽었습니다. 거기서, 당시 1930년대 일제강점기 시절 농촌의 비참한 현실을 마주하고 농촌 문제에 대한 관심을 가지게 되었습니다. 이후 2학년 때 <사회문제토론반>에 가입하여 요소수 대란의 해결방안에 대해 탐구하고, 한국지리 시간에 난지도 재개발유형을 분석하는 등 농업경제학에 대한 관심을 키워나갔습니다. 3학년 때에는 <경제학습공유> 동아리에 가입하여 애그플레이션에 관한 발표를 진행하였습니다. 이러한 활동들을 바탕으로 농업경제전문가가 되고 싶은 저의 꿈을 키워나갔고, 저는 서울대학교 농경제사회학부에 입학하여 그 꿈을 이루고 싶습니다."},{"q":"여기 독서활동 상황을 보면, 어차피 1, 2학년 때 읽은 거는 기억 못할테고, 3학년 때 ‘지금 애덤 스미스를 다시 읽는다’. 이거 읽었어요?","a":"네, 읽었습니다."},{"q":"‘지금 애덤 스미스를 다시 읽는다’에서 인상 깊었던 구절 1가지 정도 말해보세요.","a":"저는 애덤 스미스가 인간의 이기심을 딱히 긍정도, 부정도 하지 않고 단지 경제활동의 가장 강한 원동력이라고 주장한 것이 인상 깊었고, 애덤 스미스가 경제 성장의 목적은, 단순히 소수들만 잘 먹고 잘 살기 위해서가 아니라, 최소 수준의 부도 소유하지 못한 사람들의 수를 줄여나가는 데에 있다고 주장한 것이 인상 깊었습니다."},{"q":"학생 자소서에 보면, 동물농장하고 탐욕의 시대하고 2권을 적어서 냈는데, 그중 동물농장에 나오는 나폴레옹과 다국적 기업이 어느 면에서 비슷한지 설명해보시겠어요?","a":"동물농장의 동물들을 위하지 않지만, 권력 유지를 위해 그들을 위한다고 말하는 나폴레옹과, 실제로는 환경을 생각하지 않지만 패권을 유지하기 위해 환경을 생각한다고 말하는 다국적 기업이 서로 비슷하다고 생각합니다. 그리고, 나폴레옹의 말을 조금도 의심하지 않는 동물들과, 다국적 기업의 행태를 조금도 의심하지 않는 소비자들이 서로 비슷하다고 생각합니다.(이때 밖에서 문을 두드렸다.)"},{"q":"마지막으로 하고 싶은 말 있으면 하세요.","a":"아까 전에 제가, 필립스 곡선 관련해서 제대로 답변하지 못한 부분이 있는데, 서울대학교 농경제사회학부에서 학습하여 제 부족한 부분을 채워나가도록 하겠습니다. 저는 평소, 농업 관련 문제에 관심이 많고, 그 문제들을 해결하고자 하는 의지를 가지고 있습니다. 저는 서울대학교 농경제사회학부에 꼭, 진학해서 농업경제전문가가 되고 싶습니다.후배들을 위한 조언 면접을 끝내고 나오면 종교인들이 접근합니다. 무교이고, 주변에 교회 다니는 사람들이 없다고 말하는 것이 도움이 됩니다. 서울대 정문 쪽은 항상 막히고, 서울대 내부에는 순식간에 차들이 빼곡히 늘어섭니다. 따라서 아침 일찍 출발하는 편이 좋습니다.제가 면접을 볼 때는 코로나19로 인해 학부모 대기실이 설치되어 있지 않았습니다. 면접 당일에는 대부분의 건물 출입이 통제되므로, 학부모께서는 학생 구내식당에서 기다리시면 됩니다.2023 대입 면접후기"}],"result":"합격","resultNote":"","src":"충청북도교육청 「2024 수시 대비 면접 후기집」","year":"2024학년도"},{"univ":"서울대학교","dept":"","jeonhyeong":"학생부종합(지역균형면접 순번을 현장에서 부여받은 후 기다림의 시간을 가지고 대기했습)","method":"니다. 10분의 제한시간으로 면접이 진행되었으며 조그마한 방에서 타원형의 책상을 두고 2명의 교수님들과 면접을 진행하였습니다. 교수님들이 저의 생기부와 자소서를 보고서 그에 대한 질문을 답하는 형식으로 면접이 진행되었습니다.할 수 있다는 자신감이 필요합니다. 그리고 면접에서 자신이 준비한","notes":"것을 다 뽐내세요. 면접 날 매우 추우니까 따뜻하게 입고 가시고, 차가 막힐 수도 있으니 여유를 가지고 출발하세요.","qa":[{"q":"2학년 때 고급화학을 수강하셨는데, 가장 기억에 남는 내용 말해줄래요?","a":"저는 거울상 이성질체 관련 내용을 학습하면서 입체구조의 차이에 따라 다른 효능을 내는 카이랄 의약품이 기억에 남습니다. 이로 인해 임산부의 체내에서 다른 이성질체로 전환되어 수많은 기형아가 탄생한 ‘탈리도마이드 사건’이라는 비극적인 사례가 있습니다. 그래서 저는 이런 비극적인 사건이 다시는 벌어지지 말아야 한다고 생각했고 그래서 후속 활동으로 화학자들의 촉매 개발 연구 과정을 살펴보았습니다. 대표적으로 기초과학연구원(IBS) 분자활성촉매반응 연구단에서 거울상 이성질체 중 이로운 종류의 분자만을 선택할 수 있는 촉매, 즉 비대칭 유기 촉매를 개발하고 이를 활용해 의약품 필수재료인 카이랄 락탐을 만드는데도 성공했다는 연구 결과를 살펴보았습니다."},{"q":"‘비대칭 유기 촉매’ 에 대해 언급하셨는데, 촉매가 뭔지 아나요?","a":"(준비를 하지 못한 기본적인 질문이라 당황했음) 어... 어떤 화학 반응을 촉진시키거나 저해시키는 것으로 알고 있습니다."},{"q":"그러면 대표적으로 촉매로 사용되고 있는 예시 아나요?","a":"그거에 대해서는 더 알아봐야 할 것 같습니다."},{"q":"2학년 때 화학실험을 수강하셨는데, 수강하게 된 동기가 뭔가요?","a":"코로나로 인해 실험을 할 수 있는 기회가 적었습니다. 그래서 화학 실험에 참여하여 화학 실험에 참여하여 실험 방법, 다양한 기기들을 써보고 싶었습니다."},{"q":"가장 기억에 남는 실험이 있나요?","a":"‘커피 속 카페인 추출’ 실험이 가장 기억에 남습니다. 믹스커피에 들어있는 카페인을 추출하는 실험을 진행하였습니다. 염화메틸렌이라는 유기 용매를 이용하여 카페인을 추출했는데요, 유기 용매는 물과 섞이지 않기 때문에 카페인을 유기 용매 층으로 이동시켜 추출하는 것입니다. 또한 TLC를 이용하여 카페인의 추출을 눈으로 확인할 수 있었습니다."},{"q":"TLC의 원리를 알고 있나요?","a":"TLC는 얇은막 크로마토그래피로, 크로마토그래피의 일종입니다. TLC는 정지상과 이동상에 대한 친화성 차이를 이용하여 물질을 분리하는 크로마토그래피입니다. 이를 통해 카페인 표준액과 커피에서 추출한 카페인을 정성적 분석함으로써 카페인이 포함되어있다는 것을 알 수 있었습니다."},{"q":"2학년 때 과학과제연구를 하셨는데, 여기서 했던 실험에 대해 설명해줄래요?","a":"왜 약을 섭취할 때 전문가들이 물과 함께 섭취하라고 하는지 궁금증을 가지고 있었습니다. 그래서 직접 다양한 섭취 환경에서 약의 분해 속도를 비교하는 실험을 설계하여 진행하였습니다. 용액의 종류, 온도를 변인으로 설정하여 약과 용액을 항온수조에 넣고 일정시간 동안 육안으로 비교하여 녹은 정도를 파악했습니다. 에너지드링크, 물, 탄산수, 이온음료를 가지고 실험을 진행하였습니다. 저희는 물과 함께 체온에서 섭취하는 것이 가장 빠를 것이라고 예측하였으나 결과는 에너지드링크에서 약이 더 빠르게 용해되는 것을 확인할 수 있었습니다. 이를 통해 용해 속도가 빠르다고 좋은 것이 아닌, 작용하는 기관에 도달해 녹을 수 있는 적절한 용해 속도가 더 중요하다는 결과를 도출해낼 수 있었습니다."},{"q":"학생이 도출한 결론 외에 전문가들이 물과 함께 먹으라는 또 다른 이유가 있을까요?","a":"어... 예를 들어 자몽주스와 함께 약을 먹으면 심한 부작용이 일어난다고 알고 있습니다. 그렇기 때문에 적절한 용해 속도 이외에, 다른 용액과 함께 약을 섭취한다면 우리 몸에 심각한 부작용을 일으킬 수 있기 때문에 물과 함께 먹으라고 하는 것 같습니다."},{"q":"3학년 때, 물리학Ⅱ를 이수하셨는데, 이를 이수한 이유를 말해줄 수 있을까요?","a":"저희 학교는 2학년 때 물, 화, 생, 지 과학 과목 4개를 이수한 후 3학년 때 과학 과목 3개를 선택하는 것이었습니다. 저는 2학년 때의 경험과, 대학 생활에 있어서 물리학Ⅱ를 배움으로써 대학 교과과정을 이해하는데 도움이 될 수 있을 것이라고 생각하여 물리학Ⅱ를 이수하였습니다."},{"q":"기억에 남는 내용 있을까요?","a":"정전기 유도와 유전 분극 현상에 대해 배운 후, 이것이 실제로 일어나는지 눈으로 확인하고 싶었습니다. 그래서 교과서에 나와있는 실험 과정을 토대로 과학관에서 실험 도구들을 빌려 실험을 준비하였고, 이를 친구들 앞에서 진행하였습니다. 도체 구와 부도체 구를 이용하여 두 현상을 확인함으로써 실제로 이 현상들을 확인할 수 있었습니다."},{"q":"실험을 하면서 힘든 점은 없었나요?","a":"준비하는 데 있어서 습한 환경이나 오래된 실험 도구로 인해 두 현상이 잘 일어나지 않았습니다. 하지만 저는 이를 담당 선생님께 물어보고 반복해서 예비 실험을 진행함으로써 이러한 문제들을 해결할 수 있었고 실험 결과를 잘 보일 수 있었습니다."},{"q":"3학년 때 토론 동아리를 개설했는데, 그 이유가 뭔지 말해줄래요?","a":"1,2학년 때 실험 활동을 많이 하고 친구들과 특정 과학 이슈에 대해 많이 이야기해보지 못한 것이 아쉬웠습니다. 그래서 3학년 때 토론 동아리를 개설하여 친구들과 과학 이슈에 대해 이야기를 나눠보고 싶었습니다."},{"q":"‘인공화학물질’ 토론을 진행하셨다고 자소서에 적혀있는데, 이에 대해 설명해줄래요?","a":"많은 관심을 받고 있는 ‘인공화학물질’ 에 대해 찬반 토론을 진행하였는데요, 저는 반대 측에 서서 인공화학물질의 사용을 점차 줄여나가야 한다고 주장하며, 폴리염화비닐이 몸에 쌓여 죽었던 고래를 사례로 들었습니다."},{"q":"이 토론 이후에 ‘친환경 알지네이트-키토산 종이필름’을 만드는 후속 실험을 진행하셨죠? 이걸 하게 된 이유하고 실험 내용에 대해 설명해줄래요?","a":"그렇다면 저희는 토론을 통해 얻은 합의점을 토대로 인공화학물질의 사용을 줄일 수 있는, 즉 대표적인 인공화학물질인 비닐을 대체할 수 있는 친환경 물질을 만들어보고자 실험을 진행하였습니다. 알긴산 나트륨과 키토산을 이용하여 종이필름을 제작하고, 방수효과와 방염효과를 확인하여 비닐을 대체할 수 있는지 확인하는 실험이었습니다."},{"q":"무슨 종이를 사용했나요?","a":"한지나 재생지 같은 종이들을 이용했습니다."},{"q":"방수효과와 방염효과는 어떻게 확인했죠?","a":"저희가 과학축제에 있는 조의 자료를 참고하여 진행하다보니 거기 나와있는 대로 진행하였는데요, 방수효과는 물에 적셔서 모양이 살아있는지, 기능을 할 수 있는지 등을 육안으로 확인했고, 방염효과는 과학관에서 토치를 빌려 확인하였습니다. 다른 일반 종이와 다르게 토치를 대도 바로 타지 않는 것을 통해 방염효과를 확인할 수 있었습니다."},{"q":"단순히 발전만을 목표로 하는 연구에서 벗어나 바이오 소재를 활용한 친환경 물질에 관한 연구를 진행하고 싶다고 했는데, 이에 대해 설명해줄래요?","a":"이 학부에서 나노바이오소재, 생체고분자 등에 다양한 소재와 시스템에 관해 연구하고 있는 걸로 알고 있습니다. 그렇기 때문에 저는 이러한 내용들을 이 학부에서 배우고 습득하여 환경 문제, 인류 건강 문제 등을 해결하는 데 공헌하는 인재로 거듭나고 싶습니다.후배들을 위한 조언 면접 준비는 자신의 생기부를 철저히, 완전 꼼꼼히 하나하나 다 분석하고 그에 대한 예상 질문을 하나하나 다 만들고 대답을 할 수 있다면 면접은 걱정없다고 장담합니다. 웬만하면 거의 예상한 질문에서 나오기 때문입니다. 그리고 자신이 중요하다고 생각하는 질문은 무조건 거의 암기하듯이 알아두세요. 그게 나올 확률이 매우 높습니다. 면접은 자신감입니다. 자신이 여태까지 해왔던 것을 뽐내는 자리이며 절대 자신을 떨어트리기 위해 만들어진 자리가 아닙니다. 그렇기 때문에 면접 자리에서 자신감을 가지고 자신이 준비한 답을 면접관님들께 말하며 후회없이 나오세요. 그것이 면접의 의미이며 저희를 부른 이유가 될 것입니다. 화이팅하세요!2023 대입 면접후기"}],"result":"합격","resultNote":"학부명","src":"충청북도교육청 「2024 수시 대비 면접 후기집」","year":"2024학년도"},{"univ":"서울대학교","dept":"사회학과","jeonhyeong":"학생부종합(지역균형)","method":"들어가서 앉자마자 질문 바로 시작하셨고, 교수님과 문답하는 방식으로 진행됩니다. 9분이 지났을 때 밖에서 노크 한번 해주시고, 기본 10분이지만 10분이 지났다고 끊지는 않습니다.","notes":"","qa":[{"q":"면접관1: 네. 바로 질문 시작할게요. 자소서에 군중심리라는 책을 읽었다고 되어 있고, 사회문제와 갈등들을 사회의 수면 위로 끌어올릴 수 있을까라는 궁금증을 가졌다고 하는데, 이것을 미디어랑 연관지어서 말해보세요. 미디어 관련 내용이 많아서","a":"저는 군중심리라는 책을 사회문화 시간에 젠더갈등에 대해 탐구하며 읽게 되었습니다. 사회비교이론을 활용해 젠더갈등의 원인을 분석한 결과, 집단 극화현상이 그 원인이 됨을 알게 되었고, 이러한 집단 극화 현상이 일어나는 사람들의 심리에 대한 궁금증이 생겨 이 책을 읽게 되었습니다. 이 책에서 저자는 군중들은 주로 한명의 지도자가 가지는 일반적 신념에 지배받고, 결국 그 신념은 반복과 확산의 과정을 거쳐 군중들의 신념으로 자리잡게 되며, 군중들 간의 전염으로 군중의 동일성이 나타나고 있다고 언급하고 있었습니다. 저는 이러한 군중의 동일성 현상은 미디어를 통해서 더욱더 극대화되고 있다고 생각합니다. 정보들을 빠른 속도로 공유하고 전달하는 시대를 가능하게 해준 미디어의 특성상 이러한 확산 현상을 극대화시키고 있기에, 군중의 동일성을 고려할 때에는 미디어의 중요성이 더욱 커진다고 생각합니다. (반응: 고개 계속 끄덕끄덕하시면서 들으시고 표정도 좋으셨어요)"},{"q":"면접관1: 젠더 갈등을 예로 들었는데, 그러면 그들의 생각은 모두 군중의 동일성에서 비롯된 것일 뿐이라고 생각하는건가요?","a":"그것은 아닙니다. 젠더 갈등에서 사회의 변화와 개혁을 추구하기 시작한 개개인은 자신의 주체적인 신념에서 비롯되어 그 주장을 이어나간 것이라고 생각합니다. 그렇기에, 그들이 보여주는 군중의 모습은 군중의 긍정적인 모습을 대변하고 있다고 생각합니다. 하지만, 그러한 신념을 토대로 수동적으로 그 의견을 전염시키는 사람들이 군중의 동일성의 부정적 모습을 야기하는 것이라고 생각합니다. (반응 : 고개 계속 끄덕끄덕하시면서 들으시고 표정도 좋으셨어요)"},{"q":"면접관2: 연구활동을 진행했다고 나와있는데, 어떤 주제였고, 과정과 결과 한번 설명해보세요.","a":"어떤 연구를 말하는 건가요...?"},{"q":"면접관2: 아! 정치프로그램 관련이요","a":"네! 저는 당시에 정치예능프로그램을 접하고 그런 프로그램들이 사람들의 정치적 인식에 영향을 주지는 않을까 하는 궁금증이 생겨서 이를 주제로 사회과학적 연구방법 중 하나인 양적연구, 그 중에서도 질문지법으로 연구를 진행하였습니다. 먼저, 사람들의 정치적 인식을 진보, 보수, 중도로 구분하고, 각 인식별 사람들이 정치예능프로그램을 얼마나 접했고, 그를 통해 인식이 변했는지의 연부를 개념의 조작적 정의 과정을 거쳐 연구하였습니다. 질문지법을 한 결과, 처음에는 연령구분 없이 결과를 분석하고자 하였지만, 10대의 경우에는 정치예능프로그램을 접한 경우가 적어서 연령별로 나누어 결과를 분석함으로써 연구의 객관성을 키우고자 하였습니다. 이러한 과정을 거쳐 결과를 분석한 결과, 정치예능프로그램이 사람들의 정치적 인식에는 영향을 주지 않는다는 결론이 나왔습니다. 하지만, 이 부분에서 제가 연구 계획 과정에서 놓친 부분을 발견하였습니다. 바로, 정치인식의 변화여부를 통해 그 영향성을 파악하는 과정에서 변하지 않는 경우에, 인식이 강화된 것인지, 유지된 것인지에 대한 부분을 나누지 않았음을 알게 되었습니다. 그래서 문헌연구법을 통해 보충하여 탐구를 진행하였고, 그 결과 사람들은 자신의 신념과 비슷한 의견을 만날 때, 오히려 동조하며 신념을 강화하는 경향이 있다는 연구논문을 통해 사람들의 인식은 오히려 정치예능프로그램을 접하기 전보다 강화됨을 알 수 있었습니다. 이를 통해 군중의 동일성을 유도하는 군중심리와 집단극화 현상이 정치적 분야에서도 적용될 수 있다는 생각을 하게되었습니다. (반응 : 고개 계속 끄덕끄덕하시면서 들으시고 표정도 좋으셨어요)"},{"q":"면접관1: 그럼 군중의 동일성이 정치인식처럼 퍼질 수도 있지만, 군중 내에서도 신념이 퍼지지 않는 경우도 있잖아요. ~~ (이 부분을 너무 돌려돌려 길게 질문하셨어요)","a":"혹시 질문 다시 한번만 해주실 수 있을까요?"},{"q":"면접관1: 군중의 동일성이 퍼져나가서 발생하는 경우도 있지만, 그렇지 않은 경우도 있는데 이 부분은 어떻게 설명할 수 있을까요?","a":"음... 군중의 동일성이 퍼져나가는 경우는 사람들간의 공통적인 문제점 인식으로 인해 발생한다고 생각합니다. 역사적인 예시로 프랑스 혁명을 들 수 있는데, 프랑스혁명의 경우에는 부르주아들의 불만 표출로 시작되어서, 이러한 불만이 시민들에게도 공감되어 동참하게 되었고, 이것이 프랑스 대혁명으로 이어지게 되었습니다. 이러한 과정에서 보았을 때, 사회에서 발생하고 있는 문제점에 대한 비판적 인식과 그에 대한 공감이 형성 되었을 때에는 군중의 동일성이 퍼져나갈 수 있다고 생각합니다. 반대로 군중의 동일성 현상이 발생하지 않는 경우는 한 개인의 생각이 너무 독단적이고, 보편적인 사회문제에 대한 이야기를 담고 있지 않아 공감대를 형성하지 못한 경우에 발생할 수 있다고 생각합니다. (반응 : 여기서는 살짝 처음에 갸우뚱하시다가 예시들면서 긍정적인 반응 보이셨어요!)"},{"q":"면접관1: 그럼 그 공감 형성의 기준이 무엇일까요?","a":"음.... 각 나라에는 기본적으로 가지고 있는 신념이 존재합니다. 대한민국의 경우에는 민주주의와 자본주의 체제를 가지고 있습니다. 사람들은 이렇게 자신이 속한 사회의 신념에 영향을 받되, 개인의 사회적 배경이나, 개인적 환경과 경험으로 인해 공감대가 형성된다고 생각합니다. (반응 : 공감형성의 기준이 무엇이냐는 질문이 그 전 질문내용이랑 겹치는 내용이라고 생각이 들어서 어떻게 다르게 말해야 하는지 고민하다가 이렇게 답했는데 끄덕끄덕은 하시는데 반응이 엄청 좋진 않은 느낌이었어요)"},{"q":"면접관2: 아까 개념의 조작적 정의의 중요성을 느꼈다고 하셨는데, 개념의 조작적 정의가 뭔지 설명할 수 있을까요?","a":"개념의 조작적 정의는 질문지법에서 질문의 추상적 내용을 구체화하는 것을 의미합니다. 예를 들어, 제가 진행한 연구에서는 ‘사람들의 인식 변화’, ‘정치예능프로그램을 접한 정도’와 같이 수치화 시키기 모호한 내용들이 있었고, 이를 수치화시키기 위해 인식변화의 여부, 정치예능프로그램을 접한 횟수에 대한 기준을 설정하였는데, 이렇게 구체화시킴으로써 질문지법에 적용시키는 것이 개념의 조작적 정의라고 알고 있습니다. (반응 : 고개 계속 끄덕끄덕하시면서 들으시고 표정도 좋으셨어요)"},{"q":"면접관2: 네 이제 시간 다 되어서 나가시면 될 것 같아요.","a":"네! 감사합니다!후배들을 위한 조언 꼬리질문이나 깊이 있는 심화질문이 들어오더라도 당황하지 않으셨으면 합니다! 심도 있는 질문을 해볼 정도로 괜찮은 서류 점수를 받았다는 의미라고 생각하고 차분하게 본인 생각을 말하면 될 것 같아요. 생각보다 압박하는 분위기는 아니었고, 한 분은 조금 딱딱하셨지만, 나머지 한 분은 부드러우셨어요.면접을 준비할 때에는 한 활동과, 다른활동에서 읽었더라도 비슷한 주제의 책은 꼭 연결지어 생각하는 시간을 꼭 가졌으면 좋겠습니다! 조금 더 힘내서 생기부 활동과 작성했던 보고서들을 꼼꼼히 복기하고 가시면 좋은 결과 얻을 수 있을 것이라고 생각합니다!2023 대입 면접후기"}],"result":"합격","resultNote":"","src":"충청북도교육청 「2024 수시 대비 면접 후기집」","year":"2024학년도"},{"univ":"서울대학교","dept":"소비자학과","jeonhyeong":"학생부종합(지역균형)","method":"- 면접대기실에서 대기 -> 면접장 이동 -> 면접 응시 -> 바로 귀가- 생활기록부와 자기소개서 기반 면접<유의사항은 서울대학교 전체가 아닌 올 한 해 생활과학대학 면접에","notes":"국한될 수 있음>- 입실 마감 시간 이후에는 면접 준비 자료를 볼 수 없음.- 면접장에 책상 있었음.","qa":[{"q":"A, B: 네~ 어서와요~","a":"안녕하세요? 면접 번호 5번입니다."},{"q":"A, B: 네, 자리에 편하게 앉으세요.B: 학교 올 때 많이 힘들지 않았어요? 학교 많이 춥죠?","a":"(웃음) 오늘 날씨는 많이 춥지만, 서울대학교에 올 수 있어서 제 마음은 따뜻합니다!!"},{"q":"A, B: (환하게 웃으심)A: 지원자는 소비자 학과가 무엇을 배우는 학과라고 생각해요?","a":"저는 소비자 학과가 소비자를 단순히 기업의 이윤 추구의 대상으로 보는 것이 아니라 소비자의 힘과 주체로서의 역할을 올바르게 인식하는 것을 도와주는 학문이라고 생각합니다. 특히 이런 관점이 기업이 소비자를 대하는 태도에도 영향을 줌으로써 기업의 이익에도 영향을 줄 수 있는, 사익과 공익 모두를 조화롭게 할 수 있는 학문이라고 생각합니다."},{"q":"A: 그러면 소비자학과에 들어와서 어떤 것들을 공부하고 싶나요? 그리고 학과 지원 동기 등에 대해서 말해줄래요?","a":"네, 서울대학교 홈페이지에 들어가서 소비자학과의 커리큘럼을 확인한 경험이 있습니다. 저는 그중 소비자 빅데이터 분석론과 소비행태 행동론과 같은 과목에 깊은 관심이 있습니다. 저는 1학년 때 지역시장 침체 원인 분석 활동, 2학년 때 자영업 관련 탐구 활동을 하면서 제 탐구의 중심에는 항상 ‘사람’이 있다는 것을 알게 되었습니다. 3학년 때는 1~2학년 때 학습했던 내용들을 직접 지역에 적용해 보고자 직접 ‘직업인 초청’이라는 활동을 만들어 로컬크리에이터 분들의 고충을 들었습니다. 그러면서 많은 분들의 고충이 ‘소비자의 니즈를 파악하는 것이 어렵다는 것’, ‘트렌드를 분석하기 어렵다는 것’을 알게 되었고 고정적 소비층의 확보에 어려움을 겪는 것을 알게 되었습니다. 따라서 저는 이러한 분들을 직접적으로 도울 수 있는 연구를 진행하는 소비자 연구원이 되고 싶어 소비자학과에 지원했습니다."},{"q":"A: 그렇다면 1학년 때부터 관련 활동을 쭉 이어왔던 건가요?","a":"네, 그렇습니다. 1학년 때는 “코로나 19만이 지역 시장 침체에 원인을 주는 것일까?”라는 의문을 가져 탐구를 진행하며 시장 자체에 매력도가 낮다는 점을 알게 되었고 2학년 때는 ‘골목사장 분투기’라는 책을 직접 읽으며 자영업자들의 어려움에 직접 공감할 수 있었습니다."},{"q":"A: 조금 긴장한거 같은데, 편하게 말씀해 주셔도 됩니다~B: 보니까 한국 지리 시간에 MCI 모형이라는 것을 학습했던데, 이걸 왜 배우고 MCI 모형이 무엇인지 구체적으로 설명해 줄래요?","a":"한국지리 시간에 상업 입지 이론을 학습했습니다. 저는 MCI 모형 말고도 당시 컨버스의 분기점 모형, 허프의 확률모형 또한 함께 학습했습니다. 그런데 두 상업 이론은 매장의 면적과 거리로 소비자의 유인력을 측정하는 특징이 있었습니다. 하지만, 전통 시장과 대형 마트도 면적이 넓지만, 사람들이 많이 찾아오지 않는다는 의문을 품게 되었고, 저는 공간의 분위기, 가성비, 접근성 등 다양한 환경적 요소가 소비자 유인에 영향을 준다는 것을 알게 되었습니다. MCI 모형은 공간의 분위기, 접근성 등과 같이 환경적 요소가 소비자의 유인력에 영향을 줄 수 있음을 인정하고 이 요소들을 활용해 공간을 평가하는 이론입니다."},{"q":"A: 친소비자적 공간 구축에 대한 탐구도 진행하고 군집 분석에 관한 탐구도 진행하고 사회 탐구를 많이 진행했던데 구체적으로 어떻게 자료를 수집해 탐구를 진행한 건가요?","a":"군집 분석에 관한 내용을 구체적으로 말씀 드려도 되겠습니까?"},{"q":"A: 네, 그러세요~","a":"저는 학생들이 자주 가는 카페가 일관성이 있다는 것에 호기심을 갖게 되었고 카페 가치 평가와 소비자 특성 및 가치 조사를 통해 이 관련성에 대해 탐구를 진행하고자 하였습니다. 구체적으로 카페 가치 평가는 학생들이 각 카페에 대해 카페가 가지고 있는 가치를 각각 평가함으로써 카페별 비교우위를 정하는 평가였습니다. 소비자 특성 및 가치 조사는 소비자가 카페에 대해 어떤 가치를 중요하게 여기는지, 소비자의 성별, 브랜드 제품 선호 정도와 관련된 문항 등을 넣어 설문을 진행했습니다.(여기서 약간 말도 더듬고 횡설수설한 감이 있지만, 교수님 두 분이 고개를 끄덕이면서 들어주셔서 무사히 답변은 마침)"},{"q":"A: 그런데 군집 분석을 하면서 많이 힘들었을 거 같아요. 군집 분석은 어떤 프로그램을 이용해 진행한 거죠?","a":"네, SPSS라는 통계 프로그램을 이용해 진행했습니다. 저는 이전에는 상관관계 등을 분석할 때 엑셀 프로그램을 자주 사용하곤 했습니다. 그런데 엑셀 프로그램만으로는 군집 분석을 수행하기 어렵다는 것을 알게 되었습니다. 이에 저는 SPSS 통계 프로그램에 주목하게 되었습니다. 당시 무료 체험판이었던 프로그램을 활용하고 SPSS 실무서와 인터넷 자료 등을 직접 찾아가며 수학 시간에 배웠던 유클리디안 거리 개념을 활용한 K-평균 군집 분석을 실시하거나 직접 덴드로그램을 형성하는 등의 작업을 수행했습니다."},{"q":"A: 유클리디안 거리요? 이 내용은 수학 시간에 배우는 건가요?","a":"네, 저는 수학과제 탐구 시간에 유클리디안 거리 개념을 활용했습니다. 이때 맨하탄 거리와 마할라노비스 거리 등도 함께 학습했는데, 많고 다양한 변수들을 활용한 군집분석을 위해서는 다른 거리 개념보다 유클리디안 거리 개념이 가장 적합하다는 것을 알 수 있었고, 이에 유클리디안 거리 개념을 활용한 K-평균 군집 분석 방법을 채택했습니다."},{"q":"B: ‘소비의 역사’라는 책을 읽었었네요? 이 책이 어떤 내용인지 조금 구체적으로 설명해 줄 수 있을까요?","a":"소비의 역사에 나온 내용 중 의류 소비에 관한 부분을 먼저 말씀드리겠습니다. 옛날 귀족들은 보석과 같은 화려한 장신구, 사치품 등을 활용한 의류가 당시 유행이었습니다. 그런데 프로테스탄트 윤리가 퍼져나가게 되면서 당시 상류층들은 절제, 근면에 관해 신경쓰게 되었고 결국은 지금의 화이트 칼라가 주로 착용하는 스리피스 슈트가 상류층들 사이에서 유행하게 되면서 자본주의의 도입과 변천과정과 관련된 소비를 확인할 수 있었습니다. 또 하나 인상 깊었던 점은 바로 흑인들의 보이콧이었습니다. 당시 차별을 당하던 흑인들이 구매력을 갖게 된 후 백인 상점들에 대해 보이콧을 하게 되었고 이는 인종차별 해소 등에 영향을 주었다는 점에서 기억에 남고 인상깊었던 장면이었습니다. (보이콧과 관련된 부분의 끝마무리를 잘 하지 못해서 아쉬웠던 부분)"},{"q":"B: 네, 이제 시간이 2분 조금 안남았는데 자신의 최종 목표나 꼭 하고 싶은거, 이루고 싶은거 있으면 말해주세요.","a":"네, 저는 소비자 연구원으로서 제가 꼭 하고 싶은 연구가 있습니다. (A, B 교수님 모두 관심있게 쳐다보심) 저는 앞서 말씀드린 테마화된 소비자 공간의 구축 등에 관심이 깊습니다. 따라서 컬러나 오감 등을 활용한 공간, 또는 감성마케팅이나 데카르트 마케팅 등을 활용한 기법이나 공간이 소비자들의 구매 욕구와 어떤 관련이 있는지, 구매 심리에 어떤 영향을 주는 지 등에 대해서 현재 학생으로서 진행하기는 어려웠던 탐구들을 꼭 수행해 보고 싶습니다.또, 저는 서울대학교 트렌드분석 센터에 들어가서 연구를 진행해 나가고 싶고, 나중에는 소멸되어 가는 지역에 대해 사업이나 정책, 지역 개발 등에 대해 조언하고 도움을 줄 수 있는 컨설턴트가 되는데도 관심이 있습니다."},{"q":"B: 정말 수고하셨고요, 마지막으로 하고 싶은 말 있을까요?","a":"우리나라 최고의 대학교에서 면접을 볼 수 있는 기회를 주셔서 정말 감사드리고 서울대학교 소비자학과에 진학하게 된다면, 공동체에 헌신할 수 있는, 사회에 봉사하는 소비자 연구원이 될 수 있도록 최선을 다하겠습니다. 다시 한 번 감사드립니다!!"},{"q":"A, B: 네, 시간이 다 되었네요, 정말 고생하셨고 조심히 돌아가세요~","a":"네, 감사합니다!(나가기 전에 한 번 더) 안녕히 계세요!"},{"q":"A, B: 네~ 후배들을 위한 조언","a":"자신의 생활기록부를 보고 질문이 나올 수 있는 모든 부분을 형광펜으로 칠하세요. 그리고 칠한 부분에 대해 각각 질문을 만들면, 정말 많은 면접 질문들이 도출될 수 있어요. “이렇게까지 해야 하나?”라는 의문이 들 수도 있지만, 꼼꼼하게 보지 않으면 면접 준비에 큰 허점을 남길 수도 있고 마음도 불안합니다. 저도 준비한 질문이 2~300개 정도 됐는데 실제 준비한 질문도 나왔고, 그렇지 않은 질문에 대한 답변도 제가 준비했던 답변들을 적절히 이용해서 답했던 기억이 있습니다. 열심히 준비한 만큼, 면접장에 가서 편해질 거라고 확신합니다.친구들이랑 면접 스터디를 하면 얻을 수 있는 것들이 많아요. 면접 노하우 습득, 면접 답변에 관한 서로 다른 관점 파악, 면접 태도 교정 등을 할 수 있기 때문입니다. 생활기록부 기반 면접은 혼자서 연습하기 쉽지 않으니 서로서로 도와주면서 모의 연습을 해보세요. 저의 경우는 친구들과 함께 면접관과 면접자의 역할을 바꿔가며 압박면접을 연습했는데 제가 놓치거나 소홀한 부분에 대해 새롭게 알게 되어 대비한 질문이 실제 면접에도 나와 신기했던 경험이 있습니다.면접은 면접관들과 일종의 공적인 소통을 하는 특별한 상황이라고 할 수 있습니다. 면접 상황에 적절하지 않은 발화 태도(발 떨기, 손 계속 움직이기, 지나치게 편하게 말하기, 말 너무 길게하기 등)는 꼭 고치는게 좋습니다. (그러니 모의면접을 자주 해보시고 말하고 있는 자신의 모습을 촬영해 보세요.) 또 저처럼 멘탈이 약한 친구들은 꼬리질문, 추가질문이 나올 때 많이 당황할 수 있는데, 시간을 조금 가진 후에 답변을 정리해서 말하는 등 돌발상황 매뉴얼을 만들어 두면 대비하기 용이합니다.2023 대입 면접후기"}],"result":"합격","resultNote":"최초합","src":"충청북도교육청 「2024 수시 대비 면접 후기집」","year":"2024학년도"},{"univ":"서울대학교","dept":"수리과학부","jeonhyeong":"학생부종합(지역균형)","method":"면접 대기실에서 자신의 차례에 면접실로 이동. 10분간 생기부 면접 후 마무리.","notes":"개인 정보 발언 X","qa":[{"q":"기하 교과목의 장단점","a":"도형의 차원 확장, 벡터를 처음 접하는 등의 장점이 있음. 하지만 공간 벡터가 교육과정에서 사라지고, 외적이 존재하지 않는 등 확장성이 부족하다는 점에서 아쉬움을 느꼈음."},{"q":"고급수학에서 한 활동","a":"기하에서 부족함을 느낀 내용들을 추가적으로 고급수학에서 배울 수 있었음. 또한 드 무아브르 정리에서 극 좌표계, 오일러 파이 함수와의 연관성을 느꼈고, 실제로 맞음을 확인해 보았음."},{"q":"이산 로그가 무엇인지.","a":"잉여계에서의 로그, 주로 모듈러인 서로소로 이루어진 기약잉여계를 주로 다룸."},{"q":"폴라드 로가 무엇인지.","a":"플로이드 순환, 비둘기 집 원리를 활용하여 소인수분해 또는 이산 로그를 구하기 위한 알고리즘."},{"q":"지금 증명이 가능한지.","a":"앞서 말한 과정으로 이루어져 있기 때문에 충분히 답은 구할 수 있음."},{"q":"꼬인 위치에 있는 직선 사이의 거리는 왜 구했는지","a":"다양한 문제 중 저런 걸 다루는 경우를 보지 못해서 구해보고 싶었음."},{"q":"일반화 했다는게 무슨 뜻인지","a":"그 거리를 구하는 항상 구하는 방법을 정리했다는 의미임."},{"q":"지금 증명이 가능한지","a":"과정 자체를 직접 만들었기에 충분히 지금도 떠올릴 수 있음.후배들을 위한 조언 독서는 사람마다 다르다고 하기에 준비해두는 것이 좋을 듯. 확실히 해당 학과와 관련된 질문들이 주를 이루고 있기에 자신이 지원한 학과와 관련된 과목, 세특을 확실하게 봐두는 것이 큰 도움이 될 것. 10분이라는 시간이 굉장히 짧기에 분명하게 전달할 수 있는 능력이 필요할 듯.2023 대입 면접후기"}],"result":"합격","resultNote":"X","src":"충청북도교육청 「2024 수시 대비 면접 후기집」","year":"2024학년도"},{"univ":"서울대학교","dept":"인문계열","jeonhyeong":"학생부종합(기회균형특별Ⅰ1차 합격 이후 안내된 날짜와 시간, 장소를 숙지하여 면접 진행됨.)","method":"면접 대기실에서 즉시 면접 번호를 부여함.생기부와 자소서를 중심으로 면접이 진행되며 한 지원자당 10분씩 면접이 진행됨.","notes":"","qa":[{"q":"수많은 국가 중에 중국에 대해 더 집중적으로 관심을 가졌던 이유는 무엇인가요?","a":"중국은 대한민국과 정치적, 외교적으로 매우 밀접한 국가이기 때문에 심도 있게 탐구했으며, 중국은 정치 경제적으로도 특이한 체제를 취하기에 접근하기 까다로운 면도 많아서 오히려 호기심을 자극했던 것 같습니다. 뿐만 아니라, 중국어 과목을 배우며 국어와는 다른 한어병음, 한자, 성조 등과 같은 복잡한 체계에 대해 배우는 것에도 흥미를 느껴 본격적으로 중어중문학을 공부하고자 하는 목표를 세우게 되었습니다."},{"q":"중국은 어떤 면이 까다로운가요?","a":"중국은 신자유주의적인 세계화의 흐름에 반해 여전히 공산주의와 사회주의 체제를 온전히 유지하고 있는 국가이며, 동시에 이러한 사회 체제 속에서 자본주의적 요소를 도입하며 체제의 괴리가 생기기도 하는 현상 등에 대해 포괄적으로 이해해야 하기 때문입니다."},{"q":"어떤 자본주의적 요소가 도입되었나요?","a":"중국의 자유로운 수입과 수출 문화에서도 이러한 요소들을 확인할 수 있다고 생각합니다. 뿐만 아니라, 조금 다른 방향이기는 하나 모두의 평등 분배를 주장하는 공산주의 사회에서 권력층이 부와 재산을 독점하는 것은 그들이 추구하는 체제와의 괴리를 넓힌다고 생각합니다."},{"q":"공산주의 국가에서는 수입과 수출이 일어나지 않는 건가요?","a":"일어나지 않는 것은 아니지만, 수출과 수입이 이루어지는 과정에서 자본주의적 논리와 흐름에 의해 진행되는 것에서 자본주의적 요소를 발견할 수 있다고 생각했습니다."},{"q":"자기소개서에서 대한민국의 만연한 반중정서에 대한 이야기가 나왔는데, 왜 반중정서가 한국 사회에서 만연해졌다고 생각하나요?","a":"크게 두 가지의 요소가 있다고 생각합니다. 첫째로는, 황사와 미세먼지 문제와 같이 실제로 중국이 국제적으로 영향을 줄 수 있는 요소들에 대해 무책임하게 행동하는 것이 있습니다. 이러한 부분에 대해서는 상당부분 그 반중정서가 정당하다고 생각하며, 국제적으로 규탄받아야 한다고 생각합니다. 그러나 저는 두 번째 요소에 집중했습니다. 두 번째로는 명확한 이유 없이 무분별한 중국에 대한 반감이며, 이의 주된 요소는 대한민국에 비해 뒤처져있던 중국의 급속한 성장에 의해 달라진 위상에 대한 일종의 질투 감정이라고 생각합니다."},{"q":"지원자는 이러한 분야에 관심이 많으므로 그렇게 느낄 수도 있지만, 실제로 한국인들이 중국에 대한 시기와 질투를 느낄까요?","a":"저는 그 근거로서 미중패권전쟁을 들 수 있다고 생각합니다. 제가 1~2학년에 걸쳐서 탐구했던 미중패권전쟁을 통해 가장 놀랐던 점은 공고한 세계 패권국이라고 생각했던 미국과 견줄 만큼 성장한 국가가 중국이라는 점이었습니다. 이처럼 세계의 패권을 두고 미국과 경쟁하는 나라가 될 만큼 성장했다는 사실은 한국인들로 하여금 시기와 질투의 감정을 불러일으킬 수 있다고 생각합니다."},{"q":"자기소개서에서 루쉰의 광인일기에서 루쉰의 통찰력에 감탄했다고 했는데, 어떤 면에서 그런 건가요?","a":"광인일기는 문화대혁명 시기의 배척당하는 지식인들을 광인으로 표현하여 묘사한 작품입니다. 이 책을 읽고 나서 가장 기억에 남았던 이유는 책 속에서 온전히 지식인을 배척하는 감정을 느껴보기도 하고, 다 읽고 나서는 제가 느낀 감정이 당시의 사람들이 지식인에 대해 느꼈을 진실된 감정이라는 점이었습니다. 당시 사회상을 그저 묘사하는 것이 아닌 독자로 하여금 직접 감정을 느끼게끔 해주는 작품에 인상 깊었으며 작가의 통찰력에 감탄했습니다."},{"q":"현대 사회에서 광인은 어떤 사람들일까요?","a":"정확하게 대응해본다면 지식인이 그 대상이 될 수 있다고 생각합니다."},{"q":"그렇다면 지식인들이 현 사회에서 배척당하는 경향이 있다고 생각하나요?","a":"지식인에는 다양한 종류가 있기에, 자신의 재능이 현 사회와 맞지 않다는 이유만으로 그 능력을 펼치지 못하는 지식인들도 있다고 생각합니다. 그러나 현대 사회에서 지식인들은 오히려 위선적인 모습을 갖게 되는 것을 경계하며, 가진 재능과 지식이 대중화되는 것에 기여할 수 있도록 노력하는 것이 중요하다고 생각합니다."},{"q":"마지막으로, 1학년 통합과학 세특에서 20년간 썩지 않는 햄버거에 대한 산화반응을 실험하는 과정에서 변인 통제가 우수했다고 쓰여있는데, 어떤 변인을 어떻게 통제했나요?","a":"20년간 썩지 않는 햄버거에 대해서는 하나의 사례로서 문헌 연구로만 진행했고, 실제 산화반응을 위한 실험은 계란과 소금물을 통해 했습니다. 첫 번째 실험에서 삶은 계란의 껍질을 까지 않은 채로 진행해야 하는데, 계란의 껍질을 까서 실험을 했으며, 첫 실험에서 햇빛이 잘 두는 곳에서는 산화반응이 더욱 촉진된다는 것을 고려하지 못해서 산화반응의 정확한 진행 과정 관찰에 실패했던 경험을 거름으로 삼아 두 번째 실험에서는 실온에서 진행하되, 햇빛이 잘 들지 않는 곳으로 선정하는 등의 노력을 기울여 변인을 철저히 통제하기 위해 노력했습니다."},{"q":"아주 재미있는 대화였습니다. 시간이 다 되어서 여기까지 하도록 할게요.","a":"감사합니다. 후배들을 위한 조언 누구에게나 할 수 있을 만한 평범한 질문들도 많이 대비해 갔는데, 예상외로 그런 보편적인 질문보다는 내 생기부와 자소서에 대한 구체적인 질문들을 많이 받았고, 꼬리질문도 굉장히 많이 받았음. 매우 구체적인 꼬리질문에는 당황하기도 하고, 모르는 것도 있어서 정확하지는 않은 답변이었을 수도 있지만, 끝까지 당황한 모습 보이지 않고 최대한 아는 선에서 답변하기 위해 노력하는 태도를 중시하셨던 듯함. 정말 예상하지 못했던 질문이나, 깊숙한 꼬리질문에도 차분히 기억을 떠올리면서 내가 보여드릴 수 있는 것들을 최대한 잘 정리해서 말씀드리는 것이 가장 중요한 부분이라고 생각함.2023 대입 면접후기"}],"result":"합격","resultNote":"","src":"충청북도교육청 「2024 수시 대비 면접 후기집」","year":"2024학년도"},{"univ":"서울대학교","dept":"자유전공학부","jeonhyeong":"학생부종합(기회균형특별-8시에 입실-건물 안으로 들어가면 체온 측정하고 수험표 보이고 문진표 작성한 거 제출 (문진표 미리 프린트해서 작성해감))","method":"-화장실은 손 들면 감독관 동행 하에 1명씩 이용 가능-부여받은 가면접번호 순으로 면접 실시-대기실에서 불리면 본인 짐을 모두 챙겨 면접실 앞 의자에 앉아서 대기함. -면접실은 작은 편. 교수님과의 거리도 꽤 가까움.","notes":"-면접관과 면접자 모두 마스크를 착용하지만 페이스실드는 사용하지 않음.","qa":[{"q":"자유전공학부에 왜 지원했어요?","a":"제 꿈은 자유를 실현할 수 있는 건축을 하는 것입니다. 이를 위해선 인문학, 수학, 과학 등 다양한 기초 학문을 먼저 학습한 필요가 있다고 생각했습니다. 또 서로 다른 학문 간 융합을 할 수 있는 능력이 필요하고 이를 모두 만족시킬 수 있는 학과는 자유전공학부밖에 없다고 생각했습니다."},{"q":"농어촌에서 오랫동안 살았죠? 농어촌의 문제점이 뭐라고 생각해요?","a":"학업적인 측면에서 말씀하시는 건가요? 아니면 그냥 지역 경제 관련해서..."},{"q":"아무거나 느낀 게 있으면 말해보세요.","a":"두 가지 측면에서 말씀드리겠습니다. 첫 번째로 지역 인프라가 부족하다고 생각합니다. 지역만의 특색을 살릴 수 있는 투자와 정책이 이루어져야 하는데, 모든 도시가 서울을 모방하고 있기 때문에 지역 경쟁력을 상실하고 있다고 생각합니다. 두 번째로 학업적인 측면에서 학생들의 기본값이 낮다고 생각합니다. standard가 낮다 보니 전체적으로 학업 성취도도 낮아지는 것이 문제라고 생각합니다."},{"q":"확률과 통계에서 양자역학과 관련된 확률실험을 한 것으로 나와있는데, 이 탐구를 한 동기와 참고한 문헌이 있는지..","a":"양자역학은 인간이 경험하는 세계(거시세계)와는 다른 미시세계만의 물리법칙을 따른다는 사실이 흥미로웠고... 확률 자체는 어쩌면 불확실성을 가지고 있는데 이런 확률을 통해 명확한 수치를 얻을 수 있다는 것에 흥미를 느껴서 탐구하게 되었습니다. (이때 말이 끊겨서 참고 문헌을 답변을 못할 뻔 했지만 교수님이 더 하고 싶은 말이 있으면 하라고 하심)양자역학과 관련된 여러 책과 화학 시간에 배운 러더퍼드 알파입자 산란 실험과 연관지어 이해하려고 노력했습니다."},{"q":"수학2 시간에 건물이 직사각형인 이유에 대해 탐구했다고 하는데, 설명해줄 수 있을까요?","a":"효율성에 그 이유가 있었습니다. 둘레 대비 가장 큰 넓이를 가질 수 있는 것은 원인데, 삼각형과 사각형을 제외한 다른 다각형들은 배열했을 때, 항상 남는 공간이 생깁니다. 삼각형과 사각형 중 둘레 대비 더 큰 넓이를 가지는 것은 사각형이기 때문에 사각형이 사용된다고 생각합니다."},{"q":"육각형은 틈이 없이 채울 수 있음. 벌집 모양을 보면 채워진 모양을 볼 수 있는데 왜 사각형?","a":"음.."},{"q":"내부구조도 생각해서 한 번...","a":"(육각형과 사각형의 내부구조 어쩌고 설명했는데 잘 못함.)//면접 끝나고 생각난 건데 “다양성”의 측면에서 다름. 정육각형은 크기가 다르거나 모양이 다르면 빈틈없이 채울 수 없는 반면, 직사각형은 크기나 모양이 달라져도 효율적으로 공간을 채울 수 있음."},{"q":"건축과 수명 그리고 권력의 관계에 대해 흥미로운 탐구를 했어요. 만리장성에 대해서... 건축과 수명의 관계를 따로 탐구해본 게 있을까요?","a":"이스터 섬의 모아이 석상, 영국의 스톤헨지 등 무거운 돌을 이용한 거대 건축이 많이 나타난다고 알고 있습니다. 무거운 돌을 사용하여 건축물의 수명을 늘리고 그 시간만큼 과시가 된다고 생각합니다. (생각못했던 질문이라 당황함.)"},{"q":"건축과 권력의 관계에서 부피, 재료, 구조의 역할에 대해 탐구했는데, 우리나라에도 이렇게 권력을 나타내는 건축물에는 무엇이 있을까요?","a":"음... 특정 기업을 언급해도 되나요? (롯데타워랑 현대 신사옥 생각함)"},{"q":"아니 뭐.. 기업의 건축물이 권력을 과시하는건 아니니까.. 역사적인 건축물에서...","a":"(순간 조선 총독부랑 황룡사 9층 목탑 등 떠올랐지만 황룡사 9층 목탑은 교수님이 말하는 권력이랑 거리가 멀고 조선 총독부는 관련을 못 지을 것 같아서 바꿈) 우리나라 건축물로는 조선 시대 궁을 들 수 있습니다. 하지만 우리나라 전통 건축물의 경우 목조 건축물이기 때문에 높이 지을 수 없습니다. 대신 넓은 면적에 건축물을 지어 권력을 과시했다고 생각합니다."},{"q":"햄릿 “죽느냐, 사느냐.”라는 구절에 대해 많이 생각해본 것 같은데... 존재론과 관련해서.. 이 구절 원문이 뭔지 알고 있나요?","a":"“to be or not to be.”로 알고 있습니다."},{"q":"그럼 “죽느냐, 사느냐.”랑 “있음이냐, 없음이냐.” 중 뭐가 더 잘된 번역이라 생각해요?","a":"“있음이냐 없음이냐.”가 더 잘 된 번역이라고 생각합니다. “to be or not to be.”에서 “be”의 “있다”라는 의미가 더 잘 전달되고, 단순히 생사의 문제에서 사후세계에 인간이 존재하는지에 대한 문제로, 또 존재 자체의 문제로 확장하여 이해할 수 있기 때문입니다. 후배들을 위한 조언 세특 활동에 본인이 호기심을 가지고 수행했다면 서울대 면접은 그리 어렵지 않습니다. 본인이 한 활동을 한 번씩 모두 정리하며 동기, 참고자료, 출처, 느낀 점 등을 생각해보세요. 그리고 자소서에 들어가거나 중요한 활동 같은 경우 내용을 다시 공부해야 합니다. 활동의 내용을 묻는 질문에 그치지 않고 확장하는 질문에도 답변해야 하기 때문에 활동을 할 당시에 호기심을 가지고 활동하고 이를 자신의 배경 지식과 가치관으로 만드는 과정이 핵심이라고 생각합니다. 제가 다닌 고등학교는 학생 규모가 매우 작았기에 이공계 진학에 필요한 과목을 수강하는데 제한이 많았습니다. 입시를 준비하며 과학 기술원이나 공대는 진학이 어려울 수 있다는 말을 많이 들었습니다. 하지만 이에 포기하지 않고 공동교육과정으로 고급수학이나 물리학 실험을 수강하고, 스스로 인터넷 강의를 찾아 공부하는 등 제가 할 수 있는 영역까지 필요한 역량을 쌓으려 노력했습니다. 저와 같은 환경에 있는 학생들 또한 많을 것이라 생각합니다. 가장 중요한 것은 자신의 역량입니다. 여러분도 환경에 굴복하지 않고 꿈을 향해 나아가는 학생이 되길 바랍니다. 2023 대입 면접후기"}],"result":"합격","resultNote":"","src":"충청북도교육청 「2024 수시 대비 면접 후기집」","year":"2024학년도"},{"univ":"서울대학교","dept":"재료공학부","jeonhyeong":"학생부종합(기회균형특별Ⅰ오전 8시까지 36동으로 수험표확인하며 입실해야한다. 입실해서 큰 대기실에서 면접 유의사항을 공지한 뒤 본인이 몇조이고, 몇 번째로 면)","method":"접보고, 몇 시쯤 끝나는지 알려준다. 그 뒤에 휴대폰과 전자기기 걷고 대기한다. 자기 조 차례가 되면 (지역균형 8명, 기회균형 8명 정도) 한 줄로 큰 대기실을 나가 엘리베이터를 타서 (3층?) 으로 간다. 거기서 교수님이 계신 방 앞에 의자가 여러 개 있는데 앉아서 대기한다. 본인 차례가 되면 문을 열고 들어가면 면접 시작이다. 아침에 화장실에 매우 사람이 많아서 줄이 기니까 미리 해결하고 오세요.","notes":"수험표랑 신분증 챙기세요.서울대는 엄청 크니까 길 파악 잘 해놓으세요.","qa":[{"q":"안녕하세요 자기소개 해주세요.","a":"안녕하십니까? 에너지와 환경문제를 해결하고자 친환경 전지연구원이라는 꿈을 가지고 있는 지원자입니다. 이러한 꿈을 이루기 위해서는“공학적 사고 역량”과“의사소통 역량”이 필수적이라고 생각하였습니다. 이를 위해 1차 전지를 만들어 실험해 보고, pem연료전지를 분해해보는 등 많은 탐구를 진행하며 친환경 전지의 효율성 개선에 대한 공학적 사고 역량을 기를 수 있었습니다. 또한 학급 반장과 동아리장으로 활동하며 학급 축제 운영에서의 역할 분배와 실험에서의 문제 상황을 팀원들과의 협력을 통해 해결하며 상대방의 시선에서 바라보는 의사소통 기술도 배울 수 있었습니다. 이와 같은 역량을 바탕으로 학문뿐만 아니라 기초교양도 중시하는 서울대학교에서 친환경 전지연구원이라는 저의 꿈을 펼쳐보고 싶기 때문에 서울대학교 재료공학부에 지원하게 되었습니다."},{"q":"많은 과목을 수강하셨는데 그중 고급물리학을 배우면서 어려웠던 점은 없었나요? 있었다면 그 어려움을 어떻게 해결했나요?","a":"고급물리학을 배우면서 여러 공식을 유도하는 과정에서 미분방정식이 사용되었습니다. 예를 들어 RC회로에서 전하량이나 전류를 구하는 공식을 구하는 과정에서 사용되었는데 이러한 공식들을 유도하는 과정에서 미분방정식에 대한 이해가 아직 부족하여서 어려움이 있었습니다. 하지만 이를 극복하기 위해 선생님께 여러 차례 여쭈어보고, 미분방정식과 관련된 여러 동영상 강의를 참고하는 등 노력을 하여 결국 미분방정식을 이해하여 풀 수 있게 되었습니다."},{"q":"기하 시간에 ‘뉴턴의 프린키피아’ 라는 책을 이용하여 태양열 조리기를 탐구하였는데 이 책을 이용하여 어떻게 탐구한건가요?","a":"아 먼저 태양열 조리기란 포물선의 태양광 판에 태양광을 평행하게 입사하면 포물선의 초점으로 빛이 모여 음식을 가열하여 조리하는 원리로 작동하는 조리기입니다. 저는 이 조리기에서 포물선의 초점이 어디에 있는 것이고, 이 초점의 위치를 어떻게 정확하게 구하는 것인지 자세하게 알고싶어서 ‘뉴턴의 프린키피아’ 라는 책을 참고하여 탐구하였습니다."},{"q":"앞으로 미래에 어떤 사람이 되고 싶나요?","a":"저는 친환경 전지연구원이라는 꿈을 가지고 있습니다. 그렇기 때문에 수소연료전지의 효율을 향상시켜 수소연료전지의 상용화에 더욱 이바지하는 연구원이 되고 싶고, 리튬-공기전지의 과전압 문제와 같은 여러 차세대전지의 문제도 해결하는 연구원이 되고싶습니다."},{"q":"연구원이 되고싶은 것 같은데 연구원이 가져야 할 자질이 뭐라고 생각하시나요?","a":"2가지를 말씀드리겠습니다. 창의성과 협동심이라고 생각합니다. 먼저 고교생활동안 여러 탐구와 실험을 해나가면서 예기치 못한 문제에 직면했을 때 그것을 해결하는 창의성이 연구원으로서 중요하다고 생각하였습니다. 또한 요즘은 융복합시대라서 협력이 중요하고, 하나의 전지를 만들 때도 분리막, 가스확산층, 촉매층, 전해질막 등 여러 부품이 결합되기 때문에 여러 연구원의 협력이 중요해서 협동심 역시 연구원의 중요한 자질이라고 생각합니다."},{"q":"교수님: 고급화학시간에.........(갑자기 문이 열리면서) 밖에있던 관리자분: 끝났습니다.교수님 : 네 수고하셨습니다.","a":"감사합니다.후배들을 위한 조언 서울대라고 해서 되게 겁먹었는데 생각보다 평이해서 너무 긴장 안하셔도 될거같아요.제가 면접을 5개를 봤는데 가장 편안한 분위기였어요 걱정하지마세요.솔직히 말하면 면접에서는 큰 변별력 없고 이미 정해진 것 같으니까 맘편히 하고싶은 말 다 하고 오세요.2023 대입 면접후기"}],"result":"합격","resultNote":"","src":"충청북도교육청 「2024 수시 대비 면접 후기집」","year":"2024학년도"},{"univ":"서울대학교","dept":"재료공학부","jeonhyeong":"학생부종합(지역균형면접관님은 두 분이십니다. 한 분은 고개까지 끄덕여주시며 호응해주)","method":"셨기에 면접 분위기는 부드러웠습니다. 번갈아 질문하시며 한 분은 주로 인성 쪽을 한 분을 전공 측면을 질문하십니다. 밖에서 시간에 맞춰 종을 쳐주시는 분이 계십니다. 종이 울리면 바로 나와야 합니다.","notes":"들어갈 때 전자기기를 소지해도 되지만 면접 볼 때는 다 전원을 꺼야 합니다. 생기부는 면접 보기 전까지 볼 수 있으니 챙겨가면 좋습니다.","qa":[{"q":"왜 재료공학과 지원했고, 무엇을 하는 학문이라고 생각하는지?","a":"화학에 대한 흥미를 바탕으로 설명했으며, 재료 (금속, 반도체 등)를 바탕으로 재료공학과를 설명"},{"q":"흥미가 있는 분야?","a":"반도체 쪽이라고 대답"},{"q":"반도체 밴드갭이 무엇인지","a":"밴드갭이란 다시 말해 띠간격이라고도 하며, 전도띠와 원자가띠 사이의 거리를 일컫습니다."},{"q":"반도체에서 가장 흔하게 사용하는 소재는?","a":"규소의 고체 상태는 암회색인데 이를 실리콘이라고 일컫습니다. 이 실리콘이 가장 흔하게 사용됩니다."},{"q":"그것을 어떻게 활용하는지?","a":"실리콘은 14족 원소이기 때문에 실리콘만으로는 전기가 잘 흐르지 않습니다. 따라서 13족 원소나 15족 원소 같은 것으로 도핑을 하여 전기가 더 잘 흐르게 만들어줍니다."},{"q":"반도체는 어디에 활용할 수 있는 것 같나?","a":"스위칭 특성을 바탕으로 전자기기 쪽을 대답함."},{"q":"5년 뒤 자신의 모습을 예상해보면? (10년 뒤도 질문하셨습니다.)","a":"반도체의 제품화 쪽 연구를 하고 있을 것 같다."},{"q":"탐구할동을 하면서 어려운 점은 없었고 그것을 어떠한 방식으로 해결하였는가?","a":"살균제품에 대해 2학년 때 공부하였는데 그람양성균과 그람음성균에 대해 효과차이가 나는 것에서 그 이유를 몰랐던 것이 이후 책을 통해 그람음성균과 양성균의 구조차이를 설명하며 이해하며 해결했다고 대답"},{"q":"방사성 동위원소를 공부한 이유와 탐구방향을 그쪽으로 잡은 이유는?","a":"어떤 것에 대해 궁금증이 생기면 탐구하는데 2학년 때 체르노빌 원전사고의 원인을 설명해주는 영상을 보았고, 그 당시 원자핵분열을 공부하였기 때문에 공부하고 싶어 그것을 계기로 탐구했다."},{"q":"방사성 동위원소에서 대표적으로 기억나는 사례는?","a":"연대측정법이 대표적인데 칼륨에도 동위원소가 존재하며 자연에서 많이 존재하지 않는 방사성 동위원소의 한 종류인 칼륨이 긴 시간에 걸쳐 붕괴하면서 아르곤과 칼슘으로 변화한다. 칼슘은 자연에 많이 존재하기 때문에 아르곤을 이용하여 나이를 측정할 수 있다.후배들을 위한 조언 많이 춥습니다. 특히 발이 시렵기 때문에 꼭 따뜻하게 입는 것을 추천합니다. 자소서에서 많이 물어본다고 해서 자소서도 많이 봤는데 생기부를 많이 물어보셨습니다. 생기부도 잘 챙겨보셔야 합니다. 2023 대입 면접후기"}],"result":"불합격","resultNote":"","src":"충청북도교육청 「2024 수시 대비 면접 후기집」","year":"2024학년도"},{"univ":"서울대학교","dept":"전기정보공학부","jeonhyeong":"학생부종합(지역균형)","method":"대기실에서 대기하다가 순서대로 면접실로 들어가 10분 동안 교수님과의 질의응답시간을 갖는다.","notes":"","qa":[{"q":"이 학과에 지원한 지원 동기가 무엇인가요?","a":"저는 어렸을 적부터 정전을 많이 경험했습니다. 그 때 전기의 안정적인 공급이 중요하다는 것을 깨달았으며 흥미가 생겼습니다. 충학교, 고등학교 때 다양한 활동을 하면서 신재생 에너지와 스마트그리드 기술에 흥미가 생겼고 우리나라의 좁은 지리적 한계를 극복할 수 있는 발전시설을 공부하여 연구해보고 싶어 본 학과에 지원하였습니다."},{"q":"좌우명이 무엇인가요?","a":"나의 행복을 다른 사람과 비교하지 말고 긍정적으로 살아가고자 ‘다른 사람과 나를 비교하지 말자’라는 좌우명을 가지고 있습니다."},{"q":"고등학교 생활 중 가장 도전적이었던 활동은 무엇이었나요?","a":"프로그래밍을 공부하는 친구와 함께 게임을 기획하고 컨트롤러까지 제작하는 활동이 있었는데 두 팀으로 나눠 활동하면서 진행도가 달라 서로 조율해나가는 과정이 있었습니다. 기술적으로는 컨트롤러의 버튼 인식에서 사람이 정확히 두 버튼을 동시에 누를 수 없다는 문제점을 해결하기 위해 두 버튼이 눌렸을 때 버튼이 눌린 시간 간격이 일정 시간 이하일 때 동시에 누른 것으로 인식하도록 만들어 해결했던 경험이 있습니다. 시험 기간에 더불어 프로그래밍과 회로 관련 지식이 없는 친구들과의 학습이 병행되었던 때였기에 가장 도전적인 활동이었다고 생각합니다."},{"q":"고등학교 생활 중 가장 어려웠던 과목은 무엇인가요?","a":"공동교육과정 중에서 회로 이론에 대해 배웠었는데 회로 해석법을 배웠을 때 처음 보는 회로들을 많이 경험하여 처음에는 어려움을 겪었습니다. 이를 극복하기 위해 배운 회로들을 활용하는 회로들을 찾아 스스로 해석해보고 회로를 구성해보면서 회로의 작동방식에 대한 논리적 이해를 키웠습니다."},{"q":"키르히호프 법칙을 설명해주실 수 있으신가요?","a":"키르히호프 제 1법칙의 경우 전류 법칙으로 한 접점에 대하여 들어온 전류와 나간 전류의 양이 같다는 것이며 제 2법칙의 경우 전압 법칙으로 모든 전압 강하의 합은 회로의 총 전원전압과 같다는 것입니다.후배들을 위한 조언 프로그래밍과 고급수학을 배워두면 면접 때 잘 활용할 수 있으며 심화된 내용의 질문은 많이 나오지 않으니 많은 내용을 암기하여 면접을 보는 것보다는 생기부 내용을 간단하게 파악하고 마음을 편하게 하는 것이 수월하게 말을 할 수 있는데 도움이 된다고 생각합니다. 2023 대입 면접후기"}],"result":"합격","resultNote":"최초합","src":"충청북도교육청 「2024 수시 대비 면접 후기집」","year":"2024학년도"},{"univ":"서울대학교","dept":"전기정보공학부","jeonhyeong":"학생부종합(기회균형특별Ⅰ시간 맞춰 대기실로 입실하여 앉아서 기다리고 있는다. 입실 완료 후 앞에서 신원확인과 함께 면접 번호를 부여한다. 이 때 면접 번호에 따라 면접 예상 시간과 퇴실 예상 시간을 확인할 수 있다.(앞에 큰 종이에 나와있으므로 언제든 확인할 수 있다. 이때까지는 전자기기를 사용할 수 있는 것 같으니 부모님께 말씀드려도 좋을 것 같다.) 기다리는 동안)","method":"전자기기를 제외한 다른 자료들을 볼 수 있다. 면접 시간 20분 정도 전 쯤에 각 2-3명 정도를 한번에 불러서 이동한다. 이때 가지고 온 짐은 모두 가지고 이동한다. 면접실 앞에서 기다리다가 이전 지원자의 면접이 끝날 즈음에 문 앞에 서 있다가 시간 되자마자 바로 문열고 들어간다. 들어가면 면접관 2분이 계시는데 1미터 정도 간격을 두고 면접자가 앉을 수 있는 의자가 있다.(책상은 없다.) 면접 1분 전에 밖에서 노크 한번 하고 면접이 끝나면 바로 문열리며 다음 면접자가 들어온다.(시간을 칼같이 지키니 노크 소리 들리면 답변 시간 조절하자.)서울대 안으로 들어가는 버스 노선이 2개가 있는데 자기 면접 보는 건물에 더 빨리 가는 노선 타는 것을 추천한다.면접 보는 건물 앞에 가면 학생회 선배들이 각 학과별로 나와서 응원해주고 있어서 감동적이었지만 부담스러울 수 있다. 들어가면 전형, 학과 별로 대강당 같은 대기실에서 대기한다. 필자는 기균 전기과였는데 지균 전기과하고 같은 대기실에서 대기했다. 2인용 책상이 인원수 만큼","notes":"있었는데 떨어져 앉지 않고 다른 지원자와 붙어서 대기했다. 책상마다 핫팩 물, 물티슈가 있었다. 8시 반 전까진 폰이나 패드 같은 거 다 쓸 수 있지만 그 시간 지나면 제출해야 함. 이후 면접번호를 부여받고 신분 확인을 하니 신분증하고 수험표 꼭 챙겨야 함. 면접번호마다 언제쯤 끝날 것 같다고 게시판에 써놓으므로 참고하여 준비하면 될 듯. 이후 면접 전까지 가지고 온 자료로 준비할 수 있음.(이건 어느 해는 아예 볼 수 없고 어느 해는 하나만 볼 수 있다고 하는 등 해마다 달라서 일단 다 챙겨가보는 게 좋을 듯.) 한번에 여러 명씩 진행했는데, 대기실에서 이동할 때 지균 전기전자는 6명, 기균 전기전자는 4명씩 이동했음. 앞에서 자기 면접 번호 호명하면 가방하고 짐 다 챙겨서 면접실 앞으로 이동하고 그전 면접자가 나올 때까지 대기. 면접실 앞에 패딩이나 가방 다 내려놓고 면접장에 들어갈 수 있음. 들어가면 앉아서 하면 되는데 내 쪽에는 책상이 없었음. 연습할 때 책상이 없는 경우, 있는 경우 모두 대비하자. 말 하다가 1분 남았을 때 밖에서 한 번 노크하고 시간 되면 바로 문열림. 끝나면 자기가 이학교 선배라면서 자기 동아리(주로 기독교 동아리) 들어오라 하면서 개인정보(이름, 전번, 학과 등등등)를 달라 할 수 있는데 동아리는 대학 와서도 고민할 수 있으니 왠만하면 주지 않는게 좋아 보인다.","qa":[{"q":"면접관 1: (면접 번호 확인하고) 네, 그러면 시작하도록 하겠습니다. 먼저 지원동기 한번 말해보세요.","a":"저는 서울대학교 전기정보공학부만의 교과 커리큘럼과 다양한 반도체 제작 장비가 있어 지원하게 되었습니다. 교과과정의 경우, 전기전자 관련 학과임에도 컴퓨터공학 트랙이 강화되어 있어 뉴로모픽 컴퓨팅 시스템을 하드웨어적으로 또 소프트웨어적으로 모두 다뤄보고 싶은 저로서는 서울대학교 전기정보공학부가 가장 적합한 학과였다고 생각하여 지원하였습니다. 또 서울대학교에 있는 반도체공동연구소에는 반도체 제작 설비가 있는데 이를 학생들도 자유롭게 이용할 수 있어 지리적으로 가깝다는 측면에서 이점으로 다가왔습니다."},{"q":"면접관 2: 생기부를 보니 고급수학 같은 어려운 과목을 수강했는데, 왜 이런 어려운 과목을 수강했고 무엇이 어려웠는지, 또 이를 극복한 것은 무엇인지 한번 자유롭게 말해보세요.","a":"왜 고급수학을 들었는지 계기에 대한 질문으로 이해했는데, 혹시 제가 이해한게 맞을까요?"},{"q":"면접관 2: 네 맞습니다.","a":"확률과 통계 포스터 제작 활동을 하면서 추천 알고리즘의 원리를 탐색하게 되었고, 초기 알고리즘의 원리가 행렬 인수분해라는 것 알게 되었다. 그래서 행렬이 무엇이고 어떻게 사용되는 것인지 궁금했다. 또 수학의 날 부스 운영 활동에서 정사영을 주제로 활동했는데 공간상에서의 일반화된 경우에서 정사영하려면 행렬을 알아야 한다는 것을 알게 되었다. 그래서 행렬과 벡터를 기하적으로 다루는 고급수학을 수강하고자 했습니다. (이 때 약간 당황) 고급수학을 수강하면서 아무래도 내용 자체가 어렵고 또 기존의 문제풀이 위주 과목이 아니라 논리적으로 이를 설명하다보니 이를 이해하는데 어려움을 겪었습니다. 하지만 논리는 논리적으로 따라가면 된다는 생각을 가지고 있어서 이해에 어려움이 있더라도 포기하지 않고 따라간 결과 어려움을 해결할 수 있었습니다."},{"q":"면접관 1: 그 고급수학이라는 과목에서 행렬이나 뭐 이런걸 기하적으로 다루나보죠?","a":"네 그렇습니다."},{"q":"면접관 1: 어떤 걸 다루나요?","a":"행렬의 계산, 행렬의 역행렬과 행렬식, 벡터의 외적, 내적, 그리고 그래프를 배웁니다."},{"q":"면접관 1: 그래프?","a":"(우리가 아는 그래프랑은 다른 개념) 아, 점과 점 사이를 이은 직선 간의 관계를 의미하는데, 점들의 위치가 바뀌더라도 점과 점 사이가 이어진 관계, 예를 들면 각 점마다 연결된 점들의 수가 같은 경우 점들의 위치는 다르지만 같은 그래프라고 합니다. 제가 말한 그래프는 여기서의 그래프입니다."},{"q":"면접관 1: 고등학교 3년간 환경부장을 역임했다고 했는데, 지역 환경 지도 제작 과정이 무엇이고 어떤 점이 어려웠고 뭐가 또 힘들었는지 등등 해서 한 번 말해보세요.","a":"우선 제가 환경부 활동을 한 목적을 설명해야할 것 같습니다. 제가 3년간 환경부를 진행한 주요한 목적은 학생들이 환경을 더욱 친숙하게 여기고 환경에 관심을 갖게 하는 것이었습니다. 이 활동도 그러한 목적의 일환으로 진행했습니다. 제가 집에 가면서 우리 지역 근처에 천연가스 발전소가 지어진다는 것을 알게 되었습니다. 천연가스 발전소가 지어진다는 것을 알게 되면서 제가 그동안 우리 주변 지역의 환경에서는 관심이 없었다는 것을 깨달았고 그래서 우리 지역의 환경 실태가 어떠한지 알리고자 사업을 추진했습니다. 부원들에게 우리 지역을 구획별로 나누어 각각의 구획에서 환경 오염이 유발될만한 요인이 무엇인지 조사하게 하였습니다. 제가 여기서 가장 중요하다고 여겼으면서 힘들었던 점은 저희가 제작하는 환경 지도가 학생들에게 안좋은 인식을 주지 않도록 노력했던 것이었습니다. 제가 이 활동을 기획한 계기가 천연가스 발전소가 지어진다는 것을 알게되면서 였는데, 발전소라는 것이 유해물질이 배출될 수 있다는 점에서 부정적으로 비춰지지만 또 그 시설을 관리하시는 분들이 적법한 절차를 거쳐 적절하게 관리하고 있을 수 있는데 그 시설과 그 분들이 환경 보전을 위해 노력하지 않는 것으로 비춰질까봐 우려스러웠습니다. 그래서 최대한 공신력 있는 자료, 뭐 믿을만한 기사나 지자체에서 발표한 연구 결과만을 참고하라 했고, 지도를 검수하는 과정에서도 이 부분에 특히 신경을 썼습니다. 그래서 아무래도 이 부분이 어려웠습니다."},{"q":"면접관 2: 플랑크 상수 측정 실험을 한 것 같은데, 왜 했고, 그 원리는 무엇이며, 어떤 과정을 거쳤으며, 어려운 점은 무엇이고 뭐 이런 것들에 대해서 한번 설명해보세요.","a":"이 실험은 교과서에 파워 서플라이를 이용하여 플랑크 상수를 측정하는 실험이 있어 한번 해보고 싶어 진행하게 되었습니다. (밖에서 노크 한번 함.) 전력이 공급되면 전자가 LED의 띠틈만큼 전이하면서 그 만큼의 에너지를 방출하는데 이를......(생략된 부분이 많은데 원리를 설명하는 부분이 길었음.)(문 열리면서 다음 사람 들어옴.)면접관 1,2 : 수고하셨습니다.수고하셨습니다.(퇴장 후 짐 챙겨서 귀가.)후배들을 위한 조언 면접 준비할 때 생기부 정리 같은 거 하기 전에 자기가 지원한 학교와 비슷한 수준의 학교의 면접 문항을 참고해보세요. 저는 서울대, 포항공대, 과학기술원의 모든 학과, 모든 전형의 면접 후기를 꼼꼼하게 읽어봤는데(서울대는 여러번) 읽어보면 일반적인 유형의 문항뿐 아니라 돌발 질문 같은 것도 어느정도 예상할 수 있어서 나중에 면접 문항으로 만들어질만한 포인트가 보입니다. 자주 나오는 유형별들이 어떤 건지 확인해보세요. 생기부는 3학년부터 주요 ‘교과’의 주요 ‘활동’ 위주로 정리하면 될 듯 합니다.그리고 면접 잘 보고 싶으면 평소에 열심히 사셔야 합니다. 대충해놓고 나중에 면접 준비할 때 대비하겠다는 생각하지 마세요. 생각보다 수능 끝나고 면접 준비 열심히 안합니다. 그러니까 매 활동에 최선을 다하시고 뭘 공부했으면 확실하게 정리해두고, 활동 동기, 활동 과정, 본인의 역할, 활동하며 느끼고 깨달은 점 위주로 보고서를 정리해두면 나중에 면접 준비할 때 정말 정말 큰 도움이 되니 열심히 하세요!!그리고 면접장 들어가기 전까지는 엄청 긴장되는데 막상 들어가서 기다리고 있으면 긴장도 풀리고 같이 면접 보러 온 친구들과 말은 안하지만 내적 친밀감도 생기고 하니 너무 걱정하지 마시고 최선을 다해서 좋은 결과 있기를 바랍니다. 파이팅!!2023 대입 면접후기"}],"result":"합격","resultNote":"","src":"충청북도교육청 「2024 수시 대비 면접 후기집」","year":"2024학년도"},{"univ":"서울대학교","dept":"정치외교학부","jeonhyeong":"학생부종합(지역균형-입장하면 대기실에서 대기하며 전자기기 수거 및 신원 확인 이루어짐. 가번호를 배부하는데 이 번호 순서대로 면접 진행(접수번호, 수험번호와 다름). 대기실에서는 가지고 온 자료를 자유롭게 열람할 수 있고, 화장실도 갈 수 있음.-이후 시간이 되면 조별로 1, 2번째 순서 학생은 면접실 앞으로 올라가서 대기함. 첫 번째 순서 학생이 면접실에 들어가면 세 번째 학생이 대기실에서 면접실 앞으로 가게 됨. 이런 식으로 쭉 진행됨. 복도)","method":"에 마련된 책상에서 대기하며, 추울 수 있으니 핫팩 등을 챙겨가는 것을 추천함. 이때부터 자료 열람 불가능, 화장실도 이동 전에 모두 갈 것.-노크하고 들어가면 교수님들이 바로 질문을 진행하시고, 1분 전에 밖에서 노크해줌. 교수님이 노트북에 시계를 띄우고 계시는데, (보이게끔 해놓은 것인지, 보이는 것을 모르는 것인지는 확실하지 않지만) 답변하면서 시간을 확인할 수 있었음.-시간이 다 되면 퇴실하고, 전자기기와 면접 확인서(+필요한 경우 면접 확인서를 발급받을 수 있음. 대기실에서 발급을 희망하는지 조사함.)를 수령한 후 귀가함.","notes":"자세한 사항은 달라질 수 있으니 추후 학교에서 안내하는 바에 충실히 따를 것.","qa":[{"q":"(남자 면접관)(내용 질문) 숙의민주주의에 관해 탐구를 한 바 있는데, 숙의가 이루어지는 형태는 무엇이며 공론의 장에서 사회적 소수자의 참여를 어떻게 증진할 수 있는가?","a":"숙의민주주의의 실현 형태를 정치 축제의 형식으로 제시하였으며, 3학년 때 탐구한 북유럽의 사례와 우리나라의 차이를 설명한 후 초기 단계에서는 지역 주민과 정치인이 지역 관련 사안을 협의하는 형태로 진행되며, 이후 여러 지역에서 정치 축제가 활성화되면 보다 거국적인 사안(기후 변화 대응 등)을 다루는 축제로 나아갈 수 있을 것으로 봄.사회적 소수자도 숙의에 참여할 수 있는 방안에 관해서는 먼저 법적 규제의 도입이 표현의 자유를 침해할 수 있는 가능성이 있음을 밝히고, 심화영어Ⅰ 시간에 혐오 표현에 대한 형성적 규제(시민사회에서 사전적, 적극적으로 혐오에 대한 대항 표현을 조직하는 방식)를 제안했음을 말함. 공론장에서 혐오 표현과 같이 불관용을 조장하는 태도가 존재한다면 숙의 과정에서 지장을 초래할 수 있으며 소수자의 참여를 제한할 수 있기 때문임. 또한, 장애인과 같은 소수자의 물리적 접근성을 강화할 수 있는 사전 설비 장치 역시 도입될 수 있음을 말함."},{"q":"(여자 면접관)(추가 질문-내용 서류에 있음) 숙의에 참여한 사람들의 의견이 합의되지 않고, 극화되는 경우는 어떻게 할 것인가?","a":"2학년 확률과 통계 시간에 관련 탐구를 한 바를 간단히 언급함. 이후 숙의 과정에서 참여자들에게 어떠한 조정 작용도 하지 않는다면 의견이 극화될 수 있지만, 퍼실리테이터(조정자)를 투입하여 숙의의 장이 사적 이익만을 추구하는 것이 아닌, 공적 논의의 장이며 공익을 추구해야 한다는 것을 주지시킨다면 극화를 방지할 수 있음."},{"q":"(남자 면접관)(추가 질문-내용 서류에 없음) 답변 내용을 보니 사람들이 모인 것만으로는 정상적인 숙의가 진행되기 어렵다는 것 같은데, 극화를 예방하기 위한 조정자가 숙의 과정을 왜곡시킬 가능성도 있지 않는가?","a":"보이텔스바흐 합의와 민주시민교육이라는 책을 읽은 적이 있는데, 거기서 민주시민교육, 즉 정치교육을 위한 세 가지 원칙을 제시함. (이후 세 가지 원칙에 대해 설명하려 했으나 기억이 나지 않았고, 면접관님들께 긴장해서 기억이 잘 나지 못한다고 양해 말씀 구한 다음 강압 금지 원칙만 말함) 조정자가 위와 같은 합의된 정치 교육의 원칙에 따른다면 조정자로 인해 숙의가 왜곡되는 것을 방지할 수 있으며, 또한 숙의의 장은 사람들이 참여함으로써 정치교육의 일환으로 작용할 수 있다고 말함."},{"q":"(여자 면접관)(내용 질문) 정치사상에 관심이 많고, 존 스튜어트 밀의 자유에 관해서도 탐구하였는데, 그가 주장한 자유란 무엇인가?","a":"존 스튜어트 밀에 대해 관심을 가지게 된 계기인 1학년 통합사회 시간의 자유주의-공동체주의 토론 활동에 대해 부연함. 원래 공동체주의의 입장을 가지게 되었으나, 자유주의 입장으로 바꿔 토론하며 롤스와 밀의 차이점을 알게 되었고 자유주의 정치사상에 대한 흥미를 가지게 되었다고 밝힘. 밀에 대해 일종의 사랑과 같은 감정을 가졌던 것 같다고 말씀드리니 살짝 웃으심. 그가 주장한 다수의 횡포의 문제점과 해악 금지의 원칙을 말하고, 개별성 개념을 중심으로 밀의 자유에 관해 설명하며 오늘날 여전히 여론의 영향이 거센 시점에서 그가 개별성을 중시했다는 점은 의의가 있다고 말함."},{"q":"(여자 면접관)(추가 질문-내용 서류에 없음) 본인은 자유주의와 공화주의 중 어떠한 견해를 더 강하게 가지고 있는가?(1학년 때 원래 공동체주의 입장이었다는 답변을 듣고 이와 같은 꼬리 질문을 한 것이 아닐까 추측함. 공화주의 이론에 대한 독서나 탐구는 서류에 없었음.)","a":"아직 본인의 사유체계가 자유주의 또는 공화주의 중 하나로 완전히 정립되었다고 보기에는 어려우며, 자유주의에서 강조하는 개인의 자유, 특히 밀의 자유론에서 강조하는 개별성 역시 여론의 압박이 심한 현대 사회에서 시사하는 바가 있다고 생각함. 또한, 에리히 프롬이 자유로부터의 도피에서 주장했듯 오늘날에는 소극적인 자유뿐만 아니라 적극적 자유 역시 고려해야 한다고 말함. 또한, 공화주의에 관해서는 지금까지 강조했던 숙의민주주의에서 필수적인 요소인 시민성이, 공화주의에서 강조하는 시민적 덕성과 유사한 측면이 있다고 답함. 두 입장 모두 견지할 필요가 있다고 주장함.5번 답변이 끝날 즈음 1분이 남았음을 알리는 노크가 들렸고, 이에 면접관님들께서 시간이 다 되었으니 나가도 좋겠다고 하심. 당황스러웠지만 1분 남은 것으로 알고 있다고 말씀드리고, 이에 면접관님들께서 추가적으로 더 하고 싶은 말 있다면 해도 된다고 말씀해주셨음."},{"q":"(남자 면접관)(일반적인 질문) 추가적으로 더 하고 싶은 말이 있나요?","a":"밀은 모든 주장에 어느 정도의 진리가 있다고 하였고, 자유 토론을 통해 주장에 담긴 진리를 명확히 하는 것을 강조했음을 말함. 이처럼 본인 역시 앞으로 서울대학교에서 토론하고 논변하며 본인의 주장에 담긴 진리를 더 명징하게 하고 싶다고 말씀드리며 마침.후배들을 위한 조언 전반적으로 면접관님 두 분 모두 온화하게 대우해주셨으며, 질문하실 때 면접 대상자가 질문을 이해할 수 있도록 부연해주시는 경향이 있었음. 면접관님과 거리가 좀 있었지만(2-3m 남짓), 면접실이 목소리가 줄어드는 구조가 아니라 나름 잘 들리는 목소리로 답변할 수 있었음.긴장을 좀 하긴 했지만, 다행히 알고 있는 범주 내에서 질문이 나와서 큰 떨림 없이 답변할 수 있었음.학교에서 선생님들과 함께 면접 준비한 것이 도움이 많이 되었고, 비록 본인의 경우는 자소서 1번만을 물어보았지만 만약의 가능성에 대비해 다른 내용 역시 챙겨두는 것을 추천함.2023 대입 면접후기"}],"result":"합격","resultNote":"","src":"충청북도교육청 「2024 수시 대비 면접 후기집」","year":"2024학년도"},{"univ":"서울대학교","dept":"국어교육과","jeonhyeong":"학생부종합(지역균형)","method":"면접시간 약 10분 (끝나기 1분 전 노크해주심)면접 위원 수: 2명, 면접 학생 수: 1명전체 대기실 (가번호 스티커 붙이고 대기) → 개인 대기실 → 면접실입실시간 끝나기 전까지는 자료 볼 수 있음.","notes":"주민등록증(신분증), 수험표 꼭 챙기기!입실시간 끝나면 가방이랑 겉옷도 모두 내야 함. (면접 복장 따뜻하게 입기. 마실 물도 가져가면 좋을 것 같다!!)","qa":[{"q":"국어교육과에 왜 지원했나요?","a":"저는 이야기를 좋아하고, 말과 글을 통해 사람들의 삶을 이해할 수 있다는 생각을 가지고 있습니다. 그렇기 때문에 주변의 이야기에 항상 관심을 기울였고, 그 과정에서 모든 사람이 말과 글을 통해 자신을 표현할 수 있도록 돕고 싶다는 목표가 생겼습니다. 특히 배움을 시작하는 학생들이 국어를 배워 자신을 표현할 수 있도록 돕고 싶어 국어교육과에 지원했습니다."},{"q":"자소서 내용 중에 언어에는 우열이 없다라는 작가의 의견에 동의했다고 했는데 무슨 의미인가요?","a":"이 책에서는 영어와 같이 어휘와 문법이 복잡한 선진국의 언어는 우월하고, 상대적으로 그렇지 않은 소수민족의 언어가 열등하다는 인식이 잘못됐다고 이야기합니다. 표현해야 하는 대상이 많은 문화에서는 그에 따라 언어도 복잡하게 발전하지만, 굳이 표현할 필요가 없는 문화에서는 단순한 언어를 유지합니다. 따라서 복잡성만으로 언어의 우열을 가릴 수 없다고 생각했기 때문에 작가의 의견에 동의했습니다."},{"q":"그럼 영어랑 한글이 동등하다는 의미인데 (생기부 중 한글의 우수성 탐구와 관련해서) 다른 언어와 구별되는 한글의 특성은 뭐죠?","a":"표현하고자 하는 바를 전달하고 의사소통할 수 있다는 점에서는 영어와 한글이 동등합니다. 하지만 한글은 유일하게 창제자가 분명한 글자이고, 음양오행의 원리를 반영하고 있으며 자연의 모습을 추상화한 글자라는 점에서 예술적 특성이 있습니다. 이런 예술적 측면에서 한글과 다른 언어가 구별된다고 생각합니다."},{"q":"학생자치신문 활동을 오래 했는데 힘들었던 점은?","a":"1년에 4번 신문을 발간했기 때문에 학교 시험 기간과 겹쳐 처음에는 공부와 기사 쓰기를 병행하기가 힘들었습니다. 하지만 신문에 담기 위해 사회나 과학 등 다양한 분야의 자료를 접하고 글로 쓰는 과정이 공부에도 도움이 된다고 생각하며 공부와 기사 쓰는 시간을 적절히 조율하려고 노력했습니다."},{"q":"미디어 리터러시에 관심이 많은 것 같은데, 국어교육과 미디어 문해력이 어떤 관련이 있나요?","a":"미디어 문해력은 비판적 사고 능력과 창의력을 기반으로 합니다. 국어교육에서 읽기와 쓰기 교육을 통해 이를 함양할 수 있다고 생각합니다. 특히 글을 읽으며 이어질 내용을 추론하고 읽은 내용을 종합하는 능력은 매체를 분석하고 이해하는 데에도 필요합니다. 이런 점에서 국어교육을 통해 미디어 문해력에 포함되는 능력을 기를 수 있습니다."},{"q":"그럼 문학과 문해력은 어떤 관련이 있다고 생각하나요?","a":"(정확히 기억 안남. 문학 작품을 통해 사람들의 삶과 이야기를 접할 수 있는데, 문학을 공부하며 글을 쓴 사람의 생각을 이해하고 소통하는 능력인 문해력을 기를 수 있다는 내용으로 답변했습니다.)"},{"q":"언어적인 측면에서는? (이 질문은 답변 방향성에 대해 힌트를 주신 것 같습니다)","a":"문학 작품은 비유와 같은 함축적인 표현을 활용해 이야기를 전달하는 경우가 많아 숨겨진 의미를 추론하고 다음에 이어질 내용을 예측하며 읽어야 합니다. 문해력은 비판적, 종합적 사고력을 포함하기 때문에 문학을 읽는 과정이 문해력 향상과도 관련 있다고 생각합니다."},{"q":"(생기부에) 지속가능교육에 관심을 가지고 있다고 나와있는데, 지속가능한 사회를 위해서 국어교육은 어떤 방향을 가질 수 있을까요?","a":"지속가능한 사회를 위해서는 모두가 자신의 의견을 표현하고 결정에 참여할 수 있어야 합니다. 국어교육은 학생들이 국어를 배워 말과 글로 의견을 표현하고, 상대의 의견을 존중하며 의사소통할 수 있도록 교육하는 방향으로 나아가야 한다고 생각합니다."},{"q":"지속가능한 사회는 어떤 사회인가요?","a":"모든 구성원이 의사결정에 참여하여 현재의 기후 위기나, 경제적 불평등, 정보 격차와 같은 전 지구적인 문제를 해결해 갈 수 있는 사회라고 생각합니다."},{"q":"(자소서 내용) 읽기 부진의 원인은 뭐라고 생각했나요, 이를 해결하기 위해서는 어떻게 해야 한다고 생각했나요?","a":"자료 조사를 통해 읽기 부진 학생들의 공통적인 원인은 읽기에 실패한 경험이 쌓여 읽기에 흥미가 떨어지기 때문임을 알았습니다. 이를 해결하기 위해 학생의 읽기 수준에 맞는 적절한 읽기 과제를 제시하여 성취감을 느끼게 해 주는 방법을 찾아보았고, 상담을 통해 학생들의 수준을 파악하고 수준에 맞는 그림책을 이용해 개별 지도하는 방안이 필요하다고 생각했습니다."},{"q":"(생기부 질문) 노년층 디지털 문맹의 원인이 무엇이었나요?","a":"대부분의 디지털 기기가 시력이나 청력이 좋지 않은 노년층의 신체적 특징을 반영하지 않고 빠른 화면 전환이나 작은 글씨로 서비스를 제공한다는 점이 주요한 원인이었습니다. 또 이러한 디지털 기기에 거부감을 가진 노인분들이 디지털 기기 활용법 교육 등에 참여하지 않으려고 하시는 문제도 있었습니다.후배들을 위한 조언 면접 볼 당시에는 질문을 조금밖에 안 하셨다고 생각했는데 나와서 다시 적어보니까 생각보다 많았습니다. 그만큼 10분이 빨리 흘러가니까 너무 긴장하지 않아도 됩니다. 모든 말이 기억나진 않아서 실제 했던 것보다 짧게 썼는데, 실전에서는 질문에 대한 답을 한 문장으로 얘기하고 두세 문장 정도 설명을 덧붙이면 적당할 것 같습니다.기억 안나는 활동, 중요하지 않아 보이는 활동도 꼭 다시 확인하고 가세요! 그리고 활동별로 키워드를 준비해두고 당황스러운 질문이 나오더라도 키워드를 중심으로 답변을 구성하는 연습을 많이 해보시길 추천합니다. 가장 중요한 것은 자신감입니다. 지금까지 열심히 해 왔던 활동을 발표한다는 생각으로 자신 있게 말하세요! 파이팅!2023 대입 면접후기"}],"result":"합격","resultNote":"","src":"충청북도교육청 「2024 수시 대비 면접 후기집」","year":"2024학년도"},{"univ":"서울대학교","dept":"독어교육과","jeonhyeong":"학생부종합(지역균형1. 면접 고사장으로 들어가면 칠판에 안내사항이 적혀있음.)","method":"2. 입실 시간이 되면, 전자기기는 본인 가방에 넣어야함.3. 번호를 부르면 모든 짐을 챙겨서 이동하고 면접을 시작함.4. 10분 동안 진행되고, 1분 남았을 때 노크 소리가 들림.5. 면접이 끝나면 안내자를 따라서 밖으로 나감.","notes":"","qa":[{"q":"전공 기초 독일어 시간에 독일의 교육방식을 독일 역사교육의 특징, 독일 교과서를 통해 본 역사교육, 통일 이후 독일 역사교육의 방침 그리고 독일과 주변 나라의 역사 공동연구 등의 내용을 조사한 내용을 자세히 설명해주고 느낀 점도 말해보세요.","a":"제2차 세계대전 전후의 독일의 역사를 독일에서 교육하는 방식은 자신들의 과오에 대한 반성이 대부분을 이루었습니다. 독일에서는 우리나라처럼 교육부에서 지정한 교과서를 통해 수업하는 것이 아니라, 학교나 교사가 자율적으로 선택한 교과서를 통해 가르치는 것으로 알고 있습니다. 이러한 독일의 교과서를 몇 가지 찾아본 결과, 모두 참혹한 실태를 숨기려 하지 않고 자세하게 당시의 상황이 기록되어 있었습니다. 또한 독일은 유럽 중심부에 있어서 나치즘 시기에 프랑스, 폴란드, 체코, 벨기에 등 피해를 끼친 나라가 많을텐데, 특히 프랑스와의 공동 역사 연구와 교과서 편찬을 통해 독일이 반성한다는 것을 깊이 알게 되었습니다. 우리나라도 제국주의 시대에 피해국이었던 만큼 일본도 독일을 본받고 우리나라와도 외교 관계 개선이 이루어졌으면 좋겠다고 생각했습니다."},{"q":"‘AI 교육혁명’을 읽었다고 나와있는데 이 책의 내용이랑 책을 읽고 느낀 점을 말해보세요.","a":"4차 산업혁명 시대에 들어서고, 코로나19의 확산으로 원격수업이 본격화되면서 새롭게 등장한 디지털 격차 문제에 관한 내용입니다. 우리나라에서도 새 교육 과정에 디지털 소양이 새로 추가된 것으로 알고 있는데 전세계적으로 디지털 교육에 관한 관심이 높아진 만큼 디지털 기기의 부족 등의 문제로 원격수업이 제대로 실시되지 못하는 개발도상국이 선진국과의 격차가 더욱 벌어지고 새로운 분열을 겪는다는 것입니다. 이 책을 읽고 저는 교사가 되어서 적어도 우리 반에서만큼은 교육 격차 문제가 발생하지 않도록 해야겠다는 생각을 하게 되었습니다. 원격 수업이 진행될 때, 수업을 제대로 이해하기 힘들어하는 학생들을 위해 각자의 성향에 맞는 개별화 수업을 진행해야겠다고 생각했습니다."},{"q":"‘동아시아에서 자유주의란 무엇인가?’를 읽었다고 나와있는데 이 책의 내용이랑 책을 읽고 느낀 점을 말해보세요.","a":"이 책은 동아시아, 특히 한국과 중국, 일본에서 왕조에서 근대화를 이루어 정치 체계가 변하는 시기를 다룬 책입니다. 청나라에서 중화민국으로, 막부 정권에서 메이지 유신으로, 우리나라는 왕조가 유지되긴 했지만 여러 근대 단체들이 만들어진 상황에서 그동안 한 나라의 백성으로서 통치받아야할 존재라고 여겨졌던 사람들이, 이제는 나라의 주인의식을 가진 존재로 성장해나가면서 사고방식의 변화가 어떠했는지 서술한 책입니다. 이 책을 읽고 자유주의의 가치에 대해 깨달았습니다. 우리나라의 가치인 자유주의와 민주주주의에 대한 교육을 실시하여 보다 이러한 가치들의 소중함을 일깨워야한다고 생각했습니다.후배들을 위한 조언 실제로 가보면 선배님들도 앞에 서 있고 응원해줘서 덜 떨렸고,면접 분위기도 압박 면접이 아니라 편안한 분위기였으니 걱정하지 마라~2023 대입 면접후기"}],"result":"불합격","resultNote":"","src":"충청북도교육청 「2024 수시 대비 면접 후기집」","year":"2024학년도"},{"univ":"서울대학교","dept":"윤리교육과","jeonhyeong":"학생부종합(지역균형오전/오후 분리 있음 (학과별 차이, 본인은 오전))","method":"8시 20분까지 입실 → 본인확인 후 면접번호 부착 → 소지품(전부) 격리 → 대기 → 방역(라텍스 장갑 착용, 페이스실드는 자율) → 밖에서 대기 → 10분 내외로 대면 면접 → 소지품 갖고 귀가","notes":"전자기기 포함 모든 소지품을 교실 뒤에 둬야 하기에 가져온 자료 같은 것은 볼 수 없었음, 미리 도착해서 보고 있을 순 있음.","qa":[{"q":"학과장: 아침밥은 먹고 왔나요?","a":"네, 먹고 왔습니다."},{"q":"학과장: 좋아요, 질문하겠습니다.","a":""},{"q":"학과장: (자소서 보면) 미적분 듣고 수학과 윤리가 논리적이라서 닮았다고 했는데 그렇게 따지면 모든 학문이 다 논리적인거 아니에요?","a":"(당황) 그럼에도 수학을 굳이 이야기한 것은, 수학에서는 그, 선행 과목에서의 모든 지식을 종합시켜나가면서 문제를 풀어내기 때문에 그러한 종합성은 수학에서만 찾을 수 있고, 어, 그런 점에서 굳이 수학을 이야기했습니다."},{"q":"학과장: 다른 학문은 안 그런가?","a":"적어도 고등학교 교육과정에서는 그러한 윤리와 같은 논리성을 체험할 수 있는 가장 가까운 과목이 수학이고,,,그러니까 고등학교 교육과정 내에서 가장 윤리와 닮은 과목이 수학이라고 생각 했습니다."},{"q":"학과장: (혼잣말하듯이)그래도 수학 어차피 필수 과목 아니야?..","a":"하하.."},{"q":"입학사정관: (학과장에게) 저 질문 하나만..","a":""},{"q":"학과장: 예, 하세요.","a":""},{"q":"입학사정관: 1학년 진로 보면, 사회교사와 윤리교사를 둘 다 지망하다 윤리교사로 정했다고 했는데, 왜 사회교사는 안 하기로 한 건가요?","a":"네, 사회과목도 지망했던 것은, 일반사회 교과에서 다루는 기능론, 갈등론의 문제와 불평등과 차별의 문제를 다루는 것 또한 매우 재미있다고 생각했기 때문이었는데, 저는 이러한 현실의 문제를 윤리학에서도 잘 다룰 수 있다고 생각하여 윤리교사가 되기로 하였습니다. (잠시 정적)"},{"q":"학과장 : 윤리가 논리적이라 그랬는데... 윤사 들었죠? 흄의 철학은 논리적이에요? 흄이 어디가 논리적이라는 거에요?","a":"네에,,(멘붕) 흄이 정감 윤리를 주장하는데.."},{"q":"학과장: 예, 흄이 정감 윤리를 주장했잖아요. 이건 논리적이라고 할 수 있어요?","a":"흄의 정감 윤리를 보면.., 흄이 그 공감에서, 그 연민, 아닌데,.. 동정심은 각 개인에게서 어느정도 보편적이기에 이를 바탕으로 하는 윤리 또한 어느정도의 보편성을 갖출 수 있다고 하였잖아요."},{"q":"학과장: 그래요?","a":"네, 이 안에 논리성이 있지 않을까요?.. 그러니까.."},{"q":"학과장: (더 들을 필요 없다는 듯이) 알겠어요. 그렇게 해서 논리적이라는 거죠?","a":"네. (학과장님이 종이를 훑어 보심)"},{"q":"학과장: 윤사 세특 보면.. 별명이 윤리철학 부교수? 였는데 왜 정교수는 아니에요?입학사정관: (웃음)","a":"하하.. 선생님이 정말 유쾌하신 분이라..(말 끊김)"},{"q":"학과장: 그건 됐고, 여기서 맹자 읽고 뭔가 이해하려 했다는데, 뭘 했다는 건지 내가 이해가 잘 안돼, 맹자를 읽고 여기서 뭐한거에요?","a":"맹자의 해설본을 읽고, 인상깊었던 내용에 관해 글을 썼습니다."},{"q":"학과장: 그러면 인상깊었던 것이 뭐였어요?","a":"저는 맹자의 집의와 호연지기 개념을 제일 인상깊은 것으로 정했습니다."},{"q":"학과장: 맹자 철학은 논리적이라고 할 수 있어요? 그 집의랑 호연지기가 어떻게 논리적이에요?","a":"맹자도 결국은, 인간이 모두 도덕적 인간이 될 수 있는 가능성이 있다는 성선설을 기본적인 전제로 해서.. 그, 집의라는, 도덕적 실천 경험을 반복하여 호연지기를 형성해, 집의에서 호연지기로 나가는 논리를 갖추고 있는 것 같습니다.."},{"q":"학과장: 호연지기는 왜 나왔죠? 그 맥락에서 호연지기가 어떻게 나와요?","a":"맹자는, 인간이 누구나 양지가 있어 도덕적인 것을 알 수 있지만, 이것이 욕망에 의해 가로막혀 실천하는 데 실패한다고 했습니다. 이 과정에서 도덕적인 행동으로 나아가기 위해서는, 집의라는 도덕적 실천 경험을 반복적으로 쌓는 과정으로, 도덕적 용기, 기개인, 욕망을 이겨내고 도덕을 실천할 수 있는 용기인 호연지기를 형성해 도덕적인 인간이 된다고 말했기 때문입니다."},{"q":"학과장: 그래요?","a":"네."},{"q":"학과장: 좋아요, (입학사정관에게) 선생님, 질문 하세요.","a":""},{"q":"입학사정관 : 네, 저기, 윤리교사는 정확히 언제부터 지망하게 되었어요?","a":"고등학교 1학년부터였습니다."},{"q":"입학사정관: 네, 그러면 다른 대학도 다 사대나 교대 위주로 썼죠? 대학 이름은 말하지 않아도 됩니다.","a":"네, 저는 사대 위주로 거의 썼습니다."},{"q":"학과장: (흥미를 보이며) 교대는 안 썼어요?","a":"네, 안 썼습니다."},{"q":"학과장: 그래요.","a":""},{"q":"입학사정관: 윤리교사는 왜 지망했어요?","a":"네, 중고등학교를 다니면서, 많은 비도덕 행위를 보았습니다. 그중에서도 큰 영향을 준 것은, 중학교 때 일이었는데, 학교에서 불미스러운 일이 있었습니다. 성범죄에 관련한 것이었는데.., 그 사건을 보면서 생각했습니다. 인간이 어떻게 행동하는 것이 바람직한 지, 인간의 바람직한 행동 원리는 무엇인지를 생각했고, 이것이 고등학교에 와서 윤리임을 알게 되었고, 윤리에 관심을 가지게 되었습니다. 그리고, 모든 사람들이 자신만의 윤리를 갖고 살게 하기 위해서는 윤리교육의 역할이 핵심적임을 생각하였기에, 이를 바탕으로 선한 영향력을 주는 윤리 교사가 되기로 결정했습니다."},{"q":"학과장: (고전과 윤리 세특을 보며 흥미롭다는 듯이)오, 금강경이 있네, 금강경 읽었어요?","a":"네, 교과서에서 발췌글을 읽었습니다."},{"q":"학과장 : 그렇다라.., 혹시 금강경에서 가장 인상깊은 구절이 뭐였어요?","a":"네! 금강경에서 가장 인상깊었던 구절은!(불교 사상을 다시 절대적 진리로 받아들이게 되면 다시 불교 사상에 집착하는 것이므로 집착에서 벗어나지 못한다는 구절을 이야기하려 함)(문 밖에서 노크 소리 후 문 열림)조교 : 시간이 다...입학사정관: 아, 시간이 다 되었네요. 어쩔 수 없네, 수고했어요.학과장: 수고했어요.나: 네! 감사합니다!후배들을 위한 조언 서울대학교는 아무래도 학자를 뽑는다는 느낌이 강하게 들었습니다. 특징적으로 전공에 대한 지식을 깊게 질문하고 꼬리질문이 매우 많았습니다. 꼬리질문을 계속 받아도 최대한 당황하지 않으려 노력하는 것이 중요할 것 같고, 생기부에 기반하지 않은 질문(본인 경우는 흄에 대한 질문)에 허를 찔릴 수도 있는데, 당황하더라도 자기 전공에 대한 관심이 많았다면 아는 선에서라도 대답을 하면 좋고, 전혀 모르겠다면, 면접관분들이 힌트를 줘서라도 대답하게 도와줄 것입니다. 어떻게든 질문에 아는 것을 활용해 대답하고자 하는 것은 좋은 것 같습니다.서울대 사대를 지망하는 경우에는, 교육에 대한 주제도 중요하지만, 보이는 것처럼 교육에 대한 질문보다는 전공 과목에 대한 질문이 매우 많습니다. 자기 과목을 중점적으로 준비해 보세요.마지막으로, 웃으면서 면접에 임하세요. 막 싱글벙글 입꼬리를 올리라는 건 아니고, 사람이 적당히 배부를 때 느껴지는 만족감에서 나오는 표정과 같이 살짝 웃는 표정을 유지해 보세요. 위에서 표현하지는 않았지만, 저는 처음부터 끝까지 당황하고 멘탈이 깨지면서도 살짝 웃고 있었습니다. 마스크 때문에 잘 보이지는 않았겠지만, 살짝 웃는 태도를 유지하는 것만으로도 면접에 임하는 태도가 달라 보이고, 실제로도 달라집니다. 서울대 교수님 얼굴을 보는 것만으로도 행복하다고 생각한다면 긴장도 살짝 풀어집니다.2023 대입 면접후기"}],"result":"합격","resultNote":"","src":"충청북도교육청 「2024 수시 대비 면접 후기집」","year":"2024학년도"},{"univ":"서울대학교","dept":"의예과","jeonhyeong":"학생부종합(지역균형)","method":"서류(생기부/자소서) 면접 20분, MMI 40분(방 4개, 10분씩)면접 전 대기실에서 대기-면접-면접 후 대기실에서 대기-다같이 퇴장","notes":"신분증, 수험표 지참","qa":[{"q":"“너가 금 간 천장을~”에서 화자의 심정은 어땠을지 이야기해보시오","a":"저는 이 제시문이 부모가 아이의 고통을 나누어 덜어주고 싶어도 그럴 수 없어 슬퍼하는 상황을 묘사하고 있다고 생각했습니다. 그래서 아이가 고통스러워함에도 자신은 단지 주변을 둘러보는 것만 할 수 있을 뿐 아이를 도울 수 없어 슬픈 감정을 느꼈을 거 같습니다."},{"q":"당신이 이 사람들이 있는 병실에 환자로 입원했다. 당신은 이들을 위해 무언가를 해 주고 싶다. 어떻게 할 것인가?","a":"이 사람이 안 좋은 감정만 남지 않게 하기 위해 좋은 경험을 많이 만들어주고 싶습니다. 그래서 이 사람을 달래줄 거 같고, 사진을 찍어준다든지 해서 설령 일이 잘못되어도 그것이 순전히 나쁜 기억으로 남지 않게 할 거 같습니다."},{"q":"그러면 위로를 할 때 주의해야 할 점이 있다면 뭐가 있을까요?","a":"제가 이런 상황을 직접 겪어본 것이 아니기 때문에 “심정은 이해하지만”과 같이 이야기를 시작하면 안 될 거 같습니다.3번 방은 ‘나보다 남을 도울 때 더 만족감을 느낀다’ 두 갈래 Y/N, ‘나는 남에게 공감하는 것이 어렵다’ 두 갈래 Y/N, ‘나는 업무를 모두 마친 뒤 휴식을 취한다 Y/N으로 총 8가지 유형 A B C D E F G H가 분류되어있는 제시문이었음."},{"q":"제시문에 있는 유형 중 본인은 어디에 속한다고 생각하나요?","a":"저는 저보다 남을 도울 때 더 만족감을 느끼고, 남에게 공감하는 것이 어렵지 않으며, 업무를 하는 중간중간 휴식을 취하기 때문에 D유형(YNN)이라고 생각합니다."},{"q":"나보다 남을 도울 때 만족감을 느낀다고 했는데, 구체적인 예를 들어줄 수 있나요?","a":"1학년 멘토멘티 사례를 설명함."},{"q":"본인이 D 유형이라고 했는데, 다른 유형처럼 행동했던 적은 없나요?","a":"과제의 기한이 촉박하면 C(YNY)처럼 행동한 적도 있었던 거 같고, 제가 누군가와 직접적으로 경쟁을 하는 상황에서는 H(NNN)처럼 행동했던 거 같습니다."},{"q":"본인이랑 정반대 유형이랑 2인 1조 프로젝트를 하게 됐습니다. 첫 시간에 선생님께서 조원을 바꾸고 싶으면 바꾸러 오라고 이야기를 했습니다. 조원을 바꿀 건가요?","a":"다른 요인이 있으면 몰라도 저 세 가지만으로 알 수 없고, 오히려 보완할 수 있으니 안 바꾼다 함."},{"q":"이 기준으로 학급회장을 뽑을 수 있을까요? 못 뽑으면 어떤 조건을 추가할 수 있을까요?","a":"못 뽑는다 함. 업무수행능력과 친구들 이끄는 능력 추가로 얘기함.2번 방은 수재민 수해 복구 봉사와 수학 경시대회 모임 제시문이었음.제시문: [ 선우는 일요일 8시부터 4시간 동안 폭우로 인해 집이 침수 피해를 입은 수재민을 위해 수해 복구를 하는 봉사가 있다는 사실을 알았다. 일요일 1시부터는 3명의 친구와 함께 몇 달 뒤에 있을 수학 경시대회 준비를 위해 함께 모여 이야기를 나누기로 했다. 시간의 여유가 있기에 선우는 수해 복구 봉사를 하러 가기로 했다. ]"},{"q":"봉사가 끝이 안나 만남이 어려울 거 같으면 어떻게 할 것인가?(상황을 악화시키며 반복 질문)","a":"어떤 경우에도 봉사를 끝까지 하겠다고 함. 친구들한테는 양해를 구한다 함."},{"q":"자신이 가야 하는 상황일 때 수재민에게 상황을 설명해보시오.","a":"정말 죄송하지만 제가 일이 있어서 지금 봉사를 계속하지 못할 거 같습니다. 아직 복구가 다 끝나지 않았는데 이렇게 가게 되어 정말 죄송합니다. 하지만 어쩔 수 없는 일이라 지금은 가 봐야 할 거 같고, 대신 제 일이 끝난 뒤에도 복구가 끝나지 않았다면 밤에라도 꼭 찾아와 계속 봉사하겠습니다. 이해해주시길 부탁드리겠습니다."},{"q":"봉사할 때 이런 어려운 경험 겪은 적 있는가?","a":"유사하지 않지만 봉사 중 어려웠던 일 얘기함1번 방은 국가 소득과 A 질환의 관계를 표로 나타낸 제시문이었음. 자료해석형 문제였고, 표에서 설명할 수 있는 얘기를 모두 함(표를 보면 우선 고소득 국가일수록 평균 진단 나이가 적은 것을 확인할 수 있습니다. 다음으로 고소득 국가일수록 초기와 중기에 진단하는 비율이 높고, 저소득 국가일수록 중기와 말기에 진단하는 비율이 높습니다. 이는 앞서 고소득 국가일수록 평균 진단 시기가 빠른 것과 관련이 있다고 할 수 있습니다. 마지막으로 3년 생존율도 고소득 국가일수록 높아지는데, 이를 통해 A 질환을 초기에 진단할수록 더 치료가 잘 된다는 것을 알 수 있습니다.)"},{"q":"결과의 원인은 무엇이라 생각하는가?","a":"고소득 국가에 비해 저소득 국가에서 의료 환경이 열악하고 전문 인력, 즉 전문 의사가 부족하기 때문인 거 같다고 답함.후배들을 위한 조언 3학년 돼서 준비하려 하면 어려운 거 같고, 평소에 고민하며 학교생활을 하는 게 좋을 거 같음. 서류 면접도 어떤 데서 나올지 모르기 때문에 자기 서류를 다방면으로 꿰뚫고 있어야 한다고 생각함.2023 대입 면접후기"}],"result":"합격","resultNote":"","src":"충청북도교육청 「2024 수시 대비 면접 후기집」","year":"2024학년도"},{"univ":"서울대학교","dept":"간호학과","jeonhyeong":"학생부종합(지역균형)","method":"8시 반까지 면접 대기실 입실 후 8시 55분부터 2개 교실에서 면접 시행, 면접 시작 후 부터는 자료는 볼 수 없음. 면접시간은 10분 내외, 5층 강의실로 이동해 면접 시행도착해서 자료를 많이 볼 시간은 없으니 미리 자료를 숙지해 가는","notes":"것이 중요함. 화장실을 1명씩만 갈 수 있으니 미리 가 놓는 것이 좋음.","qa":[{"q":"간호학과에 지원하게 된 동기는?","a":"코로나19라는 힘든 시대를 겪으면서 생명의 최전선에서 노력하시는 간호사분들의 모습을 보며 저도 그들과 같은 역할을 하고싶다는 생각을 가지게 되었습니다. 제가 생각하기에 간호인으로서의 필요한 역량은 전문성, 상황판단력, 인류애 라고 생각했고 서울대학교 간호학과에는 제가 목표로 한 교육과정과 동아리 활동 등이 체계적으로 갖추어져 있다고 생각했습니다. 이러한 학부에 진학해 공부한다면 미래의 간호분야를 이끄는 인재로서 성장할 수 있을 거라 생각하여 지원하였습니다."},{"q":"1학년 통합사회 시간에 의료격차 관련 설문을 하셨는데 이 의료격차를 해결하기 위해서는 어떻게 해야 하나요?","a":"우선적으로 의료 낙후지역의 의사들에게 경제적인 지원을 해 주는 것이 먼저이며, 제가 통합사회 시간에 제시한 정책으로는 의료낙후지역의 사람들에게 저렴한 가격으로 약품을 제공해 주는 정책을 계획하였습니다."},{"q":"본인이 생각하는 리더십이란?","a":"제가 생각하는 리더십이란 한명한명 모두의 의견을 들어주는 것이라고 생각합니다. 그래서 특별히 반장과 부반장을 맡아서 하기보단, 조장, 팀장을 매번하며 조원들 하나하나의 생각을 세심하게 들어봐주고, 이를 통합하는 역할을 주로 하였습니다."},{"q":"3학년 확률과 통계 시간에 진단키트의 정확도에 대해서 조사하였는데 어떠한 내용이었나요?","a":"높은 정확도를 가진 자가진단키트로 검사를 하였음에도 실제 양성으로 판정되는 비율이 높지 않다는 기사를 보고 의문이 생겨 해당 주제를 탐구하게 되었습니다. 탐구 과정 중 민감도와 특이도로 결정되는 정확도와 양성 예측도의 차이를 알게 되었으며 신뢰할 수 있는 키트를 결정하는 조건에 양성 예측도가 아닌 정확도가 사용되는지에 대한 이유를 알 수 있었습니다."},{"q":"양성예측도랑 민감도의 차이점은 무엇인가요?","a":"민감도는 감염이 된 경우에 진단 키트가 양성으로 판단할 확률을 말하며 양성예측도란 자가검사키트로 양성으로 진단된 사람들 중에서 PCR 검사로 진짜 감염자를 확진한 비율입니다. 양성 예측도는 얼마나 많은 사람이 감염되었는지에 따라 변화가 있습니다. 이 부분에서 진단키트의 정확성을 판단하는 데에 양성예측도가 사용되지 않은 이유를 알 수 있었습니다."},{"q":"간호계에 관심을 가지게 된 계기는 무엇인가요?","a":"3년동안 멘토멘티 활동을 굉장히 열심히 하였는데, 멘티에게 저만의 학습 능력을 가르쳐주고 학업 방향을 제시해 주는 것에 많은 뿌듯함을 느꼈습니다. 이러한 능력이 간호계에 종사하기 위해서 필요하며 간호사의 직업적 소명에 관심을 가지게 되었습니다."},{"q":"멘토멘티 활동을 하며 힘들었던 점은?","a":"멘티의 성적이 많이 오르자 많은 친구들이 조언을 구해 저만의 공부 시간이 부족했습니다."},{"q":"멘토멘티 활동을 통해 성장한 점은?","a":"저는 항상 제가 모든 것을 다 통솔해야 한다고 생각했었는데, 제가 가르쳐준 친구가 다른 친구 또한 잘 가르쳐 주는 모습을 보며 공동체에서의 역할 분담과 더불어 살아가는 사회에서 제가 해야 할 역할에 대해 생각해 볼 수 있었다는 점에서 성장하였습니다. 후배들을 위한 조언 생활기록부, 자기소개서에 대해 깊이 있는 질문을 하기보다는 확인용의 질문을 주로 함. 인성적인 부분을 더 많이 물어본다는 것에서 과 지원 동기, 향후 목표는 준비해 가는 것이 좋음2023 대입 면접후기"}],"result":"합격","resultNote":"","src":"충청북도교육청 「2024 수시 대비 면접 후기집」","year":"2024학년도"},{"univ":"서울대학교","dept":"국어국문학과","jeonhyeong":"수시 종합(일반전형시간은 오후조로 12시 30분이었고 면접 장소는 인문1관이었습니다. 면접 도우미 분께 안내를 받고 발열 체크 및 손소독 후 대기실에 들어가 학생들 서로 거리를 두고 앉게 되었습니다. 인원은 10명으로 남자 2명에 여자 8명이었습니다. 앞에 면접 도우미 분이 30분마다 학생을 불러 면접장으로 보냈습니다. 대기실은 환기 때문에 약간 추웠고 전자기기는 사용 불가였습니다. 하지만 종이 자료는 볼 수 있었기 때문에 가져온)","method":"자료를 보며 면접 준비를 했습니다. 이름을 불리면 대기실을 나와 면접 도우미 분의 안내를 받고 답변 준비실로 가게 됩니다. 인문 지문 1개, 사회 과학 지문 1개와 플러스 펜과 종이를 받고 15분 동안 답변을 준비합니다. 1분이 남았을 때 도우미 분이 말해주시고 시간이 다 되면 지문과 종이, 펜을 챙기고 면접실로 가게 됩니다. 면접실에서는 두 분의 교수님과 30분 동안 면접을 하게 됩니다. 면접 중 1분 남았을 때 면접 도우미 분께서 노크를 하십니다. 면접이 끝난 후에는 종이와 펜은 반납하고 짐을 가지고 바로 나가면 됩니다.면접 대기실 온도에 유의해야 하마 자신이 면접 뒷번호라면 오래 기다릴","notes":"수 있으니 자료를 챙겨옵시다. 제가 있던 대기실은 책이나 자료를 볼 수 있었지만 다른 학과 대기실에서는 못 보게 하는 경우도 있었다고 하니 유의합시다.","qa":[{"q":"1-1. 제시문 (가)의 대상의 표상화, 현실적 정보의 개념과 연관지어 제시문 (나)와 제시문 (다)의 내용에 대해 이야기하시오1-2. 제시문 (나) 또는 (다)와 연관지어 아래 보기에 있는 단어들 중 하나만 골라 단어가 잘 드러나는 문학작품을 하나 이야기하시오2-1. 제시문 (가)에서 드러난 사례를 제시문 (나)와 (다)의 입장에서 평가하고 자신의 생각을 밝히시오2-2. 제시문 (라) 속에서 (가)와 (나) 중 무엇이 더욱 유해한지 선택하고 자신의 입장에서 이야기하시오충청북도교육청","a":"1-1. 제시문 (가)의 내용은 모두 개인의 입장은 다르기 때문에 대상의 표상화가 일어나 사람들이 같은 사건에 대해 이야기해도 각자 생각과 내용이 다르다는 것이었다. 제시문 (나)와 (다)는 13세기 중엽 유럽인들이 몽골인들을 묘사한 글이었는데 제시문 (나)는 몽골인을 악마와 같이 묘사했고 제시문 (다)는 몽골인의 긍정적인 부분과 부정적인 부분을 모두 언급했다. 제시문 (가)와 관련지어 제시문 (나), (다)의 내용을 보자면 몽골인에 대해 부정적으로 묘사한 부분들은 대상의 표상화로 인해서 생긴 것으로 생각할 수 있으며 제시문 (나)와 (다)의 내용 차이도 그러하다. 하지만 제시문 (나)와 (다)에서 공통적으로 나타나는 몽골인의 잔인한 침략 과정은 현실적 정보라고 볼 수 있다.추가 질문 1. 제시문 (나)와 (다)가 사회의 관점에서는 각자 어떤 사회에 속해 있다고 생각하는가?추가 질문 답변 1. 제시문 (나)는 몽골인에게 일방적으로 침략당한 사회, 제시문 (다)는 몽골인과 공존하고 있는 사회라고 생각한다. 제시문 (나)에서는 단순한 몽골인에 대한 비판만 있는 반면 제시문 (다)에서는 몽골인에 대한 긍정적 서술도 있기 때문이다.추가 질문 2. 그렇다면 만약 제시문 (나)와 (다)가 같은 사회에 있다고 한다면 제시문 (나)와 (다)를 어떻게 이해할 수 있나?추가 질문 답변 2. 그렇다면 제시문 (다)의 화자가 제시문 (나)의 화자보다 더욱 열린 마음을 가지고 있다고 생각할 수 있다. 제시문 (나)의 화자는 몽골인에게 저주에 가까운 서술만을 하고 있지만 제시문 (다)의 화자는 몽골인에 대한 비판과 함께 몽골인의 긍정적인 부문에 대해서고 이야기하고 있기 때문이다.1-2. 나는 보기 중에서 분노라는 단어를 선택해 제시문 (나)와 연관지어 고전 소설 박씨전을 제시했다. (보기에는 분노, 두려움, 혐오감, 이질감 등의 단어가 있었다.) 왜냐하면 제시문 (나)에서는 화자가 몽골인에 대해 분노에 차 부정적인 서술을 남기고 있었기 때문이었다. 그리고 박씨전 역시 몽골의 유럽 침략과 같이 조선에 대한 청나라의 침략을 다루고 있으며 당시 사회 사람들이 품었던 청나라인들에 대한 분노감이 박씨가 용골대와의 싸움에서 승리하는 부분에서 표출되고 있다. 그렇기 때문에 분노라는 단어에서 제시문 (나)와 박씨전이 연관이 있다고 생각한다.추가 질문: 그렇다면 제시문 (다)와 보기의 단어 중에 연관지을 것이 있는가?추가 질문 답변: 나는 보기에서 이질감이라는 단어와 제시문 (다)를 연관짓고 싶다. 전 답변에서 이야기 했듯이 제시문 (다)의 화자는 몽골인과 공존하고 있는 상황이라고 생각할 수 있다. 이런 점에서 제시문 (다)에서 드러나는 몽골인에 대한 부정적인 서술은 같은 공동체 내에서 다른 구성원에 대해 느끼는 이질감에서 비롯되었다고 생각한다.2-1. 제시문 (가)에서 드러난 사례는 독일에서 현재 비선출직 전문가가 정치에 참여해 정치에 국민들의 의견이 제대로 반영되고 있지 않다는 것이다. 이를 제시문 (나)와 (다)에 연관지어 생각해보면, 우선 제시문 (나)는 대의민주주의를 옹호하는 내용이었다. 이에 대해 제시문 (나)의 화자는 제시문 (가)의 사례를 국민들의 의견이 반영되지 않았다는 점에서 비판할 것이다. 제시문 (다)의 내용은 엘리트 민주주의를 옹호하는 내용이었다. 이에 대해 제시문 (다)의 화자는 제시문 (가)의 사례에 대해서 엘리트 충청북도교육청민주주의의 긍정적인 면을 바탕으로 긍정적인 평가를 내릴 것이다. 이에 대해 본인은 제시문 (나)에 공감하며 제시문 (가)의 사례와 제시문 (다)를 비판할 것이다. 이에 대해서는 2가지 근거가 있다. 첫 번째로는 시민들이 제시문 (다)에서 이야기한 것처럼 실패한다고 해도 자정작용을 거쳐 더욱 성장할 수 있기 때문이다. 두 번째로는 시민들이 참여하지 않은 정책의 피해에 대해 시민들이 책임을 지게 되는 것은 불공평하기 때문이다. 제시문 (가)에서 쿠란 금지를 정책으로 내건 정치인이 당선되었을 경우 대의민주주의가 아닌 제시문 (가)의 경우는 시민들이 부당하게 피해를 입게 된다.2-2. 제시문 (라)에서 (가)는 자유가 없는 민주주의, (나)는 참여가 없는 자유주의였다. 이에 대해 본인은 (가)가 사회에 더 안좋은 영향을 미친다고 생각한다. 그 이유는 첫 번째로 (가)는 독재로 이어질 위험이 매우 크기 때문이다. 자유가 없이 그저 선거만 하게 된다면 제대로된 시민 참여가 이루어지지 않을 것이며 이런 문제는 독재로 이어질 확률이 매우 크다고 예측할 수 있다. 두 번째 이유는 자유가 없는 민주주의는 의미가 없기 때문이다. 위 답변과 같게 자유 없는 선거는 제대로된 시민 참여를 이끌어 낼 수 없다. 그러므로 자유 없는 민주주의는 큰 의미가 없으며 이것이 (나)보다 더욱 큰 문제라고 생각한다.추가 질문: 그렇다면 (나)의 경우에는 어떤 문제점이 있다고 생각하는가?추가 질문 답변: 이에 대해서는 2가지 문제점이 있다고 생각한다. 첫 번째로 참여 없는 자유주의는 방종으로 이어지기 쉽기 때문이다. 참여가 없이 주어진 자유는 귀중함을 잃고 자유의 사용에 대해서 사람들이 생각하지 않게 만든다. 그렇기 때문에 (나)는 방종으로 이어질 확률이 매우 높다. 두 번째 이유는 참여 없이 자유를 얻는 것은 부당하기 때문이다. 자유에는 책임이 따르고 이에 대해서는 정책 결정 등에 대해 참여함으로써 책임을 지게 되거나 자유를 실현할 수 있다. 이런 과정을 거치지 않은 자유는 부당하며 위험하다.후배들을 위한 조언 꼬리 질문이 매우 많으므로 둘 중 하나를 선택하라고 하는 문제의 경우에는 웬만해서는 선택하지 않은 주제의 답변도 생각해두어야 합니다.대면면접이므로 인사나 시선처리에 신경써야 합니다.충청북도교육청"}],"result":"합격","resultNote":"","src":"충청북도교육청 「2022 대입 면접 후기집」","year":"2022학년도"},{"univ":"서울대학교","dept":"경제학부","jeonhyeong":"학생부종합전형(일반전형)","method":"30분 간 문제 풀이 + 15분간 면접","notes":"","qa":[{"q":"제시문 (나), (다)에서는 각각 기업이 사회적 책임을 이행하는 동기와 상황에 대해 추론할 수 있다.제시문 (나), (다)를 바탕으로 제시문 (가)에 나타난 인도의 회사법 개정에 대해 평가하시오.","a":""},{"q":"사회 문제 해결을 위한 정부와 기업의 바람직한 역할 구분을 말하고, 그에 비추어 (가)의 회사법 개정을 논하시오.2-1.(꼬리질문) (나)에 나타난 기업의 사회적 책임 이행과 (가)의 회사법 개정을 자발성과 강제성 측면에서 논해볼 수 있을까요?<수학>일 때, 의 값을 구하시오.1.이 되도록 하는 의 값의 범위가 ≤≤","a":""},{"q":"그릇에 담긴 물의 양이 기울이기 전과 같도록 하는 의 값의 범위가 ≤≤일 때, 의 값을 구하시오.일 때, 의 값을 구하시오.3.함수 를 구하고, cos *답변<사회과학>","a":""},{"q":"먼저 (나)와 (다)를 바탕으로 기업이 사회적 책임을 이행하는 동기와 상황을 논해보도록 하겠습니다.(나)의 경우는 기업이 사회적 책임을 이행함으로써 소비자들이 자신이 사회에 긍정적인 영향력을 미칠 수 있다는 하나의 윤리적 동기를 제공하고 있습니다. 이러한 소비자의 반응 속에서 충청북도교육청기업의 재화 구매는 증가하였으며, 결과적으로 기업의 이익에 긍정적인 영향을 주었기에 이런 이윤 창출이 하나의 윤리적 동기가 될 수 있다고 생각합니다. 한편 (다)에서는 경쟁 기업과 독점 기업이라는 이분법적 구분의 측면에서, 독점 기업은 사회적 책임을 이행하기에 적합하나 경쟁 기업은 그렇지 않음을 추론할 수 있습니다. 따라서 사회적 책임 이행의 상황으로는 해당 기업이 경쟁 상황에 놓여있는지를 중점적으로 파악할 수 있으리라 생각합니다. 이를 바탕으로 인도의 회사법 개정을 살펴보면 인도는 회사법을 개정해 특정 조건을 만족한 기업에게 사회적 책임 이행의 의무를 지우고 있습니다. 이는 (나)에서 본 바와 같이 기업이 사회적 책임을 이행함으로써 소비자의 구매를 늘려 그들의 이익을 높일 수 있도록 한 것일 수 있지만, (다)를 볼 때, 회사법의 조건을 충족한 기업이 반드시 독점 상황에 있는 것이 아닐 수 있으므로, 경쟁 상황에 놓인 기업에 사회적 책임 이행 의무를 강조해 그들의 생존을 위협할 수 있다고 생각합니다.2.정부의 경우에는 기본적으로 형평성을 핵심 동력원으로 하는 조직체이고, 기업의 경우에는 효율성을 핵심으로 하는 조직입니다. 따라서 사회 문제 해결 시에는 이에 충실하여 정부는 직접적인 개입, 이를테면 보조금 지급과 같은 직접적인 방법을 활용하는 것이 중요하며, 기업의 경우에는 효율성이 핵심이므로, 사회 문제를 직접적으로 해결하려 하기보다는 간접적인 개입, 즉 기부, 봉사활동, 스포츠팀 창설 등을 통해 우회적으로 사회 문제를 해결하는 데 주력해야 한다고 생각합니다. 그리고 이를 기반으로 (가)의 회사법 개정을 논하면 정부는 기업에게 간접적으로 사회 문제를 해결하도록 강제한다는 점에서 회사법 개정은 긍정적으로 볼 수도 있으나, 정부는 회사법 등으로 기업에 사회적 책임을 부여하는 것에 주력하기보다는 좀 더 직접적인 개입이 필요하다고 생각합니다.2-1. (나)의 경우는 기업이 자발적으로, 자신의 상황에 맞추어 사회적 책임을 이행하였고, 소비자의 윤리적 동기를 자극해 더 많은 이윤 창출로 나아갈 수 있었습니다. 하지만 (가)의 경우 회사법을 통해 기업에게 의무를 부과하는 강제성의 모습으로 (다)의 경쟁 상황 기업에게 생존 위기를 가져다줄 수 있다는 점에서 그 차이를 생각해 볼 수 있다고 생각합니다.<수학>-교수님 도움으로 풀이만 조금 말씀드렸습니다.일 때는 이차함수의 그래프가 축을 뚫고 내려가므로 을 충족하게 됩니다. 그리고","a":""},{"q":"의 점을 기울인 점이 x축과 t의 값이 점점 줄어들다가 물그릇의 오른쪽 꼭짓점인 닿았을 때 이 되는 가장 작은 각 의 값을 구할 수 있다고 생각합니다.","a":""},{"q":"일 경우에는 물그릇이 전혀 기울지 않았으므로 당연히 담긴 물의 양도 변하지 않을 것입니다. 이후 물그릇을 조금씩 기울이다 보면 의 높이가 물그릇의 오른쪽 꼭짓점인 의 점을 기울인 점에서 축 간의 거리가 되는 지점이 나오게 되는데, 이때 각이 이 되리라 생각합니다.(여기까지 하고 제가 더 답변을 하지 못했고, 시간이 되어 내보내셨습니다.)충청북도교육청후배들을 위한 조언","a":""},{"q":"면접 대기실에서 가장 큰 특징은 가져온 자료를 볼 수 없었다는 점입니다. 다른 면접과 유사하다고 생각해, 면접을 기다리면서 볼 자료까지 전날 정리해둔 저로서는 조금 당황스러웠고, 또 대기시간이 굉장히 지루했습니다. 저는 너무 긴장되는 마음에 심호흡하며 있었지만, 오전면접이라 아침부터 움직였을 지원자들 중 몇몇은 쪽잠을 자는 경우도 있었습니다.(학교에서 다른 과 지원한 친구들과 얘기해본 결과, 면접 대기 시 개인 자료를 볼 수 있는가는 단과대마다 다른 듯합니다.)","a":""},{"q":"제시문 숙독 때 가장 놀란 점은 숙독이 복도에서, 특히 면접실 바로 앞 복도에서 이루어졌다는 것에 있었습니다. 따라서 옷을 두껍게 입지 않으면 날씨에 따라 매우 추울 수도 있다고 생각했습니다. 또한, 면접실 바로 옆에서 숙독하다보니 안에서 면접 보는 소리가 조금 들립니다. 그 소리에 집중력 흐트러지지 않고 제시문에 집중할 수 있어야 하므로 항상 조용한 장소에서 제시문을 숙독해왔던 학생들의 경우 이 부분을 유의했으면 좋겠습니다.","a":""},{"q":"면접 과정에서는 면접관과의 상호작용 부분이 핵심이라는 것을 많이 들어왔고, 실제로도 어느 정도 그 중요성이 엿보였다고 생각됩니다. 특히 수리 면접을 준비하면서, 잘 모를 때는 교수님께서 힌트를 주시니 그 힌트를 잘 끌고 가야 한다는 말을 많이 들었습니다. 이러한 상호작용에 대한 것은 제 면접을 기준으로 하면 완전히 틀린 말은 아니었지만, 100% 맞는 말도 아니었다고 생각합니다. 제 경우 수리 면접을 거의 하나도 접근하지 못한 채 들어갔기 때문에 완전히 망했다는 생각에 차서, 아주 원론적이고 기초적인 풀이만 앉아서 말씀드렸습니다. 그러자 교수님께서 뒤의 화이트보드(경제학부 면접실에는 수학 문제 풀이를 원활하게 하기 위한 화이트보드와 보드마카, 지우개 등이 구비 되어 있었습니다.)로 가서 풀어보라고 하셨고, 힌트를 주고 계신다는 느낌에 덥석 가서 함수 개형을 그려보며 교수님의 힌트를 따라갔습니다. 교수님의 힌트를 통해 이 되는 경우에서의 의 개형을 추론하는 것까지는 함께할 수 있었으나, 저는 의 값을 구하는데 접선의 방정식이 활용되어야 한다는 것도 눈치채지 못했고 교수님 역시 그 부분까지는 힌트를 주시지 않으셨습니다. 아마 답을 구하는 것에서는 지원자 개인의 역량을 중점적으로 보고자 하신 것 같다고 생각합니다.⒋ 서울대는 수리 면접이 핵심이니만큼 많은 공부를 해가셨으면 좋겠습니다. 1차 합격하고 6~7일간 수능이 끝났다는 즐거움 속에서, 친구들은 놀러다니는 상황에서 혼자 앉아 수학 문제를 풀어야 한다는 것 자체가 너무나 고통일 것입니다. 게다가 본인은 부담스럽고 힘든데 주위에서는 그 어려움을 아는지 모르는지 자꾸 기대를 불어넣기 때문에 준비하다 보면 너무 벅찰 수도 있으리라 생각합니다.하지만 어쨌든 본인이 서울대에 대한 희망이 있다면, 그리고 수학 면접이 있다면 그 어려움을 이겨내고 수학을 열심히 하셔야 한다고 생각합니다. 다행스러운 점은 문과 학생들은 이과 학생들에 비해 수학 실력이 그다지 높지 못하기 때문에 평균 수준의 난이도 기준으로 절반 정도 충청북도교육청풀면 합격하는 경우가 대다수라 들었습니다. 물론 그만큼 서울대의 수학이 어렵다는 뜻이기에, 기출 문제를 반복해서 풀고 남들 앞에서 풀이하는 연습을 하는 동시에 그 문제가 어떤 과목(수학, 수학 Ⅰ, 수학 Ⅱ, 확률과 통계)의 어떤 단원에 기초를 두고 출제한 것인지, 내가 그 단원의 개념들을 충분히 숙지하고 있었는지를 확인하며 개념과 수학적 사고력을 모두 챙기면 굉장히 많은 도움이 되리라 생각합니다. 또 기출을 시간을 재고 풀어보고 설명하는 연습을 하되, 제한 시간 내에 못 풀었다고 무작정 해설지를 보는 것보다는, 모의면접을 해본 후에 몇십 분 정도 더 자신의 풀이를 생각해보는 것도 좋은 방법이 될 수 있으리라 생각합니다.충청북도교육청","a":""}],"result":"불합격","resultNote":"","src":"충청북도교육청 「2022 대입 면접 후기집」","year":"2022학년도"},{"univ":"서울대학교","dept":"인류학과","jeonhyeong":"수시(일반전형- 대기실 입실 후 본인 차례 전까지 대기)","method":"- 본인 순번에 조교 지시 따라 면접장 앞 복도로 이동- 복도에 놓인 책상에 앉아 30분간 제시문 분석 및 개요지에 답변 작성- 제시문과 개요지 모두 들고 면접장으로 이동- 15분간 제시문 및 그 외 추가질문 후 퇴실","notes":"별도 중간대기실 X대기 중 전자기기 사용 금지, 그 외 자료 읽기 가능","qa":[{"q":"나 지문 진실 - 몽골인들이 영토를 크게 확장함표상 - 악마, 메뚜기, 괴물 등의 상징으로 반감 드러냄다 지문 사실 - 몽골인들이 자신들의 사회 내에서는 큰 문제가 없으나 타 민족과의 전쟁 시 전투 민족의 특성을 드러냄표상 - 글쓴이의 감정을 반영하여 주관적 기준 설정(세상에서 가장), 미루어 판단함(누구든 속이려고 함... etc)","a":""},{"q":"이질감나 지문 - 악마, 메뚜기 떼 - 성경에서 악마적 존재 13세기 유럽 가톨릭 퍼진 배경 미루어 보아 예수 믿는 자신들 <-> 악마적 존재로 비유된 몽골인들다 지문 - 타타르인과 유럽 사람들을 철저히 다른 집단으로 분류","a":"이러한 근거로 이질감 나타났다고 판단함 문학 작품 - <딸에 대하여>동성애자 딸을 이해하지 못하고 이질감을 느끼고 부정적 감정을 느끼는 어머니와 딸의 갈등, 결말부에 이해를 통해 해결하는 양상이 나타났습니다.나, 다 지문에 나타난 부정적 감정(두려움, 분노 등도) 유럽인들이 타타르인을 이해하지 못하는 이질감에서 비롯된 것이라고 생각하여 이질감이 주된 감정이라고 판단했습니다. 충청북도교육청[제시문 2]"},{"q":"(나) - 정치 행위에 국민 참여를 중시 (다) - 정치 행위를 국민의 손에 전적으로 맡기는 것에 회의적나 제시문은 공공정책은 국민을 위한 정책이니 국민의 뜻을 더 많이 반영해야 한다고 생각할 것다 제시문은 다수 의견 반영되어 이슬람 억압된 유럽 사례에 주목하여 전문가 개입으로 더 합리적인?? 방안 도출 필요하다고 생각했을 것 나의 견해 - 둘 다 일리 있음. (정확히 기억 안 나지만 근거 말함) 국민 뜻에 맡기되 국민이 다수성 외에 소수자들의 의견도 고려할 수 있도록 교육적 보완, 또는 소수 세력에게의 언론 등에서의 발언 기회 제공이 필요하다고 생각함","a":""},{"q":"(빨리 말하고 생기부 질문하겠다 하셔서 축소해서 대답함) 권리 없는 민주주의 확산이 더 위협적이라고 생각함 다수 의견 강화할 우려가 있고 특히 현재 sns 의 영향으로 혐오 정서가 더 잘 드러나고 잘 퍼지는 상황에서 제도적이고 정치적인 내용조차 개개인의 권리보다는 다수 의견에 더 치우친다면 문제가 더 심화될 것이라고 생각함<추가 생기부 질문>","a":""},{"q":"인류학과 지원 계기는?","a":"다양한 사회 문제 탐구하던 중 환경 문제 관심 가지고 이에 대한 해결책으로 친환경적인 문화의 정착을 생각함 하지만 이것을 구체적으로 어떻게 실현할지 알아내지 못함 진학해서 배워 보고 싶음"},{"q":"사회, 지리 등 다른 학과도 많은데 왜 하필 인류학과였나?","a":"문화라는 개념을 중점으로 인류를 총체적으로 이해하려 한다는 면에서 제가 실현하고자 하는 목표를 이루는 데에 도움이 될 것 같아 희망하게 되었습니다."},{"q":"읽었던 인류학 도서를 아무거나 말해 보세요.","a":"인류학에 관심 가지게 된 계기가 환경인 만큼 환경 인류학이라는 분야에 특히 관심을 가졌습니다. 도서는 콕 집어 말씀드리기 어렵지만 그 외 다양한 사회 문제 탐구를 위한 도서를 읽으며 인류학적으로 총체적이고 균형 잡힌 관점으로 임하려고 노력했습니다."},{"q":"본인이 생각하기에 친환경적인 문화가 성공적으로 정착되었다고 생각하는 지역 및 문화권을 아무거나 하나만 대 보세요.","a":"(이미 15분 지나서 빨리 말하라고 하셨음) 상대적으로 비문명화 된 지역에서 친환경적인 양식이 나타나고 있다고 생각합니다.후배들을 위한 조언 준비할 때 제시문 관련 준비하는 것도 물론 매우 중요하지만 특히 본인 희망 전공에 대해서 전공에 지원한 계기, 전공 지식 관련 단어, 유명한 학자 이름, 도서 등을 철저히 준비하고 공부해서 가세요! 끝나고 나니 그 부분이 가장 후회되었습니다. 또, 잘 모르는 질문이 나와도 당황하지 마시고 아는 선 내에서 또렷하게 대답하는 것이 중요하다고 생각합니다.충청북도교육청"}],"result":"불합격","resultNote":"X","src":"충청북도교육청 「2022 대입 면접 후기집」","year":"2022학년도"},{"univ":"서울대학교","dept":"지리교육과","jeonhyeong":"학생부종합전형(지역균형면접시간10분)","method":"인원수면접 위원 수: 3명 조별 학생 수: 9명8시 15분까지 입실(핸드폰을 비롯한 거의 모든 소지품 면접절차제출), 9시부터 시작, 앞사람 끝나기 1분정도 전에 면접실로 이동, 대면 면접,","notes":"","qa":[{"q":"동아리, 남중국해 배운점, 활용저는 남중국해를 비롯한 국제적인 여러 갈등에 대해 배우며 세계의 여러 나라가 자신의 이익을 최대한으로 보장하기 위해 노력합니다. 저는 이를 평소 제 삶에서도 파악할 수 있었습니다. 저는 3학년 때 학급 부반장을 하며 우리반에게 도움이 되기 위해 노력했습니다. (자세한 예시도 들었었는데 기억이 안나네요... 암튼 이런 식이었습니다!)충청북도교육청","a":""},{"q":"교사가 된다면 어떤 분야를 어떻게 가르치고 싶은가저는 지형학에 대해 가르치고 싶습니다. 왜냐하면 지구과학과 세계지리를 배우며 다양한 지형과 대지형에 대해 알게되었습니다. 그래서 실제로 만져도 보고 경험해 보고 싶지만 그러지 못한 안타까움이 들었습니다. 제가 학생들에게 지형에 대해 가르친다면 증강현실인 AR과 가상현실인 VR을 적극적으로 활용할 것입니다. 앞서 말했듯이 탑카르스트 같은 지형들은 우리나라에서 찾아볼 수 없습니다. 하지만 AR을 이용한다면 아이들에게 직접 이러한 지형들을 보여줄 수 있고 생생한 교육을 할 수 있을 것이라고 생각합니다.","a":""},{"q":"지구과학이나 다른분야에 관심이 많은 것 같은데 굳이 지리교육과를 선택한 이유는?제가 지리를 선택한 이유는 그러한 다양한 분야와 서로 연결지을 수 있는 지리가 좋았기 때문입니다. 지리는 이렇게 자연환경과 관련해서는 지구과학과 그리고 인문지리와 관련해서는 정치, 세계사와 밀접하게 연결되어 있습니다. 지리라는 학문이 정체된 학문이 아닌 여러 학문과 서로 유기적으로 연결되어 있는 분야라는 점이 제게 큰 흥미가 되어서 지리교육과를 선택하게 되었습니다.","a":""},{"q":"나의 가장 큰 장점은?제 가장 큰 장점은 남다른 호기심 이라고 생각합니다. 저는 미드나잇인파리 라는 영화를 보고 프랑스 미술에 빠져 지역이해 시간에 이를 조사해보았고 소득불평등에 대해 궁금해져 로렌츠곡선과 지니계수를 탐구해 보는 등 다양한 과목에서 여러 호기심이 생겼습니다. 저는 특히 제가 지리교육과에 지원하기 때문에 이것이 제 가장 큰 장점이라고 생각했습니다. 지리는 종교, 경제, 지형 등 아주 다양한 것이 밀접하게 연결되어 있는 학문입니다. 따라서 이러한 호기심을 바탕으로 다양한 분야에 대해 지식을 축적한 것은 지리교육자로서 제 장점이라고 생각합니다.후배들을 위한 조언 일단 무조건 일찍 가세요! 학교도 넓고 학생도 많지만 주차공간이 넓지 않아 당황할 수 있습니다! 그리고 학교가 넓어서 길을 찾는데 헤멜수도 있으니까 일찍 가는 걸 추천합니다! 그리고 자기가 친근한 사람 앞에서(ex 담임쌤) 말을 잘한다면 미리 학장님 얼굴을 익혀가세요! 저는 서울대학교 지리교육과 사이트를 교육과정이나 목표를 보기위해 들락날락하다고 학장님 얼굴이 눈에 익었는데 진짜 도움이 되었어요! 내적 친밀감이라고 할까요!! 처음에 중심 질문은 2개한다고 말씀하세요 근데 그 두 질문이 진짜진짜진짜 길어요! 처음 1, 2번은 제가 요약한거지만 배경 설명을 쫙하시고 설명도 엄청 길게 하세요! 질문이 뭐였는지 기억하는게 진짜 힘들었어요! 2번은 특히 다시 한 번 말씀해달라고 했습니다! 그리고 면접실 들어갔을 때 페이스쉴드랑 앞에 아크릴 판까지 있어서 소리가 정말 안들려요! 저는 몸을 좀 앞으로 숙여서 잘 듣기위해 노력했습니다... 아직도 코로나가 심각하다면 이점 주의해주세요! 마지막으로 답변이 막히면 잠시 생각해본다고 하면 됩니다! 면접관 두분 모두 친절하게 편하게 답하라고 말씀하시면서 편하게 대해주셨어요! 그니까 긴장풀고 하고 싶은 말 모두 끝까지 하고 나오길 바랍니다!! 파이팅!!!충청북도교육청","a":""}],"result":"합격","resultNote":"최초","src":"충청북도교육청 「2022 대입 면접 후기집」","year":"2022학년도"},{"univ":"서울대학교","dept":"역사교육과","jeonhyeong":"수시(지역균형선발전형- 7시에서 8시 15분 사이 입실- 건물 안으로 들어가면 체온 측정하고 수험표 보이고 문진표 작성한 거 제출- 대기실로 들어가면 8시 20분쯤에 수험생 안내사항 전달받고 모든 전자기기 가방에 넣어 뒤에 갖다놓기 때문에 그후에는 면접 관련된 자료 못 봄- 면접 대기실에는 간격을 두고 개인별 책상이 놓여 있음. 가림막 있고, 장갑, 페이드실드(직접 조립해야 함. 조립하는 법 모르면 알려 줌), 핫팩 있음.)","method":"- 화장실은 손 들면 감독관 동행 하에 1명씩 이용 가능- 부여받은 가면접번호 순으로 면접 실시- 페이스실드와 장갑, 마스크 착용한 상태로 면접 실시- 대기실에서 불리면 감독위원 따라 면접실 바로 앞으로 이동하여 잠시 대기하고 짐은 그 앞에 놓음- 대기실 앞에서 인적사항 확인하고 수험생 유의사항 다시 한번 읽은 후 노크한 후 입실 시작함- 면접실은 작은 편. 교수님과의 거리도 멀지 않은 편. - 면접실 내 교수님과 본인 모두 마스크를 착용하고 심지어 면접자는 페이스 실드까지 착용함과 동시에 교수님과 면접자 책상 앞에는 가림막까지 있어서 교수님께서 말씀하시는 내용이 잘 안 들림. 특히 작게 말씀하실 때는 정확히 듣지 못한 질문도 있었음(면접 질문에 직접적으로 연관되는 질문은 아니었음.)","notes":"따라서 교수님께서 질문하시거나 발언하실 때에는 정말 주의 깊게 경청해야 함.- 어느 대학 면접이든 마찬가지이지만, 반드시 본인 옷이나 가방 등에 면접실 반입금지물품 없는지 꼼꼼히 확인해야 함.- 면접 대기실을 한 번 나가면 돌아올 수 없으므로 모든 소지품을 챙겨서 나감.(서울대, 연세대, 고려대 공통)","qa":[{"q":"지레짐작하지 마십시오: 최소한 면접에 응하기 전까지는 자신의 결과를 예단하지 마십시오. 그 결과는 나오기 전까지 모릅니다. 자신의 생기부는 자신이 판단하는 게 아니라 해당 대학에서 판단합니다. 그러니 본인의 생기부에 대한 본인 혹은 주변의 평가에 휘둘려 미리 면접을 포기해 버린다든지, 반대로 지나치게 자신감을 가지고 면접을 대충 준비한다는 마음가짐은 부정적인 결과로 이어질 가능성이 큽니다.","a":""},{"q":"진실된 생기부를 만드십시오: 서울대 지균의 경우, 생기부 기반 면접을 실시하기 때문에 여기에서 좋충청북도교육청은 평가를 받기 위해서는 본인의 생기부, 자소서, 그리고 그곳에서의 내용과 관련된 전공 지식을 잘 알고 있어야 합니다. 그런데 활동(자율, 진로, 동아리, 세특 등 전 영역) 시 억지로 하거나, 대충 임하거나, 단순히 ‘생기부를 채우려면 해야지’하는 마음으로 임하면 그 활동을 했다는 기억과 기록만 남습니다. 반면, 본인이 진실되게, 정말 큰 흥미를 갖고 임한 활동은 머릿속 어딘가에 분명 남아 있습니다. 그러므로 하나의 교내 활동을 하더라도 본인이 분명한 목적을 가지고, 흥미와 열정을 갖고 임해 보십시오. 학교 생활을 하다 보면 시험기간과 활동 기간이 겹치는 경우가 많은데, 저는 그렇다고 해서 활동을 대충 한 게 아니라 오히려 ‘잠을 줄여서라도 활동과 시험 모두 챙긴다.’라는 마음가짐으로 임했습니다.","a":""},{"q":"본인의 스토리를 만드십시오: 우리는 한 학문의 모든 분야에 다 통달할 수 없습니다. 그렇기 때문에 대학에서도 본인이 정말 관심 있는 하나의 국한된 분야만을 심도 있게 연구하게 됩니다. 고등학교 활동도 마찬가지입니다. 본인이 관심을 가지는 분야나 대상 몇 개에 대해 다각적으로, 간학문적으로 탐구하는 모습을 보여 주면, 분명 플러스 요소가 됩니다. 물론 그에 관련된 활동만 하는 것도 좋지 않습니다. 교과 세특이나 교내 활동을 통해 다양한 탐구를 전개하되, 대학에서 ‘이 학생은 이 분야에 관심이 많은 것 같군.’이라는 생각이 드러나도록 활동해 보십시오.","a":""},{"q":"면접은 어떻게 임하느냐에 따라 달라집니다: 다양한 서울대 지균 후기를 참고하면, 분명히 면접에서 좋은 평가를 받았을 것으로 보임에도 불합격하거나, 면접을 잘 봤다고는 생각하기 어려움에도 최초합하는 경우가 꽤 많습니다. 달리 말하면, ‘30’이라는 면접의 비율이 크지 않다고 생각할 수도 있습니다. 하지만 본인이 면접에서 강한 인상과 임팩트를 줄 경우 본인보다 서류에게 조금 더 좋은 평가를 받은 지원자보다 분명 결과적으로 더 좋은 결과를 받을 수 있습니다. 따라서 ‘30’이라는 비율은 클 수도, 작을 수도 있습니다. 그러나 어떤 경우든 최선을 다해 면접을 준비하면 후회가 남지 않습니다. 그렇기 때문에 비율에 연연하지 말고, 면접에 임하기 전까지 최선을 다해 준비하시기 바랍니다.","a":""},{"q":"지균 면접을 준비할 때는 전공 지식도 꼼꼼하게 준비하십시오: 본인의 경우, 서울대 지균 면접에서 단순히 활동의 계기, 활동을 통해 느낀 점, 배운 점을 주로 물어봐 주시지 않았습니다. 오히려 책의 내용(역사적 내용), 역사적 정의의 뜻, 일본군 ‘위안부’에 관한 내용 등 실제 역사적 지식을 풍부히 갖추고 있어야 수월하게 답할 수 있는 질문들이 주를 이뤘습니다. 그렇기 때문에 서울대 지균 면접을 준비하는 분이라면, 비단 활동 자체에 대한 복기뿐만 아니라 해당 활동과 관련한 전공 지식을 풍부하게 공부하는 노력도 들이시기 바랍니다.충청북도교육청","a":""}],"result":"합격","resultNote":"","src":"충청북도교육청 「2022 대입 면접 후기집」","year":"2022학년도"},{"univ":"서울대학교","dept":"전기정보공학부","jeonhyeong":"학생부종합(일반전형)","method":"- 대기실 제시문 풀이(45분)- 면접실 앞 대기 및 안내사항 전달(5분)- 면접(15분)","notes":"이름 말하지 않기","qa":[{"q":"-풀은 문제 정답부터 말해봐","a":"-이렇게 나왔습니다"},{"q":"-이 답 딱 두배 나왔는데?","a":"-아 도함수의 적분법을 사용했는데 긴장해서 2를 두 번 곱했네요"},{"q":"-풀이만 생각한 문제들은 어떻게 풀 거야?","a":"-이렇게 이렇게 풀면 될 것 같아요"},{"q":"-그래 맞아 맞아","a":"-이게 계산을 해보려고 했는데 식이 엄청 복잡하게 나오더라고요"},{"q":"-원래 그 문제가 계산이 복잡해서 시간이 오래 걸리는데 네가 말한 방법대로 계산하면 답이 이거야 그러면 그다음 문제는 어떻게 풀 수 있을까?","a":"-위에 문제 답을 써서 이렇게 하면 될것같아요충청북도교육청"},{"q":"-맞아 그럼 못 풀은 문제는 답이 뭐같아?","a":"-포물선인가요?(포물선이라고 답했는지 정확히는 모르겠음)"}],"result":"합격","resultNote":"","src":"충청북도교육청 「2022 대입 면접 후기집」","year":"2022학년도"},{"univ":"서울대학교","dept":"의류학과","jeonhyeong":"학생부종합(지역균형선발전형)","method":"- 학생부, 자소서 기반 면접","notes":"없음","qa":[{"q":"미술사 수업 중 생자필멸 전시회에서 특별히 중점을 두고 한 활동 있나요?","a":"도슨트 역할에서 현대미술 작품 해석에 중점 두고 활동했습니다. 데미안 허스트의 산 사람의 마음속에 있는 죽음의 불가능성이라는 작품을 해석할 때 윤리와 사상, 생활과 윤리에서 배운 하이데거의 철학을 적용해 해석했습니다. 그 결과, 현대미술이 난해하게 느껴졌던 이유가 작가의 철학이 내재되어있음을 깨달으며 미술에 대한 지식을 한층 높일 수 있었던 것 같습니다."},{"q":"사회문화 색채심리실험 탐구 느낀 점이 있다면 말해주고 이를 의류학과 연관 짓는다면 어떤 점이 있을까요?","a":"색채실험 탐구 후 느낀 점은 동일한 색채라도 상대방이 어떤 상황에 있느냐에 따라 각기 다른 감정을 불러일으킬 수 있다는 점이었습니다. 이를 의류와 관련짓는다면, 향후 패션 디자이너로서 옷감의 색을 선정할 때 내가 타깃으로 하는 대중들이 현재 어떤 사회적 정서를 겪고 있는지, 그런 요소들을 고려해서 선정해야겠다는 식으로 생각할 수 있겠습니다."},{"q":"지원동기와 진학하고 향후 방향성에 대해 말해주세요.","a":"저는 원래 영상 계열에 관심이 많아서 팀버튼이나 아담 엘리엇 감독 등의 영상을 보며 그 스토리 텔링을 디자인하는 것에 노력을 기울여 왔습니다. 고등학생 때까지 제 내면적 성장 스토리를 영상으로 만들어봤는데, 우연히 민주킴 브랜드의 철학과 디올의 오뜨 꾸뛰르 영상을 보면서, 어찌 보면 인간과 가장 밀접한 의류는 스토리를 보다 생동감있게 전달할 수 있는 매개라고 생각했습니다. 따라서 저는 의류에 스토리텔링을 더해 관객들에게 희망을 전해주고자 의류학과에 지원했습니다. 진학 후에는 이런 제 자신만의 브랜드를 론칭하기 위한 노력을 기울이고 있을 것 같습니다."},{"q":"마지막으로 하고 싶은 말이 있나요?","a":"저는 제가 대학에 입학한다면 향후 4년간의 시간이 결코 즐겁지만은 않을 거라 생각합니다. 충청북도교육청특히 디자이너는 1000장의 스케치를 통해 완성작의 10분의 1을 만들어내는 직업이라고 생각합니다. 따라서 저는 4년간의 시간을 화려한 나비가 되기 위한 번데기로서 고통스러워도 참으며 성장하는 시간으로 보내고 싶습니다.후배들을 위한 조언 학창 시절에 생기부 활동을 열심히 했다면 서울대 지균 면접은 어렵지 않습니다. 그저 생기부를 반복해서 보면서 각 활동의 간략한 활동 내용과 느낀 점을 되새겨보세요. 특히 도서목록은 간략한 느낀 점을 정리해둔다면 도움이 될 것 같습니다. 여러분의 입시 생활을 응원합니다!충청북도교육청"}],"result":"","resultNote":"","src":"충청북도교육청 「2022 대입 면접 후기집」","year":"2022학년도"},{"univ":"서울대학교","dept":"경제학부","jeonhyeong":"학생부 종합(기회균형(농어촌)전형)","method":"면접시간 20분 / 면접위원 2명","notes":"본적으로 나올만한 질문에 대한 예상질문과 답변을 준비하고 꾸준히 시뮬레이션 해볼 것.","qa":[{"q":"지원동기랑 서울대학교에 들어온다면 기대되는 바를 말해보세요.","a":"네, 저의 꿈은 경제학자가 되는 것입니다. 제가 경제학의 매력에 빠진 것은 공동교육과정에서 경제를 수강하고 난 뒤였습니다. 경제를 공부하면서, 저는 경제가 인간을 연구하는 학문이고 나아가 수학적 모델링을 통해 사회 전반을 연구하고 예측하는 학문이라는 점에서 큰 매력을 느껴 이런 꿈을 가지게 되었습니다. 때문에 저는 서울대학교 경제학부에 입학하여 경제학을 심도있게 공부해보고 싶습니다. 그리고 경제학을 공부하는 것을 넘어 저는 컴퓨터공학, 인공지능 등을 함께 공부하여 경제학 연구에 활용해보고 싶습니다."},{"q":"여기 자소서 1번에 고급수학 교과서를 찾아서 공부했다는 내용이 있는데 무엇을 공부했죠?","a":"네, 편미분에 관한 내용을 공부했습니다. 제가 3학년 때 공동교육과정에서 경제수학을 수강한 적이 있는데 그 때 생산함수에 대해 배웠습니다. 그런데 교과서에는 생산함수가 자본과 노동, 그리고 생산량의 함수관계라는 말 뿐이였습니다. 그래서 저는 생산함수가 어디에 쓰이는지 스스로 알아보기로 마음먹었습니다. 처음에 생산함수란 단기생산함수와 장기생산함수로 나뉜다는 것을 알았고, 단기생산함수는 경제적 구간을 구이는 데 쓰이며 경제적 구간은 노동과 자본의 편미분 값이 모두 양수인 구간이라는 것을 알았습니다. 이 과정에서 편미분의 개념을 알기 위해 고급수학 교과서를 참고하였다는 내용입니다."},{"q":"경제학 공부를 되게 많이 한 것 같은데, 리디노미네이션의 장단점을 말해보세요.","a":"네, 리디노미네이션은 화폐개혁으로 우리나라 화폐의 단위가 높기 때문에 그 단위를 낮추는 것을 말합니다. 리디노미네이션을 시행하면 지하에 있는 검은 돈의 규모를 알 수 있고 그것을 바깥으로 끌어낼 수 있다는 장점이 있습니다. 반면, 갑자기 화폐의 단위가 바뀌면서 우리나라 사람들은 오랫동안 높은 단위의 화폐를 써왔기 때문에 실제 화폐의 가치와 인식 사이에 괴리가 생겨 주택시장에서 갑자기 가격이 폭등할 수 있습니다. 가령, 사람들은 1억에서 1억 2천만원이 되는 것에는 민감하지만 1만원에서 1만 2천원이 되는 것에는 덜 민감한 성향이 있기 때문입니다."},{"q":"자소서 4번에 책 3권이 유기적으로 잘 연결되어 있는데, 롤스랑 프리드먼을 비교해보고, 롤스를 비판해보세요.(자소서 4번에 그대로 있는 내용이였음) 여기 다 나와 있긴 한데 다시 논리적으로 정리해보세요.","a":"네, 프리드먼과 롤스는 모두 자유주의자로 알고 있습니다, 그런데 프리드먼은 자유주의자들 중에도 아주 급진적인 자유주의자로 정부의 개입을 매우 회의적으로 바라본 사람입니다. 그러나 롤스는 이에 반해 최소수혜자의 최대 이익을 보장해야 된다는 관점에서 프리드먼과 다른 부분이 있습니다. 최소수혜자의 최대 이익을 위해 국가가 재분배를 할 수도 있다는 관점을 가지고 있기 때문입니다. 롤스가 이야기 한 것 중 대표적인 것이 ‘분배에서 운적인 요소를 배제해야 한다.’였습니다. 그런데 롤스가 어디까지가 운적인 요소이고 배제해야 되는지 명확히 하지 않았기 때문에 저는 우리 사회의 분배의 기준이 사라질 수도 있다고 생각했습니다. 누군가 ‘노력할 수 있는 자질’도 운적인 요소라고 해버린다면, 노력으로 얻은 소득 또한 재분배의 대상이 되기 때문입니다."},{"q":"그럼 자신이 생각한 대안은 뭐죠?","a":"네, 저는 부모의 지위같은 사회적 운과 능력과 같은 자연적 운 중에서 사회적 운만을 배제하고 분배해야 된다고 생각했습니다."},{"q":"그 둘을 구분하는 것이 애매할 수도 있지 않을까?","a":"네, 일부 그럴 수도 있다고 생각했습니다."},{"q":"그럼 그 기준을 어디서 정해야될지 3가지 보기를 줄테니까 말해보세요. 국회, 공청회, (나머지 하나 기억 안남). 어디서 해야 될 거 같아요?","a":"(잠시 고민하다가) 네, 사실 이에 대해 깊게 고민해 본 적은 없으나 잠깐 생각하기로 제 짧은 소견을 말씀드리자면, 저는 국회에서 그 일을 담당해야 된다고 생각합니다. 재분배는 결국 세금으로 이루어지는 것인데, 실제로 세금에 관한 일을 담당하는 국회에서 이 기준을 만들고 이에 따라 법을 만들고 세금을 부과하는 것이 좋을 것 같습니다."},{"q":"네, 좋습니다. 시간이 거의 다 되었네요. 수고하셨어요","a":"네, 수고하셨습니다. 감사합니다."}],"src":"세종특별자치시교육청 「2020 보인다! 면접지도 길라잡이」","year":"2020학년도"},{"univ":"서울대학교","dept":"수리과학부","jeonhyeong":"학생부 종합(지역균형전형)","method":"면접시간 10분 / 면접위원 2명","notes":"좋을 것 같음있는 그대로, 사실대로 대답할 것.","qa":[{"q":"다른 많은 과들 중에서 왜 하필 수학과에 오고 싶은지? 국어책처럼 준비한 거 읽지 말고 자연 스럽게 해주세요.","a":"(장황하게 말하면 싫어하실 분위기라 준비한 답변을 좀 간략하게 바꿔 말함)"},{"q":"금융수학에 관심이 많은 것 같은데, 이에 대해 아는 게 있나?","a":"(준비한 대답)서울대학교 OOO 교수님 홈페이지에서 금융수학 관련 진로에 대한 내용을 접했고(중략)"},{"q":"생기부에서 롤 모델이 리만이라고 적혀있는데, 왜 존경스러운지?","a":"(이런 내용이 있는지 정확히 몰랐는데, 평소 생각하던 것 말했음)"},{"q":"리만 말고, 관심 있는 경제학 분야에서 아는 학자가 있나?","a":"존 내쉬라는 학자를 알고 있습니다."},{"q":"존 내쉬는 무엇을 했는지?","a":"내쉬 균형이 혼합전략게임에서 언제나 존재한다는 것을 증명하여 노벨 경제학상을 수상했습니다."},{"q":"그것을 존 내쉬가 몇 살 때 했는지 아나?","a":"제가 영화에서 본 것으로는 대학생 때 했던 것으로 압니다."},{"q":"친구들이 모르는 문제 있으면 많이 물어봤을 것 같은데, 그것들 중에 못푼 문제 있나?","a":"(생각해봤는데 긴장해서 떠오르지가 않았음) 못푼 문제가 있긴 한데 정확히 기억이 나진 않습니다."},{"q":"고등학교 수학 시험보면 항상 1등 했어? A: 항상 1등은 아니었습니다.","a":""},{"q":"한 학년에 몇 명인가? A: 250명 정도 됩니다.","a":""},{"q":"일반전형으로 여기 오는 애들은 IMO(국제수학올림피아드) 1등한 애들, 이런 애들이 오는데 여기 오면 그 학생들이랑 경쟁해야 돼. 그게 힘들진 않겠어? A: (준비한 답변 함)","a":""},{"q":"함수 ~가 x = 0에서 미분 가능하지만 도함수가 그 점에서 불연속일 조건을 구했다고 하는데 어떻게 한 거야? (자소서 내용) A: 도함수에 대하여 설명드림.","a":""},{"q":"너무 쉬운 거 아닌가?","a":"간단한 내용이긴 하지만 제가 미분가능성과 연속성에 대해 가지고 있던 오개념을 바로잡을 수 있는 기회가 된 탐구여서 좋은 경험이었습니다."}],"src":"세종특별자치시교육청 「2020 보인다! 면접지도 길라잡이」","year":"2020학년도"},{"univ":"서울대학교","dept":"언론정보학과","jeonhyeong":"학생부 종합(지역균형전형)","method":"면접시간 10분 / 면접위원 2명","notes":"생기부에 기반한 질문","qa":[{"q":"지원동기 말해주세요","a":"서울대 언론정보교수님 000쓰신 책 읽고 말귀 열림의 자세가 필요하다고 생각 성공적인 커뮤니케이션 능력 함양(중략)"},{"q":"누구 교수님이요?","a":"ㅇㅇㅇ교수님입니다."},{"q":"아 ㅇㅇㅇ선생님~ 왜 말귀 열림의 자세가 필요한가요??","a":"갈등관리 소통 경험 말함."},{"q":"(생기부 첫 질문) 베트남전쟁의 여론형성에 미친 미디어의 영향 활동 소개해 주세요","a":"소개함 반대견해도 있는데 그 부분은 서울대 언정과 입학하여 알아보고 싶다."},{"q":"어떤 반대견해?","a":"예상 못해서 당황했지만 다른 예시를 들며 이야기함."},{"q":"그것도 미디어를 통해 형성 가능한 것 아닐까요?","a":"네, 그런 점에 의구심이 들어 더욱 탐구하고 싶음."},{"q":"어떤 직업을 가지고 싶나?","a":"두 가지 직업을 가지고 싶다.(중략)"},{"q":"두 번째는 추상적인데 더 구체적으로 말해보세요","a":"봉사활동 경험을 들어서 사회의 취약계층 말함"},{"q":"우리나라가 불평등이 심하다고 생각하나요?","a":"네, 심하다고 생각(중략)"},{"q":"어떤 사람이 되고 싶은가?","a":"행복을 전달해줄 수 있는 사람."},{"q":"평소 행복이란 무엇이라 생각하는가?","a":"성취감."},{"q":"너무 성취감에만 몰두하면 좌절할 수도 있다. 그런 경험 있나?","a":"있다. (사례설명) ‘도망친 곳엔 천국은 없다.’라는 가치관을 가지며 살아간다는 점을 말함."},{"q":"그거 좋은 말이다. 누가 한 말인가?","a":"기억에 나지 않지만 책에서 읽었던 것 같다."},{"q":"왜 그런 생각 했는가?","a":"사실 이번 면접도 준비하면서 많이 도망치고 싶었다. 하지만 이 과정에서 내가 포기하지 않고 성장할 수 있다면 그것 또한 행복일 것 같다고 답함.이쯤 됐을 때 밖에서 똑똑 하고 문을 두드림. 1분 남았다는 뜻."},{"q":"마지막으로 하고싶은 말 있는가?","a":"준비해온 거 말함."}],"src":"세종특별자치시교육청 「2020 보인다! 면접지도 길라잡이」","year":"2020학년도"},{"univ":"서울대학교","dept":"영어교육과","jeonhyeong":"학생부 종합(지역균형전형)","method":"면접시간 10분 / 면접위원 2명","notes":"생기부 분석은 필수! 학과별로 스타일이 조금씩 다른 것으로 알고 있기 때문에, 꼭 해당 학과 면접 후기를 보고 갈것!미리 홈페이지에서 교수님들 얼굴 보고 간 것이 상당히 도움됨.","qa":[{"q":"교내 방과후 시간에 ‘다수를 위한 소수의 희생은 필요한가?’를 주제로 토론을 진행했네요, 여기서 자신이 어떤 의견을 주장했는지 말해보세요.","a":"네. 저는 마이클 센댈 교수님의 '정의란 무엇인가' 강의 영상을 보고, '다수를 위한 소수의 희생은 필요한가'라는 주제로 토론을 진행한 바 있습니다. (이후 토론내용 설명)"},{"q":"토론의 결과는요?","a":"딜레마 상황은 정답이 없기 때문에, 분명한 승부가 나지는 않았습니다. 그러나 저의 의견이 학생들을 설득하여 받아들여졌고, 그중 한 친구가 결정론적 관점을 드러내며, 원래 다수의 사람이 죽어야 하는 상황이었으므로 이를 인위적으로 조작하여 한 사람을 희생시키는 것은 바람직하지 않다고 본 것도 흥미로웠습니다."},{"q":"세특에 영어부장을 맡아 영어일기를 걷었다...라고 나와있는데, 이를 통해 인상깊었던 활동은요?","a":"네, 영어 일기를 걷는 활동을 진행했었는데, 이 일기는 수업을 듣고, 이에 대한 감상문을 영어로 작성하는 것이었습니다. (중략) 이에 학생들이 먼저 한글로 글을 써온 후, 이것을 함께 번역하는 활동을 했습니다. 이렇게 되자, 저희 반은 모든 반을 통틀어 영어일기를 가장 많이 제출하는 반이 되었습니다."},{"q":"2학년 때 SEC교육 동아리 했었는데, 이에서 가장 노력한 점은요?","a":"네, 저희 학교에는 동아리가 많이 없었기 때문에, 교사의 꿈을 가진 친구들과 교육관련 활동을 하기 위해 교육동아리를 창설해 활동했습니다. 저는 영어교육에 관한 과제연구를 진행한 점이 가장 노력한 활동이라고 생각합니다."},{"q":"네, 그 과제연구 더 자세히 말해주세요.","a":"현재는 소통을 위한 영어가 제대로 가르쳐지지 못하고 있다고 생각했기 때문입니다. 이 연구를 하며 인지언어학에 대해서도 알게 되었고, 보다 context 안에서 유의미한 영어교육이 필요하다는 결론을 내렸습니다."},{"q":"고3때 ‘개구리’ 동아리를 했었어요, 이를 통해 배운점 말해주세요","a":"네, 그 동아리에서 저는 윤리와사상 멘토를 맡았습니다. (이후 동아리 내용 소개)"},{"q":"네, 자소서 보면, ‘책 <위대한 개츠비>를 읽고, 문학작품을 통해 당시 문화를 들여다 보았다.’ 라고 나와 있어요. 역사책을 통해서도 역사를 바라볼 수 있는데, 문학을 통해서 당시 역사를 볼 수 있는 것의 특별한 장점이 있을까요?","a":"(예시를 들어 답변 마무리)"},{"q":"근데, 개츠비를 원서로 읽은거에요? 아니면 번역본? 원서인데 조금 쉽게 된걸 읽은건가? 아니면 진짜 원서?","a":"조금 쉽게 나온 원서로 읽었습니다."},{"q":"근데, 그 파티 장면같은 게 진짜 상상이 되던가요? 그 이미지같은 게 떠올랐나 해서, 개츠비는 영화도 있잖아요.","a":"(답변)"},{"q":"음, 그래요. 문학으로 역사를 들여다보는 것의 장점이 그것 말고 또 없을까요? 생생하게 느껴진다는 게 전부는 아니잖아요?","a":"(잠시 생각할 시간을 주세요! 하고 잠시 있다가) 네 답변하겠습니다. 저는 문학을 통해서는 역사책에서는 볼 수 없는 미시사를 들여다 볼 수 있다고 생각합니다. 즉, 역사책에는 그 객관적인 사실만이 들어있지만, 문학작품을 통해서는 그 사건에 연루된 일반인들에게 끼친 영향도 들여다 볼 수 있다는 것입니다. (예를 들어 답변 마무리)"}],"src":"세종특별자치시교육청 「2020 보인다! 면접지도 길라잡이」","year":"2020학년도"},{"univ":"서울대학교","dept":"인류학과","jeonhyeong":"학생부 종합(지역균형전형)","method":"면접시간 10분 / 면접위원 2명","notes":"사회학과와 같은 대기실에서 대기함. 교수님들 전공분야, 얼굴 정도는 홈페이지에서 확인하고 면접하기.","qa":[{"q":"“교실에서 만나는 문화인류학 Project”중 가장 기억에 남는 보고서는? 이유는? (개인적인 자율활동 중)","a":"질병과 인종주의의 관계에 대한 보고서가 가장 기억에 남음."},{"q":"고2 문학시간에 젠더인류학과 “중국인의 거리”를 연관해서 설명했는데 이게 무엇인지?","a":"역사 속 반복된 남녀 대립구도가 1950년대 한국사회에 반영됨."},{"q":"그건 인류학이 아니라 역사 같은데 어떻게 생각하시나요?","a":"역사와 인류학은 밀접한 관련이 있다고 대답"},{"q":"윤리 딜레마와 영상 만들기를 하며 어려운 점?","a":"일정조정, 역할분담, 시험기간 임박"},{"q":"어떻게 해결하였는가?","a":"본인이 영상 편집을 자처하고 다른 친구들도 따라서 역할을 맡고자 함."},{"q":"반장하면서 어려웠던 점?","a":"처음 반장하면 서 미숙함. 수행평가 전달"},{"q":"‘문화의 수수께끼’ 책 읽고 인류학 관심 가졌니? 왜 관심 가졌니?","a":"인도인이 소고기 안 먹는 것을 예시로 설명하면서, 이슬람과 유대교 연구 등을 보며 이런 게 인류학이란 것을 느꼈다고 말함."}],"src":"세종특별자치시교육청 「2020 보인다! 면접지도 길라잡이」","year":"2020학년도"},{"univ":"서울대학교","dept":"인문계열(광역)","jeonhyeong":"학생부 종합(지역균형전형)","method":"면접시간 10분 / 면접위원 2명","notes":"","qa":[{"q":"서울대 와서 면접 기다리며 긴장 많이 했나?","a":"처음에는 긴장을 좀 했는데 시간이 갈수록 긴장보다는 기대가 늘었습니다."},{"q":"어떤 기대?","a":"음,,, 설명하기에는 조금 깁니다."},{"q":"인문학적 소양에는 자신의 생각과 감정을 남에게 명료하게 전달하는 것이 있다. 어떻게 생각하나? (그냥 넘어갈 줄 알았는데 궁금했나보다)","a":"(? 분명 가벼운 인사라고 생각했는데 예상 외로 치명적인 공격) 그렇다면 한 번 간단히 설명해 보겠습니다. 제가 여기서 이런 저런 제 생각들을 이야기할 것입니다. 그러면 그 중에서 제 부족한 생각이나 의견을 면접관님들이 날카롭게 찔러 주실 텐데, 저는 제가 이 곤란에 빠지길 기대하고 있습니다. (사실 그 곤란으로 더 성장할 수 있어 기대가 된다고 말해야 하는데 멍청하게 그 말을 안 했다.)"},{"q":"주어진 시간이 짧아 그 기대를 충족시킬지는 모르겠지만 이제 시작","a":"ㅇㅇ"},{"q":"자기소개서에 보면 책 '아홉 켤레의 구두로 남은 사내'를 읽고 생각했다는데 그 책 내용이 뭔가?","a":"(?? 1학년 때 읽은 책이고 나는 책 내용에 중점을 둔 것이 아니라 당황) 어... 그러니까 그게..... 급격한 도시화의 소외를 다루고 있는데... 주인공이..... 어버버... 사실 제가 책 내용에 초점을 둔 것이 아니라....."},{"q":"내용이 기억 안 나면 달리 생각한 것을 말해봐라 (약간 한심하다는 표정)","a":"(! 내가 준비한 거다) 그 책은 1학년 수업시간에 다룬 것인데 당시에는 그 책을 열린 결말로 끝나는 이야기로 배웠습니다. 주인공이 집에 구두들을 두고 떠나는데 그 뒤로 그 인물이 어떻게 될지 생각해 보았습니다. (무슨 상상을 했었냐고 물었으면 기억 안 나 망했는데 다행히 안 물어봄) 하지만 후에 개인적으로 찾아보니 이어지는 연작 작품들이 있어 뒷이야기가 결정되어 버렸기에 제 상상과 생각이 무의미해진 듯 했습니다. 그 점에서 소설에서 열린 결말이란 것의 중요성을 처음으로 느낄 수 있었습니다."},{"q":"원래 한 권의 책인가? (내 말을 제대로 이해 못 한 거 같았음)","a":"어... 단편들이 여러 편 있습니다. (나는 질문을 제대로 이해 못 한 거 같음)"},{"q":"감명 깊게 읽은 책으로 '노인과 바다'가 있는데 어떤 부분에서 노인과 바다가 조화롭다고 생각했나? (내가 자소서 4번에 조화롭다고 썼다)","a":"(! 다행, 할 말 많은 거) 책을 보면 노인은 아주 작은 존재임에도 그 거대한 바다에게 친밀감을 느끼고 말을 겁니다. 바다의 생물들인 새, 물고기들을 친구로 여깁니다. 아주 직은 존재가 그렇게 큰 존재를 가까이 생각하는 것이 노인과 바다의 조화라고 느꼈습니다."},{"q":"책에서 노인은 물고기, 상어와 투쟁하는데 이것도 조화로운 것인가?","a":"(! 날카로운 지적인 줄 알았겠지만 어림없음) 예, 조화입니다. 노인은 힘겹게 투쟁하면서도 단 한 번도 바다를 탓하거나 미워하지 않습니다. 상어들에게 욕을 하며 때려죽이면서도 상어들을 싫어하지 않습니다. 노인에게 바다는 늘 동반자였습니다. 투쟁하면서도 적이 아니었고 그러니 조화로웠습니다. (이정도 삶의 통찰이면 면접관한테 감동을 전할 줄 알았는데 무반응이라 크게 당황)"},{"q":"생활기록부를 보면 학생이 문학과 철학에 관심이 많고 동시에 과학에도 호기심이 많다고 써져 있는데 이에 대해 어떻게 생각하나?","a":"아, 제가 그런 평가를 받은 것은 아무래도 제가 전 과목을 열심히 했기 때문인 거 같습니다. 확실히 문학을 택하고서 과학에 대한 흥미가 떨어진 것은 사실입니다. 그래도 한 사람이 모든 과목을 좋아하지는 못해도, 적어도 모두 다 열심히는 할 수 있지 않느냐는 마음으로 학교생할을 했습니다."},{"q":"그러면 지금은 과학보다 문학과 철학에 관심이 있나? (질문이라기보다는 내 말을 정리하는 느낌으로)","a":"아, 근데 과학 중에서도 생물에는 흥미가 많이 있습니다."},{"q":"인문학과 생물이 무슨 관계인가.","a":"제가 관심이 있는 생물은 우리 몸의 세포나 혈관, 장기 같은 것이 아니라 개채로서의 사람이 동물이, 예로 원숭이가 서로 서로 어떻게 상호작용 하는지입니다. 이러한 것은 사람을 이해하는데 필요하다고 생각합니다."},{"q":"생물이 인문학에 어떻게 기여할 수 있는가.","a":"저는 사람을 세 가지로 나누어 이해합니다. 첫째, 동물로서의 사람. 둘째, 문화에 의해 사회화된 사람. 셋째, 자아를 가지는 개인으로서의 사람입니다. 그 중에 생물은 첫 번째 사람을 이해하는데 도움이 될 것입니다. (휴, 이정도면 굉장했다라고 스스로 만족)"},{"q":"심리학에 가까운 건가? (무덤덤한 표정이라 또 크게 당황)","a":"어, 예. (저 질문의 의도는 대략 '넌 문학과 철학한다는데 저건 심리학이 아니냐'였는데 어리버리 하다가 그냥 수긍)"},{"q":"학생이 했던 활동 중에 과제연구활동이 있다. 생활기록부에 따르면, 하이데거와 에피쿠로스의 사상을 바탕으로 죽음에 대한 고찰을 했다는데 자세히 설명해 보아라.","a":"아, 사실 생활기록부의 그 말은 제 연구의 핵심이 아니었습니다. 당시 제 활동은 저 사상들을 중심으로 한 것이 아니라, 저 개인의 생각에 인터뷰와 설문을 더했고 그 결과를 발표함에 있어 지도교사 선생님의 조언을 받아 결과의 공신력을 높이는 인용을 했을 뿐입니다."},{"q":"그러면 학생이 했던 활동을 자세히 설명해 보아라. (내가 모르겠다고 하니 살짝 어리둥절)","a":"예, 먼저 동급생들과 인터뷰를 했고 거기에서 얻은 생각을 검토하기 위해 전교생을 대상으로 설문조사를 진행했습니다. 죽음에 관한 당시 제 생각은 우리가 죽음을 인식하는 것이 우리가 유한한 삶을 더 열심히 살게 한다는 것이었습니다. 소수의 인터뷰에서는 죽음에 관한 폭넓은 인식과 삶의 태도의 연관성을 찾았고, 다수의 설문조사에서는 죽음에 대한 인식도와 삶에 대한 만족도를 비교했습니다."},{"q":"설문 결과는 어땠나.","a":"조사 결과 제 생각처럼 죽음이 우리를 열심히 살게 한다고 말할 유의미한 결과를 얻었습니다.(시간 다 됐다고 가랬는데 정확한 말은 기억 안 남)총평: 1. 학교 선생님들이랑 모의 면접한 질문들이 4개 중 3개였다.2. 면접관들 표정에 속지 마라. 우리가 무슨 말을 해도 만족스러워하지 않을 거다.3. 할 말이 없는 질문은 그냥 모르겠다고 끝내지 말고 대답할 수 있는 질문으로 바꿔라.4. 면접은 3학년의 우리가 보는데 질문들은 1~2학년의 우리에 관해서도 묻는다. 그 기간 동안 사람이라면 생각과 믿음이 분명 달라진다. 중요한 건 그 생각들의 옳고 그름이 아니라 어떻게 떠올린 생각인지, 그 과정과 합리성이다."}],"src":"세종특별자치시교육청 「2020 보인다! 면접지도 길라잡이」","year":"2020학년도"},{"univ":"서울대학교","dept":"체육교육과","jeonhyeong":"학생부 종합(지역균형전형)","method":"면접시간 10분 / 면접위원 2명","notes":"","qa":[{"q":"체육교육과 지원동기?","a":"체육 좋아하고, 학생들에게 신체적 정신적 건강을 함께 영위할 수 있도록 돕는 교사가 되길 희망함."},{"q":"‘운동화 신은 뇌’ 책 읽고 짧게 요약해 본 후, 느낀점은?","a":""},{"q":"체육교사가 가져야 할 자질은?","a":""},{"q":"가장 기억에 남는 동아리 활동은?","a":""},{"q":"서울대학교 체육교육과 지원동기?","a":""},{"q":"마지막으로 하고 싶은 말?","a":""}],"src":"세종특별자치시교육청 「2020 보인다! 면접지도 길라잡이」","year":"2020학년도"}],"official":[{"category":"","jeonhyeong":"","q":"3학년 자율활동에서 자연이자율 하락의 해결책으로 평균인플레이션 목표제를 제시했는데 평균인플레이션 목표제의 개념을 설명해보세요. 한국 경제의 적용 가능성은 어느정도인가요? 물가안정목표제와 평균인플레이션목표제 장단점 비교해보세요. 한국 경제에 어느 것이 더 적합하다고 생각하나요?","src":"경기도 진학 연구팀(진심) 「2026 면접을 준비하다」"},{"category":"학업역량","jeonhyeong":"","q":"3학년 동아리활동에서 ‘국민을 위한 국민연금은 없다’와 정부의 재정계산 자료를 탐독하여 국민연금의 현재 상황과 연금개혁안 간의 충돌을 문제 삼았는데 국민연금의 현재 상황은 어떠한가요? ‘연금개혁안’의 충돌 문제는 무엇인가요? 국민연금의 지속 가능성을 확보하기 위한 과제에 대해 생각해본 적 있나요?","src":"경기도 진학 연구팀(진심) 「2026 면접을 준비하다」"},{"category":"▣ 화학","jeonhyeong":"학생부종합전형(일반전형)","q":"챗지피티도 도덕적인 부분을 분석하고 추론할 수 있을텐데 그렇다면 챗 지피티도 도덕적인 주체로 봐야하나요?","src":"세종특별자치시교육청 「2027학년도 대입 수시모집 면접 전형 자료집」"},{"category":"▣ 화학","jeonhyeong":"학생부종합전형(일반전형)","q":"○○과목에서 ○○실험은 교과서에도 나와있는 실험인데 왜 했나요? 역할은 무 엇이고, 무엇을 얻었나요? 실제 환경에서 실험 결과가 같지는 않았을 텐데 어떻","src":"세종특별자치시교육청 「2027학년도 대입 수시모집 면접 전형 자료집」"},{"category":"꼬리질문","jeonhyeong":"학생부종합전형(일반전형)","q":"예측이 실제 사태로 이어지는 현대 사회에서의 또 다른 사례가 있을까요?","src":"세종특별자치시교육청 「2027학년도 대입 수시모집 면접 전형 자료집」"},{"category":"꼬리질문","jeonhyeong":"학생부종합전형(일반전형)","q":"생기부 질문, ○○에 대해 설명했다고 하는데, 자세히 설명할 수 있나요?","src":"세종특별자치시교육청 「2027학년도 대입 수시모집 면접 전형 자료집」"}],"admission":[{"jeonhyeong":"학생부종합전형(기회균형특별전형(사회통합))","select":"- 2배수: 전 모집단위 1단계 - 3배수: 미술대학, 음악대학 - (전 모집단위) 1단계 70 + 면접 30 - (미술대학_동양화,서양화,조소,공예) 1단계 40 + 실기 30 + 면접 30 2단계 - (미술대학_디자인과) 면접 100","type":"","method":"","schedule":"- (음악대학) 1단계 50 + 실기 40 + 면접 10 2026.12.4.(금) 전 모집단위 2026.12.5.(토) 수의과대학, 음악대학, 의과대학","notes":"","areas":[]},{"jeonhyeong":"학생부종합전형(지역균형전형)","select":"1단계 - 3배수: 전 모집단위 2단계 - 1단계 70점 + 면접 30점","type":"전 모집단위 - 서류기반 면접 및 기본적인 학업 소양 평가 (의과대학 제외) - 사범대학: 서류기반 +　교직적성·인성면접 의과대학 MMI면접(상황/제시문 기반 면접 + 서류기반 면접)","method":"전 모집단위 지원자 1명 대상 복수 면접위원(2인) 실시 10분 내외 면접 (의과대학 제외) 의과대학 북수 면접실에서 진행(60분 내외)","schedule":"2026.12.3.(금) 전 모집단위 2026.12.5.(토) 수의과대학, 의과대학","notes":"","areas":[]},{"jeonhyeong":"학생부종합전형(일반전형)","select":"1단계 2배수 - (전 모집단위) 1단계 성적 100점 + 면접 100점 2단계 - (미술대학 디자인과) 1단계 성적 미반영 + 면접 100점","type":"- (사범대학) 1단계 성적 100점 + 면접 및 구술고사 60점 + 인적성면접 40점 제시문 면접, 제출서류 참고하여 질문할 수 있음.","method":"지원자 1명 대상 복수의 면접위원 실시, 모집 단위별 평가 내용과 시간상이([첨부1] 참고)","schedule":"2026.11.27.(금) 전 모집단위, 사범대학 교직적성·인성면접 2026.11.28.(토) 수의과대학, 의과대학, 치의학대학원, 치의학과","notes":"","areas":[{"area":"▣ 화학","questions":["챗지피티도 도덕적인 부분을 분석하고 추론할 수 있을텐데 그렇다면 챗 지피티도 도덕적인 주체로 봐야하나요?","○○과목에서 ○○실험은 교과서에도 나와있는 실험인데 왜 했나요? 역할은 무 엇이고, 무엇을 얻었나요? 실제 환경에서 실험 결과가 같지는 않았을 텐데 어떻"]},{"area":"꼬리질문","questions":["예측이 실제 사태로 이어지는 현대 사회에서의 또 다른 사례가 있을까요?","생기부 질문, ○○에 대해 설명했다고 하는데, 자세히 설명할 수 있나요?"]}]}]};
